window.__CASES = [{"id":"bookclub","title":"读书会之夜","tagline":"作家说要“实话实说”，然后上楼取稿子，再没下来。","difficulty":2,"cover":"cv_bookclub","tone":"warm","brief":"十月最后一个周六，你在槐荫路17号的读书会上旁听。东道主是畅销作家晏清如。她宣布要写一本“实话实说”的回忆录，头两章已打好。十分钟后她上楼取稿子，再没下来。九点四十五，保姆端茶上去，一声尖叫喊亮了整栋房子。桥上追尾，警方要一小时后才到。韦桐拽住你的袖子：“你在，你看看吧。”屋里除了死者还有八个人，谁也没有离开。","victim":{"name":"晏清如","desc":"63岁，《半夏》作者。她侧卧在二楼书房的书桌与书架之间，后脑遭钝器重击，桌上两叠打字稿，像被抽走了中间。","look":{"skin":"light","hair":"bun","hairColor":"grey","glasses":"round","beard":"none","outfit":"dress","mood":"neutral"}},"publicFacts":["晏清如，63岁，《半夏》作者；每月最后一个周六办读书会，今晚到场八人。","20:50她宣布要写回忆录。回忆录没有电子档，全是她用电动打字机一页页敲的。","21:03她上楼取稿，没再下楼；21:45保姆发现她倒在书房。","死因是后脑一次钝器重击，死亡时间在21:00至21:40之间。","书房在二楼尽头；前楼梯通客厅，厨房另有窄门通后楼梯。","警方一个多小时后才到；宅内八人无人离开，大门有门铃回放。"],"relations":{"bai":"读书会最年长的会员，退休语文老师","luo":"合作十二年的责任编辑","geng":"住隔壁十九号，为树篱吵了十几年","xing":"两年前雇的助理，六月被辞退","pang":"出版社市场总监，负责纪念版","ji":"在她家做了八年的住家保姆","wei":"书店老板，读书会的发起人和主持","xu":"大学同窗，四十多年的老友"},"links":[{"a":"bai","b":"xu","text":"认识三十年的老相识"},{"a":"luo","b":"pang","text":"同一家出版社的同事"},{"a":"geng","b":"ji","text":"邻居，纪桂芳送过汤"},{"a":"xing","b":"pang","text":"被辞退后，庞来打听过新书卖点"}],"deathReport":{"time":"约 21:00–21:40","cause":"后脑遭钝器重击","scene":"21:45 保姆纪桂芳端茶上楼，推开书房门，见晏清如侧卧在书桌与书架之间的地毯上，已无气息。","loc":"study","notes":["后脑一处凹陷，一击致命","桌上两叠打字稿，中间桌面空着"]},"timeline":[{"t":"19:30","text":"读书会开始，韦桐主持，壁炉边立着一部手机。"},{"t":"20:50","text":"晏清如宣布要写回忆录。"},{"t":"21:03","text":"晏清如上楼取第一章稿子。"},{"t":"21:28","text":"灯光调暗，韦桐开始朗读，众人闭目听。"},{"t":"21:45","text":"纪桂芳端茶上楼，发现晏清如，尖叫。"},{"t":"21:50","text":"韦桐报警，你被拉进书房。"}],"budget":{"search":14,"ask":34},"locations":[{"id":"study","name":"二楼书房","scene":"study","desc":"二楼走廊尽头，窗下一张大书桌，墙边是满满一面书架，空气里有旧纸和墨粉味。","clues":[{"id":"c_st1","title":"缺页的稿子","text":"桌上两叠打字稿，一叠页脚到“—— 29 ——”，另一叠从“—— 37 ——”起。中间桌面空着，有一圈浅印。"},{"id":"c_st2","title":"打字机的色带","text":"一次性薄膜色带，对光能读出镂空的字。“31”页：“我改了七成，署上了自己的名字。”“32”页：“十二封读者来信是人写的。”“33”页：“每年春天，我把稿费的一半装进信封交到他手上……封口费。”再往后只认得“版权页”“不是钱”。"},{"id":"c_st5","title":"抽屉里的文件","text":"一份律师草稿《〈半夏〉署名及收益分配协议》：署名为“柏砚秋 著 / 晏清如 整理”，分成五成改六成，历年不追索。页眉铅笔字：“周三14:00律所。第36页，当面给老柏。”"},{"id":"c_st3","title":"铜灯奖座","text":"书架上的黄铜灯盏奖座，底座缝里有擦不净的暗红，朝向和旁边那座不同。大小与桌上浅印相当。晏清如侧卧在地毯上，后脑凹陷。"},{"id":"c_st4","title":"铁皮饼干盒","text":"底层抽屉里的旧饼干盒，装着《夏至》四百格稿纸，瘦长钢笔字，红笔把“雨”改成“雾”。另有每年一张的收条：“今收到稿酬分成款 ￥48,000 柏砚秋”。"}]},{"id":"living","name":"客厅读书角","scene":"library","desc":"一楼大客厅，三面书墙，中间一张长桌。壁炉边有扇通后院的落地窗，窗帘半掩。","clues":[{"id":"c_liv1","title":"三脚架上的手机","text":"壁炉边的手机一直在录像。21:03晏清如向第三个座位的人低声说话后上楼。空椅时段：庞20:59–21:41，许20:58–21:48，柏21:09–21:34（灰外套留椅背），耿21:10–21:36，骆21:15–21:22。21:28灯暗，众人闭目。"},{"id":"c_liv2","title":"椅子下的旧书","text":"柏砚秋布包里的《半夏》初版，页边满是红蓝批注：“原稿作‘雨’，非‘雾’。”“整段是我的，她只动了两行。”字迹瘦长。书里夹着一张护理院缴费单。"},{"id":"c_liv3","title":"骆知微的复印稿","text":"骆知微手袋里的复印件《实话实说》，页脚1到29页，满是红笔批注，末页写着“周四收，周五复印”。最后一句：“下一章，我要写一个人。”"},{"id":"c_liv4","title":"壁炉台上的流程单","text":"韦桐的手写流程单：长桌座次“晏、韦、柏、耿、骆、庞、邢、许”。“柏老怕凉，原定六号风口位，改到三号，挨壁炉。”“21:30第九章，灯关一半。”“落地窗留一指缝。”"}]},{"id":"garden","name":"庭院与铁桶","scene":"garden","desc":"房子侧面的小庭院，一头是冬青丛和石凳，另一头绕到后院，有烧落叶的铁桶、落地窗和邻家树篱。","clues":[{"id":"c_gar1","title":"铁桶里的纸灰","text":"铁桶沿还烫手。表层是厚厚的卷曲纸灰，斜照能见打字机字迹，认得出“封口”二字。底下才是下午的落叶灰。旁边有根烧焦的长树枝。"},{"id":"c_gar4","title":"石凳与侧门","text":"侧院石凳上有半杯凉姜茶、一个充电宝和一团湿纸巾，正对厨房窗。石凳后通前院的矮木门，门闩从院内插着，锈没蹭过，门框上蛛网完整。"},{"id":"c_gar2","title":"落地窗外的脚印","text":"从铁桶到落地窗有一串灰脚印，鞋底是圆点防滑纹。窗槛内侧和窗帘下摆沾着灰白粉末。"},{"id":"c_gar3","title":"树篱的缺口","text":"后院与十九号之间的树篱被掰出半人宽的缺口，断枝还湿。泥地上有深纹雨靴印，旁边有瓜子壳。从这里看得见铁桶。"}]},{"id":"kitchen","name":"厨房与后楼梯","scene":"kitchen","desc":"老式厨房，灶上温着酒酿，案板上水果切了一半。北角有扇窄门通二楼后楼梯。","clues":[{"id":"c_kit1","title":"后楼梯口的铜铃","text":"窄门楣上挂着铜铃，一开门就响。便条：“太太嫌楼梯窄，不走。铃是防贼的。”门下积灰上有一进一出的软底拖鞋印。"},{"id":"c_kit2","title":"台阶上的铅笔头","text":"后楼梯第四级角落卡着一截红蓝两头的铅笔头，用小刀削的。扶手灰上有新手印，一上一下。"},{"id":"c_kit3","title":"冰箱上的流程单","text":"纪桂芳写的流程单：“21:00 切水果”被划掉，改成“21:35”。案板上两盘水果只切了一盘。"},{"id":"c_kit4","title":"水龙头上的手帕","text":"水龙头上搭着拧干的白手帕，绣着“梅”字，有洗不净的淡褐污渍。水槽边有湿的软底鞋印，排水口漂着灰。"}]},{"id":"hall","name":"玄关门厅","scene":"hall","desc":"进门的玄关，有鞋柜、衣帽架和门铃屏幕，矮柜上堆着客人的礼盒和公文包。","clues":[{"id":"c_hall1","title":"客用拖鞋架","text":"客用拖鞋后跟写着姓。“柏”的那双，圆点鞋纹缝里嵌着炭灰，侧面有干泥点。“许”的后跟蹭着楼梯间的灰。"},{"id":"c_hall2","title":"门铃回放记录","text":"回放：19:10柏，19:20骆，19:35耿，19:40庞，19:55邢进门。之后20:59庞出门，21:11耿出门，21:41庞回屋，21:50韦出门接警。21:11到21:41前门无人进出。"},{"id":"c_hall3","title":"庞立峰的文件袋","text":"文件袋里有两份文件。一份《半夏》续约条款，“下月底到期”，旁注“预付200万”。一份草稿《关于部分读者来信的情况说明》：“个别来信经编辑部代拟。”"}]},{"id":"guest","name":"二楼客房","scene":"guestroom","desc":"二楼走廊中段朝后院的客房，床上摊着半开的行李袋，窗帘拉开一条缝。","clues":[{"id":"c_gst1","title":"没写完的信笺","text":"桌上的信笺：“清如：第三十三页那一段你不能发。那不是实话，是你站在岸上说的话——”被横线划掉，旁边写着“求你”。"},{"id":"c_gst2","title":"窗边的视野","text":"窗台有被手肘撑出的干净处，窗边放着凉茶。从这里往下，后院铁桶正在视线中央。窗框上有新的指甲印。"},{"id":"c_gst3","title":"塑封旧照","text":"行李袋里的旧照：编辑部里三个年轻人，右边瘦高男人戴圆眼镜，手捏红蓝铅笔。背面：“城南文艺编辑部 一九九四年夏 清如 曼琪 砚秋”。"}]}],"suspects":[{"id":"bai","name":"柏砚秋","role":"退休语文教师","age":64,"look":{"skin":"light","hair":"short","hairColor":"grey","glasses":"round","beard":"none","outfit":"jacket","mood":"smile"},"bio":"读书会年纪最大的会员，退休中学语文教师，老伴住护理院。当晚坐长桌第三位，爱用红蓝铅笔批注。","demeanor":"说话慢，爱引书里的句子；被问急了摘眼镜擦。","topics":[{"id":"t_role","q":"你为什么来读书会？","a":"老伴住进护理院后，周六晚上是我留给自己的一点时间。人老了，听年轻人讲书，是福气。"},{"id":"t_wife","q":"家里还有什么人？","a":"老伴叫梅，三年前得了阿尔茨海默，住护理院一个月九千。我一周去四天，给她念《半夏》。"},{"id":"t_memoir","q":"她要写回忆录？","a":"我鼓了掌。她说头两章已经打好，今晚先读第一章，至于第二章写了谁，她她笑笑没说，卖了个关子。"},{"id":"t_book","q":"你和《半夏》的渊源？","lie":true,"a":"一个读者罢了。这书我读了二十多遍，书页都读软了。晏老师是天生写故事的人，我只是有福气的读者。","truth":"《半夏》第一稿是我写的，那时叫《夏至》。一九九四年，我把稿纸装进饼干盒请清如看。她改了七成，署了她的名，是我答应的。"},{"id":"t_where","q":"九点后你在哪？","lie":true,"a":"一直在长桌边听韦老板讲书，中间只去过一次一楼洗手间，五分钟。不信你可以问大家，不是什么要紧的事。","truth":"我离开了二十五分钟。九点零九分起身，九点三十四分才回座。我去的是二楼书房，还有后院。"},{"id":"t_up","q":"你上过二楼吗？","lie":true,"a":"没有。我这副膝盖不爱爬楼梯，二楼的事我一概不知道，也不想知道，晏老师的书房我连门都没进过。","truth":"上去了。她在我耳边说，九点十分走后楼梯上来，有几页东西想让我先看，别惊动大家。我就去了。"},{"id":"t_garden","q":"你出过客厅吗？","lie":true,"a":"没有。顶多在落地窗边站一站透口气，屋里闷，可门槛都没迈出去过，后院黑漆漆的，我去做什么。","truth":"我去了后院，把那几页纸烧在了纪阿姨烧落叶的铁桶里，火星还没熄，一点就着。我看着它们烧完，才回去坐下。"},{"id":"t_money","q":"那些收条是什么？","needs":["clue:c_st4","ask:bai.t_book"],"a":"是我的稿酬分成，一人一半，三十一年一次没少，一次没迟。她从不给它别的名字，直到今晚。"},{"id":"t_read","q":"你读到哪一页？","needs":["clue:c_st5","ask:bai.t_where"],"a":"她递给我第三十页起的稿子。我读到第三十三页，就……后面没有再翻。钱的事我从不怕人知道。"}],"confronts":[{"clue":"c_liv1","breaks":"t_where","crack":true,"a":"他看着椅背上的灰外套，沉默很久，摘下眼镜擦了擦。“二十五分钟。你数得比我准。好，我离开过。”"},{"clue":"c_kit2","breaks":"t_up","a":"“这支笔我找了半个晚上。”他摩挲着铅笔头的刀痕，“好，我上过二楼，走的后楼梯。”"},{"clue":"c_hall1","breaks":"t_garden","a":"他低头看那双“柏”字拖鞋底的炭灰，苦笑：“老人的脚，总比嘴老实。好，我出去过，去了后院。”"},{"clue":"c_liv2","breaks":"t_book","a":"他一页页翻着自己的批注，轻声念：“原稿作‘雨’，非‘雾’。”顿了顿，“是，第一稿是我写的。”"},{"clue":"c_st4","a":"“这盒子是梅送我的纪念。”他低下头，“清如居然一直留着。她留着它，是为了什么呢。”"},{"clue":"c_st2","a":"听到“封口费”，他脸色褪尽：“后面还写了什么？我读到第三十三页，就看不下去了。”"},{"clue":"c_gar1","a":"“烧的是第三十到三十六页。”他直视着你，“七页纸，烧得那样快，不像是三十年的事。”"},{"clue":"c_st5","a":"他读到“署名”二字，纸页发抖。“她要把名字还给我……我没读到这里。我只读到第三十三页。”"},{"clue":"c_liv4","a":"“韦老板是好心。我说腿凉，他就把我挪到壁炉边。他哪想得到……”他摘下眼镜，擦了很久。"}],"fallback":"这个……我恐怕帮不上忙，我只是个爱读书的老头子。"},{"id":"luo","name":"骆知微","role":"责任编辑","age":38,"look":{"skin":"fair","hair":"bob","hairColor":"black","glasses":"rect","beard":"none","outfit":"suit","mood":"tired"},"bio":"晏清如合作十二年的责任编辑，负责《半夏》再版。她说今晚只是来“蹭一场读书会”，没想到会听到回忆录。","demeanor":"语速快，爱说“咱们先对一下”，紧张时刷手机。","topics":[{"id":"t_role","q":"你和晏老师的合作？","a":"十二年，三本新书，七次再版。《半夏》每年的加印我都盯着。她改稿时骂得狠，改完了会请你吃饭。"},{"id":"t_where","q":"九点后你在哪？","a":"九点一刻头疼，去了一楼走廊尽头的洗手间，七八分钟，补了点妆。其余时间都在长桌边。"},{"id":"t_hear","q":"你听到什么了？","a":"九点二十前后，我在一楼走廊，听见头顶闷闷一声，像一摞书掉在地毯上。上头是书房，我没多想。"},{"id":"t_read","q":"回忆录你看过吗？","lie":true,"a":"一个字没见过。晏老师这回保密得很，连我这个责编都是今晚才知道，真的，咱们可以先对一下时间线。","truth":"见过第一章。周四她快递来二十九页复印件，让我别吭声。我撒谎，是怕你们以为我知道第二章写了什么。"},{"id":"t_contract","q":"你们的合同状况？","lie":true,"a":"好好的。晏老师是我们社的头牌作者，没有谁会走，合同、排期、渠道都对齐了，没有任何问题。","truth":"《半夏》版权明年三月到期，她一直没松口。开会前我在厨房求过她，她说散会后再谈。我怕你们觉得我有动机。"},{"id":"t_ch1","q":"第一章写了什么？","needs":["clue:c_liv3"],"a":"写她十岁，母亲在纺织厂上夜班，她趴窗台等灯。最后一页：“下一章，我要写一个人。”"},{"id":"t_pang","q":"你怎么看庞总？","a":"市场部的人，只看数字。他今晚七点半就开始看表，要我说，这本回忆录，最怕的就是他。他坐立不安一晚上。"},{"id":"t_mood","q":"她今晚什么状态？","a":"很平静，像放下了一副担子。她问我：“知微，一个人把欠的账写出来，算不算还？”我没答上来。"}],"confronts":[{"clue":"c_liv3","breaks":"t_read","a":"“你们连我的包都翻了。”她按住复印件，“好，我看过，读了一整夜。她叫我别讲，我就没讲。”"},{"clue":"c_hall3","breaks":"t_contract","a":"她看着续约条款，苦笑：“底牌被铺在桌上了。是，明年三月到期。我是来救这个季度的。”"},{"clue":"c_st1","a":"听你说两叠稿子中间空了，她脸一白：“第二章被拿走了？那是她最怕给我看的一章，她一直不肯给。”"}],"fallback":"这个咱们先放一放，我得先理清楚。"},{"id":"geng","name":"耿福根","role":"隔壁邻居","age":71,"look":{"skin":"tan","hair":"cap","hairColor":"grey","glasses":"none","beard":"stubble","outfit":"jacket","mood":"stern"},"bio":"十九号的邻居，退休锅炉工程师，爱养月季。和晏清如为树篱吵了十几年，读书会却一次不落。","demeanor":"嗓门大，爱说“我跟你说”，一提树篱就吹胡子。","topics":[{"id":"t_role","q":"你和晏老师的关系？","a":"我跟你说，邻居十七年，吵了十五年。可她写的书我一本不落，《半夏》我看了三遍，你信不信。"},{"id":"t_fence","q":"你们吵什么？","a":"树篱和枇杷树。她嘴硬心不坏，上个月我老伴住院，她还让桂芳送了一锅汤过来，老太太刀子嘴豆腐心。"},{"id":"t_where","q":"九点后你在哪？","lie":true,"a":"九点十分我回家拿老花镜，坐下顺手看了会儿新闻，九点半过后才回来的，就这么回事，有什么好问的。","truth":"镜子是拿了，新闻没看。我是从树篱缺口钻回来的，在冬青后头猫了好几分钟，没敢出声。"},{"id":"t_back","q":"你从哪里回来的？","lie":true,"a":"前门，按的门铃，纪阿姨给开的。我七十一岁的人，体面着呢，才不钻什么篱笆，你别拿我开涮。","truth":"前门没按过。树篱那个缺口是我掰的，近。我怕你们抓这个小辫子，说我心里有鬼，晏清如要告我的就是这个。"},{"id":"t_saw","q":"你在缺口看到什么？","needs":["clue:c_gar3","ask:geng.t_back"],"a":"桶那边有火，一个浅色毛衣、背有点驼的人弯腰拨火。看不清脸。我怕被告钻篱笆，就没吭声。"},{"id":"t_hobby","q":"你平时做什么？","a":"养月季，看鸟，修暖气片。锅炉房干了三十八年，什么响动我都听得出，今晚这屋里的人，静得不对劲。"},{"id":"t_who","q":"你觉得是谁？","a":"我不乱说。反正姓庞的一晚上不进屋，姓邢的半年前被她赶出门，这两位我多看了几眼。至于屋里那些老书虫，软脚虾。"}],"confronts":[{"clue":"c_hall2","breaks":"t_back","a":"他嗓门一下低了：“没拍着我走前门是吧。行，我钻的篱笆。我跟你说，不是怕担责，是怕丢人。”"},{"clue":"c_gar3","breaks":"t_where","a":"“那缺口是我掰的。”他吹了下胡子，“我九点半前就蹲在里头，不是回家看新闻。我没脸见她。”"},{"clue":"c_liv1","a":"“我离席二十六分钟，对吧。”他很坦然，“我回的是家，不是行凶。你查我老伴，她能作证我找了半天眼镜。”"}],"fallback":"嗨，这个我不懂，你问点别的。"},{"id":"xing","name":"邢小川","role":"前助理","age":27,"look":{"skin":"light","hair":"messy","hairColor":"black","glasses":"none","beard":"stubble","outfit":"hoodie","mood":"sly"},"bio":"晏清如两年前雇的助理，今年六月被辞退。他说是来当普通读者的，整晚缩在长桌最边上。","demeanor":"嘴上带刺，爱自嘲，常说“说实话”“也行吧”。","topics":[{"id":"t_role","q":"你以前做什么？","a":"替她回邮件、整理读者来信，说实话就是个高级跑腿。帮她把打字机从旧货市场淘回来。干了两年，被辞了，也行吧。"},{"id":"t_fired","q":"为什么被辞退？","a":"说我偷翻她桌上的稿子。翻了就是翻了，我认。她没骂我，只是把门禁卡收走了，一句多的话都没有，说实话比骂我还难受。"},{"id":"t_where","q":"九点以后你呢？","a":"一直在长桌边，除了起身倒过两分钟茶。韦老板朗读时我闭着眼，说实话，以为自己睡着了几秒。"},{"id":"t_up","q":"你上过二楼吗？","lie":true,"a":"没有。我现在就是个普通客人，连楼梯口都不好意思站，被辞退的人，哪还敢往人家二楼跑。","truth":"上去过一次，八点一刻。我溜上书房拿回自己两年前交的小说稿，她说有空看，一直没看。"},{"id":"t_saw","q":"你在书房看到什么？","needs":["ask:xing.t_up"],"a":"桌上两叠打字稿，一叠被铜灯压着，最上面是“第二章 饼干盒”，页脚“—— 30 ——”。那会儿一切完好。"},{"id":"t_pang","q":"你怎么看庞总？","a":"市场部的人，笑起来全是牙。今晚他一个人跑到外面车里坐了半天，说是接电话，谁信。上个月他还来问我晏老师新书的“卖点”。"},{"id":"t_vic","q":"她对你怎么样？","a":"她其实不坏。辞我那天，她让我拿走打字机旁那盒旧色带做纪念，我没要。现在想想……算了。"}],"confronts":[{"clue":"c_st5","breaks":"t_up","a":"他盯着抽屉里的便条冷笑：“你们连这个也查？行，我去过。那稿子是我自己的，不叫偷。”"},{"clue":"c_liv1","a":"“那你该看到我20:14到20:31不在。”他耸肩，“这十七分钟我本来也没想瞒到底。”"},{"clue":"c_st1","a":"“我八点多去的时候，两叠都在，铜灯压着其中一叠。不是我拿的，我要偷，也该偷我自己的那本。”"},{"clue":"c_st3","a":"听到铜灯和血，他往后退了半步：“那盏灯我替她擦过无数次。……谁这么狠，下得了手。”"}],"fallback":"说实话，这个我真不知道，别看我。"},{"id":"pang","name":"庞立峰","role":"出版社市场总监","age":45,"look":{"skin":"tan","hair":"slick","hairColor":"black","glasses":"none","beard":"none","outfit":"suit","acc":"tie","mood":"smirk"},"bio":"青禾出版社市场总监，负责《半夏》三十周年纪念版。席间频频看表，九点前后出去过一阵。","demeanor":"热络，爱叫“老师”“兄弟”，话里带数字，被追问就笑着绕。","topics":[{"id":"t_role","q":"你负责什么？","a":"《半夏》三十周年纪念版，首印八十万册，渠道物料全是我盯。晏老师是金字招牌，兄弟。"},{"id":"t_where","q":"九点以后你在哪？","lie":true,"a":"一直在客厅啊，兄弟，就出去接了两分钟电话，回来继续听书。大家都看见了，不信你问别人。","truth":"我在门口车里坐了四十多分钟。不是接电话，是在车里写一份东西，怕被人看见，才说一直在客厅。"},{"id":"t_offer","q":"你知道她要写回忆录？","lie":true,"a":"今晚才知道！跟大家一样吓了一跳，也替晏老师高兴，我们社全力支持，兄弟，作家想写回忆录是好事。","truth":"上周就知道了。她想另找出版社，我是来劝的：预付两百万，优先出版权。她说“有些话不是钱能换的”。"},{"id":"t_letters","q":"纪念版的读者来信？","needs":["clue:c_hall3"],"a":"来信有的是我们帮着整理润色的。润色，你懂吧。再多不方便说，晏老师本人知道，她默许。"},{"id":"t_car","q":"你在车里做什么？","needs":["ask:pang.t_where"],"a":"草拟声明。三十封来信有十几封是代拟的，她现在要“实话实说”，我得有预案。我没碰她，书房在哪我都不清楚。"},{"id":"t_vic","q":"你怎么看晏老师？","a":"真正的作家，老派人。别人发电子档，她非要用打字机一页页敲，说“字是敲出来才作数”。"},{"id":"t_who","q":"你怀疑谁？","a":"这个不好说。小骆跟她为合同拉扯过，邻居老耿恨她恨了十五年。我是生意人，只想跟她好好做生意。"}],"confronts":[{"clue":"c_hall2","breaks":"t_where","a":"他笑容一僵：“好，我在车里。兄弟，我只是想避开人写点东西，没想到被门铃抓了个正着。”"},{"clue":"c_hall3","breaks":"t_offer","a":"“预付两百万是我开的价。她没答应，我更急。可我急的是这个。杀一个作家，对我有什么好处？”"},{"clue":"c_st2","a":"听到“十二封是人写的”，他笑僵了：“这是我最怕的一页。可我怕丢饭碗，不是杀人。要灭口，我何必先开两百万？”"},{"clue":"c_gar4","a":"他看了看门闩和蛛网，苦笑：“我在门外，门闩在里头，兄弟。蛛网完整，我这身西装翻得了墙吗？”"},{"clue":"c_gar1","a":"他摇头：“要烧的话，我烧的是我那份说明。它还在我文件袋里，没动过，对吧，兄弟。”"}],"fallback":"这个回头再对一下，兄弟，今晚我脑子乱。"},{"id":"ji","name":"纪桂芳","role":"住家保姆","age":56,"look":{"skin":"tan","hair":"bun","hairColor":"black","glasses":"none","beard":"none","outfit":"apron","mood":"worried"},"bio":"在晏家做了八年的住家保姆，软软的南方口音。她说整晚在厨房备茶点，是第一个发现晏清如的人。","demeanor":"说话软，叫“太太”，一着急就“哎哟”，眼圈红了就攥围裙。","topics":[{"id":"t_role","q":"你在这里做什么？","a":"八年啦。做饭、收拾，记太太爱吃什么。她写稿时不许人上楼，除非有事。哎哟，现在心里空落落的。"},{"id":"t_where","q":"九点后你在哪？","lie":true,"a":"厨房，一步没出去，水果切了一盘，茶烧了三回。太太交代的事我哪敢偷懒，您可别冤枉我。","truth":"我在侧院冬青丛旁的石凳上打电话，快半个钟头。儿子学费差两千块，我急哭了，不想让人看见。"},{"id":"t_bell","q":"后楼梯的铃？","needs":["clue:c_kit1","ask:ji.t_where"],"a":"铃是我系的。太太从不走后楼梯。今晚响了两回，九点十分一回，九点二十几一回。我当是客人走错了路。"},{"id":"t_tea","q":"你什么时候送茶？","a":"九点四十五，我端茶走前楼梯，推开书房门，太太趴在地上……我当场就喊了，没敢碰她。"},{"id":"t_clean","q":"后院那个铁桶？","a":"下午我烧的落叶，没浇灭，太太说让它自己慢慢熄。桶到晚上还烫手呢，早知道我就浇透了。"},{"id":"t_guests","q":"谁出过门？","a":"耿大爷九点十分走的，说回去拿老花镜；庞先生更早，在车里坐着。其余的我没留意，魂都不在身上。"},{"id":"t_gate","q":"侧院的矮门？","needs":["clue:c_gar4","ask:ji.t_where"],"a":"矮门是我傍晚插死的，怕邻居的狗蹿进来。我坐在门里十几步远，门板一响我就听得见，一晚上一次也没有。"},{"id":"t_vic","q":"太太待你如何？","a":"好。去年我儿子考大学，她悄悄塞了红包给我，叫我别告诉人。太太嘴硬，心软，对谁都是。"}],"confronts":[{"clue":"c_gar4","breaks":"t_where","a":"她看着那团湿纸巾，眼圈红了：“是我的。我在石凳那儿打电话，哭得鼻子都堵了。太太知道了又要说我。”"},{"clue":"c_kit3","a":"“‘21:35’是我改的。”她揪着围裙，“九点那会儿我在外头哭呢，时间就耽误了。”"},{"clue":"c_kit1","a":"“铃响的时候，我当时要是进来看一眼就好了。可我顾着自己的事，哎哟，太太要是……”"}],"fallback":"哎哟，这个我不晓得，您莫吓我。"},{"id":"wei","name":"韦桐","role":"书店老板","age":42,"look":{"skin":"light","hair":"curly","hairColor":"brown","glasses":"round","beard":"goatee","outfit":"vest","mood":"smile"},"bio":"桐声书店老板，读书会的发起人和主持。他说整晚都在长桌边，九点半起朗读《半夏》第九章，是报警的人。","demeanor":"爽朗，爱用书名打比方，紧张时语速变快，先说“各位书友”。","topics":[{"id":"t_role","q":"读书会是怎么回事？","a":"办了四年，每月最后一个周六，书友们轮流选书。我这个书店老板，就是倒茶、搬椅子、念书的人。"},{"id":"t_where","q":"九点后你做什么？","a":"主持啊。九点半灯调暗，我朗读《半夏》第九章，念了二十多分钟，大家都闭着眼，我嗓子都哑了。"},{"id":"t_rec","q":"今晚有录像吗？","lie":true,"a":"没有，各位书友，晏老师不许拍，这条规矩立了四年了，我一个开书店的，哪敢坏她的规矩。","truth":"拍了。手机立在壁炉边，我想剪一期公众号用，没敢告诉晏老师，怕她活着的话要骂我，也怕你们说我偷拍。"},{"id":"t_shop","q":"书店最近怎么样？","a":"挺难，租金涨了三成。晏老师答应下个月在我店里办新书首发，我正指着这个翻身，她一走……唉。"},{"id":"t_bai","q":"谁中途离开过？","needs":["clue:c_liv1"],"a":"我光顾着念书。老柏好像去了洗手间，老耿回家取眼镜，小庞出去接电话。录像里应该都有。"},{"id":"t_seat","q":"座位怎么排的？","lie":true,"a":"抽签的，各位书友，随缘，摸到几号坐几号。晏老师只定了主位，我一个书店老板，可没动过什么手脚。","truth":"不是抽签。柏老师膝盖怕风，我把他从风口的六号位换到壁炉边三号位，还留了落地窗一指缝。我怕你们以为我串通。"},{"id":"t_light","q":"为什么调暗灯？","a":"第九章是雨夜戏，晏老师交代灯关一半。大家闭上眼，满屋只有我的声音。现在才明白，那是最容易溜走的时候。"},{"id":"t_vic","q":"你怎么看晏老师？","a":"她是我书店的恩人，每封读者来信都手写回。她说：“读者不欠作家任何东西，作家欠读者。”"}],"confronts":[{"clue":"c_liv1","breaks":"t_rec","a":"他脸涨红了：“被翻出来了。是，我拍了，没敢告诉晏老师。没想到它今晚会变成证据。”"},{"clue":"c_liv4","breaks":"t_seat","a":"“老柏怕冷，我就给他换了位子；屋里闷，我就留了窗缝。好心办的事，各位书友，我真不是替谁铺路。”"},{"clue":"c_hall2","a":"“21:50我出去接警。”他搓着手，“在路口站了十分钟，我一直想，要是早点发现灯不对……”"}],"fallback":"各位书友……不对，这个我真说不上来。"},{"id":"xu","name":"许曼琪","role":"多年老友","age":64,"look":{"skin":"fair","hair":"long","hairColor":"silver","glasses":"none","beard":"none","outfit":"turtleneck","acc":"scarf","mood":"sad"},"bio":"晏清如的大学同窗，插画家，下午就到了，住二楼客房。她说身体不适，20:58回房休息。","demeanor":"嗓音沙，说话直，爱用比喻，难过时反而打趣。","topics":[{"id":"t_role","q":"你和晏老师？","a":"四十多年的朋友，一起在城南文艺打过工。我画她的封面，她写我的序。她对自己心狠，对别人心软。"},{"id":"t_read","q":"回忆录你看过吗？","lie":true,"a":"半个字没看过。她一向写完才让我看，这回连草稿也不给，我也没问，你知道她那脾气，不好追问。","truth":"前天她给我看了第二章。我读到第三十三页就跟她吵了，今晚八点五十五分楼梯口又吵了一次。我劝她别那样写。"},{"id":"t_where","q":"九点后你在哪？","lie":true,"a":"在客房，吃了头痛药，一躺下就睡过去了，什么也不知道，直到楼下有人喊，我才被吵醒。","truth":"没睡。我坐在窗边睡不着。九点二十六分，我看见后院铁桶那儿起了火，桶边站着一个人。"},{"id":"t_saw","q":"后院那个人？","needs":["clue:c_gst2","ask:xu.t_where"],"a":"弯着腰，浅灰毛衣，微驼，拿长树枝拨火。我认得那背影三十年了，是老柏。我心想他一定有道理，没敢下楼。"},{"id":"t_1994","q":"一九九四年的事？","needs":["clue:c_gst3"],"a":"那年清如做校对，老柏夜里写小说。稿子是清如递上去的，署了谁的名，你们该猜到了。我一直觉得，这对谁都不公平。"},{"id":"t_p36","q":"第三十六页？","needs":["clue:c_gst1","ask:xu.t_read"],"a":"她追着我说：“你读到三十六页再骂我。”我没读。今晚她又提到律师、署名。我没说，是怕你们觉得他恨她。可谁会杀一个要把名字还给自己的人？"},{"id":"t_bai","q":"你对老柏怎么看？","a":"最老实的人。我劝他：“你该要回你的名字。”他说：“梅喜欢那本书就够了。”他对梅，比对自己好。"},{"id":"t_vic","q":"她最近怎么样？","a":"去年查出个良性肿瘤，虚惊一场，她从此像换了个人。她说欠下的账不能留到下辈子，回忆录就是她的还账单。"}],"confronts":[{"clue":"c_gst1","breaks":"t_read","a":"她盯着被划掉的信笺：“你连这个也看到了。是，我看过，也吵过。‘求你’是我这辈子写得最丢脸的两个字。”"},{"clue":"c_gst2","breaks":"t_where","a":"“那扇窗是我这晚唯一的电视机。”她苦笑，“我没睡，坐了一个钟头，看见了不该看见的东西。”"},{"clue":"c_st2","a":"听完色带上的话，她捂了好久嘴：“她连‘版权页’都敲上了……原来她早想明白了，只是没来得及告诉他。”"}],"fallback":"这个，我没什么好说的，亲爱的。"}],"solution":{"culprit":"bai","method":{"q":"凶手怎样作案并处理稿子？","options":["借口外出，绕侧院从后门进屋行凶，把稿子带回车里销毁。","趁厨房没人上楼行凶，把稿子藏进布包，原样带出屋子。","走后楼梯行凶，在后院烧掉稿子，趁灯暗从落地窗回座。","先躲在后院，灯暗时进屋上楼行凶，再把稿子扔进铁桶。"],"correct":2},"motive":{"q":"凶手为什么杀人？","options":["三十年的稿费往事被写成“封口费”，他受不了羞辱而失控。","回忆录要揭穿“读者来信”代拟的内幕，他为保住项目而灭口。","回忆录一发表，每年的稿费就断了，护理费没了着落，争执动手。","她迟迟不肯续约，他眼看年度业绩落空，失手伤人后销毁稿页。"],"correct":0},"keyClues":["c_st2","c_liv1","c_liv2","c_gar1","c_gar4","c_kit2"],"truth":["凶手是柏砚秋，《半夏》真正的第一位作者。一九九四年他写下《夏至》，晏清如改了七成，署上自己的名，是他点的头。三十年来她每年分他一半稿费，那成了他妻子的护理费。","晏清如决心“清账”，回忆录第二章把这笔钱写成了“封口费”。21:03她在柏砚秋耳边约他九点十分走后楼梯上来，说有几页想让他先看。","他在书房读到第33页“封口费”，三十年的情分被写成勒索，抓起桌边的灯盏奖座击中她后脑。他抽走第30至36页，用妻子绣“梅”字的手帕擦了灯座。","他在厨房冲了手帕，到后院铁桶烧了七页纸。21:34趁灯暗、众人闭目，从落地窗回座。露馅处：色带字迹、铁桶纸灰、铅笔头、拖鞋炭灰，和他离席的录像。","他不知道第36页写的是把署名还给他。庞立峰有嫌疑，但矮门从内插死、前门无人进出；为钱的推断也被律师草稿推翻。韦桐的好心安排，无意中替他铺了路。"]}},{"id":"campus","title":"校庆晚宴","tagline":"百年校庆的灯火通明，校史馆里的老人却再也没走出来。","difficulty":2,"cover":"cv_campus","tone":"warm","brief":"十月，百年校庆晚宴正热闹。你是校友，也是市局刑侦顾问，被校长童静仪叫到走廊。“柏仲谦教授九点要领奖，一直没来。保安找到他，人在口述历史室，已经……”门上挂着“录音中”的牌子，老教授倒在桌脚，一只黄铜校铃躺在身边。校长低声说：“二十点十几分，还有学生在门外听见他说话。请你在警方来之前，先替我看看。今晚在场的每个人，都想让你先相信他们。”","victim":{"name":"柏仲谦","desc":"七十四岁的退休植物学教授，本该今晚领终身成就奖。他倒在口述室桌脚，后脑被黄铜校铃砸中，手里攥着放大镜。","look":{"skin":"light","hair":"bald","hairColor":"white","glasses":"round","beard":"none","outfit":"vest","acc":"pocketwatch","mood":"smile"}},"relations":{"tong":"请他来领奖的在任校长","yin":"晚辈系主任，口述史项目负责人","yu":"读本科起就跟着他的关门弟子","hong":"后勤处长，管校庆水电安保","qi":"捐款的校友，想冠名老温室地块","lan":"今晚采访过他的校报学生记者","niu":"校史馆保安，发现遗体的人","xin":"共事四十年的退休档案员"},"links":[{"a":"yin","b":"yu","text":"同一个实验室的系主任和副教授"},{"a":"tong","b":"qi","text":"校长与捐资人，共推老温室冠名"},{"a":"tong","b":"lan","text":"记者泄露融资草稿，惹恼了校长"},{"a":"hong","b":"niu","text":"后勤处长和他手下的保安"}],"deathReport":{"time":"约 19:30–21:10","cause":"后脑遭黄铜校铃重击，颅骨塌陷","scene":"21:18 保安牛三宝推开口述室的门，见柏侧卧在桌脚，已无呼吸，门外挂着“录音中”的牌子。","loc":"room","notes":["后脑一处钝器伤，与校铃形状吻合","手里攥着放大镜","门边的校铃沾有血迹"]},"publicFacts":["柏仲谦，74岁，退休植物学教授，本该 21:00 领奖，一直没出现。","21:18 保安推开口述室的门，发现他已死亡，死因是后脑被黄铜校铃重击。","记者蓝小棠说，19:00 至 19:16 采访过柏，他好好的，还说 19:20 约了人谈标本。","蓝小棠还说，20:13 她回到口述室门外，听见柏在里面说话。","宴会厅三百多人，开席 19:30，致辞 19:40，敬酒 20:30，颁奖 21:00。","展厅监控今晚被暂停，后门是只有工作人员能刷卡的消防门。"],"timeline":[{"t":"19:00","text":"蓝小棠在校史馆门厅采访柏仲谦，至 19:16。"},{"t":"19:30","text":"晚宴开席。"},{"t":"19:40","text":"系主任代表致辞，其后短片、敬酒，三百多人在场。"},{"t":"20:13","text":"蓝小棠称在口述室门外听见柏在里面说话。"},{"t":"21:10","text":"校长见柏未到，派保安去找。"},{"t":"21:18","text":"保安发现柏的尸体，21:25 报警。"}],"budget":{"search":12,"ask":28},"locations":[{"id":"room","name":"口述历史室","scene":"study","desc":"校史馆深处六平米的隔音小屋，桌上一台录音平板，门外挂着“录音中”的牌子，屋里有旧纸和血的气味。","clues":[{"id":"c_rm1","title":"倒在桌边的老人","text":"柏仲谦侧卧桌脚，后脑塌陷。门边落着沾血的黄铜校铃（展厅藏品）。地上拖出两米血痕，他右手用手帕按着伤口。"},{"id":"c_rm2","title":"录音平板","text":"平板里四条录音：前三条是三月的口述，第四条“未命名”，19:41 至 20:41，满一小时，标注“已转写，需管理员查看”。"},{"id":"c_rm5","title":"柏的手机","text":"手机落在门边。通话记录：19:35 呼出尹济川，响铃5秒，通话0秒；再呼，响铃2秒；19:38 呼出童静仪，响铃28秒，未接。"},{"id":"c_rm3","title":"柏的采访笔记","text":"笔记：“登记簿暂存辛处。14、27、31号纸新，标签打印。展柜换线，问洪。19:20 谈，先听他怎么讲。上台说不说？”"},{"id":"c_rm4","title":"门上的牌子","text":"门外“录音中·请勿打扰”纸牌裁得齐整，胶带还黏，没有灰。门外把手有薄灰和几个指印，内侧把手干净。"}]},{"id":"hall","name":"校史馆展厅","scene":"hall","desc":"老照片、旧课桌和泛黄讲义被灯光分成一格一格，靠里是标本柜，旁边有通往院子的消防门。","clues":[{"id":"c_hall1","title":"三份标本","text":"14、27、31号标本衬纸雪白，紫外灯下泛蓝光，标签是激光打印的。其余标本衬纸泛黄，标签手写。"},{"id":"c_hall2","title":"标本借展登记","text":"登记页：14、27、31号，2021年10月送修复检测，经手人尹济川（0417），次年1月归还，签收栏空白。其余标本都有馆员签收。"},{"id":"c_hall3","title":"熄灭的摄像头","text":"展厅摄像头电源线被拔，便签写“线路改造，请勿插电，后勤处”。一格展柜的锁扣是新换的。"}]},{"id":"dining","name":"晚宴大厅","scene":"dining","desc":"体育馆改成的宴会厅，红毯、横幅、三十桌圆台，签到墙贴满今晚的合影。","clues":[{"id":"c_din1","title":"签到墙合影","text":"合影背面记着时间：19:12 尹济川签到；19:16 至 19:36 七张都是蓝小棠拍的，尹不在其中，末张注“尹主任接电话”；19:38 补拍，他又站回校长身侧。"},{"id":"c_din2","title":"节目单与座次","text":"节目单：19:30 开席，19:40 系主任致辞，20:00 校史短片（调暗灯光），21:00 给柏颁奖。主桌柏的座位空着，尹坐校长右侧，椅背搭着灰西装。"},{"id":"c_din3","title":"冠名协议草稿","text":"融资意向：校友企业“海川置业”出资两亿，冠名开发老温室地块。校长批注“柏老师那边我去谈”。夹纸条：“柏仲谦反对，此地限植物研究。”"}]},{"id":"back","name":"后台与采访区","scene":"backstage","desc":"舞台侧后方堆着演出服和乐谱架，墙边折叠桌上摊满校报记者的录音笔和笔记本。","clues":[{"id":"c_bk1","title":"采访录音笔","text":"两段录音。19:00 起门厅采访：柏说拐杖头掉了，又说“19:20 我约了人，谈标本”。20:13 起：女孩敲门喊“柏老师，我是小棠”，门里传出很轻的老人声，断续讲着“那年夏天，我在后山采到那株小花”，没有应门。"},{"id":"c_bk2","title":"手机上的消息","text":"乐谱架上的手机：猎头约谈南方高校的聘请，郁知秋回“今晚 20:05 我找安静处打给您”，备忘“别让老师知道”。"},{"id":"c_bk3","title":"合唱团排练表","text":"排练表：19:15 至 19:50 彩排，指导教师郁知秋签名，学生签到。备注“19:30 郁老师借班长手机拍队形”。"}]},{"id":"duty","name":"后勤值班室","scene":"engine","desc":"配电间旁的小屋，墙上挂满钥匙，电脑显示门禁和监控后台，桌上有半杯凉茶。","clues":[{"id":"c_eng1","title":"后门门禁记录","text":"校史馆消防后门：18:47 刷卡0233；19:21 刷卡0417；19:33 从内开门出；此后到 21:25 无记录。该门只认工作人员的卡。"},{"id":"c_eng2","title":"监控维修工单","text":"后勤工单：“校史馆线路改造，18:52 至 21:30 暂停监控，负责人洪守业”。施工方“守业工程”，未走招标，签批栏空白。"},{"id":"c_eng4","title":"灯光控制日志","text":"宴会厅灯光终端日志：19:22 至 19:39 共五次操作，都标“0233·本地登录”。椅背搭着深蓝工作服。"},{"id":"c_eng3","title":"外包报价单","text":"守业工程报价单：校史馆展柜灯光改造，三十八万。业主联系人写“洪守业（舅）”，备注“晚上施工”。"}]},{"id":"garden","name":"老温室与南门","scene":"garden","desc":"校史馆后院连着民国老玻璃温室，门边是南门保安亭，夜里湿冷。","clues":[{"id":"c_gar1","title":"温室门口的烟头","text":"温室石阶上有七八个同牌烟头，泥地有拖拽的鞋印和断成两截的拐杖头，刻着“柏”字。"},{"id":"c_gar2","title":"保安巡逻本","text":"巡逻本上 19:30、20:00、20:30、21:00 四行“巡视无异常”，笔迹墨色一模一样。桌角有半瓶二锅头。"},{"id":"c_gar3","title":"撕碎的同意书","text":"垃圾桶里有撕成四片的《冠名同意书》，签字栏空白，页边柏的字：“先师捐地，只可育人，不可卖。”一片上有灰黑手印。"}]}],"suspects":[{"id":"tong","name":"童静仪","role":"校长","age":59,"look":{"skin":"light","hair":"bob","hairColor":"silver","glasses":"round","beard":"none","outfit":"suit","acc":"necklace","mood":"tired"},"bio":"在任第六年的女校长，校庆总负责人。称开席后一直在主桌，21:10 派保安找柏，21:25 报警。","demeanor":"稳、温和，爱说“咱们学校”，痛处会换成官话。","topics":[{"id":"t_role","q":"今晚的安排？","a":"三百多位校友，我下午四点起没坐下过。柏老师是最要紧的客人，奖是我亲自定的。他一辈子守时，九点座位还空着，我就心里一咯噔。"},{"id":"t_deal","q":"冠名他同意吗？","lie":true,"a":"老温室冠名是校友捐赠，大家都知道。学校和柏老师沟通得很好，他没有意见，别把庆典想复杂。","truth":"他反对，很坚决。我压着没公开，怕他授奖时讲出来，融资泡汤。我是私心，可我没有害他。"},{"id":"t_last","q":"最后见他是？","a":"下午五点半，在校史馆。他拿着放大镜站在标本柜前，说要“再核一遍”，让我晚上别催他。"},{"id":"t_yin","q":"尹济川离开过？","needs":["clue:c_din1"],"a":"19:16 前后，他说教育局来电话，出去接。差不多二十分钟，回来就补拍合影、上台致辞。我没多问。"},{"id":"t_lan","q":"记者的事？","a":"小棠？机灵的孩子。融资草稿被人从打印机拿走发上网，我很恼火，但不怪她。她肯说实话，我不追究。"},{"id":"t_find","q":"谁发现的他？","a":"保安老牛。他推门进去，回来时脸都白了，话说不全。我陪他回去看了一眼，就让人封了现场报警。"},{"id":"t_miss","q":"19:38 接过电话？","lie":true,"needs":["clue:c_rm5"],"a":"没有。宴会厅里那么吵，我整晚手机都揣在口袋里，没人找过我，也没看到什么未接来电。","truth":"响了，28 秒，屏幕写着“柏老师”。我想他又要为冠名骂我，就按了静音。后来一直不敢点开那条未接。"}],"confronts":[{"clue":"c_din3","breaks":"t_deal","a":"她拿起“柏仲谦反对”的纸条，沉默片刻：“是的，他反对。我只是想让今晚平平安安过去。”"},{"clue":"c_rm5","breaks":"t_miss","a":"她的视线落在“童静仪”三个字上，嘴唇抖了一下，掏出手机，未接来电的红点还在。“……是我按掉的。”"},{"clue":"c_din1","a":"“那行字是我写的。”她指着“尹主任接电话”，“他说教育局，我就信了。他是个很规矩的人。”"},{"clue":"c_gar3","a":"她读着“只可育人，不可卖”，眼眶微红：“这个老头，到死都在护那块地，我却想着怎么绕开他。”"},{"clue":"c_rm3","a":"“‘说还是不说’。”她轻声念出来，“他是想在授奖时说点什么吧。可我当时，只想他别说。”"}],"fallback":"这个我不太清楚，你可以问问相关的同事。"},{"id":"yin","name":"尹济川","role":"植物学系主任","age":50,"look":{"skin":"light","hair":"sidepart","hairColor":"black","glasses":"rect","beard":"none","outfit":"suit","acc":"tie","mood":"worried"},"bio":"植物学系主任，口述史项目负责人。称开席前一直在大厅迎宾，19:40 致辞后陪校长坐主桌。","demeanor":"斯文周全，爱说“严格来讲”，被追问先推眼镜。","topics":[{"id":"t_role","q":"你和柏老师？","a":"他是我老师的老师。系里的校史展、口述史，都是他点头给的机会。他走成这样，我心里很乱。"},{"id":"t_where","q":"开席前你在哪？","lie":true,"a":"19:12 签到，一直在大厅迎宾合影，到 19:40 致辞。严格来讲，我没离开过会场。","truth":"我离开了二十来分钟。不是接电话，是柏老师约我去校史馆谈标本。不欢而散，我就回来了。"},{"id":"t_back","q":"去过后门吗？","lie":true,"a":"没有。今晚我没进过校史馆，展览是前一天布好的，我没理由再去。后门那种地方我平时都不走。","truth":"后门是我进的，他电话里让我走后门，怕被客人撞见。我们吵得很凶，后来的事我不想讲。"},{"id":"t_spec","q":"馆里标本还好？","lie":true,"a":"都好。三年前那三份送去修复检测，早就还回馆里了，登记齐全，没有任何问题。柏老师这回盘点，应该只是例行公事。","truth":"那三份是仿制品。原件我卖给了海外藏家，钱发了实验室欠了四个月的工资。我想等经费下来再赎。"},{"id":"t_voice","q":"20:13 的声音？","a":"小棠听见他说话？那他 20:13 还活着，事是之后出的。我 19:40 起在台上、主桌，三百人都看着。"},{"id":"t_lab","q":"实验室经费？","needs":["clue:c_hall2"],"a":"重点项目前年被砍了一半，学生补贴我垫到垫不动了。去年春天来了一笔海外基金，才缓过来。"},{"id":"t_pin","q":"平板谁会用？","needs":["clue:c_rm2"],"a":"管理员密码只有我和知秋知道。那条没名字的录音，大概是他自己点的，他爱对着话筒练稿。"},{"id":"t_phone","q":"柏打过你电话？","lie":true,"needs":["clue:c_rm5"],"a":"没有。我的手机整晚调的是震动，一直放在致辞稿旁边的口袋里，从头到尾没响过，也没人找过我。","truth":"响了。我在走廊看见“柏老师”，挂了。校铃是我抄的。我知道他还有气，可只要没人发现，标本的事就没人知道。"}],"confronts":[{"clue":"c_din1","breaks":"t_where","crack":true,"a":"他的手指在“尹主任接电话”上停了停。“校长真细心。”他苦笑，“好，我离开过，但只是去见了老师一面。”"},{"clue":"c_eng1","breaks":"t_back","crack":true,"a":"他盯着“19:21 刷卡 0417”，半晌才说：“工号是我的。可你们不能光凭一个工号。”"},{"clue":"c_hall1","breaks":"t_spec","a":"他在紫外光下看了看，肩膀垮了下来。“对不起老师。可我卖的是死物，换回的是活人的饭碗。”"},{"clue":"c_rm5","breaks":"t_phone","crack":true,"a":"他盯着“响铃5秒”“响铃2秒”，喉结滚了几下。“……你把它翻过去，别让我看屏幕。”"},{"clue":"c_rm2","a":"“第四条？”他的目光在“19:41”上停了停，“我没动过那条。要听，找知秋吧，她比我熟。”"},{"clue":"c_bk1","a":"“那更说明 20:13 他还活着。”他声音很稳，“我那时在台上，在主桌。你们该查那个时间段。”"},{"clue":"c_rm3","a":"他看着“先听他怎么讲”，喉结动了一下：“……他是想让我自己去找校长的。我没有。”"},{"clue":"c_rm4","a":"“牌子？”他看了一眼就挪开，“口述室平时就挂这种牌子，学生录音都要用。别从一块纸牌上想太多。”"}],"fallback":"严格来讲，这个和我没有直接关系。"},{"id":"yu","name":"郁知秋","role":"副教授·柏的门生","age":38,"look":{"skin":"fair","hair":"long","hairColor":"black","glasses":"none","beard":"none","outfit":"dress","acc":"earrings","mood":"sad"},"bio":"柏仲谦的关门弟子，口述史项目执行人，今晚带合唱团。称自己一直在后台，没出过大厅。","demeanor":"轻声细语，一口一个“老师”，提到柏会擦眼睛。","topics":[{"id":"t_role","q":"你和柏老师？","a":"我读本科就跟着他，他教我辨认每一种草。他总说，学问要沉下去，不要挂在嘴上。可是今天……"},{"id":"t_where","q":"开席后你在哪？","lie":true,"a":"一直在后台，带合唱团彩排、候场，没有出过大厅一步。学生们都在，随便问谁都行，他们能替我作证。","truth":"19:50 前都在排练。20:05 到 20:30 我去车里回猎头电话，南方的大学邀我去。我怕老师知道，没敢说。"},{"id":"t_voice","q":"口述史怎么录？","a":"三月，老师在口述室连讲三个下午。第3条讲后山那株小花，他说到一半会笑。平板单段最长一小时，到点自动停。"},{"id":"t_pin","q":"平板谁能设置？","needs":["clue:c_rm2"],"a":"管理员密码只有我和尹老师知道。第四条我没见过，下午我都在后台。要看转写得用管理员账号……我可以开。"},{"id":"t_file","q":"第四条录音？","needs":["clue:c_rm2","ask:yu.t_pin"],"a":"（她手指发抖）转写：“十九点四十一分，我是柏仲谦。头上挨了一下，站不起来。刚才打了三个电话，没人来。门外的牌子是他挂的，我听见撕胶带的声音。”"},{"id":"t_file2","q":"后面还有吗？","needs":["ask:yu.t_file"],"a":"有。20:13：“有人敲门……是小棠。孩子，我出不去。我讲点别的，免得睡过去。”他一直讲到 20:41，平板满了自己停。老师是一个人在里面等的。"},{"id":"t_yin","q":"尹主任这些年？","a":"尹老师人很好，只是实验室缺钱，工资拖了四个月。去年春天忽然有笔海外基金，全发了。"},{"id":"t_leave","q":"为什么想走？","needs":["clue:c_bk2"],"a":"实验室留不住人，我也快三十九了。南方有平台有经费。可想到老师年纪大，我想等他百岁。现在等不到了。"}],"confronts":[{"clue":"c_bk2","breaks":"t_where","a":"她眼泪涌上来：“我不是故意骗你。我不想老师临走前还为我难过。20:05，我真的在车里。”"},{"clue":"c_bk3","a":"“19:30 我借班长手机拍队形。”她点头，“19:15 到 19:50 我寸步没离开学生。”"},{"clue":"c_rm2","a":"“第四条……”她声音哽住，“密码我有，可我整晚没碰过。我现在开，但我怕听不下去。”"},{"clue":"c_rm5","a":"她捂住嘴：“他打给尹老师，又打给校长，怎么没打给我？我 20:05 才出去的，早点看手机……”"},{"clue":"c_hall1","a":"她看着新纸标本愣了很久，轻声说：“这三份老师一直说是镇馆的东西，怎么会变成这样？”"}],"fallback":"对不起，我现在脑子很乱，答不上来。"},{"id":"hong","name":"洪守业","role":"后勤处处长","age":55,"look":{"skin":"tan","hair":"short","hairColor":"grey","glasses":"none","beard":"stubble","outfit":"jacket","acc":"badge","mood":"stern"},"bio":"干了三十年的后勤处长，管校庆场地水电安保。称开席前后一直在配电间和宴会厅之间来回。","demeanor":"嗓门大，爱说“咱们”，问到钱先拍胸脯再岔开。","topics":[{"id":"t_role","q":"今晚负责什么？","a":"电、水、灯、保安、车位，全是咱后勤的活。咱老洪三十年没出过岔子，出了命案，这张老脸往哪儿搁。"},{"id":"t_cam","q":"监控正常吗？","lie":true,"a":"正常得很！所有摄像头一直开着，咱从不关。命案是后头的事，没拍到，那是凶手走了死角，别往咱后勤头上扣。","truth":"关了，18:52 我下令的。说线路改造，其实是让外甥的公司晚上装展柜，没招标。监控开着我就露了，但我没碰过柏老师。"},{"id":"t_proc","q":"外包都招标吗？","lie":true,"a":"走啊，怎么不走！五万以上的活必须招标，这是规矩。每一笔都有记录，你随时去查账，查！","truth":"那三十八万的活，我拆成几笔小单绕过去了。外甥刚创业，我想拉他一把。我认违规，可跟命案无关。"},{"id":"t_where","q":"19:20 你在哪？","a":"配电间。19 点后我一直盯着配电柜，中间跑了两趟宴会厅。一个人待着，没人作证，咱认。"},{"id":"t_light","q":"开席灯光谁调？","needs":["clue:c_eng4"],"a":"开席前后的调光都是咱在配电间终端上推的，灯一歪校长能撕了咱。半步没离开那张椅子，能替咱作证的，就是那台电脑。"},{"id":"t_door","q":"后门谁能进？","needs":["clue:c_eng1"],"a":"消防后门刷卡，后台都有记录。0417……那是尹主任的卡，他是项目负责人，常出入。"},{"id":"t_qi","q":"戚老板找过你？","a":"找过。下午他要老温室的钥匙，说“先看看地”，咱没给。他还说柏老头不签字，就找校长压。"}],"confronts":[{"clue":"c_eng2","breaks":"t_cam","a":"他把工单一拍：“行，是咱让关的！”又压低声，“可你查查，那一个钟头咱是不是一直在配电间？”"},{"clue":"c_eng3","breaks":"t_proc","a":"他盯着报价单上的“舅”字，咳了两声：“三十八万拆成几笔，咱认。但这是违规，不是杀人，你分得清吧？”"},{"clue":"c_eng4","a":"“0233，本地登录，咱的号。”他哼了一声，“得人坐在跟前一下下点，咱十来分钟没离开椅子。”"},{"clue":"c_eng1","a":"“0233 是咱的卡，18:47 进去看线路，就待几分钟。”他嘟囔，“0417 那是尹主任的。”"},{"clue":"c_hall3","a":"“这便签是咱贴的。”他不情愿地承认，“线路改造，你可别往大里说，咱是为了展柜的光。”"},{"clue":"c_rm3","a":"他念着“问洪”，脸涨红：“老头子眼睛毒。是，咱没给他看单。可咱要真有那心思，用得着等今晚？”"}],"fallback":"这个咱不清楚，你去问负责的人。"},{"id":"qi","name":"戚海川","role":"校友企业家","age":48,"look":{"skin":"tan","hair":"slick","hairColor":"black","glasses":"sun","beard":"goatee","outfit":"suit","acc":"pocketwatch","mood":"smirk"},"bio":"海川置业董事长，校友，捐了五百万，推动老温室冠名。称 19:30 才到，没见过柏仲谦。","demeanor":"自来熟，爱叫“兄弟”，笑嘻嘻带刺，被抓包就拍大腿。","topics":[{"id":"t_role","q":"你和母校？","a":"九四级的穷学生出身，母校百年，我捐五百万眼睛都不眨。冠名那块地，也想给学弟学妹留点好东西。"},{"id":"t_arrive","q":"你几点到的？","lie":true,"a":"19:30，开席的点儿，我这人守时。到了就找校长喝酒，没见过什么柏老教授，也聊不到一块去。","truth":"18:40 就到了。我在老温室门口找他谈地块，谈崩了，我推了他一把，拐杖断了。我心虚，躲进车里打电话到 20:30。"},{"id":"t_deal","q":"冠名怎么谈的？","a":"两亿，海川出，冠名“海川园”，建植物中心加酒店。老教授就是不签，说地是先师捐的。"},{"id":"t_quarrel","q":"你们吵了什么？","needs":["clue:c_gar3"],"a":"他一句“只可育人，不可卖”，我就上火了。骂了他，推了他，他退两步，拐杖头断了。我马上就走了。"},{"id":"t_car","q":"你在车里做啥？","a":"打电话，十几个，生意上的事。司机小周坐驾驶座，能作证我一直到 20:30 才下车。"},{"id":"t_saw","q":"车里看到什么？","needs":["clue:c_eng1"],"a":"19:20 左右，一个穿灰西装的男人走到消防门，刷卡进去，低着头走得很急。没看清脸。"}],"confronts":[{"clue":"c_gar1","breaks":"t_arrive","a":"他笑容挂不住了：“被你捡到了。行，我 18:40 就到，推了他。可我走时他站着骂我，中气十足。”"},{"clue":"c_gar3","breaks":"t_arrive","a":"他看着撕碎的同意书，抿紧嘴：“是我递给他，被他撕了。我气炸了，可他死了这地更没法签，我图什么？”"},{"clue":"c_bk1","a":"他愣了愣：“19:00 他还能站着聊天，惦记着配拐杖……那我走的时候，他是好好的。”"},{"clue":"c_din3","a":"“两亿，一分不少。”他点头，“学校早就想要这笔钱了，我只是付钱的，别让我背锅。”"},{"clue":"c_eng1","a":"“19:21……”他想了想，“对，就是我看见那人进去的点儿。灰西装，难怪背影眼熟。”"}],"fallback":"哎，兄弟，这个我真没印象，聊点别的。"},{"id":"lan","name":"蓝小棠","role":"校报学生记者","age":20,"look":{"skin":"light","hair":"ponytail","hairColor":"brown","glasses":"round","beard":"none","outfit":"hoodie","acc":"headset","mood":"worried"},"bio":"新闻学院大三学生，校庆特刊记者。称 19:00 至 19:16 采访过柏，之后没再去过校史馆。","demeanor":"语速快，爱说“其实”，心虚时绕耳机线。","topics":[{"id":"t_role","q":"你是做什么的？","a":"校报实习记者，其实这学期才进特刊组。今晚三个任务：采访柏教授，拍签到墙，拍颁奖。结果第一个成了最后一个。"},{"id":"t_after","q":"采访后去过吗？","lie":true,"a":"没有。采完 19:16 我就回大厅拍照，一直忙到颁奖前，其实没再去过校史馆，这一点我能保证。","truth":"我去过。20:13 我回去找他问草稿泄露的事。敲门没人理，里面一直在说话，我以为他在录口述，就走了。我怕被追问。"},{"id":"t_interview","q":"采访他说了啥？","a":"他说在盘点馆藏。快结束时看了眼表：“19:20 我约了人，谈标本的事，你先去吧。”他的拐杖头掉了，一直在缠胶布。"},{"id":"t_leak","q":"草稿是你泄露的？","a":"……我在打印机旁捡到的，一开始只想看看，后来发了帖。我觉得学生有权知道老温室要变酒店。校长一定恨我。"},{"id":"t_voice","q":"你听到的声音？","needs":["clue:c_bk1"],"a":"就是他的声音，但很轻，断断续续，隔着门板像在小声念稿。我敲了好几下，他没停。我还想，老先生真入神。"},{"id":"t_door","q":"门口看到什么？","needs":["ask:lan.t_after"],"a":"门外挂着“录音中”，我就没敢推门。门缝底下好像有点暗。现在想想，要是我推了一下……"},{"id":"t_yin","q":"见过尹主任吗？","a":"19:12 他签到我拍过。19:40 他致辞我也拍了，他的手有点抖，我以为是紧张。"}],"confronts":[{"clue":"c_bk1","breaks":"t_after","a":"她咬着嘴唇：“好吧，我回去过。现在听才发现，他声音是不是太弱了？我敲那么响，他一点反应都没有。”"},{"clue":"c_din3","a":"她盯着那份草稿，手指绕紧耳机线：“这是我从打印机边拿的那份。对，帖子是我发的，我认。”"},{"clue":"c_rm4","a":"“我 20:13 去的时候牌子就在了。”她摇头，“我还想，原来在录口述，就没敢进去。”"},{"clue":"c_din1","a":"她凑近翻到背面：“那七张都是我拍的，我一直在大厅里跑。尹老师那一段，我没拍到他。”"},{"clue":"c_rm5","a":"她脸一点点白了：“19:35……他那时就在打电话求人？那我 20:13 听见的，是不是……”"}],"fallback":"这个我不太确定，怎么说呢，我不想乱讲。"},{"id":"niu","name":"牛三宝","role":"校史馆保安","age":60,"look":{"skin":"brown","hair":"cap","hairColor":"grey","glasses":"none","beard":"stubble","outfit":"uniform","acc":"badge","mood":"tired"},"bio":"二十年老保安，今晚守校史馆和南门，21:18 推开口述室门的人。称每半小时巡逻，没离岗。","demeanor":"憨厚，北方口音，爱说“嗨”，心虚时先递烟。","topics":[{"id":"t_role","q":"你今晚干啥？","a":"嗨，守校史馆呗，南门保安亭也归我。今儿人多，我下午三点就没歇着。晚上冷，我裹大衣在后门外抽两口。"},{"id":"t_patrol","q":"你巡逻了吗？","lie":true,"a":"巡了啊，每半小时一趟，19:30、20:00、20:30、21:00，都写在本子上。","truth":"本子是我提前一起填的。19:50 我在保安亭喝了二两二锅头，睡到 21:00 多。我违规，对不起学校。"},{"id":"t_find","q":"怎么发现的？","a":"21:10 校长派我找柏教授。前门没人，我绕到口述室，门挂着“录音中”，敲几下没应，推门一看……我腿都软了。"},{"id":"t_saw","q":"看到谁没有？","needs":["clue:c_eng1"],"a":"想起来了。19:34 我在后门外抽烟，有个男的从消防门出来，穿灰西装，别蓝花，边走边用湿巾擦手。我当是服务生。"},{"id":"t_flower","q":"蓝胸花谁戴？","needs":["ask:niu.t_saw"],"a":"教职工戴蓝花，嘉宾红花，学生黄花，校领导金花。教授、系主任、处长都是蓝的。没看清脸。"},{"id":"t_door","q":"后门怎么开？","a":"消防门平时关着，外面只能刷工作卡进，里头按个钮就能出来。我巡逻时会拉一下，看锁没锁。"}],"confronts":[{"clue":"c_gar2","breaks":"t_patrol","a":"他脸一红，抓抓后脑勺：“哎呀，被你看出来了，四行字是我一口气写的。那二锅头，我就喝了二两！”"},{"clue":"c_eng1","a":"他眯眼看门禁：“19:33 门开，我 19:34 看见人出来，对得上，对得上！”"},{"clue":"c_hall3","a":"“摄像头？”他摇头，“洪处长下午就说晚上要改线路，让我别多管闲事，我就没敢多问。”"},{"clue":"c_rm4","a":"“这牌子我下午巡逻还没见。”他想了想，“19:34 往走廊瞅过一眼，也没人守着。”"}],"fallback":"嗨，这个我真不知道，您别为难我老头子。"},{"id":"xin","name":"辛秀兰","role":"退休档案员","age":72,"look":{"skin":"fair","hair":"bun","hairColor":"white","glasses":"round","beard":"none","outfit":"qipao","acc":"flower","mood":"smile"},"bio":"退休档案员，帮校史馆整理馆藏，与柏共事四十年。称登记簿一直在馆里，自己 19:40 不舒服先回家。","demeanor":"慢条斯理，爱说“咱们那会儿”，偶尔叹气。","topics":[{"id":"t_role","q":"你和柏老师？","a":"四十年老同事。他管草，我管纸，一起在地下室整理过一百箱旧档案。他常说，纸会老，字不会。"},{"id":"t_book","q":"登记簿在哪？","lie":true,"a":"一直在校史馆标本柜的抽屉里，从来没拿出去过。馆藏哪能随便带走，咱们那会儿规矩严。","truth":"两周前，柏老师悄悄让我带回家的。他想对对三份标本的原始登记，不让馆里人知道。我怕牵扯出他要查的事。"},{"id":"t_left","q":"你几点走的？","a":"19:40。血压药忘带了，头晕，跟校长打了招呼，坐班车回家。后来的事是电话里听说的，吓得一夜没睡。"},{"id":"t_spec","q":"那三份标本？","needs":["clue:c_hall1"],"a":"14号右下角有道撕口，是1958年搬迁时夹的，我用宣纸补过。现在衬纸雪白没撕口？那就不是原件了。"},{"id":"t_yin","q":"谁借过标本？","needs":["clue:c_hall2"],"a":"2021年10月，尹主任说送去检测，我开的登记，他签了名。还回来时我休假，没人点收，签收栏就空了。"},{"id":"t_bai","q":"他最近状态？","a":"很沉。他说：“秀兰，我替人收拾半辈子烂摊子，这回怕收拾不了。”还交代我，他要是没上台，就把登记簿交给校长。"}],"confronts":[{"clue":"c_rm3","breaks":"t_book","a":"她读着“登记簿暂存辛处”，苦笑：“被他自己的字揭穿了。是，我拿回家了。这老头，连死都要证明我撒谎。”"},{"clue":"c_hall2","a":"她看着登记页，摇摇头：“这几条是我写的。签收栏我早提醒过要补，后来人一休假，就忘了。”"},{"clue":"c_hall1","a":"她看着新纸标本：“14号右下角那道撕口不见了。”她摸着玻璃，声音发颤，“原来的东西到哪儿去了？”"},{"clue":"c_din2","a":"她看着“21:00 颁奖”：“他年轻时最怕上台，说话还结巴。今晚本来要好好讲一回的。”"}],"fallback":"你们年轻人问的这个，我老太婆不太清楚。"}],"solution":{"culprit":"yin","method":{"q":"凶手的不在场证明是怎么“造”成的？","options":["记者离开后，趁短片熄灯潜入行凶，再赶回宴会厅","争执中失手，死者当场断气，挂牌拖延发现","找人躲在门里冒充死者说话，推迟案发时刻","开席前重击挂牌，明知有气不救，声音误导时间"],"correct":3},"motive":{"q":"凶手为什么杀人？","options":["死者拒签冠名协议，融资落空，争吵后动了手","死者查出标本被调包卖掉，要在授奖时揭发","死者发现工程违规外包亲属，扬言要举报灭口","死者听说凶手要跳槽，打算在典礼上讲出来"],"correct":1},"keyClues":["c_rm2","c_bk1","c_din1","c_eng1","c_hall1"],"truth":["凶手是系主任尹济川。他经费断档，欠了学生四个月工资，把馆里三份标本卖给海外藏家，换回仿品。柏盘点时发现，约他开席前面谈。","19:16 尹借口接电话离场，19:21 刷自己的卡（0417）进后门。谈崩后，他用展厅的校铃砸了柏的后脑，19:33 挂牌离开，湿巾擦手。","柏当时没死。他给尹打了两次电话，都被挂断；打给校长，没人接。19:41 他爬到桌边开始录音，录到 20:41 自动停止，后来才死。","20:13 蓝小棠听见的是垂死的柏，不是诡计。全场因此把案发推到 20:13 后，而尹那时一直在台上、主桌。洪守业、郁知秋的嫌疑，被灯光日志和排练表排除。","尹并非失手：他看见来电，两次挂断，又挂牌封门，任柏死去。冠名、回扣、跳槽都只是表面动机，其余人的谎各有缘由，与命案无关。"]}},{"id":"ferry","title":"雾中渡轮","tagline":"浓雾锁海，货箱失踪，凶手就在这艘不能靠岸的船上。","difficulty":2,"cover":"coverShip","tone":"cold","brief":"最后一班渡轮“海燕号”载着十个人驶向白礁岛。你是随船的海警刑侦顾问。二十三点五十分，船长庄国梁敲开你的门：头等3号舱里，货主代表方启明被人打死，他押运的两千八百万南洋金珠也不见了。海上大雾，雷达上只有这艘船，天亮前谁也不许靠岸。凶手和货都在船上。距抵达还有四个多小时，船长说：“请你在靠岸前，查出是谁。”","victim":{"name":"方启明","desc":"恒泰珠宝货主代表，五十六岁，押运金珠去白礁岛拍卖。他俯卧在3号舱床脚，后脑被重物击中，货箱托架已空。","look":{"skin":"light","hair":"sidepart","hairColor":"grey","glasses":"rect","beard":"none","outfit":"suit","acc":"tie","mood":"stern"}},"publicFacts":["货物是一箱38颗南洋金珠，估价约2800万，送往白礁岛春季拍卖会。","除你和死者外，船上有八人：四名船员，加商人、记者、游客、保险代理人。","方启明死于后脑钝器重击，时间在22:50至23:48之间。","雾很大，雷达上没有其他船，没人能上船或离船。","按规定雾中每两分钟鸣一次雾笛，今晚全程没有中断。","货箱托架是用钥匙打开的，货箱不在舱内。"],"relations":{"zhuang":"这趟船的船长，负责全船安全","shao":"船上的大副，值夜班的驾驶员","he":"船上的轮机员，管机舱的老员工","xia":"船上的厨师，夜宵是他做的","wang":"受邀赴拍卖会的珠宝商，潜在买家","su":"同船乘客，自称去做民宿专题的记者","lin":"同船的独行游客，和死者素不相识","gu":"承保这批金珠的保险代理人"},"links":[{"a":"zhuang","b":"shao","text":"船长和大副，驾驶台上的正副手"},{"a":"he","b":"xia","text":"同船干活的老同事，机舱和厨房"},{"a":"wang","b":"gu","text":"都为这批金珠而来：买家与保险方"}],"deathReport":{"time":"约 22:50–23:48","cause":"后脑遭钝器重击，颅骨塌陷","scene":"23:48，保险代理人谷明哲敲门无人应，推门见方启明俯卧在3号舱床脚，货箱不见了。","loc":"cabin","notes":["后脑一处钝器伤，一击致命","货箱托架的钢缆锁已被钥匙打开","床头小桌上的姜茶已经凉透"]},"timeline":[{"t":"21:40","text":"“海燕号”离港，起雾，雾笛开始每两分钟鸣一次。"},{"t":"22:50","text":"夜宵结束，方启明回3号舱（多人看见）。"},{"t":"23:48","text":"谷明哲敲3号舱门无人应，推门发现方启明死亡、货箱不见。"},{"t":"23:55","text":"船长封锁通道，清点人数：无人落水。"},{"t":"00:10","text":"电台通报：大雾不散，预计04:30抵岸，警方在岛上接手。"},{"t":"00:20","text":"船长将调查委托给你。"}],"budget":{"search":15,"ask":32},"locations":[{"id":"deck","name":"右舷甲板与救生艇","scene":"deck","desc":"狭长的右舷甲板，雾水把柚木地板打得又湿又滑，头顶悬着救生艇。","clues":[{"id":"c_deck1","title":"救生艇里的货箱","text":"2号救生艇的帆布罩下塞着灰色钢制货箱，铅封HT-0472完好，锁孔无划痕。单据毛重31.0公斤，手感相符。"},{"id":"c_deck2","title":"湿甲板上的鞋印","text":"白色软底人字纹鞋印，长约28厘米，从3号舱舷门到2号艇，再折回驾驶台铁梯。舷门口有暗红点。几串胶靴印压在它上面。"},{"id":"c_deck3","title":"栏杆边的电子烟","text":"右舷后段栏杆边落着一支粉色电子烟和一团泡软的纸巾。从这里看，2号救生艇就在二十来米外。"}]},{"id":"cabin","name":"3号贵宾舱","scene":"cabin","desc":"驾驶台正下方的头等舱，床头灯亮着，空气里有血腥味和姜茶味。","clues":[{"id":"c_cab1","title":"凶案现场","text":"方启明俯卧床脚，后脑塌陷。床边有沾血的扳手，钢印“E-14”。托架钢缆锁已开，钥匙还插着。门口掉着一支“晨潮报”圆珠笔。"},{"id":"c_cab2","title":"带圈的船员名单","text":"船员名单上，“邵远帆”被红笔圈了两圈，页边写“两个月前才调上这条线？谁批的。”“贺大勇”被画了叉，旁注“旧人，避开”。"},{"id":"c_cab3","title":"凉透的姜茶","text":"床头小桌上一杯满满的姜茶，已凉透，杯沿无唇印。托盘垫纸写着“23:05 3号 姜茶 夏”。烟灰缸是干净的。"},{"id":"c_cab4","title":"手机里的短信","text":"手机三条未读：汪志达22:12“价钱好商量，抵岸前私下谈？”；陌生号码22:20“聊聊海顺号吧”；谷明哲22:47“解约请再考虑到明天”。另有份未签字的“中泰保险”解约函。"}]},{"id":"engine","name":"机舱","scene":"engine","desc":"船尾下层的机舱，主机轰鸣，柴油味扑面。墙上是工具架和登记板。","clues":[{"id":"c_eng1","title":"工具架上的空位","text":"工具架上只有E-14的挂钩空着。登记板写着：“E-14 活动扳手14寸 · 18:40 借 · 厨房 夏 · 未还”。"},{"id":"c_eng2","title":"后舱的柴油桶","text":"发电机组后藏着一只铁桶，软管接着燃油柜放油阀，还在滴。日志“23:00”“23:30”两行巡检墨色一致。"},{"id":"c_eng4","title":"定时器检修卡","text":"检修卡：“雾笛自动档定时器 · 17:50 · 间隔180s→120s · 经手 贺 · 复核 ____”。复核栏空着。"},{"id":"c_eng3","title":"更衣柜里的旧照","text":"轮机员柜门内贴着“恒泰航运”合影，西装男人被画叉，写着“方启明”。柜底有张三年前的解雇通知：“擅自出售燃油”。"}]},{"id":"dining","name":"休息厅与餐厅","scene":"dining","desc":"船腹中部的休息厅，沙发、餐桌和没洗的杯子。舷窗外一片白，雾笛隔一阵响一声。","clues":[{"id":"c_din1","title":"桌上的录音笔","text":"雾笛23:08前间隔不一，23:08:15到23:32:15每两声整整120秒，23:34后又参差。底噪有酒后咒骂（23:14、23:21、23:29）。23:20:40一声闷“咚”。键盘声23:35停了七八分钟。"},{"id":"c_din2","title":"记者的剪报簿","text":"三年前的报纸：渔船“海顺号”雾夜被撞沉，船长邵远洋等四人遇难，疑为“恒泰7号”所撞，运营负责人方启明称“没有证据”。"},{"id":"c_din3","title":"竞买文件","text":"皮包里有拍卖会竞买号牌，金珠底价2500万。便签写：“上限3000万。拍前私下收货，能压到2200万。”"},{"id":"c_din4","title":"保单副本","text":"保单复印件，保额2800万，代理人谷明哲。第九条被涂亮：货主抵岸前解约，代理人须退佣金、赔违约金，资格终止。"}]},{"id":"hall","name":"驾驶台与海图室","scene":"hall","desc":"船最高处的驾驶台，玻璃外一片白雾。后壁是雾笛控制箱，隔壁是海图室。","clues":[{"id":"c_hall1","title":"雾笛控制箱","text":"控制箱旋钮在“手动”。定时器屏留着记录：“AUTO 启动 23:08 · 停止 23:34 · 间隔 120s”。"},{"id":"c_hall2","title":"航海日志","text":"邵远帆笔迹：“23:00 船长离台休息，大副值班。23:15、23:30 雾笛手鸣。23:50 接3号舱事故报告。”"},{"id":"c_hall3","title":"海图室的相片","text":"抽屉深处压着一张相片：渔船船头站着两个男人。背面写：“海顺号 · 哥 远洋 / 弟 远帆”。"}]},{"id":"kitchen","name":"厨房","scene":"kitchen","desc":"狭小的船上厨房，灶台上温着粥，后面有扇通右舷后甲板的小门，旁边是冷库。","clues":[{"id":"c_kit1","title":"内线点单板","text":"点单板记着：“22:30 大副 咖啡×1（来取）”“23:02 3号舱 姜茶×1”，后一条旁写“送，夏”。"},{"id":"c_kit2","title":"后门窗台","text":"后门旁窗台有一道长方形新压痕，水渍未干。案板上摆着半块凿开的冻鱼冰。"},{"id":"c_kit3","title":"冷库里的纸箱","text":"冷库纸箱后藏着五条无税票的外烟。压着一张船长笔迹的便条：“老夏，别带太多，上岛前收好。”"}]}],"suspects":[{"id":"zhuang","name":"庄国梁","role":"“海燕号”船长","age":58,"look":{"skin":"tan","hair":"short","hairColor":"grey","glasses":"none","beard":"stubble","outfit":"uniform","acc":"badge","mood":"tired"},"bio":"“海燕号”船长，跑白礁线十一年，矮壮。他说雾夜从不离开驾驶台，23:50后封锁了全船。","demeanor":"老海员的粗嗓门，爱说“规矩”，心虚时先清嗓子。","topics":[{"id":"t_role","q":"这条线你怎么管？","a":"白礁线我跑了十一年，船小人少，四个船员当八个用。雾天规矩只有一条：驾驶台不空人，雾笛不断声。"},{"id":"t_watch","q":"23点后你在哪？","lie":true,"a":"驾驶台，从离港一直站到出事。雾天我从不离台，大副就在我身边帮着拉雾笛，谁都能作证。","truth":"我23点就回舱躺下了。血压药一吃人发昏，我对大副说“你顶着，有事叫我”。违规，我认。"},{"id":"t_horn","q":"雾笛怎么操作？","a":"驾驶台里拉绳，手拉，两分钟一声。后面铁箱里还有个自动档，是给检修备的，值班不许用。"},{"id":"t_mate","q":"你了解大副吗？","needs":["clue:c_cab2"],"a":"邵远帆？两个月前调来，话少，手脚快，从不叫累。夜班线是他自己点名要的。……怎么忽然问起他？"},{"id":"t_foot","q":"这脚印是谁的？","needs":["clue:c_deck2"],"a":"白软底鞋甲板部统一发，我和大副各一双。我穿41码，鞋底才二十六公分出头。这脚比我大一圈。"},{"id":"t_vic","q":"方启明说过什么？","needs":["clue:c_kit3"],"a":"登船时他问我，全船有没有不该有的货。他要是报上去，我这条线就保不住了。……我杀人？"}],"confronts":[{"clue":"c_hall2","breaks":"t_watch","a":"他盯着“船长离台休息”那行，清了清嗓子：“……是我让大副这么写的。吃药的事传出去，饭碗不保。我睡了，可没杀人！”"},{"clue":"c_hall1","a":"他凑近定时器看了半天：“谁动的自动档？我23点前碰都没碰。那玩意儿值班不许用。”"},{"clue":"c_kit3","a":"“老夏那点私烟，我早知道，睁只眼闭只眼。”他摆摆手，“船上缺人，我不想连厨子也赶走。这跟命案有什么相干？”"},{"clue":"c_cab2","a":"船长眉头越皱越紧：“圈在邵远帆头上？……登船时方先生问过我，大副是哪里人。我当他闲聊。”"},{"clue":"c_hall3","a":"船长看着相片愣住了：“这是他和他哥？他从没提过家里有人出海。这小子，闷得像块石头。”"}],"fallback":"这玩意儿跟我的船没关系，你问点实在的。"},{"id":"shao","name":"邵远帆","role":"“海燕号”大副","age":36,"look":{"skin":"light","hair":"short","hairColor":"black","glasses":"none","beard":"none","outfit":"uniform","acc":"badge","mood":"neutral"},"bio":"“海燕号”大副，两个月前调来，个子很高，话少。他说23点接班后一直守在驾驶台，手拉雾笛。","demeanor":"平静克制，说话简短，被逼到点上才露出一丝冷。","topics":[{"id":"t_watch","q":"23点后你在哪？","lie":true,"a":"驾驶台，一步没离开。船长回舱休息了，我一个人值班，雷达、航向、雾笛全是我一个人在管。","truth":"我离开过驾驶台。23点08分到34分，雾笛调了自动，我下去了——就这些，别的我暂时不想说。"},{"id":"t_horn","q":"雾笛都是你拉的？","lie":true,"a":"每两分钟一声，我亲手拉的。你随便问休息厅里哪个乘客，他们听了一晚上，没断过，也没乱过。","truth":"不是手拉的。我拨到自动，让定时器替我鸣笛。我要所有人都觉得，拉绳的人一直在台上。"},{"id":"t_deck","q":"你下过甲板吗？","lie":true,"a":"没有。我只在驾驶台和海图室，23:50接到事故报告才第一次下甲板，日志里写得清楚。","truth":"下去过。我从右舷铁梯下去，进舷门，一路走到2号救生艇，再原路回来。甲板上那串鞋印是我的。"},{"id":"t_know","q":"你认识方启明吗？","lie":true,"a":"不认识。名单上见过一回，货主代表，仅此而已。我这样的人，一辈子也轮不上和他搭话。","truth":"认识。海顺号上死的四个人里，有我哥邵远洋。我知道方启明是谁。三年了，我等的就是这样一场雾。"},{"id":"t_coffee","q":"22:30你在做什么？","a":"我下厨房要了杯咖啡，在后门口站了一会儿看雾。夏师傅可以作证。值班前喝杯咖啡也有问题？"},{"id":"t_foot","q":"这鞋印是你的？","needs":["clue:c_deck2"],"a":"这是甲板部统一发的鞋，船长和我各一双，我天天穿，印子不奇怪。别人的脚是别人的事。"},{"id":"t_timer","q":"雾笛定时器的事？","needs":["clue:c_eng4","ask:he.t_timer"],"a":"检修卡是我提的。雾天手拉雾笛两只手都占着，我想有个备份，贺师傅帮着校的。别把一张卡当罪证。"}],"confronts":[{"clue":"c_din1","breaks":"t_watch","crack":true,"a":"他听完那段精确到秒的雾笛，手指在袖口捏紧了：“……没想到有人在录。好，我离开过驾驶台。但离开不等于杀人。”"},{"clue":"c_hall1","breaks":"t_horn","crack":true,"a":"他看着“23:08 – 23:34”，嘴角抽了一下：“这小东西居然自己记账。是自动档，我撒了谎。可你证明不了我去了哪。”"},{"clue":"c_deck2","breaks":"t_deck","a":"“同款鞋不止我一双。”他目光落在鞋印里的水珠和压着它的胶靴印上，“……印子比搜舱早。好，我下过甲板。可你分得出哪串是我的吗？”"},{"clue":"c_hall3","breaks":"t_know","a":"他整个人像被冻住了：“谁让你翻我的抽屉？照片里是我哥邵远洋。方启明不认得这张脸，我认得他。”"},{"clue":"c_cab2","a":"他看着那两道红圈，笑意没到眼底：“货主代表查船员的底，也算尽职。可惜他到死也没来问我一句。”"},{"clue":"c_din2","a":"他盯着剪报很久：“邵远洋……报道没漏一个字。可它漏了一件事：没人去那片海上给他们烧过香。”"}],"fallback":"这个我不清楚。没别的事，我还要回去看雷达。"},{"id":"he","name":"贺大勇","role":"“海燕号”轮机员","age":47,"look":{"skin":"brown","hair":"cap","hairColor":"black","glasses":"none","beard":"stubble","outfit":"jacket","mood":"stern"},"bio":"“海燕号”轮机员，在机舱干了二十年，嗓门大，一身柴油味。他说自己整晚守在机舱里。","demeanor":"粗声粗气，爱说“老子”，被问到痛处就梗着脖子。","topics":[{"id":"t_role","q":"机舱归你管？","a":"主机、发电机、舵机，全归我。老子干了二十年，没出过半点岔子，今晚这事跟机舱没关系。"},{"id":"t_where","q":"案发时你在机舱？","lie":true,"a":"一直在，没离开过。23点和23点半各巡一次，日志上白纸黑字，你自己去看，老子的活儿从来干净。","truth":"我在备用舵机舱睡着了，喝了二两酒。两行巡检是提前填的，后面那桶柴油是我偷放的，想卖给渔船。"},{"id":"t_know","q":"你认识方启明？","lie":true,"a":"不认识，名字都是上船才听说的。货主代表，坐头等舱的，跟我这种烧油的有什么交集？别往我身上扯。","truth":"认识。三年前在恒泰航运，是他签字开除了我，罪名卖油。我恨他，可我没碰他一根手指。"},{"id":"t_wrench","q":"那把扳手怎么回事？","needs":["clue:c_eng1"],"a":"E-14？十八点四十老夏借去砸冻鱼，一直没还，登记板上写着呢。他爱放哪儿放哪儿。"},{"id":"t_vic","q":"他死了你怎么想？","needs":["clue:c_eng3"],"a":"死了干净。你问我高不高兴，老子不装：高兴。可动手？我这把年纪，没了这份工还杀人，不想活了？"},{"id":"t_timer","q":"雾笛定时器呢？","lie":true,"needs":["clue:c_eng4"],"a":"那是例行检修，每季度都要过一遍，我签了就完事，没谁特别交代。一张卡你想问出什么？","truth":"下午大副来说怕手拉不及，想要个自动后手，让我校到120秒。我当他想夜里合眼偷懒，当人情办了，没写申请人。不知道他拿来干这个。"}],"confronts":[{"clue":"c_eng2","breaks":"t_where","a":"他脸涨红了：“谁让你翻老子的桶！”又泄了气，“行，我睡了，巡检是假的。偷油老子认，杀人不认！”"},{"clue":"c_cab2","breaks":"t_know","a":"他盯着名单上自己名字的叉，喷出一口粗气：“他倒还记得我。好，我认识他。可你拿这个说我杀他？”"},{"clue":"c_eng3","breaks":"t_know","a":"“谁让你开老子的柜子！”他伸手要夺又停住，“解雇书我留着，想有一天拍他脸上。就这样。”"},{"clue":"c_hall1","breaks":"t_timer","a":"他盯着“AUTO 23:08 · 停止 23:34”：“二十几分钟？他说备个后手，就为打瞌睡？”脸色灰了，“是大副让我弄的。老子是帮他，没想过别的。”"}],"fallback":"这玩意儿老子没见过，别拿来烦我。"},{"id":"xia","name":"夏福生","role":"“海燕号”厨师","age":52,"look":{"skin":"light","hair":"bald","hairColor":"grey","glasses":"none","beard":"none","outfit":"apron","mood":"worried"},"bio":"“海燕号”厨师兼杂工，圆脸，胆子小。他说自己整晚在厨房收拾，没离开过，也没怎么见过方先生。","demeanor":"絮絮叨叨，一紧张就搓围裙，爱先说“我可没……”","topics":[{"id":"t_role","q":"你在船上做什么？","a":"我就是个做饭的，一锅粥一碟小菜，伺候这几位祖宗。出了命案，我睡觉都要抱着锅盖了。"},{"id":"t_tea","q":"你去过3号舱吗？","lie":true,"a":"没有没有，我一直在厨房，3号舱那头我连脚都没往那边迈。夜宵之后我就没见过方先生，真的。","truth":"去了一次。23点05分送姜茶，他开门接了盘子，人好好的，脸色沉。我怕被当成最后见他的人，才咬死没去。"},{"id":"t_cold","q":"冷库里放什么？","lie":true,"a":"鱼、肉、青菜，满满当当，都是船公司的公家东西。冷库里冷得很，你要看随便看，不过别冻着了。","truth":"……还有五条外烟，是我私带上岛卖给码头工人的。老庄知道，没往上报。被查到要罚钱，我心虚，就没说。"},{"id":"t_wrench","q":"扳手是谁用的？","needs":["clue:c_eng1"],"a":"贺师傅那把？下午我借来砸冻鱼，用完随手搁在后门窗台上，想晚点还。后来就找不着了。"},{"id":"t_back","q":"晚上谁到过后门？","needs":["clue:c_kit2"],"a":"只有大副。二十二点半他来要咖啡，端着杯子在后门口站了好一阵，嘀咕什么“雾真好”。"},{"id":"t_late","q":"之后你做了什么？","a":"收拾锅碗，二十三点半给休息厅的汪老板送了碗醒酒汤。听到有人喊才知道出事，腿都软了。"}],"confronts":[{"clue":"c_kit1","breaks":"t_tea","a":"“……啊，写在板上了。”他围裙搓得更凶，“我是怕呀！我送茶时他还好好的，就是脸色沉，像在等人。我真没害他！”"},{"clue":"c_cab3","breaks":"t_tea","a":"他后退半步：“那是我端去的……进去时他还活着，说‘放那儿吧’，就把我关在门外了。”"},{"clue":"c_kit3","breaks":"t_cold","a":"“啊呀别……”他想挡又不敢，“就五条！老庄睁只眼闭只眼。就是烟，不是要紧东西，千万别写进报告！”"},{"clue":"c_cab1","a":"他一下捂住嘴：“E-14……是我借的那把！天爷，我的冰锤怎么会……我真的放在后门窗台上了！”"}],"fallback":"我可没碰过这个，真的，你别吓我。"},{"id":"wang","name":"汪志达","role":"珠宝批发商","age":49,"look":{"skin":"tan","hair":"slick","hairColor":"black","glasses":"none","beard":"none","outfit":"suit","acc":"pocketwatch","mood":"sly"},"bio":"珠宝批发商，受邀去白礁岛参加拍卖会，是这批货的潜在竞买人。他说夜宵一散就回舱睡了。","demeanor":"爱叫“兄弟”“老板”，笑里藏刀，喝了酒大舌头，被抓包就打哈哈。","topics":[{"id":"t_role","q":"你来岛上做什么？","a":"做了二十年珠宝批发，南洋金珠这种货一年就见一回。拍卖会请我，当然要去看看，哈哈。"},{"id":"t_night","q":"案发时你在哪？","lie":true,"a":"夜宵一散我就回舱睡了，白天赶路累坏了，一觉睡到被人喊起来。我可没出过舱门，老板。","truth":"我没睡，在休息厅喝闷酒，一直到23点40分以后。刚被方启明骂出来，窝火，又不想让人知道我求过他。"},{"id":"t_offer","q":"你和方启明谈过吗？","lie":true,"a":"没谈过，拍卖会上才打交道。货主代表拍卖前不见竞买人，这是行规，兄弟你不会不懂吧。","truth":"谈了。快23点我敲他的门，想私下收货，开价两千二百万。他骂我坏规矩，撵走了。可我没杀他，货没了我赚什么？"},{"id":"t_price","q":"你的上限是多少？","needs":["clue:c_din3"],"a":"上限三千万，底价两千五，我心里有数。私下谈能压到两千二。你拿这个说我杀人？可笑。"},{"id":"t_hear","q":"你听到什么动静？","a":"迷迷糊糊听见外头“咚”一声闷响，像重东西落甲板，二十三点二十分前后，我以为是浪。"},{"id":"t_who","q":"你觉得是谁干的？","a":"要我说，是船上懂货的人。夜宵时那个保险的和方先生在桌边小声吵，脸色难看，先查他。"}],"confronts":[{"clue":"c_din1","breaks":"t_night","a":"他听着录音里自己的咒骂，笑挂不住了：“嘿，兄弟，我喝多了爱自言自语。好吧，我没睡，在这儿喝了一晚上。”"},{"clue":"c_cab4","breaks":"t_offer","a":"“哎呀，这短信……”他尴尬地笑，“哪个竞买人不想拍前拿货？他骂我，我认；杀人？我图什么？”"},{"clue":"c_deck2","a":"“软底人字纹？”他抬脚晃晃，“兄弟，我穿四十码皮鞋。二十八公分得是个大个子吧？”"}],"fallback":"嗨，兄弟，这东西我不懂，别拿来吓唬我。"},{"id":"su","name":"苏晴","role":"《晨潮报》记者","age":31,"look":{"skin":"light","hair":"ponytail","hairColor":"black","glasses":"round","beard":"none","outfit":"jacket","acc":"scarf","mood":"tired"},"bio":"《晨潮报》记者，说自己去白礁岛做民宿专题。她整晚在休息厅写稿，桌上的录音笔一直开着。","demeanor":"语速快，爱追问，被刺到就反问“你们警察不也这样吗”。","topics":[{"id":"t_why","q":"你为什么上这班船？","lie":true,"a":"去白礁岛做民宿专题，海岛慢生活嘛。夜渡便宜，还能写点“雾中航行”的素材，一举两得。","truth":"我是冲方启明来的。我追海顺号案追了两年，听说他押运金珠，才订了这班船，想当面问他要个答案。"},{"id":"t_night","q":"案发时你在做什么？","lie":true,"a":"我在休息厅打字，一直没挪地方。录音笔就在桌上，雾笛、人声、杯子响，全录着，你可以放来听。","truth":"23点35分我离开了七八分钟，去敲他的门。门虚掩着，我看见他躺在地上……吓得跑回来，装作没发生过。"},{"id":"t_hai","q":"海顺号是怎么回事？","needs":["clue:c_din2"],"a":"三年前雾夜，渔船被货轮撞沉，四人遇难。我查到是恒泰7号，当晚的运营负责人方启明改过航行记录。"},{"id":"t_family","q":"遇难者家属呢？","needs":["clue:c_din2"],"a":"邵远洋有个亲弟弟，出事时在外海跑船。我怎么都找不到他，听说后来考了航海证，上了哪条船没人知道。"},{"id":"t_record","q":"录音笔为什么开着？","a":"职业习惯，也想录点雾笛声当片头。结果成了一晚上的“监控”。里面什么都有，你尽管听。"},{"id":"t_other","q":"你觉得谁可疑？","a":"保险那位，整晚魂不守舍，电话响了三回都不敢接。还有轮机员，一听说我是记者，脸一下就黑了。"}],"confronts":[{"clue":"c_din2","breaks":"t_why","a":"她叹了口气：“被你翻到了。我不是来写民宿的，我追了两年，就为今晚当面问他一句。他死了，我反成了最有动机的人。”"},{"clue":"c_cab1","breaks":"t_night","a":"她盯着那支“晨潮报”圆珠笔，咬了咬唇：“我的笔……我慌得没发现掉了。我只看了一眼，什么都没碰。说了你会信我吗？”"},{"clue":"c_din1","breaks":"t_night","a":"她听着键盘声在23:35断掉，七八分钟后才续上，苦笑：“这支笔连我停手都记着。好，我去敲了他的门，什么都没碰。”"},{"clue":"c_cab2","a":"“邵？”她凑近看，“我追的报道里，那个遇难的船长也姓邵。……我从没往这条线想过。”"},{"clue":"c_hall3","a":"她看着相片背面睁大了眼：“远洋，远帆……”她捂住嘴，“我找了他两年，他居然就在这条船上。”"}],"fallback":"这个跟我的稿子没关系。要采访我，先说清楚想问什么。"},{"id":"lin","name":"林小满","role":"独自出游的游客","age":24,"look":{"skin":"fair","hair":"bob","hairColor":"brown","glasses":"none","beard":"none","outfit":"hoodie","acc":"earrings","mood":"sad"},"bio":"刚失恋的年轻游客，一个人去白礁岛散心。她说自己晕船，吃了药，整晚蜷在休息厅沙发上睡觉。","demeanor":"爱用网络口头禅，“真的假的”“我人傻了”，紧张时语速飞快。","topics":[{"id":"t_role","q":"你来岛上做什么？","a":"请了年假去海岛散心。结果被甩、晕船、还撞上命案，我今年是不是该去庙里转转？人傻了。"},{"id":"t_night","q":"案发时你在哪？","lie":true,"a":"沙发上睡觉啊，晕船晕得想死，吃了药，整个人昏昏沉沉，什么都没听见，什么都没看见，真的。","truth":"我骗人了。我溜去右舷栏杆抽电子烟、躲着哭，大概23点10分到半。船上禁烟，我不敢说。"},{"id":"t_saw","q":"你在外面看到了什么？","needs":["clue:c_deck3","ask:lin.t_night"],"a":"行吧，你捡到我的烟了。我看见二十多米外有个穿白衬衫、肩上有杠杠的高个子，抱着方箱子往救生艇走。看不清脸。"},{"id":"t_height","q":"那人有多高？","needs":["ask:lin.t_saw"],"a":"比我高一个头吧，我一米六五。肩膀挺宽，走得很稳，一点不晃。……不是船长吧？他比我高不了多少。"},{"id":"t_sound","q":"你听见什么声音？","a":"雾笛“呜——”一直响，吵死了。我记得它有一阵特别准，每隔一会儿一声，像闹钟，后来又乱乱的。"},{"id":"t_who","q":"你怀疑谁？","a":"我哪知道啊。商人老喝酒，记者老盯着人，轮机员一脸凶相。大叔们都怪怪的，我不敢乱说。"}],"confronts":[{"clue":"c_deck3","breaks":"t_night","a":"她“啊”了一声想抢又缩回：“那是我的……行行行我出去了！我就是去哭的，不是小偷也不是凶手！”"},{"clue":"c_deck2","a":"“那串鞋印？”她歪头看，“我穿运动鞋，波浪花纹，不是人字纹。不信我脱鞋给你看。”"},{"clue":"c_cab1","a":"她听完现场描述脸一下白了：“我不敢看。我真的什么都没看到，只是想一个人emo一会儿。”"}],"fallback":"这个我真的不知道，救命，别问我。"},{"id":"gu","name":"谷明哲","role":"保险代理人","age":41,"look":{"skin":"light","hair":"sidepart","hairColor":"black","glasses":"rect","beard":"none","outfit":"suit","acc":"tie","mood":"worried"},"bio":"中泰保险货运险代理人，随船监督这批金珠。他是第一个发现方启明死亡的人，说是去核对封条。","demeanor":"客客气气，话里全是条款，紧张时反复推眼镜，爱说“按规定”。","topics":[{"id":"t_role","q":"你来船上做什么？","a":"我是中泰保险代理人，这批金珠由我们承保，保额两千八百万。按规定随船监督封条和押运。"},{"id":"t_rel","q":"你和方启明关系如何？","lie":true,"a":"很融洽啊，客户和代理人的关系，没有任何摩擦，他也很配合我们的条款要求，一切都是按规定办的。","truth":"不融洽。他要在到岸前解约。按第九条我要退佣金还要赔违约金，这个季度就完了。我晚上去求过他，吵得很凶。"},{"id":"t_last","q":"最后一次见他是？","lie":true,"a":"夜宵的时候。之后我就没再见过他，一直到23点48分我去找他，按规定核对封条，才发现出了事。","truth":"22点35分我去过他舱里，求他别解约，吵了十分钟。我走时他还好好的，冷笑说“随你便”。我怕被当成有动机的人。"},{"id":"t_find","q":"你怎么发现的？","a":"23点48分，我敲门没人应，一推就开了。他趴在地上，货箱不见了。我腿都软了，大喊着找船长。"},{"id":"t_seal","q":"封条是什么情况？","needs":["clue:c_deck1"],"a":"HT-0472，我们公司的封条，启运前我亲手打的，编号和单据对得上，现在还是完整的。"},{"id":"t_who","q":"你怀疑谁？","a":"汪老板吧，他想私下压价，谁都知道。还有那位记者，打听方先生很久了。船员我不敢说。"}],"confronts":[{"clue":"c_din4","breaks":"t_rel","a":"他推了推眼镜：“第九条……您连这个都看过了。对，我有动机。可货丢了我只会更惨，杀他图什么？”"},{"clue":"c_cab4","breaks":"t_last","a":"他看着那条“再考虑到明天”，肩膀塌了：“我去过他舱里，22点35分，吵了十分钟。走时他还好好的。”"},{"clue":"c_deck2","a":"“鞋印？”他低头看看自己的皮鞋，“我这双平底光面，哪来的人字纹。再说我穿42码。”"}],"fallback":"按规定，这个我不便评论，请出示相关条款。"}],"solution":{"culprit":"shao","method":{"q":"凶手怎样制造“案发时一直在驾驶台”的假象？","options":["趁夜宵散席的混乱溜进舱里杀人，再藏箱","让别的船员替自己守台，自己下去行凶","趁两声雾笛的空档，多次往返台和舱","把雾笛拨到自动档，趁机离岗行凶"],"correct":3},"motive":{"q":"凶手为什么杀人？","options":["亲人死于旧年撞船，死者压下真相","为那箱金珠铤而走险，想趁乱带走","死者发现他夹带违禁品，他为保差事灭口","死者毁了他的饭碗，他记恨多年泄愤"],"correct":0},"keyClues":["c_deck1","c_deck2","c_cab2","c_hall1","c_din1","c_din2"],"truth":["凶手是大副邵远帆，为兄报仇。三年前雾夜，渔船“海顺号”被货轮撞沉，船长邵远洋等四人遇难，运营负责人方启明改写记录、否认撞船。邵远洋是他亲哥。他主动调上白礁线，等的就是这样的浓雾。","抢劫是幌子：货箱藏在2号艇，铅封完好。汪志达想压价、又撒谎，最像贼；但“咚”声响起时，他正在休息厅咒骂，录音笔录着。","诡计是雾笛。他请贺大勇把自动档校到120秒，贺以为他想偷懒，不知情。23点08分他拨到自动，下甲板，用厨师遗落的扳手杀了方启明，藏好货箱，23点34分回台改回手动。","船长也不是：他回舱睡了，且他的鞋只有26厘米，林小满见到的高个子也“不是船长”。","其余人的谎各有隐情：汪志达醉酒，贺大勇偷柴油，谷明哲怕丢资格，苏晴追旧案，夏福生藏外烟，林小满躲着抽烟。"]}},{"id":"lastdish","title":"最后一道菜","tagline":"美食评论家执金匙尝下第一口，七分钟后倒地不起。","difficulty":2,"cover":"coverRestaurant","tone":"warm","brief":"今晚是金匙奖青年厨师大赛决赛夜，地点澜庭酒店宴会厅。20:05终局菜上桌，主评宋怀瑾执金匙尝下第一口，七分钟后捂着喉咙倒地，20:58不治。警方陈队长请你来：八个人个个说与己无关，个个又和死者有点瓜葛。酒店已封锁，主桌、后厨、酒窖、门厅、露台和办公室都向你开放。你21:30到场，甜香未散，金匙静静躺在桌上。","victim":{"name":"宋怀瑾","desc":"58岁，《食界》专栏作家，业内公认的“美食评论教父”，金匙奖主评兼组委会监事，以毒舌闻名。20:12在主桌倒地，20:58宣布不治。","look":{"skin":"light","hair":"sidepart","hairColor":"grey","glasses":"round","beard":"goatee","outfit":"suit","acc":"bow","mood":"neutral"}},"publicFacts":["决赛夜在澜庭酒店宴会厅；评审团是宋怀瑾（主评）、季雅芝、蒋德厚。","终局菜是选手韩大勇的“桂花酒酿炖蛋”；按传统，主评手执“金匙”第一个品尝。","医生初步判断宋怀瑾死于重度过敏反应；剩余菜品已被封存待检。","宋怀瑾重度花生过敏，记在《评委接待须知》里；组委会称三天前已撤下一切花生制品。","酒店监控只覆盖大堂与后厨走廊，宴会厅内没有摄像头。"],"relations":{"zhong":"组委会执行总监，和他合作五年","han":"三年前被他差评关店的决赛选手","fang":"冠名赞助商，出钱办这场比赛","ji":"前妻，离婚十年，仍同坐一桌","jian":"他的粉丝，受邀来直播的博主","he":"酒店侍酒师，管着放金匙的保险柜","qin":"跟了三年的私人助理，管饮食用药","jiang":"同桌评委，斗了三十年嘴的老对手"},"links":[{"a":"ji","b":"jiang","text":"同坐评审席的老同行"},{"a":"fang","b":"zhong","text":"一个出赞助款，一个申请宣传费"},{"a":"zhong","b":"he","text":"各持一把金匙保险柜的钥匙"}],"deathReport":{"time":"约 20:10–21:00（20:58 宣布不治）","cause":"重度过敏反应，引发过敏性休克","scene":"宋怀瑾在主桌尝下第一口后捂喉倒地，同桌呼救；保健员 20:14 赶到，没有备肾上腺素。","loc":"dining","notes":["口唇与面部明显肿胀，喉头水肿","身上未见外伤，无搏斗痕迹","剩余菜品已封存待检"]},"timeline":[{"t":"18:30","text":"晚宴开席，评委与来宾入席。"},{"t":"19:40","text":"后厨巡礼开始，持续约十五分钟。"},{"t":"20:05","text":"终局菜上桌，宋怀瑾执金匙尝下第一口。"},{"t":"20:12","text":"宋怀瑾捂住喉咙倒地，同桌呼救。"},{"t":"20:14","text":"驻场保健员赶到，没有备肾上腺素；120已接到报警。"},{"t":"20:31","text":"救护车到达；20:58宣布抢救无效。"}],"budget":{"search":12,"ask":30},"locations":[{"id":"dining","name":"宴会厅主桌","scene":"dining","desc":"二楼宴会厅的圆形主桌，餐具没撤，椅子歪在一边，空气里残留着桂花与酒酿的甜香。","clues":[{"id":"c_din1","title":"金匙与锦盒","text":"蓝丝绒锦盒里的金匙，勺面有一层油光，凑近有烘炒过的坚果香。同桌另两位评委用的是普通银勺。"},{"id":"c_din2","title":"椅脚的笔与小包","text":"椅脚旁落着一支灰色注射笔，印着“TRAINER”，笔头是平的，没有针孔。椅背小包里只有一张过敏急救卡。"},{"id":"c_din3","title":"直播回放","text":"回放19:44：一名深色西装、盘发、挂红挂绳的女士蹲在宋的座位边，手伸向小包，约一分钟，19:46离开。19:47蒋德厚走回座位。"}]},{"id":"kitchen","name":"后厨与备餐间","scene":"kitchen","desc":"酒店二楼后厨，灶台还有余温，墙上贴着今晚的菜单和各类清单。","clues":[{"id":"c_kit4","title":"垃圾桶里的小瓶","text":"出菜口垃圾桶里压着一只无盖小瓶，螺纹口外径约两厘米，瓶壁挂油，有烘炒坚果香。韩大勇的灶位隔着三个工位。"},{"id":"c_kit1","title":"留样与油品单","text":"蛋羹留样的试纸条显示阴性。油品清单上只有菜籽油和橄榄油，花生油三天前已撤出，有签字。"},{"id":"c_kit2","title":"传菜单","text":"传菜单：“20:05主桌4盅，另附金匙1把，宋位专用。”背面领班手记：“19:08收金匙盒，盒口缠透明胶带，有烘香，当是桂花。锁进保温柜。”"},{"id":"c_kit3","title":"储物柜里的剪报","text":"韩大勇的更衣柜里贴着宋怀瑾三年前的差评剪报，“不必再开下去了”一行被红笔画了三道。"}]},{"id":"cellar","name":"酒窖","scene":"cellar","desc":"地下恒温酒窖，酒架排成长廊，尽头嵌着一只双锁保险柜，存放金匙和名酒。","clues":[{"id":"c_cel1","title":"保险柜登记簿","text":"登记簿：“18:30 贺明 擦净金匙，封盒入柜（骑缝章封条）”“19:05 钟岚 取金匙，仪式用”。钥匙两把，酒窖和组委会各一。"},{"id":"c_cel2","title":"暗格里的私账","text":"酒架后暗格里有本小账本，记着：“19:00 露台 方总 老年份红 4800 现金”。字迹是贺明的。"},{"id":"c_cel3","title":"水槽边的瓶盖","text":"水槽边落着一枚小塑料瓶盖，内径约两厘米，盖内有油渍和烘炒香。台面有块水痕，像是用湿布抹过。"}]},{"id":"hall","name":"门厅与衣帽间","scene":"hall","desc":"二楼门厅，设有签到桌、前台值班席和衣帽间，地面带着几行湿脚印。","clues":[{"id":"c_hall1","title":"后厨巡礼签到表","text":"19:40巡礼签到表：宋、季、韩、方、简都签了，蒋德厚、秦川空着。组委会钟岚的名字后手写“留场，核对颁奖流程”。"},{"id":"c_hall2","title":"外套口袋的纸条","text":"宋的深灰大衣口袋里有张便笺，女人的字迹：“笔带好，别逞强，也别又跟人吵。——雅”"},{"id":"c_hall3","title":"门厅值班本","text":"值班本：“17:28 厨师韩大勇求见，休息室，17:52离开”“19:36 助理秦川出门接电话，19:52返回”。宴会厅内无监控。"}]},{"id":"garden","name":"露台花园","scene":"garden","desc":"宴会厅外的露台花园，夜里下过雨，石板湿亮，长椅和花盆沿着围栏排开。","clues":[{"id":"c_gar1","title":"碎成片的撤资函","text":"花盆泥土里埋着撕碎的信，拼起来是澜庭酒店终止冠名赞助的函，落款打印“方鸿业”，没有签名，日期是今天。"},{"id":"c_gar2","title":"花盆后的红酒","text":"花盆后塞着一瓶贴酒窖编号条的红酒，瓶下压着收条：“19:02 老年份红 4800，当面点清——贺”。"},{"id":"c_gar3","title":"粉丝签名本","text":"长椅上的粉红签名本，扉页是宋给小满的题字。页脚小字：“19:40巡礼，手机留支架上别关，直播不能断。”"}]},{"id":"study","name":"组委会办公室","scene":"study","desc":"宴会厅旁临时腾出的办公室，桌上堆着流程表和奖杯盒。","clues":[{"id":"c_stu1","title":"废纸篓里的快递","text":"废纸篓里的快递面单：收件“金匙奖组委会 Z 收”，电话尾号6082，品名“过敏急救笔演示训练套装（无针无药）”，10月9日下单。"},{"id":"c_stu2","title":"带批注的发票","text":"对账单上“场地宣传费380,000元”出现两次，批准人都是钟岚。页边钢笔字：“重复。颁奖前先当面谈。不谈，致辞里说。”"},{"id":"c_stu3","title":"评委接待须知","text":"须知里宋的一页：“重度花生过敏，随身带肾上腺素笔。”“已知悉”处签着钟岚、秦川。联络表：执行总监钟岚，尾号6082。"}]}],"suspects":[{"id":"zhong","name":"钟岚","role":"赛事执行总监","age":41,"look":{"skin":"light","hair":"bun","hairColor":"black","glasses":"none","beard":"none","outfit":"suit","acc":"earrings","mood":"smile"},"bio":"金匙奖执行总监，统筹全场流程。宋倒下时她就在主桌旁待命，第一个叫了救护车，看上去最悲痛。","demeanor":"温和干练，爱说“您放心”；被追问时先反问一句。","topics":[{"id":"t_role","q":"你负责什么？","a":"流程、嘉宾、评委接待，还有金匙仪式。宋老师是主评，也是监事，合作五年了。今天这样……我手到现在还是凉的。"},{"id":"t_tour","q":"巡礼时你在哪？","lie":true,"a":"跟着大家去的呀。一大队人挤在后厨，听韩师傅讲蛋羹。您放心，问谁都行，我全程都在。","truth":"我没去。写“留场”，是想等人走空。我走到宋老师座位边，蹲下，把他小包里的笔换了。我只有那几分钟。"},{"id":"t_spoon","q":"金匙怎么送的？","lie":true,"a":"十九点零五分我从酒窖取出，零八分交给传菜领班，盒子我连扣都没开过。仪式用的东西，哪敢乱动。","truth":"我开了盒子。在水槽边把花生油抹在勺面，再用胶带缠回原样。空瓶丢进出菜口垃圾桶，让后厨去背。金匙只有他一人用。"},{"id":"t_pen","q":"训练笔是你订的？","lie":true,"needs":["clue:c_stu1"],"a":"办公室买的都是办公用品，急救的东西我从没订过。大概是哪个同事网购，快递丢我纸篓里了。","truth":"是我订的。真笔换下来，我扔进了后院垃圾箱。我要他到那一刻，手里是一支按不出东西的笔。"},{"id":"t_money","q":"那38万怎么回事？","lie":true,"needs":["clue:c_stu2"],"a":"发票早处理好了，宋老师只是例行问问，会后坐下来说清楚就行。没什么好谈的，更谈不上什么威胁。","truth":"我把钱挪去给母亲还手术费和欠债，发票开了两遍。他要在致辞里点我的名，我五年的心血，一句话就没了。"},{"id":"t_wine","q":"方总买酒的事？","needs":["ask:fang.t_wine","ask:he.t_call"],"a":"我提过一句。方总被宋老师堵着问发票，脸都青了，我劝他去露台透口气，顺口说贺明手里有瓶好年份。酒窖这点事，我一直睁只眼闭只眼。"}],"confronts":[{"clue":"c_hall1","breaks":"t_tour","a":"她低头看着那行字，停了一下。“是我写的。……说去了巡礼，是我记混了，当时太乱。”笑还挂着，只是不稳了。"},{"clue":"c_din3","breaks":"t_tour","crack":true,"a":"她盯着回放里蹲下的侧影，很久没出声。“红绳，组委会和酒店管理层都戴……可这身衣服，十九点四十四分。”她吸了口气，“我认。”"},{"clue":"c_din1","breaks":"t_spoon","crack":true,"a":"“油……”她轻声重复，手指绞着工牌绳。“金匙每年都擦得干干净净，怎么会——”她闭上眼，“这味道我熟。你们总会闻到。”"},{"clue":"c_kit4","a":"她看了小瓶一眼，目光很快滑开。“后厨的垃圾，跟我有什么关系。”停了半拍，“花生油不是早撤干净了吗。”"},{"clue":"c_kit2","breaks":"t_spoon","a":"“胶带……”她的手指在桌沿敲了两下。“领班记错了吧，我送去时盒子是原样的。”没人接话，她自己先把视线挪向窗外。"},{"clue":"c_cel1","a":"“登记簿是我的字，十九点零五分，没错。”她抬了抬下巴，“取出来就是取出来，我没打开过。”"},{"clue":"c_cel3","breaks":"t_spoon","a":"她的视线落在瓶盖上，嘴唇动了动。“我在水槽边洗过手，也许是谁掉的。”这话又轻又快，连她自己听着都不信。"},{"clue":"c_stu1","breaks":"t_pen","crack":true,"a":"“Z……”她把面单看了一遍又一遍，肩膀慢慢垮下来。“尾号是我的。我以为纸篓里的东西，早上保洁会收走。”"},{"clue":"c_din2","breaks":"t_pen","a":"“训练笔……”她像被烫了一下，“他倒下时，我看着他一遍一遍地按。”手捂住嘴，“我就站在旁边，一句话都没说。”"},{"clue":"c_stu2","breaks":"t_money","a":"她看着蓝黑钢笔字，苦笑出声。“不谈，致辞里说。他一向说到做到。”抬头时眼里全是血丝，“我妈的手术等不了。”"}],"fallback":"您放心，这件事我没什么好补充的，需要材料我让人送来。"},{"id":"han","name":"韩大勇","role":"决赛选手·主厨","age":45,"look":{"skin":"tan","hair":"cap","hairColor":"black","glasses":"none","beard":"stubble","outfit":"apron","acc":"badge","mood":"stern"},"bio":"决赛选手，终局菜“桂花酒酿炖蛋”主理人。三年前他的老店因宋的差评关门。当晚主要在后厨。","demeanor":"嗓门大、直来直去，激动时爱拍灶台。","topics":[{"id":"t_role","q":"你的终局菜？","a":"桂花酒酿炖蛋。蛋蒸得像凝住的月光，桂花是老家带来的。练了两年，就想让人知道韩记没死。"},{"id":"t_met","q":"赛前见过宋吗？","lie":true,"a":"没有。我一个进决赛的厨子，躲评委都来不及，哪敢去找他。评委休息室的门，我走过都绕着。","truth":"见过。下午五点半我去求他这回公平点。他回我一句“你的汤，还是老样子”，我就炸了，拍桌说“你再毁我一次，我跟你没完”。只是吼，没动手。"},{"id":"t_grudge","q":"你恨他吗？","a":"恨过。他写“灵魂已死”，我店里客人一天比一天少，半年就关门。可我今晚是来拿冠军的，杀了他，我有什么脸站在这儿？"},{"id":"t_dish","q":"菜里有花生吗？","a":"没有！钟总监三天前就通知花生全撤，我酱料都重新备的，每步助手都盯着。要验尽管验。"},{"id":"t_tour","q":"巡礼时你在做什么？","needs":["clue:c_hall1"],"a":"我带队讲解，十九点四十讲到五十五，一圈人围着灶台，方总还拉我合影。要对时间，问他们。"},{"id":"t_zhong","q":"巡礼时钟岚在吗？","needs":["clue:c_hall1"],"a":"没有。我带队走的时候她没跟上来，我还纳闷。她平时最爱跟在评委后头，今晚居然没影。"},{"id":"t_bin","q":"出菜口的小瓶？","needs":["clue:c_kit4"],"a":"什么瓶？我灶台离那桶隔着三个人，出菜口谁都往里扔东西。我这儿一滴花生油也没有，闻我的锅去。"}],"confronts":[{"clue":"c_hall3","breaks":"t_met","a":"他盯着值班本上自己的名字，牙咬得咯吱响。“行，我去过。”一拳砸在灶台上，“我是去求他，不是去杀他！”"},{"clue":"c_kit3","a":"他脸色变了。“你连我的柜子都翻。”过了会儿苦笑，“我留着，天天看，咽不下这口气。可气归气，杀人是两码事。”"},{"clue":"c_kit1","a":"“阴性。”他吐出一口长气，“我就说我的菜没问题。”随后又愣住，“那东西是怎么进他嘴里的？”"},{"clue":"c_kit4","a":"他捏着小瓶转了转。“这不是我厨房的，我的油都是大桶装。”抬头瞪你，“有人把它扔在我眼皮底下，是想让我背锅？”"},{"clue":"c_din1","a":"他凑近勺面闻了闻。“这味道不是我厨房里的。”猛地抬头，“金匙是组委会给的，我碰都没碰过！”"}],"fallback":"这玩意儿跟我有啥关系？我就是个做菜的。"},{"id":"fang","name":"方鸿业","role":"冠名赞助商","age":57,"look":{"skin":"light","hair":"slick","hairColor":"grey","glasses":"rect","beard":"none","outfit":"suit","acc":"tie","mood":"smirk"},"bio":"澜庭酒店集团董事长，金匙奖冠名赞助商。当晚坐贵宾席，与评委席隔着两桌，主要在应酬各路嘉宾。","demeanor":"商人腔，爱说“我很忙”，被戳到就拔高嗓门。","topics":[{"id":"t_role","q":"为何赞助金匙奖？","a":"做品牌。五年投了四百多万，酒店名字跟着一起红。今年又追加一笔宣传费，是钟总监申请的。花钱不怕，怕花得糊涂。"},{"id":"t_talk","q":"和宋说过话吗？","lie":true,"a":"没有。他是评委，我是赞助商，要避嫌。一整晚连他的杯子都没碰过，更别说说话，我跟他没交集。","truth":"说过。十八点五十，他在门厅拿着发票问那三十八万是不是花在了场地上。他说颁奖前让钟岚自己说清楚，不然他替她说。我火了，说那我撤资。"},{"id":"t_where","q":"19:40你在哪？","a":"后厨巡礼，跟着去的。韩师傅讲蛋羹，我拍了几张，还合了影。自己酒店办的活动，怎么能不去？"},{"id":"t_pull","q":"真想撤资吗？","needs":["clue:c_gar1"],"a":"信写了，没发，撕了，是气话。金匙奖办了五年，我不想它砸在一笔烂账上。现在人没了，撤不撤也没意义了。"},{"id":"t_wine","q":"酒怎么买的？","needs":["clue:c_gar2"],"a":"吵完我正在火头上，钟总监过来劝我去露台透气，说酒窖贺明手里有瓶好年份，私下能拿。我就打了酒窖电话。她一向周到，我没多想。"},{"id":"t_zhong","q":"你看钟岚如何？","needs":["clue:c_stu2"],"a":"能力一流，五年来大小事一个人扛。可那笔钱……我后悔当初没多问一句。她人缘好，所以谁也没细查。"}],"confronts":[{"clue":"c_gar1","breaks":"t_talk","a":"他盯着拼好的信纸，哼了一声，又泄了气。“……好吧，吵过。信是我写的，写完就撕了。我嘴硬，心里有数。”"},{"clue":"c_stu2","a":"他看了一遍对账单。“同一笔钱开了两次？”倒吸一口凉气，“我只付了一次，另一次是谁的？得回去查。”"},{"clue":"c_gar2","a":"“酒是我买的，”他摆手，“十九点钟他送到露台，讲了一刻钟年份，我就站着听。跟命案有什么关系？酒店内部规矩，别往外传。”"}],"fallback":"这个我不清楚。我很忙，没空盯着每件小事。"},{"id":"ji","name":"季雅芝","role":"评委·美食作家","age":54,"look":{"skin":"light","hair":"bob","hairColor":"silver","glasses":"round","beard":"none","outfit":"dress","acc":"necklace","mood":"sad"},"bio":"评委，著名美食作家，宋怀瑾的前妻，离婚十年。当晚与宋同坐主桌，宋倒下时就在他身边。","demeanor":"说话慢，爱用比喻，提到前夫先停顿，再冷冷补一句。","topics":[{"id":"t_role","q":"你们什么关系？","a":"前夫。二十年婚姻，离了十年。这一行太小，躲不开，每年还坐同一张桌子，互相挑刺，倒像老搭档。"},{"id":"t_relation","q":"离婚后还联系？","lie":true,"a":"除了评审的场合，没有。十年没打过一个私人电话。我们早就是两条河，不往一处流了。谁还惦记谁呢。","truth":"有。他孤身一人，我是他的紧急联系人，每月至少一通电话，每年冬天提醒他换笔。嘴上说不联系，是怕人觉得我还放不下他。"},{"id":"t_will","q":"听说他的遗产……","needs":["clue:c_hall2"],"a":"律师说，老房子和版权都留给我了。我哭了。你们怀疑我，我懂。可我要是为钱，十年前离婚就拿了，何必等到今天？"},{"id":"t_tour","q":"巡礼时你在哪？","needs":["clue:c_hall1"],"a":"跟着队走的。宋走在我前面半步，一路挑韩师傅灶台的毛病。我们是一起回来的，大概五十五分。"},{"id":"t_dish","q":"蛋羹你吃了吗？","needs":["clue:c_kit1"],"a":"吃了，温润干净，真的好。我和蒋老都吃了，没事。我们用普通银勺，只有他一人用金匙。所以我不信是菜的问题。"},{"id":"t_pen","q":"那支笔呢？","needs":["clue:c_din2"],"a":"他摸出笔往大腿上按，咔哒，咔哒，咔哒，什么也没有。那支笔是去年冬天换的新的，他不会弄错。"}],"confronts":[{"clue":"c_hall2","breaks":"t_relation","a":"她接过便笺，指尖发抖。“我的字。我撒谎了。他去哪儿都忘带东西，我就是见不得他一个人。”她别过脸，眼泪掉了下来。"},{"clue":"c_din2","a":"她盯着那支灰笔，脸色倏地白了。“这不是他的笔。他的是白色保险帽。谁，是谁换了它？”声音抖得站不稳。"},{"clue":"c_stu3","a":"她看了一眼“已知悉”下的签名，冷笑。“写得这么清楚，还能出事。看来有些人是看懂了的。”"},{"clue":"c_stu2","a":"她盯着“致辞里说”几个字，慢慢点头。“他就是认死理，不留余地。”又轻声补一句：“这样的人，会有人受不了。”"}],"fallback":"这个我帮不上忙。我只想知道，是谁把他变成了这样。"},{"id":"jian","name":"简小满","role":"美食博主","age":24,"look":{"skin":"light","hair":"ponytail","hairColor":"brown","glasses":"none","beard":"none","outfit":"hoodie","acc":"headset","mood":"worried"},"bio":"百万粉丝的美食博主，受邀坐媒体席，当晚全程开直播，同时在线两万多人。宋怀瑾是她的偶像。","demeanor":"语速快，爱说“哇”“真的假的”，紧张时口头禅“我发誓”。","topics":[{"id":"t_role","q":"你来做什么？","a":"直播啊！决赛夜同时在线两万多人。我还想请宋老师讲讲他的第一碗面。结果……我发誓，我没想过会这样。"},{"id":"t_fan","q":"你和宋熟吗？","a":"我是他的小迷妹！下午他在休息室门口给我签名，写了“好好吃饭，别只好好拍”，我感动得差点哭。他是真的好人。"},{"id":"t_live","q":"直播一直你盯着？","lie":true,"a":"当然！我全程守在机位旁，没离开过。我发誓，直播间每一帧我都亲眼看着，一点岔子都没有。","truth":"没有……巡礼时我把手机留在支架上继续开着，自己跟去了后厨。酒店规定后厨不许拍，我怕被抓，就没说。我发誓，这跟命案没关系。"},{"id":"t_heard","q":"听到过争吵吗？","a":"有！下午五点半，休息室门口，我听见韩大厨拍桌子，说“你再毁我一次，我跟你没完”。吓死我了，赶紧溜了。"},{"id":"t_stream","q":"回放里的女士？","needs":["clue:c_din3"],"a":"只有背影，看不清脸。红挂绳是组委会和酒店管理层的，我们媒体是蓝色。哇，我的直播居然拍到这个，手都在抖。"},{"id":"t_book","q":"这本签名本？","needs":["clue:c_gar3"],"a":"是我的！巡礼完我去露台透气，大概掉那儿了。后面是我想问宋老师的问题，一个都没来得及问……"}],"confronts":[{"clue":"c_din3","breaks":"t_live","a":"她小声叫起来：“被拍到了！”缩缩脖子，“是，我走了，手机留着开着。后厨我就待了十分钟，别告诉酒店。”"},{"clue":"c_hall1","a":"“我签名了！”她指着自己那行，“我真的去了。可是我的手机……哎呀，反正我去了。”越说越小声，耳朵都红了。"},{"clue":"c_gar3","a":"“我的本子！”她眼睛一亮又暗下去，“宋老师写的字，我舍不得擦。”把本子抱在胸口，眼泪啪嗒掉下来。"},{"clue":"c_kit3","a":"“韩大厨的剪报……”她捂住嘴，“他今天抱着蛋盅手都在抖，我看见了。不像会下手的人，我发誓。”"}],"fallback":"啊？这个我真没看见。我发誓，知道我第一个告诉你。"},{"id":"he","name":"贺明","role":"侍酒师","age":32,"look":{"skin":"light","hair":"sidepart","hairColor":"brown","glasses":"none","beard":"none","outfit":"vest","acc":"bow","mood":"neutral"},"bio":"澜庭酒店侍酒师，看管酒窖和保险柜里的金匙。当晚大部分时间在酒窖当值，据说从未离岗。","demeanor":"讲究，轻声细语，爱先报时间，被问到钱会擦手。","topics":[{"id":"t_role","q":"你负责什么？","a":"酒窖里所有的酒和仪式器具。金匙每年只在颁奖夜用一次，平时锁在保险柜里，我一个月擦它两回。"},{"id":"t_vault","q":"谁能开保险柜？","a":"两把钥匙，我一把，组委会一把。每次取放都要在登记簿上签字。十八点三十，我亲手擦净金匙、封盒入柜。"},{"id":"t_stay","q":"开席后离开过吗？","lie":true,"a":"没有。金匙是我的责任，我连洗手间都不敢去。十八点三十封盒之后，我一直守在酒窖，没人进来过。","truth":"离开过。十八点五十五分，方总约我送一瓶老年份红酒到露台，现金交易，违反规定。十九点十五分我才回酒窖。我怕丢饭碗才撒谎，那二十分钟我什么也没看到。"},{"id":"t_seal","q":"金匙盒怎么封？","needs":["clue:c_cel1"],"a":"骑缝章封条，盖我的章，一撕就破。章就在我口袋里。拆封只能撕条，想原样复原，很难，几乎做不到。"},{"id":"t_call","q":"谁让你离开的？","needs":["clue:c_gar2"],"a":"方总来电话，说钟总监提过我手上有瓶好年份红。我不放心。几分钟后钟总监也来电话，说十九点零五分她亲自取金匙，登记自己签，叫我只管去。"},{"id":"t_log","q":"19:05谁取的？","needs":["clue:c_cel1"],"a":"登记簿上是钟总监的字。我十九点十五分回酒窖，柜子锁好，簿子也签好了。她有钥匙，名正言顺，我没多想。"}],"confronts":[{"clue":"c_gar2","breaks":"t_stay","a":"他看着酒瓶和收条，嘴角抽了抽。“……是我的字。十八点五十五分出去过，二十分钟。只是卖了瓶酒。”一边说一边擦手。"},{"clue":"c_cel2","breaks":"t_stay","a":"他看到暗格被翻开，脸一下白了。“私卖酒要被开除的。可我发誓，走开那二十分钟，只是送酒。”"},{"clue":"c_kit2","a":"他眉头一拧。“胶带？我封的是骑缝章条，从不用胶带。这盒子在我封好之后被人开过，才缠的胶带。不是我，我一直在露台。”"},{"clue":"c_cel1","a":"“就是这两行。”他指着登记簿，“十八点三十我，十九点零五钟总监，钥匙我和她各一把。”说到“我和她”，他自己顿了一下。"},{"clue":"c_cel3","a":"他拿起瓶盖闻了闻。“花生味的油？酒窖里怎么会有。我绝对没带进来，我连花生都不吃。”"}],"fallback":"这个……不是我管的范围，我一无所知。"},{"id":"qin","name":"秦川","role":"宋怀瑾助理","age":28,"look":{"skin":"light","hair":"short","hairColor":"black","glasses":"rect","beard":"none","outfit":"shirt","acc":"badge","mood":"tired"},"bio":"宋怀瑾的私人助理，跟了三年，管行程、饮食和用药。当晚坐在宋的后排，宋倒下时第一个冲过去。","demeanor":"语速快，条理清楚，被问私事爱低头看手机。","topics":[{"id":"t_role","q":"你替他做什么？","a":"行程、稿件、饮食，还有药。他过敏又健忘，细节都得我记。三年了，他想吃甜还是咸，我都猜得到。"},{"id":"t_where","q":"19:40你在哪？","lie":true,"a":"一直在宴会厅，坐宋老师后排。他去巡礼，我也跟在后面，寸步不离。助理的本分就是这样。","truth":"我不在。十九点三十六分我出门接了个猎头电话，宋老师下午说年底不续约，我得找后路。十九点五十二分才回来。怕传出去毁了名声，才撒谎。"},{"id":"t_pen","q":"他的药谁管？","a":"我管。下午五点我检查过他的肾上腺素笔：白色保险帽，药液澄清，效期也对，放进他的牛皮小包。那时它是真的。"},{"id":"t_fired","q":"他对你好吗？","a":"他骂人出了名。今天下午说合同年底不续，还说我“记不住该记的事”。我气了一下午。可那是份工，不是仇，我不会拿人命去赌。"},{"id":"t_ask","q":"谁打听过他过敏？","a":"有。上周钟总监在群里问过宋老师过敏的具体情况，说要报酒店备案。我把须知上的都发给她了。"},{"id":"t_seen","q":"包里的笔你认得？","needs":["clue:c_din2"],"a":"这支灰色的？不对，我放的是白色保险帽的真笔。这支印着TRAINER，我没见过。一定有人动过那个包。"}],"confronts":[{"clue":"c_hall3","breaks":"t_where","a":"他盯着值班本，手机在掌心亮了又灭。“……好吧，我出去了十六分钟。我就想给自己找个出路，哪想到偏是那十六分钟。”"},{"clue":"c_hall1","a":"“我那栏是空的。”他自嘲，“我不是去巡礼，是在门外接电话。早知道，宁可不接。”眼眶红了。"},{"clue":"c_din3","a":"他看回放，脸色越来越难看。“蹲在他座位边，手伸向包。”攥紧拳头，“那是我的位置，我的活。我才走开十六分钟。”"}],"fallback":"这个我不清楚，我只记得和宋老师有关的事。"},{"id":"jiang","name":"蒋德厚","role":"评委·餐饮耆宿","age":68,"look":{"skin":"light","hair":"bald","hairColor":"white","glasses":"round","beard":"mustache","outfit":"jacket","acc":"pocketwatch","mood":"smile"},"bio":"评委，三十年老饕、餐饮界前辈，与宋斗了三十年嘴。当晚同坐主桌，坐在宋的右手边，耳朵有点背。","demeanor":"慢悠悠，爱讲“想当年”，耳朵偶尔“背”。","topics":[{"id":"t_role","q":"评审多少年了？","a":"三十一年了！想当年，一碗面吃一口，就知道师傅哪年入的行。现在年轻人手艺进步，可那股“气”，差了点。"},{"id":"t_tour","q":"你去巡礼了吗？","lie":true,"a":"去了去了！从头到尾，韩师傅一锅一锅炒的锅气，我现在还记得。这个年纪，哪能错过后厨？","truth":"没去。膀胱不好，十九点四十我就去了洗手间，出来在走廊歇了会儿，不好意思说。十九点四十七分才回座。老了就是这样。"},{"id":"t_rival","q":"你和宋如何？","a":"老对手，他骂我守旧，我骂他浮夸。他走了，我才发现没人跟我吵架了。昨天他还说要请我吃老面馆，这个老东西。"},{"id":"t_saw","q":"那段时间主桌边？","needs":["clue:c_hall1"],"a":"我回座时，看见一个穿深色西装、盘头发、脖子挂红绳牌的女人从桌边走开，走得挺快。我当是酒店的人，没在意。"},{"id":"t_dish","q":"蛋羹你吃了吗？","needs":["clue:c_kit1"],"a":"吃了！舀了一大勺，好得很。我用普通银勺，金匙是宋怀瑾的专利，每年只有他碰。吃完什么事也没有。"},{"id":"t_bag","q":"他的小包？","needs":["clue:c_din2"],"a":"我回座时，他椅背上的包拉链是敞着的。我还想，这老宋丢三落四，包都不拉好。现在想想……唉。"}],"confronts":[{"clue":"c_hall1","breaks":"t_tour","a":"他看着自己那行空白，摸了摸光头。“……好吧，我没去。别笑话。不过回来时，我真看到了人。”"},{"clue":"c_din3","breaks":"t_tour","a":"他凑近屏幕眯眼看了半天。“白头发的是我吧？我从洗手间回来，没去后厨。那个蹲着的女人，我走回来时她刚起身走。”"},{"clue":"c_din2","a":"他摇摇头。“他的真笔我见过，是白的，这支不是。”叹气，“老宋啊，到最后连支笔都没守住。”"}],"fallback":"这个我没留意，人老了，记性不如从前。"}],"solution":{"culprit":"zhong","method":{"q":"凶手怎么让宋怀瑾丧命？","options":["在蛋羹里混入花生油，再把他包里的急救笔取走藏起","在他专用的金匙上抹花生油，再把包里急救笔换成无药训练笔","趁看守离岗只动了金匙，急救笔没被动过，是他自己按错","把致敏物涂在他的酒杯和餐巾上，再拖延旁人替他注射"],"correct":1},"motive":{"q":"为什么杀人？","options":["死者三年前一篇评论毁了凶手的店，积怨在决赛夜爆发","死者追问赞助费用去向，凶手怕赞助撤走、赛事垮掉","死者查出重复开票、挪用三十八万，要在致辞里揭发","死者准备年底终止与凶手的合作，凶手想保住前程"],"correct":2},"keyClues":["c_din1","c_din2","c_kit1","c_hall1","c_stu1","c_stu2"],"truth":["凶手是执行总监钟岚。杀招有两层：一是金匙上的花生油，二是被换成训练笔的肾上腺素笔。菜本身没问题。","先排除后厨：留样阴性，同吃蛋羹的季、蒋无恙。出菜口的空瓶没有盖，盖子在酒窖水槽边，瓶子是从酒窖带去栽赃韩大勇的。","再看金匙：贺明18:30用章条封盒，19:05只有钟岚取走，领班收到的却是胶带盒。方、贺在露台私下买酒，都是钟岚劝去的，酒窖空档是她造的。","再看笔：19:44直播回放拍到红挂绳、盘发女士蹲在宋的座位边，蒋德厚19:47撞见她走开。签到表上只有钟岚“留场”。她用网购训练笔换走真笔。","动机：钟岚把三十八万宣传费重复开票，挪去还母亲手术费。宋要在致辞里揭发，她让他永远开不了口。其他人的谎，只是各自的小秘密。"]}},{"id":"library","title":"闭馆之后","tagline":"百年馆庆的酒会正热闹，三楼善本室里少了一册宋刻，多了一具尸体。","difficulty":2,"cover":"coverLibrary","tone":"cold","brief":"十月十五日夜，怀德图书馆百年馆庆酒会刚散，三楼传来噩耗：古籍部主任方敬之倒在善本室里，一册宋刻不见了。那间屋的门会自动落锁，外人进门要刷卡。校方不想让这事上新闻，悄悄请你来查个清楚。八个人被留在楼里等你问话，每个人都有点不想说的事。三楼走廊的监控正在检修，线索只能靠你自己找出来。你有十二次搜证，三十次发问。","victim":{"name":"方敬之","desc":"61岁，古籍部主任，在馆里工作三十多年。倒在三楼善本室长桌旁，后脑遭重击，身旁有沾血的黄铜镇尺。","look":{"skin":"light","hair":"short","hairColor":"grey","glasses":"round","beard":"none","outfit":"vest","mood":"neutral"}},"relations":{"wen":"同门师弟，如今的文学院院长","kang":"捐了八百万的校友，常与他谈善本室的事","xu":"带了五年的博士生，论文刚被他打回","he":"古籍部同事，管库房的老馆员","geng":"图书馆夜班保安，打交道多年","lin":"版本学家周怀瑾的外孙，来馆求看遗稿","jian":"常来馆里收旧书的书商，认识他","shen":"共事六年的修复师，同在古籍部"},"links":[{"a":"wen","b":"lin","text":"闻是林外祖父周怀瑾的学生"},{"a":"wen","b":"kang","text":"酒会上同在头桌的贵宾"},{"a":"he","b":"geng","text":"同在馆里值班的老同事"},{"a":"he","b":"shen","text":"同属古籍部，楼上楼下共事"}],"deathReport":{"time":"约 20:00–21:30","cause":"后脑遭黄铜镇尺重击","scene":"22:03 馆员贺德昌刷卡进善本室，发现方敬之倒在长桌旁，已无呼吸。","loc":"lib","notes":["后脑一处凹陷伤，与镇尺端头吻合","善本柜敞开，锁孔无撬痕，宋刻函套是空的","右手指甲缝里有异物"]},"publicFacts":["方敬之当晚在三楼善本室加班，没参加一楼酒会。","善本室门自动落锁，外面进入要刷卡，里面有出门按钮。","有门卡的只有方敬之、馆员、保安、修复师和馆长。","死因是镇尺重击后脑；失窃的宋刻估价数百万元。","酒会嘉宾约四十人，包括文学院院长闻立群、捐赠人康颂文。","三楼走廊监控检修停用；门禁只记录刷卡和门磁开合。"],"timeline":[{"t":"19:30","text":"一楼酒会开场。"},{"t":"19:48","text":"方敬之刷卡进入善本室。"},{"t":"20:00","text":"各阅览室闭馆，酒会继续。"},{"t":"21:30","text":"酒会散场。"},{"t":"22:03","text":"贺德昌刷卡开门，发现方敬之已无呼吸。"},{"t":"22:10","text":"校保卫处报警。"},{"t":"22:20","text":"勘查：善本柜敞开，宋刻不见。"}],"budget":{"search":12,"ask":30},"locations":[{"id":"lib","name":"三楼善本室","scene":"library","desc":"恒温恒湿的小库房，长桌、善本柜，一股旧纸味。门自动落锁，里面有出门按钮。尸体已抬走，地上用白线圈着。","clues":[{"id":"c_lib1","title":"门禁日志打印","text":"19:48 方敬之刷卡进。20:19、20:31 门磁各开关一次，无刷卡。22:03 贺德昌刷卡进。出门按钮不经读卡器。"},{"id":"c_lib2","title":"敞开的善本柜","text":"后脑有凹陷伤，黄铜镇尺落在桌脚，端头沾血。柜门敞着，锁孔无撬痕，宋刻本《颐斋诗话》的函套空了。"},{"id":"c_lib3","title":"使用登记簿","text":"方敬之笔迹：“19:50 取出 K-0231 周怀瑾遗稿”，未归还。该稿 2024/04 起有十一条取阅记录，同一人笔迹。"},{"id":"c_lib4","title":"三楼值班台记录","text":"访客登记只有一行：19:52 林慕白，20:02 退出。巡更机三楼最后打卡 17:58。走廊监控贴着“检修停用”。"}]},{"id":"study","name":"古籍部主任办公室","scene":"study","desc":"三楼走廊另一头的办公室，书架顶到天花板。方敬之平时多半在这里备课、审稿。","clues":[{"id":"c_study1","title":"对照表复印稿","text":"遗稿与闻立群《宋元版本考略》对照表，三十七处。初稿 2024.04.11，修订 2026.10.12。末页：下周一递交。"},{"id":"c_study2","title":"座机通话记录","text":"19:41 呼出“闻立群（手机）”，3 分 12 秒。旁边便签：“20:10 三楼，当面谈，最后一次机会。”"},{"id":"c_study3","title":"许知夏查重报告","text":"博士论文相似度 38%，多出自网络和硕士论文。便签：“不同意送审”。夹着学生字条：“老师，我只是太着急了。”"},{"id":"c_study4","title":"给林慕白的回信","text":"方敬之回信：“遗稿暂不提供复制，请再等一周。我答应您的事，不会不算数。”旁有林慕白的申请表，与周怀瑾关系：外孙。"},{"id":"c_study5","title":"库房盘点表","text":"铅笔圈出三项账实不符：方志残页三叶、《文选》残册一册、一项待核。页边写着：“周一问贺”。"}]},{"id":"hall","name":"一楼大厅","scene":"hall","desc":"馆庆酒会的场地，酒会已散，长桌上留着残局。签到台、贵宾休息室和侧门都在这一层。","clues":[{"id":"c_hall1","title":"酒会照片索引","text":"20:12 大合影，闻立群在前排。20:19 至 20:41 的 14 张里没有闻。20:47 敬酒特写，闻的肩头有灰黑碎屑。"},{"id":"c_hall2","title":"礼品袋领取表","text":"金色礼品袋六只，编号贴袋底。02 康颂文，03 闻立群（20:05 签领），06 方敬之未领，余为来宾。"},{"id":"c_hall3","title":"流程单与花艺清单","text":"流程单：20:45 康颂文致辞，20:47 闻立群敬酒。背面花艺清单：全场白百合配桔梗，不用玫瑰等带刺花材。"},{"id":"c_hall4","title":"被摔的冠名协议","text":"休息室茶几上的协议：善本室更名“颂文厅”，捐赠方康颂文。方敬之红笔批：“不同意。”10 月 14 日。"}]},{"id":"lab","name":"古籍修复室","scene":"lab","desc":"二楼的修复室，窗朝后院，台面摊着待修的旧书页，空气里一股糨糊味。","clues":[{"id":"c_lab1","title":"纸墨检测报告","text":"K-0231 遗稿：八十年代稿纸，约 1986–88 年所写。沈青禾签，10/12。附页：专项经费三笔共 120 万，闻立群批。"},{"id":"c_lab2","title":"抽屉里的收据","text":"“嘉树斋收到方志残页三叶、《文选》残册一册，3200 元。”经手人贺德昌，10 月 9 日。小字：“余款周四晚后门结”。"},{"id":"c_lab3","title":"修复师工作日志","text":"沈青禾笔迹：20:10 隔壁库房有人拆箱。20:35 后院有烧纸味。20:52 后门外两男人递纸包。21:05 关灯。"}]},{"id":"garden","name":"后院花园","scene":"garden","desc":"图书馆背面的小花园，有花坛和铁皮落叶焚烧桶，一道铁门通员工楼梯。夜里没有路灯。","clues":[{"id":"c_gar1","title":"花坛里的礼品袋","text":"灌木后丢着金色礼品袋，袋底编号“03”。里面是线装书，签条“宋刻本《颐斋诗话》”，书角沾泥。袋口黏着焦纸屑。"},{"id":"c_gar2","title":"焚烧桶里的残页","text":"灰堆刚被翻动过。几片没烧透的格子稿纸，蓝黑钢笔字，认得出“怀瑾”“考辨”，还有一角蓝布面。"},{"id":"c_gar3","title":"员工楼梯铁门","text":"铁门锁舌缠着透明胶带，关上也不落锁。门边有四五个同牌烟头。楼梯直通三楼东端，离善本室二十来步。"}]},{"id":"clinic","name":"校医务室","scene":"clinic","desc":"一楼东侧的校医务室，酒会期间有校医值班，夜里有登记簿和一张观察床。","clues":[{"id":"c_cli1","title":"夜间登记簿","text":"20:52，闻立群，56 岁，左手背三道平行抓痕，渗血，已消毒贴创可贴。备注：“自述被花刺划伤”。"},{"id":"c_cli2","title":"校医初步验尸","text":"估计死亡在 20:00 到 21:00 之间。死者右手指甲缝里有深灰色羊毛纤维和皮屑。创口与镇尺端头吻合。"},{"id":"c_cli3","title":"观察床登记","text":"许知夏，26 岁，20:24 入，20:58 离，“过度换气，情绪激动”。备注：“拒绝联系导师”。"}]}],"suspects":[{"id":"wen","name":"闻立群","role":"文学院院长","age":56,"look":{"skin":"light","hair":"sidepart","hairColor":"grey","glasses":"rect","beard":"none","outfit":"suit","acc":"tie","mood":"stern"},"bio":"文学院院长，方敬之的师弟，今晚馆庆酒会的校方主持嘉宾。正在竞争副校长，酒会期间一直在大厅。","demeanor":"官腔儒雅，爱说“请注意”，被质疑先反问","topics":[{"id":"t_rel","q":"你和方教授的关系？","a":"同门三十多年，他是我师兄。治学一流，做人嘛，认死理。我常说他是图书馆的守门人。唉，痛心。"},{"id":"t_where","q":"案发时你在哪？","a":"整场酒会我都在大厅，康先生、馆长、摄影师都看着呢。我是主持嘉宾，岂有离席之理？请不必再问。","lie":true,"truth":"我出去过一会儿，说是接电话，大厅太吵，出去透口气，大概二三十分钟。没说，是怕被你们写成文章。"},{"id":"t_call","q":"他今晚找过你吗？","needs":["clue:c_study2"],"a":"没有。今晚我们一句话都没说上。他连酒会都不肯露面，还能同我谈什么？请注意，你的问题带着倾向。","lie":true,"truth":"有。七点四十几他打我手机，说想当面谈，“最后一次”。我说酒会正忙，改天。他说：没有改天了。"},{"id":"t_book","q":"周怀瑾遗稿？","needs":["clue:c_study1"],"a":"周先生是我恩师，晚年我替他整理过讲义，书里引述他的思想，序言也致谢了。说抄袭，是断章取义。"},{"id":"t_bag","q":"你的礼品袋呢？","needs":["clue:c_hall2"],"a":"放在席位上，后来找不到了，想是被谁错拿。酒会人来人往，一只礼品袋，我没闲到去管它。","lie":true,"truth":"袋子是我提着出去的，后来随手丢了。你们要是以为里面有什么名堂，那是想多了，我无话可说。"},{"id":"t_hand","q":"你的手怎么回事？","needs":["clue:c_cli1"],"a":"席间玫瑰的刺划的，小事，贴个创可贴就行。人上了年纪，皮肤薄，碰一下就破，也值得追问？","lie":true,"truth":"……不是花刺，是被人抓的。谁抓的，在哪里抓的，我现在不想再说了。我要见律师，他到之前别问。"},{"id":"t_fund","q":"古籍专项经费？","needs":["clue:c_lab1"],"a":"年年有预算，批给谁、批多少都有程序，同方敬之个人没有干系。请注意，这是公款，不是私账。","lie":true,"truth":"钱是我批的，三笔一百二十万。他收了两年钱没再提对照表。上周他却说钱不要了，叫我自己去委员会说清楚！"},{"id":"t_theft","q":"宋刻失窃你怎么看？","a":"内贼，这点我强调。柜子没撬痕，说明作案的人有钥匙或熟悉流程，馆员、保安、书商都有嫌疑。"}],"confronts":[{"clue":"c_hall1","breaks":"t_where","crack":true,"a":"几张照片能证明什么？我去洗手间，我同人寒暄，谁盯着我每一分钟？……好，我是出去过，我已经说了！"},{"clue":"c_study2","breaks":"t_call","a":"一通电话而已。我是不想被你们扯进来。他是我师兄，我说了改天，他就挂了，仅此而已。"},{"clue":"c_gar1","breaks":"t_bag","a":"这袋子……我说了，丢了。花坛里捡到的东西，也能算到我头上？编号是编号，人是人。请注意。"},{"clue":"c_hall3","breaks":"t_hand","a":"花艺清单？我记错了，行不行？别拿这种小事做文章！我手上这点伤，同你们要追的案子毫无关系！"},{"clue":"c_study1","a":"这是敬之的偏执！拿一叠复印件，就想毁掉我三十年的名誉？学界谁没引过前辈的东西，荒唐。"},{"clue":"c_lab1","breaks":"t_fund","a":"专项的列支单……批钱是我的职责，用在哪里有账可查！纸是八十年代的，所以呢？好，钱我批过！"},{"clue":"c_lib1","a":"我没有善本室的卡，日志上自然没有我。拿一份没有我名字的记录来问我，不觉得可笑吗？"}],"fallback":"这与我无关，请不要拿不相干的东西占用我的时间。"},{"id":"kang","name":"康颂文","role":"校友捐赠人","age":62,"look":{"skin":"tan","hair":"slick","hairColor":"grey","glasses":"none","beard":"none","outfit":"suit","acc":"pocketwatch","mood":"smile"},"bio":"鸿运地产董事长，本校校友，捐资八百万做善本数字化。今晚是贵宾，20:45 致辞。","demeanor":"嗓门大，爱提“我捐了八百万”，开口“哎呀”，带笑","topics":[{"id":"t_why","q":"你为什么来酒会？","a":"哎呀，我是这儿毕业的！捐了八百万，馆庆我能不来吗？头桌坐着，还要致辞呢，我就爱热闹，哈哈！"},{"id":"t_where","q":"案发时你在哪？","a":"全程在大厅啊！碰杯、拍照、听乐队，20:45 我还上台讲了两分钟，一屋子人看着，哪有空上楼？"},{"id":"t_fang","q":"你和方教授有过节吗？","a":"没有没有！老方是个老顽固，但我敬他。冠名那点小事早谈妥了，我们生意人好商量，哎呀，不至于。","lie":true,"truth":"有。他打回我的冠名协议，今晚 19:25 休息室我拍了桌子，说钱可以收回。他说：“随你，名字不卖。”气话！"},{"id":"t_name","q":"冠名协议？","needs":["clue:c_hall4"],"a":"想给善本室起个名，颂文厅，多响亮！八百万照给，名字让一让嘛。他倒好，红笔一批，不行！"},{"id":"t_wen","q":"闻院长一直在吗？","needs":["clue:c_hall1"],"a":"一直在啊，院长就在我旁边，碰了好几回杯，再忙也没离开过大厅，我看得清清楚楚，不会错。","lie":true,"truth":"不是一直。20:15 前后他说去接电话，我上台他才回来。散场前他要我，有人问就说他整晚跟我在一起。我就应了。"},{"id":"t_seen","q":"酒会上有异样吗？","a":"闻院长敬酒时肩头有灰，我顺手拍了两下。散场前见他手上贴了创可贴，他说是花刺划的。"}],"confronts":[{"clue":"c_hall4","breaks":"t_fang","a":"哎呀……好，我认，是吵了。可我要动手，会在酒会上当着四十个人致辞？我骂过他，没碰过他！"},{"clue":"c_hall1","breaks":"t_wen","a":"照片里我是一直在。可院长……好，我说实话，他出去了。我答应过替他圆，真不知他去干什么！"},{"clue":"c_hall2","a":"我的袋子放头桌椅子上了，里头是一本纪念册和一瓶酒，没拆。你们别告诉我，这也算线索？"},{"clue":"c_gar1","a":"花坛里的袋子？不是我的，我是 02 号。我那只在车上呢，不信问我司机，我哪有闲心扔东西！"}],"fallback":"哎呀，这个我真不清楚，你问点别的，我知无不言！"},{"id":"xu","name":"许知夏","role":"博士研究生","age":26,"look":{"skin":"fair","hair":"ponytail","hairColor":"black","glasses":"round","beard":"none","outfit":"hoodie","acc":"badge","mood":"worried"},"bio":"方敬之的博士生，论文刚被导师打回，不同意送审。她自称今晚一直在宿舍，没来过图书馆。","demeanor":"声音小，容易哽咽，答话先停顿，爱说“对不起”","topics":[{"id":"t_rel","q":"你和方教授的关系？","a":"方老师是我导师，五年了。他对我很严，但我知道，他是为我好。他走了，我真不知道怎么办。对不起。"},{"id":"t_where","q":"案发时你在哪？","a":"我在宿舍复习，一晚上没出门。室友今晚回家了，没人能作证。我没来过图书馆。对不起。","lie":true,"truth":"我撒谎了。傍晚被拒后喘不上气，20:24 去了一楼医务室，躺到快九点。我丢人，也怕你们觉得我有动机。"},{"id":"t_report","q":"你的论文怎么回事？","needs":["clue:c_study3"],"a":"那份查重……是我太着急，从网上拼了一些综述。方老师说，不想毁了我，也不能放过去。"},{"id":"t_hate","q":"你恨他吗？","a":"那天晚上，恨过一点点。但我更恨自己。他是唯一逐字批我论文的人，我怎么会杀他。对不起。"},{"id":"t_old","q":"他最近在忙什么？","a":"这两周他总在查一份旧稿，晚上也不回家。我听见他对着电话说：“有些人，得自己认。”"},{"id":"t_door","q":"善本室怎么进？","a":"没卡的人只能敲门。老师隔着门问“谁”，认识的才按钮放行。我进去过很多次，都这样。"},{"id":"t_stair","q":"你去过后院吗？","needs":["clue:c_cli3","clue:c_gar3"],"a":"……去过。20:15 前后我想再求老师，绕到后院，见个拎金袋子、穿深灰西装的男人先进了铁门。"}],"confronts":[{"clue":"c_gar3","a":"这扇门……我没碰过它，我只是站在门口，真的。我当时哪知道里面会出这种事。对不起。"},{"clue":"c_cli3","breaks":"t_where","a":"……是，我去了医务室。当时快窒息了，校医让我别联系导师，我就没联系。对不起，我不该骗你们。"},{"clue":"c_study3","a":"别拿这份报告说话……这是我这辈子最丢脸的东西。我已经知道错了，不会拿它开脱，也不想再提。"},{"clue":"c_study1","a":"这是老师最近在弄的东西？我没见过，他不让我碰，说学生不要卷进这种事，只说他很累。"},{"clue":"c_lib1","a":"门禁？我没有善本室的卡，从来都是老师开门让我进。日志上这些，我看不懂，也不关我的事。"}],"fallback":"对不起，我……这个我不太清楚。"},{"id":"he","name":"贺德昌","role":"古籍部馆员","age":58,"look":{"skin":"light","hair":"short","hairColor":"grey","glasses":"round","beard":"none","outfit":"vest","acc":"badge","mood":"worried"},"bio":"古籍部管理员，在馆里二十多年，持善本室门卡，常穿灰羊毛马甲。22:03 刷卡发现了尸体。","demeanor":"絮叨，爱叹气，自称“老头子”，被问急了就念“这可怎么办”","topics":[{"id":"t_find","q":"你怎么发现的？","a":"22:00 前后我上楼清场，善本室灯还亮着。敲门没人应，我刷卡进去，他躺在地上。这可怎么办啊。"},{"id":"t_card","q":"你有善本室门卡吗？","a":"有。我的卡直接刷就进，用不着敲门。今晚只刷了 22:03 那一次。没卡的人只能敲门。"},{"id":"t_where","q":"20:00 之后你在哪？","a":"清完三楼的场，我就下到一楼服务台守着，22:00 前后才上去。老头子一个，没别处可去。","lie":true,"truth":"我没守着。20:10 去二楼库房包包裹，20:17 听见有人上楼，皮鞋声，20:33 又下来，我当是老耿。20:50 去后门交了点东西。"},{"id":"t_audit","q":"库房缺册的事？","needs":["clue:c_study5"],"a":"那几件是民国就丢的老账，几十年没人看，早核销了。方教授非要翻出来，真没必要啊，唉。","lie":true,"truth":"是我卖的。残页是副本，值不了几个钱，共三千二。我儿子欠了网贷，我昏了头。可方教授的死，真和我无关！"},{"id":"t_stair","q":"后院的员工楼梯？","a":"铁门平时锁着，一通到三楼东头，离善本室不远。可老耿说他天天检查的，应该一直锁着啊。"},{"id":"t_key","q":"善本柜的钥匙？","a":"柜钥匙两把，一把方教授自己带着，一把锁在馆长的保险柜。我腰上只有门卡和库房钥匙。"},{"id":"t_hands","q":"让我看看你的手？","needs":["clue:c_cli2"],"a":"你看，全是老年斑和修书的旧疤，新伤一道都没有。马甲是灰的不假，天天穿，谁不知道？"}],"confronts":[{"clue":"c_lab3","breaks":"t_where","a":"连修复师的日志都看了？……对，我和书商私下交过货。可我在库房打包，和命案没关系！"},{"clue":"c_lab2","breaks":"t_audit","a":"这收据，你们怎么翻到的？唉，我认，我是卖了点残页。可我宁可割自己的肉，也不会动方教授。"},{"clue":"c_lib1","a":"20:19 那次没刷卡，那就不是我。我有卡，进去哪用得着敲门？你们放心，老头子没那个本事。"},{"clue":"c_cli2","a":"灰羊毛？你们是不是盯上我了？你们看我这双手，指甲剪得秃秃的，抓不出那样的伤，这可怎么办。"},{"clue":"c_gar3","a":"铁门被胶带缠了？不是我干的！老耿说他每天都查，难怪他今晚一直躲着我，唉，我还纳闷呢。"}],"fallback":"唉，这个我真不知道，老头子这把年纪了，别吓我。"},{"id":"geng","name":"耿大海","role":"图书馆保安","age":49,"look":{"skin":"tan","hair":"short","hairColor":"black","glasses":"none","beard":"stubble","outfit":"uniform","acc":"badge","mood":"tired"},"bio":"图书馆夜班保安，持员工楼梯和善本室的门卡，当晚一个人负责大门、监控室和夜间巡更。","demeanor":"大嗓门，爱说“嗨”“我干了十几年”，心虚时声音更大","topics":[{"id":"t_round","q":"今晚你巡逻了吗？","a":"巡了啊！20:30 我上了三楼，走廊挨个看，一切正常。我干了十几年，规矩还不懂？","lie":true,"truth":"嗨……我没上去。20:10 我回监控室看球赛，一直盯到快九点。怕担责任，才吹牛。"},{"id":"t_back","q":"后院你见过谁？","needs":["ask:geng.t_door"],"a":"20:40 我去撕胶带，远远看见院长从花坛往大厅侧门走，肩头沾灰。我喊他，他说出来醒酒。"},{"id":"t_door","q":"后院员工门锁了吗？","a":"一直锁着，我天天查！钥匙在我这，谁也进不去，别怀疑到我头上，我干了十几年，不犯这种错！","lie":true,"truth":"……胶带是我缠的。19:50 想去后院抽烟，怕门关上进不来。20:40 去撕，半路被岔开，就忘了。"},{"id":"t_camera","q":"三楼监控呢？","a":"检修，周四下午停到周五上午，通知就贴在值班台上。我只管大门，三楼的事别怪我，嗨！"},{"id":"t_card","q":"你的卡能进善本室吗？","a":"能。但今晚我没刷过，你们看日志就知道。我一个保安，跑上去干什么？是吧，嗨，真没有。"},{"id":"t_left","q":"闭馆时还有谁没走？","a":"就剩个姓林的访问学者。20:05 左右贺师傅带他下楼，我在大厅碰见，他脸色不好，像哭过。"}],"confronts":[{"clue":"c_lib4","breaks":"t_round","a":"巡更机最后是 17:58？……行，我认，没上去。别告诉领导，我老婆还指着这份工资！"},{"clue":"c_gar3","breaks":"t_door","a":"这胶带被你们找到了。嗨，我缠的，我认。可我发誓，就是想去后院抽根烟，谁知道会出这事！"},{"clue":"c_lib1","a":"20:19 那次开门没刷卡，那就不是我的卡。我今晚真没进过善本室，你们别乱写，嗨！"}],"fallback":"嗨，这个我真没注意，你问别的吧！"},{"id":"lin","name":"林慕白","role":"访问学者","age":39,"look":{"skin":"light","hair":"short","hairColor":"black","glasses":"rect","beard":"none","outfit":"jacket","acc":"scarf","mood":"sad"},"bio":"新加坡国立大学访问学者，版本学家周怀瑾的外孙，来本校三个月，一直想看外祖父的遗稿。","demeanor":"斯文克制，偶尔夹英文，爱说“honestly”，提到外公会停顿","topics":[{"id":"t_why","q":"你为什么来本校？","a":"我外公周怀瑾 1989 年去世，手稿都在这座馆里。Honestly，我等了三个月，想复印一份带回家。"},{"id":"t_3f","q":"你去过三楼善本室吗？","a":"没有。善本室我进不去，闭馆前一直在一楼阅览室。I mean，三楼我连楼梯都没踩过。","lie":true,"truth":"我撒了谎。19:52 我上去敲门求方教授。他在门口说：“再给我一周，下周一之前让它见光。”又低声：“我欠你外公的。”20:02 被送出来。"},{"id":"t_where","q":"20:05 之后你在哪？","a":"出了图书馆，去校内“木心咖啡”，点了杯美式写笔记，坐到 21:30。付款记录在手机里。"},{"id":"t_cafe","q":"咖啡馆有人记得你吗？","needs":["ask:lin.t_where"],"a":"老板娘认得我，我几乎每晚都去，坐靠窗那张桌子。Sorry，这听上去像给自己找证人。"},{"id":"t_grand","q":"你外祖父的遗稿？","needs":["clue:c_study4","clue:c_study1"],"a":"那是外公晚年的版本学讲稿，没发表过。后来有人拿去出了书成了名。家里一直知道，但没证据。"},{"id":"t_title","q":"遗稿是什么样子？","needs":["clue:c_gar2"],"a":"叫《版本考辨》，手抄在格子稿纸上，蓝布面。原件我没见过。要是烧的真是它……I mean，我不敢想。"},{"id":"t_sorry","q":"他那句“欠你外公”？","needs":["clue:c_lab1","ask:lin.t_3f"],"a":"遗稿在他手里两年多，我问过三回，他都说在整理。Honestly，他像是在等什么，后来自己也说不清了。"}],"confronts":[{"clue":"c_lib4","breaks":"t_3f","a":"你们翻到访客登记了……是，我上去过，怕成嫌疑人。但 20:02 我就离开了，登记表上写着。"},{"clue":"c_study4","a":"那封回信我也收到了。“我答应您的事，不会不算数”，他一向言出必行，我不信他会食言。"},{"clue":"c_lab1","a":"八十年代的纸，蓝黑墨水……那就是外公的字。看到它，我眼睛都湿了，想起他教我握笔。"},{"clue":"c_gar2","a":"这是外公的稿纸格式！天哪，谁烧了它？你们一定要查清楚，不然我一辈子都不会原谅那个人！"}],"fallback":"抱歉，这个我帮不上忙。Sorry."},{"id":"jian","name":"简嘉树","role":"古籍书商","age":46,"look":{"skin":"light","hair":"short","hairColor":"brown","glasses":"round","beard":"goatee","outfit":"jacket","mood":"sly"},"bio":"嘉树斋老板，常年出入学校和馆里收旧书，与图书馆几位老人相熟。今晚有人见过他的车停在馆外。","demeanor":"圆滑，爱说“咱们明白人”“您”，笑里藏刀","topics":[{"id":"t_biz","q":"你做什么生意？","a":"旧书生意。收线装书、残页，转手卖给懂行的人。咱们明白人，这行水深，国家一级的我不碰。"},{"id":"t_where","q":"今晚你在哪？","a":"一晚上都在店里对账，没出过门，也没到过学校，您信我。店员八点就下班了，反正我没来。","lie":true,"truth":"我来了。20:50 在后门外和贺师傅碰面，付了余款，拿了个纸包，20:58 走的。别的我没碰。"},{"id":"t_buy","q":"残页是怎么买的？","needs":["clue:c_lab2"],"a":"正规流出的旧货，贺师傅说是库房核销品，手续齐全，明码实价，有收据可查，咱们明白人。","lie":true,"truth":"哪来的手续。我知道是馆藏，价压得低，心里清楚是灰色生意。但宋刻我真没碰，那是掉脑袋的东西。"},{"id":"t_cash","q":"这笔账怎么结的？","needs":["clue:c_lab2"],"a":"三叶方志加一册残《文选》，说好三千二。先付两千，余下一千二，约周四晚后门当面交割。"},{"id":"t_smell","q":"后院有什么异样？","a":"我在后门外站了几分钟，天黑又离花坛远，什么也没看清，就闻到一股烧纸味，还当是烧落叶。"},{"id":"t_theft","q":"宋刻扔花坛你怎么看？","needs":["clue:c_gar1"],"a":"书没丢，扔在花坛里，那还叫偷？真贼舍不得这么糟蹋，除非他本来就不是冲着书去的，您想想。"}],"confronts":[{"clue":"c_lab3","breaks":"t_where","a":"连窗外的人影都被人记下了？行，我来过。您只要记住我没上过楼，杀人的买卖我不干，真的。"},{"clue":"c_lab2","breaks":"t_buy","a":"收据在你们手里……那我认，知道来路不正。可你们要当我是凶手，冤枉！我犯的不是杀人的事。"},{"clue":"c_gar1","a":"好端端一册宋版扔花坛，还蹭了泥，糟蹋东西！贼不识货，我可不会这样对待宋版，您说是吧。"}],"fallback":"咱们明白人，这个我不清楚，您换个问法。"},{"id":"shen","name":"沈青禾","role":"古籍修复师","age":34,"look":{"skin":"fair","hair":"bun","hairColor":"black","glasses":"none","beard":"none","outfit":"labcoat","mood":"neutral"},"bio":"古籍部修复师，在二楼修复室工作，持善本室门卡，与方敬之共事六年，今晚本应准时下班。","demeanor":"话少，句子短，用词专业，偶尔停顿，手上有药水味","topics":[{"id":"t_leave","q":"今晚几点下班？","a":"20:00，准时。回家了。修复室熄灯锁门。后面楼里发生什么，我不知道，也没听见。","lie":true,"truth":"我没走。有一批补好的页子要晾，我留守到 21:05。怕你们问我知道什么，才没说。"},{"id":"t_test","q":"你给方教授做过检测吗？","needs":["clue:c_lab1"],"a":"没有。这一周只有常规修补，没接过特殊检测。方主任也没派额外的活。你们大概弄错了。","lie":true,"truth":"做过。10 月 12 日他让我测 K-0231 的纸和墨，嘱咐暂不外传，说：“我想给一个人最后一次机会，让他自己认。”"},{"id":"t_paper","q":"遗稿的年代？","needs":["clue:c_lab1","clue:c_study1"],"a":"八十年代稿纸，蓝黑墨水，氧化程度对得上 1986 到 1988 年。比 1999 年早十年以上。"},{"id":"t_smell","q":"你闻到什么了吗？","needs":["clue:c_gar2"],"a":"20:35 开窗，后院有烧纸味，我以为是烧落叶。20:52 后门外两个男人说话，递了个纸包。不认识。"},{"id":"t_fund","q":"修复室的专项经费？","needs":["clue:c_lab1"],"a":"普通专项，设备、耗材、我的补贴都从里面走。方主任管账，我只管用，没什么特别的，真的。","lie":true,"truth":"有特别。每批款下来，方主任就在办公室坐很久。他说过：“这钱拿着烫手，该还了。”我怕你们觉得我也拿了好处。"},{"id":"t_fang","q":"方教授最近如何？","a":"很紧绷，我没见过他那样。他说过：“有些事，得有人认。”我问是谁，他只说“下周一见分晓”。"},{"id":"t_lin","q":"你认识林慕白吗？","needs":["ask:shen.t_fang"],"a":"来修复室看过两次纸样，是周怀瑾先生的外孙，方主任告诉过我。他对纸很敬重，不像有些人。"}],"confronts":[{"clue":"c_lab3","breaks":"t_leave","a":"日志是我自己写的，抵赖不了……好，我留守到 21:05。不想让人知道，是怕说多了惹麻烦。"},{"clue":"c_lab1","breaks":"t_test","a":"报告上有我的名字，我不能说没做过。他嘱咐过保密，我才瞒。现在他没了，再瞒也没有意义。"},{"clue":"c_study1","breaks":"t_fund","a":"对照表日期是二〇二四年四月。(停顿)他知道得比我想的早得多。好，钱的事，我是知道的。"},{"clue":"c_gar2","a":"那是稿纸的残片？是被谁烧了吗？天哪，纸不能这样烧。那是别人一辈子的东西，毁了就没了。"}],"fallback":"这个，我不太清楚。纸上的事，我才懂一些。"}],"solution":{"culprit":"wen","method":{"q":"凶手怎么做到的？","options":["持卡的馆员被撞破私卖馆藏，刷卡进屋动手，之后伪造盗窃现场。","酒会中离席走后院楼梯，被死者按钮放进屋，杀人后伪造盗窃。","访客趁死者开门说话时闪进屋，躲到柜后，等没人再动手。","外来买家从后院溜进楼偷书，被撞见后行凶，原路逃走。"],"correct":1},"motive":{"q":"为什么杀人？","options":["死者查出成名作的来历，当面摊牌，凶手一时情急动了手。","死者要追问库房账目缺口，凶手怕丢饭碗，抢先封口。","死者收好处压了抄袭两年，如今反悔，凶手灭口并毁稿。","死者驳回重金捐赠协议，凶手怀恨，一时冲动动手。"],"correct":2},"keyClues":["c_lib1","c_study1","c_lab1","c_hall1","c_hall2","c_gar1"],"truth":["凶手是文学院院长闻立群。他的成名作大段取自恩师周怀瑾的遗稿。方敬之2024年就发现了，却收下闻批的三笔共一百二十万专项经费，压了两年。","林慕白来后，方动摇了。他检测遗稿，19:41 约闻 20:10 到善本室，说钱不要了，叫闻自己去委员会认。闻只听出一层意思：交易被撕毁。","闻早有预谋：领了 03 号礼品袋，托康颂文圆谎，20:13 离席，走后院楼梯上三楼，20:19 被方按钮放进屋。争执中被抓伤，他用镇尺杀人，带走遗稿和宋刻。","失窃是幌子。贺私卖残页、耿谎称巡逻、简后门收货，都像内贼，却对不上两次无刷卡开门：持卡者不必敲门。贺在库房，简在后门，耿在监控室。","闻在焚烧桶烧了遗稿，把装着宋刻的袋子丢进花坛，20:47 上台敬酒，肩头沾灰。他手背的伤自称花刺划的，可全场只有白百合。死者指甲缝里的深灰羊毛和皮屑，对得上他。"]}},{"id":"teahouse","title":"半盏春","tagline":"开张大吉的夜里，掌柜倒在了后院的雨水里。","difficulty":2,"cover":"cv_teahouse","tone":"sepia","brief":"城南老街的半盏春歇业十四个月，今夜重新开张，六十多位街坊挤满前厅。说书先生谭九龄刚开书，窗外就落了雨。你是恰好在座的刑侦顾问，立刻被请去看现场。二十一点三十二分，学徒阿禾推开后院门尖叫：掌柜席怀山趴在青石板上，后脑塌陷，已经没气。账房钟砚秋压低声音：“二十一点零五分，前厅还听见我舅舅在后院骂人。怎么会……”","victim":{"name":"席怀山","desc":"半盏春掌柜，六十六岁，经营老茶馆四十余年。他倒在后院石桌旁，后脑遭钝器重击，深灰夹袄被雨淋透。","look":{"skin":"light","hair":"short","hairColor":"grey","glasses":"none","beard":"none","outfit":"jacket","mood":"stern"}},"publicFacts":["半盏春是七十余年的老茶馆，歇业十四个月，今夜重新开张，宾客约六十人。","席怀山十九点二十回后院，吩咐“二十一点三十分前勿扰”，此后无人公开去过后院。","二十点四十、五十二、二十一点零五分，前厅三次听到后院传来席怀山的骂声，警方暂以“二十一点零五分他还活着”为准。","谭九龄二十点登台，到二十一点三十分没有下过台，满堂亲眼所见。","十九点五十八分到二十点二十六分下过急雨；后院只有靠墙一圈有屋檐。法医只能把死亡时间划在十九点三十到二十一点三十之间。","开书后离席超过十分钟的只有邹茂才和郝慎之；后院通后巷的小门今晚没有闩上。"],"relations":{"tan":"在茶馆说了三十年书的说书先生","zou":"给茶馆供镇店老茶饼的云南茶商","xiao":"坐了四十年一号位的老茶客","liu":"掌柜的远房晚辈，新来的学徒","hao":"对门药铺老板，做了二十年邻居","sui":"替房东来收房租的跑腿人","zhong":"掌柜的亲外甥女，店里的账房","ge":"灶上干了三十年的点心师傅"},"links":[{"a":"xiao","b":"hao","text":"今晚邻座，一起下棋"},{"a":"liu","b":"zhong","text":"都是掌柜的亲戚，在店里做事"},{"a":"liu","b":"ge","text":"同是店里的伙计，一起忙开张"}],"deathReport":{"time":"约 19:30–21:30","cause":"后脑遭钝器重击，颅骨塌陷","scene":"21:32 学徒阿禾去请掌柜切糕，在后院石桌旁发现他面朝下趴着，已没了气息。","loc":"garden","notes":["后脑一处钝器重击，一击致命","深灰夹袄背上被雨淋透","急雨干扰了判断，死亡时间只能划大范围"]},"timeline":[{"t":"18:00","text":"开门迎客，阿禾十八点三十分给后院的八哥罩上黑布。"},{"t":"19:00","text":"开张仪式，席怀山致辞、敬头道茶，满堂都看见了他。"},{"t":"19:20","text":"席怀山回后院，吩咐二十一点三十分前勿扰；谭九龄上二楼后台候场。"},{"t":"19:58","text":"急雨落下，二十点二十六分停。"},{"t":"20:00","text":"谭九龄登台开书，直到二十一点三十分没有下台。"},{"t":"21:05","text":"前厅第三次听到后院的骂声，此后再没有人听到。"},{"t":"21:32","text":"阿禾去请席怀山切开张糕，发现他倒在后院，尖叫呼救。"},{"t":"21:40","text":"你赶到现场，封锁后院和各个出口。"}],"budget":{"search":12,"ask":28},"locations":[{"id":"garden","name":"后院","scene":"garden","desc":"后院有老桂树、青石桌和荷花缸。只有靠墙一圈有屋檐，院心的石板还湿着。","clues":[{"id":"c_gar1","title":"石板上的人形","text":"席怀山面朝下倒在石桌旁，后脑塌陷，穿深灰夹袄，背上湿透。翻过身，他身下的石板是干的。石桌上茶盏里的茶淡得近乎无色。"},{"id":"c_gar2","title":"廊下的八哥笼","text":"西头廊钩挂着靠近板壁的鸟笼，笼里一只八哥，布带搭扣空垂。东头钩下柱面有圈干净灰印。你拍手，八哥便骂：“吵什么吵！谁在前头拍桌子！”"},{"id":"c_gar3","title":"缸后的黑布","text":"荷花缸后塞着一团湿透的黑布，大小正合鸟笼，两角缝着搭扣布带，布面有暗红蹭痕。缸沿的青苔被蹭掉一块。"},{"id":"c_gar4","title":"缸底的铜壶","text":"缸底摸出一把紫铜长嘴壶，壶肚有新凹痕，壶底沾着几根灰白短发，凹痕里水色发红。炭炉上的壶位已经空了。"},{"id":"c_gar5","title":"后巷小门","text":"后院通后巷的小门虚掩，横闩靠在墙上没插。门洞檐下落着八九截细支烟蒂，烟灰是干的。"}]},{"id":"hall","name":"前厅与说书台","scene":"hall","desc":"六十来张八仙桌摆得满满当当，梁柱新漆还带着桐油味。正前方是矮矮的说书台，台后是一道板壁。","clues":[{"id":"c_hall1","title":"节目单与便笺","text":"节目单：“二十点谭九龄开书，二十一点三十分收书。”旁有席怀山便笺：“九龄：醒木轻点，老黑一听响动就嚷。”“二十一点三十分前后院勿扰。”"},{"id":"c_hall2","title":"阿禾的添茶簿","text":"续水簿：“一号肖19:46续。”“三号郝19:48续；20:55空，21:20回。”“四号邹19:30空；20:01回；21:02空，21:24回。”"},{"id":"c_hall3","title":"一号位的布包","text":"一号位旁蓝布包里露出线装旧书《鹤年书底·卷三》。扉页毛笔字：“此书付九龄，莫使断绝。”书角用软布裹过，几乎没磨损。"},{"id":"c_hall4","title":"说书台后的板壁","text":"你在台上拍醒木，板壁那头传来沙哑老声：“吵什么吵！谁在前头拍桌子！”你在厅中八仙桌重拍、拍手，壁后毫无动静。"}]},{"id":"guestroom","name":"二楼后台客房","scene":"guestroom","desc":"楼上客房今晚腾给说书先生做后台，窄木楼梯从走廊尽头直通后院。","clues":[{"id":"c_gu1","title":"铜盆里的长衫","text":"凳上铜盆泡着一件深蓝长衫，右袖口压在水底，水色淡红。毛巾上有暗红手指印。衣架上挂着灰布长衫，领口别着“谭”字铜牌。"},{"id":"c_gu2","title":"门边的梨汤","text":"门内小凳上一碗梨汤，汤面凝了薄皮，勺子没动。垫纸写着“19:40 后台润嗓 阿禾”。茶几上的盖碗茶已凉透。"},{"id":"c_gu3","title":"提纲上的红“拍”","text":"《定军山》提纲页边画着红“拍”字，标着“20:40·20:52·21:05·21:25”。有一个画在半句话中间。"},{"id":"c_gu4","title":"相框后的信稿","text":"相框里是师徒合影。背后塞着未寄的信稿：“怀山兄：砚秋把实话都告诉我了。鹤年师父的书底，你卖与了谁？别再瞒我。”无落款。"}]},{"id":"study","name":"账房","scene":"study","desc":"前厅后头一间窄账房，老算盘桌，一排账簿。灯亮着，钢笔没盖帽。","clues":[{"id":"c_stu1","title":"书底转让收据","text":"存根：“今收肖仲谦先生叁拾捌万元，购得谭鹤年手录《书底》全卷。席怀山。”十二天前。背面小字：“款补窟窿。九龄处，开张夜后我亲自去讲。”"},{"id":"c_stu2","title":"翻修账本","text":"翻修超支六十二万。“邹茂才，老茶饼预付四十万。”“郝慎之，药茶备料三十万，契约暂缓。”“房东欠租九万。”末行：“19:36 付房租九万，隋大有签收。”"},{"id":"c_stu3","title":"祝词草稿","text":"席怀山写了一半的祝词，末尾涂改很重：“九龄，书的事是我对不住你，散场后我当面认，你打我骂我都使得。”"}]},{"id":"kitchen","name":"茶灶与厨房","scene":"kitchen","desc":"厨房连着茶灶，蒸笼冒着开张糕的甜香。墙上挂粉笔任务板，后门通向后院边的小台阶。","clues":[{"id":"c_kit1","title":"粉笔任务板","text":"任务板：“18:30 老黑罩布 ✓ 阿禾（掌柜说罩到散场）”“19:40 后台梨汤 ✓ 阿禾（人不在，放凳上）”“21:30 切开张糕”。"},{"id":"c_kit2","title":"粘好的紫砂壶","text":"碗柜底层藏着一把裂了的紫砂壶，用胶带粘得歪歪扭扭，底签“镇店·一九八〇”。下压阿禾的便笺：“对不起，我赔。”旁有湿纸巾。"},{"id":"c_kit3","title":"后门台阶","text":"后门台阶上落着五六个新烟头，同一牌子，烟灰被雨打糊。台阶朝着后院，能望见荷花缸和檐廊一角。"},{"id":"c_kit4","title":"压着的聘书","text":"面粉柜的铁盒底压着信：对岸“听潮阁”聘葛有福做点心总管，月薪八千，“望勿声张”。日期是上周。"}]},{"id":"cellar","name":"茶窖","scene":"cellar","desc":"地下茶窖青砖拱顶，木架上码满茶饼，满是陈茶和潮土味。","clues":[{"id":"c_cel1","title":"窖口登记簿","text":"登记簿：“钟18:40入18:45出。”“邹19:28入19:58出。”“邹21:02入21:24出。”窖顶铁栅正对后院，窖里能听见头顶石板上的动静。"},{"id":"c_cel2","title":"做旧作坊","text":"最里间的木盆泡着浓褐茶汤和新压茶饼，案上一摞崭新内飞印着“民国三十八年·同兴号”，油墨还粘手。角落有咖啡渣和电吹风。"},{"id":"c_cel3","title":"进货单据","text":"发货单：新压茶饼“每饼成本九十元”，转手半盏春“每饼八千”，共五十饼。另有字条：“散场前，染盆和内飞都扔江里。”"}]}],"suspects":[{"id":"tan","name":"谭九龄","role":"说书先生","age":68,"look":{"skin":"light","hair":"short","hairColor":"white","glasses":"round","beard":"mustache","outfit":"robe","mood":"neutral"},"bio":"半盏春说了三十年书的评书艺人，今夜二十点登台开《定军山》，满堂亲眼见他没下过台。","demeanor":"文白夹杂，爱说“列位”“且慢”，被逼急了反而更慢更稳。","topics":[{"id":"t_wood","q":"醒木讲究","a":"醒木一拍，醒书也醒人，轻重要匀。我拍了三十年，席怀山隔墙骂了三十年，常客都当彩头。"},{"id":"t_prep","q":"开书前","lie":true,"a":"十九点二十我就上了后台，关门过词，一步没下来。二十点差一分走到台口，列位都看见。","truth":"我下去过。十九点三十八分，我从后楼梯下后院找席怀山说话，回楼换了衣裳，十九点五十八分上台。"},{"id":"t_voice","q":"后院骂声","lie":true,"a":"还能有谁？席怀山呗。台上一拍醒木，他隔墙就骂。今晚骂了三回，他活着，列位都听见。","truth":"是老黑。席怀山十九点四十七分就倒在后院了。我掀了鸟的罩布，排练十天，它一听醒木就骂。"},{"id":"t_robe","q":"为何换灰袍","lie":true,"a":"蓝袍送洗了，灰袍是排练时穿的。台上穿什么不要紧，嘴上功夫才要紧，哪个看过我的袍子？","truth":"蓝袍右袖沾了他的血，我泡在铜盆里没洗净，只好换排练的灰袍上台。手背红，是在缸里涮的。"},{"id":"t_book","q":"鹤年书底","lie":true,"a":"师父手抄的书底，一直存在席掌柜账房里，保管得好，我信得过他。老友交情，不必多问。","truth":"被他卖了，三十八万，瞒我十二天。他当面说“一本破书，换个房顶”。那是我这一门唯一的香火。"},{"id":"t_other","q":"你怀疑谁","a":"郝掌柜二十点五十五分离席，邹老板二十一点零二分离席。席怀山二十一点零五分还在骂，要紧的是之后。"},{"id":"t_liu","q":"和阿禾","needs":["clue:c_gar2","ask:liu.t_cover"],"lie":true,"a":"阿禾？傍晚忙开张，我连话都没跟她说过一句。后院的鸟啊笼啊，是掌柜和她的事，与我无关。","truth":"是我叫她挪的。十九点十五分我撞见她哭，哄她把笼子挪到靠板壁的钩上。孩子什么都不知道。"},{"id":"t_end","q":"那本书","needs":["clue:c_hall3"],"a":"师父临终说“书在，门就在”。没了书，我说得再好也是无根浮萍，这一门到我这代就断了。"}],"confronts":[{"clue":"c_gar1","breaks":"t_voice","crack":true,"a":"他看着那块干石板，半晌才说：“雨十九点五十八分落。人躺着，雨是淋不到他身下的。”"},{"clue":"c_gar2","breaks":"t_liu","a":"“老黑……学得真像。”他低声说，“那孩子心实，叫她挪就挪，她不知道我要它做什么。”"},{"clue":"c_hall4","breaks":"t_voice","a":"他指节在袖里捏紧：“前头一拍，后头一骂……三十年的对口相声，到头来是这么个收场。”"},{"clue":"c_gu1","breaks":"t_robe","crack":true,"a":"“谁让你进我后台？”他沉默片刻，“那袖口是席怀山的血。我不想说，现在也由不得我了。”"},{"clue":"c_gu2","breaks":"t_prep","a":"他看着那碗凝皮的梨汤：“阿禾那丫头实心。汤没人动，我没在屋里。十九点三十八分，我下了后院。”"},{"clue":"c_stu1","breaks":"t_book","a":"他读到“叁拾捌万”和“我亲自去讲”：“他要在我背了三十年的台上，替自己的体面去讲。”"},{"clue":"c_gu4","breaks":"t_book","a":"“那是我没寄出去的信。”他怔住，“三天前砚秋心软告诉我，我才知道师父的书底早换了钱。”"},{"clue":"c_hall3","a":"他盯着那册包好的《书底》，半天才开口，声音极低：“肖兄买的？他买去做什么……难道是替我留着？”"},{"clue":"c_stu3","a":"他把祝词末尾读了两遍：“当面认……我等了十二天，他只差这一晚。”眼里有什么碎了。"}],"fallback":"这个，老朽就不知道了，列位还是问别人吧。"},{"id":"zou","name":"邹茂才","role":"茶商","age":54,"look":{"skin":"tan","hair":"slick","hairColor":"black","glasses":"none","beard":"goatee","outfit":"suit","acc":"pocketwatch","mood":"sly"},"bio":"云南来的茶商，供应半盏春的镇店老茶饼。自称整晚都在大堂陪客，只去过一次洗手间而已。","demeanor":"满口行话，一口一个“老弟”，赌咒发誓比谁都快。","topics":[{"id":"t_role","q":"你做哪行","a":"做了三十年茶，云南福建两头跑。今晚镇店茶，民国三十八年同兴号老饼，一饼八千，我老邹拿招牌担保。"},{"id":"t_who","q":"你怀疑谁","a":"药铺郝老板，三十万药材压手里，掌柜一句“暂缓”，他当场摔了盏。还有收租的隋大有。我老邹不干折本买卖。"},{"id":"t_hall","q":"开书前","lie":true,"a":"一直在大堂陪客，老弟。就二十一点零二分去了趟洗手间，二十一点二十几分回来，就这些。","truth":"我下了茶窖。十九点二十八分到五十八分在窖里收拾，二十一点零二分又下去一趟。我是怕你查我的茶。"},{"id":"t_tea","q":"镇店茶","lie":true,"a":"真的！民国三十八年同兴号，有凭有据，内飞票据都在。老弟尽管查，我拿三十年招牌担保，假一赔十。","truth":"是新压茶饼，染的，内飞我自己印的，骗了席掌柜四十万。他敬茶时一抿就说“这味儿不对，散场单聊”，我才慌了。"},{"id":"t_money","q":"那四十万","needs":["clue:c_stu2"],"a":"预付四十万，货到付清，账面干净。我再不济，也不会为四十万杀人。……我是说，我没杀人。"},{"id":"t_heard","q":"二趟下窖","needs":["clue:c_cel1"],"a":"二十一点零五分，通风栅上头“啪”一声，立刻有人骂“吵什么吵”，一拍一骂。我当老席还在撒气，没敢上去。"},{"id":"t_thump","q":"头趟下窖","needs":["clue:c_gar1","ask:zou.t_heard"],"a":"你翻出干石板，我也不捂了。十九点四十七八分，头顶“咚”一声，又“当啷”一响。我怕被撞见，没敢出去。"}],"confronts":[{"clue":"c_cel1","breaks":"t_hall","a":"他盯着自己歪扭的签名，笑僵在脸上：“嗨，我这字真丑。”他叹气，“行，我下过窖，两趟。”"},{"clue":"c_hall2","breaks":"t_hall","a":"他看着“四号座空，茶没动”：“这小丫头倒心细。”他搓搓手，“好吧，我不在座上，实话我给你。”"},{"clue":"c_cel2","breaks":"t_tea","a":"“谁让你翻我的窖！”他瘫坐下去，“染盆、内飞，都让你看见了。货是我做的手脚，可杀人我真没干！”"},{"clue":"c_cel3","breaks":"t_tea","a":"他盯着“每饼成本九十元”，嘴唇动了好几次：“五十饼，赚了三十九万。老弟，这两年茶行不景气。”"},{"clue":"c_gar1","a":"“干的？”他怔了怔，“二十一点零五分我在窖里听见他骂……”他停住，“那声‘咚’，我还当是桌子倒了。”"}],"fallback":"这个我老邹不懂，老弟别拿来唬我。"},{"id":"xiao","name":"肖仲谦","role":"老主顾","age":71,"look":{"skin":"light","hair":"short","hairColor":"white","glasses":"round","beard":"none","outfit":"vest","mood":"smile"},"bio":"退休语文教师，半盏春四十年的老茶客，常坐前厅一号位。称十八点十分入座后没挪过窝。","demeanor":"慢条斯理，爱引“当年”和诗句，被戳到心事便望着茶汤发呆。","topics":[{"id":"t_role","q":"您与半盏春","a":"四十年的老座位，靠窗第一张。老席那人嘴硬，心里有这间茶馆。今夜我是来讨一碗头道茶的。"},{"id":"t_seat","q":"一直在一号位","a":"十八点十分入座，没挪窝，我腿脚不便。郝掌柜坐旁边陪我下棋。阿禾十九点四十六分来添过水。"},{"id":"t_voice","q":"听到骂声","a":"听到三回，二十点四十、五十二、二十一点零五分，满堂笑。老席骂我四十年词从不重样，今晚三回却一字未变。"},{"id":"t_book","q":"与席银钱往来","lie":true,"a":"没有，喝喝茶，下下棋罢了。老席的账我从不问，我们读书人讲究这个，银钱上的事，不沾。","truth":"我买了鹤年书底，三十八万，十二天前的事，怕它出城。老席求我先瞒九龄。书我今晚带来，想散场后白送还他。"},{"id":"t_tan","q":"谭先生今晚","a":"怪。三十年穿蓝袍，今晚换灰的。他向来早半个钟头候场，今晚二十点差一分才上台，手背通红，端茶盏还在抖。"},{"id":"t_zou","q":"邹郝二位","a":"郝掌柜二十点五十五分去洗手间，近二十一点二十才回。邹老板十九点半不见人，二十一点零二分又走了。"},{"id":"t_end","q":"怎么看谭","needs":["clue:c_gu4"],"a":"九龄把师门看得比命重。他师父走时，他在灵前跪了三天。他要是知道书被卖了……我不敢往下想。"}],"confronts":[{"clue":"c_stu1","breaks":"t_book","a":"他沉默片刻，苦笑：“被你翻到了。老席千叮万嘱叫我瞒着九龄，我这读书人倒学会了撒谎。”"},{"clue":"c_hall3","breaks":"t_book","a":"“我的布包……那是我今晚要还给九龄的。”他说，“我花三十八万，为的是扉页那八个字。”"},{"clue":"c_gu4","a":"他读完信稿，闭上眼：“他是知道了。我若早一天告诉他，是不是……”后半句没说出口。"},{"clue":"c_stu3","a":"“当面认……”他念着，眼眶红了，“这老东西嘴硬了一辈子，临了还是认了。可惜没撑到散场。”"}],"fallback":"这个老朽不懂，你得去问问年轻人。"},{"id":"liu","name":"柳阿禾","role":"学徒","age":19,"look":{"skin":"tan","hair":"ponytail","hairColor":"black","glasses":"none","beard":"none","outfit":"apron","mood":"worried"},"bio":"半盏春新来四个月的学徒，负责添茶，也照看后院的八哥。她是发现尸体的人，说话直发抖。","demeanor":"声音发紧，爱先说“我、我”，被追问时低头绞围裙。","topics":[{"id":"t_role","q":"你做什么","a":"我、我是学徒，来了四个月。添水，擦桌，傍晚给后院的老黑喂食、罩布。掌柜是我远房舅公。"},{"id":"t_bird","q":"那只八哥","a":"老黑专学掌柜骂人。白天一拍手它就嚷“吵什么吵”。夜里罩上黑布它就睡了，一声不吭。"},{"id":"t_cover","q":"黑布是你罩的","lie":true,"a":"十八点半我亲手罩的，两道搭扣都扣了。掌柜说罩到散场，之后我没碰过那笼子，谁也不许碰。","truth":"……我碰过。十九点十五分，谭先生哄我把笼子从东头挪到靠板壁的钩上。我只挪了笼子，布没动。怕挨骂才瞒的。"},{"id":"t_vic","q":"掌柜待你","lie":true,"a":"掌柜待我好，教我认茶烫壶，从来没红过一次脸。我真的、真的没受过什么委屈，你别往那边想。","truth":"十九点十分，他发现我打碎镇店壶，我偷偷粘好藏起来，被他翻出。他骂得凶，说明天让我回乡下。我哭了，可没想害他。"},{"id":"t_soup","q":"送梨汤","needs":["clue:c_kit1"],"a":"十九点四十给谭先生送的。门虚掩，灯亮着，我喊了一声没人应，就把汤放在门内凳上，以为他去了洗手间。"},{"id":"t_serve","q":"开书后","a":"十九点四十五分以后我一直在前厅续水，簿子上都记着。肖老和郝老板都看见我了，我没去后院。"},{"id":"t_find","q":"怎么发现的","a":"二十一点三十二分我去请掌柜切糕，他趴在地上。我一叫，老黑也骂了一句“吵什么吵”，我忘不了。"},{"id":"t_tan","q":"谭先生问过","needs":["ask:liu.t_cover","clue:c_gar3"],"a":"他问过老黑是不是一听醒木就骂。我说厅里怎么吵它都不理，台上一响就嚷。他还问搭扣怎么解，我说一拉就开。"}],"confronts":[{"clue":"c_kit2","breaks":"t_vic","a":"她看着那把壶，眼泪涌出来：“我不是故意的，手一滑……怕被赶才偷偷粘。他骂我时我想钻地缝。”"},{"clue":"c_hall2","a":"“这是我记的。”她声音发抖，“十九点四十六分给肖老续水，二十点以后我一直在前厅。”"},{"clue":"c_gar2","breaks":"t_cover","a":"她看到东头那圈灰印，脸一白：“是我挪的。可我只挪了笼子，布没动，搭扣都扣着！除非有人专门去解……”"},{"clue":"c_hall4","a":"她低声说：“对，厅里怎么拍它都不理。这十来天谭先生在后头排书，它就认台上那一声。”"},{"clue":"c_gu3","a":"她顺着提纲念：“二十点四十、五十二、二十一点零五……这几个钟点老黑都骂了。”声音越来越轻。"},{"clue":"c_gar3","a":"她捧着黑布，指尖摩挲着搭扣布带：“这是我缝的搭扣。上头怎么有血……谁拿它擦手！”"}],"fallback":"我、我不太懂这个，你别吓我。"},{"id":"hao","name":"郝慎之","role":"药铺老板","age":49,"look":{"skin":"light","hair":"sidepart","hairColor":"black","glasses":"rect","beard":"none","outfit":"vest","acc":"tie","mood":"stern"},"bio":"对门药铺老板，与席怀山做了二十年邻居，谈药茶合伙一年。称坐三号位，只去过一趟洗手间。","demeanor":"精打细算，爱拿药理打比方，口头禅“这个嘛”。","topics":[{"id":"t_seat","q":"你坐哪儿","a":"三号位，肖老旁边，十九点零五分到的。下了一盘棋，输了三子。阿禾十九点四十八分给我续过水。"},{"id":"t_who","q":"你怀疑谁","a":"邹茂才。敬茶时掌柜皱了眉，他脸都白了，十九点半后就没见人影。这个嘛，亏心事做多了。"},{"id":"t_out","q":"中途离席","lie":true,"a":"二十点五十五分去洗手间，这个嘛，一泡尿的工夫，十来分钟就回来了，肖老能作证，我棋下到一半不会走远。","truth":"我去了后巷小门，想逼席怀山签药茶契约。二十点五十五分出去，二十一点二十回，在巷里抽了十来分钟烟，没进院。"},{"id":"t_quarrel","q":"谈崩了吗","lie":true,"a":"没有，一直融洽。这个嘛，生意不成仁义在，药茶的事慢慢来，我们两家从没红过脸，邻居抬头不见低头见。","truth":"谈崩了。他十七点说“药茶暂缓”，我压着三十万药材，当场摔了盏。一时气话，我没想过要他的命。"},{"id":"t_heard","q":"巷里听到","needs":["clue:c_hall2"],"a":"二十一点零五分，我在小门口听院里一声“吵什么吵！”我当他没消气，不敢进。这个嘛，声音偏高，像从檐下传来。"},{"id":"t_deal","q":"药茶生意","needs":["clue:c_stu2"],"a":"三十万药材，陈皮、菊花、茯苓、酸枣仁，合同没签，货先到了。这个嘛，缺一味，方子就废了。"}],"confronts":[{"clue":"c_hall2","breaks":"t_out","a":"他眨了眨眼：“……簿子上写得这么清楚。”他推推镜框，“好吧，我没去洗手间。肖老替我遮了回。”"},{"clue":"c_gar5","breaks":"t_out","a":"他盯着檐下的烟蒂，咽了口唾沫：“……是我的。这个嘛，站那儿不抽烟心里没底。我一步没迈进去。”"},{"clue":"c_stu2","breaks":"t_quarrel","a":"他脸色铁青：“三十万药材，说不要就不要。我是当场摔了盏。可摔盏跟杀人是两码事。”"},{"clue":"c_gar1","a":"“干的？”他愣住，“雨是十九点五十八分落的，可我二十一点零五分在门外明明听见他骂……不对劲。”"},{"clue":"c_gar2","a":"他听完鸟笼的描述，嘴张了张：“我二十一点零五分听到的骂声，是它？学得这么像？”一时说不出话。"}],"fallback":"这个嘛，我是外行，说不准。"},{"id":"sui","name":"隋大有","role":"收租人","age":52,"look":{"skin":"tan","hair":"cap","hairColor":"black","glasses":"none","beard":"stubble","outfit":"jacket","mood":"tired"},"bio":"替房东收租的跑腿人，半盏春欠了三个月房租。自称二十点半才到，进来后坐后排蹭酒席。","demeanor":"北方口音的粗直，爱说“咱”“甭”，一激动就掰着手指算账。","topics":[{"id":"t_rent","q":"欠了多少","a":"三个月，九万。房东撂话了，月底前补不上就收回铺子。咱劝过席掌柜，可他那人宁折不弯。"},{"id":"t_who","q":"你怀疑谁","a":"咱不懂。可那位卖药的，二十点五十五分就溜了，二十一点二十才回来，神色不对。那位茶商脸白得像纸。"},{"id":"t_come","q":"何时到的","lie":true,"a":"二十点半才到，进前厅领了碗茶，坐后排。开张的大日子，哪好意思上门要租？甭提了甭提了。","truth":"十九点半就到了，走后巷小门，想赶在人多前堵他要租。他当场数了九万现钱，十九点三十八分我走，那时他还好好的。"},{"id":"t_seen","q":"他当时怎样","needs":["clue:c_stu2"],"a":"嘴上骂咱不会挑日子，手上利索，点心匣里数出九万。一身深灰夹袄，没穿长衫。石桌上那杯茶还冒着热气。"},{"id":"t_door","q":"后巷小门","a":"那门只能从里头闩，外头闩不上。进去是席掌柜自己开的，咱出来顺手拉上，没法落闩，也没多想。"},{"id":"t_after","q":"离开后","a":"巷口老李小卖部买了包烟，十九点四十一分的收银条还在兜里。后来在巷口檐下躲雨，雨停才进前厅。"}],"confronts":[{"clue":"c_stu2","breaks":"t_come","a":"他瞅着“19:36 付房租九万，隋大有签收”，挠头：“唉，钱都叫人记了账。是，咱十九点半就来了。”"},{"clue":"c_gar2","a":"他伸头看了一眼笼子：“咱走的时候，那笼子上头还罩着黑布呢，里头悄没声。谁给揭的？”"},{"clue":"c_gar1","a":"他嘟囔：“干的？咱十九点三十八分走时他还好好的，天上连点云都没有，没见着下雨。”"},{"clue":"c_gar3","a":"他凑近看了看：“就是它。咱走的时候它还好好罩在笼子上。后来谁摘的，别算咱头上。”"}],"fallback":"这玩意儿咱不懂，甭拿来问咱。"},{"id":"zhong","name":"钟砚秋","role":"账房","age":45,"look":{"skin":"light","hair":"bun","hairColor":"black","glasses":"rect","beard":"none","outfit":"jacket","mood":"stern"},"bio":"席怀山的外甥女，半盏春的账房先生。自称开书前一直在大厅招呼来客，一步都没离开过。","demeanor":"短句，数字先行，口头禅“白纸黑字”，被问到家事就收紧下巴。","topics":[{"id":"t_role","q":"你管什么","a":"账。进项出项，白纸黑字，没有一笔糊涂。翻修超了六十二万，我一笔笔压着，没让舅舅伤了脸面。"},{"id":"t_order","q":"他最后露面","a":"十九点二十，他回后院说要改祝词，“二十一点三十分前别来烦我”。所以前厅没人去后院。"},{"id":"t_hall","q":"开书前","lie":true,"a":"我一直在前厅招呼客人，十九点二十后也没离开过，二十点开书我就坐在柜台边。白纸黑字，肖老可以作证。","truth":"十九点二十五分到二十点，我一个人在账房重做现金账。这段时间没人能证明，所以我撒了谎。"},{"id":"t_told","q":"书底的事","lie":true,"a":"什么书底？我只管银钱的账，舅舅的那些书我从不碰，也从没跟谁提过这事，你问错人了。","truth":"我知道。三天前我告诉了谭先生，他还问开张夜舅舅是否整晚守后院，我说改祝词到散场。我怕是我的话害了舅舅。"},{"id":"t_money","q":"翻修账","needs":["clue:c_stu2"],"a":"超支六十二万：欠邹老板四十万茶款，郝老板三十万备料，房东九万租。舅舅说开张夜后一笔笔还。"},{"id":"t_bird","q":"八哥晚上","a":"老黑白天吵，罩了布就睡。舅舅最疼它。这十来天谭先生排练，老黑跟着凑热闹，我们都笑。"}],"confronts":[{"clue":"c_stu2","breaks":"t_hall","a":"她看了眼“19:50 记”：“那是我的字。好，十九点二十五分到二十点，我在账房，没人看见。”"},{"clue":"c_gu4","breaks":"t_told","a":"她读完信稿，肩膀塌下来：“他连我的名字都写上了。是，三天前我告诉他的。他一点声响都没有。”"},{"clue":"c_stu1","a":"她看着收据，声音哑了：“这是我抄进账的。舅舅的字我认得。他说过，开张夜后一定说。”"},{"clue":"c_stu3","a":"“祝词他改了三遍。”她轻声说，“最后几行我没敢看。他嘴上硬了一辈子，心里是软的。”"},{"clue":"c_hall3","a":"她脸色变了：“肖老买下的？舅舅说卖给了外地藏家……”她把话咽回去，“谭先生要是知道……”"}],"fallback":"这个与账无关，我不方便说。"},{"id":"ge","name":"葛有福","role":"点心师傅","age":58,"look":{"skin":"light","hair":"bald","hairColor":"grey","glasses":"none","beard":"none","outfit":"apron","mood":"smirk"},"bio":"半盏春灶上三十年的点心师傅，做了今夜的八层开张糕。自称整晚都没离开过厨房，只隔门听热闹。","demeanor":"嗓门大，爱抱怨，口头禅“哎哟喂”“我老葛”，被问急了先骂菜刀。","topics":[{"id":"t_role","q":"做什么点心","a":"哎哟喂，我老葛灶上三十年，桂花糕、芙蓉酥、八层开张糕。今晚那糕蒸了十四个钟头，手都不敢抖。"},{"id":"t_bird","q":"后院那只鸟","a":"那畜生！灶台一响它就隔墙骂“吵什么吵”，把我当成谭先生了。掌柜惯着它。夜里罩上布就消停。"},{"id":"t_kitchen","q":"一直在厨房","lie":true,"a":"没出过厨房，灶上离不开人。蒸笼、烤箱、切糕，哪样不得我盯着？哎哟喂，我老葛一步没挪过窝。","truth":"十九点五十分到二十点，我去后门台阶抽烟了。戒了又抽。掌柜最恨厨房有烟味，我才躲出去。"},{"id":"t_loyal","q":"打算干下去","lie":true,"a":"那还用说？半盏春是我老葛的家，我这把年纪还能去哪？掌柜待我不薄，我死也死在这灶上。","truth":"我接了对岸“听潮阁”的聘书，月薪八千，比这儿多三千。掌柜一直不涨，我想开张夜后再提辞。"},{"id":"t_saw","q":"后院所见","needs":["clue:c_kit3"],"a":"十九点五十三分，荷花缸边有个弯腰的人影，袖子挽着，穿深色长衫。我当是掌柜，可他今晚穿夹袄。"},{"id":"t_liu","q":"阿禾今晚","a":"那丫头傍晚摔了壶，哭了一场。十九点四十送汤上楼，下来就进前厅续水，一晚上没闲着。"}],"confronts":[{"clue":"c_kit3","breaks":"t_kitchen","a":"他挠头：“哎哟喂，烟头都让你捡着了……我老葛认，我就是在后门台阶上坐了一会儿。”"},{"clue":"c_kit4","breaks":"t_loyal","a":"他想夺信又缩回手：“你都翻着了。我不是忘恩负义的人，可三千块一个月，我老婆等着我寄钱。”"},{"clue":"c_gar3","a":"“这布我见过，是罩老黑的。”他嘀咕，“晚上罩白天摘，可今晚是谁把它塞到缸后面去的？”"},{"clue":"c_gar1","a":"他盯着“深灰夹袄”，嘴唇发抖：“我十九点五十三分在缸边看见的，穿的可是长衫。哎哟喂……”"}],"fallback":"我老葛是个做点心的，这个不懂，你问别人去。"}],"solution":{"culprit":"tan","method":{"q":"凶手如何造出“二十一点零五分他还活着”的假象？","options":["雨前行凶，让同伙在板壁后学死者骂人","雨前行凶，掀布让鸟听醒木学骂","趁听书入神，二十一点后潜入后院行凶","行凶后藏尸地窖，雨停再搬回后院"],"correct":1},"motive":{"q":"凶手为什么杀人？","options":["死者要拆说书台改作表演，辞退他","死者握有他冒充嫡传的把柄，要揭穿","他欠死者巨债，死者当晚逼他还清","死者瞒着他卖掉师父遗留的手抄书"],"correct":3},"keyClues":["c_gar1","c_gar2","c_gu1","c_stu1","c_kit1","c_hall1"],"truth":["凶手是说书先生谭九龄。席怀山死于雨前，十九点四十七分前后；二十点后的“掌柜骂声”，是八哥学的。","谭师父遗下手抄《书底》。席怀山为填翻修窟窿，卖给了肖仲谦，瞒了谭十二天。谭十九点三十八分下院质问，被一句“一本破书，换个房顶”激怒，抄铜壶砸死他。","谭早排练十天：八哥只认台上醒木，一拍就骂。他借阿禾挪近笼子，杀人后掀罩布、沉铜壶、泡血袍，换灰袍上台，再按提纲拍醒木。","假结论一：邹、郝有动机有谎话。干石板、淡茶、隋大有所见和“咚”声推翻它。假结论二：阿禾挪过笼子，可她在前厅续水，且厅里拍桌八哥不应，只有台上醒木灵。","破绽：梨汤没动，铜盆血袖，换灰袍，手背通红，葛师傅见长衫人影。可悲的是，席祝词写着“散场后当面认”，肖带来要还的书，就在台下。"]}},{"id":"wedding","title":"婚礼前夜","tagline":"明天就是婚礼，今夜暖房的兰花下，躺着新郎的哥哥，还有一只空了的戒指盒。","difficulty":2,"cover":"coverWedding","tone":"red","brief":"十月十六日夜，郊外白鹭庄园。周子恒与林若溪明天在这里办婚礼，今晚是彩排晚宴。你受新郎之父周振国之托，来做婚礼的“安保顾问”，刚到就撞上命案：总策划、新郎的兄长周明哲死在花园暖房里，周家传了三代的钻戒也不见了。警方封锁了庄园。周振国把你拉到一旁，压低声音说：“天亮之前，我要知道是谁干的。明天的婚礼，也许还办得成。”","victim":{"name":"周明哲","desc":"36岁，婚礼工作室创办人，这场婚礼的总策划，新郎同父异母的兄长。他倒在暖房兰花架旁，后脑遭钝器重击。","look":{"skin":"light","hair":"short","hairColor":"black","glasses":"rect","beard":"none","outfit":"suit","acc":"tie","mood":"neutral"}},"relations":{"heming":"新郎的发小，今晚的伴郎，管着递戒指","luye":"请来的摄影师，和他合作过不少婚礼","ziheng":"死者同父异母的弟弟，明天的新郎","ruoxi":"弟媳，明天的新娘，婚礼由他一手策划","zhen":"死者的父亲，新郎的父亲","xiaotang":"新娘的伴娘，筹备婚礼时常碰面","guyan":"新娘的前任恋人，今晚不请自来","hanbo":"庄园管家，替周家打理多年"},"links":[{"a":"ziheng","b":"ruoxi","text":"明天就要结婚的新郎新娘"},{"a":"ruoxi","b":"guyan","text":"前任恋人，已分手多时"},{"a":"ziheng","b":"heming","text":"穿一条裤子长大的发小"},{"a":"ziheng","b":"zhen","text":"亲生父子"}],"deathReport":{"time":"约 21:00–21:30","cause":"后脑遭钝器重击，颅脑损伤致死","scene":"管家韩伯 21:55 去关暖房加湿系统，发现周明哲倒在兰花架旁，已无呼吸，随即报警。","loc":"garden","notes":["后脑一处钝器伤，一击致命","现场的铜喷壶沾有血迹","花架上的戒指盒敞开，里面是空的","手表停在心率归零的时刻"]},"publicFacts":["死者周明哲是婚礼总策划，也是新郎的兄长，死因是后脑钝器伤，现场有沾血的铜喷壶。","彩排结束后，伴郎把戒指盒交给周明哲保管；现在盒子是空的，戒指不见了。","周明哲的智能手表与手机自动校时，心率 21:19 归零，警方据此认定死亡时间。","从宴会厅步行到暖房要四五分钟；另有一条月季小路连着后厨后门。","庄园只有大门一个出入口，由管家登记；警方到场前没人离开，也没有外人闯入的痕迹。"],"timeline":[{"t":"18:30","text":"彩排仪式结束，伴郎把戒指盒交给周明哲保管。"},{"t":"19:00","text":"彩排晚宴在白鹭厅开席，约三十位亲友入座。"},{"t":"20:38","text":"门岗登记：新娘前任顾衍到达，无请柬，经周明哲同意放行。"},{"t":"21:05","text":"据同桌宾客称，周明哲前后离席，说去暖房看花。"},{"t":"21:19","text":"周明哲的智能手表记录到心率归零。"},{"t":"21:40","text":"因新郎迟到，彩排蛋糕此时才开始切。"},{"t":"21:55","text":"管家去关暖房加湿系统，发现尸体并报警。"},{"t":"22:20","text":"警方到达，封锁庄园。"}],"budget":{"search":12,"ask":30},"locations":[{"id":"garden","name":"花园暖房","scene":"garden","desc":"庄园后花园深处的玻璃暖房，湿热，满是兰花香。黄色警戒带拦在门口。","clues":[{"id":"c_gh1","title":"死者与智能手表","text":"周明哲倒在兰花架旁，后脑有钝器伤，铜喷壶沾着血。他的手表心率 21:19 归零，表与手机自动校时，是准的。"},{"id":"c_gh2","title":"半朵被踩的胸花","text":"尸体右手旁有半朵踩碎的白兰胸花，银针弯了，针上缠着一截蓝缎带。"},{"id":"c_gh3","title":"空戒盒与放大镜","text":"花架上的丝绒戒指盒敞开着，里面是空的。地上有一只十倍放大镜，挂绳系着“明哲婚礼”铭牌。"},{"id":"c_gh4","title":"门边的细烟头","text":"暖房门边盆土里按着三个新烟头，滤嘴有玫瑰色口红印。旁边泥地有一行细高跟鞋印，进了门口又折返。"}]},{"id":"hall","name":"门厅与露台","scene":"hall","desc":"庄园正门的大门厅，连着朝花园敞开的石砌露台。厅里摆满明天要用的花艺。","clues":[{"id":"c_hall1","title":"胸花清单","text":"签到台上的花艺清单：“新郎·白兰·白缎带；伴郎·白兰·蓝缎带；新郎父亲·白兰·金缎带。18:00 前别好。”"},{"id":"c_hall2","title":"捧花里的字条","text":"新娘的捧花里夹着字条：“若溪，我在花园长椅等你，最后一次，就五分钟。——衍”。纸角沾着红酒渍。"},{"id":"c_hall3","title":"露台烟灰缸","text":"露台烟灰缸里有四个同牌子的烟头，多数只抽一半。栏杆下有一只刻着“白鹭庄园”的银色打火机。"}]},{"id":"dining","name":"白鹭厅宴会厅","scene":"dining","desc":"彩排晚宴的会场，长桌上还摆着甜品和香槟杯。一角堆着摄影器材，蛋糕立在推车上。","clues":[{"id":"c_din1","title":"摄影师的相机回放","text":"相机回放停在一张照片：贺铭举杯大笑，背后墙上圆钟入了半边画面。信息栏写着 21:21，他左翻领有个针孔。"},{"id":"c_din2","title":"墙上的挂钟","text":"你用手机对照宴会厅的圆钟，时分完全一致。管家说这是石英钟，每周一校准，这几天没人碰过。"},{"id":"c_din3","title":"彩排流程表","text":"流程表：“21:00 自由交流；21:30 切蛋糕；22:00 散场。”红笔改过：“新郎迟到，蛋糕推迟到 21:40。”"}]},{"id":"guestroom","name":"新郎伴郎休息间","scene":"guestroom","desc":"二楼走廊尽头的休息套间，沙发上堆着衣袋和行李包，衣架挂着明天的礼服。","clues":[{"id":"c_gr1","title":"珠宝店取件单","text":"新郎礼服袋里有“琢玉轩”取件单：经手人贺铭，9月3日送修，5日取件。末尾手写：“加订锆石仿品一枚，付款人贺铭。”"},{"id":"c_gr2","title":"伴郎的行李袋","text":"贺铭的行李袋里有两份文件：借款三十六万、10月18日到期的协议；以及9月6日“裸钻1.8克拉，回收价22万”的收据。"},{"id":"c_gr3","title":"揉皱的意向书","text":"新郎内袋里有一张被揉皱的《股权转让意向书（草稿）》：周振国转让51%股份给周明哲，日期是本周六。"}]},{"id":"kitchen","name":"后厨与酒窖口","scene":"kitchen","desc":"庄园后厨，灶台上还有没洗的餐具。后门通向碎石小路，墙角小门通酒窖。","clues":[{"id":"c_kit1","title":"后门水槽的毛巾","text":"水槽边挂着湿毛巾，沾着淡红水渍和黑泥。厨师记录：“21:30 前后，一位穿深色礼服的先生进来冲手，说被花刺划了。”"},{"id":"c_kit2","title":"酒窖出入簿","text":"出入簿上 20:55 写着：“2009年波尔多红一瓶，取用人：韩。”备注空白，今晚的酒水清单里没有这款酒。"},{"id":"c_kit3","title":"后门的月季小路","text":"后门外的小路穿过月季丛，直通暖房侧门，枝条新折，脚印杂乱。中段锦鲤池的石沿有一处青苔刚被蹭掉。"}]},{"id":"study","name":"管家办公室","scene":"study","desc":"庄园一楼的小办公室，墙上挂着钥匙，桌上有门岗登记本和周明哲的策划文件夹。","clues":[{"id":"c_stu1","title":"门岗登记本","text":"登记本：“20:38 顾衍，无请柬，策划师口头放行，车尾号7K”，出场栏空白。管家说这辆车一直没开出大门。"},{"id":"c_stu2","title":"策划文件夹","text":"待办写着：“21:05 暖房：戒指再看一遍（带放大镜）。有话问取件的人。”夹着他与苏小棠的拍立得，背面“7.14 我的小棠”被划掉一半。"},{"id":"c_stu3","title":"婚礼预算核对表","text":"核对表红圈：“9月28日，婚礼专户转出32,000元至‘顾衍’，授权人：林若溪。”旁注“明天前找她谈”。"},{"id":"c_stu4","title":"律师名片与预约","text":"名片背面手写：“周六08:00，送文件至庄园，周振国先生，51%股份，婚礼前勿告知子恒。”"},{"id":"c_stu5","title":"保安交班记录","text":"交班记录：“21:15 巡前院，7K车内有人，敲窗叫醒；21:22 再巡，人醒着。”背面路线图标注：停车场到暖房约8分钟。"}]}],"suspects":[{"id":"ziheng","name":"周子恒","role":"新郎","age":29,"look":{"skin":"light","hair":"short","hairColor":"black","glasses":"none","beard":"none","outfit":"suit","acc":"flower","mood":"worried"},"bio":"周家小儿子，明天的新郎，周明哲同父异母的弟弟。他说晚宴中途一个人去了露台，直到蛋糕环节才回。","demeanor":"老实、短句，容易叹气，被戳到痛处会突然提高音量。","topics":[{"id":"t_rel","q":"和哥哥感情","a":"他大我七岁，小时候我闯祸他替我挨打。我的婚礼方案他改了十几稿，没一句怨言。没想到今晚是最后一面。"},{"id":"t_quarrel","q":"今晚吵过吗","lie":true,"a":"没有，我们兄弟从不吵。他还帮我张罗整场婚礼，我怎么会跟他吵？警官，你是在怀疑我吗？","truth":"吵了，20:15 在走廊。爸要把51%股份给我哥，我说“凭什么”，摔门去了露台抽烟。那成了我跟他的最后一句话。"},{"id":"t_where","q":"21点后在哪","a":"露台，一个人抽烟。韩伯 21:12 到 21:22 陪我站了会儿。他走后我又站了很久，下楼时蛋糕在等了。"},{"id":"t_ring","q":"谁送戒指清洗","needs":["clue:c_gr1"],"a":"贺铭，他说顺路，我就把单子给他了。仿品？我真不知道，他是我最好的兄弟，我没理由怀疑他。"},{"id":"t_bride","q":"若溪异常吗","a":"她这半个月老是接了电话就躲着我，我以为是婚前焦虑，没敢问。你别说是我讲的，行吗。"},{"id":"t_share","q":"股权意向书","needs":["clue:c_gr3"],"a":"下午我在爸书桌抽屉翻到的。爸选他我认，可瞒着我，这口气咽不下。但他是我哥，我下不了手。"}],"confronts":[{"clue":"c_gr3","breaks":"t_quarrel","a":"他攥住那张纸，指节发白。“你们连这个都翻出来了。我是吵了，但吵完就去露台，没碰过他一根手指。”"},{"clue":"c_gh2","a":"他摸了摸自己胸前的花，白缎带，完好。“不是我的。可你们是不是已经觉得，我哥的事跟我有关？”"},{"clue":"c_kit1","a":"“深色礼服今晚一大半人都穿。21:30 前后我在露台吹风，没人作证，我知道这听着像什么。”"},{"clue":"c_gh1","a":"听到“21:19”，他僵住了。“那会儿我在露台，韩伯在旁边。我哥死的时候，我正在怨他。”"}],"fallback":"这个……我没见过，也不太明白，你问问别人吧。"},{"id":"ruoxi","name":"林若溪","role":"新娘","age":27,"look":{"skin":"fair","hair":"long","hairColor":"black","glasses":"none","beard":"none","outfit":"dress","acc":"necklace","mood":"sad"},"bio":"明天的新娘，小学美术老师。她说晚宴后回二楼化妆间换鞋歇脚，直到切蛋糕环节才下楼。","demeanor":"轻声细语，爱说“对不起”，紧张时会咬嘴唇、绞手指。","topics":[{"id":"t_rel","q":"和明哲的关系","a":"他像我另一个哥哥。选场地跑了二十多家，只因我随口说想要有暖房的庄园。对不起，我眼睛又……"},{"id":"t_where","q":"21点后在哪","a":"二楼化妆间，换了双鞋，坐着静一静，21:30 才下楼。一个人，没人作证，对不起。"},{"id":"t_exmeet","q":"见过顾衍吗","lie":true,"a":"没有……我根本不知道他今晚会来。我们早断了，号码都删了。别往他身上想，他不是坏人。","truth":"见了。20:50 在花园长椅，五分钟。他喝了酒，求我别嫁，我让他走。怕子恒误会才瞒着，对不起。"},{"id":"t_money","q":"婚礼专户那笔钱","lie":true,"needs":["clue:c_stu3"],"a":"那笔钱我不清楚，预算都是明哲哥管的，可能是工作室周转吧。对不起，我对数字不敏感。","truth":"是我转的三万二。顾衍欠赌债被堵，哭着求我。20:30 明哲要我明天前向子恒坦白，我很怕，但没伤害他。"},{"id":"t_ringfeel","q":"试戴过戒指吗","a":"9月底子恒让我试戴过一次，觉得有点轻，还以为是改了圈口的缘故。难道真的有问题吗？"},{"id":"t_ringmiss","q":"戒指失踪","a":"那是子恒奶奶留下的心意。可我更在意明哲哥。戒指没了可以再买，人没了就真的没有了。"}],"confronts":[{"clue":"c_hall2","breaks":"t_exmeet","a":"她手指绞紧。“是他写的。我去了，只坐了五分钟。我怕子恒误会才没说。对不起，我是不是毁了所有人的信任？”"},{"clue":"c_stu3","breaks":"t_money","a":"她脸色发白，眼泪滑下来。“明哲哥连这个都记着……他那样哭，我没办法。我从没想过要他死。”"},{"clue":"c_gr1","a":"“仿品？”她愣住，“难怪那天我戴上总觉得轻飘飘的。是谁换的？子恒他知道吗？天哪。”"},{"clue":"c_gh3","a":"她看着空戒盒。“他拿着放大镜……明哲哥一向细心，发现什么，会先自己弄清楚再告诉我们。”"}],"fallback":"对不起，这个我不太清楚，我现在脑子里一片空白。"},{"id":"zhen","name":"周振国","role":"新郎之父","age":63,"look":{"skin":"tan","hair":"sidepart","hairColor":"grey","glasses":"rect","beard":"mustache","outfit":"suit","acc":"pocketwatch","mood":"stern"},"bio":"周氏建材创始人，两兄弟的父亲。他说晚宴上陪亲家寒暄，之后找了个安静的地方抽雪茄。","demeanor":"威严、说话慢，爱训人，一口一个“年轻人”，嫌烦时直接敲桌子。","topics":[{"id":"t_rel","q":"怎么看两个儿子","a":"老大稳，老二浮。我从没偏心，只是做生意，要用最合适的那个人，这没错，年轻人，别多想。"},{"id":"t_where","q":"21点后在哪","a":"21:05 前陪亲家，之后去管家办公室抽雪茄，到 21:40。韩伯中间添过一次茶。我老了，嫌吵。"},{"id":"t_lawyer","q":"找过律师吗","lie":true,"needs":["clue:c_stu4"],"a":"没有。家里的事我现在没打算动，也没老糊涂到婚礼前夜办这种事。年轻人，别拿这话激我。","truth":"找了。周六早八点，林律师送文件，把51%股份给明哲。我想婚礼后再跟子恒说。没想到明哲走在我前面。"},{"id":"t_aware","q":"子恒知情吗","needs":["ask:zhen.t_lawyer"],"a":"他下午翻过我的抽屉，我是知道的，只是没点破。今晚他摔门，我就猜他是看见了。唉，造孽。"},{"id":"t_ring","q":"戒指值多少","a":"一点八克拉老矿钻，去年估价四十多万。更值钱的是老太太的心意。谁偷了，我追到天涯海角。"},{"id":"t_blame","q":"你怀疑谁","a":"两个儿子脾气冲，但杀人，不会。我倾向外人，那个前任小子大半夜还赖在庄园，难说他安的什么心。"}],"confronts":[{"clue":"c_stu4","breaks":"t_lawyer","a":"他看了名片很久，声音沙哑：“是，我要把股份给明哲。想等婚礼过了再说，是我糊涂。”"},{"clue":"c_gr3","a":"“这张纸在老二手里？”他颓然，“难怪他摔门。我安排了一辈子，却一句话都没交代清楚。”"},{"clue":"c_gr1","a":"“传家宝被换成假的？谁敢！”他敲桌的手停住，“贺铭经手的？他和子恒穿一条裤子长大，我没往那边想过。”"},{"clue":"c_hall3","a":"“这打火机刻着庄园的名字，不是我的。我抽雪茄，不抽这种细烟。年轻人，别把我也圈进去。”"}],"fallback":"这种东西，年轻人，你拿来问我，不如去问管家。"},{"id":"xiaotang","name":"苏小棠","role":"伴娘","age":26,"look":{"skin":"light","hair":"ponytail","hairColor":"brown","glasses":"none","beard":"none","outfit":"dress","acc":"earrings","mood":"sly"},"bio":"新娘的表妹，护士，首席伴娘。她说自己整晚都在餐厅里帮表姐盯流程，从没单独离开过。","demeanor":"咋咋呼呼，爱用网络词（破防、emo、绝了），慌了就笑得更大声。","topics":[{"id":"t_rel","q":"和新娘的关系","a":"若溪是我表姐，一起长大的，这伴娘我当得心甘情愿！累得脚都肿了。救命，婚礼还办得成吗？"},{"id":"t_where","q":"21点后在哪","lie":true,"a":"一直在餐厅呀！帮若溪盯蛋糕，还跟贺铭他们闹。不信问陆野，他到处拍我！你不会怀疑我吧？","truth":"撒谎了。21:00 我溜去暖房门口抽烟，到 21:07。明哲一个人在看戒指，说“在等人”，让我先走。我怕被姨妈撞见。"},{"id":"t_affair","q":"和明哲熟吗","lie":true,"a":"不熟呀，就工作对接，顶多一起开过几次会。你问这个干嘛，我才不会为这种事难过呢，绝了！","truth":"……交往过两个多月，7月14号开始的。上个月他说“工作太忙”提了分手。我没恨他，就是难受，破防了。"},{"id":"t_bride","q":"新娘最近怎样","a":"我表姐这半个月可 emo 了，老接了电话就躲着打。她那个前任也真是，阴魂不散的。"},{"id":"t_shoes","q":"今晚穿什么鞋","needs":["clue:c_gh4"],"a":"银色细高跟，好看吧？鞋印是我的，我承认。但我只在门口抽烟，真没往里面看，别想太多！"},{"id":"t_ringmiss","q":"戒指失踪","a":"肯定被人偷了呗，那么贵谁不动心？宴会厅人来人往，盒子又不在新人手里，谁防得住啊！"}],"confronts":[{"clue":"c_gh4","breaks":"t_where","a":"她盯着口红烟头，笑声卡在嗓子里。“……行吧，是我。就抽了三根。那会儿明哲哥明明还好好的啊！”"},{"clue":"c_stu2","breaks":"t_affair","a":"她捏着拍立得，眼眶红了。“他居然还留着……好吧，我们谈过恋爱，分手那天我哭了一整晚。但我对他只有难过。”"},{"clue":"c_gh3","a":"“放大镜？我走的时候他就拿着它对着戒指转，脸色特别难看。他是不是看出了什么呀？”"},{"clue":"c_hall1","a":"“蓝缎带是伴郎的，我记得清楚，是我提醒花艺师别弄混的。怎么，这跟案子有关系吗？”"}],"fallback":"啊？这个我真不知道，别逼我，我已经很慌了！"},{"id":"heming","name":"贺铭","role":"伴郎","age":29,"look":{"skin":"light","hair":"slick","hairColor":"black","glasses":"none","beard":"stubble","outfit":"suit","acc":"flower","mood":"smile"},"bio":"新郎的发小，投资顾问，彩排时负责递戒指。他说整晚都在餐厅闹酒，只出去接过一个电话。","demeanor":"嘴碎爱开玩笑，一口一个“兄弟”，被问急了就讲段子打岔。","topics":[{"id":"t_rel","q":"和周家的关系","a":"我跟子恒穿一条裤子长大，明哲哥算半个亲哥。这婚礼全是他盯的……操，怎么就出事了。"},{"id":"t_where","q":"21点后在哪","lie":true,"a":"都在白鹭厅陪伴娘们闹，中间出去接了个电话。陆野还拍了我一张，21:21，举杯那张。","truth":"我撒谎了。21:08 我说接电话，其实走月季小路去了暖房。我和明哲吵到 21:19，推了他一把，抓起喷壶砸了下去。21:38 才回餐厅。"},{"id":"t_ring","q":"戒指经你手吗","lie":true,"a":"就跑个腿，送琢玉轩清洗改圈，5号取回来，原样交给了子恒。这种传家宝，我哪敢乱碰。","truth":"那枚是我订的仿品。真钻9月6日我就卖了，二十二万。想着婚后赚钱赎回来，没想到明哲一眼就看出来了。"},{"id":"t_money","q":"最近手头紧吗","lie":true,"a":"我吃的就是钱这碗饭，紧什么紧。今晚伴郎红包我包了两万六，你这问法，别拿我开涮啊。","truth":"紧得要命。我赌球借了三十六万，十八号到期，卖钻的钱只还了一部分。真的走投无路了。"},{"id":"t_flower","q":"你的胸花呢","lie":true,"needs":["clue:c_gh2"],"a":"掉了吧，闹得太疯，不知道蹭哪儿去了。不是，就一朵花而已，你们不会拿它来怀疑我吧？","truth":"是在暖房被扯掉的。明哲死抓我领口，胸花连针被他拽下来。我慌了没敢捡，只拿走戒指盒里的东西。"},{"id":"t_photo","q":"21:21的照片","lie":true,"needs":["clue:c_din1"],"a":"陆野顺手拍的。他吃这碗饭的人，相机时间还能有假？您别疑神疑鬼的啊，我就是个伴郎。","truth":"我知道他的相机慢了二十分钟，20:55 他自己抱怨过。我 21:38 回来，趁乱叫他拍一张，好显得我当时还在餐厅。"},{"id":"t_suspect","q":"你怀疑谁","a":"还用问？顾衍呗。前任闯进婚礼，不是抢人就是抢东西。再不然，就是子恒跟他哥吵翻了。"}],"confronts":[{"clue":"c_din1","breaks":"t_where","crack":true,"a":"他盯着屏幕，笑着开口：“21:21，我在笑，怎么可能……”目光滑到背景的挂钟，喉结一动，后半句没接上。"},{"clue":"c_kit1","breaks":"t_where","a":"“冲手而已。”他嗤笑，笑意却僵住，“穿深色礼服的满场一半，凭什么就是我？”他搓了搓指节。"},{"clue":"c_gh2","breaks":"t_flower","a":"他下意识摸了摸左翻领，那里只剩一个针孔。“蓝缎带的……行，您说是我的，那就是我的。”声音越来越低。"},{"clue":"c_gr1","breaks":"t_ring","a":"“仿品……订个仿品给新郎开玩笑，不行吗？”没人接话，他的笑声越来越小，“好吧，这玩笑开大了。”"},{"clue":"c_gr2","breaks":"t_money","a":"他肩膀垮了下去。“您翻我包了……对，我缺钱，缺得睡不着觉。伴郎红包都是跟别人借的。”"},{"clue":"c_din2","breaks":"t_photo","a":"“钟是准的……”他喃喃，又猛地抬头，“相机慢了，我哪知道！”声音刺耳，手指却在发抖。"},{"clue":"c_gh1","a":"听到“21:19”，他肩膀一震，又嬉皮笑脸：“这么准？可惜我那会儿在餐厅。”说得太快，像背过的台词。"}],"fallback":"这东西跟我有什么关系？兄弟，别为了破案瞎找人下嘴啊。"},{"id":"guyan","name":"顾衍","role":"新娘前任","age":30,"look":{"skin":"tan","hair":"messy","hairColor":"black","glasses":"none","beard":"stubble","outfit":"coat","acc":"scarf","mood":"tired"},"bio":"新娘的前男友，开酒吧的，没有请柬却来了庄园。他说和新娘聊几句就走了，后面的事一概不知。","demeanor":"带着酒气，嘴硬爱讽刺，江湖腔，自嘲时会苦笑一声。","topics":[{"id":"t_rel","q":"和新娘的关系","a":"前女友，处了四年。她爸妈看不上我，就分了。我今晚来真不是闹的，就想亲口说句祝福。"},{"id":"t_leave","q":"什么时候走的","lie":true,"a":"跟若溪聊了几句我就走了，大概九点前，回家睡了一觉。后面的事我一概不知，别往我头上扣。","truth":"没走。我喝多了开不了车，一直窝在停车场车里。21:30 左右看到个穿深色礼服的男人从暖房小路过来，在后厨后门冲手，没看清脸。"},{"id":"t_window","q":"车里能看到啥","needs":["ask:guyan.t_leave"],"a":"车正对主楼。二楼窗帘后有个人影一直坐着，应该是若溪。保安老赵九点一刻和九点二十二都来敲过窗。"},{"id":"t_terrace","q":"露台上有谁","needs":["ask:guyan.t_window"],"a":"两个人影，一个年轻的靠栏杆，一个穿马甲的老头站旁边，打火机嚓嚓亮。老赵两次来敲窗，他们都在。"},{"id":"t_letter","q":"字条是你写的","a":"是，托服务生塞进捧花的。丢人，可我没别的办法。她来坐了五分钟，一句话不松口，我就死心了。"},{"id":"t_money","q":"三万二的事","needs":["clue:c_stu3"],"a":"是我欠的赌债，她可怜我才转的，我会还。明哲要她坦白，说实话，我听着都觉得他是为她好。"},{"id":"t_suspect","q":"你觉得谁有问题","a":"我？第一眼怀疑的就是我这种人，我认。可我连暖房朝哪开门都没摸清，不信你们去查我鞋底。"}],"confronts":[{"clue":"c_stu1","breaks":"t_leave","a":"他盯着出场栏的空白，苦笑：“你们查得真细。行，我没走，坐在车里一杯接一杯灌，没勇气再进去。”"},{"clue":"c_stu5","a":"“老赵还写下来了？九点一刻，九点二十二，对得上。”他苦笑，“头一回被记在本子上还觉得踏实。”"},{"clue":"c_hall2","a":"“那是我写的。字丑吧，喝了点酒。她来了，坐了五分钟让我走，我是真想走，可腿不听使唤。”"},{"clue":"c_kit1","a":"他眼睛一亮：“对，就是这个点！那人从后门进去洗手，我还纳闷客人怎么往厨房钻。可惜没看清脸。”"}],"fallback":"这玩意儿我没见过。别看我，我比你们谁都想知道真相。"},{"id":"hanbo","name":"韩伯","role":"庄园管家","age":58,"look":{"skin":"light","hair":"bald","hairColor":"grey","glasses":"round","beard":"none","outfit":"vest","acc":"tie","mood":"neutral"},"bio":"白鹭庄园的管家，干了二十年的老管家。21:55 他去关暖房加湿系统，发现尸体并报了警。","demeanor":"稳重守规矩，话带老派敬语，被问到私事会含糊其辞，说“这个嘛”。","topics":[{"id":"t_role","q":"你做什么的","a":"庄园管家，二十年了。钥匙、门岗、酒水、客人起居都归我管。出了这种事，对不住周家。"},{"id":"t_found","q":"尸体是你发现的","a":"是。21:55 我去关暖房加湿系统，看见周先生倒在兰花架旁，颈脉已经没了。我马上报警，什么都没碰。"},{"id":"t_terrace","q":"见过新郎吗","a":"见过。21:12 到 21:22，我在露台给少爷递打火机，陪他站着。他眼圈红红的，没离开过我的视线。"},{"id":"t_ex","q":"前任怎么进来","a":"20:38 到门岗，没有请柬。周先生说放他进来，免得外面闹得难看，还嘱咐我登记。"},{"id":"t_door","q":"暖房锁门吗","a":"晚上不锁，要通风保湿。侧门通花园小径，另一头有月季小路直通后厨后门，熟悉庄园的人才知道。"},{"id":"t_wine","q":"酒窖缺东西吗","lie":true,"needs":["clue:c_kit2"],"a":"酒窖一切正常，一瓶没少。酒水都按清单走，您放心，我当了二十年的管家，没出过差错。","truth":"少了一瓶09年波尔多红，是我私自开的。20:55 心里发慌想压惊，只喝了一杯。怕丢饭碗没敢说，与命案无关。"},{"id":"t_tea","q":"周董在哪","a":"在我办公室抽雪茄。21:08 我送过茶，21:23 从露台回来续茶，他还坐着，雪茄烧了一半。"},{"id":"t_pond","q":"小路边的池子","needs":["clue:c_kit3"],"a":"锦鲤池，夫人当年挖的，水深一米多，池底铺着一层鹅卵石，掉进去的小东西根本找不着。"},{"id":"t_route","q":"去暖房要多久","a":"后厨小路走四五分钟，从露台下去五六分钟，从停车场绕过主楼七八分钟。这个嘛，谁熟悉庄园我不敢说。"}],"confronts":[{"clue":"c_kit2","breaks":"t_wine","a":"他脸慢慢红了。“这个嘛……是我。一瓶酒而已，不想让周董知道。但那会儿我都没离开庄园半步。”"},{"clue":"c_stu5","a":"“是老赵写的，我让他盯着那辆车。那位先生九点以后一直在车里没挪窝，这个我敢担保。”"},{"clue":"c_stu1","a":"“这是我登记的。我以为他走了，没想到车一直停在那儿。”他叹气，“年轻人，感情的事，唉。”"},{"clue":"c_kit3","a":"他蹲下看了看脚印。“这些月季是夫人亲手种的。人人踩过都有痕迹，可今晚来往的人太多，分不出是谁。”"}],"fallback":"这个嘛……我不太清楚，您还是问问别人吧。"},{"id":"luye","name":"陆野","role":"摄影师","age":32,"look":{"skin":"tan","hair":"messy","hairColor":"brown","glasses":"none","beard":"stubble","outfit":"jacket","acc":"badge","mood":"tired"},"bio":"长期合作的自由摄影师，负责全场抓拍。案发时他一直在餐厅里拍照，相机器材都放在桌边。","demeanor":"话少，懒洋洋，爱用摄影行话，被问到专业问题会立刻绷紧。","topics":[{"id":"t_role","q":"你负责什么","a":"全场抓拍。明哲哥交代多拍伴郎伴娘，说明天要剪短片。现在想想，这些片子要变遗物了。"},{"id":"t_clock","q":"相机时间准吗","lie":true,"a":"准。我出门前跟手机对过，一分不差。吃这碗饭，时间戳是我的底线，错了真的没法交片。","truth":"不准。20:55 我换电池，凭印象重设，慢了差不多二十分钟。怕老板扣尾款，我没敢说，只被贺铭听见过。"},{"id":"t_lapel","q":"伴郎的胸花","needs":["clue:c_gh2"],"a":"20:30 那张合影里他有，蓝缎带，别得挺正的。后面的我就不知道了，我只顾构图。"},{"id":"t_sisters","q":"拍到伴娘吗","needs":["ask:luye.t_clock"],"a":"伴娘团合影，屏幕显示 20:58，小棠在中间。相机慢二十分钟的话，就是 21:18，她们在餐厅。"},{"id":"t_request","q":"谁叫你拍的","needs":["clue:c_din1"],"a":"贺铭自己招手喊我的，说伴郎也该有张正经的，站位也是他挑的。墙上的钟入没入镜我没留意。"},{"id":"t_overheard","q":"有人知道慢了吗","needs":["ask:luye.t_clock","clue:c_din1"],"a":"换电池时我骂过一句“慢了二十分钟”，贺铭就在旁边端酒瓶，没吭声。……他是故意的？我什么都不知道。"},{"id":"t_ringshot","q":"拍过戒指吗","a":"交接时拍过特写。怪了，那颗老钻在灯下不怎么“冒火”，补拍也一样。明哲哥凑近看了很久。"}],"confronts":[{"clue":"c_din1","breaks":"t_clock","a":"他抢过相机，手停在半空。“墙上的钟……九点四十一？我的相机慢了。”他苦笑，“我装不知道，一晚上都心虚。”"},{"clue":"c_din2","breaks":"t_clock","a":"“钟是准的？”他抹了把脸，“那就是我的相机出事了。我怕老板念叨，没敢说。这算不算帮了谁的忙……”"},{"clue":"c_gh2","a":"他不敢多看那半朵花。“蓝缎带是伴郎的。我拍过特写，没想到会在这种地方再见到它。”"},{"clue":"c_din3","a":"“蛋糕推迟这事我印象特别深，新郎一直没回来，大家干等着，我拍了好几张无聊的脸。”"}],"fallback":"这东西我没拍过，也不太懂。构图我熟，案子我真不在行。"}],"solution":{"culprit":"heming","method":{"q":"凶手怎么做到的？","options":["假装去露台独处，实则折回暖房行凶，再找人作证","外人从侧门潜入偷戒指，被撞破后慌乱杀人","借口接电话抄小路行凶，用慢相机的照片造在场","取走死者手边的胸花后下手，故意留物嫁祸他人"],"correct":2},"motive":{"q":"为什么杀人？","options":["觊觎家传戒指，借彩排混乱抢夺，被撞破后失手杀人","偷换并卖掉传家真钻抵债，被死者识破后灭口","不甘心股份落到死者手里，想在婚礼前除掉对手","挪用婚礼专款被死者察觉，怕当众揭穿而铤而走险"],"correct":1},"keyClues":["c_din2","c_gh2","c_hall1","c_din1","c_gr1","c_gr2"],"truth":["凶手是伴郎贺铭。表面像为股份或戒指，实为灭口：他赌球欠债三十六万，9月借送修之机订了仿品，把周家真钻换掉卖了二十二万。","第一层假结论是新郎：他谎称没吵架，口袋里有股权意向书。但保安记录和顾衍证明，21:15与21:22露台上一直是他和管家；现场蓝缎带胸花是伴郎的，他的白缎带花完好。","第二层假结论是有人嫁祸伴郎：贺铭的照片显示21:21，晚于死亡。但照片里的挂钟是九点四十一，摄影师陆野换电池后相机慢了二十分钟，被贺铭听见。","21:08贺铭借口接电话，走月季小路去暖房。周明哲用放大镜看出戒指是假的，约他对质。两人争执到21:19，贺铭砸死了他，带走仿品，扔进锦鲤池。","21:38他回到餐厅，趁乱让陆野拍下这张照片，实际是21:41。死亡时间、蓝缎带、挂钟、取件单和借款收据，串起了证据链。"]}},{"id":"antique","title":"古董店","tagline":"镇店之宝纹丝未动，老掌柜却死在了后堂——这一夜，谁在替谁说谎？","difficulty":3,"cover":"coverAntique","tone":"sepia","brief":"一九九八年十月，省城老街。派出所来电：聚珍斋老掌柜谷鸿年昨夜死在后堂。镇店之宝宣德青花梅瓶仍立在展柜里，没人抢，也没人偷。所里还收到一张匿名条子：“聚珍斋有事瞒着”。你赶到时，学徒方小满脸色惨白守在门口，前堂灯还亮着，街对面几个街坊探头张望。你有十二次搜证、二十六次发问的机会。真与假之间，有人在撒谎。","victim":{"name":"谷鸿年","desc":"聚珍斋第三代掌柜，六十八岁，侧卧后堂太师椅旁，后脑凹陷，腕表碎裂停在九点十分。收音机仍大声放着评书。","look":{"skin":"light","hair":"short","hairColor":"white","glasses":"round","beard":"none","outfit":"robe"}},"publicFacts":["谷鸿年，68岁，聚珍斋第三代掌柜，合伙人是常永昌。","镇店之宝是宣德青花云龙梅瓶。1979年11月曾被盗，三天追回，学徒沈文清因此被判十年，1983年病死狱中。","10月21日，谷向省文物鉴定站递交梅瓶热释光检测委托，26日（周一）取样。","展柜铜锁完好，保险柜未动，没有劫财迹象。","凶器疑为案头铜镇尺。前后门均无撬痕。"],"relations":{"fang":"在店里跟了六年的学徒，昨晚锁的前门","li":"死者唯一的亲侄子，做建材生意","chang":"占三成股的合伙人，管账和对外联络","yu":"三十多年的老主顾，一直想买梅瓶","jiang":"拍卖行经理，想让梅瓶上拍代销","he":"住后巷的老街坊，从前摆馄饨摊","lin":"香港古玩商，来省城想买梅瓶","zhong":"隔壁裱画铺老板，三十年老邻居"},"links":[{"a":"li","b":"fang","text":"都盼着将来接手这家店"},{"a":"chang","b":"jiang","text":"常管账，一向由他对接拍卖行"},{"a":"jiang","b":"lin","text":"林想买梅瓶，由蒋居中联络"}],"deathReport":{"time":"约 19:30–22:00","cause":"后脑遭钝器重击，颅脑损伤致死","scene":"22:10 学徒方小满按约回店，在后堂发现谷倒在太师椅旁，已无气息，22:14 报警。","loc":"study","notes":["后脑一处钝器伤，一击致命","案头铜镇尺带血和白发，与伤口吻合"]},"timeline":[{"t":"19:30","text":"聚珍斋打烊，小满锁前门，谷留在后堂。"},{"t":"21:10","text":"谷的腕表停在这个时刻，表蒙碎裂。"},{"t":"22:10","text":"小满按约回店，发现谷倒在后堂。"},{"t":"22:14","text":"小满用店里电话报警。"},{"t":"22:40","text":"民警记录：后堂收音机音量被拧到最大。"},{"t":"23:05","text":"警医到场，确认后脑钝器伤致死。"}],"budget":{"search":12,"ask":26},"locations":[{"id":"hall","name":"聚珍斋前堂","scene":"hall","desc":"临街铺面，博古架与玻璃柜台。打烊后灯还亮着，正中展柜立着镇店之宝。","clues":[{"id":"c_hall1","title":"展柜里的梅瓶","text":"展柜里立着青花云龙梅瓶，釉色莹润，口沿光洁完整，底款“大明宣德年制”。铜锁完好。"},{"id":"c_hall2","title":"来客登记簿","text":"23日：15:20 俞鹤龄观瓶；17:50 蒋文彬谈代销，离店补写“19:15”。22日：16:00 港商林嘉明。"},{"id":"c_hall3","title":"鉴定委托回执","text":"鉴定站回执：梅瓶送热释光检测，26日（周一）到店取样，谷亲签，21日立。旁有蒋文彬的代销意向书，谷未签。"},{"id":"c_hall4","title":"柜台上的BP机","text":"BP机汉显：“叔，速回电！立群 20:52”。话机下压着便条：“十点，小满来”。"}]},{"id":"study","name":"后堂","scene":"study","desc":"前堂后面的小厅，太师椅、紫檀小几、多宝格。谷平日在此会客看货听收音机。","clues":[{"id":"c_study1","title":"碎表","text":"谷侧卧椅旁，后脑凹陷。腕表表蒙砸碎，停在9:10；表冠被拉到校时位，表壳背面光洁无磕碰。"},{"id":"c_study2","title":"警医的意见","text":"23:05 警医验尸：尸僵遍及大关节，尸斑指压不褪，死亡已两个半到三个半小时。案上铜镇尺带血和白发，与伤口吻合。"},{"id":"c_study3","title":"两只盖碗","text":"小几上两只盖碗：一只茶剩小半、有唇印；另一只斟满，冷膜浮面，盖子严合，没人动过。"},{"id":"c_study4","title":"开大的收音机","text":"收音机音量旋钮拧到底，远过旁边红纸上毛笔写的“三”字标记。保险柜锁着，没动过。"}]},{"id":"library","name":"账房与档案室","scene":"library","desc":"后堂旁的小屋，四壁是账簿货单，樟脑味很重。老书桌上摊着稿纸和一只铁盒。","clues":[{"id":"c_lib1","title":"信稿","text":"致公安局信稿（22日）：“沈文清非窃贼，是我私售真品、请人仿制、嫁祸于他……仿制之人尚在，已约周五夜再谈，盼同去投案。”"},{"id":"c_lib2","title":"旧照与剪报","text":"1979年9月旧照：梅瓶口沿内侧有米粒大补痕，旁站年轻学徒。剪报（11月5日）：学徒沈某落网，追回国宝。"},{"id":"c_lib3","title":"合伙分红账","text":"分红账上“常永昌”名下有三笔“私支”共三万元，谷批：“来路不明，限月底还清。”便条：“周五晚找老常谈。”"},{"id":"c_lib4","title":"铁盒里的汇款单","text":"汇款存根：1984年起每月80元，收款人贺秀英。另有判决书抄件：沈文清盗窃文物罪，判十年。"}]},{"id":"cellar","name":"地窖库房","scene":"cellar","desc":"店后的地窖，阴凉干燥，码着木箱旧家具，一盏昏黄灯泡吊在梁下。","clues":[{"id":"c_cel1","title":"旧木箱","text":"樟木箱里有1979年10月30日的旧报纸，压着宣纸条：残朱印只剩“缘斋”，背面铅笔字“口沿不补”，沾着干浆糊。"},{"id":"c_cel2","title":"麻布包","text":"空布包里有三张谷手写的货签：玉蝉、鼻烟壶、核桃，都被铅笔划了价。压着拍卖行收货单副本，经手人“蒋”。"},{"id":"c_cel3","title":"港商名片","text":"名片“林嘉明·香港嘉廷古玩行”，背面：“家父林廷芳1979年10月购得贵店梅瓶，凭据尚存，请一谈。10月22日”。"}]},{"id":"garden","name":"后院与夹道","scene":"garden","desc":"店后小院，有井和葡萄藤。院墙边小木门通向夹道，另一边是后门。","clues":[{"id":"c_gar1","title":"夹道小门","text":"小门内闩被拔开。门框离地一米处有两处发黏的灰白指印，门轴挂着碎纸屑。门外夹道脚印一浅一深。"},{"id":"c_gar2","title":"窗下烟头","text":"后堂窗下有三个被碾过的红塔山烟头，旁有一对宽皮鞋印，鞋头朝窗。"},{"id":"c_gar3","title":"后门钥匙板","text":"钥匙板挂钩标着“谷”“满”“常”：谷、满的钥匙在，“常”字钩空着。后门没插闩。"}]},{"id":"kitchen","name":"灶间","scene":"kitchen","desc":"后堂旁的小灶间，煤球炉、砂锅、碗柜，碗碟码得整整齐齐。","clues":[{"id":"c_kit1","title":"半碗面","text":"灶台上的阳春面只吃两三口，已凝出白油。竹食盒盖里贴红纸，写着“贺”。碗柜少了两只盖碗。"},{"id":"c_kit2","title":"诊断书与药","text":"省医院诊断书：谷鸿年，肺癌晚期，日期10月19日。旁边止痛片只剩几粒。"},{"id":"c_kit3","title":"灶间门口票根","text":"“金鼎录像厅”票根：10月23日 20:10 场，背面蓝戳“21:05 断片补映”。旁有蓝围裙，绣着“满”字。"}]}],"suspects":[{"id":"fang","name":"方小满","role":"店里学徒","age":26,"look":{"skin":"tan","hair":"messy","hairColor":"black","glasses":"none","beard":"stubble","outfit":"jacket","acc":"badge","mood":"worried"},"bio":"聚珍斋学徒，跟谷鸿年学了六年。昨晚是他锁的前门，十点回店，他是第一个发现尸体的人。","demeanor":"嘴快、慌张，爱说“哎呀”“师傅常说”，被问急了声音发飘。","topics":[{"id":"t_leave","q":"昨晚几点离店？","a":"七点半我锁前门，七点四十五从后院走。师傅说他还有客人。走时我听见常老板在后堂吼。"},{"id":"t_home","q":"离店后去了哪？","lie":true,"a":"我直接回家了呀，吃碗泡面就睡了。我住城南，一个人，没人能作证，可我真的没骗你们。","truth":"我没回家。去蒋经理家送了小货拿钱，又去金鼎录像厅看了八点十分那场。怕您当我偷师傅的东西，就瞒了。"},{"id":"t_stolen","q":"你动过店里的货吗？","lie":true,"a":"没有！师傅的货我碰都不敢乱碰，擦货都戴着白手套。你们不能因为我是徒弟，就怀疑我。","truth":"动过三回：玉蝉、鼻烟壶、核桃，卖了三百块。师傅说我靠不住，我想攒钱另找活路。人我真不敢杀。"},{"id":"t_return","q":"为什么十点回来？","a":"师傅前天交代：“十点你来一趟，有话同你说。”我准点到，推开后门，就看见他躺在地上……"},{"id":"t_fired","q":"师傅要说什么？","needs":["clue:c_hall4"],"a":"我猜是要赶我走。可那便条写得一笔一划的，也许他有话没来得及说完，这是我现在才想到的。"},{"id":"t_quarrel","q":"常老板吼了什么？","needs":["ask:fang.t_leave"],"a":"好像是“你查我的账凭什么”“三万块你要逼死我”。师傅的声音很低，我没敢多听，就从后院溜了。"},{"id":"t_film","q":"那晚放什么片？","needs":["clue:c_kit3"],"a":"港片。放到一半断片，灯亮了，老板还给前排退烟。九点过后重放，十点散场，我跑回的店。"}],"confronts":[{"clue":"c_kit3","breaks":"t_home","a":"他脸红到耳根。“中间断了片，九点过后才接着放，十点散场。”他挠头，“八点十分我就坐在黑厅里，我没杀人。”"},{"clue":"c_cel2","breaks":"t_stolen","a":"小满往后缩了一步。“货签是师傅写的，价是我划的。”他低下头，“我糊涂。可师傅出事，我比谁都怕。”"},{"clue":"c_study1","a":"“师傅最爱惜这块表，睡觉都不摘。”小满瞪大眼，“我只听他说过：该办的事不能再拖了。”"}],"fallback":"哎呀，这个……我没见过，师傅也没交代过。"},{"id":"li","name":"谷立群","role":"死者亲侄","age":41,"look":{"skin":"tan","hair":"slick","hairColor":"black","glasses":"sun","beard":"stubble","outfit":"jacket","acc":"necklace","mood":"sly"},"bio":"谷鸿年的亲侄，做建材倒卖，是死者唯一的亲人。他说昨晚在家和朋友打牌，案发后才赶来。","demeanor":"油滑，爱称“叔”，夸大其词，被盯紧了就拍桌子说“我是苦主”。","topics":[{"id":"t_role","q":"你和叔叔关系如何？","a":"我叔就我一个亲侄子，他没儿没女，将来这店不给我给谁？我当苦主，不当嫌疑人，听清楚。"},{"id":"t_night","q":"昨晚你在哪儿？","lie":true,"a":"在家打牌，一桌四个人，从七点打到十一点多，不信你问。我连我叔后门朝哪开都不记得。","truth":"八点四十我去了后门，想借两万还赌债。敲半天没人应，收音机响得吓人。我在窗下抽了三支烟，八点五十走了，没进去。"},{"id":"t_money","q":"你最近缺钱吗？","lie":true,"a":"我缺钱？我的建材生意好得很！上半年刚进了一批货。要缺钱，我能用BP机满街找人借？","truth":"欠了两万赌债，月底要还。BP机那条是我发的，不是找叔叙旧，是催他把钱借给我的，他一直不松口。"},{"id":"t_will","q":"店将来怎么分？","a":"叔说“谁守得住归谁”。他觉得我守不住，更想给小满。我气归气，没动过他一根手指头。"},{"id":"t_window","q":"窗下脚印是谁的？","needs":["clue:c_gar2"],"a":"是我的，行了吧？我承认我在窗下站过。收音机震天响，我还当叔在里头装死，故意不开门。"},{"id":"t_aunt","q":"你婶婶呢？","a":"婶婶七九年得重病，叔掏空家底还欠债。那年秋天债突然还清了，她八〇年开春还是走了。"},{"id":"t_sick","q":"你知道叔病了吗？","needs":["clue:c_kit2"],"a":"肺癌？他从没跟我说过。难怪这些日子咳得像破风箱，我还嫌吵。他是拿我当外人吗？现在想问也问不到了。"}],"confronts":[{"clue":"c_gar2","breaks":"t_night","a":"“红塔山，我只抽这个。”他苦笑，又拍桌子：“我是去借钱！借钱不犯法吧？我叔活着时我没进去，死了更没必要。”"},{"clue":"c_hall4","breaks":"t_money","a":"他抢过BP机看看，又放回去。“我发的，行。欠人两万，人家拿刀催。叔不借，我才在窗下骂他……”"},{"clue":"c_gar3","a":"“我没有钥匙，叔不给。”他盯着空钩，“常叔那把呢？他要进去过，凭什么说六点就回家？”眼睛转得飞快。"},{"clue":"c_study4","a":"“收音机开那么大？”他愣了，“我叔嫌吵，平时只开一点点。我八点四十在后院就听得见。”"}],"fallback":"这玩意儿我没见过，别往我身上泼脏水。"},{"id":"chang","name":"常永昌","role":"店铺合伙人","age":58,"look":{"skin":"light","hair":"sidepart","hairColor":"grey","glasses":"rect","beard":"none","outfit":"suit","acc":"tie","mood":"worried"},"bio":"一九八五年入股聚珍斋的合伙人，占三成，管账和对外联络。他说自己昨晚六点就回家了。","demeanor":"圆滑、爱算账，爱说“按规矩”“这么说吧”，一急就开始报数字。","topics":[{"id":"t_role","q":"你在店里管什么？","a":"这么说吧，我三成股，管账、进货、跟拍卖行打交道。老谷懂货，我懂账，这是搭档的规矩。"},{"id":"t_leave","q":"昨晚几点离店？","lie":true,"a":"下午六点就走了，回家吃饭看电视，早早睡了。我老婆能作证。打烊后店里的事我一概不知。","truth":"我去过。七点三十五用自己的后门钥匙进去，和老谷吵了十几分钟，七点五十二摔门走。怕你们把吵架当杀人。"},{"id":"t_money","q":"分红账怎么回事？","lie":true,"needs":["clue:c_lib3"],"a":"账是老谷自己记的，他那手字你看得懂吗？我按规矩分红，该拿多少拿多少，谁说我多拿了？","truth":"拿了三万，给儿子付婚房首付，想着年底补上。老谷查出来，限我月底还清。我怕他抖出去。"},{"id":"t_test","q":"梅瓶送检你怎么看？","needs":["clue:c_hall3"],"a":"我反对。送检出了岔子，聚珍斋招牌就砸了，我三成股缩水。劝了他三遍，他犟，我只好听他的。"},{"id":"t_after","q":"你走时他什么样？","needs":["ask:chang.t_leave"],"a":"我走时他好好的，坐太师椅上咳嗽，还骂我。他说“八点有位老朋友要来，不方便见你”。"},{"id":"t_fang","q":"你怎么看那个学徒？","a":"小满手脚不干净。他说一个人回家没人证，十点又头一个进后堂。表停九点十分，他在哪儿？"}],"confronts":[{"clue":"c_gar3","breaks":"t_leave","a":"他喉结滚了几下，慢慢掏出钥匙：“我是去过，也吵了。可我走的时候他还活着，坐着骂我呢。”"},{"clue":"c_lib3","breaks":"t_money","a":"他肩膀一塌。“三万，我认。可杀了他这三万也不勾销，反而一辈子洗不清。我没那么傻。”"},{"clue":"c_study1","a":"“九点十分？我七点五十二分走，那时他表走得好好的。谁砸的，我这个算账的算不出。”"},{"clue":"c_kit2","a":"他的手发抖。“肺癌……他一个字没说。难怪半年脾气更拗，是在安排后事。”他摘下眼镜擦了擦。"}],"fallback":"这个我不清楚，账上没记，我不乱说。"},{"id":"yu","name":"俞鹤龄","role":"老主顾藏家","age":63,"look":{"skin":"light","hair":"bald","hairColor":"white","glasses":"round","beard":"goatee","outfit":"robe","acc":"scarf","mood":"sad"},"bio":"退休中学语文教师，收藏家，聚珍斋最老的主顾，对镇店之宝念念不忘。他说周四后没再去过店。","demeanor":"文绉绉，咳嗽，爱引古人，自称“老朽”，说到伤心处会停顿。","topics":[{"id":"t_role","q":"你与谷掌柜的交情？","a":"老朽与鸿年兄交往三十五年，知根知底。他一辈子靠一个“真”字，最怕人说他的货不真。"},{"id":"t_visit","q":"昨天你去过聚珍斋吗？","lie":true,"a":"周四之后老朽没再踏进过那道门。昨日在家临帖，晚上去文化宫票房，唱了半夜的戏。这点小事不劳翻簿子。","truth":"去过。下午三点二十到四点十分，我在店里看了那只梅瓶，看了很久。我瞒着，是看完心里发慌。"},{"id":"t_1979","q":"一九七九年的案子？","lie":true,"a":"梅瓶失窃？老朽只是略有耳闻。案子是公家办的，学徒是公家抓的，老朽不过是个爱瓷器的人，与我何干？","truth":"干系大了。当年法庭请我鉴定追回的瓶，我说“是真品”，这一句话，把二十二岁的孩子送进了牢房。"},{"id":"t_buy","q":"你想买那只瓶吗？","a":"想了二十年。我开价五十万，他说“此瓶不卖”。近来他却说“怕是要出个新价钱”，话里有话。"},{"id":"t_mouth","q":"昨天你看出什么？","needs":["clue:c_hall1","ask:yu.t_visit"],"a":"口沿。当年那只内侧有米粒大补烧痕，昨日我用放大镜照了一刻钟，这只光洁如新……不敢往下想。"},{"id":"t_shen","q":"沈文清死后你做过什么？","needs":["clue:c_lib4"],"a":"他死后第三年，我去他母亲家放了二百块，老太太没收，说“我儿没偷东西”。我站了一刻钟就走了。"}],"confronts":[{"clue":"c_hall2","breaks":"t_visit","a":"他看着登记簿上自己的名字，叹了口气。“是老朽糊涂。我怕你们一见我，就想起那个旧案子。”"},{"clue":"c_lib2","breaks":"t_1979","a":"他抚过照片上米粒大的补痕。“当年我在法庭上咬定它是真的，可法庭那只，我好像没见过这道疤……”声音哑了。"},{"clue":"c_hall1","a":"他凑近玻璃：“太光洁了。真东西可以有毛病，做出来的，只会没毛病。”说完便闭了口。"},{"clue":"c_lib4","a":"他眼眶红了。“每月寄钱，一寄十四年。我一直当他是良心发现，不曾想……”他没说下去。"}],"fallback":"老朽不识此物，也不敢妄断。"},{"id":"jiang","name":"蒋文彬","role":"拍卖行经理","age":45,"look":{"skin":"fair","hair":"slick","hairColor":"black","glasses":"rect","beard":"none","outfit":"suit","acc":"tie","mood":"smirk"},"bio":"省拍卖行经理，一年来一直游说谷鸿年把镇店之宝交给他上拍。他说自己和谷只有电话联系。","demeanor":"套话多，爱说“这个嘛”“我们公司的流程”，被追问时会反问“有凭据吗”。","topics":[{"id":"t_role","q":"你找谷鸿年谈什么？","a":"代销。镇店之宝上我们春拍，保守估价一百二十万。这个嘛，对老先生、店、公司都是三赢。"},{"id":"t_meet","q":"昨天你见过他吗？","lie":true,"a":"没见面，只在上午十点多通过一个电话。他说再考虑考虑，我就没催。我们公司讲究分寸。","truth":"见了。五点五十到七点一刻，吵得很凶：我要他签意向书，他不签还要送检。怕你们把吵架听成谋财。"},{"id":"t_contract","q":"代销合同签了吗？","lie":true,"a":"签了，口头加书面，老先生点了头，只差盖章。这个嘛，行内规矩，点了头就算数，公司流程也认。","truth":"没签，一个字都没签。我对林先生说“已经谈妥”，其实是谷老先生没点头，我先把话说满了。"},{"id":"t_goods","q":"你收过小满的货吗？","lie":true,"a":"我们是正规拍卖行，只收有手续的东西，学徒送来的私货一概不收。你不信，可以去查收货单。","truth":"收了三回，玉蝉、鼻烟壶、核桃，私下给小满三百块转手。谷老先生知道，会剁了我的手。"},{"id":"t_quarrel","q":"你们吵了些什么？","needs":["ask:jiang.t_meet"],"a":"我劝他别送检，他说“谁拦我就拼命”，还说晚上要见位“老相识”。我问是谁，他不讲。"},{"id":"t_lin","q":"林嘉明是什么人？","needs":["clue:c_cel3"],"a":"香港来的行家，上周找我说想买那只瓶。我收了他五万港币订金。这个嘛，生意人总得抢个先手。"}],"confronts":[{"clue":"c_hall2","breaks":"t_meet","a":"他盯着“19:15”，笑容僵了。“……好，我去了。可我七点一刻就走，他活得好好的。”"},{"clue":"c_hall3","breaks":"t_contract","a":"他低头看着空白的签字栏，脸色难看。“我说的是口头。”他强笑，“这一行，有时要抢跑一步。”"},{"clue":"c_cel2","breaks":"t_goods","a":"“收货单副本……那是我签的。三个小件三百块，不犯大法吧？”他勉强笑笑，“老先生本不会知道的。”"},{"clue":"c_study2","a":"“两个半到三个半钟头？那是八点多的事。我七点一刻就走了，你们该查八点以后进来的人。”"},{"clue":"c_lib1","a":"他皱眉：“仿制者？我不知道。”把信稿推回去，“老先生想自首，我没想到。”不像演戏。"}],"fallback":"这个嘛，我们公司没有相关记录。"},{"id":"he","name":"贺秀英","role":"后巷街坊","age":71,"look":{"skin":"tan","hair":"bun","hairColor":"white","glasses":"none","beard":"none","outfit":"apron","acc":"flower","mood":"sad"},"bio":"后巷孤老太太，摆过三十年馄饨摊。她说和谷掌柜只是点头之交，昨晚七点后就关门睡了。","demeanor":"絮叨、方言重，爱说“哎哟”“咱们”，提到伤心事会抹眼睛。","topics":[{"id":"t_know","q":"你和谷掌柜熟吗？","lie":true,"a":"哎哟，哪能说熟呢，街坊嘛，见面点个头，他买我馄饨，我送他半碟小菜。人家是大掌柜。","truth":"不是点头之交。他每月汇我八十块，十四年没断。我儿子沈文清是他徒弟，死在牢里。我只当他念旧情。"},{"id":"t_night","q":"昨晚你去过后堂吗？","lie":true,"a":"没有没有，我七点收了摊就关门睡了，老人家晚上哪还出门？有人说我去过，那是看错了。","truth":"去了。他胃不好，我每晚七点五十五送阳春面。他吃了两口说“有客要来，你先回”。我怕牵连才瞒。"},{"id":"t_alive","q":"你走时他什么样？","needs":["ask:he.t_night"],"a":"他还行，就是咳得厉害。叫我洗了两只盖碗，沏两盏茶，一盏他跟前，一盏摆对面。我走时差两分八点。"},{"id":"t_chang","q":"那晚后门还有别人吗？","needs":["ask:he.t_night"],"a":"我提着食盒到后门，正碰上常老板摔门出来，脸红脖子粗，闷头往街口走。里头老谷还在咳。"},{"id":"t_see","q":"夹道里你见到谁？","needs":["clue:c_gar1","ask:he.t_night"],"a":"八点刚过，开窗见个人影背着扁画夹，左腿有点拖，闪进谷家后院小门。脸看不真……我不敢说。"},{"id":"t_son","q":"沈文清是你儿子？","needs":["clue:c_lib4"],"a":"是我独苗，二十二进监，二十六死的。他到死说没偷东西，我信。老谷汇钱，我只当他可怜我。"},{"id":"t_hate","q":"你恨谷掌柜吗？","needs":["clue:c_lib2"],"a":"恨过。他寄钱我也收了，人总得吃饭。昨晚他吃了我的面，还说了声“谢谢”，那是头一回。"}],"confronts":[{"clue":"c_lib4","breaks":"t_know","a":"她手抖着接过存根。“十四年……我不想人知道我靠他养活。知道文清是我儿子，会说是我下的手。”"},{"clue":"c_kit1","breaks":"t_night","a":"她看着食盒盖里的红纸。“那是我写的。”她抹了把脸，“我去了，可我连儿子都不敢恨，哪敢杀人。”"},{"clue":"c_hall1","a":"她摇头：“文清说过，这瓶口上有个米粒大的小疤。现在柜里这只，我找了半天也没找着。”"},{"clue":"c_lib1","a":"她听人念了两遍，浑身发抖。“‘并非窃贼’……”泪大颗落下，“二十年了，终于有人说这句话。”"}],"fallback":"哎哟，这个我老婆子不认得，别拿来吓我。"},{"id":"lin","name":"林嘉明","role":"香港古玩商","age":50,"look":{"skin":"light","hair":"sidepart","hairColor":"black","glasses":"round","beard":"none","outfit":"suit","acc":"tie","mood":"neutral"},"bio":"香港“嘉廷古玩行”东主，十月中旬来省城，住省城宾馆，自称为镇店之宝而来。案发当晚他在宾馆。","demeanor":"港普夹杂粤语，爱说“唔该”“我话畀你知”，彬彬有礼却滴水不漏。","topics":[{"id":"t_role","q":"你来省城做什么？","a":"做生意，来看货。听说聚珍斋有件宣德梅瓶，我话畀你知，宣德青花难得，当然要看一眼。"},{"id":"t_know","q":"你以前见过谷先生吗？","lie":true,"a":"没有。这回是第一次来贵店，也是第一次同谷先生讲话。我只是想问问价钱，唔该不要想复杂。","truth":"周四下午我见过他，在后堂谈了一个钟头。我对他说，家父林廷芳1979年从他手里买走的才是真品。"},{"id":"t_night","q":"昨晚你在哪里？","a":"七点起同助手在宾馆餐厅吃饭，八点半回房，九点多叫宵夜谈事，十点睡。前台领班可证。"},{"id":"t_father","q":"你父亲买的是什么？","needs":["clue:c_cel3"],"a":"青花云龙梅瓶，口沿内侧有旧补烧。1979年10月家父以四万港币买下。去年热释光检测，明初无疑。"},{"id":"t_real","q":"你看了店里那只怎样？","needs":["clue:c_hall1","ask:lin.t_father"],"a":"做得很好，连橘皮纹都对，可口沿太干净。我对谷先生说：“您柜里这只，我家也有一只。”他说：“我知道。”"},{"id":"t_deposit","q":"你付了订金吗？","needs":["clue:c_hall3"],"a":"付了五万港币给蒋经理，收据在我房间。他说谷先生已同意代销，现在才知那只是他自己的话。"}],"confronts":[{"clue":"c_cel3","breaks":"t_know","a":"他看着名片上的折痕，轻叹：“都是我递的。我怕一开口，谷先生就成了‘被骗的主’。其实被骗的人更多。”"},{"clue":"c_hall2","breaks":"t_know","a":"“二十二号下午四点，是我。”他点头，“事由是谷先生让我别写。他说要先给我父亲一个交代。”"},{"clue":"c_lib1","a":"他久久没抬头。“‘愿以此身承担’……我以为他会赖，想不到是我低估了这位老先生。”"}],"fallback":"唔该，这个我不清楚，不方便乱讲。"},{"id":"zhong","name":"钟世昌","role":"邻铺裱画师","age":56,"look":{"skin":"light","hair":"short","hairColor":"grey","glasses":"rect","beard":"none","outfit":"vest","acc":"pocketwatch","mood":"tired"},"bio":"“墨缘斋”裱画铺老板，与聚珍斋一墙之隔的老邻居。他说案发那晚一直在街口茶馆打牌。","demeanor":"慢条斯理，文人腔，爱称“老哥”“惭愧”，说话时总捻着指尖。","topics":[{"id":"t_role","q":"你和谷鸿年什么交情？","a":"三十年的老邻居了。他懂货，我懂纸，彼此客气。老哥走成这样，我心里难受，实在惭愧。"},{"id":"t_where","q":"昨晚你在哪里？","lie":true,"a":"街口清心茶馆，七点半坐下就没动过，一桌四个老牌友，随便你问。听说出事，我才跑过来。","truth":"我离过席。八点说回铺子取烟，其实从夹道进了老谷后院，待到八点半过，八点四十五回的茶馆。"},{"id":"t_gate","q":"夹道小门怎么回事？","needs":["clue:c_gar1"],"a":"夹道是两铺共用的。我前几日借道给他送过画，有指印脚印也不稀奇。至于昨晚，我在茶馆。"},{"id":"t_1979","q":"一九七九年失窃案？","lie":true,"a":"那年我在文物商店修复组，只听说学徒偷了瓶，又追了回来。具体怎么回事我不清楚，帮不上忙。","truth":"瓶是我仿的，画了四十天，连口沿都没补。他说老婆等钱救命，给了我八百块和一个铺面的承诺。木箱里那方印，是我的旧斋号。"},{"id":"t_appoint","q":"最近你们见过吗？","lie":true,"a":"没什么往来。他前些天来我铺里借过一回糨糊，没说几句话。人老了各忙各的，哪来的什么“约”。","truth":"他周四傍晚亲自来，说要去自首，约我周五晚八点到后堂，劝我同去。我没应，晚上还是去了。"},{"id":"t_shen","q":"沈文清是谁？","needs":["clue:c_lib2"],"a":"那个学徒，手脚不干净，判了十年，病死了。可怜是可怜，法院判的案子，外人别嚼舌根。"},{"id":"t_guest","q":"他约了客人吗？","needs":["ask:he.t_alive"],"lie":true,"a":"约没约，我哪里晓得。老哥嘴紧，连我这个邻居也不吐一个字。我只劝他近日气色差，早点歇着。","truth":"约的是我。周四他亲口说的，叫我八点到后堂。他沏了两盏茶，一盏摆在我面前，我一口没碰。"},{"id":"t_leg","q":"你的腿怎么回事？","needs":["clue:c_gar1"],"a":"早年修房顶摔的，落了个左腿使不上劲，阴天就拖。街上谁不知道？你问这个做什么，走路也有罪吗？"}],"confronts":[{"clue":"c_gar1","breaks":"t_where","crack":true,"a":"他捻指尖的手停在半空。“夹道谁都能走……那门闩是老谷在里头拔的，外人推不开——”话一出口，他自己也听出了破绽。"},{"clue":"c_cel1","breaks":"t_1979","crack":true,"a":"他望着残缺的朱印，哑声说：“他竟留着。二十年，一只木箱，一张纸。我以为早烧光了。”"},{"clue":"c_lib1","breaks":"t_appoint","a":"“他连这个也写了。”他闭了闭眼，“仿制之人尚在……他一点没替我想过。我这辈子，就该跟着他的良心去投案吗？”"},{"clue":"c_study3","breaks":"t_guest","a":"他盯着那只盖严的茶碗，低声说：“茶是他沏的。我怕说出口，你们就当我是那个客人。”"},{"clue":"c_study2","a":"“两个半钟头……”他捻指尖的手停了，“我不懂这个，警医怎么说便怎么是。”目光移向别处。"},{"clue":"c_study1","a":"“停在九点十分……我那时在茶馆，打的是……”他猛地收声，“谁都能砸块表，我不信靠块表能定人的罪。”"}],"fallback":"这个……老朽实在没见过，帮不上忙，惭愧。"}],"solution":{"culprit":"zhong","method":{"q":"凶手是怎么做到的？","options":["A. 持后门钥匙进店，用镇尺行凶，没动别的东西","B. 争执中失手推倒死者，事后伪造被殴现场","C. 经夹道小门入院行凶，再砸表、拧大收音机","D. 茶里下药使其昏睡，再补一击伪装行窃"],"correct":2},"motive":{"q":"为什么杀人？","options":["A. 死者拒绝拍卖，凶手盼的佣金落空","B. 死者欲为旧案投案，凶手怕被供出","C. 死者查出账目被挪用，凶手怕丑事败露","D. 死者害死了凶手至亲，多年恨意爆发"],"correct":1},"keyClues":["c_study1","c_study2","c_lib1","c_cel1","c_gar1"],"truth":["凶手是邻铺“墨缘斋”裱画师钟世昌。1979年的梅瓶失窃案，是谷鸿年与他合演的一场戏。","当年谷为救重病的妻子，私卖真瓶给港商林廷芳，让钟仿造赝品，谎报失窃，嫁祸学徒沈文清。沈判十年，病死狱中。镇店之宝从那年起就是假的。","谷确诊肺癌，又被林嘉明当面道破真相，决心自首。他写好信稿，约“仿制者”周五晚八点来后堂，劝他同去投案。","周五晚，钟借口取烟溜出茶馆，从夹道小门入后堂，劝说不成，用镇尺杀人。他拔出表冠、砸表拨到九点十分，拧大收音机，八点四十五回茶馆。","破绽：表冠拉出而表壳无磕碰，警医断定死于八点半前；残印“缘斋”、小门指印、跛脚画夹人影，都指向钟。其余人的谎，只是各自的私事。"]}},{"id":"blackout","title":"断电夜","tagline":"台风夜断电四十七分钟，一位教授倒在冷库门外，没人能证明自己在哪。","difficulty":3,"cover":"coverBlackout","tone":"green","brief":"台风“云岚”登陆那晚，沪南生命科学研究所全楼断电四十七分钟。来电后，课题组组长周廷远被发现倒在低温样本间门外，后脑有伤。所长压着嗓子对你说：图3 数据刚被质疑，明天还要签几千万的专利许可，不能再出岔子。你冒雨赶到时，应急灯还亮着，门禁日志、温度记录和实验记录本都没人动过。八个人被留在楼里，个个说自己什么也没做。","victim":{"name":"周廷远","desc":"沪南生命科学研究所教授、课题组组长，五十六岁。来电后被保安发现倒在三楼冷间门外，后枕部有挫裂伤。","look":{"skin":"light","hair":"sidepart","hairColor":"grey","glasses":"rect","beard":"none","outfit":"suit","acc":"tie","mood":"stern"}},"relations":{"qin":"周廷远多年的合作者，专利第二发明人","wei":"周廷远课题组的博士后，天天跟着他做实验","xu":"周廷远名下的博士生，答辩被压了一年","tong":"所里管仪器和冷库的技术员，十九年老员工","qi":"所办行政主管，经手周的专利和合同","fang":"华澜生物的商务总监，来谈次日的签约","sun":"夜班保安，平时只和周打个招呼","jiang":"周廷远的妻子，中学教师"},"links":[{"a":"qin","b":"wei","text":"同一课题组的副教授与博士后"},{"a":"wei","b":"xu","text":"同在周廷远课题组，博士后与博士生"},{"a":"qi","b":"fang","text":"为次日许可协议对接合同"}],"deathReport":{"time":"约 21:30–23:00（受低温影响，难再精确）","cause":"后脑遭钝物撞击，颅脑损伤","scene":"来电后，保安孙国栋巡到三楼，在冷间门外发现周廷远倒地，已无呼吸。","loc":"lab","notes":["后脑一处挫裂创，为致命伤","体表冰凉，低温使死亡时间难以估算","衣着完整，随身物品仍在身上"]},"publicFacts":["22:13 至 23:00 全楼停电。UPS 和发电机只保 -80℃ 冷冻柜、应急灯、门禁；楼内照明和 -20℃ 冷间压缩机不在其内。","周廷远 23:02 被保安孙国栋发现倒在冷间门外，后脑受钝击，警方暂无法给出死亡时间。","样本间走廊门只记录刷卡进入，出门靠按钮；冷间开门超过三分钟才会中央报警。","图3 数据近期被质疑有偏差；周廷远与华澜生物约定次日 10:00 签 7F2 抗体专利许可。","被留下的有：秦海、魏子墨、许知夏、童伟、齐美玲、方知行、孙国栋，以及周的妻子蒋书琴。","会后秦海与周廷远在会议室门口当众争吵，全组都听到。"],"timeline":[{"t":"20:05","text":"组会结束，秦海与周廷远在门口争吵。"},{"t":"21:46","text":"门禁：周廷远的工牌刷开样本间走廊门。"},{"t":"22:13","text":"台风造成全楼停电，应急回路接管。"},{"t":"22:36","text":"门禁：周廷远的工牌再次刷开走廊门。"},{"t":"22:40","text":"中央系统记录冷间开门超时报警一次。"},{"t":"23:02","text":"来电后，保安发现周廷远，23:15 报警。"}],"budget":{"search":12,"ask":26},"locations":[{"id":"lab","name":"低温样本间走廊","scene":"lab","desc":"三楼尽头的走廊，一侧是 -20℃ 冷间，另一侧是 -80℃ 冷冻柜间。应急灯亮着，地上有粉笔人形。","clues":[{"id":"c_lab1","title":"冷间温度记录仪","text":"冷间温度记录仪：21:55 升到 -13.4℃，21:57 回落；22:37 升到 -8.9℃，22:41 回落。中央报警仅 22:40 一条。"},{"id":"c_lab2","title":"冷间地面","text":"冷间靠门的地面有几点暗红冻斑和一道两米长的擦痕，都覆着白霜。冷间外的走廊地面干燥，没有血迹。"},{"id":"c_lab3","title":"秦组的冷冻柜","text":"3号冷冻柜的取用登记：22:23 开，22:29 关，秦海笔迹。第三层一个样本盒的标签是新贴的，盒内有两个空位。"},{"id":"c_lab4","title":"货架转角","text":"靠冷间门的货架下层转角有一块被酒精擦过的亮痕，垃圾桶里有洇着褐色的酒精棉纸。"}]},{"id":"clinic","name":"临时急救室","scene":"clinic","desc":"一楼医务室，被警方临时当作询问室和存放随身物品的地方。窗外风雨拍得砰砰响。","clues":[{"id":"c_cli1","title":"法医初检记录","text":"后脑挫裂创。23:20 直肠温 30.8℃，背部有薄霜，鞋跟有拖拽磨痕。死亡时间栏：“受低温影响，暂无法估算。”"},{"id":"c_cli2","title":"工牌与手机","text":"工牌在内袋，挂绳盘成一圈。手机 21:44 后无人解锁，只亮过一次：21:52“书琴”来信“我在接待室等你”。"},{"id":"c_cli3","title":"蒋书琴的电脑包","text":"蒋书琴抱着一只电脑包，里面是关机的笔记本，外壳贴着“周廷远 课题组”的贴纸。"}]},{"id":"study","name":"周廷远的办公室","scene":"study","desc":"三楼东侧的组长办公室，书架顶到天花板，桌上堆满打印稿，抽屉有被翻动的痕迹。","clues":[{"id":"c_study1","title":"专利申请底稿","text":"发明人只有“周廷远、秦海”，红笔批注：“魏：致谢处理。图3 偏差追魏，周一前递委员会。”另夹华澜协议草案。"},{"id":"c_study2","title":"被裁走的记录页","text":"抽屉里夹着整齐裁下的六页记录（57–62 页），页眉“魏子墨”，记着 7F2 克隆的筛选，有魏子墨和组长的签字。"},{"id":"c_study3","title":"空的电脑底座","text":"桌上的扩展坞没有电脑。便签：“电脑别留所里。周一前——学术委员会。”抽屉里的文件夹被翻乱了。"},{"id":"c_study4","title":"核查函草稿","text":"《关于核查技术组私接外部测序业务的函》草稿，周廷远签名，日期本周一，涉事人员：童伟。"}]},{"id":"hall","name":"一楼门厅与保安室","scene":"hall","desc":"一楼门厅，保安室玻璃窗上贴着值班表。停电时只有应急灯亮着。","clues":[{"id":"c_hall1","title":"门禁日志导出","text":"走廊门：21:46 周廷远，22:20 秦海，22:36 周廷远。P2房：魏子墨 21:40 进、21:44 出、22:03 进。"},{"id":"c_hall2","title":"保安巡查与访客登记","text":"方知行 18:40、蒋书琴 21:20、齐美玲 17:00 入所，离馆栏空白。孙国栋巡查本：“22:25 去抽水，22:45 回岗。”"},{"id":"c_hall3","title":"监控与后门钥匙","text":"门厅录像 22:13 至 23:00 全黑，三楼走廊摄像头“检修中”。后门改用实体钥匙，保安室那把仍挂在原位。"}]},{"id":"library","name":"实验记录本档案室","scene":"library","desc":"三楼资料室，满墙铁皮柜存放历年记录本，借阅要签名登记。长桌上摊着几本记录本。","clues":[{"id":"c_lib1","title":"魏子墨的当晚记录","text":"魏子墨记录本：“21:42 加样；孵育 20 min；22:04 读板。”方案注：“孵育无需守候，25 分钟内返回。”"},{"id":"c_lib2","title":"档案借阅登记","text":"“21:50 许知夏借 W-07 魏记录本、Q-12 秦记录本，22:12 还。”W-07 的 57 至 62 页被裁走。"},{"id":"c_lib3","title":"秦海的记录本","text":"Q-12 图3 那页有两个编号被划掉重写，批注“改贴，待核”。页边有周廷远的红笔：“此处我知道。”"}]},{"id":"garden","name":"后院发电机房与停车场","scene":"garden","desc":"研究所楼后的小院，台风里树枝乱舞，积水没过台阶。角落的发电机房亮着一盏应急灯。","clues":[{"id":"c_gar1","title":"发电机值班本","text":"童伟的铅笔字：“22:14 转自动；22:16 魏博士来；22:30 离岗；22:49 回岗；22:51 魏博士取手电回。”"},{"id":"c_gar2","title":"停车场的银色轿车","text":"银色轿车里有一支U盘，标签“华澜—细胞株测序”。副驾电脑的传输窗口：“从U盘复制 22:34 开始，22:46 完成”。"},{"id":"c_gar4","title":"机房的雨披与钥匙板","text":"墙上两件蓝雨披印着“技术组”，都在滴水；一件右袖内侧有褐色擦痕。钥匙板上的后门钥匙，齿上沾着湿泥。"},{"id":"c_gar3","title":"消防梯口的断伞","text":"后门外的消防梯口有几个烟头和一把折断的大黑伞，伞柄贴着“保安室”的标签。"}]}],"suspects":[{"id":"qin","name":"秦海","role":"副教授","age":44,"look":{"skin":"light","hair":"messy","hairColor":"black","glasses":"rect","beard":"stubble","outfit":"shirt","mood":"stern"},"bio":"周廷远多年的合作者，专利第二发明人。会后与周当众争吵，自称断电后一直在自己办公室。","demeanor":"急躁、嗓门大，爱打断人。","topics":[{"id":"t_role","q":"你和周廷远什么关系？","a":"合作二十年，斗了二十年。论文他是通讯，我永远排后面。我认了，没想到他连专利都要拿来压我。"},{"id":"t_fight","q":"会后你们吵什么？","a":"二十点零五分，会议室门口。我不服署名排序，他说我“没资格谈条件”。全组都听见了，但我还没蠢到杀人。"},{"id":"t_corr","q":"22:20你在哪？","lie":true,"a":"我在办公室，一个人摸黑看文献。样本间那条走廊我晚上压根没去过。你们说我去了？证据呢？","truth":"我去了。22:20 进走廊，到 -80 间取回被改贴的两管样本。冷间门关着，门口什么都没有。"},{"id":"t_fig3","q":"图3 的数据有问题吗？","lie":true,"a":"我组里的原始数据完整无缺，每管都有记录。有人拿图3 做文章，是冲着我来的，我不接。","truth":"有两管编号我改贴过，原标签脱了，我不想写“数据丢失”。周廷远知道，拿这事压了我两年。"},{"id":"t_nobody","q":"走廊里当时有什么？","needs":["clue:c_hall1"],"a":"我拿手电扫过，冷间门关着，门口地上是空的。我待了十一分钟，没碰上人，也没看见周廷远。"},{"id":"t_patent","q":"专利署名怎么回事？","needs":["clue:c_study1"],"a":"底稿只有我和周廷远两个名字。7F2 是魏子墨筛的，我心里有数，但没吭声。这是我欠他的。"},{"id":"t_wei","q":"你怎么看魏子墨？","a":"踏实，肯吃苦，没脾气。周廷远对他比对我还刻薄，他从没吭过声。要说有火气，我没看出来。"}],"confronts":[{"clue":"c_hall1","breaks":"t_corr","a":"他盯着“22:20 秦海”，一巴掌拍在桌上。“我忘了这破东西记账！我进去过，但是去拿自己的东西！”"},{"clue":"c_lab3","breaks":"t_corr","a":"“我自己写的字……好，我认。22:20 进去，29 分关柜。”他的肩膀垮了下去。"},{"clue":"c_lib3","breaks":"t_fig3","a":"他看着“改贴，待核”和旁边的红笔“我知道”，眼红了。“他一直知道，拿这个压了我两年。”"},{"clue":"c_study1","a":"“这四个字我下午就听说了。”他手指点着“致谢处理”，半晌才说，“我没吭声。我是个懦夫。”"},{"clue":"c_lab1","a":"“21:55？我 22:20 才到，那时冷间早关好了。”他抬头，“你们该查是谁在这之前开过它。”"},{"clue":"c_cli1","a":"“背上有霜？那他在冷间待过？”他愣住，“可我去的时候门口是空的……那就是我走之后的事了。”"}],"fallback":"没印象，别想往我头上扣。"},{"id":"wei","name":"魏子墨","role":"博士后","age":33,"look":{"skin":"light","hair":"short","hairColor":"black","glasses":"round","beard":"none","outfit":"labcoat","mood":"smile"},"bio":"周廷远课题组的博士后。台风夜去后院帮技术员盯发电机，自称断电前一直在P2房做实验。","demeanor":"温和有礼，爱说“我理解”，被问急了会放慢语速。","topics":[{"id":"t_role","q":"你在课题组做什么？","a":"做抗体筛选和细胞实验，来组里第四年了。周老师是我导师，组里一半的活是我在盯，不觉得苦。"},{"id":"t_where","q":"21:40到22:10你在哪？","lie":true,"a":"一直在P2房做转染，加样后孵育等着，没出过门。出来正好断电，我就去后院找童师傅了。","truth":"我出去过，追着周老师进走廊。吵起来我推了他，后脑撞上货架角，人当场没了。我把他拖进冷间，拿走工牌。"},{"id":"t_blackout","q":"断电后你一直在哪？","lie":true,"a":"断电我就去后院陪童师傅守发电机，一直守到来电。童师傅能给我作证，我们俩一步都没分开过。","truth":"我借口拿手电，童师傅说钥匙在板上。他一走，我披雨披进楼，用周老师的卡开走廊门，把他拖出冷间。"},{"id":"t_rel","q":"你和周老师关系怎样？","lie":true,"a":"亦师亦友。周老师对我有知遇之恩，我们从没红过脸。他这一走，我也不知道课题组还撑不撑得下去。","truth":"那是场面话。7F2 是我筛的，他却把我划成“致谢”，还要把图3 的错推给我。我恨他，可我没想过杀他。"},{"id":"t_7f2","q":"7F2 抗体是谁筛的？","needs":["clue:c_study2"],"a":"是我筛的。那六页是我一个春天的心血，每步都有他的见证签字。现在被裁走了，他想让它从我手里消失。"},{"id":"t_cold","q":"冷间的温度曲线？","needs":["clue:c_lab1"],"a":"断电后压缩机停了，温度当然升。22:37 那下大升，是有人开门。周老师不放心冷间，也许他自己去看的。"},{"id":"t_xu","q":"许知夏说22:02遇见你？","lie":true,"needs":["ask:xu.t_saw"],"a":"许知夏？她那时不是在学生办公室写论文吗？我回P2的路上谁也没碰到，大概是她记混了吧。","truth":"碰到了。她问我手怎么这么凉，我说刚在冷间拿试剂。那时我刚拖完他，手上的东西洗了三遍才干净。"},{"id":"t_fig3","q":"图3 的偏差怎么回事？","needs":["clue:c_study1"],"a":"图3 的原始数据是秦老师组提供的批次，我只负责拟合。偏差不出在我这里，我有记录，不怕查。"}],"confronts":[{"clue":"c_hall1","breaks":"t_where","crack":true,"a":"他盯着“21:44 出”那一行，摘下眼镜。“二十分钟，我说我守着……门禁不会说谎，是吧。”"},{"clue":"c_lib1","breaks":"t_where","a":"“孵育无需守候。”他念出那行字，苦笑，“方案是我自己写的。你们真会抠字眼。”声音哑了下去。"},{"clue":"c_gar1","breaks":"t_blackout","a":"他看着“22:30 离岗”到“22:51”之间的空白，笑意挂不住。“我以为童师傅不会写这么细。”"},{"clue":"c_study1","breaks":"t_rel","a":"红笔“致谢处理”让他静了几秒。“看到了吧，这就是亦师亦友。我把他当老师，他把我当耗材。”"},{"clue":"c_lab1","a":"“21:55？”他很快稳住，“那时还有市电，冷间谁都能进，取个样本开两分钟门，很正常。”"},{"clue":"c_cli1","a":"“背上有霜。”他重复一遍，“冷间里的东西会沾霜，这能说明什么？”话出口，他自己先愣了一下。"},{"clue":"c_cli2","a":"他的目光在“21:44 最后解锁”上停了一瞬。“停电了，谁还看手机。”可他没解释工牌为何盘在内袋。"},{"clue":"c_lib2","breaks":"t_xu","a":"“二十一点五十到二十二点十二。”他声音低下去，“她就在走廊外面……她没理由编这个。”"},{"clue":"c_gar4","a":"“那件雨披是童师傅借我的，取手电时披过。”他盯着袖口褐痕，“这能说明什么？机房里谁都能穿。”"},{"clue":"c_gar3","a":"他对着断伞摇头。“后院风大，伞都折了。我披的是雨披，不打伞。这跟我有什么关系？”"}],"fallback":"我不太了解，不过愿意配合调查。"},{"id":"xu","name":"许知夏","role":"博士生","age":25,"look":{"skin":"fair","hair":"ponytail","hairColor":"black","glasses":"none","beard":"none","outfit":"hoodie","mood":"worried"},"bio":"周廷远名下的博士四年级学生，论文答辩被压了一年。自称整晚都在学生办公室里写论文。","demeanor":"声音小，说话快，紧张时抠指甲。","topics":[{"id":"t_role","q":"周老师对你怎样？","a":"他是我导师，对我挺严的。我延期一年，答辩申请一直卡在他那。他说“等图3 的事处理完”。"},{"id":"t_where","q":"21:40到22:15你在哪？","lie":true,"a":"在学生办公室写论文，从九点多坐到被保安叫下楼，没出过门。你看文档保存时间就知道。","truth":"我去了资料室，21:50 借了魏师兄和秦老师的记录本拍图3，想匿名举报。怕被当嫌疑人才没说。"},{"id":"t_saw","q":"离开资料室时遇见谁？","needs":["clue:c_lib2"],"a":"22:02 我出去倒水，撞见魏师兄急匆匆回P2。碰到他的手，冰得吓人。他说“刚在冷间拿了试剂”。"},{"id":"t_wei","q":"魏师兄是怎样的人？","needs":["ask:xu.t_saw"],"a":"他对我最好，论文都是他教的。可那晚他手那么冷，说话那么急……我不想怀疑他，也没法当没看见。"},{"id":"t_fig3","q":"图3 你知道什么？","needs":["clue:c_lib3"],"a":"秦老师记录本里图3 有两个编号被改过，写着“改贴待核”，周老师也知道。我只想留份记录，免得学生背锅。"},{"id":"t_zhou","q":"你恨周老师吗？","a":"恨过，也怕。他压了我一年答辩，说话从不留余地。可我从没想过他会死，更不会自己动手。"}],"confronts":[{"clue":"c_lib2","breaks":"t_where","a":"她盯着登记表上自己的名字，声音发颤：“是我签的……我怕你们不信一个被压了一年答辩的学生。”"},{"clue":"c_lib3","a":"“我拍的就是这页。”她过了一会才抬头，“我只想留份证据，不是要揭谁的短，真的。”"},{"clue":"c_study2","a":"“这是魏师兄的记录页？被裁掉了？”她把后半句咽回去，“他们之间的事比我想的严重。”"},{"clue":"c_hall1","a":"“21:44 出，22:03 进。那我 22:02 撞见他，时间对得上。”她顿了顿，“你们知道什么了？”"}],"fallback":"这个……我真的不太清楚。"},{"id":"tong","name":"童伟","role":"实验室技术员","age":46,"look":{"skin":"tan","hair":"cap","hairColor":"black","glasses":"none","beard":"stubble","outfit":"jacket","mood":"tired"},"bio":"在所里干了十九年的技术员，管仪器、发电机、冷库。自称断电后和魏子墨一直守在发电机房。","demeanor":"话少而硬，爱说“按规程”，心虚就低头摆弄手套。","topics":[{"id":"t_gen","q":"断电后设备怎么运转？","a":"发电机和UPS只顶 -80 柜子、应急灯、门禁，冷间压缩机不在上头。规程说断电过半小时要开冷间看一眼。"},{"id":"t_shed","q":"断电后你一直在哪？","lie":true,"a":"就在发电机房，一步没离开。魏博士 22:16 来帮忙，我们俩守到来电。按规程我不敢离岗。","truth":"我离岗了。22:30 说去取柴油，其实去车里送东西。22:49 回来魏博士不在，过两分钟他披雨披回来。"},{"id":"t_fang","q":"你认识方知行吗？","lie":true,"a":"华澜的方经理？招待过一两次，不熟。他是客人，我是技术员，除了带他参观仪器，没私下来往。","truth":"熟。我私下替华澜做过几次细胞株测序拿外快。当晚去车里把U盘交给他。传出去我饭碗就丢了，所以说谎。"},{"id":"t_notice","q":"周教授找过你谈话吗？","needs":["clue:c_study4"],"a":"周一叫我谈话，说有人举报我私接测序，要核查。处分没下，我连老婆都没敢说。恨他有一点，不至于动手。"},{"id":"t_lend","q":"雨披和后门钥匙借过谁？","needs":["ask:tong.t_shed","clue:c_gar1","clue:c_gar4"],"a":"魏博士说手电落在三楼，后门电子锁又停了。我说钥匙在板上，雨披挂着，披那件。就顺口一句，哪想到提防他。"},{"id":"t_cover","q":"魏博士让你做了什么？","needs":["ask:tong.t_shed","clue:c_gar1"],"a":"来电后魏博士悄悄说：“咱俩就说一直在一起，你出去那事我也不提。”我当时只当他讲义气。"},{"id":"t_cold","q":"冷间该怎么检查？","needs":["clue:c_lab1"],"a":"按规程断电超三十分钟要开冷间核对温度。我守着机器走不开，想着等来电再去，这是我失职。"}],"confronts":[{"clue":"c_gar1","breaks":"t_shed","a":"他看着自己写的铅笔字，手套捏成一团。“22:30 离岗，22:49 回岗。”他哑声说，“行，我认。”"},{"clue":"c_gar2","breaks":"t_fang","a":"他盯着U盘，脸一下白了。“我就赚点外快！没偷过课题组的核心数据，我拿十九年名声担保！”"},{"clue":"c_hall1","a":"“22:36 周老师的卡？”他皱眉，“我在机房守机器，什么都不知道。这卡按规程谁都不该借。”"},{"clue":"c_lab1","a":"“21:55？那时还没断电，谁开的冷间？”他摸摸帽檐，“开门三分钟内不报警，这人懂规矩。”"},{"clue":"c_study4","a":"他盯着自己的名字，手套越拧越紧。“你们是不是觉得我有理由盼他出事？”半天才说，“我没动他。”"},{"clue":"c_gar4","a":"他看着袖口翻卷的雨披，眉头拧紧。“这件不是我穿的。我那件在车里淋透了……这件借出去过。”"},{"clue":"c_gar3","a":"“保安室的伞，风大折了。”他看了一眼，“这个别算在我头上，我那晚压根没碰过伞。”"}],"fallback":"不在我管的范围，按规程你该问别人。"},{"id":"qi","name":"齐美玲","role":"所办行政主管","age":41,"look":{"skin":"light","hair":"bun","hairColor":"black","glasses":"rect","beard":"none","outfit":"suit","acc":"badge","mood":"worried"},"bio":"研究所行政主管，管专利和合同流程。自称十九点三十分就下班回了家，是被电话叫回来的。","demeanor":"客气、官腔，爱说“按流程”，被追问就看表。","topics":[{"id":"t_role","q":"你负责哪些事？","a":"管课题组的合同审批、专利备案和考勤，全按流程走。周老师的项目多，每份文件我都亲手过。"},{"id":"t_leave","q":"你当晚几点离开所里？","lie":true,"a":"十九点三十分我就下班了，台风要来，提前回了家。是接到所里电话才赶回来的，什么都没见着。","truth":"我没走，十七点入所，留所登记上有我。我在办公室加班到断电，之后一个人摸黑坐到来电。怕被追问才说谎。"},{"id":"t_sign","q":"专利文件有没有违规？","lie":true,"a":"材料都是齐的，发明人声明、署名页、各方签字，一样不缺。我亲手过的东西，经得起查，我敢保证。","truth":"不合规。下午五点周老师让我把发明人声明从三人改成两人，魏子墨没签放弃声明。他说“我负责”，我没敢拦。"},{"id":"t_form","q":"发明人声明改过吗？","needs":["clue:c_study1","ask:qi.t_sign"],"a":"改过。原来是周廷远、秦海、魏子墨三人。周老师说魏子墨的贡献“按致谢处理”，我劝过，他不耐烦。"},{"id":"t_wei","q":"你对魏子墨印象怎样？","a":"稳重，礼貌，从不惹事。他前两天来问过专利进度，我只说“还在走流程”。现在想想，那眼神……"},{"id":"t_dark","q":"断电后你做了什么？","a":"我一个人坐在办公室，听着风雨声，没离开过二楼。你们别指望我给谁作证，我连自己都证明不了。"}],"confronts":[{"clue":"c_hall2","breaks":"t_leave","a":"她盯着留所登记上自己的名字，手去扶眼镜。“十七点入，没有离馆……是，我骗了你们。我怕丢工作。”"},{"clue":"c_study1","breaks":"t_sign","a":"她脸色发白，捏着衣角：“这份底稿……魏子墨的放弃声明根本不在流程里。是我违规，我认。”"},{"clue":"c_study2","a":"“被裁走的六页？”她愣了愣，“难怪魏子墨前两天来问我，能不能调他的原始记录。我只当他核对。”"},{"clue":"c_hall1","a":"“这些刷卡我看不懂。”她把日志推开，“我只知道当晚周老师没跟我说过要去样本间。”"}],"fallback":"这个我得查一下流程，现在不好说。"},{"id":"fang","name":"方知行","role":"华澜生物商务总监","age":38,"look":{"skin":"light","hair":"sidepart","hairColor":"black","glasses":"none","beard":"none","outfit":"suit","acc":"tie","mood":"smirk"},"bio":"华澜生物商务总监，傍晚来所里谈次日签约的许可协议。自称二十点三十分就回了酒店休息。","demeanor":"圆滑，笑着打太极，爱说“从商业角度讲”。","topics":[{"id":"t_role","q":"你来所里做什么？","a":"谈 7F2 抗体检测许可，我们出四千八百万，明天十点签。从商业角度讲是双赢，谁也不想它黄。"},{"id":"t_leave","q":"你几点离开所里？","lie":true,"a":"二十点三十分，吃完饭就回酒店了。台风前我总得早点歇，一夜平安，什么都没看见，也不想卷进来。","truth":"我没走成，台风封路打不到车。为了等童伟的东西，我躲进自己车里。说回酒店，是不想被当成现场的人。"},{"id":"t_drive","q":"你和技术员有来往吗？","lie":true,"a":"技术员？没有，就见过一面。商务上的事都找周教授谈，和实验室的人我从来不私下打交道。","truth":"有。童伟私下帮我们做过几次测序。当晚我在车里等他，他把一支U盘交给我，是私人交易，与专利无关。"},{"id":"t_tong","q":"童伟在你车里待了多久？","needs":["ask:fang.t_drive","clue:c_gar2"],"a":"他 22:33 上车，数据从U盘拷进我电脑，他在旁边抽烟等，22:47 才下车。看传输记录，我没必要圆谎。"},{"id":"t_see","q":"你在车里看到什么？","needs":["ask:fang.t_drive","clue:c_gar2"],"a":"童伟走后一两分钟，约 22:49，楼里跑出一个披蓝雨披、拿手电的人，往机房去。帽子压得低，看不清脸。"},{"id":"t_who","q":"专利发明人有变化吗？","needs":["clue:c_study1"],"a":"三天前我手里的版本，发明人是周、秦、魏三个人。今天下午收到的只剩两个。周教授说“内部调整”。"}],"confronts":[{"clue":"c_hall2","breaks":"t_leave","a":"他看着空白的“离馆”栏，笑出声。“你们保安做得真细。好吧，我没走成，被台风钉在这儿了。”"},{"clue":"c_gar2","breaks":"t_drive","a":"他盯着车里的U盘，笑意挂不住。“标签写得太老实了。好吧，童伟跟我有生意，与专利无关。”"},{"clue":"c_study1","a":"他翻了翻底稿。“签约前一晚还在改发明人？”他笑意淡了，“发明人不清，专利将来要打官司。”"},{"clue":"c_hall1","a":"“22:36 很有意思。”他把日志推还，“教授如果已经出事，谁刷的他的卡？反正我没有他的卡。”"}],"fallback":"从商业角度讲，这和我没关系。"},{"id":"sun","name":"孙国栋","role":"夜班保安","age":52,"look":{"skin":"tan","hair":"short","hairColor":"grey","glasses":"none","beard":"stubble","outfit":"uniform","acc":"badge","mood":"tired"},"bio":"研究所夜班保安，来电后第一个发现周廷远倒在冷间门外。自称整夜都没有离开过门厅岗位。","demeanor":"憨厚，一口乡音，说话先“哎呀”。","topics":[{"id":"t_role","q":"你当晚负责什么？","a":"看大门、登记来客、半夜巡楼。哎呀，我这人不聪明，就是老实，几十年没出过岔子，台风夜更加小心。"},{"id":"t_post","q":"你整夜都在岗位上吗？","lie":true,"a":"哎呀，那当然！我在门厅一步没动，眼睛一直盯着大门。就是断电以后黑咕隆咚，看不太清。","truth":"不是一步没动。22:25 地下车库漏水，我怕淹了配电箱，去抽了二十分钟水。怕领导知道，才说一直在。"},{"id":"t_find","q":"谁发现了周教授？","a":"来电后我上三楼巡查，23:02 在冷间门外看见周教授躺着，一动不动。我马上喊人报警，没敢碰他。"},{"id":"t_guest","q":"当晚有哪些外来人员？","a":"外来的是方总监和蒋太太，都在本子上登记了。几点进来的你自己翻本子，我记性不如笔头。"},{"id":"t_lobby","q":"你回岗时遇见谁？","needs":["ask:sun.t_post","clue:c_hall2"],"a":"22:46，楼梯口出来个披蓝雨披的，帽子扣得严，往后门去。我喊他，他摆手说“去机房”。我以为是童师傅。"},{"id":"t_card","q":"门禁记录靠得住吗？","needs":["clue:c_hall1"],"a":"读卡器断电也记账，只是出门按钮不记，开门后八秒才锁，跟得紧的人也能进。不过刷卡就是刷卡。"}],"confronts":[{"clue":"c_hall2","breaks":"t_post","a":"他看着“22:25 去抽水”，脸涨红，拍了下大腿。“哎呀，我自己写的，赖不掉了！就这一回离岗！”"},{"clue":"c_gar3","a":"“保安室的伞。”他指着标签，“我去车库抽水用的，风太大折了，后来丢在后门口，我是真去干活了。”"},{"clue":"c_hall1","a":"“22:36 周教授刷卡？”他茫然，“那时我在车库……我要在门厅，肯定看见谁进的走廊。”"},{"clue":"c_cli2","a":"“手机一直没亮过？”他挠头，“黑成那样，活人谁不先摸手机照亮？”说到这儿他自己顿住了。"},{"clue":"c_cli1","a":"“背上有霜？”他倒吸一口气，“我发现他时，身子冰得吓人，我还当是淋了雨。走廊里可没有雨。”"}],"fallback":"哎呀，这个我不懂，你问别人吧。"},{"id":"jiang","name":"蒋书琴","role":"周廷远的妻子","age":54,"look":{"skin":"light","hair":"bob","hairColor":"grey","glasses":"none","beard":"none","outfit":"coat","acc":"necklace","mood":"sad"},"bio":"周廷远的妻子，是一名中学教师。自称在家里接到电话，到二十三点二十分才赶到研究所。","demeanor":"体面克制，爱用反问，被戳到心事会突然安静。","topics":[{"id":"t_role","q":"你和周廷远的关系？","a":"三十年夫妻。他把一生给了实验室，我习惯了。外人眼里我们体面，我咽进肚子的话比说出口的多。"},{"id":"t_arrive","q":"你几点到的所里？","lie":true,"a":"接到电话已经二十三点多了，台风天路上堵，我打车二十三点二十分才到。之前我一直在家。","truth":"我 21:20 就到了，想接他回家。保安让我在接待室等，21:36 我上楼找过他，被劝回，等到来电。"},{"id":"t_laptop","q":"电脑包里是什么？","lie":true,"a":"是我自己的东西，一些旧文件和教案，不值一提。我是来接丈夫的，不是来受审的，别翻我的包。","truth":"是周廷远的笔记本，22:02 我趁他不在上楼拿的。里面有他转移专利收益的聊天记录，我想留作离婚证据。"},{"id":"t_stair","q":"你在所里见过谁？","needs":["ask:jiang.t_arrive","clue:c_cli2"],"a":"21:36 我上三楼找他，在楼梯口撞见魏博士，脸色发白，说“周老师在忙，您先去接待室等”。"},{"id":"t_wei","q":"你对魏子墨印象如何？","a":"周廷远嘴上嫌他“太老实”，其实最倚重他。魏博士每年中秋都往家里送月饼，礼数周全。"},{"id":"t_marriage","q":"你们夫妻怎么了？","needs":["clue:c_study3"],"a":"他一年来账上多了个我不知道的户头，电话里还提“离岸”。我不想闹，只想留份证据。我没杀人。"}],"confronts":[{"clue":"c_cli2","breaks":"t_arrive","a":"她盯着手机预览里自己发的那行字，捂住嘴。“21:52 是我发的……好，我 21:20 就到了。”"},{"clue":"c_hall2","breaks":"t_arrive","a":"“访客登记里有我。”她苦笑，“老孙写得比我记得清。好，我 21:20 就到了，别再逼我了。”"},{"clue":"c_cli3","breaks":"t_laptop","a":"她抱紧电脑包，指节发白。“……你们都看见贴纸了。是他的电脑，我拿的。我不是贼，我是他的妻子。”"},{"clue":"c_study3","breaks":"t_laptop","a":"她看着空底座，沉默很久。“是他的电脑，我拿的。别问里面有什么，我自己也不想再看。”"},{"clue":"c_study1","a":"她读到“致谢处理”，轻轻一震。“他还是这样，把别人的功劳揣进兜里，一辈子都改不了。”"}],"fallback":"我不清楚，也不想多说。"}],"solution":{"culprit":"wei","method":{"q":"凶手怎样让人相信周廷远死于断电期间？","options":["断电后趁黑在走廊当面行凶，尸体一直倒在原处不动","篡改冷间温度记录和报警设置，让死亡时间显得更晚","断电前行凶藏尸冷间，再用死者工牌开门移尸","断电前行凶藏尸，让同伙持死者工牌开门移尸"],"correct":2},"motive":{"q":"凶手为什么杀人？","options":["因专利署名排序积怨已深，又被当众羞辱而起了杀心","被除名发明人又要背图3 的锅，争执中失手掩盖","怕被处分私接业务，想让死者永远开不了口","收了企业好处，想阻止次日专利许可协议的签署"],"correct":1},"keyClues":["c_cli1","c_cli2","c_lab1","c_hall1","c_gar1","c_study1"],"truth":["凶手是博士后魏子墨。周廷远不是死在断电后，而是断电前就死了。秦海和童伟都被怀疑过，但都不是凶手。","动机：7F2 抗体是魏子墨筛的，周廷远却在专利里把他划成“致谢”，还要把图3 的偏差推给他。次日就要签约，这是他最后的机会。","手法：21:44 魏趁孵育空窗尾随周进走廊，争执中推他撞上货架角致死。他把尸体拖进冷间，拿走工牌，22:03 回 P2，撞见许知夏，手冰凉。","第一层反转：法医的霜与拖痕、冷间 21:55 的曲线、盘在内袋的工牌，说明周断电前已死。秦海 22:20 进走廊时冷间门关着、门口无人，嫌疑排除。","第二层反转：22:30–22:49 魏借童伟的好意（雨披和后门钥匙）进楼，刷死者的卡，把尸体拖出冷间。童伟当时在方知行车里，传输记录为证；值班本的空白戳穿了魏。"]}},{"id":"filmset","title":"杀青宴","tagline":"杀青宴上，替身死在道具仓库；录像里的人，个个有不在场证明。","difficulty":3,"cover":"cv_filmset","tone":"none","brief":"云岭影视城，古装剧《凤阙行》杀青当晚。你是被编剧岑子昂请来蹭杀青宴的退休刑警，在“醉仙楼”听了一晚上导演的酒话。22:18，道具师谷春来脸色发白地冲进来：武术指导谭铁山倒在B库仓库，后脑被砸，已经没气。大雨冲断了山路，警方最快凌晨才到。导演邢广川抓着你的袖子：“老谭是我兄弟，你帮我看看，到底是谁。”","victim":{"name":"谭铁山","desc":"四十七岁，《凤阙行》武术指导，兼男主角周衍的替身。俯卧在B库货架间，后脑遭重击，旁边落着染血的铸铁虎形镇纸。","look":{"skin":"tan","hair":"short","hairColor":"grey","glasses":"none","beard":"stubble","outfit":"jacket","mood":"stern"}},"publicFacts":["《凤阙行》今晚在云岭影视城杀青，剧组在“醉仙楼”办杀青宴，约四十人出席。","谭铁山，47岁，武术指导兼男主角周衍的替身，通告单排了他21:45的压轴刀剑表演。","谭铁山21:12刷卡进B库，22:18被道具师谷春来发现死亡，死因是后脑钝器重击，案发在这两个时间之间。","新租的花絮机拍下祝酒片段，时间码21:31至21:52。据场记日志，致辞因导演晚到推迟了一小时。","画面里的人警方暂时视为在场；灯光师、道具师、编剧没有入镜。","周衍晚间已赶往机场。夜里大雨，山路被冲断，22:25后无人出入基地。"],"relations":{"qi":"同剧组的场记，片场常碰面","xing":"合作二十五年的导演，老兄弟","hai":"剧组总制片人，管钱管进度","gu":"管B库道具的道具师，常打交道","mei":"男主角周衍的经纪人，也带女主角","shu":"剧组女主角，动作戏常找他指导","cen":"剧组编剧，常为打戏和他争论","yuan":"灯光师，多年相识的老熟人"},"links":[{"a":"mei","b":"shu","text":"经纪人和旗下艺人"},{"a":"xing","b":"hai","text":"导演和制片人，一个管戏一个管钱"},{"a":"xing","b":"cen","text":"导演和编剧，合作《凤阙行》"}],"deathReport":{"time":"约 21:00–22:15","cause":"后脑遭钝器重击","scene":"22:18，道具师谷春来进B库仓库，发现谭铁山俯卧在货架间，已无呼吸。","loc":"wh","notes":["后脑一处钝器伤，一击致命","三步外一只铸铁虎形镇纸，沾着血","血已半凝，皮夹腕表都在"]},"timeline":[{"t":"19:30","text":"杀青宴开席，导演邢广川到场。"},{"t":"21:12","text":"谭铁山刷卡进入B库正门。"},{"t":"21:31","text":"据场记日志与花絮机：致辞、祝酒、切蛋糕开始（较通告单推迟60分钟）。"},{"t":"21:45","text":"压轴表演开场，谭铁山未现身。"},{"t":"22:18","text":"谷春来在B库发现谭铁山死亡。"},{"t":"22:25","text":"山路被冲断，基地封闭。"}],"budget":{"search":15,"ask":30},"locations":[{"id":"wh","name":"B库道具仓库","scene":"cellar","desc":"影视城后巷尽头的砖仓，铁架上堆满龙纹椅、宫灯和刀枪剑戟，空气里是樟木和桐油味。","clues":[{"id":"c_wh1","title":"倒在货架间的武指","text":"谭铁山脸朝下倒在货架间，后脑塌陷，血已半凝。三步外滚着一只七斤重的铸铁虎形镇纸，沾着血。皮夹腕表都在。"},{"id":"c_wh2","title":"读卡器本地日志","text":"读卡日志：14:02 场务07侧门入；21:12 谭铁山正门入；21:19 场务07侧门入，21:33出；22:16 谷春来入"},{"id":"c_wh3","title":"恒温柜里的刀","text":"刀匣完好，标签写“凤阙·实物·1.3kg”，刀却明显轻。刀背近护手处有极小的“仿”字钢印，匣内刀痕比此刀宽一圈。"},{"id":"c_wh4","title":"指缝里的绿丝线","text":"谭铁山右手指缝缠着几缕深绿色编织绳纤维，连着半粒断裂的塑料卡扣。"},{"id":"c_wh5","title":"侧门外的烟头","text":"侧门外后巷墙根有六七个薄荷烟头，最上面两个还没湿。旁边落着一只打火机，底部刻着“岑”字。"}]},{"id":"ban","name":"醉仙楼宴会厅","scene":"dining","desc":"两层置景酒楼，红灯笼、长条桌、吃了一半的冷菜。墙上挂着一面圆形旧挂钟。","clues":[{"id":"c_ban1","title":"桌上的通告单","text":"通告单：19:30开席；20:30致辞、祝酒、切蛋糕；20:50周衍离场；21:45谭铁山压轴。纸角铅笔写“祝酒按点！”"},{"id":"c_ban2","title":"签到台的工作牌","text":"挂绳颜色表：导演组黑，制片组和编剧红，美术道具黄，灯光蓝，场务场记绿。备用挂绳里绿色只剩两条，吊牌未撕。"},{"id":"c_ban3","title":"谭铁山的外套","text":"椅背外套口袋里有手机。通话记录：21:09 戚小棠 0:41。微信：舒见月19:58“师父，谢谢您今天”，他回了抱拳。"},{"id":"c_ban4","title":"推车上的蛋糕","text":"蛋糕只被切走一角，奶油已经塌陷。盒底小票写着“提货 20:10”。"}]},{"id":"mon","name":"监视器棚","scene":"stage","desc":"一号棚外的临时监视器棚，一台回放机，桌上堆着场记本和器材卡。","clues":[{"id":"c_mon1","title":"花絮机的回放","text":"花絮机回放，叠字21:31:08–21:34:48。导演、周衍、戚小棠、祁海生、舒见月、梅敏仪入镜；后墙挂钟指向八点半。"},{"id":"c_mon2","title":"摄影组器材卡","text":"器材卡：“A机（租赁新机）时区JST(UTC+9)”。背面便利贴：“时间先别动，收工统一校。——凯”"},{"id":"c_mon3","title":"场记日志","text":"场记日志：“祝酒 TC 21:31–21:52，较通告单延误60分，导演晚到。”页边另笔迹：“周衍20:55出门岗”"}]},{"id":"off","name":"制片办公室","scene":"study","desc":"拖挂板房，文件柜成排，桌上堆满合同和报销单。","clues":[{"id":"c_off1","title":"门卡与钥匙登记簿","text":"登记簿：“场务卡07·戚·13:40借·未还”，后有小字“卡先留着——春”。刀匣备用钥匙：上月12日祁借，14日还。"},{"id":"c_off2","title":"凤阙刀鉴定书","text":"鉴定书：“明代绣春刀，全重1.3公斤，无任何标记，保额480万。”保险公司函要求每月验刀，最近一次只签着“祁”。"},{"id":"c_off3","title":"被撕掉的协议","text":"纸篓里撕开的保密协议：乙方谭铁山，不得谈周衍动作戏实情。乙方未签，红笔批“再谈——梅”。"}]},{"id":"rm","name":"化妆休息拖车","scene":"backstage","desc":"街口一排拖车，一节化妆间，一节休息间，靠板壁摆着储物柜。","clues":[{"id":"c_rm1","title":"场记的帆布包","text":"帆布包里有张照片，背面写“小川·《龙渊》开机”；剪报报道威亚员坠亡，称武指谭铁山“检查无误”；还有条带吊牌的绿挂绳。"},{"id":"c_rm2","title":"谭铁山的储物柜","text":"笔记本待办：“①刀的事，杀青后找老祁。②小戚，今晚当面，我欠她哥一句真话。”另夹一封致影视安全协会的未写完的信。"},{"id":"c_rm5","title":"假发修补单","text":"化妆组工作单：“21:00谷师傅来帮忙对线；21:05起缝；22:10谷师傅被导演叫走”，每行有化妆师签名。"},{"id":"c_rm3","title":"舒见月的剧本","text":"休息间沙发上有对家剧组的剧本，页脚有泪痕。茶几上一份未签的《杀青续约意向书》，手机停在“明天九点试装”。"},{"id":"c_rm4","title":"垃圾桶里的绳头","text":"休息拖车外垃圾桶里有条断掉的绿色编织挂绳，扣头裂开，边缘磨白，断口很新。"}]},{"id":"gate","name":"门岗与停车场","scene":"garden","desc":"正门岗亭和水泥停车场。夜里下着雨，山路被冲断的消息在对讲机里滚动。","clues":[{"id":"c_gate1","title":"门岗出入登记","text":"登记：“20:55 保姆车·周衍出基地送机，送行梅敏仪签”；“21:00 梅敏仪回基地”。此后到22:25再无车辆出入。"},{"id":"c_gate2","title":"商务车里","text":"祁海生车里：通话“老林（藏家）21:08”，微信有“凤阙尾款”转账截图。记录仪21:07–21:42拍到他一直在车内。"},{"id":"c_gate3","title":"灯光车里的纸箱","text":"灯光车货厢里有半瓶白酒、一件军大衣，座椅下两箱旧灯泡灯珠，贴着“散件5元/个”。"},{"id":"c_gate4","title":"导演的房车","text":"房车里两个空酒瓶，沙发有睡出的人形压痕。手机有22:08场务宋的未接来电。"}]}],"suspects":[{"id":"qi","name":"戚小棠","role":"剧组场记","age":28,"look":{"skin":"light","hair":"ponytail","hairColor":"black","glasses":"rect","beard":"none","outfit":"jacket","acc":"headset","mood":"neutral"},"bio":"《凤阙行》场记，管连戏和时间码。杀青宴上举杀青板切了蛋糕，说之后一直在宴会厅张罗压轴。","demeanor":"轻声慢语，爱报数字，被问急了就盯着手里的铅笔。","topics":[{"id":"t_role","q":"场记做什么？","a":"连戏、记日志、对时间码，哪句台词在哪个镜头，我都得记着。这行没人看见你，出了错全看得见。"},{"id":"t_toast","q":"祝酒几点？","lie":true,"a":"通告单写八点半，但导演晚到，推迟了一小时，二十一点三十一分才拍。我的日志写得清楚。","truth":"八点半，准点。花絮机时区没调，快了一小时。我是场记，我知道。出事后没人问，我就没纠正。"},{"id":"t_where","q":"21点后在哪？","lie":true,"a":"一直在宴会厅收杀青板、盯蛋糕、串压轴，一步没离开。祝酒录像里你能看见我，这就是证明。","truth":"二十一点十五分，我借口拿蜡烛出了宴会厅，去了B库，二十一点四十才回来。我去见谭铁山。"},{"id":"t_card","q":"卡07在哪？","needs":["clue:c_off1"],"lie":true,"a":"下午取完连戏道具，我就把卡放回办公室抽屉了。临时卡谁都能拿，后来谁用的我不知道。","truth":"卡一直在我身上。谷师傅说卡先留着，省得晚上再跑。我二十一点十九分用它进了侧门，二十一点三十三分出来。"},{"id":"t_call","q":"你给他打过电话？","needs":["clue:c_ban3"],"lie":true,"a":"只是通知他压轴的时间，一句话的事，说完就挂了，没有多聊。通告上谁几点上场，向来归我提醒。","truth":"我说导演想先看刀匣，让他先去B库。他答应了，还问我：“你是小戚吧？”我手心当时就凉了。"},{"id":"t_know","q":"和谭铁山熟吗？","lie":true,"a":"共事一个月，点头之交。他是武行大哥，我是记日志的，平时说不上几句话，没什么交情。","truth":"他害死了我哥。小川两年前在《龙渊》坠亡，谭铁山在检查表上签了字，却说是我哥自己系错了结。我就是为他来的。"},{"id":"t_lanyard","q":"挂绳换过吗？","needs":["clue:c_wh4"],"lie":true,"a":"没换过。这条是上周领的备用，场记组一人发两条，我天天挂着，宝贝着呢，真没换过，一直是这条。","truth":"换了。旧的被他一把拽断。我回厅前去签到台拿了新的，吊牌在厕所撕的，旧的扔进了拖车外垃圾桶。"},{"id":"t_last","q":"他最后说了什么？","needs":["ask:qi.t_know"],"a":"他说：“你是小戚吧，你哥那件事……”只说到这里。我听着像笑，脑子嗡的一声，后半句没听完。"}],"confronts":[{"clue":"c_mon1","breaks":"t_toast","crack":true,"a":"她盯着挂钟，铅笔停在指间。“……八点半。钟是对的，叠字是错的。我知道机器是东京时间，我没说。”"},{"clue":"c_gate1","breaks":"t_toast","a":"“周衍八点五十五就走了。”她指尖发白，“那他不可能二十一点三十一分还在镜头里。我早该想到有人翻门岗。”"},{"clue":"c_wh2","breaks":"t_where","crack":true,"a":"她把日志看完。“21:19，21:33。十四分钟。”她笑得很薄，“我最会记数字，原来最好记的是我自己的。”"},{"clue":"c_off1","breaks":"t_card","a":"“登记簿上有我的字，还有谷师傅的‘先留着’。”她说，“卡我没放回去，从没打算放回去。”嗓子哑了。"},{"clue":"c_ban3","breaks":"t_call","a":"她盯着“0:41”：“四十一秒，不是提醒的长度。”停了停，“那是我这辈子打得最长的一通电话。”"},{"clue":"c_rm1","breaks":"t_know","a":"她伸手要抢照片，又在半空停住。“那是我哥，戚小川。”声音软了，“他的命，没人替他记。”"},{"clue":"c_rm4","breaks":"t_lanyard","a":"她捏了捏胸前崭新的挂绳。“旧的戴了一年多，边都磨白了。扔的时候我想，这下谁也看不出少了一条。”"},{"clue":"c_rm2","a":"她看着那封没写完的信，嘴唇抖了很久。“……他写了？”她问，然后蹲下去，把额头抵在膝盖上，没再抬头。"}],"fallback":"这个跟我的日志没关系，你问点有时间、有数字的。"},{"id":"xing","name":"邢广川","role":"《凤阙行》导演","age":52,"look":{"skin":"tan","hair":"cap","hairColor":"grey","glasses":"none","beard":"stubble","outfit":"jacket","mood":"tired"},"bio":"《凤阙行》导演，爱喝酒，与谭铁山合作二十五年。据说致辞后一直留在宴会厅陪大家喝酒。","demeanor":"北方腔，嗓门大，爱说“哎我说”，伤心处就骂人。","topics":[{"id":"t_role","q":"你和他交情如何？","a":"二十五年的兄弟。我拍第一部戏他就是武行，替人摔过多少回，数不清。哎我说，这样的人怎么就……"},{"id":"t_where","q":"21点后在哪？","lie":true,"a":"在楼里陪大伙儿，酒敬了一圈又一圈，一直敬到出事。哎我说，我邢广川什么时候躲过酒？","truth":"九点我就溜回房车，喝多了睡死过去，睡到场务宋敲门。怕传出去，说导演在杀青宴上先醉了。"},{"id":"t_speech","q":"致辞几点？","needs":["clue:c_mon3"],"a":"八点半，通告单上写的。讲完周衍就得赶飞机，我哪敢拖？场记那丫头说我迟到？我七点二十就到了。"},{"id":"t_quit","q":"他说过要走吗？","lie":true,"a":"哎我说，没有，从来没有。这人闲不住，成天泡在片场。他要走，我跟他二十五年能不知道？","truth":"前天他说，杀青后要把一件旧事说清楚，说完就收山。问什么事他不肯讲。我怕你们往那边想，才说没有。"},{"id":"t_feud","q":"最近吵过吗？","a":"吵过。上周补拍吊威亚，我嫌他保守，骂了他一顿。他说：“我这辈子不会再让人在我手下摔下来。”"},{"id":"t_wire","q":"《龙渊》的事？","needs":["clue:c_rm1"],"a":"别家剧组的事故，死了个威亚员。老谭那回被圈里嚼了半年舌头，从不提。之后他每次吊威亚都亲手摸三遍扣。"}],"confronts":[{"clue":"c_gate4","breaks":"t_where","a":"他踢开地上的空酒瓶，嗓子沙了：“行，我睡了。……我要是醒着，老谭是不是还活着？”"},{"clue":"c_rm2","breaks":"t_quit","a":"他翻来覆去看那封信：“收山，说清楚……他就是要说这个。”抹了把脸，“我当兄弟的，还替他瞒着。”"},{"clue":"c_mon3","a":"“迟到？我？”他气得拍桌，“通告单八点半，我讲的话，周衍搂着我肩膀，我记得清清楚楚！这谁写的？”"}],"fallback":"哎我说，这玩意儿我不懂，你问点我能答的。"},{"id":"hai","name":"祁海生","role":"制片人","age":50,"look":{"skin":"light","hair":"sidepart","hairColor":"black","glasses":"none","beard":"none","outfit":"suit","acc":"tie","mood":"sly"},"bio":"《凤阙行》总制片人，管钱、管进度、管投资方。他自称宴后一直在宴会厅陪投资方的朋友喝酒。","demeanor":"圆滑，爱说“咱们”“格局”，被问到钱就笑着绕开。","topics":[{"id":"t_role","q":"你负责什么？","a":"融资、进度、投资方，剧组上上下下的钱和脸面都在我这儿。咱们做制片的，不就干这个嘛。"},{"id":"t_where","q":"21点后在哪？","lie":true,"a":"在楼里陪几位投资方的朋友喝酒，咱们得有格局，一直敬到出事。在场哪个不能给我作证？","truth":"我在停车场的车里接电话，谈一笔钱，不方便让剧组的人听见。二十一点零八分打到快二十一点四十分。"},{"id":"t_sword","q":"凤阙刀有问题吗？","lie":true,"a":"那是四百八十万的镇组之宝，鉴定书、保险一样不少，每月验刀我亲自看。一根毛都没少。","truth":"……是仿的。真刀上个月我背着投资方卖了，填剧组的窟窿，想杀青就还。谭铁山下午一掂就看出来了。"},{"id":"t_key","q":"刀匣钥匙谁拿过？","needs":["clue:c_off1"],"a":"上个月拿过一次，拍宣传照，第二天就还了。老谷当天就在场，咱们都是明白人，别写进卷宗。"},{"id":"t_tan","q":"他找过你吗？","needs":["clue:c_rm2"],"a":"找过。下午他说刀不对，我求他杀青后再说，他答应了。我为什么要杀一个已经答应等我的人？"},{"id":"t_money","q":"剧组的钱怎么样？","needs":["clue:c_gate2"],"a":"紧。投资方砍预算，爆破加了两场，我是靠卖掉一点东西撑到杀青的。哪家剧组不是靠一口气撑着？"},{"id":"t_think","q":"你觉得谁干的？","a":"录像里谁在谁不在，警察看过了。灯光、道具、编剧三个人没进过镜头，躲着镜头的，才可疑嘛。"}],"confronts":[{"clue":"c_gate2","breaks":"t_where","a":"他的笑僵在脸上：“行。我在车里，记录仪拍着呢，赖不掉。钱的来路我可以解释，杀人，我没那个胆。”"},{"clue":"c_wh3","breaks":"t_sword","a":"他蹲下看那枚“仿”字钢印，半晌才说：“钢印是我找人打的，怕以后说不清。我就知道纸包不住火。”"},{"clue":"c_off2","breaks":"t_sword","a":"他盯着“每月验刀”那行，嘴角一抽：“验刀栏是我签的。我对不起藏家，也对不起老谭。”"},{"clue":"c_rm2","a":"他读到“刀的事，杀青后找老祁”，喉头滚了滚。“他给我留了时间。我昨天还骂他不识抬举。”"}],"fallback":"这个咱们回头再谈，先说案子的事。"},{"id":"gu","name":"谷春来","role":"道具师","age":44,"look":{"skin":"tan","hair":"short","hairColor":"black","glasses":"rect","beard":"none","outfit":"apron","mood":"worried"},"bio":"《凤阙行》道具师，管B库所有道具，发现了谭铁山。他说九点后一直在化妆拖车帮人修假发。","demeanor":"慢吞吞，爱说“这个东西啊”，紧张就摸腰上的钥匙串。","topics":[{"id":"t_where","q":"21点后在哪？","a":"在化妆拖车，帮化妆师修假发，头套的线又崩了。从九点修到十点多，导演叫我才去仓库，她可以作证。"},{"id":"t_find","q":"怎么发现的？","a":"二十二点十六分我刷卡进正门，灯亮着，喊了两声“谭哥”没人应。走到里头……我腿一软，赶紧叫人。"},{"id":"t_sword","q":"凤阙刀是真的吗？","lie":true,"a":"是真的，下午我亲手锁进刀匣的，沉，一掂就知道没动过。这个东西啊，我闭着眼睛也认得。","truth":"……不是。上个月十二号祁总借走备用钥匙，叫我把刀换了，给了两万封口。谭哥今天一掂就知道了。"},{"id":"t_key","q":"刀匣钥匙谁有？","needs":["clue:c_off1"],"a":"匣子钥匙我腰上一把，备用的在办公室登记着。祁总上个月借过，说拍宣传照，第二天就还了。"},{"id":"t_fight","q":"今天吵过吗？","lie":true,"a":"没有，谭哥人好，我们从来没红过脸。这个东西啊，我们俩连大声说话都没有过，有话他好好讲。","truth":"下午吵了，吵得凶。他掂了刀问我是不是早知道，我不敢认。他说要报告。我怕丢饭碗，可我没杀他。"},{"id":"t_door","q":"侧门07卡呢？","needs":["clue:c_wh2"],"lie":true,"a":"我的卡是Y-008，二十二点十六分进的正门，就那一次。07卡是办公室发的临时卡，没经过我手。","truth":"那张卡是我让她留着的。下午小戚来取道具，我随口说卡先别还，省得晚上再跑。听说卡进了侧门，我吓哑了。"},{"id":"t_habit","q":"谁常来B库？","needs":["clue:c_wh2"],"a":"武行，美术，场记。场记小戚最常来，取连戏小道具，手脚很轻。下午她还来过，待了二十来分钟。"}],"confronts":[{"clue":"c_wh3","breaks":"t_sword","a":"他的手在钥匙串上停住：“被你找出来了。我就知道谭哥掂的那一下，迟早出事。这个东西啊，我对不起它。”"},{"clue":"c_off1","breaks":"t_door","a":"他盯着“先留着”，认出自己的笔迹，声音发虚：“是我写的。我就想省她一趟腿，哪晓得……”"},{"clue":"c_rm5","a":"他看着工作单，肩膀松了点：“那顶头套我对了一个多钟头的线，化妆师的签名可不是我替她写的。”"},{"clue":"c_rm2","breaks":"t_fight","a":"他读到“刀的事，杀青后找老祁”，肩膀塌了。“谭哥给我留了面子。下午吵归吵，到底没往外说。”"}],"fallback":"这个东西啊，我没碰过，不清楚。"},{"id":"mei","name":"梅敏仪","role":"艺人经纪人","age":38,"look":{"skin":"fair","hair":"bun","hairColor":"black","glasses":"none","beard":"none","outfit":"suit","acc":"headset","mood":"stern"},"bio":"周衍工作室经纪人，也管女主角舒见月。送周衍去门岗后回宴会厅，说后半场一直陪着舒见月。","demeanor":"语速快，爱说“这样，我给你捋一下”，客气里带刺。","topics":[{"id":"t_role","q":"你是做什么的？","a":"周衍和见月都是我带的。这样，我给你捋一下：我的活，就是不让艺人出事，谁喝多了发朋友圈我都得兜。"},{"id":"t_gate","q":"周衍几点走的？","needs":["clue:c_gate1"],"a":"八点五十五，我陪他到门岗签了字，九点整回来的。他赶二十三点十分的飞机，不能晚。这个点我不会记错。"},{"id":"t_where","q":"21点后在哪？","a":"在休息拖车，和见月。她那点破事我得跟她聊聊，聊到快十点一刻才出来。见月可以作证。"},{"id":"t_inter","q":"和谭铁山有矛盾？","lie":true,"a":"矛盾？没有啊。谭老师帮了周衍不少，我们上下都感激他。私下就更没有了，同一个组的人而已。","truth":"他要接杂志采访，说周衍不打动作戏，人设塌了代言要赔几千万。我拿保密协议逼他，他撕了。我怕他，没杀他。"},{"id":"t_artist","q":"见月接了别的戏？","needs":["clue:c_rm3"],"lie":true,"a":"见月的档期我一手排，没有任何别的工作，杀青后三个月都是空的。你别拿八卦当线索，我不太高兴。","truth":"半个月前我就在她包里看到对家剧本，假装没看见。今晚才摊牌，她哭成那样，我骂了她一个小时。"},{"id":"t_sword","q":"你觉得谁可疑？","needs":["clue:c_off2"],"a":"刀有问题。验刀那一栏全是祁海生一个人写的，他从不让我们看刀。这样，我给你捋一下：他图什么？"}],"confronts":[{"clue":"c_off3","breaks":"t_inter","a":"她盯着撕碎的协议，眼神冷了一瞬：“是我让他签的，他撕了，我也撕了。我拿合同吓他，没拿刀。”"},{"clue":"c_rm3","breaks":"t_artist","a":"她敲了敲对家剧本的封面：“被你翻出来了。是，我骂了她一个小时，可那是公司的家事，跟他的死无关。”"},{"clue":"c_gate1","a":"她看着自己的签名，点头：“对，是我送的。后来的事你问见月。不过这页最好别让周衍工作室的人看见。”"},{"clue":"c_rm2","a":"她读完那页待办和没写完的信，沉默了很久，苦笑一下：“这个人，到死都没把话说绝。”"}],"fallback":"这样，你换个问法，我给你捋一下。"},{"id":"shu","name":"舒见月","role":"女主角","age":29,"look":{"skin":"fair","hair":"long","hairColor":"black","glasses":"none","beard":"none","outfit":"dress","acc":"earrings","mood":"sad"},"bio":"《凤阙行》女主角。她说宴上喝多了，后来回休息拖车歇着，案发时与经纪人梅敏仪在一起。","demeanor":"声音轻，爱说“其实”，伤心处会停一下，带吴语软调。","topics":[{"id":"t_relation","q":"和谭铁山熟吗？","lie":true,"a":"只是同事吧。他是武指，我是演员，拍戏时打过些交道，其实除此以外没有什么私下来往，就这样。","truth":"他是我师父。我进组只会跑龙套的功夫，他每天六点陪我练。我叫他师父，他不让外传，怕人说闲话。"},{"id":"t_where","q":"21点后在哪？","a":"其实，我在休息拖车和梅姐在一起。她说我两句，我就哭了好久。她十点一刻才走，我才听说出事。"},{"id":"t_contract","q":"你接了别的戏？","needs":["clue:c_rm3"],"lie":true,"a":"没有，杀青后我休息三个月，公司都排好了，什么别的戏也没接，其实我也想好好睡一觉。","truth":"签了对家，半个月前，违反了独家条款。明天九点试装。梅姐骂了我一个小时。师父劝我早说，我没勇气。"},{"id":"t_last","q":"最后一次见他？","a":"其实，是祝酒之后。他冲我挥了挥拳头，说“压轴看师父的”。我给他回了个表情，他回我一个抱拳。"},{"id":"t_mood","q":"他最近有心事吗？","needs":["ask:shu.t_relation"],"a":"师父这个月不对劲。有天夜里我看到他站在场记桌前，看着小棠的背影看了很久。他说像一个故人。"},{"id":"t_photo","q":"祝酒时拍过吗？","needs":["clue:c_mon2"],"a":"拍了一小段发给我妈，微信显示八点三十七分。那会儿我还没哭，也没被拉去拖车。你问这个干什么？"}],"confronts":[{"clue":"c_ban3","breaks":"t_relation","a":"她看着那条“师父，谢谢您今天”，一下捂住嘴：“被你看到了。我从不敢当着人叫他师父，这是我们的秘密。”"},{"clue":"c_rm3","breaks":"t_contract","a":"她看着画满注解的剧本，咬着唇：“是我的。违约金不是小数目，我不敢说。师父说，要说就别等人逼你。”"},{"clue":"c_rm2","a":"她读到没写完的信，眼泪掉下来：“师父是不是早就打算好了？他说过，等这部戏完了，想了结一件事。”"},{"clue":"c_mon1","a":"“我在里面。”她看着画面里的自己，轻声说，“其实，那时候我还在笑。那天晚上，只有那一会儿是开心的。”"}],"fallback":"其实……这个我不太懂，你问我别的？"},{"id":"cen","name":"岑子昂","role":"编剧","age":36,"look":{"skin":"light","hair":"messy","hairColor":"brown","glasses":"round","beard":"none","outfit":"turtleneck","mood":"smirk"},"bio":"《凤阙行》编剧，刻薄爱引用，被请来当杀青宴“文化顾问”。他说一直待在宴会厅聊剧本。","demeanor":"毒舌，爱掉书袋，心虚时反问“你读过吗”。","topics":[{"id":"t_role","q":"编剧做什么？","a":"把一个故事写好，再看着它被导演、制片、演员和天气一块块拆开。杀青宴是葬礼，我是念悼词的人。"},{"id":"t_where","q":"21点后在哪？","lie":true,"a":"宴会厅，和几个文艺青年的残余势力聊剧本，我一步没挪过，你可以问满屋子的人，都看见了。","truth":"二十一点二十到五十，我在B库侧门外后巷抽烟、打电话。禁火区抽烟，我怕被抓，更怕被问为什么站在那儿。"},{"id":"t_saw","q":"后巷看到什么？","needs":["ask:cen.t_where"],"a":"二十一点半前后，侧门开了，一个人低着头快步出来，手捂着胸口。路灯被树挡着，没看清脸。"},{"id":"t_height","q":"那人多高？","needs":["ask:cen.t_saw"],"a":"一米六出头，比我矮一个头，肩窄，脚步轻。我一米八。至于是男是女，我不敢说，真看不清。"},{"id":"t_toast","q":"祝酒时你在吗？","needs":["clue:c_mon1"],"a":"在，只是没入镜。我怼了导演一句，他拿我开涮。我还发了条朋友圈，八点三十四分，不会骗人。"},{"id":"t_quarrel","q":"和他吵过吗？","a":"吵过。他说我写的打戏是“文人的幻想”，我摔了杯子。一个钟头后我们又碰了杯，他说想演我写的雨中群殴。"}],"confronts":[{"clue":"c_wh5","breaks":"t_where","a":"他看着刻“岑”字的打火机，推了推眼镜：“真是个不会保密的玩意儿。好吧，我在后巷，但我只是抽烟。”"},{"clue":"c_off1","a":"他扫了一眼登记簿，哼了一声：“场务卡？我连场务的门往哪边开都不知道。去问发卡的人，拿卡的人。”"},{"clue":"c_mon1","a":"“我不在里头，编剧永远在镜头外。”他盯着画面，嘀咕道，“墙上那只钟……我那会儿才喝第一杯。”"}],"fallback":"你读过《雷雨》吗？没读过的话，这个问题我不想答。"},{"id":"yuan","name":"袁大庆","role":"灯光师","age":55,"look":{"skin":"brown","hair":"cap","hairColor":"grey","glasses":"none","beard":"stubble","outfit":"vest","mood":"smile"},"bio":"《凤阙行》灯光师，蓝挂绳，大家叫他老袁。他说宴后一直带两个小工拆灯，没离开过一号棚。","demeanor":"四川口音，爱说“哪个”“莫得”，说谎就搓手。","topics":[{"id":"t_role","q":"灯光师干什么？","a":"管光嘛。灯往哪儿摆，给哪个演员打啥子光，我说了算。杀青了，最后就是把灯收得整整齐齐。"},{"id":"t_where","q":"21点后在哪？","lie":true,"a":"一直在棚里拆灯，两个小工跟着我，哪个不晓得？哪个也跑不了。我老袁一辈子没偷过懒。","truth":"拆到九点半，我钻灯光车喝酒睡觉去了。小工只能证明九点半以前。车里的旧灯泡我偷偷卖了，被谭哥抓过。"},{"id":"t_guy","q":"和谭铁山熟吗？","a":"熟，喝过酒也红过脸。他人不坏，嘴硬，手稳。我年轻时在别的组摔过，是他背我去的医院。"},{"id":"t_overhear","q":"席间他说过什么？","needs":["clue:c_rm1"],"a":"七点五十多，他喝多了讲《龙渊》，吹自己签字没错。邻桌场记姑娘筷子掉了，脸白得像纸。我莫放在心上。"},{"id":"t_light","q":"看到什么可疑的？","needs":["clue:c_wh5"],"a":"九点一刻有个深色外套的人影往后巷走，走得快。后来我在棚顶看见后巷红火星一根接一根，九点半都没灭。"},{"id":"t_lamp","q":"旧灯泡怎么回事？","needs":["clue:c_gate3"],"a":"公家的旧灯泡，放着也是放着，没得啥子大问题。我就想着孙子上学要钱。……你莫说出去哈。"}],"confronts":[{"clue":"c_gate3","breaks":"t_where","a":"他搓着手，笑得很难看：“被你翻出来了。是，我睡了，酒是白天剩的，灯泡也是我卖的。莫往外说哈。”"},{"clue":"c_rm1","a":"他看着那张照片：“这个姑娘……她哥哥的事我晓得一点，圈里传得快。我还以为她早就放下了。”"},{"clue":"c_mon1","a":"“我不在里头。”他指指画面，“我在棚顶拆灯，听见喊干杯，还低头看了一眼表。几点记不清喽，灯才拆一半。”"}],"fallback":"哪个晓得这是啥子？莫问我。"}],"solution":{"culprit":"qi","method":{"q":"凶手靠什么让人以为自己案发时不可能离开宴会厅？","options":["祝酒确在晚上，凶手等录像结束再离场，用抽屉里的备用卡进出仓库","请人替自己在宴会厅露面，自己趁空溜去仓库行凶，事后悄悄回席","设备时间快了一小时，旧录像被当成案发时段，再用没还的卡进出","让管钥匙的人代开仓库，自己留在宴会厅作证，由那人动手并清理"],"correct":2},"motive":{"q":"凶手为什么杀人？","options":["死者发现贵重道具被调包并要揭发，凶手受调包者指使前去灭口","死者当年检查失职并嫁祸遇难者，凶手是其亲人，听半句话失控","死者要接受采访戳穿艺人人设，凶手为保护艺人前程而出手杀人","死者当众贬低凶手的创作，多年积怨酒后爆发，随手抓起重物行凶"],"correct":1},"keyClues":["c_wh2","c_mon1","c_gate1","c_off1","c_rm1","c_rm2"],"truth":["凶手是场记戚小棠。两年前，她哥哥威亚员戚小川在《龙渊》坠亡。武指谭铁山签了检查单却没查，还说是她哥自己系错。她进组，只想等他一句真话。","21:09她借口“导演想先看刀匣”叫谭铁山去B库。21:15她借口拿蜡烛离席，21:19用下午领的、一直没还的场务卡07从侧门进去，抓起镇纸动手。","花絮机是新租的，时区是东京时间，快了一小时。祝酒其实在20:30，她却把日志写成“导演晚到”，让录像洗清入镜者，嫌疑落到没入镜的岑子昂身上。","挂钟八点半、周衍20:55离场、蛋糕20:10提货，都证明录像是旧的。岑子昂当晚在后巷抽烟，戴红绳；谭手里的是场记组的绿绳。读卡日志里的卡07，指向戚小棠。","刀被祁海生卖掉、谷春来写下“卡先留着”，只是第二层假象：谷在修假发，祁在行车记录仪里。真动机是复仇：谭其实想认错，半句话被她听成嘲弄。其余人的谎，都与命案无关。"]}},{"id":"greenhouse","title":"玻璃花房","tagline":"十一年一开的尸花旁，老园丁在花开夜里悄悄停了呼吸。","difficulty":3,"cover":"cv_greenhouse","tone":"green","brief":"十月，归棠园迎来十一年一遇的花开夜：巨魔芋绽放，宾客、摄影师和药企代表挤在花房里，忍着腐肉般的气味等第一缕白烟。清晨六点二十，实习生栗禾在花盆边发现了守园四十年的老园丁岑守拙。他靠坐矮凳，手里还握着授粉的毛笔，已经没了呼吸。园主沈知微请你来查清楚。上午十点，她要和药企签一份一亿二千万的合同。你戴上手套，推开了热带室的玻璃门。","victim":{"name":"岑守拙","desc":"归棠园老园丁，六十九岁，在花房工作四十年。死在魔芋花盆边，右手握着授粉毛笔，衣襟有呕吐痕迹。","look":{"skin":"tan","hair":"short","hairColor":"grey","glasses":"none","beard":"stubble","outfit":"apron","mood":"tired"}},"publicFacts":["花开夜在10月11日。魔芋17:40展开，19:10全开，宾客约十四人，21:20后转去餐厅吃宵夜。","法医：死于心律失常，血样提示强心苷类物质。这类物质摄入数小时后才发作，死亡时间推断为22:00至次日02:00。","巨魔芋只会让人头晕反胃，本身不致命。","凉室的药草畦种着有毒植物，只有一道矮栅栏，没有上锁。","热带室的延时摄影机18:00到23:58每两分钟一帧，没拍到他之外的人进出。","岑守拙当晚没喝开幕酒，也没吃宵夜。"],"relations":{"zhiwei":"园子的主人，和他共事四十年的老朋友","yan":"园主的儿子，想卖地，下午和他吵过架","chuan":"药企雇的植物猎人，去云岭核验居群","man":"药企代表，明天上午来签约","wu":"沈家管家三十一年，管钥匙和茶水","zhang":"隔壁养蜂的邻居，为老樟树吵了十年","sang":"受邀来拍花开夜的摄影师","lihe":"园主带的研究生，在园里实习，早上发现了他"},"links":[{"a":"zhiwei","b":"yan","text":"母子，儿子想卖东边的地"},{"a":"zhiwei","b":"lihe","text":"导师和她带的硕士生"},{"a":"zhiwei","b":"man","text":"明天上午签约的双方"},{"a":"chuan","b":"man","text":"药企雇他去云岭核验居群"}],"deathReport":{"time":"约 22:00–次日 02:00","cause":"心律失常致死，血样提示强心苷类物质","scene":"清晨 6:20，实习生栗禾在热带室花盆边发现他，靠坐矮凳旁，已无呼吸，手里还握着毛笔。","loc":"tropic","notes":["嘴角和衣襟有呕吐痕迹，瞳孔放大","体表无外伤，没有搏斗的迹象","右手仍握着授粉用的毛笔"]},"timeline":[{"t":"14:00","text":"岑守拙在繁育间走廊与沈知微谈了十几分钟。"},{"t":"17:40","text":"巨魔芋开始展开，宾客陆续入场。"},{"t":"20:15","text":"开幕酒三瓶，宾客十四人无人不适，岑守拙未取杯。"},{"t":"21:20","text":"宾客转去餐厅，岑守拙留在花盆旁等授粉。"},{"t":"23:58","text":"延时摄影最后一帧，岑守拙仍坐在矮凳上。"},{"t":"06:20","text":"栗禾发现岑守拙死亡，报警。"}],"budget":{"search":12,"ask":28},"locations":[{"id":"tropic","name":"热带室与魔芋","scene":"garden","desc":"玻璃花房最深处，空气湿热。正中大花盆里的巨魔芋撑开暗红佛焰苞，气味像腐肉混着烂洋葱。","clues":[{"id":"c_tr1","title":"花盆边的老人","text":"岑守拙靠坐在花盆边的矮凳旁，右手握着沾了黄粉的毛笔。嘴角和衣襟有呕吐痕迹，瞳孔放大。"},{"id":"c_tr2","title":"控制屏的历史","text":"温控屏记录：设定一直是28℃，仅21:28“手动设定21℃”，22:31“恢复自动28℃”。柜锁无撬痕。"},{"id":"c_tr3","title":"延时摄影的存卡","text":"23:24窗外有草帽人影。TEST夹七张测试照（15:46–15:58）：马尾白大褂者举着反光板。"},{"id":"c_tr4","title":"开花记录板","text":"夹板上岑的字：“19:30花序34℃。”下一行歪斜写着“眼睛发花，看什么都黄”。再下：“授粉窗口至凌晨二时。”"}]},{"id":"cool","name":"凉室与药草畦","scene":"lab","desc":"常年16度的药草凉室。里面一块矮栅栏围起的药草畦，立着“有毒 勿触”，窗台下是旧工作台。","clues":[{"id":"c_cool1","title":"凉室温度记录纸","text":"纸带16℃线上的尖峰：15:24（2分钟）、15:52（6分钟）、16:10（2分钟）、19:35（19分钟）。"},{"id":"c_cool2","title":"窗台的搪瓷杯","text":"搪瓷杯剩小半口茶，漂着绿碎屑。旁边的粉色保温壶缠胶布写着“禾”。纸条：杯中强心苷阳性；壶中余茶阴性。"},{"id":"c_cool3","title":"药草畦的缺口","text":"毛地黄最底下的几片大叶被齐根剪走，切口已干。工具板上园艺剪那一格是空的。"},{"id":"c_cool4","title":"洗手池与药片壳","text":"洗手池边有呕吐后冲过的痕迹。纸篓里的止吐药铝箔板（甲氧氯普胺）十格空了一格。"}]},{"id":"study","name":"知微的书房","scene":"study","desc":"二楼朝南的书房，满墙植物图谱，写字桌上摊着标本册和电脑，窗边有通向花园的侧门。","clues":[{"id":"c_st1","title":"致辞的版本记录","text":"致辞字数：15:41·2318；16:12·2331；16:22·2490。桌角红茶结了膜，杯沿干净。"},{"id":"c_st2","title":"尽调与签约文件","text":"霁安药业《YL-3专利买断协议》，1.2亿，10月12日上午签约。附件要求云岭居群“Y-07”须经第三方核验。"},{"id":"c_st3","title":"二十年前的标本册","text":"毛地黄标本贴着“Y-07 云岭 2006.9”。挑开标签，底下压着旧标签：“归棠B区 杂交栽培 2003”。"},{"id":"c_st4","title":"抽屉里的旧照","text":"褪色照片：山坡紫色毛地黄前，年轻的沈知微与一个黝黑青年并肩笑着。背面：“云岭·岑守拙 摄 · 1998”。"}]},{"id":"cottage","name":"园丁小屋","scene":"guestroom","desc":"后院的矮砖屋，岑守拙住了四十年。一张行军床，一台旧收音机，墙上挂满剪刀和日程黑板。","clues":[{"id":"c_ct1","title":"手写日程黑板","text":"黑板：“15:30歇（樟树下）/ 16:10 凉室 茶 / 花开夜 通宵”。旁边小字：“杯留窗台，最后半杯回来喝。”"},{"id":"c_ct2","title":"笔记本的压痕","text":"笔记本被撕走几页。下一页压痕断续可辨：“Y-07是B区的苗……牌子是我换的……花开夜一过……先同知微……”"},{"id":"c_ct3","title":"座机旁的便签","text":"岑的字：“13:20 川来电。云岭回来了，居群没了。先别交给药企，等我。”"},{"id":"c_ct4","title":"门口的烟头","text":"台阶下有一个薄荷爆珠烟头，烟丝还新。岑只抽烟斗，门边烟斗灰缸里是陈灰。"}]},{"id":"kitchen","name":"配膳间与门厅","scene":"kitchen","desc":"主楼一层的配膳间，墙上钉着供餐记录本和钥匙板，隔门便是通往花房的玻璃长廊。","clues":[{"id":"c_ki1","title":"邬伯的送茶记录","text":"供餐记录：“15:45 书房 红茶×1 · 无人应门，放桌；16:08 再去，太太在，茶凉未动，撤。”无涂改。"},{"id":"c_ki2","title":"晚饭与开幕酒","text":"记录：“18:05 岑伯晚饭送小屋，说没胃口；18:55 原样收回。20:15 开幕酒三瓶，岑伯未取杯。”"},{"id":"c_ki3","title":"控制柜钥匙登记","text":"登记卡：“20:30 领用 栗禾 · 22:40 还”，管家签名邬松龄。抬头规定：钥匙仅限管家与女主人，不得转借。"},{"id":"c_ki4","title":"露台的托盘","text":"记录：“18:15 露台 咖啡、清茶 · 简小姐/岑伯。”清茶没动。夹着名片，背面写“顾问费 三十万/年”。"}]},{"id":"lab","name":"繁育间与检疫缸","scene":"clinic","desc":"玻璃长廊尽头的繁育间，一排排育苗架。角落蒙着塑料膜的检疫区，墙上钉着苗圃登记卡。","clues":[{"id":"c_lab1","title":"厉川的样本包","text":"帆布包里有河滩土和照片：山洪冲过的河滩只剩乱石，标“Y-07”，日期10月8日。另有蜂园路17号的签收单，收件人“章”。"},{"id":"c_lab2","title":"没有标签的兰花","text":"检疫缸里一盆小兰花，盆上写着“厉”，无检疫标签和许可证号。叶背铅笔写着“云岭以西 · 9月”。"},{"id":"c_lab3","title":"B区的苗圃登记卡","text":"毛地黄苗架的登记卡：“归棠B-3 杂交 1998”被红笔划掉，改成“Y-07 云岭居群 2006引种”，墨色相差多年。"}]}],"suspects":[{"id":"zhiwei","name":"沈知微","role":"植物学家 · 园主","age":67,"look":{"skin":"light","hair":"bun","hairColor":"silver","glasses":"round","beard":"none","outfit":"coat","acc":"scarf","mood":"tired"},"bio":"归棠园主人，知名药用植物学家。她说下午在书房写致辞，晚上一直陪着客人，没离开过。","demeanor":"温和、慢条斯理，爱叫晚辈“孩子”，被问急了只会放轻声音。","topics":[{"id":"t_rel","q":"你和老岑关系？","lie":true,"a":"守拙吗？四十年的老伙计了。吵嘴有过，红脸没有，今天更没有。你问几遍，我都是这一句。","truth":"他两点来找我，说花开夜一过要对简小姐讲牌子的事。我求他等签完约，他说“牌子不能骗人”。我们吵了几句。"},{"id":"t_pm","q":"下午三点后在哪？","lie":true,"a":"书房，改明晚要念的致辞，三点以后没出过门。老邬来送过茶，不信你去问他好了。三点以后真没出过门。","truth":"我出去过，往花房那边走了走，剪了几枝花。几点记不清了。我没说，是怕听上去像借口。"},{"id":"t_habit","q":"他午后的习惯？","a":"三点半去樟树下歇半个钟头。他的搪瓷杯总搁凉室窗台，留半杯回来喝完。全家人都知道，谁都说得出。"},{"id":"t_origin","q":"云岭居群是真的？","lie":true,"a":"Y-07是我2006年九月在云岭亲手采的，凭证标本俱全。怀疑它，就是怀疑我一辈子。","truth":"居群2005年山洪里就没了。我手上只有B区杂交的苗，论文已发。牌子是我让守拙换的。但这与他的死无关。"},{"id":"t_night","q":"晚上你在哪里？","a":"招呼客人到后半夜。九点前去看过他，脸色不好，劝他歇，他说授粉窗口错过了要再等十一年，我就没再坚持。"},{"id":"t_deal","q":"药企的买断协议","needs":["clue:c_st2"],"a":"这化合物对一类心律失常有用。买断款要养十一个学生，撑住这座园子。我图的是它有个下文。"},{"id":"t_poison","q":"杯子和药草畦","needs":["clue:c_cool2"],"a":"药草畦的栅栏拦孩子的，没锁，谁都知道在哪。杯子是小禾泡的苦丁。老岑自己栽的东西，他不会喝错。"},{"id":"t_why","q":"他为何非要说？","needs":["ask:zhiwei.t_rel"],"a":"他说活到七十，不想带着假牌子进土。他是园丁，对苗的出身最较真。我认识他时，只到他肩膀高。"}],"confronts":[{"clue":"c_cool2","a":"她看着写“禾”字的保温壶，停了一会儿：“壶里是干净的，是么。那就好，别让她背这个。”"},{"clue":"c_tr3","a":"她认出测试照里扎马尾的背影：“小禾那阵子在帮桑先生。孩子，你们是一点点把人排除掉的么？”"},{"clue":"c_st1","breaks":"t_pm","a":"她擦着眼镜：“我写得慢，一出神就是半小时。可孩子，一份致辞的记录，不该拿来审人。”"},{"clue":"c_ki1","breaks":"t_pm","crack":true,"a":"她望着那行小楷，轻叹一声：“老邬一辈子老实。好，我出去过一会儿。但你拿这半个钟头，要问我什么？”"},{"clue":"c_cool1","breaks":"t_pm","a":"“门一开，记录笔就跳。这台仪器我父亲装的，从没错过。”她顿了顿，“15:52，我在凉室附近。”"},{"clue":"c_ct2","breaks":"t_rel","crack":true,"a":"她久久看着压痕，低声说：“他到最后也没写完整。先同知微讲一声，他真的先来讲了。我没说实话。”"},{"clue":"c_lab3","breaks":"t_origin","a":"她笑了一下，像笑自己：“字是我写的。二十年了，我以为它早烂在那堆旧牌子里，没想到被你翻出来。”"},{"clue":"c_lab1","breaks":"t_origin","a":"她一张张翻过河滩照片，手有些抖：“山洪后就是这个样子。厉川把真话带回来了，是么。”"},{"clue":"c_st3","a":"“标签底下的标签。”她合上标本册，手压在封面上，指节发白，“收藏的人最怕的，是被人看见。”"},{"clue":"c_st4","a":"她目光软下来：“1998年，云岭。那片紫色开起来像一场雾。守拙说他死也要死在花边上。”"}],"fallback":"这个东西，我想不出它和我有什么关系，孩子。"},{"id":"yan","name":"沈砚","role":"沈知微之子","age":38,"look":{"skin":"light","hair":"slick","hairColor":"black","glasses":"none","beard":"stubble","outfit":"jacket","mood":"smirk"},"bio":"沈知微独子，做地产投资，一直想卖掉园子东边的地。下午五点和老园丁吵过一架，说是为了老樟树。","demeanor":"语速快，冷嘲热讽，爱说“说白了”，被戳中就笑着岔开。","topics":[{"id":"t_role","q":"你做什么工作？","a":"地产投资，说白了就是替人算一块地值多少钱。东边那块开发商出八千万，我妈一口回绝。"},{"id":"t_fight","q":"下午吵了什么？","a":"五点，老樟树下。树根拱了边界，我要砍，他不让。我说了句气话。后来他一个人坐了很久。"},{"id":"t_aft","q":"下午三点后在哪？","lie":true,"a":"前院，坐车里打电话谈地块，两点多一直到五点。不信你查通话记录，我做生意不留空白。","truth":"我在小屋。老岑歇脚时我溜进去，翻拍了他的笔记本，想拿点我妈的把柄，逼她松口卖地。"},{"id":"t_saw","q":"出小屋后看到什么","needs":["ask:yan.t_aft"],"a":"十五点五十七分左右，小路尽头，米色开衫，应该是我妈，从凉室那头走来，手里像拎着剪刀。我没敢说。"},{"id":"t_photo","q":"你拍了什么？","needs":["ask:yan.t_aft"],"a":"一页压痕，一页撕口。“牌子是我换的，二十年了。”我当时没懂，看到尽调文件才明白。"},{"id":"t_night","q":"晚上你在哪里？","a":"陪客人，吃宵夜，二十二点前后去车里打了十来分钟电话。今晚要是不在，我妈会说我不孝。"}],"confronts":[{"clue":"c_ct4","breaks":"t_aft","a":"他盯着烟头，笑慢慢收了：“我戒了三次，只剩这个牌子。行，我去过小屋，但没碰过凉室一步。”"},{"clue":"c_ct2","a":"“就是这页，我拍过。”他苦笑一声，“我以为抓住了我妈的软肋，没想到这是一颗炸弹。”"},{"clue":"c_st2","a":"他翻着文件，嗤了一声：“一亿二。早知她底牌是这个，我就坐下来谈了，不会去偷看笔记本。”"},{"clue":"c_cool1","a":"“15:52？我在小屋，手机相册有时间戳，十五点四十一到五十五拍的。”他问，“你在怀疑我妈？”"},{"clue":"c_ki1","a":"他看了一眼那行小楷，沉默几秒：“老邬从不记错。”后半句他咽了回去，“……我什么都没说。”"}],"fallback":"说白了，这个我没兴趣，你换个问题。"},{"id":"chuan","name":"厉川","role":"植物猎人","age":51,"look":{"skin":"tan","hair":"cap","hairColor":"grey","glasses":"none","beard":"stubble","outfit":"parka","mood":"stern"},"bio":"受霁安药业雇用，去云岭核验“Y-07居群”的植物猎人。他说今早才回城，五点前到园里。","demeanor":"话少，短句，爱说“山里头”“讲真”，心虚时盯着靴子。","topics":[{"id":"t_role","q":"你是做什么的？","a":"采样的。山里头跑了二十八年。药企给钱，我去把居群拍照、取土取叶，回来交差，不管别的。"},{"id":"t_back","q":"什么时候回城的？","lie":true,"a":"今早的航班。下午到市里办完手续就赶过来，五点前进的园子，路上有监控，不信你去查。","truth":"十月八号就回来了，躲在章老师家。云岭居群没了，河滩上只有石头。我拿着药企的钱，不敢交底。"},{"id":"t_call","q":"和岑师傅通过话？","needs":["clue:c_ct3"],"a":"十一号下午一点二十，打小屋座机。我说居群没了，山洪冲的。他半天没吭声，说“先别交给药企，等我”。"},{"id":"t_site","q":"云岭现在什么样？","needs":["ask:chuan.t_back"],"a":"岩壁上的水位线比人头还高。老乡说二〇〇五年夏天那场洪水，整条沟的毛地黄全冲走了。"},{"id":"t_orchid","q":"检疫缸里的兰花？","lie":true,"a":"手续齐全，检疫证、许可证都在文件夹里，你随便翻。我做这行的，不会在这上头栽跟头。","truth":"没手续。九月在云岭以西采的，是保护物种，我想悄悄带回来研究。罚我认，这事与死人无关。"},{"id":"t_fee","q":"药企给你多少钱？","a":"核验费四十万，居群证实了再加二十。现在这二十拿不到了，四十也得吐。但我不会为这杀人。"},{"id":"t_aft","q":"下午三点后在哪？","needs":["ask:chuan.t_back"],"a":"章老师家，从下午一点到快五点，喝茶，看他修蜂箱。五点前我从后院小路进的园子，不是走的大门。"},{"id":"t_night","q":"晚上你做了什么？","a":"听了一阵致辞，受不了味，去繁育间看兰花。二十二点五十出去，二十三点半回来，一个人。"}],"confronts":[{"clue":"c_lab1","breaks":"t_back","a":"他盯着自己的照片：“拍照日期是八号。好，我骗了你。我回来三天了，不敢见任何人。”"},{"clue":"c_lab2","breaks":"t_orchid","a":"他侧过脸，不看缸里的兰花：“……我知道会有这一天。罚款我认，别写进杀人案的卷宗。”"},{"clue":"c_ct3","a":"他喉结动了动：“他写得比我说得清楚。‘先别交给药企，等我’。我答应了他，他就先走了。”"},{"clue":"c_st2","a":"“核验报告须于签约前提交。”他苦笑，“签约是明天上午，我手里却是一堆石头照片。”"},{"clue":"c_ct2","a":"他一字一字读完压痕：“老岑只跟我说‘先别交，等我’。讲真，我现在才懂，他是想自己去讲。”"}],"fallback":"山里头的东西，这个我没见过。"},{"id":"man","name":"简曼","role":"霁安药业代表","age":41,"look":{"skin":"fair","hair":"long","hairColor":"brown","glasses":"rect","beard":"none","outfit":"suit","acc":"earrings","mood":"smile"},"bio":"霁安药业商务拓展负责人，来参加花开夜，办明天上午的签约。她说傍晚才远远见过岑师傅。","demeanor":"职业微笑，措辞严谨，爱说“合规”“咱们”，被追问时语速变慢。","topics":[{"id":"t_role","q":"你来园里做什么？","a":"代表霁安来见证花开夜，也是明天上午签约的前置环节。YL-3是咱们今年最重要的项目。"},{"id":"t_talk","q":"和岑师傅聊过吗？","lie":true,"a":"没有，傍晚只在人堆里远远看过他一眼。园丁和咱们这类商务人员，本来也没什么交集，真要谈也是找沈老师。","truth":"聊过，十八点十五分在露台。他说“签约前我有话跟你讲”。我误会他要涨价，递了张顾问费名片。他看我的眼神像受了侮辱。"},{"id":"t_check","q":"尽调有风险吗？","lie":true,"a":"没有。云岭居群核验只是例行手续，合规部门早已通过。沈老师论文发表二十年，没人质疑过。","truth":"其实我心里发毛。厉川十天前就失联，我没向总部报。指望他签约前赶回来。一汇报，项目就黄了。"},{"id":"t_fee","q":"三十万的顾问费","needs":["clue:c_ki4"],"a":"这是行业里的惯例，合规，不违法。他拒绝了，我没再追。我碰到了一个不能用钱谈的人。"},{"id":"t_aft","q":"下午三点后在哪？","a":"机场出来，十七点三十到的园门，门岗有登记。十五点到十七点在路上，同行助理可以作证。"},{"id":"t_night","q":"晚上你在哪里？","a":"二十二点前在餐厅陪客，之后在车里给总部发邮件。签约不能改期。我焦虑，但没到杀人。"}],"confronts":[{"clue":"c_ki4","breaks":"t_talk","a":"她看着名片，笑僵了：“管家记得真细。好，我和他谈过。没说实话，是因为这数字像贿赂。”"},{"clue":"c_st2","breaks":"t_check","a":"她长出一口气：“核验条款是我们自己写的。厉川一直没回我，我也没敢报总部。是，我撒了谎。”"},{"clue":"c_ct3","a":"“居群没了……”她脸慢慢发白，“岑师傅要说的就是这个？他明天一开口，项目全作废。”"},{"clue":"c_lab1","a":"她翻着照片，动作很轻，嘴唇抿成一条线：“厉川八号就回来了？这三天躲着我，原来是这个。”"}],"fallback":"这个，咱们得按合规流程来谈，我不便评价。"},{"id":"wu","name":"邬松龄","role":"归棠园管家","age":63,"look":{"skin":"light","hair":"short","hairColor":"white","glasses":"rect","beard":"none","outfit":"vest","mood":"worried"},"bio":"沈家管家三十一年，花房的钥匙、账本和规矩都归他管。他说太太整个下午都在书房写东西。","demeanor":"老派恭敬，开口先说“您”，提到太太时语气一下子硬起来。","topics":[{"id":"t_role","q":"管家都管什么？","a":"三十一年，园子里的钥匙、账本、客人茶水、仆役班次，都归我管。规矩是我立的，也是我守的。"},{"id":"t_tea","q":"下午太太在书房吗？","lie":true,"a":"整个下午都在书房。十五点四十五我送红茶，她说放着，我就放着。太太写东西不喜欢人打扰，我不会记错。","truth":"十五点四十五我进去，书房没人，我放下茶就走。十六点零八分再去，太太已在，茶一口没动。我是想替太太圆个话。"},{"id":"t_key","q":"温控柜的钥匙呢？","lie":true,"a":"两把钥匙，一把在我身上，一把在太太那儿，从来没外借过。这是规矩，您可以看登记卡。","truth":"二十点三十，栗小姐来领，说摄影师要拍花序，得调室温。我想是太太请来的人，就借了。二十二点四十还回来。"},{"id":"t_found","q":"早上怎么发现的？","a":"栗小姐六点二十打电话到我房里，声音抖得说不清。我赶过去，他已经凉了。我只用外套盖了他的脸，就报了警。"},{"id":"t_back","q":"太太回来时什么样？","needs":["ask:wu.t_tea"],"a":"十六点零八分，太太从侧门进来，脸色白，袖口蹭着一抹青绿，像叶汁。她说头有点晕，不让请医生。"},{"id":"t_loyal","q":"你信得过太太吗？","needs":["ask:wu.t_tea"],"a":"我跟了太太三十一年，守拙是她的老朋友，我不信她会……但您问到这儿，我不能再替她撒谎了。"}],"confronts":[{"clue":"c_ki1","breaks":"t_tea","a":"他看着自己的笔迹：“是我的字，我不会改。”背塌了一点，“请别告诉太太是我说的。”"},{"clue":"c_ki3","breaks":"t_key","a":"他声音哑了：“登记卡是我填的，我违了规矩。请别以为温控与命案有关，我只是给年轻人开了个口子。”"},{"clue":"c_st1","a":"他看着那条记录，抿紧了嘴，很久才低声说：“那是太太的电脑里的东西，我不懂这些。”"},{"clue":"c_ct2","a":"“先同知微讲一声。”他念出声，眼神黯下去，“守拙大哥对太太，一辈子没半句重话。”"},{"clue":"c_tr2","a":"“温控是栗小姐动的，用的我借出去的钥匙。”他苦笑，“这条被警方看见，我这管家做到头了。”"}],"fallback":"这个，恕我不便多说。您请继续。"},{"id":"zhang","name":"章吉安","role":"退休教师 · 邻居","age":68,"look":{"skin":"light","hair":"short","hairColor":"white","glasses":"round","beard":"none","outfit":"vest","mood":"smile"},"bio":"住隔壁蜂园路的退休生物老师，养蜂，和老园丁为老樟树吵了十年。他说花开夜在家睡了。","demeanor":"絮叨爱讲课，句句“我跟你讲”，被追问就东拉西扯。","topics":[{"id":"t_role","q":"你和归棠园的关系？","a":"我跟你讲，我教了三十五年生物，退休养蜂。隔壁这园子，是我最想进又最不敢进的地方。"},{"id":"t_tree","q":"你和岑师傅的矛盾","a":"那棵樟树树荫盖了我四箱蜂。我谈了十年，他说“树比人老，你让”。我说过让雷劈了它。劈树，不是劈人。"},{"id":"t_night","q":"花开夜你在哪？","lie":true,"a":"在家记账，核算今年的蜜量，九点就睡了。我这岁数早起早睡，你去问邻居，灯是几点灭的。","truth":"我翻墙进来看花。一辈子没见过开花的魔芋。二十三点十分，我贴着玻璃看了十几分钟，那草帽是我的。"},{"id":"t_saw","q":"你看到了什么？","needs":["ask:zhang.t_night"],"a":"岑守拙坐矮凳上，握毛笔的手抖得厉害。我敲玻璃，他冲我摆手，嘴型是“别叫人……花”。我就没吭声。"},{"id":"t_guest","q":"最近家里有客人吗？","lie":true,"a":"没有。我一个糟老头子，一个人住，蜂箱都是自己一箱一箱搬的，家里哪来的客人，你不信可以去数。","truth":"有。厉川住我家，十月八号回来的，是我从前的学生。他说有件事不能让药企知道，我没问。他下午一直在，快五点才走。"},{"id":"t_gate","q":"你怎么进来的？","needs":["ask:zhang.t_night"],"a":"东墙靠樟树那块，下雨后塌了一截，我踩着蜂箱就上来了。你别告诉老沈，我这脸往哪搁。"}],"confronts":[{"clue":"c_tr3","breaks":"t_night","a":"他看着草帽人影，干笑：“抓到了，那帽子是老伴买的。好，我去过。可我走时他还活着。”"},{"clue":"c_lab1","breaks":"t_guest","a":"他叹了口气：“那是我家地址。川子是我学生，一进门就说‘章老师，别问’，我就没问。”"},{"clue":"c_tr1","a":"他手在口袋里攥紧：“他握着毛笔……我就知道。”低声说，“我要是回头看一眼就好了。”"},{"clue":"c_cool2","a":"“杯子里有毛地黄？”他愣住了，“老岑自己种的东西，他怎么会不知道。……谁干的？”"}],"fallback":"我跟你讲，这个我不太熟，换个问题。"},{"id":"sang","name":"桑野","role":"纪录片摄影师","age":33,"look":{"skin":"tan","hair":"messy","hairColor":"black","glasses":"none","beard":"stubble","outfit":"hoodie","acc":"headset","mood":"smirk"},"bio":"受邀拍花开夜的摄影师，下午三点到场，在热带室架了延时机位。他说自己没碰过花房设备。","demeanor":"随性，满嘴行话，爱说“哥们儿”“你懂的”，被抓包就挠头。","topics":[{"id":"t_role","q":"你在这里做什么？","a":"拍纪录片。下午三点到场，架了延时机位，两分钟一帧，十八点拍到零点。哥们儿，这是我最臭的一次拍摄。"},{"id":"t_ctrl","q":"你动过温控吗？","lie":true,"a":"没有，温控是人家花房的东西，我碰了出事怎么办。我只管拍，你懂的，别的不碰，哥们儿。","truth":"是我让栗禾去调的。我想拍花序顶上的蒸汽，室温太高看不见，得降到二十一度。钥匙的事我们瞒着，对不起。"},{"id":"t_plume","q":"蒸汽拍到了吗？","needs":["ask:sang.t_ctrl"],"a":"拍到了！二十一点四十，一缕一缕往上飘，像仙气。没想到这一夜还有人死在边上，真是造孽。"},{"id":"t_yellow","q":"他当时状态如何？","needs":["clue:c_tr3"],"a":"二十点五十他说“灯都晕成黄的了”。我以为他喝多了，他从不喝酒啊。后来他一直守着那盆花。"},{"id":"t_frames","q":"存卡被删过吗？","a":"一帧没删，一百八十张，原片我没动。时间戳是机器自带的，我动不了。你可以把存卡拷走。"},{"id":"t_out","q":"后来你离开过吗？","a":"二十二点四十到二十三点十五，我去外面车里传蒸汽预览图，就是那几帧。别的时间都在花盆附近。"},{"id":"t_helper","q":"下午有人帮你吗？","needs":["ask:lihe.t_aft"],"a":"栗禾。三点四十来的，给我举反光板拍测试，到快四点。她本该去巡苗圃，你别说是我拉的壮丁。"}],"confronts":[{"clue":"c_tr2","breaks":"t_ctrl","a":"他挠头：“看来这东西会记账啊。对，是我让栗禾去调的。我不想背锅，可没想到这么巧。”"},{"clue":"c_ki3","breaks":"t_ctrl","a":"“得，这下邬伯饭碗也被我砸了。”他叹气，“调温度只为拍蒸汽，跟他的死没关系，你信我。”"},{"clue":"c_tr3","a":"他指着二十三点二十四那帧：“这草帽人影是隔壁老头，还朝镜头挥手呢。那会儿岑师傅还活着。”"},{"clue":"c_cool1","a":"“尖峰？我就一拍片的。”他耸肩，“不过要是有人进过凉室，那张纸带肯定会跳。哥们儿你聪明。”"}],"fallback":"哥们儿，这个我真不懂，你问别人吧。"},{"id":"lihe","name":"栗禾","role":"研究生 · 实习生","age":23,"look":{"skin":"fair","hair":"ponytail","hairColor":"black","glasses":"round","beard":"none","outfit":"labcoat","mood":"worried"},"bio":"沈知微带的硕士生，在园里实习半年，第一个发现老园丁死亡的人。她说下午一直在繁育间整理幼苗。","demeanor":"紧张爱道歉，常以“呃”开头，被追问就低头抠手指。","topics":[{"id":"t_role","q":"你在园里负责什么？","a":"呃，观测、记录、浇水，帮岑伯整理苗圃。我的课题挂在YL-3下面，做云岭居群的栽培对照。"},{"id":"t_fight","q":"下午五点的争吵","a":"沈先生要砍樟树平地，岑伯不让，在树下吵了十几分钟。岑伯说“你砍了树，我就搬走”。"},{"id":"t_cup","q":"那杯茶谁泡的？","lie":true,"a":"呃，岑伯自己泡的吧？那是他用了几十年的杯子，他的茶，他的规矩，我哪敢碰，就是偶尔路过看一眼。","truth":"是我泡的。他说胃里烧得慌，我用苦丁泡了一壶，三点二十几分倒进他杯子。他喝了半杯，说“够味”。我怕你们说是我下毒。"},{"id":"t_aft","q":"下午三点后在哪？","lie":true,"a":"呃，我在繁育间整理幼苗，三点到五点都没出去过。真的，我整天都没出去过，巡检本上有我的签名。","truth":"不全是。三点四十到快四点，我在热带室给桑老师举反光板。本该去巡苗圃，怕沈老师知道。"},{"id":"t_pill","q":"你给过岑伯药吗？","lie":true,"a":"没有，我怎么会给别人药？我只是实习生，不敢乱给的。他一直说没事，我就帮他搬东西。","truth":"给了。十九点四十五分，他已吐过一回，我给了他一片自己带的止吐药。他叮嘱别声张。我怕你们怪药。"},{"id":"t_ear","q":"下午听到什么？","lie":true,"a":"呃，我下午整个人都在繁育间里整理幼苗，窗户也关着，什么都没听见。我这人做事很专心。","truth":"听见了。两点前后，岑伯对沈老师说“牌子不能骗人”，沈老师说“等签完约”。我的课题全压在云岭居群上，不敢说。"},{"id":"t_bitter","q":"他后来说过什么？","needs":["ask:lihe.t_cup"],"a":"十六点二十，他回凉室喝完最后半杯，皱眉说“今天茶苦，像泡了老叶子”。他不爱浪费。"},{"id":"t_lunch","q":"午饭后聊过什么？","needs":["ask:lihe.t_cup"],"a":"廊下，岑伯揉着胃说烧得慌，沈老师和邬伯都在。我说下午给他泡壶苦丁，沈老师还点头夸我细心。"},{"id":"t_ctrl","q":"热带室温控怎么回事？","lie":true,"a":"呃，我没碰过温控。控制柜是上锁的，钥匙在管家手里，我一个实习生，哪敢去动那些东西，真的不敢。","truth":"是桑老师让我调的，说要拍蒸汽。我向邬伯领了钥匙，二十一点二十八降到二十一度，二十二点三十一调回。"}],"confronts":[{"clue":"c_cool2","breaks":"t_cup","a":"她盯着写“禾”的壶：“……是我的壶。我怕你们觉得是我。可壶里的茶我自己也喝了，没事。”"},{"clue":"c_tr3","breaks":"t_aft","a":"她凑近测试照，认出自己的背影，脸红了：“我举着板子手酸得发抖……对，我没在繁育间。”"},{"clue":"c_cool4","breaks":"t_pill","a":"她盯着纸篓里的铝箔板，红到耳朵：“……那一片是我的。我怕你们以为是药的问题，也怕被学校知道。”"},{"clue":"c_ct2","breaks":"t_ear","a":"她读完压痕，眼眶红了：“对，我听见了。我一直在想，是不是我早点说，就会不一样。”"},{"clue":"c_ki3","breaks":"t_ctrl","a":"她看到登记卡上自己的名字，咬着嘴唇点头：“是我领的。对不起，邬伯，我不是故意连累你。”"},{"clue":"c_cool1","a":"她数着尖峰：“十五点二十四，是我，送茶。十九点三十五，他在里头吐，我在外面等。别的我说不清。”"},{"clue":"c_tr4","a":"她读着夹板，小声说：“他写这行‘眼睛发花’时我就在旁边，他还冲我笑，说是老毛病。”"}],"fallback":"呃，这个我真的不知道，对不起。"}],"solution":{"culprit":"zhiwei","method":{"q":"凶手如何下毒，又有夜里的不在场证明？","options":["晚上递止吐药时把毒混进药片，让他吞下，守花途中慢慢发作。","午后趁他离开，往窗台那杯剩茶里加药草，数小时后发作。","泡茶的人一开始就下了毒，他分两次喝完，夜里发作。","在冷藏花粉瓶里掺毒粉，他授粉时吸入，夜里发作。"],"correct":1},"motive":{"q":"凶手为什么要杀人？","options":["他死守东边地块不肯让，凶手急着变现，还被他当众顶撞。","他握着好处费当凭据，凶手怕行贿丑闻毁了到手的合作。","他要在签约前讲出换牌旧事，凶手要保论文与买断款。","他一开口课题就作废，凶手多年投入和出路都要落空。"],"correct":2},"keyClues":["c_cool1","c_cool2","c_st1","c_ct2","c_ki1","c_ki2"],"truth":["凶手是沈知微。她没在夜里的人群中下手，而是在午后趁岑守拙去樟树下歇脚，往他留在凉室窗台的茶杯里下了毒叶。","毒不是夜里下的。他18:05没胃口，19:30写下“眼睛发花”，19:35在凉室呕吐，都早于止吐药和开幕酒。强心苷数小时才发作，他硬撑到零点后死去。","栗禾曾像嫌疑人：壶、杯、15:24记录都有她。但壶中余茶阴性，岑说第二半杯才苦；15:46–15:58她在热带室举反光板。她那句“泡苦丁”被沈知微听见，成了掩味的一环。","15:52谁进了凉室？沈砚在小屋，厉川在章家，桑野栗禾在热带室。只剩沈知微：致辞15:41到16:12几乎没增字，邬伯送茶时书房无人，她回来袖口沾叶汁，沈砚见她拎着剪刀。","动机是二十年前的假牌子：云岭居群2005年毁于山洪，她让岑把B区杂交苗换成“Y-07”。岑要在签约前坦白，她求他等等，他说“牌子不能骗人”。其余人的谎言只是各有隐情。"]}},{"id":"homestay","title":"雪山民宿","tagline":"暴雪封山的民宿里，主人死在从内反锁的房间，八个人谁也走不了。","difficulty":3,"cover":"coverHomestay","tone":"cold","brief":"昨天午后一场罕见的暴雪封了山路。旅行博主、“栖雪山居”民宿主人山屿，今早被发现死在二〇二房间，门从里面插着插销，窗也锁着，窗外积雪没有脚印。警方最快明天才能上山，你受镇派出所老同学所托，骑雪地摩托先到了民宿。大厅的炉火烧得很旺，却没有一个人敢靠近二楼。八个人围着壁炉，都说什么也不知道。你搓搓冻僵的手，开始一个个看他们的脸。","victim":{"name":"山屿（商屿）","desc":"33岁，一百二十万粉丝的旅行博主，民宿主人。今早倒在二〇二房间地毯上，面颈肿胀，满身红疹，喉部有抓痕。","look":{"skin":"light","hair":"slick","hairColor":"black","glasses":"none","beard":"stubble","outfit":"vest","mood":"smirk"}},"publicFacts":["山屿，本名商屿，33岁，旅行博主，民宿主人。","昨天午后雪封山路，晚上七点起手机信号中断。","今早七点二十撞开二〇二：插销插死，窗内锁，窗外积雪无脚印。","遗体面颈肿胀、满身红疹，喉部有抓痕；现场没有打斗痕迹。","民宿里共八人：四位房客、管家、杂工、运营和一个借宿学生。","电话初步判断，死亡时间在昨晚二十二点到二十四点之间。"],"relations":{"lin":"住203的房客，昨晚在大厅和他大吵","xing":"装修老板，他欠着八十六万尾款","wei":"民宿管家兼厨师，管他的饮食","he":"民宿运营兼摄像，替他剪片管号","su":"住201的房客，和他只隔一堵墙","xu":"住204的房客，自称是他的粉丝","zhou":"民宿杂工兼向导，干了十年","qiao":"借宿的徒步学生，睡地下储藏间"},"links":[{"a":"su","b":"xu","text":"昨晚在壁炉边聊天，聊到快十点"},{"a":"wei","b":"zhou","text":"同在民宿多年的老员工"},{"a":"qiao","b":"lin","text":"偷听了她和山屿的大厅争吵"}],"deathReport":{"time":"约 22:00–24:00","cause":"窒息，喉头水肿，现场表现似严重过敏发作","scene":"今早七点二十，周守山与邢大海撞开二〇二的门，发现山屿倒在地毯上，门从内插死。","loc":"room","notes":["面颈肿胀，满身红疹，喉部有抓痕","指缝带血，靠201一侧墙根有新磕痕","书桌上的保温杯还剩小半杯姜茶","窗锁完好，窗外积雪无脚印"]},"timeline":[{"t":"14:00","text":"暴雪封山，所有人被困民宿。"},{"t":"19:00","text":"晚饭，山屿另有一份魏敏单做的饭菜。此后手机信号中断。"},{"t":"21:00","text":"前后，大厅里山屿与一位女房客激烈争执，约21:15结束。"},{"t":"22:05","text":"山屿拿着保温杯，穿着橙色背心，独自上楼回房。"},{"t":"23:10","text":"前后，有人在202门外敲门，无人回应。"},{"t":"07:20","text":"周守山与邢大海撞开房门，发现山屿已死。"}],"budget":{"search":12,"ask":26},"locations":[{"id":"room","name":"二〇二主人房","scene":"guestroom","desc":"二楼走廊中段的主人房，暖气还开着，空气里有淡淡的姜味。门框上的插销座被撞裂。","clues":[{"id":"c_room1","title":"山屿的保温杯","text":"书桌上的保温杯剩小半杯姜茶，杯底沉着浅褐色的细沉淀，闻着有烘过的坚果味。"},{"id":"c_room2","title":"背心与翻乱的抽屉","text":"背心左口袋敞开，空的，布面有笔形压痕。抽屉倒在地上，散落一张卡片：“花生过敏。发作注射肾上腺素，拨120。”"},{"id":"c_room3","title":"反锁的门窗与遗体","text":"门内插销推到底，插销座撞裂，窗锁完好。遗体脸颈红肿，指缝带血；靠201的墙根有新磕痕，门外下缘有靴尖泥印。"}]},{"id":"kitchen","name":"民宿厨房","scene":"kitchen","desc":"一楼后侧的厨房，有小门通后院，案板边堆着没收拾完的碗碟。","clues":[{"id":"c_kit1","title":"垃圾桶里的小瓶","text":"垃圾桶里有只空分装瓶，标签被撕，残角印着蓝色细线，内壁糊着坚果酱；旁边有只用过的塑料手套。"},{"id":"c_kit2","title":"厨房值班本","text":"魏姐的值班本：“21:35姜蜜茶装杯，放操作台。22:00山屿下楼取杯。”另写：山屿的饭“无任何坚果”。"},{"id":"c_kit3","title":"未拆封的牛轧糖","text":"料理台上有盒系丝带的花生牛轧糖，塑封完好，卡片写着“给山屿——鹿”。"}]},{"id":"hall","name":"一楼大厅","scene":"hall","desc":"带壁炉的大厅，楼梯通二楼，门边立着一排衣帽架。","clues":[{"id":"c_hall1","title":"书架后的运动相机","text":"书架后藏着相机。21:52:04壁炉边两女人背对镜头；一只戴荧光绿腕带的手，从衣帽架湿背心口袋摸走一支细筒。"},{"id":"c_hall2","title":"装修催款函","text":"催款函：山屿欠“大海装饰”装修尾款86万，逾期八个月，落款“邢”。后附银行逾期通知。"},{"id":"c_hall3","title":"前台登记本","text":"登记本里“沈晴”的身份证复印件被胶带遮住，露出一个“苏”字。中间一页被撕走，残留三年前十月的日期。"}]},{"id":"garden","name":"后院与火盆","scene":"garden","desc":"后院屋檐下摆着铜火盆，雪积了一尺厚。运营室的侧门通向这里。","clues":[{"id":"c_gar1","title":"火盆里的残骸","text":"火盆灰里有截半融的塑料圆筒，残留“上腺素”字样；旁有烧卷的标签，剩“商屿”“自动”。"},{"id":"c_gar2","title":"通向火盆的脚印","text":"运营室侧门到火盆有串往返脚印：软底拖鞋纹，无鞋跟印，步幅小。火盆前撒着炭灰。"},{"id":"c_gar5","title":"柴房门边的挂钉","text":"柴房钉子上挂着荧光绿反光腕带，内侧写着“周”；门槛下是一双粗纹高筒胶靴。"},{"id":"c_gar3","title":"门廊下的烟蒂","text":"门廊下有六七根“黄鹤楼”烟蒂，旁边雪地里有个人形凹坑，雪被蹭乱一大片。"},{"id":"c_gar4","title":"东墙角的挂绳","text":"东墙角信号稍好处，雪被踩平一块，雪里落着一根手机挂绳，系着刻“魏”字的小木牌。"}]},{"id":"cellar","name":"地下储藏间","scene":"cellar","desc":"地下储藏间堆着酒坛和旧工具，角落搭了几个又冷又潮的铺位。","clues":[{"id":"c_cel1","title":"偷拍笔记本","text":"笔记本上列着“拆穿山屿”清单，记着：“21:03大厅争吵 录音”“22:20二楼，女客在202门前停留约两分钟”。"},{"id":"c_cel2","title":"红色登山包","text":"酒坛旁有只褪色的红登山包，吊牌写着“苏岚”；旁边的空酒杯，酒渍未干。"},{"id":"c_cel3","title":"工具柜里的旧本子","text":"周守山的旧记事本：“10.17老板说别报警。10.18工钱涨五百。”此后每月一行“封口”。"}]},{"id":"study","name":"运营室","scene":"study","desc":"大厅旁的小房间，摆着显示器和灯具，一扇侧门通向后院。","clues":[{"id":"c_study1","title":"待签的情况说明","text":"《情况说明》：“本人贺杰，擅自冒用山屿名义收款十七万余元，责任自负。”签名处空白，页脚铅笔：“周一报警前让他签。——屿”"},{"id":"c_study2","title":"摄影包的分装瓶","text":"摄影包四个袋格，三格插着贴蓝线白标签的分装瓶，第四格空着。便条：“镜头里不出现花生。老板人设＝什么都敢吃。——杰”"},{"id":"c_study3","title":"账号后台与转账","text":"“山屿”私信后台：“鹿鸣”聊了一年多，每晚十点“晚安，不怕，慢慢来”；有笔十二万八转账。实名许敏，登录设备“贺杰”。"},{"id":"c_study4","title":"剪辑软件的日志","text":"剪辑日志：21:31保存后，到22:03无任何操作。鞋架上的灰色软底拖鞋，鞋底潮湿，沾着炭灰。"}]}],"suspects":[{"id":"lin","name":"林小鹿","role":"自由插画师","age":24,"look":{"skin":"fair","hair":"long","hairColor":"black","glasses":"none","beard":"none","outfit":"coat","acc":"scarf","mood":"sad"},"bio":"外省插画师，雪封山前一天入住203，自称来看雪。听说她昨晚在大厅和山屿大吵，之后回了房。","demeanor":"说话轻声，紧张就绞围巾，被逼急了会呛声。","topics":[{"id":"t_why","q":"你为什么来这里？","lie":true,"a":"就是来旅游的，看了他的视频，想来看雪。我跟他一点都不熟，你们别瞎猜，也你们别再问了。","truth":"我是来见他的。网上聊了一年多，每晚十点他说晚安。我转了十二万八，他说是我们小院的基金。"},{"id":"t_night","q":"昨晚九点你在哪？","lie":true,"a":"吃完饭就回房了，一步没出来过。睡前吃了两片安眠药，一觉睡到天亮，什么都没听见，真的。","truth":"九点我在大厅跟他大吵，九点一刻哭着跑回房。安眠药是真的，所以后面的事我真没听见。"},{"id":"t_feel","q":"你对山屿感觉？","a":"以前觉得他最懂我。昨晚见到真人，他看我像陌生人，连“鹿鸣”是谁都要想半天。那一刻我心都碎了。"},{"id":"t_gift","q":"牛轧糖是你的？","needs":["clue:c_kit3"],"a":"是我买的，他在视频里说过爱吃甜的。封条都没拆，你不会觉得我是想用糖毒他吧？我就想送个礼物。"},{"id":"t_threat","q":"说要他身败名裂？","needs":["clue:c_cel1"],"a":"说过，气话而已。我只想把聊天记录发上网让大家看看，从没想过动手，我连鸡都不敢杀。"},{"id":"t_chat","q":"你们聊了多久？","needs":["clue:c_study3"],"a":"一年零两个月，每晚的“晚安”我都截图存着。可他昨晚说，那些话是花钱请人写的。写字的人是谁？"},{"id":"t_he","q":"觉得贺杰怎样？","needs":["clue:c_study3"],"a":"运营小哥，话不多。我哭的时候他递纸巾，说“不怕，慢慢来”。那是每晚对我说的话……我不敢想。"}],"confronts":[{"clue":"c_cel1","breaks":"t_night","a":"她盯着“21:03大厅争吵”，嘴唇发白。“好，我承认吵了。可我没碰他一根手指，也没碰过他的东西！”"},{"clue":"c_study3","breaks":"t_why","a":"她看着屏幕上一行行“晚安”，手指发抖。“瞒不住了。我来，是想亲口对他说一声我愿意。”"},{"clue":"c_kit3","a":"“丝带是我系的。”她吸了吸鼻子，“他说放厨房，连拆都没拆。我连他吃什么都不知道。”"},{"clue":"c_room1","a":"她捂住嘴后退一步。“花生？我没进过厨房，也没进过他的房间！你们要查就随便查，我在这儿等着。”"},{"clue":"c_hall1","a":"她凑近看了很久，摇头。“看不出是谁，只看见腕带是绿的。我吵完架就上楼了，没在大厅。”"}],"fallback":"这个我不知道……我已经很难受了。"},{"id":"xing","name":"邢大海","role":"装修老板","age":47,"look":{"skin":"tan","hair":"short","hairColor":"black","glasses":"none","beard":"stubble","outfit":"jacket","acc":"pocketwatch","mood":"stern"},"bio":"装修老板，山屿欠他八十六万尾款。前天上山催款被大雪困住，住205，说昨晚早早睡了。","demeanor":"嗓门大，爱拍桌子，句句带“老子”。","topics":[{"id":"t_debt","q":"山屿欠你多少？","a":"八十六万，拖了八个月！周一前不结，老子就起诉。我干了二十年工程，还没被谁赖过账。"},{"id":"t_night","q":"昨晚你几点睡的？","lie":true,"a":"吃完饭就回205了，看了会儿手机，十点不到就睡。一觉到天亮，别往老子头上扣屎盆子。","truth":"我没睡。九点二十在后院火盆边堵他，吵了二十分钟，一火大推了他一把，他摔进雪里。九点四十我就上楼了。"},{"id":"t_knock","q":"去过202吗？","needs":["clue:c_room3"],"lie":true,"a":"没有。我的门一直关着，谁看见我去过了？你们有种就拿出证据来，别在这儿血口喷人，老子最烦被冤枉！","truth":"去过。十一点十分，我想再逼他一回，敲了几下门，还踹了一脚。没人应，我骂两句就走了。"},{"id":"t_hear","q":"敲门听见什么？","needs":["ask:xing.t_knock"],"a":"什么声音都没有，静得吓人。门缝透出灯光，就是没人说话。他那时候是不是已经……想起来我后背都发凉。"},{"id":"t_firm","q":"你的公司怎样？","lie":true,"a":"好得很！工程排到明年去了，八十六万在我这儿就是个零头，我追着要只是为了争口气，不是等米下锅。","truth":"早空了。银行贷款逾期，工钱欠着，高利贷追到家门口。这笔钱周一收不回来我就得跑路，我要他活着还钱。"},{"id":"t_motive","q":"他死对你有利？","needs":["clue:c_hall2"],"a":"放屁！我要的是钱，不是命！他死了，我这八十六万找谁要？找鬼要吗？我比谁都盼着他活着！"},{"id":"t_who","q":"你怀疑谁？","a":"那个闹得最凶的小姑娘。还有运营小贺，整天跟着老板转，我看他那眼神，像个憋着火的炮仗。"}],"confronts":[{"clue":"c_gar3","breaks":"t_night","a":"他盯着烟蒂和雪坑，咬了咬牙：“行，被你抓到了。我是推了一把，没下死手！他自己爬起来的。”"},{"clue":"c_room3","breaks":"t_knock","a":"邢大海脸涨成猪肝色：“那靴印是我踢的，我认。可我要是想杀他，用得着在门口大声嚷嚷吗！”"},{"clue":"c_hall2","breaks":"t_firm","a":"“催款函是我写的，光明正大！”他翻到后一页，脸黑了，“谁让你们翻这张的？我的账轮不到你们看！”"},{"clue":"c_gar1","a":"他蹲下拨了拨灰：“药？老子没往火盆里扔过。我走时就一堆炭，你查谁最后去的后院。”"},{"clue":"c_room1","a":"“花生？”他一愣，“老子昨晚吃的宫保鸡丁就有花生。他对这个过敏？这些年从没人说过。”"}],"fallback":"少来这套，老子没什么好说的。"},{"id":"wei","name":"魏敏","role":"管家兼厨师","age":51,"look":{"skin":"tan","hair":"bun","hairColor":"black","glasses":"none","beard":"none","outfit":"apron","acc":"necklace","mood":"tired"},"bio":"在民宿干了四年的管家兼厨师，山屿的饮食都归她管。今早敲不开202的门，是她叫的人。","demeanor":"说话快，爱碎碎念，紧张就拿围裙擦手。","topics":[{"id":"t_routine","q":"山屿睡前喝什么？","a":"一杯姜蜜茶，装保温杯，他自己下来取。三个月前有粉丝半夜翻墙，他从那以后睡前必插插销。"},{"id":"t_tea","q":"茶几点做的？","a":"九点三十五分做的，就姜、红枣、蜂蜜。放操作台，十点他自己来拿，已经穿着橙背心了。"},{"id":"t_stay","q":"离开过厨房吗？","lie":true,"a":"没有！我这个人手不离灶，哪儿也没去，一直在厨房收拾碗碟，不信你们问谁都行，我骗你们干什么！","truth":"我出去过。九点四十几分，儿子来电话，我怕被人听见，跑到后院东墙角讲了十来分钟。厨房那会儿没人。"},{"id":"t_allergy","q":"山屿有什么忌口？","lie":true,"a":"没什么忌口，他什么都吃，天南海北的东西都敢尝，这事粉丝都知道，视频里都拍着呢，不信你们去翻。","truth":"他花生过敏，很严重。他让我对谁都别说，传出去赞助商要掀桌。我答应了，所以不敢吭声。"},{"id":"t_jar","q":"蜂蜜罐谁碰过？","needs":["clue:c_kit1"],"a":"蜂蜜罐一直在我柜顶，盖子拧得紧。这种小分装瓶我们厨房从来不用，我这儿用的是玻璃罐，谁掺过我看得出。"},{"id":"t_pen","q":"他的药放在哪里？","needs":["clue:c_room2"],"a":"一支笔，在左口袋。昨晚他摔湿了背心，九点四十挂在大厅烘。他十点穿走时，我没再想。"},{"id":"t_seen","q":"你出去前见过谁？","needs":["ask:wei.t_stay"],"a":"九点四十一分，我看见贺杰在大厅伸懒腰，说剪片腰疼出来透气。我九点五十二回厨房，垃圾桶盖开着。"}],"confronts":[{"clue":"c_gar4","breaks":"t_stay","a":"魏姐在围裙上擦了又擦：“这挂绳是我的。我去接了个电话，怕你们觉得是我在茶里动了手脚。”"},{"clue":"c_kit2","breaks":"t_allergy","a":"她眼圈红了：“‘无任何坚果’是我提醒自己的。他花生过敏，要我烂在肚子里，现在人都没了，还守什么。”"},{"clue":"c_room2","a":"她一见卡片就哽住：“药一直揣在他左口袋。要是我早劝他别瞒着……”后面的话被抽泣吞掉。"},{"clue":"c_room1","a":"“杯里有花生？”她手一抖，“我只放了姜、红枣、蜂蜜！你们疑我疏忽，我没话说，可我没放别的。”"},{"clue":"c_kit1","a":"“这瓶子不是我们厨房的。”她脸色变了，“里头像早饭台上那罐花生酱。谁会这么干？”"},{"clue":"c_hall1","a":"她看了又看：“荧光绿腕带，拍摄时小贺戴一条，老周扫雪也有条。我不敢乱说是谁，对不起。”"}],"fallback":"这个我真不清楚，老板的事他很少跟我说。"},{"id":"he","name":"贺杰","role":"民宿运营","age":27,"look":{"skin":"light","hair":"sidepart","hairColor":"black","glasses":"rect","beard":"none","outfit":"hoodie","acc":"headset","mood":"tired"},"bio":"山屿的运营兼摄像，在民宿干了两年。说昨晚一直在一楼运营室剪片，今早第一个去通知魏姐。","demeanor":"语速慢，爱说“可能吧”，提到老板时嘴角会绷紧。","topics":[{"id":"t_boss","q":"山屿待你如何？","a":"还行吧……可能吧。他脾气大，工资拖了三个月，说等赞助到账再补。我房贷还欠着，走又走不了。"},{"id":"t_where","q":"九点半后在哪？","lie":true,"a":"一直在运营室剪片，九点半坐下去，剪到十一点多，没出过门。屋里就我一个，没人给我作证。","truth":"我出去过。九点四十走的，去了厨房、大厅，又从侧门去后院，十点前才回来导出视频。我不想让你们知道。"},{"id":"t_allergy","q":"你知道他过敏吗？","lie":true,"a":"过敏？没听说过。山屿的人设就是什么都敢吃，镜头前吃过辣、吃过虫子，哪来的过敏？你们别听外头瞎传。","truth":"我知道。花生，很严重。“镜头里不出现花生”是我定的红线。他随身带肾上腺素笔，放左口袋。"},{"id":"t_yard","q":"去过火盆吗？","lie":true,"a":"没去过。侧门我只用来抽烟。外头零下十几度，谁没事往火盆跑，邢老板倒是在那儿抽了一晚上。","truth":"去了。十点差几分，我从侧门出去，在火盆前把那支笔扔进炭里。拖鞋沾了灰，没来得及擦。"},{"id":"t_chat","q":"私信是你回的？","needs":["clue:c_study3"],"lie":true,"a":"账号是公司的，粉丝私信我有时代回几条，都是套话。哪个粉丝聊了多久，我真的记不清了。","truth":"“鹿鸣”的每一条都是我写的，一年多，每晚十点。山屿根本不看私信，只收钱。她在我心里早不是粉丝了。"},{"id":"t_vest","q":"碰过背心吗？","needs":["clue:c_hall1"],"lie":true,"a":"没有。老板的东西我从不乱碰，那件背心挂在衣帽架上烘着，我连那个角落都没走近过，真的。","truth":"是我。九点五十二，没人回头，我从他背心左口袋摸出笔，扔进火盆。茶里的花生酱也是我拌的。"},{"id":"t_doc","q":"情况说明？","needs":["clue:c_study1"],"lie":true,"a":"什么说明？没见过这东西。多半是老板自己打的，反正我没打算签，也轮不到我签，跟我没关系。","truth":"昨晚八点四十，他拍在我桌上：周一报警前签字，把十七万全算我头上，否则送我进派出所。"},{"id":"t_lin","q":"怎么看小鹿？","a":"很单纯的姑娘，被骗了。可她吵起来很狠，说要让他身败名裂，我觉得你们该多留意她，别被她那副可怜样骗了。"}],"confronts":[{"clue":"c_hall1","breaks":"t_vest","crack":true,"a":"他盯着那只手，左手下意识往袖口缩，绿色腕带露出一半。“拍摄用的，每人都发过。”再开口，声音哑了：“二十一点五十二……让我想想。”"},{"clue":"c_gar1","a":"“火盆里烧的是药？”他盯着变形的塑料，“山屿的东西……可能吧。可火盆谁都能去。”"},{"clue":"c_study4","breaks":"t_where","a":"他苦笑：“三十二分钟，什么都没动。还有这双鞋……你们把时间对得真细，我还以为没人会看剪辑日志。”"},{"clue":"c_gar2","breaks":"t_yard","a":"“软底拖鞋……”他把脚往后缩了缩，“好吧，我去过后院。可这民宿穿拖鞋的人多着呢。”"},{"clue":"c_study2","breaks":"t_allergy","a":"他沉默片刻：“便条是我写的，红线是我定的。我怎么会不知道他过敏。只是我不想说。”"},{"clue":"c_study1","breaks":"t_doc","a":"他脸色惨白：“你们翻我桌子？这是他逼我签的，我一个字都没签！我只是拿工资的，凭什么替他背十七万？”"},{"clue":"c_study3","breaks":"t_chat","a":"他伸手挡住屏幕，指节发白：“别念了。那些话是我写的，一个字一个字敲的。她不知道。”"},{"clue":"c_kit1","a":"“一个小瓶子而已。”他声音很平，握杯的手却在抖，“这种瓶子我有一堆，分装洗发水用的。”"},{"clue":"c_gar5","a":"“老周的东西。”他答得很快，“他扫雪天天戴，昨晚搞不好又戴了。你们别全盯着我。”"}],"fallback":"这个……我真不太清楚，你再问问别人？"},{"id":"su","name":"沈晴","role":"自由摄影师","age":36,"look":{"skin":"light","hair":"ponytail","hairColor":"black","glasses":"none","beard":"none","outfit":"coat","acc":"scarf","mood":"tired"},"bio":"登记为“沈晴”，自称第一次上山拍雪景。住201，和死者只隔一堵墙，说昨晚睡得很沉。","demeanor":"话少，目光很沉，回答前总要停顿一下。","topics":[{"id":"t_why","q":"你为什么上山？","lie":true,"a":"拍雪景。朋友推荐的这家民宿，我是第一次来，没想到会被大雪困在这儿，还碰上这种事。","truth":"我叫苏晴，“沈晴”是假名。三年前，我妹妹苏岚住进这家民宿后再没回来。我来，是想弄清她怎么没的。"},{"id":"t_night","q":"昨晚你听到什么？","lie":true,"a":"什么都没听见。我睡得很沉，这房子隔音又挺好，隔壁有没有动静，我是真的完全不知道。","truth":"我听见了。十点四十前后，隔壁有“咚、咚”的撞墙声。我恨他，没敲门。想到我可能听着一个人死，我整夜没合眼。"},{"id":"t_sister","q":"你妹妹的事？","needs":["clue:c_cel2"],"a":"那个包是岚岚的，吊牌是我给她写的。他把它藏在地窖里三年。我恨不得杀了他，可我没有。"},{"id":"t_name","q":"“沈晴”？","needs":["clue:c_hall3"],"a":"胶带下是我的真名。山屿这三年一直说不认识苏岚，我要报真名，他连门都不会让我进，我只能瞒着。"},{"id":"t_fire","q":"21:50在哪？","needs":["clue:c_hall1"],"a":"壁炉边，和那位许老师聊天，聊到快十点。那时我背对着衣帽架，什么也没看见，真后悔没多看一眼。"},{"id":"t_hate","q":"你恨他吗？","a":"恨。可恨一个人和杀一个人，中间隔得很远。我要的是真相，他死了，岚岚的事就更没人说得清了。"}],"confronts":[{"clue":"c_room3","breaks":"t_night","a":"她盯着墙根的磕痕，嘴唇动了动：“是我隔壁那面墙。我听见了，一整夜都听见。我不该装没听见。”"},{"clue":"c_hall3","breaks":"t_why","a":"“那个‘苏’字是我的。”她声音很平，“我早料到会被人看出来。我不是来害人的，我是来找人的。”"},{"clue":"c_cel2","a":"她的手指在吊牌上停了很久：“这是岚岚的字，是我给她写的。他居然留着，放了三年。”"},{"clue":"c_hall1","a":"她看了一遍，摇头：“画面里我们俩是背对镜头的，聊得很投入。那只手是谁的，我没法判断。”"}],"fallback":"我只想知道妹妹的下落，别的没兴趣。"},{"id":"xu","name":"许敏","role":"瑜伽教练","age":38,"look":{"skin":"fair","hair":"bun","hairColor":"brown","glasses":"round","beard":"none","outfit":"turtleneck","acc":"earrings","mood":"stern"},"bio":"登记为“许老师”，瑜伽教练，自称山屿的粉丝，来看看真人。住204，说昨晚十点就睡了。","demeanor":"冷静克制，说话像在教课，生气时语速变慢。","topics":[{"id":"t_know","q":"你认识山屿吗？","lie":true,"a":"不认识，我就是个粉丝，看了他两年视频，这回来看看真人。你们别拿这个做文章，没意思。","truth":"我是他前妻，离婚两年了。“山屿”这个号当年用我的身份证注册，现在一百二十万粉丝，收益我一分没拿到。"},{"id":"t_night","q":"昨晚你几点上楼？","lie":true,"a":"聊了会儿天，十点就回204睡了。后面没出过门，也没有听见任何的动静，你们别再问了。","truth":"不是。十点二十，我去敲202的门，想谈账号过户。里头有很哑的声音，说“别……烦我”。我以为他又喝多了，就回去了。"},{"id":"t_allergy","q":"你知道他过敏吗？","needs":["clue:c_study3"],"a":"知道。结婚时我给他备过两次药。他最恨别人提，一提就毁人设。那支笔他一直放左口袋。"},{"id":"t_acct","q":"账号怎么回事？","needs":["clue:c_study3"],"a":"实名认证是我，我是法定所有人，这次来就是要他签字转还。现在的文案，很多根本不是他写的。"},{"id":"t_fire","q":"21:50在哪？","needs":["clue:c_hall1"],"a":"壁炉边，和住201的那位聊天。有人在衣帽架那边晃了一下，我没回头，以为是找外套的。"},{"id":"t_div","q":"你们为何离婚？","a":"人设立住后，他要的是粉丝，不是老婆。我劝他别把假的当真，他说：“真的没人看。”那天我就知道没法过了。"}],"confronts":[{"clue":"c_cel1","breaks":"t_night","a":"“浅色睡袍，两分钟。”她盯着那行字苦笑：“被拍到了啊。对，是我。我真希望那时多敲几下。”"},{"clue":"c_study3","breaks":"t_know","a":"她看着“实名认证：许敏”，笑意没到眼底：“不演了。我是他前妻，账号一开始是我的名字。”"},{"clue":"c_room2","a":"她的指尖在“花生过敏”上停了一瞬：“这事粉丝圈里传过。那支笔，就是他一直带在身上的那种。”"},{"clue":"c_hall1","a":"“绿腕带……”她眯起眼，“我只顾说话，没看见。你们是说有人趁我们在壁炉边动手？”"}],"fallback":"这个跟我没关系，你问别人吧。"},{"id":"zhou","name":"周守山","role":"杂工兼向导","age":58,"look":{"skin":"brown","hair":"cap","hairColor":"grey","glasses":"none","beard":"stubble","outfit":"jacket","mood":"tired"},"bio":"山下村里人，在民宿做杂工兼向导十年，今早他撞开了202的门。说昨晚扫完雪就回柴房睡了。","demeanor":"寡言，乡音重，爱说“莫得事”，被追问就低头抽烟。","topics":[{"id":"t_night","q":"昨晚你在哪？","a":"扫完雪回柴房躺着，睡不着。十点过后去了趟地窖，那儿清静，坐了好一阵才回去。莫得别的事。"},{"id":"t_missing","q":"三年前苏岚的事？","lie":true,"a":"那个姑娘？听说是自己上山走丢的，我莫得印象，也不清楚。山里头每年都有人走丢的嘛，不稀奇。","truth":"山屿带她走封闭的老道，要直播日出。她在冰壳上滑了下去。老板说别报警，一报号就完了，给我涨了五百工钱。"},{"id":"t_vest","q":"见过背心吗？","a":"橙色那件，湿的，挂在大厅衣帽架上。十点前后他自己来拿，穿上去厨房取杯，然后上楼了。"},{"id":"t_side","q":"谁松的闩？","needs":["clue:c_gar2"],"lie":true,"a":"侧门？我莫动过。那门平时就闩着，是哪个松的我不晓得，你们莫问我，我哪管得了屋里的事。","truth":"是我松的。九点半前后，贺杰说晚上剪片要出去抽烟，让我松闩。我当他图方便，就松了。"},{"id":"t_hej","q":"了解贺杰吗？","needs":["ask:zhou.t_side"],"a":"那孩子命苦，工资还拖。他来让我松闩时，往兜里塞了个黑东西。他整天都穿那双软底拖鞋。"},{"id":"t_band","q":"戴过腕带吗？","needs":["clue:c_hall1"],"a":"扫雪才戴，一条挂柴房墙上，昨晚没戴。我穿胶靴、戴手套，大厅里那种细活，我干不来。"},{"id":"t_hate","q":"你恨山屿吗？","needs":["clue:c_cel3"],"a":"恨过。三年的封口费，我每月拿着，手都是抖的。可他死了，我也莫得高兴，只是……那姑娘还在山上。"}],"confronts":[{"clue":"c_cel2","breaks":"t_missing","a":"老周盯着吊牌，嘴唇抖了抖：“苏岚……你们真找到了。我昨晚就坐这儿，陪这姑娘坐了一阵。”"},{"clue":"c_hall3","breaks":"t_missing","a":"他看着被撕走的那一页：“那页是三年前老板亲手撕的，说不撕会有人顺藤摸瓜。我劝过，他不听。”"},{"clue":"c_cel3","a":"他把本子攥在手里，半晌才松开：“那是我的账。拿封口费的事，我一笔一笔记了三年。”"},{"clue":"c_gar2","breaks":"t_side","a":"他蹲下看脚印：“软底拖鞋，是屋里人穿的。不是我，我穿胶靴，一脚一个大坑。……闩是我松的。”"},{"clue":"c_gar5","a":"“这是我的反光带，扫雪戴的。”他看了看胶靴，“昨晚我莫戴它。你们先对对这靴印。”"}],"fallback":"我莫得啥说的，你问别个吧。"},{"id":"qiao","name":"乔木","role":"徒步学生","age":20,"look":{"skin":"light","hair":"messy","hairColor":"brown","glasses":"none","beard":"none","outfit":"hoodie","mood":"sly"},"bio":"外地大学生，自称徒步路过，被大雪逼进民宿，花八十块睡地下储藏间。说昨晚一觉到天亮。","demeanor":"语速快，爱抖机灵，被问急了就抓头发。","topics":[{"id":"t_why","q":"你为什么在这儿？","lie":true,"a":"徒步路过的，下午雪太大，魏姐好心让我睡地下室。就这么简单，大学生穷游，你们懂的。","truth":"我做“拆穿”类短视频。我怀疑山屿人设造假，专门上山偷拍，相机藏在大厅书架上，拍了他一整天。"},{"id":"t_night","q":"昨晚你听到什么？","a":"九点多大厅吵架，我在楼梯拐角偷听，还录了音。女的说“你不是他”，男的说“你充钱买的是故事”。"},{"id":"t_stairs","q":"上过二楼吗？","lie":true,"a":"没有，我一直在地下室，晚上只在一楼上了趟厕所。二楼我可不敢上，怕被赶出去，没地方睡了。","truth":"上去过。二十二点二十，我想拍素材，看见一个女客站在202门口，我缩回楼梯口，没敢拍。"},{"id":"t_cam","q":"相机拍到了什么？","needs":["clue:c_hall1"],"a":"我回看过，只拍到一只手，戴荧光绿腕带，运动手环那种。是谁的，我真看不出来。要认得出我早说了。"},{"id":"t_audio","q":"录音里还有什么？","needs":["ask:qiao.t_night"],"a":"山屿最后说：“那些话是我花钱请人写的，要找温柔的，去问写字的人。”那姑娘当场不说话了。"},{"id":"t_sleep","q":"你睡在哪儿？","needs":["clue:c_cel2"],"a":"酒坛后头，离那只红背包不到三米。老周昨晚十点多下来过，我装睡，他坐了很久，一直念“对不起”。"}],"confronts":[{"clue":"c_hall1","breaks":"t_why","a":"他挠头：“相机是我藏的，好吧我是偷拍党。我拍的是他的人设，没想到会拍到这种东西。”"},{"clue":"c_cel1","breaks":"t_stairs","a":"他叹气：“行行行，我上去过，笔记本都被你们翻了。可我就看了一眼，什么都没碰，真的。”"},{"clue":"c_room2","a":"他倒吸一口气：“左口袋，一支笔……我拍他三天，他总把手揣左口袋，原来是在护命。”"},{"clue":"c_gar1","a":"“你们连火盆都翻了？”他吹了声口哨又收住，“不好意思，我一紧张就爱打岔。那东西是被人故意烧的吧？”"}],"fallback":"这个你问我不如看我的素材，哈哈，开玩笑的。"}],"solution":{"culprit":"he","method":{"q":"房间从里面反锁，凶手是怎么杀人的？","options":["备餐时无意混入致敏食材，纯属意外，死者自己锁门后病发","先下安眠药，待其昏睡后进屋捂死，再从内插好门","此前冲突中被推搡撞伤，伤势后来才发作，他锁门后不治","在睡前饮品里混入致敏食物，并取走他随身的急救药"],"correct":3},"motive":{"q":"凶手为什么杀人？","options":["被逼签字替死者背诈骗罪名，还长期被欠薪","为失踪多年的亲人讨公道，认定死者隐瞒了真相","被拖欠的巨额款项拖垮，催讨无果后愤而报复","长年替死者隐瞒旧案，良心难安，想了断共谋"],"correct":0},"keyClues":["c_room1","c_room2","c_hall1","c_gar1","c_study1","c_study2"],"truth":["凶手是运营贺杰。山屿没被人闯进密室杀死，他自己锁门，喝下掺了花生酱的姜蜜茶，找不到救命药，窒息而死。","动机：山屿逼他周一报警前签《情况说明》，替自己背十七万诈骗的锅，还欠薪三个月。他也是冒充山屿与小鹿聊了一年的人。","21:44，趁魏敏出去接电话，他在厨房把花生酱拌进姜蜜茶。21:52，他从衣帽架湿背心里取走肾上腺素笔，扔进火盆烧了。","22:05山屿拿杯上楼，锁门喝茶，22:15发作，翻遍背心抽屉找不到药。22:20许敏听见嘶哑声，22:40苏晴听见撞墙声，都没进去；约22:50他死去。","破绽：相机拍到绿腕带的手取笔；火盆里有烧毁的药笔；软底拖鞋沾炭灰，不是穿胶靴的周守山；剪辑日志空白半小时；便条证明他知道过敏。"]}},{"id":"lighthouse","title":"孤塔","tagline":"台风夜，栈道被潮水吞没，守塔人的后代死在灯下。","difficulty":3,"cover":"cv_lighthouse","tone":"cold","brief":"鹭屿灯塔如今是纪念馆和民宿，只靠一条木栈道连着对岸。你受海事局特聘，随调查员甘仲谋上岛，复核十一年前渔船“海盛6号”触礁案。台风压境，栈道在九点十分被增水吞没，岛上与外界隔绝。夜里十一点四十，甘仲谋和讲解员梁小雨敲开你的房门：守塔人闻庭舟死在了灯室。岛上除你，还有八个活人。你披上雨衣，走向那座仍在转动的灯塔。","victim":{"name":"闻庭舟","desc":"五十一岁，第三代守塔人，纪念馆驻馆讲述人。他侧卧在灯室透镜脚下，头部遭黄铜摇柄重击，外廊门从里面插着销。","look":{"skin":"tan","hair":"short","hairColor":"grey","glasses":"none","beard":"stubble","outfit":"parka","mood":"tired"}},"relations":{"qi":"隔壁“鹭栖”民宿的老板，是邻居也是朋友","cui":"纪念馆馆长，和他共事十五年","ying":"海盛6号遇难者的父亲，当众骂过他","yu":"来岛拍塔的杂志摄影师，认识才三天","gan":"来复核旧案的调查员，说只通过邮件联系","tan":"推进灯塔开发的县干部，他是联署反对的人","liang":"纪念馆实习讲解员，他手把手教过她","jian":"民宿厨娘，管了他九年的三餐"},"links":[{"a":"qi","b":"jian","text":"民宿老板与厨娘，同在鹭栖共事多年"},{"a":"cui","b":"liang","text":"馆长与她带的实习讲解员"},{"a":"tan","b":"cui","text":"谭要改造纪念馆，崔不让碰档案"},{"a":"gan","b":"ying","text":"甘复查的海盛6号案，死者里有应的儿子"}],"deathReport":{"time":"约 21:00–22:30","cause":"头部遭钝器重击，颅骨凹陷","scene":"23:40，甘仲谋与梁小雨上塔，在灯室发现他侧卧在透镜脚下，外廊玻璃门从里面插着销。","loc":"lamp","notes":["右耳上方一处凹陷，一击致命","伤口周围的血已发暗发干","黄铜摇柄落在尸体旁，沾着血和灰发"]},"publicFacts":["闻庭舟，51岁，十一年来每晚十点整用遮光帘打三下“平安灯”，只有他自己动手。","他死在灯室，头部遭黄铜摇柄重击，外廊门从里面插着销。","21:10栈道被增水淹没，此后无人上岛离岛，岛上连死者共十人。","今晚的平安灯比平时早，多人看见；此后再没人见过闻庭舟。","塔底连廊的钥匙，在馆长、死者、梁小雨和戚大年手里。","22:40全岛停电，22:47发电机手动合闸后恢复。"],"timeline":[{"t":"19:00","text":"闻庭舟点灯。"},{"t":"20:05","text":"应海根席上当众骂闻庭舟“你欠我儿子一条命”。"},{"t":"20:55","text":"简桂香送姜汤上灯室，闻庭舟人好好的。"},{"t":"21:10","text":"栈道被淹，岛上封闭。"},{"t":"21:52","text":"遮光帘打出“平安灯”，比往常早。"},{"t":"22:40","text":"全岛停电，22:47合闸恢复。"},{"t":"23:40","text":"甘仲谋和梁小雨上灯室，发现尸体。"}],"budget":{"search":12,"ask":28},"locations":[{"id":"lamp","name":"灯室","scene":"hall","desc":"塔顶的灯室，玻璃外是被风撕碎的雨。菲涅尔透镜缓缓转动，写字台和暖炉挤在透镜脚下。","clues":[{"id":"c_lamp1","title":"透镜脚下的死者","text":"闻庭舟侧卧在透镜脚下，右耳上方凹陷，血已发暗发干。黄铜摇柄落在旁边，沾着血和灰发。外廊玻璃门从里面插着销。"},{"id":"c_lamp2","title":"遮光帘拉绳","text":"遮光帘拉绳的铁钩空着，绳头用渔夫结接了一根绿色编织线，松垂着穿过地板圆孔，落进配重井。"},{"id":"c_lamp3","title":"写字台上的日志","text":"日志停在“21:00 灯正常”。台历:“20:15 甘”“20:35 谭”“21:20 他上来”。抽屉有止痛片和复诊单。"},{"id":"c_lamp4","title":"暖炉里的纸灰","text":"暖炉里是新烧的纸灰，残片写着“说我睡着了，那是假的”“真正离开岗位的人，我今晚当面”。炉前有几枚小巧的湿鞋印。"},{"id":"c_lamp5","title":"死者的手机","text":"手机记录：回甘“八点一刻，灯室”；20:52呼出“老戚”；21:12发甘“明早七点当面给你，今晚我要先跟一个人说”。"}]},{"id":"well","name":"塔底潮井","scene":"cellar","desc":"塔底最潮的角落。一口通外海的潮井，旁边是直通塔顶的配重井，墙上刷满潮位刻度。","clues":[{"id":"c_well1","title":"潮井里的跷板","text":"潮井口架着木条做的跷板，一端绑“鹭栖07”橙色浮球，一端系绿线绕过滑轮，通进配重井。井壁刻度4.6处有水痕。"},{"id":"c_well2","title":"配重井底的滑轮","text":"井底横梁上用两颗崭新的螺丝拧着滑轮，绿线从上绕过。地上有段剪断的线，每隔一米缠着白胶布。铁梯底阶沾着胶靴泥印。"},{"id":"c_well3","title":"连廊门内的印子","text":"连廊门内有两组脚印：约44码的胶靴印，边缘已干；小号女鞋印，湿亮清晰，部分踩在胶靴印上。"}]},{"id":"arch","name":"纪念馆与馆长室","scene":"library","desc":"塔底一层外的纪念馆展厅，尽头是虚掩的馆长室，档案柜钥匙就挂在锁孔上。","clues":[{"id":"c_arch1","title":"十一年前巡检单","text":"“崔 存 勿动”纸袋里的单子：“22:05 离岗（家属急病） 未交接 戚大年”。备注：“闻高烧，医务室21:40”。"},{"id":"c_arch2","title":"暖气片上的湿鞋","text":"暖气片上晾着一双湿的女式平底鞋，鞋底嵌着白灰。门后的雨披滴着水，袖口沾着黑灰。"},{"id":"c_arch3","title":"“三代守塔人”展板","text":"展板写着：2013年台风夜灯灭九十分钟，闻庭舟徒手摇亮灯光，评为模范；渔船海盛6号触礁，四人遇难。"},{"id":"c_arch4","title":"帮扶登记本","text":"登记本上，“闻庭舟（个人）→应海根 渔具补助1500元”，每月一行，记了十一年。回单附言：“别告诉他。”"}]},{"id":"lounge","name":"民宿大堂","scene":"dining","desc":"“鹭栖”民宿的大堂兼餐厅，靠窗有张牌桌，柜台后藏着一台小监控主机。","clues":[{"id":"c_lob1","title":"牌桌上的记分纸","text":"记分纸抬头是甘、谭、梁、简。“简”被划掉，改成“戚”，旁注“21:38 开”。最后一行是“停电 22:40”。"},{"id":"c_lob2","title":"监控主机日志","text":"日志：21:09:40 admin 停止录像，21:37:12 手动开始。22:04有撑伞女子入连廊，22:21返回。"},{"id":"c_lob3","title":"大堂黑板上的潮汐","text":"黑板上：高潮23:42，潮高4.9米。红笔写“增水+0.8米，21:10封路。戚”。旁边画着六根水位桩。"},{"id":"c_lob4","title":"柜台下的红桶","text":"柜台下塞着红塑料桶，桶沿缠白胶布，桶底有泥水和斜剪的绿线头。椅背搭着湿毛巾。"}]},{"id":"gate","name":"栈道口与外廊","scene":"deck","desc":"岛这一端的铁闸、水位桩和北侧环塔的外廊。栈道已没入黑水，只剩六根桩顶露出来。","clues":[{"id":"c_gate1","title":"外廊上的相机","text":"相机视频：21:52:03到21:52:44，灯室光束被遮八次，长短不一。22:12起窗口有橘光和缩肩人影。"},{"id":"c_gate2","title":"六号桩旁的粉笔","text":"礁石上有泡软的烟头，正对水位桩。桩脚粉笔：3号21:08（4.0）、5号21:31（4.3）、6号21:52（4.6）。"},{"id":"c_gate3","title":"上了锁的铁闸","text":"铁闸挂着民宿的黄铜锁，牌子用绿色扎带绑着，尾巴没剪。闸内水泥地有一串水脚印通向连廊。"}]},{"id":"store","name":"杂物间与办公角","scene":"engine","desc":"民宿后院的杂物间，一半是发电机房，一半隔成老板的办公角，满墙钓竿和浮标。","clues":[{"id":"c_sto1","title":"蓝色钓具箱","text":"盖内贴着“戚”的钓具箱里，黑蓝橙线轮都是满的，绿色编织线轮只剩半截，线端斜剪。胶布剩小半卷。"},{"id":"c_sto2","title":"浮球挂架","text":"挂架上挂着01到08号蟹笼浮球，07号的挂钩空着，那一格的灰比别处薄。"},{"id":"c_sto3","title":"抽屉里的缴费单","text":"抽屉里有产科缴费单：十一年前9月17日22:41入院，缴费人戚大年。旁有字条：“庭舟，这条命我欠你。”"}]}],"suspects":[{"id":"qi","name":"戚大年","role":"“鹭栖”民宿老板","age":46,"look":{"skin":"tan","hair":"short","hairColor":"black","glasses":"none","beard":"stubble","outfit":"jacket","mood":"smile"},"bio":"让人安心的“鹭栖”民宿老板。他说锁了栈道闸就回大堂打牌，停电后还陪甘调查员修了发电机。","demeanor":"热络爱笑，口头禅“放心”，被问紧了先递烟。","topics":[{"id":"t_role","q":"和这座塔的关系？","a":"我十年前盘下附楼开民宿，只管吃住和发电机。老闻是邻居，也是朋友。放心，你尽管问。"},{"id":"t_where","q":"九点以后在哪？","lie":true,"a":"锁了闸我就回大堂，九点二十不到就上了牌桌，打到停电。梁小雨、老谭、甘调查员都能作证，放心。","truth":"闸是九点零五锁的，我没直接回大堂，快九点四十才上牌桌。中间办什么事，我现在不想说。"},{"id":"t_tower","q":"你上过塔吗？","lie":true,"a":"没有。连廊那扇门我晚饭后就没碰过。一百多级台阶，我这条腿，没事谁爬？台风天我忙客人都来不及。","truth":"上去过。他九点多叫我上去，在灯室说了几句，话不投机我就下来了。别的，等你拿出东西再说。"},{"id":"t_dvr","q":"监控谁停的？","needs":["clue:c_lob2"],"lie":true,"a":"那破东西打雷就抽风，隔三差五断一回，我今晚压根没碰它。小民宿的摄像头，吓唬人的。","truth":"是我手动停的，九点零九分。我不想被人拍到进连廊。这事不光彩，可我只是怕人说闲话。"},{"id":"t_line","q":"你用什么钓线？","needs":["clue:c_lamp2"],"lie":true,"a":"我用黑的蓝的，都是尼龙。绿色编织线贵还挂水，我从来不用。谁都买得到，别往我身上套。","truth":"是我的线。箱子里那半截绿线是我剪的，四十来米。……我不想再往下说了，让我喘口气，行不行。"},{"id":"t_2013","q":"十一年前那夜？","lie":true,"a":"那年我在县里电器行打工，那夜在家守着老婆生孩子。灯塔的事，都是后来听说的。老闻是好人。","truth":"我是灯塔外包电工。老婆难产，我扔下配电柜就跑，没交接。灯灭了九十分钟，他替我背了十一年的锅。"},{"id":"t_call","q":"他找过你吗？","needs":["clue:c_lamp5"],"a":"他九点前打来电话，说九点二十灯室见，最后一次。我回他台风夜走不开，明天吧，就挂了。"},{"id":"t_cui","q":"怎么看馆长？","needs":["ask:cui.t_found"],"a":"崔馆长要强了一辈子。她十点过上塔，烧了东西，还说没出过办公室。这事你得去问问她。"}],"confronts":[{"clue":"c_lob1","breaks":"t_where","a":"他盯着“21:38 开”，笑意松了：“进去晚了几分钟，谁还掐着表过日子。有问题吗？”"},{"clue":"c_lob2","breaks":"t_dvr","a":"他手指在柜台上敲了两下：“admin是我。……行，那个键是我按的，我不想被拍到。”"},{"clue":"c_sto1","breaks":"t_line","crack":true,"a":"他看着只剩半截的线轮，没递烟，也没笑。“那是我的箱子。我的线，我剪的。你问吧。”"},{"clue":"c_well1","breaks":"t_tower","a":"“这是我民宿的浮球。”他像是自己都不信，“……可你问我上没上过塔，行，我上去过。”"},{"clue":"c_arch1","breaks":"t_2013","a":"他读到“戚大年”三个字，像被烫了一下：“她还留着……十一年，她还留着。好，那一夜是我。”"},{"clue":"c_gate1","a":"他盯着乱闪的灯光看了半分钟：“浪拍塔，帘子跟着抖，不稀奇。”他说得很稳，手却把烟盒捏瘪了。"}],"fallback":"这个嘛……放心，我没碰过，真不清楚。"},{"id":"cui","name":"崔慈安","role":"纪念馆馆长","age":58,"look":{"skin":"fair","hair":"bun","hairColor":"grey","glasses":"round","beard":"none","outfit":"coat","acc":"scarf","mood":"stern"},"bio":"纪念馆馆长，退休语文老师，十五年来经营这座塔。她说晚饭后一直在办公室核对材料，没出过馆。","demeanor":"书面语，语速平稳，被戳到就推眼镜、抬高声调。","topics":[{"id":"t_role","q":"塔对你意味着什么？","a":"十五年，我带志愿者把它从废铁里收拾出来。“孤塔”二字，是我一页页写进县志的。我只想让它立在那里。"},{"id":"t_night","q":"九点半后在哪？","lie":true,"a":"在办公室核对接待材料，又在沙发上眯了一会儿。我没出过馆，更没上过塔。这话我对谁都是这样讲。","truth":"我上过塔。十点过八分，他已倒在透镜脚下，手是凉的，血也干了。我吓坏了，什么也没说就下来了。"},{"id":"t_burn","q":"炉子里烧了什么？","needs":["clue:c_lamp4"],"lie":true,"a":"那是老闻自己的废稿吧，他爱写爱烧。别把一个人的习惯，写成另一个人的罪名，这不公平。","truth":"是我烧的。三页信稿写着十一年前他对调查组撒了谎。我不能让“模范”二字，毁在今晚。"},{"id":"t_sheet","q":"当年有原始单据吗？","lie":true,"a":"没有。认定和报告都在县档案馆，我这里只有复印件。老闻亲自问过我，我也是这么说的。","truth":"有。那张巡检单我十一年前就拿到了，一对医务室记录，就知道离岗的不是他。我锁起来，是不想塔塌。"},{"id":"t_afternoon","q":"下午他找过你？","needs":["ask:cui.t_sheet"],"a":"他下午来要那份单据，我说没有。他说：“崔姐，你骗不了我，但我不逼你。”然后走了。"},{"id":"t_found","q":"你上去看到什么？","needs":["clue:c_lamp4","clue:c_arch2"],"a":"十点过八分，他趴在透镜脚下，血发暗，手是凉的。可平安灯，我在窗口明明看见它闪过，我还以为自己疯了。"}],"confronts":[{"clue":"c_arch2","breaks":"t_night","a":"她看了很久那双鞋，推推眼镜：“湿鞋才要晾在暖气上。……我没想好怎么说。我上去过。”"},{"clue":"c_lamp4","breaks":"t_burn","a":"她看着残片上的墨迹，肩膀塌了一下：“他写得很干净，像他那个人。……是我烧的，我对不起他。”"},{"clue":"c_arch1","breaks":"t_sheet","a":"她看着自己的抽屉，没有争辩：“我留了十一年，也不敢拿出来十一年。你们读到它，就知道展板上有多少字是空的。”"},{"clue":"c_arch3","a":"她站在展板前，背挺得很直：“每个字都是我写的。我知道哪个字是空的，所以天天来擦玻璃。”"}],"fallback":"这与馆里的事无关，请别扰乱我的思路。"},{"id":"ying","name":"应海根","role":"讨海渔民","age":63,"look":{"skin":"brown","hair":"cap","hairColor":"white","glasses":"none","beard":"stubble","outfit":"parka","mood":"sad"},"bio":"对岸老渔民，送蟹上岛被涨潮困住。十一年前儿子死于海盛6号。他说自己晚饭后一直在大堂喝酒。","demeanor":"嗓门粗，爱叫“后生仔”，说到儿子就低头。","topics":[{"id":"t_role","q":"你怎么在岛上？","a":"送蟹，老闻订的。我七点多靠的栈道，当时想放下就走，哪晓得潮来这么快，被封在这里。"},{"id":"t_son","q":"和闻家的过节？","a":"十一年前，我儿子应小满死在海盛6号上，才二十二岁。今晚我当面骂了他，骂得对，你要抓我就抓。"},{"id":"t_where","q":"九点以后在哪？","lie":true,"a":"我在大堂喝酒，从晚饭喝到停电，老戚他们都在。我坐窗边那桌，没挪过。喝多了，你别笑话。","truth":"我没在大堂。九点四十我溜出去，坐在栈道口礁石上淋雨，想看一眼他那盏平安灯。十一年，我每晚都等那三下。"},{"id":"t_money","q":"收过闻家的钱吗？","lie":true,"a":"一分没收！他想拿钱买我闭嘴，没门。我儿子的命，不是钱能换的。一条人命，他拿什么还？","truth":"收了，每月一千五，十一年。我老婆病着，船贷压着，就当他欠的。今天才知是他自己掏腰包。"},{"id":"t_signal","q":"平安灯看见了吗？","needs":["clue:c_gate2"],"a":"九点五十二，我看着表，水刚舔到桩6的四点六。往日十点整三下，稳。今晚早了八分钟，还乱。"},{"id":"t_seen","q":"你看见别人了吗？","a":"九点零三分我在闸口，见老戚锁闸，还帮他扯了链条。九点四十出去时，大堂牌桌那边有人影，谁在没细看。"}],"confronts":[{"clue":"c_gate2","breaks":"t_where","a":"他看着泡软的烟头，在裤腿上擦手：“……是我的。我没喝酒，我在那块石头上坐着，淋着，等灯。”"},{"clue":"c_arch4","breaks":"t_money","a":"他看着“渔具补助”，嘴唇动了好几下：““那个‘别告诉他’，是说我？……我拿了十一年。他为什么不骂我。”"},{"clue":"c_gate1","a":"他盯着乱闪的光：“我在礁上看到的就是这个。真是老闻的手，三下就是三下，不会这样抖。”"},{"clue":"c_well3","a":"他抬脚给你看鞋底：“我穿四十一的。岛上四十四码的，我只见过一个。我没钥匙，进不了那扇门。”"}],"fallback":"这玩意儿我看不懂，后生仔，问点我懂的。"},{"id":"yu","name":"郁清和","role":"自由摄影师","age":34,"look":{"skin":"light","hair":"bob","hairColor":"black","glasses":"none","beard":"none","outfit":"jacket","acc":"scarf","mood":"tired"},"bio":"来拍“孤塔”的杂志摄影师，在民宿住了三天。她说晚饭后一直在房间修图，停电才下楼。","demeanor":"话少，句子短，爱用摄影词，被问烦了就看窗外。","topics":[{"id":"t_role","q":"你来拍什么？","a":"杂志稿，主题“孤塔”。三天了，拍灯室、栈道、潮。我话少，做事快，别指望我讲故事，故事在片子里。"},{"id":"t_where","q":"九点以后在哪？","lie":true,"a":"在房间修图，修到停电才下楼。外面那种雨，谁会出门拍片，脑子有毛病。我稿子明天就要交。","truth":"我出去了。用梁小雨借的钥匙开北外廊门，架机位拍十点的平安灯。馆长禁止夜上外廊，我违规了。"},{"id":"t_light","q":"平安灯怎么打？","a":"我跟拍了三晚。准十点，三下，每下约两秒，间隔稳得像节拍器。老头老头说他是数着心跳打的。"},{"id":"t_clip","q":"你拍到了什么？","needs":["clue:c_gate1"],"a":"九点四十四开机。九点五十二提前了八分钟，灯被遮了八下，乱七八糟。十点过，窗口有橘光和人影。"},{"id":"t_cam","q":"相机时间准吗？","a":"下午三点跟手机校过时，错不了一秒。你不信就拿手机来对，我的帧都带时间戳，你可以验。"},{"id":"t_key","q":"钥匙哪来的？","needs":["ask:yu.t_where"],"a":"梁小雨借我的备用钥匙，说好天亮前还她。是我磨她的，她心软。你别为难她，要罚就罚我。"}],"confronts":[{"clue":"c_gate1","breaks":"t_where","a":"她盯着自己的相机叹气：“你看了存储卡。对，是我。三脚架是我架的，被馆长知道，我这单就黄了。”"},{"clue":"c_lamp4","a":"“炉子……十点过十分，我从镜头里看到窗口有橘色晃动，以为是暖炉烧旺了，没当回事。”"},{"clue":"c_lamp1","a":"她脸色白了一下，转头看窗外：“别让我看这个。我拍过太多东西，这一张，我真的不想存。”"}],"fallback":"这不在我的画面里，没法说。"},{"id":"gan","name":"甘仲谋","role":"海事局调查员","age":44,"look":{"skin":"light","hair":"sidepart","hairColor":"black","glasses":"rect","beard":"none","outfit":"shirt","acc":"badge","mood":"stern"},"bio":"海事局事故调查员，来复核十一年前的海盛6号案。他说与闻庭舟只有邮件往来，没见过面。","demeanor":"公文腔，条理分明，爱说“按程序”，问到私事会停一拍。","topics":[{"id":"t_role","q":"为什么来鹭屿？","a":"海事局复核海盛6号案，当年认定与气象、电力记录有几处对不上。按程序，只做初步询问。"},{"id":"t_contact","q":"你接触过闻吗？","lie":true,"a":"此前只有邮件往来，今天也没见到面。按程序，我要等明天才对他正式询问，不会提前接触当事人。","truth":"八点一刻到八点半，我在灯室见过他。程序上不该提前接触，我隐瞒了。他说明早七点交原件，今晚要先通知一个人。"},{"id":"t_wait","q":"后来你做了什么？","a":"回大堂打牌。九点四十一、十点零五、十点三十一我发消息都没回，拖到十一点多才找小梁拿钥匙。"},{"id":"t_gen","q":"停电时你在做什么？","a":"十点四十停电，戚老板说要手动合闸，我举手电跟他去后院。四十七分来电，他一直在我眼前。"},{"id":"t_cards","q":"牌局怎么开的？","needs":["clue:c_lob1"],"a":"九点三十八开的牌。先是我、谭处长、小梁，简阿姨顶了一局，戚老板一进来，她就下去了。"},{"id":"t_2013","q":"你查到了什么？","needs":["clue:c_arch3"],"a":"供电公司记录显示2号开关是人为跳闸未复位，不是电缆故障。有人替一次失误做了掩护。"}],"confronts":[{"clue":"c_lamp5","breaks":"t_contact","a":"他看着“八点一刻，灯室”，眨了下眼：“……是我违反了程序。请把它和案子分开写。”"},{"clue":"c_lamp3","a":"“台历上有我的名字。”他语气没变，“他说要先通知一个人，我没追问，现在很后悔。”"},{"clue":"c_arch1","a":"他把底联看了三遍：“这就是我要找的东西。放在抽屉里十一年。‘戚大年’……他现在就在楼下打牌。”"},{"clue":"c_well1","a":"他蹲下去看浮球和跷板：“这不是展品，是有人搭的。绿线、滑轮……一直通到楼上吗？”"}],"fallback":"按程序，这个和本案无直接关联，暂不记录。"},{"id":"tan","name":"谭立成","role":"县文旅办干部","age":38,"look":{"skin":"light","hair":"slick","hairColor":"black","glasses":"none","beard":"none","outfit":"suit","acc":"tie","mood":"sly"},"bio":"县文旅办干部，来岛上推进灯塔开发方案。他说晚饭后在房间处理邮件，九点半前后才下楼打牌。","demeanor":"官话套话，爱说“原则上”“盘活”，被追问就看手机。","topics":[{"id":"t_role","q":"你来岛上做什么？","a":"原则上是前期调研。灯塔、栈道、潮汐，都是可以盘活的资源。我下午三点半到的，住二楼。"},{"id":"t_plan","q":"开发方案是什么？","a":"保护性开发：附楼拆除重建，塔身交给运营方，纪念馆只留一间展室。闻老师联署反对，意见比较大。"},{"id":"t_met","q":"单独见过闻庭舟吗？","lie":true,"a":"晚饭后没有。我在房间处理邮件，九点半才下楼。谈了几回都没结果，我也不想再自讨没趣。","truth":"二十点三十五分我上过灯室，开价六十八万，请他撤回联署。他只说“数字再大也不卖”。我怕被当成有动机。"},{"id":"t_money","q":"六十八万是什么钱？","needs":["ask:tan.t_met"],"a":"咨询费，合法合规，写在合同里。他的联署一撤，评估才能过，对整个岛都有好处，你们想多了。"},{"id":"t_cards","q":"牌局怎么记的？","a":"九点三十八开的牌，我、甘调查员、小梁，简阿姨顶了一局。戚老板九点四十出头才进来，之后我一直在桌上。"},{"id":"t_who","q":"你怀疑谁？","a":"原则上谁都不怀疑。但应海根扬言要算账，崔馆长又不让我碰档案，这两位的情绪，你们可以重点关注。"}],"confronts":[{"clue":"c_lamp3","breaks":"t_met","a":"他在“20:35 谭”上停了停，笑了一下：“被他记下来了。好，我去过，价钱说得很客气。”"},{"clue":"c_lob1","a":"他看着记分纸：“牌是九点三十八开的，那时戚老板还没进来。有问题吗？我只是个打牌的。”"},{"clue":"c_arch3","a":"“展板很有传播力。”他语气淡淡的，“可惜传播力和安全评估，是两回事。”他看了看展板。"}],"fallback":"原则上，这个我不便发表意见。"},{"id":"liang","name":"梁小雨","role":"实习讲解员","age":22,"look":{"skin":"fair","hair":"ponytail","hairColor":"brown","glasses":"none","beard":"none","outfit":"hoodie","mood":"worried"},"bio":"纪念馆实习讲解员，大四学生，住员工宿舍。她说备用钥匙没借过人，晚上一直陪客人打牌。","demeanor":"年轻，语气软，爱说“那个……”，一紧张就道歉。","topics":[{"id":"t_role","q":"你在馆里做什么？","a":"那个……我是实习讲解员，天天讲“三代守塔人”。闻老师人很好，还手把手教我怎么摇透镜。"},{"id":"t_key","q":"钥匙借过人吗？","lie":true,"a":"没有没有，备用钥匙一直在我这儿，我绝对没借过人……啊，可能放抽屉里了，反正没借过。","truth":"借了。借给郁老师，她想拍十点的平安灯，说好天亮前还。我违规了，求你别告诉馆长，我会被开除的。"},{"id":"t_cards","q":"牌局怎么看？","a":"我、老谭、甘调查员开的，三缺一，桂香阿姨顶了一局。戚哥进来时外套滴着水，我递了块毛巾。"},{"id":"t_signal","q":"你喊了什么？","a":"我喊“平安灯，今天好早”，因为每天都是十点整。我看了墙上的钟，肯定是九点五十二。"},{"id":"t_dish","q":"九点多在忙什么？","a":"在厨房帮桂香阿姨收碗，洗到九点半过。然后阿姨说三缺一，把我拉去打牌，我真的就是凑数的。"},{"id":"t_old","q":"闻老师最近怎样？","a":"他瘦了很多，上楼喘得厉害，说是烟抽多了。还让我把展板照片擦亮点，现在想起来，像在交代后事。"}],"confronts":[{"clue":"c_gate1","breaks":"t_key","a":"她看着外廊的相机，眼眶红了：“是郁老师的。对不起，我借了钥匙给她，想帮她拍到平安灯。”"},{"clue":"c_lob1","a":"“这是我记的。”她指着字迹，“戚哥来之前是桂香阿姨在打，时间是我看着墙上的钟写的。”"},{"clue":"c_lamp1","a":"她刚听到描述就别过脸，指尖发白：“别、别说了……我现在一闭眼，就是灯室那扇门。”"}],"fallback":"那个……这个我不太懂，对不起。"},{"id":"jian","name":"简桂香","role":"民宿厨娘","age":57,"look":{"skin":"tan","hair":"bun","hairColor":"grey","glasses":"none","beard":"none","outfit":"apron","mood":"worried"},"bio":"“鹭栖”民宿厨娘，九年来管闻庭舟的三餐。她说闻老师身体好得很，晚上只给他送过一碗姜汤。","demeanor":"碎碎念，爱说“哎哟”“作孽”，心虚时擦围裙。","topics":[{"id":"t_role","q":"你在岛上做什么？","a":"做饭呀，九年了，客人的饭、闻老师的饭都归我，一天开火五回。哎哟，今晚风大，灶上的火直打晃。"},{"id":"t_ill","q":"闻老师身体怎样？","lie":true,"a":"好得很呐，一顿两碗饭，爬一百多级楼梯比年轻人还快。哎哟，谁想到会出这种事，作孽。","truth":"他病了，肺上的，晚期。他不让我说，怕塔没人要。今晚送汤他咳得直不起腰，我答应替他保密。"},{"id":"t_soup","q":"几点送的汤？","a":"二十点五十五，他在对讲机里喊要姜汤。他一直咳，桌上有药。还说：“桂香，明天起别给我做饭了。”"},{"id":"t_cards","q":"你打过牌吗？","a":"顶了一局，九点三十八开的，是小梁硬拉我的。戚老板一来，我就回厨房了，汤还炖着呢。"},{"id":"t_saw","q":"你看见过什么？","needs":["clue:c_lob2"],"a":"九点十分刚过，我在厨房窗口，看见老板拎着红桶从前台往连廊走。那桶沉得很，他拎得吃力。"},{"id":"t_boss","q":"戚老板是什么人？","a":"戚家小子，我看着他结的婚。热心肠。他孩子就是台风夜生的，他有时半夜站在塔底下抽烟。"}],"confronts":[{"clue":"c_lob4","a":"她盯着那只红桶，手在围裙上蹭了好几下：“就是这只。哎哟，九点十分我在窗口看见的，我还当他去收钓具。”"},{"clue":"c_lamp3","breaks":"t_ill","a":"她看着止痛片和复诊单，手在围裙上擦了又擦：“……被你们翻出来了。是真的。他不让我说，我就一直没说。”"},{"clue":"c_lamp1","a":"她捂着嘴，眼泪直往下掉：“作孽。他明明答应我，明天起不用做饭了，我还没来得及问为什么。”"}],"fallback":"哎哟，这个我不懂，我就是个做饭的。"}],"solution":{"culprit":"qi","method":{"q":"凶手如何让全岛相信死者九点五十二还活着？","options":["行凶后篡改日志台历，把死亡时间往后推。","趁停电摸黑上塔行凶，再混进抢修中取得人证。","用钓线把拉绳连到塔底，让涨潮替死者打灯。","等灯打完才上塔行凶，事后烧掉信稿灭证。"],"correct":2},"motive":{"q":"凶手为什么杀人？","options":["死者拒收一笔钱，开发搁浅，凶手指望落空。","凶手当年擅离岗位，死者替他顶罪，如今要揭开。","死者要推翻旧模范故事，凶手为护名声灭口。","凶手亲人死于海难，认定死者造假，要报仇。"],"correct":1},"keyClues":["c_lamp2","c_well1","c_lob2","c_sto1","c_arch1","c_gate1"],"truth":["凶手是民宿老板戚大年。平安灯九点五十二还亮过，看似崔慈安最可疑，但那三下灯，根本不是活人打的。","十一年前台风夜，戚大年扔下配电柜去陪难产的妻子，灯灭九十分钟，海盛6号触礁。闻庭舟替他背了罪，如今病重，要在死前说破。","九点多，他停了监控，拎着钓具红桶进塔，在灯室谈崩后用摇柄杀人。再用绿线连起拉绳、配重井滑轮和潮井里的浮球跷板。","涨潮替死人打灯：水位升到井壁4.6米，浮球托起跷板，线拽落遮光帘。水来得比他算的早，九点五十二分灯被遮八次，乱了节奏。","他21:38才回牌桌，空档无人能证；监控日志、记分纸、半截绿线、07号浮球钉死了他。崔慈安只是烧信的发现者，其余人的谎都与命案无关。"]}},{"id":"museum","title":"展柜","tagline":"开幕前夜，镇馆之宝的守护人死在恒温恒湿的修复室里，每一道门都说他是一个人。","difficulty":3,"cover":"cv_museum","tone":"cold","brief":"十月，雨下了一整天。博物馆新展《吴越遗珍》明早九点剪彩。22:40，馆长屠启贤悄悄带你进了二楼修复室：首席修复师辛怀远倒在他守了二十五年的工作台边，后脑塌陷。修复室正门整晚只有两个人刷过卡，屋里恒温恒湿，数字一格不差。馆长把手电塞给你，没看你：“镇馆之宝，辛师傅最近一直说有点不对。你先看，别声张。”","victim":{"name":"辛怀远","desc":"博物馆首席文物修复师，六十一岁，做了二十五年青铜器修复。侧倒在工作台与档案柜之间，后脑遭钝器重击，脚边有带血的铅压块。","look":{"skin":"light","hair":"short","hairColor":"grey","glasses":"round","beard":"none","outfit":"labcoat","mood":"tired"}},"publicFacts":["镇馆之宝是战国云纹错银铜壶（ZG-0417），保额8000万，公估报告出具后保险才生效。","修复室正门读卡：18:02辛怀远进，22:04葛桂香进，其间无人刷卡。","修复室另有一扇通后勤通道的货运门。展厅层与修复区装有温湿度记录仪。","当晚在馆：馆长、策展人、安保主管、公估师、捐赠人、研究员、保洁员，另有一名志愿者。","法医初步：死亡约21:15至21:55，凶器是现场的铅压块。","当晚大雨，外人进不来，案发后也没人离开过馆。"],"relations":{"jian":"本展策展人，馆里共事二十一年的同事","tu":"博物馆馆长，辛怀远的上司","mou":"安保主管，管着修复室的门禁和监控","feng":"外聘公估师，为云壶出报告，今晚才打交道","wu":"前副馆长的遗孀，和辛怀远是老相识","zhai":"考古系志愿者，一直想拜他当师父","guan":"青铜器研究员，常和修复室打交道的同行","ge":"夜班保洁员，他常给她留热茶"},"links":[{"a":"jian","b":"feng","text":"今晚一起在展厅核对展品"},{"a":"tu","b":"wu","text":"馆长与捐赠人，正商量新翼铭牌"},{"a":"wu","b":"jian","text":"邬春婉的亡夫，曾是简兰絮之父的副手"},{"a":"tu","b":"jian","text":"屠启贤看着简兰絮长大"}],"deathReport":{"time":"约 21:15–21:55","cause":"后脑遭钝器重击，颅骨塌陷","scene":"22:04 保洁员葛桂香刷卡进修复室，见辛怀远倒在工作台与档案柜之间，脚边有带血的铅压块。","loc":"lab","notes":["后脑一处钝器伤，伤口与铅压块相符","室内恒温恒湿，体温难以精确推断死亡时间","倒地处没有明显拖拽痕迹"]},"timeline":[{"t":"18:02","text":"辛怀远刷卡进入修复室，留下做开幕前的最后一遍保养。"},{"t":"20:10","text":"云壶展柜开启，20:17关闭（双卡记录）。"},{"t":"22:04","text":"保洁员葛桂香进修复室，发现辛怀远倒地。"},{"t":"22:09","text":"安保主管牟振岳封锁现场并报警。"},{"t":"22:40","text":"你到达现场，馆长请你在警方接手前先查一轮。"},{"t":"23:10","text":"法医初步：死亡时间约21:15至21:55。"}],"budget":{"search":12,"ask":28},"locations":[{"id":"lab","name":"文物修复室","scene":"lab","desc":"二楼后区的恒温修复室，灯光冷白。正门要刷卡，另有一扇通后勤通道的货运门。","clues":[{"id":"c_lab1","title":"倒在台边的人","text":"辛怀远倒在台边，后脑塌陷，脚边有带血的铅压块。货运门内侧是开门按钮，外侧只有门铃，地垫上粘着橙黄漆皮。"},{"id":"c_lab2","title":"修复室记录仪","text":"记录仪基线22.0℃、50%。18:31、19:02、21:13、21:38、22:04各有小尖峰，降温升湿。"},{"id":"c_lab3","title":"摊开的工作笔记","text":"辛的笔记：“10.16 18:47 报告到，年代不对。”“和九六年那回事对得上。”“先跟邬家、简家各讲一声，再报馆长。”"},{"id":"c_lab4","title":"打印机里的报告","text":"热释光报告：壶内壁泥芯“距今30±4年”，备注“与战国时期不符”。打印时间19:10。"}]},{"id":"hall","name":"《吴越遗珍》展厅","scene":"hall","desc":"明早剪彩的新展厅，油漆味未散。中央展柜里是镇馆之宝，墙角立着展板和脚手架。","clues":[{"id":"c_hal1","title":"镇馆之宝展柜","text":"展柜记录：20:10开柜（简、牟双卡），20:17关柜。柜前地毯上掉着一枚卡通青铜壶徽章。"},{"id":"c_hal2","title":"序言板校样","text":"序言板落款：“策展简兰絮，谨以此展纪念先父简伯勋先生。”校样上“十八年”被圈出，批注“任期1985—2003，已核”。"},{"id":"c_hal3","title":"值班台与展板后","text":"值班台内线显示“3105”。台后展板遮着一扇疏散门，门下和地毯边散着橙黄色漆皮碎屑。"},{"id":"c_hal4","title":"洗手间的清洁牌","text":"女洗手间门口立着“清洁中”牌，登记本写“21:00立牌，21:50收牌”。里面地面拖得发亮，纸盒封条未拆。"}]},{"id":"back","name":"货运过渡间与后勤通道","scene":"backstage","desc":"展厅背后的小过渡间，一侧通展厅，一侧通无空调的后勤通道。通道新刷了橙黄防滑漆。","clues":[{"id":"c_bac1","title":"过渡间记录仪","text":"记录仪基线18.0℃、55%。17:50、21:09、21:41、22:06各有尖峰。纸角铅笔字“通道侧14℃”。"},{"id":"c_bac2","title":"被旁路的报警触点","text":"过渡间两道门的报警触点全灭，旁边插着旁路钥匙，标签“10.10 布展期间暂停”。"},{"id":"c_bac3","title":"清洁车的夹层","text":"后勤通道的清洁车，下层夹层里藏着布展剩的纸箱、整箱矿泉水和两只周边帆布袋。"}]},{"id":"sec","name":"安保监控室","scene":"engine","desc":"一整面墙的监控屏闪着蓝光，窗外雨一直不停。","clues":[{"id":"c_sec1","title":"展厅摄像头回放","text":"回放：21:07简兰絮走进展板后的角落；21:31冯思齐回厅，不见她；21:43她走回值班台。那个角落不在镜头内。"},{"id":"c_sec2","title":"内线通话记录","text":"20:57 修复室3105→展厅值班台2210，41秒。21:06 馆长室→安保室，12秒。21:22 研究室→食堂。"},{"id":"c_sec3","title":"修复室门禁","text":"修复室正门读卡：18:02辛怀远进，22:04葛桂香进，中间无人。监控室门禁：牟振岳20:20刷进，22:07才刷出。"},{"id":"c_sec4","title":"露台摄像头","text":"露台回放：冯思齐21:04撑伞出门接电话，来回踱步，21:29挂断，21:30进屋。露台上只有他一人。"},{"id":"c_sec5","title":"访客登记与巡屏本","text":"大厅登记：邬春婉18:25入、19:08出，提保温桶进、空手出；翟一鸣工牌20:00刷出。巡屏本21:30一栏空白。"}]},{"id":"arc","name":"库房档案室","scene":"cellar","desc":"一楼库房深处的档案室，铁架上堆满发黄的登记册，除湿机嗡嗡响。","clues":[{"id":"c_arc1","title":"1996年水损登记册","text":"7月19日：暴雨进水，“ZG-0417铜壶坠地碎裂，无法拼复”。签字简伯勋、邬松年。后面几页被订书钉订住。"},{"id":"c_arc5","title":"被订住的几页","text":"订住的三页：6月30日出库单（送苏城鉴定，归库栏空白）；境外汇款回执，收款人简伯勋；水损页补记“碎片未见”。"},{"id":"c_arc2","title":"1996年付款凭证","text":"同年10月凭证：苏城锻铜工艺社仿古铜器一件，8600元，经办简伯勋。变更表写“ZG-0417修复完成，归库”。"},{"id":"c_arc3","title":"档案借阅登记","text":"借阅：9.30屠启贤，10.9管亦桐（1996年登记册），10.12辛怀远。夹着移交单：简伯勋笔记三册，简兰絮签收。"},{"id":"c_arc4","title":"壶的老照片","text":"登记卡背面两张照片：黑白照壶口内沿有铸缝；1997年彩照内沿光滑。重量栏旧写5.62kg，改为4.10kg。"}]},{"id":"office","name":"馆长办公室","scene":"study","desc":"三楼馆长室，红木大桌上堆着剪彩红绸、致辞稿和铭牌校样。","clues":[{"id":"c_off1","title":"致辞稿与保险函","text":"致辞稿“毫发无损”一行被圈出，旁注“待修复科确认”。保险函：保额8000万，公估报告出具后生效。另有抵押贷款申请。"},{"id":"c_off2","title":"修复师的邮件","text":"9月27日辛怀远写：“云壶取泥芯送检，结果先报您。”屠启贤回：“等开幕后再说，别声张。”10月14日辛再催，无回复。"},{"id":"c_off3","title":"捐赠协议与铭牌","text":"邬松年纪念厅捐赠协议，邬春婉捐1200万。铭牌校样上她手写：“请把‘守护国宝’四个字留着。”"},{"id":"c_off4","title":"会客记录","text":"邬春婉19:55—22:00在馆长室。走廊摄像头：21:11屠启贤出门，21:14回，其间无人进出。茶几两只杯，茶已凉。"}]}],"suspects":[{"id":"jian","name":"简兰絮","role":"《吴越遗珍》策展人","age":44,"look":{"skin":"light","hair":"bun","hairColor":"black","glasses":"round","beard":"none","outfit":"turtleneck","acc":"necklace","mood":"neutral"},"bio":"展陈部主任，本展总策展人，馆里工作二十一年。称整晚在展厅，与公估师冯思齐在一起。","demeanor":"温和书面，语速慢，爱停顿；被逼到点上先笑一下。","topics":[{"id":"t_role","q":"负责什么","a":"总策展，从选件、布光到写序言都是我。最后一晚，我就是在看每件器物是否站稳了自己的位置。"},{"id":"t_where","q":"案发时在哪","lie":true,"a":"一直在展厅，和冯老师核对展柜、重拍底足。中间只去过一趟洗手间，大概就五六分钟。我没离开过多久。","truth":"我离开了三十多分钟，没有去洗手间，是去了修复室。辛老师叫我去的。我怕说出来被怀疑。"},{"id":"t_call","q":"20:57的电话","needs":["clue:c_hal3"],"lie":true,"a":"馆长打的，在楼上催四号射灯的色温。最后一晚他总是这样，一遍遍地问，我早就习惯了，没多想。","truth":"是辛老师，从修复室打来。他说：“兰絮，来一趟，有件事想先对你说，关于你父亲。”我说，我知道了，你先别动。"},{"id":"t_know","q":"父亲与云壶","lie":true,"a":"家父在任十八年，经手的器物成千上万，云壶只是其中一件。他不爱跟我讲馆里的事，那一代人都这样。","truth":"我知道。2019年读他的遗物笔记：1996年库房进水，壶碎了，他怕担责，找人仿了一件。我锁了七年。"},{"id":"t_sold","q":"那张出库单","needs":["ask:jian.t_know","clue:c_arc5"],"lie":true,"a":"外借鉴定是常事，壶后来回了库，七月才遇上水灾。汇款回执是别的款子，跟壶没有关系。","truth":"笔记里写：六月壶托人带出，卖了四十五万美元，水灾是三周后的由头。壶没碎过。辛老师追下去，追到的就是这个。"},{"id":"t_whyshow","q":"为什么办展","needs":["clue:c_hal2"],"a":"他一辈子守着这座楼，却连一块牌子都没有。《吴越遗珍》，就是我亲手给他立的那块牌子。"},{"id":"t_route","q":"货运过渡间","needs":["clue:c_hal3"],"a":"布展那半个月都走那条路，当然熟。可今晚我没走过，展板后面太暗，地上全是线，容易绊倒。"},{"id":"t_alive","q":"你走时他怎样","needs":["ask:jian.t_where"],"lie":true,"a":"他还活着，坐在桌边，冲我点了头。我没碰他。你们很难信一个说过谎的人，我明白，但我说的是真的。","truth":"他没点头。他背对着我翻档案柜，说“我不能再替你父亲瞒下去”。我求他，他没回头。手边正好是那块铅。"},{"id":"t_report","q":"怎么看检测","needs":["clue:c_lab4"],"a":"一粒泥芯而已，热释光受很多因素影响，也可能是后补的。凭一页纸就说壶是假的，对辛老师和这座馆都不公平。"}],"confronts":[{"clue":"c_sec1","breaks":"t_where","crack":true,"a":"回放里她21:07消失，21:43回来。她轻轻一笑：“三十六分钟。好吧，我没去洗手间。”"},{"clue":"c_bac1","breaks":"t_where","a":"她盯着两处尖峰：“这是门在呼吸。我从展板后的疏散门走过去，又走回来，门开了两次。”"},{"clue":"c_hal4","breaks":"t_where","a":"“清洁中……葛阿姨一直守在门口，是吗？那我说的洗手间，就没有任何人能替我作证了。”"},{"clue":"c_sec2","breaks":"t_call","a":"她长长出了口气：“我以为你们不会查内线。是辛老师打来的。他最后约的人，就是我。”"},{"clue":"c_arc2","breaks":"t_know","a":"她只看了凭证一眼：“八千六百块。我父亲就用这点钱，买了一件让他夜里睡不着的东西。”"},{"clue":"c_lab2","breaks":"t_alive","a":"她看着22:04前再无尖峰，低声说：“门只为我开了两次。我出来之后，再没有别人进去过。”"},{"clue":"c_arc5","breaks":"t_sold","a":"她把三页纸摊在掌心，笑意慢慢没了：“有人把它订起来，想让它一直压在底下。对，就是这件事。”"},{"clue":"c_arc3","a":"她看着移交单上自己的签名：“三册笔记。我看了，我全明白了，可我什么都没说，一个字都没说。”"},{"clue":"c_lab3","a":"“邬家、简家各讲一声……”她低声说，“辛老师想给我时间。可我有了时间，只会做更糟的决定。”"}],"fallback":"这件东西，我需要再想一想。"},{"id":"tu","name":"屠启贤","role":"馆长","age":58,"look":{"skin":"light","hair":"sidepart","hairColor":"grey","glasses":"rect","beard":"none","outfit":"suit","acc":"tie","mood":"stern"},"bio":"博物馆馆长，主持新展筹备，明早剪彩。称案发时在馆长室，和捐赠人邬春婉核对铭牌校样。","demeanor":"官腔，爱说“这个嘛”“组织上”，急了拍桌子。","topics":[{"id":"t_role","q":"开幕的意义","a":"这个嘛，是全馆三年的心血。明天市里、省里的领导都来，电视台也到，谁也不想在这时候出岔子。"},{"id":"t_doubt","q":"辛师傅提过疑问","lie":true,"a":"没有。云壶这么多年鉴定、展出、保险都没问题。辛师傅若有疑问，一定会第一时间向我汇报。","truth":"写过邮件。他九月底说取泥芯送检，我回“开幕后再说”。八千万保险、贷款、领导都压着，我想等过这一天。"},{"id":"t_open","q":"为什么开柜","a":"保险公估要求开幕前验底拍照。开柜须双卡，策展一张、安保一张，二十分钟内开了就关。"},{"id":"t_alibi","q":"案发时在哪","a":"馆长室，晚上八点到十点和邬女士对校样。中间去了趟洗手间，就三分钟。茶杯还在茶几上。"},{"id":"t_insure","q":"保险与贷款","needs":["clue:c_off1"],"a":"抵押贷款是新馆资金安排，合法合规。保险要等公估报告生效。你想说我有杀人的理由？荒谬。"},{"id":"t_press","q":"为何让他等","needs":["clue:c_off2"],"a":"延期就是新闻，新闻就是八千万的损失。可我只是让他等一天，没想过让他送命啊。你们不懂一把手的难处。"},{"id":"t_jian","q":"怎么看简兰絮","needs":["clue:c_hal2"],"a":"老馆长的女儿，我看着长大的。为这个展，她三个月没回过家。她要杀人，我第一个不信。"}],"confronts":[{"clue":"c_off2","breaks":"t_doubt","a":"他看着自己那行“等开幕后再说”，把手按在桌上：“……是我的字。”声音一下子哑了。"},{"clue":"c_off1","a":"“那行是我圈的。”他不看你，“没有把握的话，就不能在大庭广众之下讲，这是原则问题。”"},{"clue":"c_lab3","a":"他看完笔记，嘴角往下塌：“把我排在第三位……老夫子，你到底是怕我，还是怕什么……”话没说完。"},{"clue":"c_arc1","a":"他盯着被订住的几页，第一次露出真实的惊愕：“老馆长从没跟我提过。这些页是谁订的？”"},{"clue":"c_arc5","a":"他捏着三页纸：“六月就出库了？那水损那页写的什么？这要是真的，不是丢脸，是要进局子的。”"},{"clue":"c_sec2","a":"“21:06那通是我打的，叫安保备车送邬女士，就十二秒。灯光？灯光是兰絮的事。”"},{"clue":"c_off4","a":"“三分钟，真的。”他摊开手，“我去洗手，回来茶还没凉。你们要把我编进哪个故事里？”"}],"fallback":"这个嘛，我需要请示一下，你先问别的。"},{"id":"mou","name":"牟振岳","role":"安保部主管","age":50,"look":{"skin":"tan","hair":"short","hairColor":"black","glasses":"none","beard":"stubble","outfit":"uniform","acc":"headset","mood":"tired"},"bio":"安保部主管，退伍军人，管全馆门禁和摄像头十一年。称案发时一直坐在监控室里盯屏，没离开。","demeanor":"军人腔，短句，爱说“报告”；心虚就立正。","topics":[{"id":"t_role","q":"你管什么","a":"报告，门禁、监控、报警三样。一百二十三个摄像头，三十七道读卡门，这是我立的规矩。"},{"id":"t_alarm","q":"货运间报警","lie":true,"a":"正常布防，每天早晚各测一次，我签字。没有任何一道门，能在不报警的情况下被打开，报告。","truth":"两道门磁，我10月10日旁路了。布展天天进出，夜里误报，我想开幕完就恢复。我失职。"},{"id":"t_watch","q":"案发时做什么","lie":true,"a":"在监控室，全程盯屏。每半小时巡屏一次，签字留底，全程没有离岗，没有睡觉，没有漏看，报告。","truth":"21:15前后我困得趴下了，到21:48才醒，赶紧给馆长室打电话。21:30那行没签，因为我在睡觉。丢人。"},{"id":"t_open","q":"开柜经过","a":"20:10开柜，20:17关柜，我和简主任双卡，冯先生拍摄。20:20我回监控室，程序完整。"},{"id":"t_door","q":"修复室门禁","needs":["clue:c_sec3"],"a":"正门读卡，进出都记，当晚只有辛老师和葛阿姨两个人。记录可靠。货运门另说，没读卡器。"},{"id":"t_code","q":"谁走货运门","needs":["clue:c_bac2"],"a":"布展时馆长、简主任、管老师和我都走过那道门。它没有读卡器，没有读卡记录，谁走过都查不到，报告。"},{"id":"t_find","q":"发现经过","a":"22:04葛阿姨进去，22:07内线喊我，声音在抖。我上去封锁现场，22:09报警，只碰过门把手。"}],"confronts":[{"clue":"c_bac2","breaks":"t_alarm","a":"他立正，盯着旁路钥匙：“报告，是我停的。如果当时恢复了，今晚也许会有一声警报。我担全责。”"},{"clue":"c_sec5","breaks":"t_watch","a":"他盯着21:30那行空白，腰板塌下去：“是，我打了盹，三十多分钟。我不敢补签。”"},{"clue":"c_sec1","a":"“这块是死角，被脚手架挡了，我申请过移机，预算没批下来。”他指着展板后面的黑块。"},{"clue":"c_bac1","a":"他看着两处尖峰，神色一变：“两道门被开过两回，我没收到报警，因为我关了。谁走的？”"},{"clue":"c_hal3","a":"“3105，是修复室。”他皱起眉，“通道的橙黄漆三天前才刷，没干透，踩过就会带。”"}],"fallback":"报告，这个我不清楚。"},{"id":"feng","name":"冯思齐","role":"保险公估师","age":38,"look":{"skin":"light","hair":"sidepart","hairColor":"black","glasses":"rect","beard":"none","outfit":"shirt","acc":"tie","mood":"worried"},"bio":"保险公司外聘公估师，负责云壶的开幕前报告。称案发时与简兰絮一直在展厅，没分开过。","demeanor":"爱报数字，精确到分钟；紧张就推眼镜。","topics":[{"id":"t_role","q":"你的工作","a":"出具公估报告。云壶保额八千万，报告出来之后保险才生效。今晚十点前，我本该把稿子交上去。"},{"id":"t_together","q":"一直在一起吗","lie":true,"a":"是的，20:05进展厅到22:04听到消息，没分开过。我能为她作证，她也能为我。","truth":"没有。21:04我去露台接总部电话，21:30才回。我想让报告和行踪都显得干净。回来时，展厅没人。"},{"id":"t_open","q":"开柜所见","a":"20:10到20:17我拍了四十一张。壶底内壁有一圈接缝，不太自然，我当时没说。"},{"id":"t_call","q":"总部电话","needs":["clue:c_sec4"],"a":"总部问壶底接缝要不要写“保留意见”。写了保险不生效，剪彩就悬了。我拖了二十五分钟。"},{"id":"t_out","q":"谁让你去的","needs":["ask:feng.t_call"],"a":"简老师。我说这里回音大，她说露台信号好，你去接，我替你看着柜子。现在想想，她替我想得真周到。"},{"id":"t_return","q":"回厅情形","needs":["ask:feng.t_together"],"a":"21:31我回到值班台，一个人也没有，平板还亮着。21:43她从展板后出来，说去了洗手间，脸色很白。"},{"id":"t_phone","q":"值班台电话","a":"20:57左右响过，简老师接的，说“我知道了，你先别动”。她事后说是馆长催灯光。"}],"confronts":[{"clue":"c_sec4","breaks":"t_together","a":"他看着露台回放里踱步的自己，推推眼镜：“21:04。我没有说谎的习惯，除了今晚。离开了二十六分钟。”"},{"clue":"c_sec1","a":"他盯着21:31那一帧：“她那时候不在。我还以为她去了洗手间，一个人等得很焦虑，一直看表。”"},{"clue":"c_hal1","a":"“开柜记录。”他点头，“双卡，十分钟，四十一张。底足内壁那圈接缝，我至今记得。”"},{"clue":"c_lab4","a":"他读着“30±4年”脸色发白：“报告不能写‘无异常’了。保险、剪彩全垮。辛老师是因为这个？”"},{"clue":"c_hal3","a":"“就是那一通，20:57。”他想了想，“简老师当时看了我一眼，把话筒贴得很紧。”"}],"fallback":"这个不在我的公估范围内，我需要再核实。"},{"id":"wu","name":"邬春婉","role":"新翼捐赠人","age":72,"look":{"skin":"fair","hair":"bun","hairColor":"white","glasses":"none","beard":"none","outfit":"coat","acc":"necklace","mood":"worried"},"bio":"亡夫邬松年曾任副馆长，她捐赠1200万建新翼。称今晚只为核对铭牌，一直和馆长在一起。","demeanor":"上海口音，爱说“阿拉”“勿要”；提到丈夫就红眼圈。","topics":[{"id":"t_role","q":"为何捐钱","a":"阿拉屋里厢老邬做了十四年副馆长。伊走了，我想给伊一块牌子，让后头人晓得伊守过东西。"},{"id":"t_visit","q":"见过辛师傅","lie":true,"a":"勿曾，我今朝一直在馆长室对校样，对到老晚。辛师傅我老早就认得，今朝真的勿曾碰过面。","truth":"见过。我十八点二十五到馆，拎保温桶去修复室送腌笃鲜。坐了半个钟头，伊讲壶可能勿是老的。"},{"id":"t_alibi","q":"案发时在哪","a":"馆长室，十九点五十五到二十二点，同屠馆长对铭牌。伊出去三分钟样子。凉茶杯里是我唇印。"},{"id":"t_husband","q":"丈夫与云壶","needs":["clue:c_off3"],"a":"老邬是副馆长，哪能勿有关系？伊病里一直讲“对勿起老简”，我也勿晓得伊到底对勿起啥。"},{"id":"t_said","q":"辛怎么说","needs":["ask:wu.t_visit"],"a":"伊讲取了泥芯去验，晚上出结果。伊讲“我勿是为难老邬，是不能让东西骗人”，会先同该讲的人讲。"},{"id":"t_adv","q":"劝他先找谁","needs":["ask:wu.t_said","clue:c_lab3"],"a":"我讲，那你先同兰絮讲吧，伊是老简的小囡，最懂事。伊点点头，讲好的。我回来越想越勿安。"},{"id":"t_jian","q":"怎么看简兰絮","needs":["clue:c_hal2"],"a":"老简走的辰光，伊一个人站在灵堂角落，一滴泪勿落。这趟展览，就是伊对爷的一桩交代。"},{"id":"t_plaque","q":"为何在意铭牌","needs":["clue:c_off3"],"a":"“守护国宝”是老邬一世人的体面。我勿要这块牌子，同啥假的、骗人的东西扯上关系。你讲我自私，我认。"}],"confronts":[{"clue":"c_sec5","breaks":"t_visit","a":"她绞着披肩流苏：“你们连这个都有……好，我去过。进去是满的，出来是空的，伊吃光了。”"},{"clue":"c_lab2","breaks":"t_visit","a":"她俯身看那两处尖峰，18:31，19:02，嘴唇发抖：“门开一趟起一个峰……这两趟是我。”"},{"clue":"c_off3","a":"她按住校样一角，红了眼圈：“这几个字勿要改。老邬走了九年，勿想伊还背勿清勿白的事。”"},{"clue":"c_arc5","a":"她翻着三页纸：“老邬签水损页的辰光，晓得壶勿在库里吗？伊到死讲对勿起老简，原来是这个。”"},{"clue":"c_arc1","a":"她看着“邬松年”三个字，沉默很久：“这是伊的字。难怪伊后来每个礼拜去老简墓上。”"},{"clue":"c_off4","a":"“我的口红印勿会错。”她碰了碰杯沿，“另外一只是屠馆长的，伊话多，茶倒喝得少。”"}],"fallback":"勿晓得，这个阿拉真勿晓得。"},{"id":"zhai","name":"翟一鸣","role":"大学生志愿者","age":21,"look":{"skin":"light","hair":"messy","hairColor":"black","glasses":"none","beard":"none","outfit":"hoodie","acc":"headset","mood":"smile"},"bio":"考古系大三学生，新展的讲解志愿者。称自己八点就下班回了宿舍，之后没有再回过馆里。","demeanor":"网络用语，爱说“离谱”“绝了”；紧张语速飞快。","topics":[{"id":"t_role","q":"做什么","a":"讲解志愿者，背了一个月稿子，开幕第一场就是我，家人们。我人傻了。结果现在出这种事，绝了。"},{"id":"t_leave","q":"几点离开","lie":true,"a":"八点，工牌刷出去的，大厅有记录。我回宿舍背稿子了，真的没再回来过，我一个小志愿者晚上进展厅干嘛？","truth":"工牌八点刷出，但我借室友的工牌溜回来，想偷拍壶发账号。拍了二十分钟，21点前从员工通道走了。"},{"id":"t_phone","q":"听见什么","needs":["ask:zhai.t_leave"],"a":"20:57值班台电话响，策展人接的，说“我知道了，你先别动”，然后盯着展板后那扇门发呆。"},{"id":"t_video","q":"拍到什么","needs":["ask:zhai.t_leave"],"a":"壶、展柜，背景里值班台旁有两个人：保险那位埋头敲电脑，策展人站着，看着有点紧张。别的没了。"},{"id":"t_why","q":"为何偷拍","a":"我学考古的，头回见战国的东西，想留个念想，也想涨粉。我知道不对，但我保证没碰壶！"},{"id":"t_xin","q":"和辛师傅","a":"辛师傅人超好，上周还教我认铜锈。我一直想拜他当师父……现在想起来就想哭，emmm。"}],"confronts":[{"clue":"c_hal1","breaks":"t_leave","a":"他盯着那枚卡通徽章：“我的！说怎么少个别针！行行行我招，我偷偷回来了，真没碰壶！”"},{"clue":"c_sec5","a":"“工牌是八点刷出。”他挠头，“但这只能证明工牌出去了，不能证明我本人，对吧？我自己招。”"},{"clue":"c_hal3","a":"他盯着内线电话：“就是这部，铃声叮——铃——咦，3105？那是后面修复室的分机吧。”"},{"clue":"c_lab3","a":"他读完笔记，眼圈红了：“‘邬家、简家’，是说邬婆婆和策展人吗？为什么偏偏是她们？”"}],"fallback":"呃，这个我没印象，emmm。"},{"id":"guan","name":"管亦桐","role":"青铜器研究员","age":47,"look":{"skin":"light","hair":"bun","hairColor":"brown","glasses":"round","beard":"none","outfit":"vest","acc":"pocketwatch","mood":"smirk"},"bio":"青铜器研究员，专著《吴越青铜》把云壶断为战国中期精品。称案发时独自在研究室写发言稿。","demeanor":"学究气，冷幽默，爱引《考工记》；被问到自己就收声。","topics":[{"id":"t_role","q":"怎么看云壶","a":"纹饰是典型的战国云纹错银，工艺到位。可它太端庄、太规矩，端庄得让人有一点不自在。"},{"id":"t_archive","q":"碰过档案吗","lie":true,"a":"没有。我的材料都在自己研究室里，档案室没必要去。十一月才交结题报告，现在没这个时间。","truth":"10月9日我借过1996年事故登记册，当天还。我对着壶的铸缝越看越不对，翻到壶摔碎那页就合上了，没敢往下翻。"},{"id":"t_alibi","q":"案发时在哪","a":"研究室，十九点五十回去写开幕发言稿，写着写着睡着了，被警铃吵醒。没人能证明，你们可以不当回事。"},{"id":"t_book","q":"你的专著","needs":["clue:c_arc3"],"a":"书里我把它定为战国中期。壶若有问题，我二十年的名声就是一笔糊涂账。要说动机，我有。"},{"id":"t_seam","q":"铸缝的问题","needs":["clue:c_arc4"],"a":"老照片口沿内壁有铸缝，是战国范铸的痕迹。现在这件光滑，像整体翻模。我10月9日才注意到。"},{"id":"t_code","q":"货运门","needs":["clue:c_bac2"],"a":"布展时我经常走那条路，门我熟，但今晚没走过。你要找最熟那一带的人，馆里有四个，不止我。"}],"confronts":[{"clue":"c_arc3","breaks":"t_archive","a":"她看着登记本上自己那行：“10月9日，管亦桐。是我的字。我去过。”她摘下眼镜擦拭。"},{"clue":"c_arc4","a":"她对比两张照片，指尖停在口沿内壁：“铸缝，黑白照有，彩照没有。不是壶变了，是壶换了。”"},{"clue":"c_lab4","a":"她读得很慢：“三十年……不是我的鉴定错了，是我的鉴定对象错了。这两件事，评审分得清吗？”"},{"clue":"c_arc1","a":"她像被当头泼了冷水：“1996年，我还在读硕士。老简，老邬，你们怎么敢……怎么敢。”"},{"clue":"c_bac2","a":"“旁路钥匙。”她挑眉，“‘暂停’两个字很有意思，像在说门有话要说，但暂时不让说。”"}],"fallback":"这个不在我的专业范围里，恕我无话可说。"},{"id":"ge","name":"葛桂香","role":"保洁员","age":57,"look":{"skin":"tan","hair":"bun","hairColor":"grey","glasses":"none","beard":"none","outfit":"apron","mood":"tired"},"bio":"夜班保洁员，东北人，在馆九年。称先在展厅层女厕打扫，22点才去修复室，是第一发现人。","demeanor":"东北话，爱说“哎呀妈呀”；实在，一慌就数落自己。","topics":[{"id":"t_role","q":"每晚做什么","a":"擦地倒垃圾洗厕所。十点到十一点是修复室，进出要登记。辛师傅人好，从不嫌我慢，还每回给我留热茶。"},{"id":"t_cart","q":"清洁车里有啥","lie":true,"a":"就拖把、水桶、喷壶、消毒液，没别的了。馆里的东西我一根针都没拿过，我可是正经人，你放心。","truth":"哎呀妈呀……还有布展剩的纸箱、整箱水、两个帆布袋。馆里不要了，我拿去卖，给孙子交补课费，真不是偷！"},{"id":"t_sign","q":"21点到22点","a":"展厅层女厕，21:00立牌，21:50收牌。我在门口那条走廊拖了两遍，没人进过女厕。"},{"id":"t_see","q":"看到谁没有","needs":["ask:ge.t_sign"],"a":"21:43前后，简主任从展板那边走回值班台，头发有点乱，鞋面湿的，像踩过水。她冲我点点头。"},{"id":"t_find","q":"怎么发现的","a":"22:04我刷卡进修复室，辛师傅倒在台边，满地血。我腿一软愣了好几分钟，22:07才喊的安保。"},{"id":"t_xin","q":"和辛师傅","a":"好人。去年我孙子住院，他悄悄塞给我两百块，还不让说。拖了九年地，就他把我当“同事”。"}],"confronts":[{"clue":"c_bac3","breaks":"t_cart","a":"她肩膀垮下去：“哎呀，被你翻出来了。纸箱、水和帆布袋都是我拿的，别告诉馆长，我再不敢了。”"},{"clue":"c_hal4","a":"“就是这块牌。”她挺起腰，“我立的，登记本我一笔一画写的。这一个钟头我一步没离开。”"},{"clue":"c_lab1","a":"她嗓子里“咯”了一声：“就是这样！我进去的时候就这样！哎呀妈呀，我晚上睡不着了。”"},{"clue":"c_sec2","a":"她看着22:07那一条：“我喊他们之前已经傻了三分钟，什么都不记得，就记得手在抖。”"}],"fallback":"这个我不懂啊，我就是个扫地的。"}],"solution":{"culprit":"jian","method":{"q":"凶手怎样在“无人进出”的门禁记录里杀人？","options":["前一晚藏在修复室过夜，等他独自留下动手，再趁开门混出。","借他人门卡从正门刷入，事后改掉门禁记录，伪装成一人在室。","趁监控死角离开展厅，走后勤通道，由死者开货运门放行。","与另一人串通互作证，轮流离开，一人动手一人撑场面。"],"correct":2},"motive":{"q":"凶手为什么杀人？","options":["检测会揭出当年隐瞒水灾损毁，要替长辈守住名誉和展览。","检测会让开幕泡汤、保险失效、贷款落空，要保住钱和位置。","检测会推翻自己专著的结论，要保住多年积累的学术名声。","追查会揭出水灾只是掩护，真品被长辈私卖，怕罪行曝光。"],"correct":3},"keyClues":["c_lab2","c_bac1","c_sec1","c_sec2","c_arc5","c_hal2"],"truth":["凶手是策展人简兰絮。云壶是三十年前的仿品：1996年馆长简伯勋，即她的父亲，私卖真壶，再借水灾谎报“壶碎”，定制仿品顶替。","辛怀远送检发现壶只有30±4年。屠启贤压下邮件，邬春婉怕亡夫签字曝光，看似串通，但走廊摄像头证明两人没离开。","邬春婉好心劝他“先同兰絮讲”。20:57他从修复室打到展厅，接电话的正是简兰絮。她支开冯思齐，21:07躲进死角，走后勤通道，辛怀远从内侧开货运门放她进去。","谈不拢，21:33她趁他背身，抄起铅压块行凶，21:43回展厅，称去了洗手间。破绽：记录仪两处尖峰即两次开门，监控空白，内线记录，洗手间有人守牌。","她认下的“替父遮掩事故”是假动机。订住的三页证明壶六月就被卖掉，水灾只是掩护。辛怀远追查下去就会揭出盗卖国宝，她非动手不可。"]}},{"id":"onsen","title":"温泉旅馆","tagline":"雪封山路，露天汤池里的老板娘还是热的，可她究竟死于几点？","difficulty":3,"cover":"cv_onsen","tone":"warm","brief":"你是来泡汤养腰的前刑警，住在听雪汤屋3号房。零点三十分，山下派出所老所长来电：老板娘桑瑶卿死在露天汤池里，大雪封了山路，警车和法医明早才能上来。“你在上头，替我们看一眼，别让现场凉了。”楼里还有八个人：医生、作家、投资商、一对夫妇、领班、厨师和杂役。每个人都说什么也没看见，只有院子里的雪还没被人动过。","victim":{"name":"桑瑶卿","desc":"听雪汤屋老板娘，五十八岁，爱披旧羽绒服。被发现脸朝下漂在汤池里，只裹一条毛巾，后脑有挫伤，肩上有两道指印般的淤痕。","look":{"skin":"light","hair":"bun","hairColor":"grey","glasses":"none","beard":"none","outfit":"robe","acc":"flower","mood":"smile"}},"publicFacts":["听雪汤屋是半山腰的百年温泉旅馆。楼里除你和死者，有五名住客、三名员工。","桑瑶卿三十年来收完账，23:00前后独自泡“收工汤”。21:10她也这样告诉冉素珍。","据袁大有记录，雪从21:50下到23:30。山路已封，没人能上下山。","23:50冉素珍收灯时发现尸体。死因溺水，池水43度。","费承泽医生00:05初检：体温几乎没降，死亡“不超过一个半小时”，倾向滑倒溺水。","更衣屋储物柜的锁控器，会打印每次开合的柜号和时间。"],"relations":{"fei":"每年冬天都来的老友，也是退休医生","ran":"店里的仲居领班，管前台和客房","gu":"店里的厨师长，在这做了很多年","lu":"常来写稿的作家，和费医生是棋友","cen":"想买下这家旅馆的投资商","yu":"来度假的住客，和妻子同住6号房","luo":"来度假的住客，和丈夫同住6号房","yuan":"管锅炉和汤池的老杂役"},"links":[{"a":"yu","b":"luo","text":"结婚三年的夫妻"},{"a":"fei","b":"lu","text":"常在茶室下棋的老棋友"},{"a":"ran","b":"yuan","text":"一起在店里干了多年的老同事"}],"deathReport":{"time":"约 21:00–23:30","cause":"溺水，后脑有一处挫伤","scene":"23:50领班冉素珍收灯时发现，她脸朝下漂在露天汤池里，只裹着一条毛巾。","loc":"pool","notes":["后脑一处挫伤，不深","双肩各有一道指印般的淤痕","池水43度，尸体泡在热水里"]},"timeline":[{"t":"21:10","text":"桑瑶卿对冉素珍说，十一点前后去泡收工汤。此后没人公开承认见过她。"},{"t":"21:50","text":"开始下雪。"},{"t":"23:30","text":"雪停，池边量雪尺读数六厘米。"},{"t":"23:50","text":"冉素珍发现桑瑶卿漂在汤池里。"},{"t":"00:05","text":"费承泽初检，认为死亡在一个半小时内。"},{"t":"00:30","text":"派出所来电，请你先稳住现场。"}],"budget":{"search":12,"ask":28},"locations":[{"id":"pool","name":"露天汤池","scene":"garden","desc":"山岩围出的大汤池，白雾翻滚，竹篱、石灯笼和松枝都顶着厚雪。池水乳白，硫磺味很淡。","clues":[{"id":"c_pool1","title":"池边衣架上的浴衣","text":"无檐竹衣架上挂着桑瑶卿的浴衣，肩头积雪约六厘米，内衬是干的。架下小码木屐的鞋面也盖着雪。石灯台上的量雪尺同为六厘米。"},{"id":"c_pool2","title":"雪下的木屐印","text":"冉素珍踩出的一行脚印下，压着三行雪前的木屐齿印：小码只进不出；大码一去一回，左脚印浅，步距不匀。石墩旁另有一行胶靴印，到石墩为止。"},{"id":"c_pool3","title":"漂着的酒托盘","text":"池面漂着木托盘，一把空酒壶，两只青瓷杯：一只有口红印，一只杯沿贴着灰白细发，杯里剩小半杯凉酒。托盘上没有雪。"},{"id":"c_pool4","title":"池沿的湿痕","text":"靠岩壁的池沿有一片湿痕，青苔被擦掉，沾着灰白发丝。池沿离水面二十多厘米，石面平整，没有尖角。"}]},{"id":"hut","name":"更衣小屋与回廊","scene":"hall","desc":"连着汤池的木板更衣屋，沿墙是编号储物柜。有顶回廊挂着暖黄灯笼，栏杆上没有积雪。","clues":[{"id":"c_hut1","title":"回廊公告牌","text":"回廊木牌贴着红纸：“大浴场今夜21:00—22:00排水清洁，暂停使用。——前台 冉”。大浴场门口挂着“清扫中”。"},{"id":"c_hut2","title":"储物柜开合记录条","text":"锁控器记录：No.1 21:47开21:49关；No.6 22:11开22:12关；No.12 22:38开22:41关。柜号即房号，不记人。No.1的手环挂在池边挂钩上，是干的。"},{"id":"c_hut3","title":"1号柜里的空文件夹","text":"1号柜是老板娘专用柜：旧羽绒服，一只空的蓝色文件夹，夹口卡着印有“…县人民医院”的纸边。门内便签：“周日，交给洛小姐。”"},{"id":"c_hut4","title":"12号柜里的折纸","text":"12号柜里有双皮鞋和一张折纸，是《泉质与水量评估报告》第4页，边缘毛糙。铅笔字：“三年下降七成，池水约半数靠锅炉补热。”"}]},{"id":"office","name":"账房","scene":"study","desc":"主楼尽头的小账房，老式账桌，墙上挂着旧照。炭盆已熄，台灯还亮着。","clues":[{"id":"c_off1","title":"摊开的账本","text":"账本最后一行：“21:20 汤池 酒一壶”。钢笔没盖帽，墨已干硬；老花镜压在页脚，转椅推开一臂远，茶已凉透结膜。"},{"id":"c_off2","title":"抽屉里的信稿","text":"信稿：“盈小姐：你父亲洛建华先生十二年前走得不明不白，当年的证明并非实情。周日我把东西交给你，也请当年在场的人当面说清。”末注：“放更衣屋1号柜。”"},{"id":"c_off3","title":"收购意向书","text":"买方岑氏文旅，报价4800万，首页被红笔打叉，写着“不卖”。夹着的五页评估报告，第四页被撕走。"},{"id":"c_off4","title":"合作社章程草稿","text":"手写《员工合作社章程》草稿，股东列冉素珍、古泰来、袁大有，注明“周日早饭后宣布”。末页有泪痕，沾着一根栗色长发。"}]},{"id":"boiler","name":"锅炉房","scene":"engine","desc":"主楼背面的锅炉房，老锅炉闷烧，铜管成排，墙上钉着控制盘和手写黑板。","clues":[{"id":"c_boi1","title":"池暖控制盘","text":"“池暖”旋钮拨在“手动”。字条：“池暖每晚22:00自停，夜里勿动。——袁”。记录笔曲线从17:00起一直停在43度，直到纸尽。"},{"id":"c_boi2","title":"炉膛里的纸灰","text":"炉膛里是刚烧过的纸灰，炉口压着一角医院复写联，可辨“…建华”“…性猝死”，“医师签章”后焦黑，有半枚红印。灰还有余温。"},{"id":"c_boi3","title":"袁大有的记事本","text":"记事本今天写着：“18:00 池暖 自动√”“21:50 起雪”“23:30 雪停，尺6”“00:05 池暖怎么是手动？？”最后一行字迹发抖。"},{"id":"c_boi4","title":"风箱后的酒瓶","text":"风箱后暗格有半瓶白酒、缺口搪瓷杯和一件棉袄。通后院茅房的小门虚掩，门槛有未化的雪水。"}]},{"id":"lounge","name":"茶室休息厅","scene":"dining","desc":"一层茶室，地台上摆着炭炉和围棋盘，墙边是衣架酒柜，窗外庭院被雪吞没。","clues":[{"id":"c_lou1","title":"围棋棋谱本","text":"路明川的棋谱：“第1手 黑 费 21:57”“第38手 22:40”“第112手 23:50 被打断”。首页“约21:30开局”，“21:30”被横线划去。"},{"id":"c_lou2","title":"炉边烘着的浴衣","text":"炉边烘着男浴衣，竹牌“8”，左袖从肘到袖口、下摆到膝全湿，有淡硫磺味；腰带是干的。"},{"id":"c_lou3","title":"作家的稿纸","text":"稿纸《听雪·续》：“泉眼三年前细得像根针，老袁说，现在池里一半的水是锅炉烧的。我也不愿写。”"},{"id":"c_lou4","title":"住客登记簿","text":"6号房郁乔、洛盈，备注有桑瑶卿的字：“洛小姐：这间朝池的房，留给你。”8号费承泽，9号路明川，12号岑志远。"}]},{"id":"kitchen","name":"厨房","scene":"kitchen","desc":"宽敞的厨房，台面擦得发亮，墙上吊着铁锅刀具，点单板钉在门边，满是高汤暖香。","clues":[{"id":"c_kit1","title":"点单板","text":"点单板：“21:20 汤池 酒一壶（桑）”“21:27 汤池 加杯一只（桑嘱）”，第二条的勾旁画着小小的“古”字。"},{"id":"c_kit2","title":"冰箱里的小蛋糕","text":"冰箱里有只小蛋糕，写着“盈盈 三周年快乐”，旁边绒面盒里是枚银戒。垃圾桶里有团写满“其实吧……”的草稿纸。"},{"id":"c_kit3","title":"划掉的新菜单","text":"下月菜单印着“岑氏文旅·统一配送”，页边“厨房人员优化：6人→2人”被狠狠划掉，下面写着“泰来：怎么办”。"}]}],"suspects":[{"id":"fei","name":"费承泽","role":"住客·退休医生","age":62,"look":{"skin":"light","hair":"sidepart","hairColor":"silver","glasses":"round","beard":"none","outfit":"robe","acc":"scarf","mood":"worried"},"bio":"退休心内科主任，每年冬天都来，是桑瑶卿的老友。他说九点半前就在茶室和路明川下棋。","demeanor":"温和慢条斯理，爱说“不碍事”，被问紧就擦眼镜。","topics":[{"id":"t_role","q":"您和老板娘熟吗？","a":"二十年的老朋友了。她怕冷，血压又偏高，我每年上来，一半是泡汤，一半是替她量血压。"},{"id":"t_bath","q":"21点到22点你在哪？","lie":true,"a":"饭后回房吃了药，九点半不到就下茶室找老路摆棋，一坐就是三个钟头。老路能替我作证，不会错。","truth":"没那么早。我先去了露天汤池，她约的，聊了十来分钟，我走时她还在池里喝酒。回茶室快十点了，怕被盯上才瞒。"},{"id":"t_robe","q":"你的浴衣怎么湿了？","lie":true,"needs":["clue:c_lou2"],"a":"晚饭前在大浴场泡过一回，披着这件擦的身子，没拧干，就一直挂到现在。上了年纪，邋遢，让你见笑。","truth":"大浴场那时封着，是我顺嘴编的。我走后又折回池边想把话说完，她已趴在水里，我蹲下探她，袖子下摆才湿的。"},{"id":"t_time","q":"你怎么判断死亡时间？","a":"四十三度的水凉得慢。我摸过，体温还在三十七度出头，估计不超过一个半小时。仅供参考，要等法医。"},{"id":"t_meet","q":"之后见过她吗？","lie":true,"a":"见过一回，二十二点四十分前后，在回廊碰上她，披着浴衣，说“先泡一会儿，账明天收”。那是最后一面。","truth":"没见过。回廊上根本没碰到她。那话是我顺着时间编的，就想让你们以为她那会儿还活着。"},{"id":"t_boiler","q":"你去过锅炉房吗？","lie":true,"needs":["clue:c_boi1"],"a":"锅炉房？我连门朝哪边开都不知道。看病的又不烧火，去那儿做什么。别拿这个为难我这老头子。","truth":"去过。我烧了十二年前我签的证明副本，还拨了旋钮，想让池子别凉。她是自己撞了池沿滑下去的，我吓住了，没敢叫人。"},{"id":"t_old","q":"十二年前的事","lie":true,"needs":["clue:c_off2"],"a":"洛建华？这么多年，记不得了。山里每年冬天总有老人出点状况，我又不是天天记账，哪记得住名字。","truth":"记得。那年阀门坏了，水烫到四十七度，洛先生在池里昏厥不治。桑瑶卿求我写“心源性猝死”，后来出钱给我诊所添了设备。"},{"id":"t_who","q":"你觉得是谁干的？","a":"我是医生不是警察。要说的话，岑老板席上脸色最难看，谈了三个月的买卖，听说被桑姨当面回了。外行话。"}],"confronts":[{"clue":"c_hut1","breaks":"t_robe","a":"他读完红纸，手指在袖口捏了捏。“……我忘了，那个钟点封着。”他摘下眼镜慢慢擦，“人老了，容我想想。”"},{"clue":"c_lou1","breaks":"t_bath","a":"他看着划掉的“21:30”和底下的“21:57”，轻轻“哦”了一声。停了一会儿才说：“好吧。我先去过汤池那边，说了几句话。”"},{"clue":"c_pool4","a":"他看了眼那段池沿，嘴唇动了动。“滑倒的话，头也能磕出伤来……”说到一半，自己也觉得不对，没再接。"},{"clue":"c_pool2","a":"他蹲下去看雪底下的齿印，像在数。“雪盖得乱，”他直起身，“走过去又走回来，谁数得清。”"},{"clue":"c_hut2","a":"“柜子？”他停了一下，“谁开的我不知道。我又不是……”话说了半句就收住，手指在膝盖上敲了两下。"},{"clue":"c_pool1","breaks":"t_meet","a":"他盯着积雪的浴衣，喉结动了一下。“她披的……不一定是这件。”话到一半自己先停了，“也许我记错了。”"},{"clue":"c_off2","breaks":"t_old","a":"他把信稿读了两遍，眼睛慢慢红了。“她还是写了。”声音很哑，“我劝过她，都过去了。她说，过不去，老费。”"},{"clue":"c_boi2","breaks":"t_boiler","crack":true,"a":"他看着炉膛里没烧透的复写联，很久没出声。“……我烧的。”他慢慢坐下，“可我没杀她，她自己磕了池沿，我吓坏了。”"}],"fallback":"这个我不太懂，说句外行话，你得去问更懂的人。"},{"id":"ran","name":"冉素珍","role":"仲居领班","age":45,"look":{"skin":"light","hair":"bun","hairColor":"brown","glasses":"none","beard":"none","outfit":"qipao","acc":"flower","mood":"tired"},"bio":"店里做了二十八年的领班，桑瑶卿最信任的人。她说21:10后没再见过老板娘，23:50发现尸体。","demeanor":"声音软，句句带“您”，说到桑姨会停顿。","topics":[{"id":"t_role","q":"你在店里做什么？","a":"十七岁进门，从后厨剥葱做起，后来跟桑姨学带客。迎客、送茶、铺被、收灯都归我。桑姨待我比亲姐姐还亲。"},{"id":"t_last","q":"最后见到老板娘是？","lie":true,"a":"二十一点十分，账房门口。她说收完账十一点前后去泡收工汤，别去扰她。那以后我没再往账房去过。","truth":"二十二点一刻我进去过，想翻翻卖了店我们怎么安排。灯亮着，椅子推在外头，笔帽没盖，人不在。桑姨从不那样离桌。"},{"id":"t_find","q":"你怎么发现的？","a":"二十三点五十，我去汤池收灯锁门。推开更衣屋的门，雾里有个影子趴在水面上，我腿一软就喊了。后来和费医生把她抬上来。"},{"id":"t_snow","q":"池边的雪是什么样？","needs":["clue:c_pool2"],"a":"雪都没过脚面了，路上就我一行脚印。我还在想，桑姨是什么时候进去的，怎么一点印子也看不见。"},{"id":"t_sale","q":"听说要卖店？","a":"岑老板谈了三个月，我们下面的人后来才听说。桑姨前天跟我说，“素珍，放心，谁也赶不走你们”。我信她。"},{"id":"t_doctor","q":"十二年前的医生","needs":["clue:c_boi2"],"a":"那年请的特约保健医生就是费医生。出事后他年年冬天来，桑姨每回都给他留最好的房，我还当他们交情深。"}],"confronts":[{"clue":"c_off4","breaks":"t_last","a":"她看着草稿上那根栗色长发，手一抖，围裙角攥成一团。“是我的头发……我进去过。不是偷东西，我怕卖了店没地方去。”"},{"clue":"c_off2","a":"她读完信稿，眼泪涌出来：“十二年前……我也在，那年我刚做领班。桑姨每年到那天，都一个人去池边坐半宿。”"},{"clue":"c_pool1","a":"“桑姨的浴衣，怎么积了这么厚的雪？”她声音忽然轻了，“雪还没下，她就进去了么？”"}],"fallback":"这个我真不知道，您问我别的吧。"},{"id":"gu","name":"古泰来","role":"厨师长","age":55,"look":{"skin":"tan","hair":"cap","hairColor":"grey","glasses":"none","beard":"stubble","outfit":"apron","mood":"worried"},"bio":"掌勺十五年的北方厨师长，在店里最久的老员工之一。他说晚宴后一直在厨房备料，没出过门。","demeanor":"大嗓门，爱“嘿”一声起头，一紧张就攥拳头。","topics":[{"id":"t_role","q":"你在店里干什么？","a":"嘿，掌勺的呗。十五年了，桑姨的口味我闭着眼都做得出来。客人吃得好，我心里就踏实。"},{"id":"t_kitchen","q":"晚宴后你在哪儿？","lie":true,"a":"厨房呗，还能去哪儿？收拾，备明早的料，一步没出过门。听见喊才知道出事，嘿，甭问我。","truth":"去过一趟。二十一点半前后桑姨叫我送酒，还加只杯子。我穿胶靴，走到石墩就放下了，没往池边去。怕被当成最后见她的人。"},{"id":"t_cup","q":"她当时说了什么？","needs":["clue:c_kit1","ask:gu.t_kitchen"],"a":"她泡在池里，笑着说：“费医生一会儿来，说点旧事。你别往前，杯子放石墩上。”我放下就走了。"},{"id":"t_menu","q":"新菜单是怎么回事？","needs":["clue:c_kit3"],"a":"岑老板的“统一配送”，厨房六个人裁成两个，我这把老骨头往哪搁？晚宴上我顶了他一句，他还笑里藏刀。"},{"id":"t_cake","q":"厨房晚上有什么事？","a":"嘿，小郁要给媳妇弄三周年惊喜，求我教做小蛋糕。三十五分来的，折腾到十点半，奶油抹得跟泥巴似的。"},{"id":"t_who","q":"你怀疑谁？","a":"我哪有资格怀疑谁。不过岑老板那人，一顿饭看了三回表，不像来谈买卖，倒像来收账的。"}],"confronts":[{"clue":"c_kit1","breaks":"t_kitchen","a":"他盯着那个“古”字，嗓门一下子低了：“……嘿，我画的。行，我认，去过汤池。可我送完就走，桑姨好好的，还冲我笑呢。”"},{"clue":"c_pool3","breaks":"t_kitchen","a":"他盯着那两只杯，挠挠头：“这杯是我送去的。得嘞，不瞒你了，我去过一趟汤池，就送了个杯子。”"},{"clue":"c_pool2","a":"他盯着那行胶靴印：“这是俺的靴子，到石墩就回了。嘿，雪底下压着，倒替俺作了个证。”"}],"fallback":"嘿，这个我不懂，你问点我能答的。"},{"id":"lu","name":"路明川","role":"住客·作家","age":48,"look":{"skin":"fair","hair":"messy","hairColor":"black","glasses":"rect","beard":"stubble","outfit":"turtleneck","mood":"smirk"},"bio":"写过随笔《听雪》的作家，十几年常客，住9号房。他说九点半起就和费承泽在茶室下棋。","demeanor":"爱打比方，说话绕，口头禅“怎么说呢”，被戳中会突然安静。","topics":[{"id":"t_role","q":"你写什么书？","a":"写过一本《听雪》，讲这家汤屋和山里的冬天。怎么说呢，书卖得比我想的好，汤屋也因此吵了不少。"},{"id":"t_game","q":"你和费医生下棋？","lie":true,"a":"九点半开的局。老费一向准时，一坐就是三个钟头，中间谁也没起身。冉姐一喊，我们才一起冲出去。","truth":"老费快十点才到，我一个人对着棋盘写了半晚稿子。替他圆……怎么说呢，老朋友的反射动作。"},{"id":"t_help","q":"是老费让你这么写的？","needs":["ask:lu.t_game"],"a":"没人让我。散席时他说“晚上摆一盘，九点半吧”。后来他进门快十点，头发袖口都湿的，我只当他偷泡了汤，顺手把时间写早了。"},{"id":"t_spring","q":"《听雪》里的泉水？","lie":true,"a":"天然的啊，源头就在后山，百年不竭，书里写得清清楚楚。怎么说呢，桑姨总说，那是汤屋的命。","truth":"书里写的是个梦。泉眼三年前就细得像根针，老袁说池里一半的水是锅炉烧的。我舍不得写，也怕毁了桑姨的店。"},{"id":"t_sound","q":"你听见什么动静？","a":"雪是快十点才下的。十点出头，回廊上有阵细碎的木屐声，像个女人，往楼上去了，走得急，像怕被谁看见。"},{"id":"t_vic","q":"桑老板娘是怎样的人？","a":"她像一盏灯，谁冷了都往她那儿靠。前天她还跟我说，“老路，周日有件大事，请你做个见证”。我没来得及问。"}],"confronts":[{"clue":"c_lou1","breaks":"t_game","a":"他低头看着划掉的时间，苦笑：“我这手字，连自己都不信。好，老费21:57才落第一子。可他不是那种人。”"},{"clue":"c_lou3","breaks":"t_spring","a":"他沉默很久才说：“被你翻到了。是，我知道。可一个人写了十几年的梦，不想亲手戳破。”"},{"clue":"c_lou4","a":"“洛小姐……”他念着那行字，“怎么说呢，桑姨留这间朝池的房，是有心的。她很少为谁留房。”"}],"fallback":"怎么说呢，这东西不在我的故事里。"},{"id":"cen","name":"岑志远","role":"住客·文旅投资商","age":43,"look":{"skin":"light","hair":"slick","hairColor":"black","glasses":"none","beard":"none","outfit":"suit","acc":"pocketwatch","mood":"stern"},"bio":"岑氏文旅副总，三个月来一直在谈收购，住12号房。他说晚宴很愉快，之后回房回邮件。","demeanor":"条理清楚，爱用数字说话，被问急了会看表。","topics":[{"id":"t_role","q":"你来做什么？","a":"岑氏文旅想整体收购听雪汤屋，做中高端康养度假。尽调、估值、报价都走完了，这周末来敲细节。"},{"id":"t_deal","q":"今晚谈得怎样？","lie":true,"a":"很顺利。老板娘对方案挺满意，细节周日再定。我们是合作关系，没有任何不愉快，你们尽管去问。","truth":"她当场回绝了，把意向书划了叉，说要改成员工合作社。我气得想掀桌子。可谁会为一单没谈成的买卖杀人？"},{"id":"t_night","q":"22点后你在哪？","lie":true,"a":"房间里回邮件，没出过门。我睡眠浅，是听见喊声才下楼的。不信的话，可以去查网络日志。","truth":"二十二点三十五分下过楼，溜进账房，撕了报告最要紧的一页想压价，藏进12号柜。我没去过汤池，走到更衣屋就折回了。"},{"id":"t_report","q":"评估报告怎么回事？","needs":["clue:c_off3"],"a":"第三方做的报告。第四页写泉量近三年降了七成，池水大半靠锅炉补热。“百年天然泉”只是话术，但影响估值。"},{"id":"t_saw","q":"你到更衣屋看见什么？","needs":["ask:cen.t_night"],"a":"雪已经下了一阵，更衣屋灯亮着，池那边白茫茫。衣架上挂着老板娘的浴衣，肩头有雪。我心虚，放了东西就走。"},{"id":"t_who","q":"你怀疑谁？","a":"我是外人。不过晚宴后那位医生拉着老板娘在回廊角落说了半天，两人脸色都不好，我一走近就不说了。"}],"confronts":[{"clue":"c_off3","breaks":"t_deal","a":"他看着首页的红叉，嘴角抿了一下。“她下笔很重。好吧，她拒绝了。我不想提，因为听上去就像个动机。”"},{"clue":"c_hut2","breaks":"t_night","a":"他看着“No.12 22:38开 22:41关”，沉默了一下：“12号是我的房号。我下过楼，拿了一页纸，仅此而已。”"},{"clue":"c_pool1","a":"他盯着肩头积雪的浴衣，算了算时间，脸色慢慢变了。“我22:35经过的时候，它就已经挂在那儿了。”"},{"clue":"c_hut4","breaks":"t_night","a":"“这页纸……”他叹了口气，“是我撕的，不光彩。但我没有杀人，不会为了半份报告杀人。”"}],"fallback":"这个跟我们的项目无关，回头再对一下口径。"},{"id":"yu","name":"郁乔","role":"住客·年轻丈夫","age":29,"look":{"skin":"fair","hair":"messy","hairColor":"black","glasses":"round","beard":"none","outfit":"hoodie","mood":"worried"},"bio":"来度三周年旅行的界面设计师，住6号房。他说晚饭后和妻子回房看电影，一直没再出门。","demeanor":"慌张、爱自我纠正，开口先说“其实吧”。","topics":[{"id":"t_role","q":"你们为什么来这儿？","a":"其实吧，今年是我们结婚三周年。盈盈一直想来这家汤屋，说看过攻略，我想给她一个惊喜。"},{"id":"t_night","q":"晚上你们在做什么？","lie":true,"a":"其实吧，九点就回房看电影了，一部老片子，看到十一点多才睡。我俩一直在一起，她能作证。","truth":"其实吧，二十一点三十五分我溜去厨房和古师傅做蛋糕，到二十二点半才回房。回去时盈盈已经躺下了。我不想她知道惊喜，才撒谎。"},{"id":"t_wife","q":"盈盈这几天怎么样？","a":"其实吧，她这几天怪怪的，有心事。入住时前台塞给她一张字条，她看完就折起来，说是账单。哪来的账单。"},{"id":"t_ring","q":"戒指是怎么回事？","needs":["clue:c_kit2"],"a":"其实吧，那是我攒了三个月钱买的，想在蛋糕上摆个小仪式。现在这样，戒指大概送不出去了。"},{"id":"t_back","q":"你回房时她在吗？","needs":["ask:yu.t_night"],"a":"在，床上，被子盖到下巴。可我现在想起来，她的拖鞋是湿的，鞋尖还有雪水。当时没在意，其实吧，后背发凉。"},{"id":"t_doc","q":"你和费医生聊过吗？","a":"其实吧，他挺和气。昨天盈盈说老家在南边，他盯着她看了好久，说“姓洛的人，我认识过一位”。"}],"confronts":[{"clue":"c_kit2","breaks":"t_night","a":"他一眼认出蛋糕，脸涨红：“被发现了！行行，我骗你了，我一直在厨房。盈盈不知道，千万别告诉她。”"},{"clue":"c_hut2","a":"“No.6是我们的房号。”他愣住，“可我晚上没去过更衣屋啊……是盈盈？”他马上摇头，“不，不会的。”"},{"clue":"c_kit1","a":"“加杯？”他茫然，“我进厨房的时候，点单板上已经有了。古师傅忙着，手上还拿着杯子。”"}],"fallback":"其实吧，这个我真的不知道。"},{"id":"luo","name":"洛盈","role":"住客·年轻妻子","age":27,"look":{"skin":"fair","hair":"long","hairColor":"black","glasses":"none","beard":"none","outfit":"coat","acc":"earrings","mood":"sad"},"bio":"郁乔的妻子，中学美术老师，住6号房。她说这趟纯粹是度假，晚上一直在房里，没出过门。","demeanor":"话少，句子短，不看人，被逼到点上才一口气说很多。","topics":[{"id":"t_role","q":"你们为什么来这儿？","lie":true,"a":"度假。三周年，翻攻略看到的这家。风景好，水也热。我们就是普通客人，真的没别的可说。","truth":"不是。我父亲洛建华十二年前死在这家的露天汤池里。三周前桑老板娘来信，说要把真相讲给我听。我没告诉乔乔。"},{"id":"t_night","q":"晚上你出过门吗？","lie":true,"a":"没有。看了电影，早早就睡了。我怕冷，晚上从来不出门，一直在房里陪着乔乔，没有别的事。","truth":"出去了。信上说“夜里十点，更衣屋见”，我犹豫到二十二点十一分才到。浴衣肩头有薄雪，池那边白雾茫茫。我叫了两声没人应，就走了。"},{"id":"t_letter","q":"信上写了什么？","needs":["ask:luo.t_night"],"a":"很短：“盈小姐，周日来。夜里十点，更衣屋有话先对你说。——桑”。我父亲死时我十五岁，医生说是心脏病。"},{"id":"t_father","q":"你父亲是怎样死的？","needs":["clue:c_off2"],"a":"他六十一岁，来疗养，泡汤时昏过去再没醒。证明写“心源性猝死”。可我妈说他死时皮肤红得吓人，像被烫伤。"},{"id":"t_doc","q":"你认识费医生吗？","a":"昨晚吃饭才第一次见。他听我报姓“洛”，手里的茶杯顿了一下，盯着我看了很久，我岔开了话。"},{"id":"t_return","q":"你回房路上遇到谁？","needs":["ask:luo.t_night"],"a":"二十二点二十分，我从茶室外走过，里面有人下棋。听见我的木屐声，路先生朝门口看了一眼。我低着头小跑上了楼。"}],"confronts":[{"clue":"c_off2","breaks":"t_role","a":"她把信稿读了两遍，肩膀微微发抖。“她真的写了……是，我不是来度假的。你们说我有动机，我认。可我只要真相，不要一条命。”"},{"clue":"c_hut2","breaks":"t_night","a":"她盯着“No.6 22:11”，咬着嘴唇：“是我。我去过更衣屋。我怕说了，你们会当我是凶手。”"},{"clue":"c_lou4","a":"“她写了‘留给你’。”她轻声说，“我以为她只是敷衍一个陌生客人。她从一开始就在等我。”"}],"fallback":"我不知道。……对不起。"},{"id":"yuan","name":"袁大有","role":"锅炉与汤池杂役","age":63,"look":{"skin":"brown","hair":"cap","hairColor":"grey","glasses":"none","beard":"stubble","outfit":"parka","mood":"tired"},"bio":"烧了四十年锅炉，管汤池水温和扫雪。他说整晚守在锅炉房，直到被冉素珍的喊声叫出来。","demeanor":"话少，口音重，爱“嗯”一声，问急了就搓手说“俺不懂”。","topics":[{"id":"t_role","q":"你管什么？","a":"烧锅炉，看水温，扫雪，四十年了。池水热不热，俺心里门儿清。老板娘说俺这手比温度计还准。"},{"id":"t_timer","q":"池暖的旋钮","lie":true,"needs":["clue:c_boi1"],"a":"那旋钮是俺晚上拨的手动。老板娘说今晚客人多，池子要多烧一阵。她交代的，俺就照做了。","truth":"没人交代，是俺撒谎。十八点俺拨的自动。零点过后见是手动，吓出一身汗，十二年前那回也是俺炉子的阀，俺怕又怪到俺头上。"},{"id":"t_out","q":"你整晚没离岗？","lie":true,"a":"没，一直守着炉子。夜里不能离人，这是规矩。俺哪也没去，一步都没挪过，不信你问那炉子。","truth":"二十一点四十五去了后院茅房，五十五分回来。暗格里藏了点酒，趁机喝了两口，怕老板娘骂。"},{"id":"t_man","q":"你回来时看到谁？","needs":["ask:yuan.t_out"],"a":"俺回炉房那会儿雪刚下。看见个高个子，穿浴衣，毛巾盖着头，从炉房往回廊走，左脚拖着地。脸没看清。"},{"id":"t_old","q":"十二年前那回事","needs":["clue:c_off2"],"a":"那年阀门裂了，池水烫到四十七度，洛先生就是那天……老板娘叫医生写了证明。俺一听洛这个姓就发憷。"},{"id":"t_cold","q":"池水本来会凉吗？","needs":["clue:c_boi1"],"a":"会。二十二点自停，到半夜十二点就凉到三十六度上下。要不是旋钮动了，十点以后那池子是要凉的。"}],"confronts":[{"clue":"c_boi3","breaks":"t_timer","a":"他盯着自己写的“18:00 自动√”，手在膝盖上搓了又搓：“……俺写的。行，俺认，没人交代过。俺怕。”"},{"clue":"c_boi4","breaks":"t_out","a":"他脸红到耳根，低着头说：“暗格里那点酒，俺认。二十一点四十五俺出去过一趟。这事传出去，俺饭碗……”"},{"clue":"c_pool2","a":"“雪底下有脚印？”他蹲下去用手比划，“有大有小，是雪前的。俺扫了四十年雪，这个看得出。”"}],"fallback":"嗯，俺不懂这个。"}],"solution":{"culprit":"fei","method":{"q":"凶手怎样让死亡时间“显得”晚于自己的不在场证明？","options":["她深夜独自入池，凶手趁夜深动手后悄悄回房。","她酒后滑倒溺水，凶手只是毁掉证物、再拨动了水温。","她入池不久即被害，凶手让水温整夜不降以改时间。","凶手把尸体从别处搬进池里，借大雪盖住拖痕。"],"correct":2},"motive":{"q":"凶手为什么杀人？","options":["他开过不实的证明，她要在周日说出真相，他怕身败名裂。","她拒绝了他谈了数月的收购方案，他不愿投入落空，失手杀人。","她的旧事曾让他的亲人丧命，他得知她要说实情，决心讨公道。","她打算把旅馆交给员工，取消他的长期低价包房，他积怨已深。"],"correct":0},"keyClues":["c_pool1","c_pool2","c_hut2","c_lou1","c_boi1","c_boi2"],"truth":["凶手是退休医生费承泽。十二年前锅炉失灵，洛建华昏厥不治，费受桑瑶卿之托开了不实的“心源性猝死”证明，还收了她的设备款。","桑决定周日把证明副本交给洛建华的女儿洛盈，约了费来池边谈。费与她争执，约21:40把她按进水里。","他用池边的1号手环取走副本，21:51趁袁大有离岗烧纸，并把旋钮拨成手动，让池水整夜不降温，好谎称死亡不过一个半小时。21:55他已在茶室下棋。","露馅处：衣架积雪六厘米，她降雪前已入池；雪下大码齿印一去一回；旋钮手动而记事本写“自动”；炉膛残片有“…建华”；“大浴场”“回廊遇见她”两谎被戳穿。","路明川是不知情的帮手：见费进门袖子全湿，以为他偷泡了汤，把开局写早。其余人都有秘密，但都与命案无关。"]}},{"id":"railway","title":"末班车","tagline":"大雪把夜行列车困在荒野，软卧里的死者，似乎死在每个人都有不在场证明的那个钟点。","difficulty":3,"cover":"cv_railway","tone":"purple","brief":"十二月七日夜，K2146次从北陵开往澜城，你是回乡的刑警，睡在7车硬卧。二十三点五十分，列车长贺怀山叫醒你：8车软卧03号包厢，旅客尹正衡被人打死了。列车22:41被积雪困在鹰嘴岭荒野里，救援最早凌晨四点才能到。随车医生检视后说，人是一小时内死的。列车长把名册推给你：“天亮之前，请您把凶手找出来。”","victim":{"name":"尹正衡","desc":"六十三岁，正衡物流老板，曾任铁路局运输处副处长。他侧卧在03号下铺，后脑被钝器重击，屋里热得像蒸笼。","look":{"skin":"light","hair":"sidepart","hairColor":"grey","glasses":"rect","beard":"none","outfit":"suit","acc":"tie","mood":"tired"}},"relations":{"he":"本趟列车的列车长，负责全车事务","yue":"随车乘警，负责车上治安","song":"8车乘务员，管软卧03号所在车厢","bian":"合伙六年的生意伙伴，当晚吵过架","xu":"同车的急诊科医生，住08-06","sheng":"同在8车软卧的退休小学老师","gan":"7车硬卧的音乐学院学生","lin":"柳河堡补票上车的旅客，坐3车硬座"},"links":[{"a":"he","b":"song","text":"列车长与乘务员，同一个车组"},{"a":"he","b":"yue","text":"列车长与乘警，同车组搭档"},{"a":"yue","b":"song","text":"同车组同事，都是跑车的"}],"deathReport":{"time":"约 21:30–23:15（现场难以精确判断）","cause":"后脑遭钝器重击，颅骨凹陷","scene":"23:35乘警令乘务员宋小河用备用钥匙开门，尹正衡侧卧在03号下铺，窗帘拉死，屋里闷热。","loc":"cabin","notes":["后脑一处钝器伤，血迹已发黑","小桌上的茶已凉，面上结了一层膜","室内温度计显示33度，尸体体表却发凉"]},"publicFacts":["K2146次12月7日19:40从北陵发车。8车软卧，6车餐车，1车行李车，9车为列车长办公室。","尹正衡住8车03号，买下全部四个铺位，死于后脑钝器重击。门自动落锁，列车长和乘务员各有一把备用钥匙。","23:30起死者手机响个不停，23:35乘警令乘务员宋小河开门，发现尸体。","柳河堡站原定停2分钟，因除雪车被延长到11分钟（21:52–22:03），只开3车、8车两个门。22:41列车在鹰嘴岭停下，此后无人能上下车。","23:40随车医生胥岚初步检视，判断“死亡约在一小时之内”，没有法医复核。","相关八人：列车长、乘警、乘务员、商人、医生、退休教师、学生，以及柳河堡补票上车的旅客。行李车有只无主黑箱。"],"timeline":[{"t":"19:40","text":"K2146次从北陵发车。"},{"t":"21:52","text":"到柳河堡站，延长停车，22:03开车。"},{"t":"22:41","text":"在鹰嘴岭因积雪停车，此后无人能离开。"},{"t":"23:35","text":"乘警令乘务员开门，发现尹正衡遇害。"},{"t":"23:40","text":"医生胥岚检视，称死者“不到一小时”。"},{"t":"23:50","text":"乘警封锁全车，列车长请你介入。"},{"t":"00:20","text":"调度通报：救援最早凌晨4点到。"}],"budget":{"search":12,"ask":28},"locations":[{"id":"cabin","name":"8车软卧03号包厢","scene":"cabin","desc":"软卧03号包厢，四个铺位只住一人。窗帘拉死，闷热，门一合就落锁。","clues":[{"id":"c_cab1","title":"下铺的尹正衡","text":"尹侧卧在下铺，后脑凹陷，血已发黑。小桌上的茶凉透，面上结了一层膜。"},{"id":"c_cab2","title":"暖气阀与温度计","text":"暖气阀拧到“5”，手轮缠着纸巾，温度计33度。门外挂着“请勿打扰”牌，背面印“8车乘”。"},{"id":"c_cab3","title":"门后的手杖","text":"门后挂着黑檀手杖，铜头接缝里有暗红干渍，还卡着一根二十厘米的黑发。"},{"id":"c_cab4","title":"门缝里的纸条","text":"烟盒纸条：“尹总：明早到澜城前不给准话，您那几笔账我就摆到桌面上。——卞 22:30”"}]},{"id":"guest","name":"8车乘务员室与走廊","scene":"guestroom","desc":"8车一头的乘务员室，墙上钉着巡视表和供暖表。走廊尽头是连接处。","clues":[{"id":"c_gst1","title":"夜间巡视记录","text":"宋小河的巡视表：21:30、23:00两栏是蓝圆珠笔，22:00、22:30两栏是黑签字笔，字更工整。22:30写“03铺：应，无需服务”。"},{"id":"c_gst2","title":"供暖检查表","text":"“21:30 软卧全车阀门均在2档，签：宋”。规定：夜间限2档，乘客调高须劝回。22:00后无记录。"},{"id":"c_gst3","title":"连接处的手套","text":"8车靠9车一端的垃圾桶最上面，有一副S号蓝色丁腈手套，外面沾发黑血迹，无酸味，里侧粘两根黑发。"},{"id":"c_gst4","title":"零食账本","text":"账本：“22:05–22:50 三号车厢：方便面×6，火腿肠×8，矿泉水×4”。末页小字：“岳哥火腿肠×2，免”。"},{"id":"c_gst5","title":"用品借出簿","text":"借出簿一行：“21:48 请勿打扰牌×1 08-06 未还”。其后再无新记录。"}]},{"id":"dining","name":"6车餐车","scene":"dining","desc":"摇晃的餐车，吧台后挂着订餐单。停车后窗外只剩风雪。","clues":[{"id":"c_din1","title":"没动过的面","text":"订餐单：“21:42 08-03 尹 牛肉面 22:10送，要热的”。小票背面：“22:10敲三下无应，牌挂门把，放过道折椅。22:41收回，未动。”"},{"id":"c_din2","title":"摔碎的搪瓷杯","text":"吧台记事板：“21:15–21:22 软卧老太太与08-03客人争执，杯摔了。”下一行：“22:05–22:25 08-04 白酒二两，一人。”"},{"id":"c_din3","title":"押着的学生证","text":"小票：“22:20 啤酒×4，现金不足，押学生证一张：甘子川”。背面：“人没来赎。”"}]},{"id":"engine","name":"机车司机室","scene":"engine","desc":"机车头司机室，仪表绿光映着窗外一片白。门边挂着记录本。","clues":[{"id":"c_eng1","title":"运行监控记录","text":"“21:52:10 速度0（柳河堡）；22:03:25 起动；22:41:50 速度0（鹰嘴岭，积雪停）”。批注：“柳河堡延长停车至22:03。”"},{"id":"c_eng2","title":"调度命令抄件","text":"抄件：“令K2146次：柳河堡延长停车，22:03开。21:30发，列车长贺怀山21:31签收。21:40广播。”"},{"id":"c_eng3","title":"副司机的手记","text":"“21:54 列车长下车与值班员对表，同往小屋；21:59 有人拎黑箱疾跑上8车；22:01 列车长从小屋跑回；22:35 列车长来问道岔；22:41起一直在机车室，23:10离开。”"}]},{"id":"hall","name":"9车列车长办公室","scene":"hall","desc":"列车长办公室，也是临时乘警席。桌上摊着旅客名册。","clues":[{"id":"c_hal1","title":"公文包里的信封","text":"信封写“致 戚远同志家属 收 · 澜城市金桥路27号3单元402”。内有九年前行车日志复印件，“22:03开”被划掉，旁注“实按21:58发出，尹（处）令”。便笺：“原件我留了九年。命令是我下的，这个人不该背。”"},{"id":"c_hal2","title":"实名制旅客名册","text":"08-02 盛云芳，68；08-03 尹正衡（四铺全买）；08-04 卞金城，48；08-06 胥岚，44，澜城市金桥路27号3单元402，医生；7车11号 甘子川，20，学生。"},{"id":"c_hal3","title":"补票存根","text":"“柳河堡 21:59 上 → 澜城 硬座 补票 蔺野 · 22:12 收，贺”。下压乘警值勤本：“22:14 行李车：无主黑色硬箱，内有无线电设备，已封。”后面被划掉一行。"},{"id":"c_hal4","title":"广播记录簿","text":"只有两条：“21:40 柳河堡停约十一分钟，宋”；“22:41 停车，机车来话：广播线因雪压断，暂停使用，贺”。"}]},{"id":"cellar","name":"1车行李车","scene":"cellar","desc":"紧挨机车的行李车，货架上堆满麻袋和纸箱。","clues":[{"id":"c_cel1","title":"相机里的站台","text":"封条下的黑箱里有台相机。第214张，21:58:12：前景红围巾老太太，远处风衣男人抽烟，小卖部窗口有个连帽衫。背景8车03号窗，窗帘正被一只手从里面拉上，窗里有盘发人影。"},{"id":"c_cel2","title":"监听笔记与接收机","text":"箱里有台调度频率接收机。笔记：“12/7 K2146 柳河堡停11分，想拍站台灯。21:52到，21:59抢上8车，补票。”存储卡里有调度员录音：“柳河堡延长至22点03分开。”"},{"id":"c_cel3","title":"贝司琴箱与通知","text":"贴满贴纸的琴箱，行李牌“甘子川 7车11号”。夹层里有张揉过的《关于终止“正衡寒门学子奖学金”资助的通知》，页边写着“凭什么”。"}]}],"suspects":[{"id":"he","name":"贺怀山","role":"K2146次列车长","age":57,"look":{"skin":"tan","hair":"short","hairColor":"grey","glasses":"none","beard":"none","outfit":"uniform","acc":"badge","mood":"tired"},"bio":"列车长，干了三十二年，这是退休前最后一趟车。他说21:31签收调度命令，22:41停车后一直在机车室。","demeanor":"官话慢条斯理，爱说“按章程”，心虚时摘帽擦汗。","topics":[{"id":"t_hut","q":"小屋里那七分钟？","needs":["clue:c_eng3"],"a":"对表是真的。我借值班员的电话给老伴打了一个，没人接。九年前也是这个钟点，我手脚发凉。听见要开车才跑回去。"},{"id":"t_stop","q":"柳河堡为何多停？","a":"21:30调度发令，要过除雪车，延长到22:03。我21:31签收，让小宋21:40广播。"},{"id":"t_know","q":"你认识死者吗？","lie":true,"a":"不认识。软卧旅客那么多，我一个个记不住，头一回见这位尹先生。你查名册去，我跟他没有交情。","truth":"认识。九年前柳河堡那夜，我是车长，改过的报告上有我的签字。21:46他在走廊说明天去纪委，叫我自己想想。我怕了。"},{"id":"t_talk","q":"他对你说了什么？","needs":["clue:c_hal1"],"a":"他说原件留着，明天交出去，该担的他担，还说“老贺，你那份签字也该有个说法了”。我杀人？我没那胆。"},{"id":"t_engine","q":"停车后你在哪？","a":"22:35我去机车室问道岔，22:41停车后一直在那儿，到23:10才回来。司机和副司机都能作证。"},{"id":"t_doc","q":"谁给遗体做检视？","a":"23:40随车的胥岚医生。她一进门就说死了不到一个钟头，口气不容人多问。我们外行，只能信。"},{"id":"t_horn","q":"夜里还广播过吗？","needs":["clue:c_hal4"],"a":"21:40之后就没有了。22:41机车来话，线被雪压断，喇叭哑了，我试过，没响。"}],"confronts":[{"clue":"c_hal1","breaks":"t_know","a":"他手指发抖，翻不开那页复印件。半晌低声说：“原件……他真留着。我签字那天，他就站在旁边。我欠他一个说法。”"},{"clue":"c_gst1","a":"“22:00、22:30换了黑笔，别的栏都不是。”他叹气，“这孩子回头我得说他。可他不是杀人的料。”"},{"clue":"c_eng3","a":"他把手记递回来，沉默了一会儿：“七分钟……我自己都怕算。信不信由你，我只能说我在小屋里。”"}],"fallback":"这个我不清楚，你问点章程上有的。"},{"id":"yue","name":"岳峥","role":"随车乘警","age":35,"look":{"skin":"light","hair":"short","hairColor":"black","glasses":"none","beard":"stubble","outfit":"uniform","acc":"badge","mood":"stern"},"bio":"随车乘警，退伍转业。23:35令人开门，23:50封锁全车。他说22点后整晚都在各车厢巡视。","demeanor":"干脆，爱说“报告”，问到私事就顶一句“这跟案子有关系吗”。","topics":[{"id":"t_role","q":"你负责什么？","a":"报告，全列车的治安都归我管。命案我只能控制现场、上报，剩下的得靠你这样的专业人来办。"},{"id":"t_round","q":"22点后你在哪？","lie":true,"a":"报告，22点到23点我在乘警室和各车厢巡视，没离开过。你问沿途乘务员，都见过我。","truth":"我在3车。22:15到22:40，在小宋那儿吃火腿肠，靠着座椅打了个盹。传出去，我这身衣服就穿不成了。"},{"id":"t_touch","q":"你碰过遗体吗？","a":"23:35我摸了他的颈和手腕：凉，手腕已发硬，可屋里热得像蒸笼，我纳闷。胥医生说不到一小时，我就没吭声。"},{"id":"t_outsider","q":"车上有外人吗？","lie":true,"a":"报告，没有。上车的人我都对过名册，每一个都对得上号，没有来路不明的外人，请放心。","truth":"有。柳河堡补上来一个背黑箱的。我22:14在行李车见到箱子，22:20在3车遇见他，翻了一遍没发现违禁，就放了。怕担责，没说。"},{"id":"t_stop","q":"停车那十一分钟呢？","a":"报告，我守在3车门口，门开着，不能没人。8车那头是小宋守的，我没过去，也没离岗。"},{"id":"t_song","q":"你和小宋很熟？","needs":["clue:c_gst4"],"a":"都是跑车的，混熟了。他卖点东西我不管，这算人情，不算违纪。你别拿这个说我整晚不在岗。"}],"confronts":[{"clue":"c_gst4","breaks":"t_round","a":"他盯着“岳哥火腿肠×2，免”，冷着脸承认：“报告，我撒谎了。22:15到22:40我在3车。该巡的我都巡过。”"},{"clue":"c_hal3","breaks":"t_outsider","a":"“我划的。箱子是他的，我知道。怕你们说我放了个来路不明的人。我错了，但他没动过尹正衡。”"},{"clue":"c_cel1","a":"“21:58？这个钟点我在3车。窗帘是有人在里头拉的……”他没说下去，眉头拧得更紧。"},{"clue":"c_gst1","a":"“小宋提前写的？难怪22:50他回来，我在，他慌里慌张地说‘03号我查过了’。”"}],"fallback":"报告，这个我不清楚，你要问案子本身。"},{"id":"song","name":"宋小河","role":"8车乘务员","age":26,"look":{"skin":"light","hair":"messy","hairColor":"black","glasses":"none","beard":"none","outfit":"uniform","mood":"worried"},"bio":"8车乘务员，入行三年。他说22:30敲过03号门，听见里面说“不用了”，23:35是他开的门。","demeanor":"年轻，语速快，紧张时舌头打结，爱说“我真没有”。","topics":[{"id":"t_last","q":"最后见他是何时？","a":"21:45我送热水，他在写东西，说“晚上别敲门”。21:53他在车门口看了一分钟站台灯，念叨“还是那盏灯”。"},{"id":"t_check","q":"22:30查铺怎么样？","lie":true,"a":"我22:30敲了03号门，他说“不用了”，声音挺正常。表上都写着呢，我从来不糊弄。","truth":"我没敲。那两行是我21:50提前写好的。22:05到22:50我一直在3车卖零食，给妈妈挣药钱。我撒了谎，对不起。"},{"id":"t_sign","q":"请勿打扰牌是谁挂的？","lie":true,"a":"我21:45送水时门上没牌。22:50回来才看见，我以为是客人自己挂的。谁挂的我真不知道。","truth":"牌子是我的。21:48胥医生来借，说睡不着想挂自己铺门口。22:50我认出它挂在03号门上，不敢说，一说就得认我不在岗。"},{"id":"t_chat","q":"她还问过你什么？","needs":["ask:song.t_sign"],"a":"她问03号住谁、是不是一个人。我说四个铺他全包了，不让敲门。她点头说“那就好”。我还觉得医生心细。"},{"id":"t_heat","q":"暖气阀是怎么回事？","needs":["clue:c_gst2"],"a":"21:30我逐间查过，软卧全在2档，绝对没错。真调到5档，整节车厢的人都能热醒。"},{"id":"t_trash","q":"连接处的垃圾桶呢？","needs":["clue:c_gst3"],"a":"我21:30倒的，之后没碰过。那副蓝手套不是我们的，我们用白线手套。那是医院用的吧。"},{"id":"t_doctor","q":"医生那晚做了什么？","a":"22:50我回来，胥医生正蹲在7、8车连接处照顾醉倒的学生，一直没离开。岳哥后来也来看过。我还夸她心善。"},{"id":"t_platform","q":"停车时你在哪？","a":"21:52到22:03我在8车门口举灯守着。老太太遛弯，大叔抽烟，快22点有个背大箱子的抢上车。"}],"confronts":[{"clue":"c_gst1","breaks":"t_check","a":"他嘴唇动了好几下：“……是我提前写的，怕列车长扣钱。22:30我真没敲门，也没听见他说话。”"},{"clue":"c_gst4","breaks":"t_check","a":"他一把按住账本：“别交上去，我妈靠这个买药！22:05到22:50我一直在3车，没去过03号，我发誓。”"},{"clue":"c_gst5","breaks":"t_sign","a":"他肩膀塌下去：“是我借的……我怕说了，人家以为我跟她一伙。我真不知道她拿去干什么。”"},{"clue":"c_cab2","a":"“5档？我21:30查的时候是2档。谁拧的？如果是别人拧的，那一定是21:30之后。”"}],"fallback":"这个我真不知道，我就是个乘务员。"},{"id":"bian","name":"卞金城","role":"机械厂老板","age":48,"look":{"skin":"tan","hair":"slick","hairColor":"black","glasses":"none","beard":"none","outfit":"coat","acc":"necklace","mood":"sly"},"bio":"北陵矿机厂老板，和死者合伙六年。当晚在03号包厢与死者争吵，他说21:25吵完就回铺睡觉，直到被叫起。","demeanor":"嗓门大，爱拍桌子，口头禅“我跟你说”，被抓包就泄气。","topics":[{"id":"t_role","q":"你和死者的关系？","a":"合伙六年，他出钱我出力。他一句“撤资”，我连后路都没有。我跟你说，最靠不住的就是有钱的合伙人！"},{"id":"t_last","q":"最后一次见他？","lie":true,"a":"21:25吵了一架，我气得回铺睡觉，之后再没见过他。我跟你说，我睡得可踏实了，一觉到天亮。","truth":"22:30我又去了。敲门没人应，就把条子塞进门缝。我以为他故意不理我，骂了一句就走。怕你们说是我干的。"},{"id":"t_where","q":"21:50后你在哪？","lie":true,"a":"我吵完就回自己铺位躺着，一步都没出来过。要是有人说见过我，那一定是认错人了，我跟你说。","truth":"21:52到22:02我在站台抽烟。上车后去餐车喝闷酒，到22:25才回铺。一个人，没人证明。"},{"id":"t_deal","q":"你们为什么吵？","a":"他要撤资，我欠银行三百万，他一撤我就垮。我求他拖到年后，他说没得谈。急归急，杀人我不敢，我连只鸡都没杀过。"},{"id":"t_threat","q":"纸条上的账是什么？","needs":["clue:c_cab4"],"a":"他这些年通过正衡物流给铁路系统的人送好处，账我有复印件。我就想吓唬他缓一缓。真公开了我也完蛋。"},{"id":"t_box","q":"你看见什么了吗？","a":"22:30我到03号门口，把手上挂着牌子，折椅上一托盘面，凉透了。我还嘀咕，这老家伙架子真大。"}],"confronts":[{"clue":"c_cab4","breaks":"t_last","a":"他脸涨成猪肝色：“是我写的，我塞的。我就想吓他。他死了，我三百万的债砸手里了。他死的时候我不在！”"},{"clue":"c_cel1","breaks":"t_where","a":"他盯着远处抽烟的身影，苦笑：“这个胖子是我。21:58我还在站台抽烟，窗帘怎么拉上的，我没看见。”"},{"clue":"c_din1","a":"他拍桌又泄了气：“22:10就没人应门？那我22:30来的时候他早就……我还以为他故意不理我！”"}],"fallback":"我跟你说，这个我真不知道，别往我身上泼脏水。"},{"id":"xu","name":"胥岚","role":"急诊科医生","age":44,"look":{"skin":"light","hair":"bun","hairColor":"black","glasses":"none","beard":"none","outfit":"coat","acc":"stethoscope","mood":"neutral"},"bio":"澜城二院急诊医生，回家过冬。23:40她检视遗体。她说整晚在08-06看书，22:45起照顾醉倒的学生。","demeanor":"语速平稳，爱说“从医学上讲”，被逼到点上反而更冷静。","topics":[{"id":"t_tod","q":"死亡时间怎么判断？","lie":true,"a":"从医学上讲，体温偏高，尸僵只在下颌和颈部，屋里又有三十三度。死亡不到一小时，大致在22:45到23:15。","truth":"我故意往晚了说。暖气是我拧到最大的，热环境里体温掉得慢。真正的时间是21:57前后，是我动的手。"},{"id":"t_where","q":"21:50到22:45你在哪？","lie":true,"a":"08-06，一直在铺上看书，没出过门。22:45听到广播找医生才出去，在连接处发现醉倒的学生，陪到23:25。","truth":"21:55我进了03号包厢，21:57用他的手杖打了他。之后拧暖气、拉窗帘、挂牌子，手套扔进车尾的桶，回了08-06。"},{"id":"t_student","q":"那个学生怎么样？","a":"喝多了，吐了一地，体温偏低。我给他清理、盖外套。小宋22:50、岳乘警23:00都来过，我22:48到23:25没离开。"},{"id":"t_know","q":"你认识死者吗？","lie":true,"a":"不认识。餐车里见过一眼，穿得讲究，看着像个有钱人。我这种做医生的，对富人没有什么特别的印象。","truth":"认识。九年前的今天，柳河堡站，我弟弟戚远被他下令提前开动的列车卷倒。他把责任推给我弟弟，我母亲到死没等到说法。"},{"id":"t_cane","q":"这手杖和长发呢？","needs":["clue:c_cab3"],"a":"手杖我没碰过。头发？车上留长发的女人多了，你一根一根查。熬夜当班的，谁不掉几根。"},{"id":"t_gloves","q":"手套是你的吗？","needs":["clue:c_gst3"],"a":"我给学生清理呕吐物时戴过，用完随手扔了，哪个桶记不清。暗红的……他吐的东西里带血也不稀奇。"},{"id":"t_bcast","q":"谁通知你有人不舒服？","needs":["ask:gan.t_doc"],"lie":true,"a":"广播。22:45前后车上广播问有没有医生，我就出去了。当时不止我一个人听到，你可以去问。","truth":"没有广播。22:20我在门缝里看见他拎着四瓶酒进连接处，知道他撑不住。22:48我去“发现”他，是要所有人看见我整晚在照顾人。"},{"id":"t_heat","q":"暖气怎么回事？","needs":["clue:c_cab2"],"a":"暖气阀乘客自己就能调，谁都能拧。屋里热只会让尸体看着更新鲜，医学上有这种误差，所以我才只给个大概。"}],"confronts":[{"clue":"c_din1","breaks":"t_tod","a":"她看着那碗坨了的面，停了停：“22:10没人应门，饭没动。……我的判断，可能有误。”声音平稳，指尖却按住了桌沿。"},{"clue":"c_cel1","breaks":"t_where","crack":true,"a":"她盯着窗里盘发的剪影，很久没说话。“那个高度，是我。”她轻轻吐气，“窗帘是我拉的。你们终于找到了这张照片。”"},{"clue":"c_hal1","breaks":"t_know","crack":true,"a":"她看着信封上的地址，那是她自己的家。许久才问：“他留了九年？他是要去自首？……他怎么敢，在我面前死……”声音戛然而止。"},{"clue":"c_hal2","breaks":"t_know","a":"她垂眼看着自己的地址：“金桥路27号3单元402。我弟弟住在那里，直到九年前的十二月七日。”"},{"clue":"c_hal4","breaks":"t_bcast","a":"她看着“广播线因雪压断”那一行，停了很久：“……我记错了，也许是有人在走廊里喊。”这回没再补医学说法。"}],"fallback":"从医学上讲，这个跟我没有关系。"},{"id":"sheng","name":"盛云芳","role":"退休小学教师","age":68,"look":{"skin":"fair","hair":"bun","hairColor":"white","glasses":"round","beard":"none","outfit":"coat","acc":"scarf","mood":"stern"},"bio":"退休语文老师，矮个，围红围巾。她说去澜城看孙女，停车时在站台散步，之后回铺睡了。","demeanor":"条理分明，爱纠正别人用词，动了气就连名带姓叫人。","topics":[{"id":"t_know","q":"你认识死者吗？","lie":true,"a":"不认识。我一个退休老太太，哪认识什么有钱人？车上遇见，连点头的交情都没有，你们不必往我这儿绕。","truth":"认识，在报纸上。九年前我的学生戚远死在柳河堡站，报纸登过尹正衡的照片。今晚餐车我认出他，骂了一句，摔了杯子。"},{"id":"t_platform","q":"停车时你在做什么？","a":"我在站台走了一圈，21:53到22:02，围巾是红的，不难认。站台灯很旧，看得人心里发酸。"},{"id":"t_window","q":"你看到他的窗了吗？","needs":["clue:c_cel1"],"a":"看见了。九点五十八分前后，03号窗帘被人从里面拉上。是个盘着头发的人影，比我高——我个子矮，从下往上看谁都高。"},{"id":"t_after","q":"22点后你在哪？","a":"回08-02了，开着小灯，翻戚远小时候的作文本。他写过“长大我想当铁路工人”。我坐着哭，没出声。"},{"id":"t_cup","q":"你在餐车说了什么？","needs":["clue:c_din2"],"a":"我说“你也配坐这趟车”。他看了我一眼，什么也没说。那眼神我忘不掉，不是心虚，像个早就认了罪的人。"},{"id":"t_wall","q":"隔壁有什么动静？","a":"没有。倒是后半夜靠03号的那面墙烫手，我把被子都踢了。想找乘务员，转念一想，他的事我不乐意管。"}],"confronts":[{"clue":"c_din2","breaks":"t_know","a":"她捏着围巾角，沉默良久：“是我骂的，杯子也是我摔的。我教了戚远六年，我去过他的葬礼，我知道那份报告是怎么写的。”"},{"clue":"c_cel1","a":"她眯眼指着红围巾的小个子：“这个矮老太婆是我，21:58就站这儿。窗帘是人从里面拉的，不是我，我够不着。”"},{"clue":"c_hal1","a":"她读着便笺，手抖：“‘这个人不该背’……他九年前为什么不说？早说，戚远的妈妈也不会……”"}],"fallback":"这个我不清楚，你问点我知道的。"},{"id":"gan","name":"甘子川","role":"音乐学院学生","age":20,"look":{"skin":"light","hair":"messy","hairColor":"black","glasses":"none","beard":"none","outfit":"hoodie","acc":"headset","mood":"tired"},"bio":"音乐学院大三学生，坐7车硬卧，背着贝司琴箱。他说22点后回铺睡觉，一觉睡到被叫醒。","demeanor":"年轻嘴硬，爱说“反正”“无所谓”，心虚时抠手指。","topics":[{"id":"t_night","q":"22点后你在哪？","lie":true,"a":"回铺睡觉了啊，一晚上没出过车厢。吃完泡面就躺下，什么都不知道，也没听见什么，无所谓。","truth":"我22:20买了四瓶啤酒，躲在7、8车连接处喝光了。22:45吐了一地，醒来胥医生蹲在旁边帮我收拾，陪了快一个小时。"},{"id":"t_know","q":"你认识死者吗？","lie":true,"a":"不认识啊。反正我是坐硬卧的穷学生，车上遇到的人我一个都不认识，跟软卧那边没关系，无所谓。","truth":"认识，他是“正衡寒门学子奖学金”的出资人。上周学校通知我，奖学金终止了。我来澜城找他理论，没想到他死了。"},{"id":"t_hear","q":"21:24走廊里听到什么？","a":"我去厕所路过03号，听见里面有人吼：“你要是不答应，我就公开！”声音很凶，另一个老头没吭声。"},{"id":"t_doc","q":"医生是怎么发现你的？","needs":["ask:gan.t_night"],"a":"我迷迷糊糊的，她就蹲在我边上，说“广播里说有人不舒服”。她帮我擦，还给我盖了外套，人挺好的。"},{"id":"t_door","q":"拎酒回来碰到谁？","needs":["ask:gan.t_night","clue:c_cel1"],"a":"22:20我拎酒到连接处，隔着玻璃看见8车走廊。有间包厢门开着条缝，一个盘头发的女人在看书，抬头看了我一眼。"},{"id":"t_platform","q":"停车时你在做什么？","a":"我在站台买泡面，21:52到22:00。看见抽烟的大叔、红围巾老太太，还有个拿相机的。没什么特别的。"}],"confronts":[{"clue":"c_din3","breaks":"t_night","a":"他抠着手指：“行，我喝了，四瓶，一个人。我心情差。胥医生一直陪着我，她可以作证，我没杀人。”"},{"clue":"c_cel3","breaks":"t_know","a":"他脸色一变，伸手想夺：“这是我的！……行，我认识。奖学金说停就停。我来找他，不是来杀他。”"},{"clue":"c_cel1","a":"他指着小卖部窗口的小人影：“这是我，在买泡面。21:58我在站台另一头，没看到这边。”"}],"fallback":"反正这个我不知道，无所谓。"},{"id":"lin","name":"蔺野","role":"无票补乘旅客","age":32,"look":{"skin":"tan","hair":"cap","hairColor":"black","glasses":"none","beard":"stubble","outfit":"parka","acc":"headset","mood":"worried"},"bio":"在柳河堡补票上车的年轻人，坐3车硬座。行李车里有只无主黑箱，他说那箱子与自己无关。","demeanor":"说话飞快含糊，爱说“就是拍着玩的”，问到箱子就岔开。","topics":[{"id":"t_case","q":"黑色硬箱是你的？","lie":true,"a":"不是不是，我就一个背包，没见过什么箱子。肯定是别人放的，别算到我头上，就是拍着玩的。","truth":"是我的。里面是相机和一台调度频率接收机。我是铁路迷，爱拍车，也爱听调度台。监听不合规，我怕被没收、被罚。"},{"id":"t_board","q":"你在哪站上的车？","lie":true,"a":"北陵上的，坐了一晚上了。补票是因为票作废了，列车长能证明。我就是个普通乘客，真的。","truth":"我在柳河堡上的。听调度说这站停十一分钟，下去拍站台灯，21:59抢上8车补的票。怕追问箱子，才说北陵。"},{"id":"t_saw","q":"你上车时看到什么？","needs":["clue:c_cel1"],"a":"我进8车往车尾走，到03号门口，见一个灰大衣、盘发的女人从里面出来，挂上“请勿打扰”牌，带上门往车尾去了。"},{"id":"t_height","q":"她多高？","needs":["ask:lin.t_saw"],"a":"比我矮一点，我一米七五，她大概一米七。走路很稳，不慌，我还以为是乘务员。她没回头，我没看清脸。"},{"id":"t_scan","q":"接收机里有什么？","needs":["clue:c_cel2"],"a":"21:31我听到调度令，柳河堡延长到22点03分开。所以一到站我就下去拍站台灯，拍了十几张。"},{"id":"t_yue","q":"乘警盘问过你吗？","a":"22:20在3车，翻了我的背包，没翻到别的就放了。他后来叫我别乱说。我真的什么也没干。"}],"confronts":[{"clue":"c_cel2","breaks":"t_case","a":"他盯着自己的笔记本：“是我的。我就想拍张站台灯。监听调度台违法我知道，所以不敢认。跟命案没关系。”"},{"clue":"c_hal3","breaks":"t_board","a":"他看着“柳河堡 21:59”，苦笑：“行，我在柳河堡上的。说北陵，是怕你们顺藤摸瓜查到我的箱子。”"},{"clue":"c_cel1","a":"他缩了脖子：“这是我拍的，21:58那张也是。我只拍站台，窗里有没有人没留意，现在才发现拍到了。”"}],"fallback":"就是拍着玩的，这个我不清楚。"}],"solution":{"culprit":"xu","method":{"q":"凶手如何把案发时间推迟近一小时？","options":["22:30前后借谈事进屋动手，再用门缝纸条和预填的巡视记录钉住时间。","趁柳河堡长停的空档动手，再靠暖气、窗帘和旁人无意的记录推后时间。","停车后用备用钥匙进屋行凶，让送面托盘留在门外，造出他活着的假象。","趁停车从站台混上车的外来者潜入动手，再借他人留下的记录拖后时间。"],"correct":1},"motive":{"q":"凶手为什么杀人？","options":["死者握有合伙人行贿的账本，对方背着巨额债务，为保住企业灭口。","死者明天要揭发九年前被改写的事故报告，当年签字人为保住待遇下手。","死者终止了一名受资助者的奖学金，对方理论时争执升级，一时冲动报复。","凶手的亲人死于九年前被改写的事故，她为其复仇，却不知死者要去自首。"],"correct":3},"keyClues":["c_cab2","c_din1","c_eng1","c_cel1","c_hal1","c_hal2"],"truth":["凶手是随车医生胥岚。九年前柳河堡站，尹正衡下令提前开车，站务员戚远被列车带倒身亡，报告却把责任推给戚远。胥岚是戚远的姐姐。","第一个结论：尹死在22:30后，是卞金城干的。可22:10送面无人应门，巡视表22:00、22:30两栏是预填的，卞22:05到22:25在餐车喝酒。","第二个结论：蔺野21:59抢上8车最可疑。可他21:58还在站台拍照，照片里03号窗帘正被人从屋里拉上。手杖和手套上是黑色长发，贺怀山是灰短发。","手法藏在无心之举里：宋小河借出的牌子，预填的巡视表，成了“22:30还活着”的假证；醉倒的甘子川成了她的不在场证明。广播线22:41已断，“听广播”是谎。","21:55她进03号，21:57杖击其后脑，拧暖气、拉窗帘、挂牌子，23:40说“不到一小时”。尹带着原始日志，明天要向戚远家人自首。她杀的，是带真相来的人。"]}},{"id":"troupe","title":"最后一场","tagline":"解散前的告别演出，灯灭三分钟，再亮时台柱已经没有了呼吸。","difficulty":3,"cover":"coverTheater","tone":"purple","brief":"暮光剧社在纺机剧场演最后一场《雨夜归人》，演完就解散。下半场忽然断电三分钟，灯亮后团长方知远没有上场，随后被发现死在后台化妆间，案发时间成谜。警方听到录音里一声巨响，便断定他死在黑暗中。观众被扣在场内，刑警朋友深夜请你来，天亮前看清每个人真正的位置，别被表面的结论带偏。所有人都说，最可疑的是管灯的陈野。","victim":{"name":"方知远","desc":"暮光剧社团长、导演兼台柱，五十二岁。伏在后台化妆台前，左侧头部被重物击伤，脸上的底妆只涂了一半。","look":{"skin":"light","hair":"sidepart","hairColor":"grey","glasses":"none","beard":"stubble","outfit":"shirt","mood":"stern"}},"publicFacts":["《雨夜归人》19:30 开演，中场 20:35 到 20:55，下半场 20:55 开始。","方知远 21:00 前后在化妆间念完旁白，这是他最后一次被人听到。","21:12 到 21:15 供电中断三分钟，灯光师陈野称自己什么也没碰。唐婉清提灯在台上撑场。","21:25，乔小满与贺长根推开化妆间的门，发现尸体。","凶器是走廊道具桌上的黄铜烛台。录音里 21:13 有一声巨响，警方认为凶手趁停电行凶。","观众和剧社成员都被留在剧场内。"],"relations":{"xu":"剧社会计，管账十二年","chen":"剧社灯光音响师，管控台","su":"《雨夜归人》原作者，因署名与他闹僵","tang":"女主演，合作十二年的前恋人","he":"老舞美师傅，在剧社二十八年","jin":"出资八年的投资人，也是厂房业主","qiao":"新人演员，兼他的助手和叫场","jiang":"五年前被他赶走的老团员"},"links":[{"a":"qiao","b":"he","text":"两人一起推门发现了尸体"},{"a":"chen","b":"he","text":"同属幕后技术班底，常搭手"},{"a":"jin","b":"xu","text":"他每年都在她经手的账上签字"}],"deathReport":{"time":"约 20:55–21:20","cause":"左侧头部遭钝器重击，颅骨凹陷","scene":"21:25，乔小满与贺长根推开未锁的化妆间门，发现他伏在化妆台前，已无呼吸。","loc":"back","notes":["左侧头部一处凹陷伤，一击致命","伤口形状与走廊道具桌上的黄铜烛台相符","脸上底妆只涂了半边"]},"timeline":[{"t":"19:30","text":"《雨夜归人》开演。"},{"t":"20:55","text":"下半场开场，方知远在化妆间候场。"},{"t":"21:00","text":"方知远念完下半场开场旁白，话筒静音。"},{"t":"21:12","text":"供电中断，台上漆黑；唐婉清持提灯继续演出。"},{"t":"21:15","text":"灯光恢复。乔小满去叫方知远候场，无人应答。"},{"t":"21:25","text":"乔小满与贺长根发现方知远死亡。"},{"t":"21:32","text":"剧社报警，警方通知你。"}],"budget":{"search":12,"ask":26},"locations":[{"id":"stage","name":"舞台与控台","scene":"stage","desc":"黑盒剧场的小舞台和观众席后方的控台。台上还留着雨夜布景，台口放着一盏电池提灯。","clues":[{"id":"c_stage1","title":"后台监听录音","text":"监听放大后有两声：21:02:10 很轻的闷响；21:13:02 响亮的撞击，紧跟金属扣合声。其间无人声、无脚步。"},{"id":"c_stage2","title":"灯光台操作日志","text":"日志：Cue31 在 21:11:58，之后到 21:15:00 无新指令，21:15:00 灯光台“重新上线”。"},{"id":"c_stage3","title":"演出场记本","text":"场记本：“20:50 走廊防火门吸合（贺）”“21:12 停电”“21:15 来电，走廊门已关”。最后一行墨色较深。"}]},{"id":"back","name":"后台化妆间","scene":"backstage","desc":"走廊尽头方知远的单人化妆间。门外挂着“勿扰”牌，拉了警戒带，镜框一圈灯泡亮着。","clues":[{"id":"c_back1","title":"化妆间的尸体","text":"方知远趴在化妆台前，左侧头部凹陷，底妆只涂了半边，已干透。地上滚着沾血的黄铜烛台，原放在走廊道具桌上。"},{"id":"c_back2","title":"走廊尽头的防火门","text":"走廊的铁防火门关着，门框上的电磁吸座灯灭，线接“B 路调光回路”。闭门器铭牌：延时 60 秒。"},{"id":"c_back3","title":"方知远的手机","text":"20:30 发唐婉清：“演完来化妆间谈合同。”20:50 发“许会计”：“九点整，化妆间。只给你五分钟。”回：“好。”"}]},{"id":"cellar","name":"道具仓库与配电角","scene":"cellar","desc":"舞台下方的地下仓库，堆着旧布景和道具箱。一角是调光柜的配电角，电缆沿墙根通向舞台。","clues":[{"id":"c_cellar1","title":"电缆上的定时插座","text":"调光柜电缆中间串着一只很新的白色定时插座，程序栏：关 21:12，开 21:15，每日。外壳边缘还有没撕净的包装胶带。"},{"id":"c_cellar2","title":"仓库出入登记簿","text":"登记簿“进出必签”，今晚三行：19:58 许 取找零备用金；20:38 贺 取座钟箱；21:03 陈 取外租灯×2。"},{"id":"c_cellar3","title":"空的座钟木箱","text":"花梨木大箱里只剩泡沫衬垫，标签写“民国座钟 库存”。盘点表此栏被铅笔划过，注“待核”。箱底有张新的拍卖行名片。"}]},{"id":"hall","name":"前厅与观众席","scene":"hall","desc":"剧场入口的前厅和小观众席。柜台、海报，墙角挂着一台监控摄像头，观众被留在原位等待问话。","clues":[{"id":"c_hall1","title":"前厅监控回放","text":"20:52 金永昌出大门；20:57 许敏锁屏，拿灰开衫进侧门；21:07 她回来；21:08 金永昌回。"},{"id":"c_hall2","title":"保安亭值班记录","text":"值班本：“20:53 金总车内另有一男子（宏远置业·赵），21:07 离开。”“20:55–21:06 贺后门抽烟。”"},{"id":"c_hall3","title":"观众席F12座位","text":"F12 放着米色风衣和写满批注的剧本。邻座说这位女士下半场刚开始就走了，停电后好一阵才回来。"},{"id":"c_hall4","title":"停电时的观众视频","text":"观众手机拍到：停电三分钟里，唐婉清提着电池提灯站在台中央念台词，始终没有离开光圈。"}]},{"id":"study","name":"团长办公室","scene":"study","desc":"二楼不大的办公室，墙上贴满历年海报，办公桌上堆着文件和一台老式打印机。警方带你进来。","clues":[{"id":"c_study1","title":"审计函与银行流水","text":"文旅局通知：下周一进场审计。流水里红笔圈出十几笔转出，都进尾号 7316 的个人账户，共 38.6 万。"},{"id":"c_study2","title":"报销单与消防月检单","text":"报销单：“数显定时插座×2”，经办许敏，收款尾号 7316。消防检单：防火门吸座接 B 路，断电释放，延时 60 秒，审核许敏。"},{"id":"c_study3","title":"违约追偿函草稿","text":"打印机里卡着没发出的函：致唐婉清，未经同意与星河影视签约，追偿违约金 80 万元。落款方知远，日期今天。"},{"id":"c_study4","title":"被改过的署名页","text":"署名页复印件上，“编剧：苏孟”被划掉，改成“编剧：方知远（原作：苏孟）”。背面有半行涂掉的字：“你欠我的。”"}]},{"id":"dining","name":"后台休息室","scene":"dining","desc":"后台的休息室兼茶水间，一张长桌、几把折叠椅、一个电热水壶和半面墙的服装架。","clues":[{"id":"c_din1","title":"休息室出入白板","text":"白板：“乔 20:57 出（取充电器）／21:01 回”“唐 20:55 上场”“贺 20:50 出／21:05 回”。"},{"id":"c_din2","title":"沙发上的旧团服","text":"旧团服胸口绣“暮光”，后背贴着“晨星剧社”。口袋里的后台通行证盖着“20:48”，已过期一年。"},{"id":"c_din3","title":"垃圾桶里的便条","text":"揉皱的打印便条：“方导，请核对补贴专户流水，尤其是尾号 7316 的转入。别问我是谁。”旁边拿铁杯套上写着“小满”。"}]}],"suspects":[{"id":"chen","name":"陈野","role":"灯光音响师","age":34,"look":{"skin":"tan","hair":"messy","hairColor":"black","glasses":"none","beard":"stubble","outfit":"hoodie","acc":"headset","mood":"worried"},"bio":"剧社灯光兼音控，一个人守着控台。停电发生在他的调光台上，所有人都先怀疑他。他说整场没离开过控台。","demeanor":"语速快、爱说行话，嘴硬，一急就挠头发，句尾带“我跟你讲”。","topics":[{"id":"t_role","q":"你在剧社做什么？","a":"灯、音一把抓，上百个 cue 全在我手里。方导说我这台子是剧社的心脏，结果最后一场心脏停了三分钟。"},{"id":"t_booth","q":"下半场你离开过控台吗？","lie":true,"a":"没有，从头到尾没挪窝，每个 cue 都是我手按的。停电时我吓傻了，什么键都没碰，我跟你讲。","truth":"离开过，21:03 到 21:09。我跑下仓库拿两盏外租 LED 灯，私下把备用灯租给婚庆公司，怕方导知道。"},{"id":"t_blackout","q":"停电是怎么回事？","a":"调光柜 21:12 整个没电，不是我这边断的。警察一听就认定是我。我跟你讲，我是被冤枉的。"},{"id":"t_auto","q":"灯为什么自己亮了？","needs":["clue:c_stage2"],"a":"跳闸得有人去合闸，可它 21:15 整自己上线了。这是有人给供电设了时间，没人愿意听我讲。"},{"id":"t_rack","q":"仓库里的电缆？","needs":["clue:c_cellar1"],"a":"下午五点我巡检，电缆还是直插墙的。21:03 去时中间多了个白插座，我以为是防浪涌插排，没细看。"},{"id":"t_who","q":"你觉得谁有理由害他？","a":"多了去了。苏孟为署名吵了半年，金总想拆楼，唐姐签了影视约被追偿。我就是个打灯的，哪知道。"},{"id":"t_door","q":"走廊那扇防火门？","needs":["clue:c_back2"],"a":"磁吸座接在我调光柜的备用回路上，断电就释放，一分钟后闭门器拉上。开演后贺老总把它吸住搬景。"}],"confronts":[{"clue":"c_cellar2","breaks":"t_booth","a":"他挠了挠头发。“……我签了字还撒谎。好吧，我去仓库拿租出去的灯。千万别告诉方导——哦，他已经……”"},{"clue":"c_stage2","a":"“对，这就是我说的！”他一下来了精神，“没有指令，供电自己归零又自己回来，灯台没错。”"},{"clue":"c_stage1","a":"他听了三遍。“一声轻，一声重。重的那声我在控台根本没听见，监听我早推下去了。这是两回事啊。”"},{"clue":"c_cellar1","a":"他蹲在屏幕前倒抽一口气：“就是它！我下去就觉得别扭……要是我当时拔了，哪来这三分钟。”"},{"clue":"c_back2","a":"“它和我的柜子一路电。”他吸了口气，“那一声‘哐’，要在黑里听，谁都当成有人倒下……”"},{"clue":"c_stage3","a":"他点着那行字：“20:50 门吸上，21:15 来电，门是关的。这中间……门自己关的？”"}],"fallback":"这个我真不清楚，我就是个打灯的，别拿我当替罪羊。"},{"id":"su","name":"苏孟","role":"编剧","age":45,"look":{"skin":"light","hair":"long","hairColor":"black","glasses":"round","beard":"none","outfit":"coat","acc":"scarf","mood":"sad"},"bio":"《雨夜归人》原作者，因署名与方知远闹僵，被禁入后台。她说下半场一直坐在观众席 F12。","demeanor":"说话慢、爱引台词，感情一上来就停顿，眼圈发红。","topics":[{"id":"t_role","q":"你和剧社是什么关系？","a":"这个本子是我十年前写的，每句台词我都背得出。剧社要散了，我只想在最后一场把话说清楚。"},{"id":"t_feud","q":"你们为署名吵过吗？","a":"吵，从去年吵到今年。他把“编剧”改成“原作”，说版权归剧社。我恨过他，可我没想过他会死。"},{"id":"t_seat","q":"下半场你在哪？","lie":true,"a":"就在 F12，从头坐到谢幕，一步没动。后台我进不去，方导早禁了，我何必自讨没趣。","truth":"我离开过。下半场刚开场我就去后台堵他谈署名，怕被人看见才撒谎。我只是站在门外，什么都没做。"},{"id":"t_sign","q":"署名页上的涂改？","needs":["clue:c_study4"],"a":"那行狠话是他写的，涂掉一半，是他自己也觉得过分。他一向伤了人，又装作什么都没发生。"},{"id":"t_heard","q":"你在门外听到了什么？","needs":["clue:c_hall3","clue:c_stage1"],"a":"九点整，门里有女人压低声音求他“再给我一点时间”。方导说：“周一我必须如实报告。”接着一声闷响，我以为是道具，吓得跑去抽烟。"},{"id":"t_vic","q":"你觉得他是什么样的人？","a":"固执，爱面子，对钱有洁癖。为一句台词能跟人吵一晚上，为一分钱对不上能翻账翻到半夜。"}],"confronts":[{"clue":"c_hall3","breaks":"t_seat","a":"她看着那件风衣，轻声说：“是我的。我不是故意骗你。我和他吵了半年，你们一听就会怀疑我。”"},{"clue":"c_study4","a":"“他连这个都留着。”她苦笑，“划掉我名字那天我骂了他。他只说‘剧社要散了，你再忍忍’。”"},{"clue":"c_stage1","a":"她脸色一点点白下去。“轻的那声，就是我听到的闷响。那是九点过两分，不是停电的时候。”"},{"clue":"c_back1","a":"她只看了一眼烛台就转过脸，肩膀发抖。“我写的时候，让老团长拿它点灯，等一个回不来的人……”"}],"fallback":"这个我不知道，也许是在我没写过的那一场戏里。"},{"id":"tang","name":"唐婉清","role":"女主演","age":38,"look":{"skin":"fair","hair":"long","hairColor":"auburn","glasses":"none","beard":"none","outfit":"dress","acc":"earrings","mood":"worried"},"bio":"女主演，与方知远合作十二年，曾是他的恋人。下半场一直在台上，停电时提灯撑完三分钟的戏。","demeanor":"腔调优雅带刺，爱用反问，爱摸耳坠。","topics":[{"id":"t_role","q":"你和方知远的关系？","a":"合作十二年，前恋人，现在大概是仇人。他教会我演戏，也毁了我很多年。可他对戏，比对人真诚。"},{"id":"t_last","q":"你最后一次私下见他？","lie":true,"a":"上周排练的时候，我们吵了一架。之后只在台上说台词，下了台不说话。今晚我没和他单独待过。","truth":"今晚中场后，20:45 我们在走廊吵过，他还发短信叫我演完去化妆间。我没去，怕被当嫌疑人，才说上周。"},{"id":"t_contract","q":"你和影视公司的事？","lie":true,"a":"谣言。我去试过镜，没签。剧社都要散了，我总得给自己留条路吧？你们别听人乱传，更别当真。","truth":"我签了，星河影视的剧集，月底进组。他要追偿八十万，我说我赔。人死了，我一分钱也赔不出，没理由杀他。"},{"id":"t_stage","q":"停电时你做了什么？","a":"我拿起台口的提灯，站到台中央，把戏接着念完。观众的手机灯亮成一片，我一句词都没错。"},{"id":"t_quarrel","q":"他让你演完去化妆间？","needs":["clue:c_back3"],"a":"对，要我带合同去。我不会去的。21:20 我下场，在侧幕喘气，直到小乔来喊“方导不对劲”。"},{"id":"t_xu","q":"你觉得许会计这人怎样？","a":"许会计？工资发得一分不差，对谁都客气。就是这阵子瘦了一圈，大概是为解散的事烦的。"}],"confronts":[{"clue":"c_back3","breaks":"t_last","a":"她盯着自己那句“我没什么好谈的”，摸了摸耳坠。“是，我们 20:45 在走廊吵过。可我没去。”"},{"clue":"c_study3","breaks":"t_contract","a":"“日期还是今天。”她慢慢笑了，“八十万，他是真要我偿命。可我没动手，我只在台上杀人。”"},{"clue":"c_hall4","a":"她看着视频里提灯的自己，眼神软下来。“台词没停，手却一直在抖。那时他已经……”她没说下去。"},{"clue":"c_din1","a":"“20:55 上台，21:20 才下场。”她指着白板，“中间一步没出过台口，问谁都行。”"}],"fallback":"我不知道。我只会念台词，不会猜谜。"},{"id":"xu","name":"许敏","role":"剧团会计","age":41,"look":{"skin":"light","hair":"bun","hairColor":"black","glasses":"rect","beard":"none","outfit":"jacket","acc":"badge","mood":"tired"},"bio":"剧社会计，管账十二年。她说下半场一直守在前厅柜台，停电时就坐在投资人金永昌身边。","demeanor":"轻声细语、句句讲规矩，被逼急了会反复整理袖口。","topics":[{"id":"t_role","q":"你在剧社管什么？","a":"管钱。票房、补贴、工资、报销，十二年了。方导管戏，我管账。今晚我还在对遣散清单。"},{"id":"t_where","q":"停电时你在哪？","lie":true,"a":"前厅柜台对票房，中场后没挪过窝。停电时金总就坐在我旁边，你们问他，他会说一样的。","truth":"我离开过柜台。20:57 我进了后台，21:07 才回来。金总那时不在前厅，停电时他才回来坐到我旁边。"},{"id":"t_contact","q":"最后一次和方导说话？","lie":true,"a":"下午三点，谈今晚的结算和遣散费。之后没单独说过话，他今晚手机一直在响，不缺我一个。","truth":"他 20:50 发短信，让我九点整去化妆间，只给五分钟。我回了“好”，也去了。我撒谎，是怕被认定是我。"},{"id":"t_tech","q":"你懂电路设备吗？","lie":true,"a":"我只会按计算器，连投影仪都接不好。停电的事你去问陈野吧，我连总闸在哪儿都要问人。","truth":"定时插座是我买的。19:58 我下仓库取备用金，顺手接在调光柜前，设成 21:12 关、21:15 开。网上看一遍就会。"},{"id":"t_blackout","q":"你怎么看这次停电？","a":"那是陈野的台子，灯一直归他管。老剧场线路旧，跳闸不稀奇。可惜最后一场出了这种事。"},{"id":"t_audit","q":"补贴账是怎么回事？","lie":true,"needs":["clue:c_study1"],"a":"那是项目分摊，先转到我户头走手续，年底冲平。周一我本来就要向审计说明，方导爱多心。","truth":"不是分摊。三年，三十八万六。我妈尿毒症换肾，ICU 一天一万多。方导对账后说周一必须如实报告。"},{"id":"t_door","q":"走廊的防火门？","lie":true,"needs":["clue:c_back2"],"a":"检单我只是顺手签，门吸是物业装的，接哪路电我从来不看。门每天开开关关，跟停电有什么关系。","truth":"下午我对贺师傅说走廊闷，让他开演后吸上门。灯一灭，六十秒后门会哐地合上。我要警察以为他死在那一声里。"}],"confronts":[{"clue":"c_hall1","breaks":"t_where","crack":true,"a":"她看着屏幕里自己走进侧门的那一帧，手指停在袖口上。“……连门都拍了。我是离开过，可金总那会儿也不在。”"},{"clue":"c_back3","breaks":"t_contact","a":"她盯着那个“好”字，睫毛颤了颤。“我怕说出来你们就认定是我。”她吸了口气，“现在不也这样。”"},{"clue":"c_cellar1","breaks":"t_tech","a":"“这种插座网上谁都买得到。”她说得有点急，手又去理袖口，“一个会计，怎么会去动电线？”"},{"clue":"c_study2","breaks":"t_door","a":"她看着审核栏里自己的签字，嘴唇发白。“……都是我填的。做了十二年账，从来不留空格。”"},{"clue":"c_stage3","a":"“吸门是贺师傅的习惯，场记记一笔，很正常。”她说得很平，“走廊闷，大家都知道。”"},{"clue":"c_study1","breaks":"t_audit","a":"她闭了闭眼。“尾号 7316，是我的卡。我一直想补。我妈在 ICU 里一天天烧钱……您说，我还能怎么办？”"},{"clue":"c_stage1","a":"她听完两段声音。“一轻一重。警察听的是重的那声，对吗？声音不会撒谎，听的人会挑。”"}],"fallback":"这个我不清楚，你可以去查账，凡事都有记录的。"},{"id":"jin","name":"金永昌","role":"投资人","age":50,"look":{"skin":"light","hair":"slick","hairColor":"grey","glasses":"rect","beard":"none","outfit":"suit","acc":"tie","mood":"smirk"},"bio":"永昌文化基金老板，八年投了三百万，也是剧场这栋厂房的业主，想月底前签解散协议。他说下半场一直陪会计坐在前厅。","demeanor":"商人口吻，爱说“从商业角度”，笑里带刀，被追问时先报数字再绕开。","topics":[{"id":"t_role","q":"你和剧社的关系？","a":"八年，三百万，外加这栋楼的租约。从商业角度，这是笔很不划算的投资。我只想让事情早点收场。"},{"id":"t_where","q":"下半场你在哪？","lie":true,"a":"前厅，陪许会计，中场后没离开过。灯灭时我就站在她旁边，我们一起摸黑等了三分钟，她可以作证。","truth":"20:52 到 21:08 我不在前厅，在车里见宏远置业的赵经理，谈出让这栋楼。停电时我确实回来站在她旁边。"},{"id":"t_blackout","q":"停电时你看见了什么？","a":"一片漆黑。我只听见唐婉清在台上念台词，身边许会计喘得有点急，我还说她紧张。三分钟后灯亮。"},{"id":"t_dissolve","q":"你想拿到解散协议吗？","a":"当然想。但方知远一死对我不是好事，程序要重走，麻烦一堆。再不讲情面，我也不会为一栋楼杀人。"},{"id":"t_deal","q":"你在车里和谁谈？","needs":["clue:c_hall2"],"a":"宏远置业的赵经理。意向书月底签，要剧社三十天内腾退。方知远要延到明年，我拒绝了。"},{"id":"t_books","q":"你怎么看剧社的账？","a":"许会计管，十二年没出过错。我每年签字，从来没细看过，不是不信她，是信任得过头了。"}],"confronts":[{"clue":"c_hall2","breaks":"t_where","a":"他的笑僵了一下，又堆回来。“你们连保安亭都查。好，20:52 到 21:08 我不在。生意嘛，见不得光。”"},{"clue":"c_hall1","breaks":"t_where","a":"他叹了口气。“监控不会骗人，我在车里谈生意。不过我回来后，她确实一直坐在柜台后。”"},{"clue":"c_study3","a":"“追偿函？”他挑眉，“方知远对谁都下得去手。从商业角度，没发出去的函，价值为零。”"},{"clue":"c_study1","a":"“三十八万？”他眼神冷下来，“账是谁管的，不用我明说吧？这个数，不值得我杀人。”"}],"fallback":"从商业角度说，这件事和我关系不大。"},{"id":"he","name":"贺长根","role":"舞美师傅","age":56,"look":{"skin":"tan","hair":"cap","hairColor":"grey","glasses":"none","beard":"stubble","outfit":"vest","mood":"tired"},"bio":"剧社老舞美，二十八年没离开过后台，布景、道具、仓库都归他管。他说今晚没进过仓库。","demeanor":"老派话少，带方言“咯”“哇”，被问急了就拍大腿。","topics":[{"id":"t_role","q":"你在剧社做什么？","a":"搭台，摆景，管道具，二十八年了。这台子是我一钉一钉搭的，这回剧社要散了，我心里空咯。"},{"id":"t_cellar","q":"今晚你下过仓库吗？","lie":true,"a":"没有哇。道具下午全摆好了，开演后我就守在侧幕，仓库那头连脚都没伸过。不信你问别人。","truth":"下去过，20:38。我去看座钟箱。那只民国座钟被我偷卖了三万八，想解散盘点前糊弄过去。丢人，才说谎。"},{"id":"t_wing","q":"停电时你在哪？","a":"侧幕里，摸黑按住几块景板，怕被撞倒。灯亮后手心全是汗。21:25 我和小乔开的门。"},{"id":"t_timer","q":"仓库里的白插座？","needs":["clue:c_cellar1"],"a":"我 20:38 下去时它就在了，白的，带个小屏幕。我当是陈野加的防浪涌插排，没碰。"},{"id":"t_candle","q":"烛台一直放在哪？","needs":["clue:c_back1"],"a":"走廊道具桌上，谁都能拿。20:48 我最后看过，它还在。后来见它在地上，我腿一软。"},{"id":"t_door","q":"走廊防火门是你吸上的吗？","lie":true,"needs":["clue:c_back2"],"a":"那门我没碰过哇。开演后谁吸的我不晓得，我整晚不是在侧幕就是在休息室，又不盯着门看。","truth":"是我吸的，20:50。许会计说走廊闷，叫我吸上，我没多想。之后在后门抽烟。我怕你们追问，把座钟翻出来。"},{"id":"t_clock","q":"座钟去哪了？","needs":["clue:c_cellar3"],"a":"卖了，我认。拍卖行开价三万八，那阵子我老伴住院，缺钱，我没扛住。丢人，但我不会为这个杀人。"}],"confronts":[{"clue":"c_cellar2","breaks":"t_cellar","a":"他看着登记簿自己那行，拍了下大腿。“我签了名还赖。20:38 我下去过，座钟的事，丢人啊。”"},{"clue":"c_cellar3","a":"“这是我摆的。”他声音低下去，“里头本来是师父传下来的老座钟。我对不起老团长，也对不起它。”"},{"clue":"c_stage3","breaks":"t_door","a":"他摸着场记本上那个“贺”字，半晌才说：“……是我吸的。许会计说走廊闷，哪晓得跟灯一路电。”"},{"clue":"c_hall2","a":"“后门是我抽烟的地方。”他挠了挠脖子，“借了两回火，老张记性好。九点前后我都在那儿。”"},{"clue":"c_back1","a":"他站了很久才敢看。“这烛台是我亲手擦亮的……二十八年了，我头一次不敢进这间屋。”"},{"clue":"c_din1","a":"“白板是我写的，20:50 出，21:05 回。”他叹气，“上了趟厕所，又去外头抽一根。”"}],"fallback":"这个……我不晓得哇，我就是个搭台子的。"},{"id":"qiao","name":"乔小满","role":"新人演员","age":22,"look":{"skin":"fair","hair":"ponytail","hairColor":"black","glasses":"none","beard":"none","outfit":"hoodie","mood":"worried"},"bio":"去年进剧社的新人，兼任方知远的助手和“叫场”。21:15 她去敲化妆间的门，没人应。","demeanor":"声音发颤、爱道歉，紧张时先说“对不起”，会攥衣角。","topics":[{"id":"t_role","q":"你在剧社做什么？","a":"我演小女佣，也给方导跑腿、叫场。他对我很好，教我台词。对不起，我说着说着就想哭。"},{"id":"t_stay","q":"中场后你在哪？","lie":true,"a":"休息室，一直在背词，没出去。21:15 才按排场表去敲方导的门。对不起，我什么都没看见。","truth":"我 20:57 出去过，21:01 回来。手机没电，去走廊拿充电器，在拐角看见一个人往化妆间走。我怕惹事，对不起。"},{"id":"t_tip","q":"你知道账上的事吗？","lie":true,"a":"账？我只负责跑腿，不懂这些。许姐让我核过几次发票，我看都看不懂。对不起，我真不知道。","truth":"我知道。核发票时发现补贴专户有几笔转进个人账户。我不敢当面说，打印了便条塞给方导。我怕被赶出剧社。"},{"id":"t_saw","q":"你在走廊看见了谁？","needs":["clue:c_din1","clue:c_hall1"],"a":"……白板和监控都在，我就说吧。大概 20:58，我看见许姐穿灰开衫往化妆间走。我没多想，现在才觉得不对。"},{"id":"t_knock","q":"你敲门时情形如何？","a":"21:15，门上挂着“勿扰”牌，我敲了三下没人应，以为他在入戏。21:20 他没上场我才慌了。"},{"id":"t_find","q":"谁发现了尸体？","a":"我和贺师傅，21:25。门没锁，方导趴在化妆台上，旁边有只烛台。我腿软，是贺师傅扶我出来的。"}],"confronts":[{"clue":"c_din1","breaks":"t_stay","a":"她盯着白板上自己的名字，揪紧衣角。“对不起，我骗了你。20:57 我出去拿充电器。我怕你们怀疑我。”"},{"clue":"c_din3","breaks":"t_tip","a":"她脸刷地白了：“这是我打的，咖啡是我洒的。”眼泪掉下来，“我只是想帮方导，对不起。”"},{"clue":"c_back1","a":"她只看一眼就捂住嘴。“他今晚还跟我对台词，说‘台上你是最亮的’。对不起，对不起。”"},{"clue":"c_hall1","a":"她盯着那个灰开衫的身影，嘴唇哆嗦：“……是许姐。我不是说她干了什么，我只是看见了。”"}],"fallback":"对不起，这个我真的不知道……"},{"id":"jiang","name":"江临","role":"前团员","age":36,"look":{"skin":"tan","hair":"cap","hairColor":"brown","glasses":"none","beard":"goatee","outfit":"jacket","mood":"sly"},"bio":"五年前被赶出暮光的老团员，如今在晨星剧社做导演助理。他说自己 21:30 才买票进场。","demeanor":"吊儿郎当、爱调侃，被戳到痛处反而笑得更大声。","topics":[{"id":"t_role","q":"你和暮光什么关系？","a":"前团员，演过五年，被方知远一脚踢出去。听说要散，我就来看最后一场，毕竟是青春。哈，像悼词。"},{"id":"t_grudge","q":"你恨方知远吗？","a":"恨过。他当众说我“没有舞台感”。五年了，我现在也做导演了，才明白那话有一半是对的。"},{"id":"t_arrive","q":"你几点进的剧场？","lie":true,"a":"21:30 左右，谢幕前买的站票。我从大门进，没去后台，哪儿也没去，你们查监控好了。","truth":"我 20:48 就进来了，用过期的旧通行证从后台门溜进休息室，偷看下半场。我想拷贝他的舞美，丢脸，但不是杀人。"},{"id":"t_why","q":"你为什么躲着看？","needs":["clue:c_din2"],"a":"晨星要排同题材的戏，我想看他怎么做雨夜光影。票太贵，又怕他不让我进，就偷偷看了。"},{"id":"t_dark","q":"停电时你听到了什么？","needs":["clue:c_stage1","clue:c_din2"],"a":"黑的时候我去洗手间，走到走廊，听见身后“哐”的一声很重。我等着有人喊或跑，结果一点动静都没有。"},{"id":"t_see","q":"休息室里谁进出过？","needs":["clue:c_din1","clue:c_din2"],"a":"我躲在衣架后看得清。小乔 20:57 出去，四分钟后拿着充电器回；老贺 20:50 走，21:05 左右回。"}],"confronts":[{"clue":"c_din2","breaks":"t_arrive","a":"他笑得比平时大声：“被抓了。20:48 进来的，旧通行证，老张没认出来。我是来偷师的。”"},{"clue":"c_stage1","a":"“重的那声我听见了，像整块铁板拍在墙上。”笑意收起，“可倒了个人，怎么会没一点人声？”"},{"clue":"c_back1","a":"他别开视线，没笑。“他最爱干净，连台上的灰都要擦。我讨厌他，可也不想他这么走。”"}],"fallback":"哈，这个我可不清楚，我只是个来看戏的。"}],"solution":{"culprit":"xu","method":{"q":"凶手怎样让人以为死者死在停电里？","options":["趁停电摸黑潜进后台动手，靠熟悉格局来去无踪，事后混回人群。","停电前已动手，再借定时断电和自动合上的铁门，制造一声巨响。","提前在配电线路装定时装置，再靠旁人证词，坐实自己没进过后台。","有人在调光台上切断电源，同伙趁黑进化妆间动手，口径一致。"],"correct":1},"motive":{"q":"凶手为什么杀人？","options":["多年挪用补贴与票房款，死者要在审计上如实报告，凶手怕败露。","死者拿着巨额违约金追偿函，凶手无力偿还，又怕毁了自己的前程。","死者擅改作品署名与版权，凶手长期被压制，在这一晚终于失控。","死者当年当众否定其才能并逐出团队，怨恨在这晚彻底爆发。"],"correct":0},"keyClues":["c_stage1","c_cellar1","c_back2","c_hall1","c_study1","c_study2"],"truth":["凶手是会计许敏。全场都以为方知远死在 21:12 的黑暗里，其实他 21:02 就死了。","三年间许敏转走补贴与票房款 38.6 万（尾号 7316）给母亲治病。方知远对账后约她 21:00 在化妆间，说周一必须如实报告。她哀求无果，用烛台打死了他。","她早有准备：19:58 在调光柜电缆前接了定时插座，21:12 关、21:15 开。走廊防火门磁吸座接同一回路，断电后 60 秒自动合上，她又借贺长根把门吸上。","21:13 的巨响就是门合上的声音，警方因此认定案发在黑暗中。陈野和贺长根的谎，只是各自的私事；保安本、报销单与检单都指向许敏。","她的不在场证明只覆盖假的死亡时间：前厅监控显示她 20:57 到 21:07 离岗，金永昌那时也在车里。"]}},{"id":"vineyard","title":"天使的份额","tagline":"镇庄老桶还没开，酿酒师先倒在了窖底，烛火只熄在半截。","difficulty":3,"cover":"cv_vineyard","tone":"red","brief":"云岭酒庄开桶品鉴会，今晚要开的是封了二十七年的“镇庄桶”。你是庄主请来的老友，也是县里挂名的刑侦顾问。21:00开桶时间到了，酿酒师阚远山没有出现。临时工下窖找人，吐着爬了回来。消防员抬上来的，是已经没了气的阚远山。窖里的发酵桶每年秋天都冒气，人人都说是意外。庄主拉住你的袖子：“老阚在窖里干了四十年，闭着眼都不会倒在自己的窖里。你帮我看一眼。”","victim":{"name":"阚远山","desc":"云岭酿酒师，六十三岁。侧卧在镇庄桶下，右手握着取样管，没有外伤，嘴唇发紫。","look":{"skin":"tan","hair":"short","hairColor":"grey","glasses":"none","beard":"stubble","outfit":"apron","mood":"neutral"}},"publicFacts":["镇庄桶今晚21:00开桶。按惯例，阚远山19:45–19:55独自下窖“敬桶”，不许人跟。","阚远山死于窒息，死亡时间约在19:50至20:30。下层窖离地六十公分以下几乎无氧。","下层窖有两只发酵桶，每年秋天会释放二氧化碳，所以现场第一判断是意外。","开桶雾效用的10公斤干冰，由侍酒师梁瑾签收，存放在厨房冷库。","品酒师柏秋实19:35到20:58在台上主持品鉴，近四十位宾客看着他。","窖里风机17:50被阚远山关闭，二氧化碳探头被保鲜膜包住，没有报警。"],"relations":{"luo":"酒庄庄主，和死者共事三十一年的老兄弟","bai":"为酒庄写评分十几年的品酒师，合作多年的老搭档","shang":"预付八百万订下镇庄桶的进口商，死者的买家","kan":"死者的独生女，酒庄市场总监","pu":"采摘季临时工，给死者打下手","liang":"酒庄首席侍酒师，死者手下的老员工","qi":"酒庄的法律顾问，负责见证开桶公证","qiu":"在酒庄掌勺二十年的大厨，和死者是老同事"},"links":[{"a":"luo","b":"qi","text":"庄主和他聘请的法律顾问"},{"a":"shang","b":"kan","text":"买家和酒庄代表，在谈预付款交割"},{"a":"bai","b":"luo","text":"合作十几年的评分人与庄主"}],"deathReport":{"time":"约 19:45–20:30","cause":"窒息死亡，现场缺氧","scene":"21:08 临时工下窖寻人吐着退出，21:40 消防员入窖，在下层镇庄桶下发现死者，已无呼吸。","loc":"cellar","notes":["没有外伤，嘴唇发紫","侧卧在镇庄桶下，右手握着取样管","下层窖离地六十公分以下几乎无氧"]},"timeline":[{"t":"15:40","text":"10公斤干冰送到，梁瑾签收，放进冷库。"},{"t":"18:00","text":"露台酒会开始。"},{"t":"19:30","text":"庄主骆鸿钧致辞，宾客入品鉴厅。"},{"t":"19:35","text":"柏秋实开始主持品鉴，直到20:58都在台上。"},{"t":"19:48","text":"阚远山举着烛台独自下窖，蒲小亮看见。"},{"t":"21:00","text":"开桶时间到，阚远山没有出现。"},{"t":"21:08","text":"蒲小亮下窖寻人，头晕呕吐退出，随后报警。"},{"t":"21:40","text":"消防员入窖，发现阚远山已死亡。"}],"budget":{"search":12,"ask":28},"locations":[{"id":"cellar","name":"老窖","scene":"cellar","desc":"酒庄地下的橡木桶窖，分上下两层，镇庄桶躺在下层最里面。刚被风机排过气。","clues":[{"id":"c_cel1","title":"熄在半截的烛火","text":"烛台倒在死者身边，蜡烛在离地半米内熄灭，壁龛高处那支仍亮。消防员记录：六十公分以下缺氧。"},{"id":"c_cel2","title":"桶架后的蓝水桶","text":"第三排桶架后塞着蓝色拖把桶，水冰手，边缘结薄冰，桶底两块豌豆大的白色固体还在冒烟。"},{"id":"c_cel3","title":"被缠住的探头","text":"窖口二氧化碳探头被保鲜膜裹住，装在齐胸高。风机空开拨在“关”，贴着阚的便条：“静窖，20:30前勿开。”"},{"id":"c_cel4","title":"镇庄桶的塞口","text":"塞口红蜡封曾被划开又抹平，表面有一道针尖似的新划痕。酒面比去年低了一指多。"}]},{"id":"lab","name":"酿酒师工作室","scene":"lab","desc":"窖口旁的小屋，阚远山的工作室兼化验间，长桌上满是酒渍。","clues":[{"id":"c_lab1","title":"阚的实验笔记","text":"笔记：“17:10给老柏摆三杯，B杯泡过坏塞子，他说都干净。”“18:30他求再给一年。我说开桶后盲评，你先退出。”"},{"id":"c_lab2","title":"三只杯子与化验单","text":"桌上三只杯，B杯有潮纸板的怪味。化验单：B杯含TCA，高于常人嗅出下限，A、C未检出。"},{"id":"c_lab3","title":"“囡囡”的小瓶","text":"窗台上一只750毫升酒瓶，红蜡封口，标签“1999·岭上红·囡囡27岁”。旁边的铜勺里蜡还软。"}]},{"id":"kitchen","name":"后厨与冷库","scene":"kitchen","desc":"厨房后门通向去窖口的服务通道，冷库就在通道口，门边挂着工具挂板。","clues":[{"id":"c_kit1","title":"冷库里的泡沫箱","text":"箱盖内登记单：“15:40收干冰10.0kg”“18:15复称10.0kg”“20:58复称4.1kg”，均签“梁”。"},{"id":"c_kit2","title":"挂锁与挂板","text":"冷库密码锁拨盘停在“1993”，锁梁没扣死。挂板上“防冻手套”少了一副。墙上纸条：“密码=建庄年。”"},{"id":"c_kit3","title":"墙上的禁令","text":"厨房门背后的告示，阚亲笔：“干冰只许放窖口台阶上层，严禁入窖！二氧化碳比空气重，会沉在地上。”"},{"id":"c_kit4","title":"后门台阶上的烟","text":"后门台阶上有半截带口红印的烟头，窗台旧手机记录：“18:46 儿子班主任 17分钟”。"}]},{"id":"hall","name":"品鉴厅","scene":"hall","desc":"一楼品鉴大厅，四十张椅子对着小台，墙上投影还停在标题页。","clues":[{"id":"c_hal1","title":"开桶流程单","text":"流程单：“19:35柏秋实主持品鉴／19:45–19:55酿酒师独自下窖敬桶／21:00开桶”。"},{"id":"c_hal2","title":"手册里的评语","text":"宾客手册末页印着柏的亲笔评语和“97分”，小字注明“18:00付印”。那时桶还没开。"},{"id":"c_hal3","title":"台上的抓拍","text":"相机里19:35、20:10、20:40三张，柏都在台上。19:26的进场照里，他右袖口湿了一块。"},{"id":"c_hal4","title":"帮手拍的布杯照","text":"帮手手机里五张布杯照，时间18:22至19:12。每张里侍酒师都在长桌后摆杯，黑马甲白衬衫。"}]},{"id":"lodge","name":"客房与前台","scene":"guestroom","desc":"酒庄小客栈，二楼三间客房住着受邀客人。前台电脑能调电子门锁记录。","clues":[{"id":"c_gst1","title":"门锁开合记录","text":"门锁记录：201商励18:20出；202祁长青18:25出、19:15入；203柏秋实18:49出、19:12入。"},{"id":"c_gst2","title":"203房的衣橱","text":"衣橱里一件灰针织开衫，袖口发硬泛白，还是潮的。垃圾桶里一副橡胶手套，指尖冰凉，标签“防冻手套”。床边有黑色文件夹。"},{"id":"c_gst3","title":"洗漱包里的药","text":"203房洗漱包里有鼻喷剂和一张八个月前的检查单：“嗅觉阈值测试：双侧重度减退”，姓名柏秋实。"},{"id":"c_gst4","title":"201房的采样箱","text":"201房有带冰袋的采样箱，里面是空采样瓶和检测委托单。抽屉里压着聘书抄件：聘梁瑾为商氏酒业酒窖总监。"},{"id":"c_gst5","title":"抽屉里的顾问协议","text":"聘书下压着《品鉴顾问协议》：商氏酒业聘柏秋实为镇庄桶撰写品评与评分，顾问费六万，上周签订。"}]},{"id":"garden","name":"露台与前院","scene":"garden","desc":"酒会的露台连着前院，宾客座椅还没收完，各处都留着今晚来过的人的痕迹。","clues":[{"id":"c_gar1","title":"雾效策划与送货单","text":"送货单：“15:40干冰10kg，订货人阚雨桐，收货梁瑾。”策划册页边手写：“爸不让进窖，雾只在台阶口放。”"},{"id":"c_gar2","title":"酒会直播回放","text":"直播回放：18:52雨桐与商励在露台；19:03梁瑾在厅里摆杯；19:17侧廊传来女声：“你守着那个桶过一辈子吧！”"},{"id":"c_gar3","title":"门岗登记与催收函","text":"门岗登记：“18:36祁长青，轿车出。19:09入。”祁的公文包里露出一角《贷款逾期催收函》。"},{"id":"c_gar4","title":"花盆后的空瓶","text":"花盆后藏着两只空试饮酒瓶，旁边塞着写“蒲”字的工作手套，掌心沾着窖口的青苔。"}]}],"suspects":[{"id":"luo","name":"骆鸿钧","role":"云岭酒庄庄主","age":68,"look":{"skin":"tan","hair":"short","hairColor":"white","glasses":"none","beard":"none","outfit":"jacket","acc":"pocketwatch","mood":"worried"},"bio":"酒庄创办人。整晚在露台迎客，19:30上台致辞，随后坐在第一排看品鉴，一直没有离席。","demeanor":"嗓门大，爱拍桌子，口头禅“咱云岭”。","topics":[{"id":"t_role","q":"你和阚师傅？","a":"三十一年！咱云岭的酒，七成是他的鼻子和手。老阚啊老阚，你怎么偏偏挑在今晚走了呢。"},{"id":"t_quarrel","q":"今天吵过架吗？","lie":true,"a":"吵？没有没有！我和老阚三十年没红过脸，今天这么大的日子，高兴还来不及，吵什么吵。","truth":"吵了。下午四点半，我要把整桶卖给商老板抵债，老阚死活要留一部分，我拍了桌子走人。"},{"id":"t_loan","q":"酒庄的账怎么样？","needs":["ask:luo.t_quarrel"],"a":"难。贷款逾期两个月，催收函都下来了。商老板那八百万预付款，就是咱云岭过冬的粮食。"},{"id":"t_where","q":"19点后你在哪？","a":"露台迎客到19:25，一堆人看着。19:30上台说几句，就坐第一排，一眼没离开过台子。"},{"id":"t_ice","q":"谁安排雾效？","a":"雨桐的主意，说年轻人爱看雾。老阚说只准在台阶口放。我嫌麻烦，也就没管他们俩，随他们折腾去。"},{"id":"t_gas","q":"为何会窒息？","a":"下层有两只桶在发酵，每年秋天都冒气，老阚晓得的。他在窖里干了四十年，我不信是意外！"},{"id":"t_suspect","q":"你怀疑谁？","a":"我怀疑那个雾。干冰是侍酒师管的，主意是雨桐的，姓商的又急着要酒。哎，这话可不能乱说。"}],"confronts":[{"clue":"c_lab1","breaks":"t_quarrel","a":"他手背青筋跳了两下：“他连这个都记。是，吵了。可三十年的兄弟，我犯得着杀他吗？”"},{"clue":"c_gar3","a":"他一把抢过催收函：“银行的事我自己扛！老阚一死，这庄子就是空壳，我拿什么去还银行？”"},{"clue":"c_gar1","a":"“雨桐订的？”他愣了一下，“小孩子想让今天好看点，不懂事。”他的声音有些心虚，眼神也躲开了。"},{"clue":"c_cel2","a":"“窖里怎么有个桶？”他脸色发白，“不是漏气，是有人干的？到底谁跟老阚有这么大的仇？”"}],"fallback":"这事儿我不懂，你问点实在的。"},{"id":"bai","name":"柏秋实","role":"品酒师（评分人）","age":58,"look":{"skin":"fair","hair":"sidepart","hairColor":"silver","glasses":"round","beard":"none","outfit":"suit","acc":"bow","mood":"tired"},"bio":"业内称“金鼻子”，为云岭写评分十几年。19:35起主持品鉴，一直到结束都站在台上。","demeanor":"慢条斯理，开口先“嗯”一声；被逼问时声音更轻。","topics":[{"id":"t_role","q":"你和阚师傅？","a":"嗯……三十年。他酿酒，我评酒，谁也离不开谁。他是我见过鼻子最干净的人，没有之一。"},{"id":"t_talk","q":"今天你们谈过吗？","lie":true,"a":"谈过，下午帮他试杯，聊开桶流程。他还夸我状态好。这桶酒是我们俩共同的作品，我替他高兴。","truth":"他说开桶后评分改由盲评组打，要我先退出。我求他再给一年，他不肯，一点情面都没留。"},{"id":"t_where","q":"19点前后在哪？","lie":true,"a":"回房写评语，从18:40待到19:25，没出过门。开场前我习惯一个人静一静，这是老习惯。","truth":"我出过门。18:49出去，19:12才回来，二十三分钟。去了哪里，我现在不想说。"},{"id":"t_nose","q":"你的鼻子？","lie":true,"a":"嗯，三十多年没闻错过一杯酒。好鼻子是养出来的。你要是不信，我现在就盲品一杯给你看。","truth":"两年前鼻窦手术后，我的嗅觉就废了，只剩一点酸和甜。我瞒了所有人，连阚都没告诉，靠记忆写评语。"},{"id":"t_cold","q":"去过冷库吗？","lie":true,"a":"冷库？我连它朝哪开都不知道。品酒师从不进厨房，今天我一步都没往那边去过，真的，你别不信。","truth":"去过。18:52，密码是建庄年。我戴上挂板上的防冻手套，从泡沫箱里舀走了大半的干冰。"},{"id":"t_ice","q":"谁能拿到干冰？","needs":["clue:c_kit1"],"a":"干冰是梁瑾签收、称重的。冷库密码大家都知道，她说锁了，那就是锁了吧，当时我并不在场。"},{"id":"t_fee","q":"和商励有合作吗？","needs":["clue:c_gst5"],"a":"六万，是。他要一篇推介文字，我写了。分数是我自己给的，不是他买的，你可别误会了。"},{"id":"t_asked","q":"问过梁瑾吗？","needs":["ask:liang.t_tell"],"a":"嗯……随口问过，想知道雾怎么放。她都说了。刚才说连冷库朝哪开都不知道，是我说过头了。"},{"id":"t_year","q":"以后怎么办？","needs":["ask:bai.t_nose"],"a":"我妻子在护理院，一个月两万八。“金鼻子”是我唯一的收入。老阚要我退，就是断她的命。"}],"confronts":[{"clue":"c_lab1","breaks":"t_talk","crack":true,"a":"他翻到最后一页，指节发白：“他连这个都写。是，我求过他。可被拒绝的人，就一定会杀人吗？”"},{"clue":"c_gst1","breaks":"t_where","crack":true,"a":"他轻轻笑了一下：“门锁会替人记账。18:49到19:12，我不在房里。去了哪里，记录没写。”"},{"clue":"c_gst3","breaks":"t_nose","a":"他盯着检查单：“医生说也许会好。没有。一个闻不到酒的品酒师，岂不是比死人还不如。”"},{"clue":"c_gst2","breaks":"t_cold","crack":true,"a":"他看了看手套和开衫：“这件开衫是我的。冷库挂板上的东西怎么在我房里，你该清楚。”"},{"clue":"c_hal2","a":"他指尖停在“97分”上：“评语是我写的，桶还没开。品酒师都这样，开之前心里早有分数。”"},{"clue":"c_kit1","a":"“少了六公斤。”他淡淡地说，“我从19:35到20:58一直在台上，没人比我更有不在场证明。”"},{"clue":"c_hal4","a":"他把照片看了很久：“她一直在厅里，是吧。……我知道你接下来想问什么了，你问吧。”"},{"clue":"c_gst5","a":"“文字是我写的，钱是我收的。”他说，“可你得先问问阚，他在乎的到底是不是这个。”"},{"clue":"c_hal3","a":"他抹了抹照片里湿了的右袖口：“台上出了汗，又洒了点酒。你不会连这个也要怀疑吧。”"}],"fallback":"嗯……这个我得想想，你换个问法。"},{"id":"shang","name":"商励","role":"进口商（预付买家）","age":45,"look":{"skin":"light","hair":"slick","hairColor":"black","glasses":"rect","beard":"none","outfit":"suit","acc":"tie","mood":"sly"},"bio":"商氏酒业老板，预付八百万订下镇庄桶。18:20出房，在露台待到开场，之后坐在厅里。","demeanor":"语速快，爱算账，开口“讲真”，被抓住就笑着打岔。","topics":[{"id":"t_role","q":"你来酒庄做什么？","a":"讲真，我来收货的。八百万预付，镇庄桶二十七年，开桶那一刻，我就是第一个签收的人，没什么好绕的。"},{"id":"t_cellar","q":"你去过窖吗？","lie":true,"a":"没有。我一下午都在客栈和露台，窖口都没靠近过。讲真，别什么事都往我头上扣，我受不起。","truth":"去过。下午五点半，我溜到窖口想取点样送检，被临时工的脚步声吓跑了，什么也没取到。"},{"id":"t_terrace","q":"18点半后？","a":"露台上，和阚小姐聊预付款交割，一直到19:25庄主上台前。直播里应该都录着，你去看。"},{"id":"t_deal","q":"你们谈了什么？","lie":true,"a":"就是交割细节，付款节点、物流、保险，我跟她一项一项算过账，白纸黑字，真的真没别的。","truth":"我劝她带着她爸的配方出来单干，我出资。她没答应。我还想把侍酒师梁瑾也挖到我这边来。"},{"id":"t_sample","q":"你为什么想取样？","needs":["ask:shang.t_cellar"],"a":"我见过太多“二十七年”，一尝是三年新酒兑焦糖色。八百万呢，我想验，错了吗？没取成。"},{"id":"t_score","q":"你和柏老师熟吗？","lie":true,"a":"不熟，酒会点个头。他评分，我买酒，隔着距离才干净。讲真，我从来不做买评分这种事。","truth":"有协议。上周请他写镇庄桶推介文字和评分，六万。我想要九十五以上，没写进合同。他回：“酒到了才算数。”"},{"id":"t_ice","q":"谁能动那些干冰？","a":"听说是侍酒师签收，放冷库。要说最方便，当然是她。不过我讲数据，没证据我不乱咬人。"},{"id":"t_vic","q":"他死对你有利？","a":"他死了，我的八百万就悬着，桶还可能被封。讲真，我是全场最希望他活着的人之一，你信不信。"}],"confronts":[{"clue":"c_gst4","breaks":"t_cellar","a":"他嘴角抽了抽，又笑起来：“被你翻到了。我去过窖口，但没进去。生意人嘛，总要防一手。”"},{"clue":"c_gar2","breaks":"t_deal","a":"他的笑僵了一下：“好，没只谈交割。我想把她和配方一起带走。那是商业，不是犯罪。”"},{"clue":"c_gst5","breaks":"t_score","a":"他摊手：“有协议。可买的是一篇文字，不是分数。我哪有本事，买得了一个金鼻子的鼻子。”"},{"clue":"c_cel4","a":"他沉默半拍：“那是我划的，就一下，想看蜡底下有没有第二层封。什么都没取到，你要信我。”"},{"clue":"c_kit1","a":"他皱眉：“少了六公斤？客人连冷库在哪都不知道。这事你该去问问管冰的那个人，别来问我。”"}],"fallback":"这个跟我的买卖没关系，说点能落到纸上的。"},{"id":"kan","name":"阚雨桐","role":"酒庄市场总监（死者之女）","age":27,"look":{"skin":"fair","hair":"ponytail","hairColor":"black","glasses":"none","beard":"none","outfit":"dress","acc":"earrings","mood":"stern"},"bio":"阚远山的独生女，策划今晚的开桶会。18:50前后在露台，19:30进厅，之后在厅里。","demeanor":"冷静带刺，爱说“闭环”“颗粒度”，被戳中才吸一口气。","topics":[{"id":"t_role","q":"你在酒庄做什么？","a":"市场、品牌、活动。我爸负责酒，我负责让人知道这是好酒。每个环节我都有闭环。除了今晚。"},{"id":"t_dad","q":"见过父亲吗？","lie":true,"a":"18点之后没见过。他在窖里准备，我在露台和厅里忙得脚不沾地，连一句话都没来得及说上。","truth":"见过，19:15在侧廊。我劝他卖桶，他不肯，我骂了他，他说“我下去静一静”。那是最后一次说话。"},{"id":"t_ice","q":"干冰是谁订的？","lie":true,"a":"那是梁瑾的事，她管陈列和饮品。雾效我只出创意，送货和签收我都没有经手，你去查她。","truth":"是我订的，10公斤，用在开桶雾效上。我怕别人说，是我订的东西害死了他，才不敢认。"},{"id":"t_formula","q":"和商励谈了啥？","a":"付款节点和物流。他还提过“另起品牌”，我没接。我爸的配方，我绝不会拿去卖，也不会跟他走。"},{"id":"t_barrel","q":"那只桶？","needs":["clue:c_lab3"],"a":"那是我出生那天封的桶。他说等我二十七岁，开一瓶给我。所以他才死活不肯把整桶都卖掉。"},{"id":"t_save","q":"怎么发现的？","a":"21:00他没出现，我去窖口喊，没人应。小蒲下去，吐着上来。我站在窖口，一步都不敢往下。"},{"id":"t_suspect","q":"你怀疑谁？","a":"我不想先怀疑任何人。但干冰是梁瑾签收保管的，能碰到它的人，本来就不多。你们自己想。"}],"confronts":[{"clue":"c_gar2","breaks":"t_dad","a":"她指甲掐进掌心：“对，是我。我骂了他，他说想静一静。那就是我们父女最后的一句话。”"},{"clue":"c_gar1","breaks":"t_ice","a":"她叹了口气：“是我订的。策划册写了不许入窖。我不敢说，怕你们觉得，是我杀了他。”"},{"clue":"c_lab3","a":"她嘴唇抖了一下：“囡囡27岁……这个傻老头，什么话都不肯当面跟我说上一句，到死都是。”"},{"clue":"c_kit1","a":"“少了六公斤？”她眉头一跳，“我订了十公斤，雾效只要三公斤。多出来的是谁拿走的？”"}],"fallback":"这个跟活动没关系，我暂时没有判断。"},{"id":"pu","name":"蒲小亮","role":"临时工（采摘季帮工）","age":20,"look":{"skin":"brown","hair":"messy","hairColor":"black","glasses":"none","beard":"none","outfit":"hoodie","mood":"worried"},"bio":"采摘季临时工，负责冲窖、搬椅子、送酒。最后见阚下窖，21:08第一个下去找人的是他。","demeanor":"紧张结巴，爱说“那个……就是”，急了连说“真的真的”。","topics":[{"id":"t_role","q":"你今天做什么？","a":"那个……就是，下午三点冲窖里的地，阚师傅让我把探头包一下防溅水。后来搬椅子送酒，真的没干啥。"},{"id":"t_where","q":"18点后你在哪？","lie":true,"a":"前院，一直搬椅子，搬到十九点多。没去过窖里，真的，阚师傅说了，闲人不许往下面去的。","truth":"我偷懒了。躲在上层桶厅桶后，喝了两瓶试饮酒，还睡了一会儿。怕被老板骂，才撒谎的。"},{"id":"t_film","q":"探头的膜撕了吗？","lie":true,"a":"撕了撕了！冲完地我就撕了，阚师傅叮嘱过的，我哪敢忘呀，真的真的，不信你问阚师傅……哦。","truth":"没撕。冲完地我就去搬椅子，忘得干干净净。要是撕了，探头也许就会响……是我害的，真的是我害的。"},{"id":"t_saw","q":"桶厅看到什么？","needs":["clue:c_gar4","ask:pu.t_where"],"a":"十九点前，有人从服务通道过来，穿灰针织衣，抱着白色泡沫箱往下层走。我以为是梁姐，没敢看脸。"},{"id":"t_fog","q":"你见到雾吗？","needs":["ask:pu.t_where"],"a":"十九点二十五，台阶底下有白雾贴着地爬上来，凉凉的。我以为是在试雾效，就没吭声，也没跟人说。"},{"id":"t_shape","q":"那人什么样？","needs":["ask:pu.t_saw"],"a":"背有点驼，人不算高，腋下夹着黑色硬壳文件夹。别的我真看不清，我那时候还喝了酒，晕乎乎的……"},{"id":"t_last","q":"见过阚下窖？","a":"十九点四十八，窖口门边，他举着铜烛台说“蒲娃，别跟着”。他举着蜡烛走下去，背影特别稳。"},{"id":"t_shang","q":"窖口有生人？","a":"下午五点半，那个穿西装的商老板在窖口探头往里看。我踩响了台阶，他就走了，也没敢问他想干嘛。"}],"confronts":[{"clue":"c_gar4","breaks":"t_where","a":"他涨红了脸：“那是我的手套……好吧，我躲在桶厅喝酒睡觉。怕被开除，才撒谎，真的真的。”"},{"clue":"c_cel3","breaks":"t_film","a":"他盯着裹住的探头，嘴唇发抖：“我没撕……就忘了。如果探头是亮的……”眼泪砸在手背上。"},{"clue":"c_cel2","a":"“这个桶？”他愣愣地看着，“我下午冲地的时候，第三排桶架后面没有这个桶啊，一定是后来才放的。”"},{"clue":"c_hal4","a":"“黑马甲……”他挠挠头，“我看见的那个没穿马甲，是灰毛衣。梁姐那么整齐，不会披毛衣。”"},{"clue":"c_hal3","a":"他摇头：“我看见的那个不是穿西装的，是灰色的毛线衣。别的我真说不准，你别逼我。”"}],"fallback":"这个我不知道，真的，我就是干零活的。"},{"id":"liang","name":"梁瑾","role":"侍酒师（品鉴主管）","age":34,"look":{"skin":"light","hair":"bun","hairColor":"black","glasses":"none","beard":"none","outfit":"vest","acc":"badge","mood":"stern"},"bio":"首席侍酒师，签收干冰。19:35起在台侧斟酒，20:58才去冷库取冰，发现少了。","demeanor":"利落，爱说“SOP”“节点”，短句，被怀疑时更冷。","topics":[{"id":"t_role","q":"你今晚负责什么？","a":"流程、杯具、酒序、斟酒，还有雾效执行。每个节点我都有表，一分钟不差。除了窖里这个节点。"},{"id":"t_lock","q":"冷库有人动过吗？","lie":true,"a":"没有。18:15称完重我就锁了，打乱了拨盘。20:58去取冰才发现少了。这是我的SOP。","truth":"我没打乱拨盘。蒲小亮要取冰块，我把拨盘停在1993。我怕被抓住把柄，才说锁死了。"},{"id":"t_future","q":"想离开吗？","lie":true,"a":"当然。我在云岭六年，从学徒做到首席，从没想过要走，也没有人来找过我。酒庄就是我的家。","truth":"我动过心。商老板给了我一份聘书，年薪翻倍。我还没答应，也没告诉过阚师傅，怕他伤心。"},{"id":"t_where","q":"18点后在哪？","a":"18:15称完重，就在厅里和三个帮手布杯，到19:20。19:35开斟，一直站台侧。"},{"id":"t_weigh","q":"何时发现？","needs":["clue:c_kit1"],"a":"20:58，我去取三公斤做雾效，一称只有4.1公斤。早先是10.0，这数我亲自称的。"},{"id":"t_rule","q":"干冰能不能入窖？","needs":["clue:c_kit3"],"a":"绝对不能。阚师傅贴了告示，我也培训过所有人。二氧化碳沉在地面，所以只能在台阶口放雾。"},{"id":"t_code","q":"密码锁谁知道？","needs":["clue:c_kit2"],"a":"建庄年1993，印在酒标和手册上。厨房、侍酒、帮工都知道。这密码本就不该这么设。"},{"id":"t_tell","q":"柏问过冷库？","needs":["clue:c_hal4"],"a":"问过。下午五点四十，柏老师说致辞想提雾效，问干冰怎么取。我都说了：冷库、密码、手套挂在挂板上。"},{"id":"t_suspect","q":"你怀疑谁？","a":"说不好。进得了冷库的人太多，我数不过来。我现在不想乱说，说错一个，就是毁一个人。"}],"confronts":[{"clue":"c_kit2","breaks":"t_lock","a":"她脸色冷下去：“我没打乱。蒲小亮要取冰块，我偷懒了。这是我的失误，但我没有杀人。”"},{"clue":"c_gst4","breaks":"t_future","a":"她沉默几秒：“他开的价我没法拒绝，也不想告诉阚师傅。但我从来没有想过要让他死。”"},{"clue":"c_hal4","a":"她松了口气：“这几张的时间，我没离开过长桌。”又抿嘴，“可我也不算一点关系都没有。”"},{"clue":"c_kit1","a":"“最后一行是我亲手称的，4.1公斤。”她盯着字迹，“我当时就知道有人动了手脚。”"},{"clue":"c_cel2","a":"“蓝桶是窖里洗地用的，不是我们放的。”她声音发紧，“有人把干冰倒进了水里，是故意的。”"}],"fallback":"这个不在我的流程里，请说清楚你要问什么。"},{"id":"qi","name":"祁长青","role":"酒庄法律顾问","age":52,"look":{"skin":"light","hair":"sidepart","hairColor":"grey","glasses":"rect","beard":"none","outfit":"suit","acc":"tie","mood":"neutral"},"bio":"酒庄法律顾问，见证开桶公证。自称18:25出房后一直在露台，19:15回房取文件。","demeanor":"严谨，字字推敲，爱说“就事论事”“证据在哪里”。","topics":[{"id":"t_role","q":"你今晚的职责？","a":"见证开桶，确认桶内酒与销售合同一致，并在附件签字。就事论事，我只管程序，不管酒。"},{"id":"t_where","q":"18点半前后？","lie":true,"a":"露台，接了几个重要电话，一直没挪过位置，宾客都看见了。19:15我才回房取文件。","truth":"我开车出去了。18:36出门，19:09回来，去镇上取农商行的催收函，不能让庄主知道。"},{"id":"t_loan","q":"酒庄的财务如何？","needs":["ask:qi.t_where"],"a":"不健康。贷款逾期两个月，十日内不还就申请查封。我想等晚宴结束后，再单独告诉庄主。"},{"id":"t_contract","q":"合同怎么约？","a":"商氏预付八百万，验收合格付余款。标的灭失则预付款返还。注意，“标的”指酒，不是人。"},{"id":"t_will","q":"阚师傅找过你吗？","needs":["ask:qi.t_loan"],"a":"十四号找过。他问酒庄若被查封，留给女儿的那瓶酒算不算资产。我答算。我没告诉庄主，是我疏忽。"},{"id":"t_gas","q":"怎么看死因？","a":"法律上只有“窒息死亡”一个事实。是不是意外，要看证据。若有人动过窖里设备，就另当别论。"},{"id":"t_suspect","q":"你怀疑谁？","a":"依我看，先别急着挑人。动机谁都有一点，机会也不少，证据在哪里，就跟到哪里，别的都是猜。"}],"confronts":[{"clue":"c_gar3","breaks":"t_where","a":"他合上笔记本：“门岗有记录。好，我离开过。我去取一封对酒庄不利的函件，与阚师傅的死无关。”"},{"clue":"c_gst1","a":"他点点头：“与门岗对不上，我承认。但我可以证明，18:36到19:09我都在镇上。”"},{"clue":"c_lab1","a":"“他们吵过。”他眉心拧起，“这对销售合同有影响，可我万万没想到，会走到这一步。”"},{"clue":"c_hal2","a":"他翻到末页：“评语印在18:00。这属于宣传材料，我没审过，也不应该由我来负责。”"}],"fallback":"这不在我的职责范围内，请给我明确的问题。"},{"id":"qiu","name":"邱桂兰","role":"酒庄大厨","age":55,"look":{"skin":"tan","hair":"bun","hairColor":"grey","glasses":"none","beard":"none","outfit":"apron","mood":"worried"},"bio":"在云岭掌勺二十年，负责今晚的小食和热汤。自称整晚没离开过厨房半步，只听到窖里一声闷响。","demeanor":"絮絮叨叨，爱说“哎哟”“我跟你说”，急了就拍围裙。","topics":[{"id":"t_role","q":"你今晚忙什么？","a":"哎哟，我跟你说，二十个人的小食，一锅热汤，四十人的夜宵，我从下午两点起就没坐过。"},{"id":"t_kitchen","q":"18:30后？","lie":true,"a":"厨房呀！炉子上煨着汤，我哪敢走开半步？一步没离开，帮手都能给我作证，哎哟，我跟你说，真的。","truth":"我溜出去了。18:45到19:05，在后门台阶接儿子班主任的电话。怕被庄主说不专心。"},{"id":"t_door","q":"冷库的门怎么样？","needs":["ask:qiu.t_kitchen"],"a":"我回来时冷库门开着条缝，泡沫箱盖歪着。我当是梁小姐没关好，顺手推上了。这不会有事吧？"},{"id":"t_cold","q":"谁常去冷库？","a":"梁小姐，还有小蒲，他去拿冰块。密码是建庄年，大家都知道，厨房进进出出的人多，我也没留意。"},{"id":"t_knock","q":"你听到什么声音？","a":"二十点前后，窖口方向“咚”的一声闷响，我以为是桶倒了。没人去看。现在想起来，头皮发麻。"},{"id":"t_vic","q":"阚是什么人？","a":"好人哪！每年开桶前他都下去“敬桶”。对干活的从不摆架子，我儿子发烧，他还借我车。"},{"id":"t_suspect","q":"你怀疑谁？","a":"我哪敢怀疑呀。要说怪，下午商老板在后厨门口转过，问我窖口怎么走，我就让他去找小蒲了。"}],"confronts":[{"clue":"c_kit4","breaks":"t_kitchen","a":"她拍着围裙：“哎哟，被你看到了。我出去接电话，十七分钟。怕被庄主骂，就瞒着了。”"},{"clue":"c_kit2","a":"“我回来推门时，锁就挂在那儿，我没拨过。”她小声说，“哎哟，要是我多看一眼就好了。”"},{"clue":"c_kit1","a":"她咂嘴：“是梁小姐的字。我就记得箱盖歪着，白白的雾还往外冒，我还说，哎呀别浪费了。”"},{"clue":"c_gst3","a":"“柏老师的药？”她愣了愣，“他吃东西从来不放辣，说是怕影响鼻子。原来……原来是这样。”"}],"fallback":"哎哟，这个我真不懂，你别吓我。"}],"solution":{"culprit":"bai","method":{"q":"凶手怎样做到“案发时人在台上”？","options":["把整箱干冰搬到下层窖台阶下，等死者走进去","提前取走部分干冰藏进窖里，再回台上等待","锁死窖门堵住通风口，让发酵气体慢慢积满","推死者摔下台阶昏迷，再拖到发酵桶旁熏死"],"correct":1},"motive":{"q":"凶手为什么要杀人？","options":["死者不肯整桶出售，挡住酒庄唯一的还债路","收了买家好处提前印好高分，被死者察觉","死者看穿他已失去谋生本事，要当众撤下","死者多年前夺走他的成名之作，积怨爆发"],"correct":2},"keyClues":["c_cel1","c_cel2","c_kit1","c_lab1","c_gst1","c_gst2"],"truth":["凶手是品酒师柏秋实。他用开桶雾效备下的干冰，加上“二氧化碳比空气重”的常识，布下一个看不见的陷阱。","两年前他鼻窦手术后嗅觉丧失，一直瞒着。阚用坏塞子杯试出真相，18:30要他退出评分。妻子在护理院，“金鼻子”是他唯一的收入。","18:52他用密码1993进冷库，戴防冻手套舀走约六公斤干冰，倒进下层窖的水桶藏好，19:12回房，19:35上台。","气体沉在地面，积成约六十公分的气层。19:48阚举烛下窖，弯腰取酒时一头栽进去。他在台上，是对的，只是陷阱早已布好。","第一层反转：梁瑾只是好心告诉过柏冷库怎么进，帮手相册证明她一直在厅里。第二层：柏的动机不是收买家的钱，而是嗅觉被看穿。"]}},{"id":"bank","title":"金库","tagline":"周末加班的老银行，行长死在二十个小时里谁也打不开的时间锁金库里。","difficulty":4,"cover":"cv_bank","tone":"cold","brief":"临澜商业银行老城支行，周一迎总行审计，全行周末加班。周日14:00，金库时间锁到点，副行长殷鹤年与风控主管戚韵双钥开库，审计桑知白在场——行长柯正庭倒在保管箱间，已无呼吸。\n周六18:00封库后，谁的钥匙也打不开，直到这一刻。你受总行监察室委托，周日15:10到场，走廊里坐着八个人，个个说什么也不知道。","victim":{"name":"柯正庭","desc":"五十八岁，老城支行行长。周日14:00在保管箱间17号箱前被发现，侧卧，西装整齐，没有外伤，身下压着黑色文件夹。","look":{"skin":"light","hair":"slick","hairColor":"grey","glasses":"rect","beard":"none","outfit":"suit","acc":"tie","mood":"tired"}},"relations":{"yin":"副行长，共事十一年的老搭档","qi":"风控主管，行长的下属","wu":"客户经理，业务上常找行长签字","li":"押运队长，每周往库里送钱","xi":"外包IT，管着行里的机房和报警","chu":"保洁员，天天收拾行长的茶具","sang":"总行派来的审计，和行长是查与被查","guan":"跟了他十四年的秘书"},"links":[{"a":"yin","b":"qi","text":"一人一把钥匙，同守金库"},{"a":"wu","b":"guan","text":"想见行长，都得先过她这关"}],"deathReport":{"time":"约周六 21:00–24:00","cause":"缺氧窒息，体内检出镇静药","scene":"周日14:00开库，殷鹤年、戚韵与桑知白在场，发现行长侧卧在保管箱间17号箱前，已无呼吸。","loc":"vault","notes":["身上无外伤，西装整齐","指甲发紫，右手握着一把小钥匙","身下压着一个黑色文件夹"]},"publicFacts":["金库周六18:00封库，须殷鹤年（A钥）、戚韵（B钥）双钥同开合，并设时间锁至周日14:00。紧急解锁最快周一。","时间锁周三由柯正庭、殷鹤年设定，防盘库前有人接触库存。","医生初判：无外伤，缺氧死亡，镇静药快检阳性，死亡时间在周六21:00至24:00。","库内只有主厅有摄像头。封库前，两位钥匙人要执行“清库”，确认库内无人。","周六加班：副行长、风控、客户经理、押运队长、IT、保洁、审计、行长秘书都在行内或出入过。","周五预审发现系统库存与账面有差异，待周日盘库核实。"],"timeline":[{"t":"周六 17:41","text":"押运车到行，柜员点钞至 17:58。"},{"t":"周六 17:58","text":"库门闭合；17:59 双钥；18:00:41 时间锁设至周日 14:00。"},{"t":"周六 19:00","text":"IT 维护员郗晨开始网络割接，至 21:30。"},{"t":"周日 13:55","text":"行长秘书管若兰从老家赶回行里。"},{"t":"周日 14:00","text":"双钥开库，发现柯正庭已死。"},{"t":"周日 15:10","text":"你到达，警方预计两小时后赶到。"}],"budget":{"search":12,"ask":26},"locations":[{"id":"vault","name":"金库","scene":"cellar","desc":"半米厚的库门敞开，主厅是现金架和钞箱，东侧栏栅门后是编号保管箱。空气闷，有铁锈味。","clues":[{"id":"c_vault1","title":"保管箱间的遗体","text":"柯侧卧在17号箱前，无外伤，指甲发紫，右手握小钥匙，箱内空。医生字条：镇静药阳性，胃里有茶叶渣。"},{"id":"c_vault2","title":"黑色文件夹","text":"手写账外往来簿，合计240万，旁注“柯”。末页铅笔字：“周一前三张确认书由若兰补签。”"},{"id":"c_vault3","title":"时间锁与双钥面板","text":"门板记录：17:58:12闭门，17:59双钥，18:00:41设锁至周日14:00，其间钥匙无效。"},{"id":"c_vault4","title":"库内应急按钮","text":"红色应急按钮罩子完好，机械计数器为0。从17号箱走到按钮约十几步。"}]},{"id":"monitor","name":"监控室与机房","scene":"lab","desc":"一楼后侧小房间，三面监控屏，机柜灯全绿，只有一盏闪黄。","clues":[{"id":"c_cam1","title":"库内录像","text":"17:46柯扶墙走进主厅，脚步不稳。17:54殷鹤年在箱间口弯腰十秒，摆手离开；戚韵在门口看手机。"},{"id":"c_cam2","title":"大堂与走廊录像","text":"行长室进出：邬16:50–17:05；管16:58端茶盘入，17:03空手出；戚17:12–17:15；管17:16–17:19端杯出。17:50管走前门。"},{"id":"c_cam3","title":"接警主机日志","text":"主机自周五16:00起处于“检修态”，未收到任何信号。黄色标签“请复原”，落款周五。"}]},{"id":"hall","name":"营业大厅与后场","scene":"hall","desc":"柜台空荡，点钞机盖着罩布，后场通道通向押运交接口，墙上钉着值班表。","clues":[{"id":"c_hall1","title":"押运交接单","text":"“预计到达”16:30改为17:30。页脚：行长办公室15:10申请，账号gr_0126。实收17:41，厉铁成签。"},{"id":"c_hall2","title":"库内出入登记簿","text":"17:54“清库”，殷鹤年、戚韵签名画钩。柯正庭一栏没有记录。"},{"id":"c_hall3","title":"押运车行车记录","text":"GPS：16:44–17:03在实验小学附近停十九分钟，17:41到后场。驾驶员厉铁成。"}]},{"id":"study","name":"行长室","scene":"study","desc":"朝北的大办公室，窗帘半拉。警员刚用备用钥匙打开了上锁的抽屉。","clues":[{"id":"c_study1","title":"抽屉里的处理意见","text":"《经办责任处理意见》草稿：确认书差异由经办人管若兰个人承担，周一前劝其离职。铅笔批：“别让她早知道。”"},{"id":"c_study2","title":"日程本","text":"周六：16:50子骞；17:00茶；17:15戚送文件；17:40取黑夹→17号箱；18:00封库。杯垫有水渍，杯不在。"},{"id":"c_study3","title":"柜子里的白酒","text":"文件柜里一瓶开过的白酒，旁边是降压药盒，药按日剥到周六早上。"},{"id":"c_study4","title":"渠道费用核对表","text":"邬子骞名下十一个客户的渠道费用表，合计31.4万。柯批：“随周一审计材料报送，先通知本人。”"}]},{"id":"kitchen","name":"茶水间与保洁间","scene":"kitchen","desc":"走廊尽头的茶水间，连着保洁储物间，堆着拖把桶和压扁的纸箱。","clues":[{"id":"c_kit1","title":"行长的盖杯","text":"消毒柜里刻“柯”字的白瓷盖杯，洗得发亮，盖沿凹槽里留着白色细颗粒。"},{"id":"c_kit2","title":"回收袋里的药盒","text":"回收袋里有撕破的药房纸袋和空药盒，印“镇静催眠”。小票：患者霍桂英，67岁，周三。"},{"id":"c_kit3","title":"茶水间白板","text":"白板：“17:00行长茶——若兰”；保洁17:35收茶水间垃圾。茶具旁条子：“只许若兰动”。"}]},{"id":"audit","name":"审计工作间","scene":"library","desc":"临时腾出的小会议室，长桌上摞着凭证，白板画着审计流程图。","clues":[{"id":"c_aud1","title":"三份库存确认书","text":"三份确认书盖“账实相符”，经办管若兰、复核柯正庭，日期补填“周五”，墨色不同。桑批：差额约240万。"},{"id":"c_aud2","title":"审计谈话记录","text":"桑的笔记15:40：管若兰问口头指示签了假确认书责任算谁（答：签字人），指示人“不在了”怎么认定（答：看书面证据）。"},{"id":"c_aud3","title":"盘库计划","text":"时间锁方案“行长办公室周二拟稿送副行长，周三柯、殷确认”。名单备注：管“周六晚回老家，周日13:55前返”。"}]}],"suspects":[{"id":"yin","name":"殷鹤年","role":"副行长","age":51,"look":{"skin":"light","hair":"sidepart","hairColor":"black","glasses":"rect","beard":"none","outfit":"suit","acc":"tie","mood":"stern"},"bio":"老城支行副行长，持A钥，在行里二十多年。封库时参与清库，案发后第一个提出保护现场。","demeanor":"官腔稳重，爱说“按程序”，被追问时扶眼镜。","topics":[{"id":"t_role","q":"你和柯行长的关系？","a":"共事十一年。他是行长，我是副手，该他拍板的我从不越线。人没了，我心里也不好受，这不假。"},{"id":"t_sweep","q":"封库前你清过库吗？","lie":true,"a":"清库我亲自走的，主厅、货架、保管箱间一处没落，确认没人才插的钥匙。这是按程序办的。","truth":"我没走完。保管箱间口，我看见他靠着箱子，眼睛半睁，抬手含糊说“你们先……”。我当他又犯头晕，没去拽他。"},{"id":"t_dizzy","q":"行长身体怎么样？","a":"血压高，常年吃降压药。上个月开会晕过一回，缓了几分钟，还叮嘱我别声张出去，怕人说他老了。"},{"id":"t_call","q":"封库后联系过他吗？","needs":["ask:yin.t_sweep"],"a":"18:20我打了两次电话，没人接。我当他回家睡了。早知道，我该叫上戚主管一起进去看看。"},{"id":"t_lock","q":"时间锁怎么定的？","a":"周三我和行长设的，周日14:00。总行要盘库，盘库前库存不许人碰。设完谁也改不了。"},{"id":"t_rank","q":"想过接他的位置吗？","a":"年纪到了该退让。行长三年没给我报职级，要说没怨气是假的，可我没为这个说过半个字。"},{"id":"t_lockwho","q":"方案谁提的？","needs":["clue:c_aud3"],"a":"周二行长办公室送来一页方案，建议上时间锁。我看稳妥，周三给行长，他点头。没署名，我没追问。"},{"id":"t_guilt","q":"你为什么不早说？","needs":["ask:yin.t_sweep","clue:c_cam1"],"a":"开库那刻我就知道他在里面。封库前我还见过他，却说不出口，怕人说是我把他给关死的。"}],"confronts":[{"clue":"c_cam1","breaks":"t_sweep","a":"他盯着屏幕里弯腰的人影：“是我。我看见他了。”揉着太阳穴，“他摆手说你们先走，我就信了。”"},{"clue":"c_hall2","a":"“清库签名，两人画了钩。”他指着最后一行，手有些抖，“那个钩，我是闭着眼画的。”"},{"clue":"c_vault3","a":"“门一合，锁一设，谁都打不开。”他声音哑了，“我们要是多等一分钟，重新开一次门……”没说完。"},{"clue":"c_study3","a":"“降压药和应酬酒。”他看了一眼，“他平时不怎么喝，这药吃了很多年，没出过岔子。”"},{"clue":"c_aud3","a":"“方案是行长办公室送来的，我只是照章办……”他停住了，低声重复了一遍，“照章办。”"}],"fallback":"这个不在我职责范围，按程序你得去问别人。"},{"id":"qi","name":"戚韵","role":"风控主管","age":46,"look":{"skin":"light","hair":"bob","hairColor":"black","glasses":"rect","beard":"none","outfit":"suit","acc":"badge","mood":"stern"},"bio":"风控主管，风控主管，持B钥，直来直去，行里没人不怕她的黑皮笔记。封库时与殷鹤年一起清库。","demeanor":"干脆利落，语速快，爱说“我是风控”。","topics":[{"id":"t_role","q":"你负责什么？","a":"风控。贷款、库存核对，该盯的我盯。不讨喜我知道，可银行出事，哪回是不讨喜的人惹的？"},{"id":"t_close","q":"封库那天的情形？","lie":true,"a":"17:54我和殷副行长一块清的库，主厅、保管箱间都过了，没人。我是风控，什么时候马虎过？","truth":"我没进去。库门口我在接孩子的电话，他发烧。殷副行长说“看过了”，我就画了钩。保管箱间我没亲眼看。"},{"id":"t_rush","q":"封库有什么异常？","a":"押运车原定16:30，通知改到17:30。柜员点钞排到17:57，我们是掐着点清库的，没几分钟。"},{"id":"t_doc","q":"17:12你去行长室？","a":"送风险评级文件。他在喝茶，嫌了句“今天这茶发苦”，说话还正常，还让我周一别摆黑脸。"},{"id":"t_loan","q":"你的报告有问题？","lie":true,"a":"我的报告每页都有依据。有人说我改过数字，那是外行不懂，评级本来就是动态的，调整是常态。","truth":"我改过一笔评级。邬子骞的大客户，从“关注”调成“正常”，是行长电话要求的，没留书面。这和他的死无关。"},{"id":"t_yin","q":"殷副行长清库时有异常？","needs":["ask:qi.t_close"],"a":"他进去时脸色正常，出来嗓子有点哑，说“都看过了，签吧”。我还以为他嫌我在门口打电话。"},{"id":"t_audit","q":"你怎么看这次审计？","a":"我盼着审计早点来，该查就查。不过这次行长盯库存确认书盯得格外紧，我在这行头一回见。"}],"confronts":[{"clue":"c_hall2","breaks":"t_close","a":"她盯着“17:54清库”：“这钩是我画的。我没亲眼看库里，孩子在发烧，我在门口。”"},{"clue":"c_cam1","a":"她看着屏幕里低头的自己，脸色发白：“我一直在看手机，没往里走。我要是走进去……”"},{"clue":"c_aud1","breaks":"t_loan","a":"她翻了翻确认书：“这不是我的事，我只管评级。”停了停，“邬子骞那笔是我改的，行长要的。”"},{"clue":"c_vault3","a":"“关门，插钥，设定，面板写得清楚。”她声音很低，“我手里还攥着手机，转身都没回头。”"},{"clue":"c_hall1","a":"“改点的通知写的是行长办公室，我觉得怪，也不好多问。”她皱眉，“库房最忌临时改点。”"}],"fallback":"这个跟我的职责无关，你问对人。"},{"id":"wu","name":"邬子骞","role":"客户经理","age":29,"look":{"skin":"tan","hair":"messy","hairColor":"black","glasses":"none","beard":"stubble","outfit":"shirt","acc":"tie","mood":"smirk"},"bio":"老城支行最能拉业务的客户经理，嘴甜，手里握着一百多个客户。称周六下午在大堂接待客户。","demeanor":"油滑爱笑，口头禅“哥们儿”，被戳穿时先打哈哈再叹气。","topics":[{"id":"t_role","q":"你负责什么业务？","a":"理财和对公，管着一百多家客户。哥们儿，这行靠关系吃饭，谁手上客户多，谁说话就大声。"},{"id":"t_visit","q":"下午去过行长室吗？","lie":true,"a":"没有，整个下午我一直在大堂陪客户，咖啡都喝了三杯。行长室没事我不上去，怕他念叨我。","truth":"我去了，16:50到17:05，求他别把我的“渠道返点”单送审计。他不松口，我被撵出来，腿都软了。怕被当成动机，才没说。"},{"id":"t_money","q":"你为什么怕审计？","needs":["ask:wu.t_visit"],"a":"我拿了稳盈产品的渠道返点，三十来万，违规。行长说周一照章报送，他一没，那单子落谁手里我没底。"},{"id":"t_tea","q":"你在行长室喝茶没？","needs":["ask:wu.t_visit"],"lie":true,"a":"我没喝，那是行长的茶。桌上有一杯，没人动过，他只顾骂我，杯子碰都没碰，我走时他好好的。","truth":"我没碰，他喝了。她送茶进来，他当场端起就喝，皱眉说“发苦”，边喝边骂我。我走时杯里剩小半。"},{"id":"t_ye","q":"周六晚你在哪儿？","a":"19点前回家，打游戏到半夜，外卖单和代驾单都在手机里，你们尽管去查，我真没兴趣。"},{"id":"t_guan","q":"你和管秘书熟吗？","a":"熟，她跟行长十几年，大小事都她经手。我们想约行长，都得先过她这关。人挺好，就是最近黑眼圈重。"}],"confronts":[{"clue":"c_cam2","breaks":"t_visit","a":"他看着监控里16:50走进行长室的自己，挠头：“行吧，你们连走廊都不放过。我去了，求他保我。”"},{"clue":"c_study2","a":"他瞟了眼日程：“‘子骞’是我，约的16:50，我没敢迟。”吸口气，“我可没动他的杯子。”"},{"clue":"c_vault1","breaks":"t_tea","a":"他盯着“胃里有茶叶渣”，喉结滚了滚：“行，他喝了，当着我的面。我是怕沾上边，杯子要有事，头一个问的就是我。”"},{"clue":"c_study4","a":"他一看抬头，脸色变了：“这单子他果然留着。”干笑，“我要想他闭嘴，犯得着在走廊里被拍下来？”"},{"clue":"c_aud1","a":"“确认书是行长和管秘书的事，我只管卖产品。”他摆手，“差额这种东西，我看见都绕道。”"},{"clue":"c_kit1","a":"“行长的杯子谁敢碰？”他撇嘴，“牌子写着专用。我进茶水间只倒了杯自己带的咖啡。”"}],"fallback":"哥们儿，这个我真不清楚，你别逼我。"},{"id":"li","name":"厉铁成","role":"押运队长","age":45,"look":{"skin":"tan","hair":"short","hairColor":"black","glasses":"none","beard":"stubble","outfit":"uniform","acc":"badge","mood":"tired"},"bio":"安保公司的押运队长，退役军人，负责这家支行的库款押运已有六年。周六押运车晚了一小时。","demeanor":"话少，爱说“按规矩”，一撒谎就盯着地面。","topics":[{"id":"t_role","q":"押运怎么交接？","a":"车到后场，我和库管当面点箱数、验封条，逐箱签字。每个环节两个人在场，少一个我不收。"},{"id":"t_late","q":"为什么晚到一小时？","lie":true,"a":"周六下午堵得厉害，主干道出事故，绕了好大一圈，17:41才到。耽误怪路，不怪人。","truth":"没堵车。我绕去实验小学，女儿发烧，老师一直打电话，我偷偷停了十九分钟送她。怕被通报，才说堵车。"},{"id":"t_change","q":"谁改了到达时间？","a":"周六三点多来电，女的，说行长办公室通知，改到17:30。我要行长签字，她说行长开会，她顶着。"},{"id":"t_woman","q":"那个女的是谁？","needs":["ask:li.t_change","clue:c_hall1"],"a":"声音我不熟。她说话很稳，像办了一辈子事。我当时还嘀咕，行长什么时候这么好说话了。"},{"id":"t_count","q":"交接时有异常吗？","a":"柜员排着队一箱箱搬，17:40后库里全是人。我站在后场一直看着库门，没见谁出来。"},{"id":"t_leave","q":"交接后你去哪儿？","lie":true,"a":"交完货我就走了，从后场把车开出去，直接回车队，路上还给老婆打了电话，说晚上回家吃饭。","truth":"我没走。17:58后借了后门钥匙，在后门抽了根烟，18:10才开车。怕队里知道我作业时间抽烟。"},{"id":"t_back","q":"后门抽烟看见什么？","needs":["ask:li.t_leave"],"a":"没见什么人。就17:50左右，一个拎包的女的从前面绕过去，往大街走，走得挺急。没看清是谁。"}],"confronts":[{"clue":"c_hall3","breaks":"t_late","a":"他垮下肩膀：“你们还看GPS。……是，我去了学校。十九分钟，我就想看孩子一眼。我认罚。”"},{"clue":"c_hall1","a":"他指着“17:41”：“时间是行长办公室改的。”停了停，“那通电话，声音是个女的，不是行长。”"},{"clue":"c_kit3","breaks":"t_leave","a":"他看着白板，咬了咬牙：“好吧，17:58后我在后门抽了根烟。保洁17:35收垃圾，我知道。”"},{"clue":"c_cam2","a":"“17:50前门出去的，是行长秘书吧。”他认了认，“我在后门看见她拎着包，走得快，没回头。”"}],"fallback":"这事不归我管，我们只管交接。"},{"id":"xi","name":"郗晨","role":"IT 维护员","age":31,"look":{"skin":"light","hair":"messy","hairColor":"black","glasses":"round","beard":"none","outfit":"hoodie","acc":"headset","mood":"tired"},"bio":"外包公司派驻的IT维护员，一人守着机房和报警系统。周六晚负责割接，称一直盯着机房。","demeanor":"熬夜脸，爱用技术词，被问责任就缩肩膀。","topics":[{"id":"t_role","q":"你负责什么？","a":"机房、网络、门禁、监控、报警，系统我一个人看。周末加班是想把割接做完，周一别掉链子。"},{"id":"t_panel","q":"接警主机什么状态？","lie":true,"a":"一直正常，指示灯全绿。割接那两个半小时本地告警是断的，但那是有预案的，不算故障。","truth":"主机从周五下午起就在检修态，我换板子忘了复原。周六才发现，可人已经困得不行。怕被通报，瞒了一天。"},{"id":"t_nap","q":"割接时你在做什么？","a":"脚本自动跑，我在机房兜底，中间在沙发眯了一小会儿。这个你别往外传，我怕被公司扣绩效。"},{"id":"t_btn","q":"应急按钮会响吗？","needs":["clue:c_vault4"],"a":"计数器是机械的，不靠网络，按一次走一格。停在0，就是没人按过。清醒的人十几步，谁都会按。"},{"id":"t_cam","q":"库内摄像头有盲区吗？","a":"主厅有一个，保管箱间没有，那是客户隐私区，装不了。我提过补装，预算一直批不下来。"},{"id":"t_swipe","q":"账号gr_0126是谁的？","needs":["clue:c_hall1"],"a":"这是个人账号，我查一下……是管若兰的，行长秘书。她常替行长在行内系统里操作各种申请。"}],"confronts":[{"clue":"c_cam3","breaks":"t_panel","a":"他盯着黄色标签，沉默三秒：“是我贴的。”蹭了蹭鼻子，“换板子忘了复原。我以为没事。”"},{"clue":"c_cam2","a":"“走廊录像？我只管硬件，不看内容。”他随口回，“要看谁进了行长室，找监控回放。”"},{"clue":"c_vault4","a":"他看了很久：“计数器是机械的，所以不影响。……我睡了一觉，不是故意的。”把头埋进手心。"},{"clue":"c_hall1","a":"“gr_0126。”他念了一遍，“这是正常授权的个人账号，至于谁在用，那不归我管。”"}],"fallback":"这个不是我这块的，你问问别人？"},{"id":"chu","name":"褚秀莲","role":"保洁员","age":61,"look":{"skin":"tan","hair":"bun","hairColor":"grey","glasses":"none","beard":"none","outfit":"apron","mood":"worried"},"bio":"外包进驻，在行里做了十二年保洁，认得每个人的杯子和脚步声。周六下午当班，称一直在打扫。","demeanor":"乡音重，爱说“莫”“哩”，紧张时擦手。","topics":[{"id":"t_role","q":"你在行里做什么？","a":"打扫，十二年了。大厅、走廊、茶水间都是我的地盘，行长们的杯子、字纸篓，我都认得。"},{"id":"t_trash","q":"垃圾怎么处理？","lie":true,"a":"都按规矩，封袋交给物业，我一样东西都没留。银行的东西，我一个扫地的哪敢拿？你们莫冤枉人哩。","truth":"我留了纸壳和瓶子，攒着卖，一个月几十块，补贴孙子学费。这是不对，可我一个人在城里打工。"},{"id":"t_tea","q":"谁给行长泡茶？","a":"若兰，只有她。那白瓷盖杯是行长专用，贴了牌子，别人碰了她会不高兴，我每次都绕开。"},{"id":"t_wash","q":"见过有人洗杯子吗？","needs":["ask:chu.t_tea"],"a":"周六五点二十左右，我进去换抹布，碰见若兰在水池洗那个盖杯，洗洁精打两遍。平常只冲冲水的。"},{"id":"t_bag","q":"回收袋里的药盒？","needs":["clue:c_kit2","ask:chu.t_trash"],"a":"17:35我收茶水间垃圾，从桶里捡的纸盒子。我当是普通药盒，塞进回收袋了。早知道多看一眼。"},{"id":"t_mother","q":"认识霍桂英吗？","needs":["ask:chu.t_bag"],"a":"若兰的妈妈，见过一回，瘦瘦小小。若兰每周三去药房给她取药，都是助眠的，说她妈夜里睡不着。"},{"id":"t_guan","q":"管秘书最近怎样？","a":"她这几天眼圈黑得吓人。周五晚我见她在行长室门口站了很久，手里捏张纸，没进去也没走。"}],"confronts":[{"clue":"c_kit2","breaks":"t_trash","a":"她低头在围裙上搓手：“好吧，是我留的。药盒也是我从垃圾桶里拣的，想着能卖。别记我的过。”"},{"clue":"c_kit1","a":"“那个杯子我不敢动。”她摇头，“牌子上写着只许若兰碰，我每天只擦台面，杯子连看都不敢看。”"},{"clue":"c_kit3","a":"“班表是我写的，没变过。”她点头，“若兰那天泡茶，16:58我在走廊看见她端着盘子。”"},{"clue":"c_cam2","a":"她眯眼看屏幕：“这是我，这是若兰。17:50她从前门走，拎着包，走得急，我还说怎么今天走这么早。”"}],"fallback":"这个我莫晓得哩，你问别个。"},{"id":"sang","name":"桑知白","role":"总行审计","age":38,"look":{"skin":"fair","hair":"sidepart","hairColor":"black","glasses":"round","beard":"none","outfit":"shirt","acc":"pocketwatch","mood":"neutral"},"bio":"总行外派审计员，周六一早到行，驻在临时审计间，周日14:00在场见证开库，只讲证据。","demeanor":"平静克制，措辞精确，爱说“证据显示”。","topics":[{"id":"t_role","q":"你为什么在这里？","a":"总行派我做专项审计。预审发现库存差异，周日盘库，周一汇报。我只认证据，不认人情。"},{"id":"t_talk","q":"和行内人私下聊过吗？","lie":true,"a":"没有。审计期间我不与被审单位人员私下交谈，所有问话都在审计间、有记录的情况下进行。","truth":"周六15:40管若兰来问过：按口头指示签了不实确认书，责任算谁。我答签字人承担。我没记入底稿，怕牵连她。"},{"id":"t_sec","q":"管若兰问了什么？","needs":["clue:c_aud2"],"a":"她问得很细：口头指示的效力，还有一句，指示的人若“不在了”怎么办。我说看书面证据。当时没多想。"},{"id":"t_gap","q":"库存差异有多少？","a":"系统与账面差额约240万。盘库验证前我不下结论，差额属实的话，三份确认书是第一份要查的。"},{"id":"t_sign","q":"确认书上的签名？","needs":["clue:c_aud1"],"a":"三份都写“周五”，字是同一支笔，却不是同一时间，像先签后补日期。谁让谁签的，要看书面。"},{"id":"t_open","q":"开库时你看见什么？","a":"14点两把钥匙一起转，库门外开，一股闷气。我站最前面，先看到箱间栅栏里有个人影。"}],"confronts":[{"clue":"c_aud2","breaks":"t_talk","a":"他合上笔记本：“是我记的。她问完，我没放进正式底稿，担心牵连一个什么都没做的人。”"},{"clue":"c_study1","a":"他把两页纸看了两遍，轻轻吸气：“如果这是柯行长周四写的，他已经决定让谁来承担了。”"},{"clue":"c_vault2","a":"他翻着账外往来簿：“两百四十万，跟预审的差额吻合。”低声念出，“最后一行写着，让管若兰补签。”"},{"clue":"c_aud3","a":"“时间锁是配合我盘库设的。”他摘下眼镜擦了擦，“没想到，它成了把所有人挡在外面的保险。”"}],"fallback":"这不在我的审计范围，我无法评论。"},{"id":"guan","name":"管若兰","role":"行长秘书","age":34,"look":{"skin":"fair","hair":"ponytail","hairColor":"black","glasses":"none","beard":"none","outfit":"dress","acc":"earrings","mood":"sad"},"bio":"行长秘书，跟了柯正庭十四年，人称“柯行长的影子”。周六傍晚回老家，周日13:55返行。","demeanor":"轻声细语，滴水不漏，情绪激动时会整理袖口。","topics":[{"id":"t_role","q":"你跟了行长多久？","a":"十四年了。他还是副行长时我就跟着，端茶跑腿记日程。外头说我是他的影子，也没说错。"},{"id":"t_leave","q":"周六你几点走的？","lie":true,"a":"17:30我就下班了，走前他说想回家，从后门走。之后的事我不知道，我赶高铁回老家，整夜陪我妈。","truth":"我17:50走的，前门。走前我提醒他：17:40下库，黑夹子别忘了放进17号箱。"},{"id":"t_tea","q":"那天你给他泡茶了吗？","lie":true,"a":"没有。那天他说胃不舒服，叫我不用泡，我就没动茶具，只进去送了份文件，放下就出来了。","truth":"泡了。16:58那杯，我加了母亲的镇静药。17:20撕了药盒扔掉，杯子洗了两遍。我只想让他睡一晚，可我知道他会下库。"},{"id":"t_deliv","q":"押运时间谁改的？","lie":true,"a":"行长亲口交代，说16:30太紧，调到17:30。我只是按他的意思在系统里提了申请。","truth":"是我自己改的，用我的账号，以行长办公室的名义。我要那个傍晚乱成一团，让清库的人腾不出眼睛。"},{"id":"t_alibi","q":"周六晚你在哪儿？","a":"18:41的高铁回老家，快20点到家，整夜陪我妈，邻居家人都能作证。周日13:55回到行里。"},{"id":"t_memo","q":"你知道处理意见吗？","needs":["clue:c_study1"],"lie":true,"a":"处理意见？我没见过。柯行长从没跟我提过这样的东西，他对我一直很好，怎么会写这个。","truth":"我看过。周五夜里打印日程，抽屉没关严，纸露了一半：“经办人个人承担”“别让她早知道”。我站着看了很久。"},{"id":"t_lockmemo","q":"时间锁方案谁拟的？","needs":["ask:yin.t_lockwho"],"lie":true,"a":"那是行长和殷副行长定的，我一个秘书不碰这些。方案是谁拟的、怎么送的，我真不清楚。","truth":"是我拟的。周二，一页纸，每个字都有规定依据，很稳妥。库一封，没人进得去，也没人出得来。"},{"id":"t_ask","q":"你为什么问审计那些？","needs":["ask:sang.t_sec"],"a":"我只是想弄明白，要是真出了事，我这种人要担多大责任。我问一句，有什么不对？谁不想自保？"},{"id":"t_final","q":"你恨他吗？","needs":["ask:guan.t_ask","clue:c_study1"],"a":"我不恨他。我只是不想再替他签字，不想进去，不想让我妈一个人。跟了他十四年，不该有这念头吗？"}],"confronts":[{"clue":"c_cam2","breaks":"t_leave","a":"她盯着自己拎包走出前门的画面，指尖在膝盖上收紧：“是17:50，我说错了。走得急，记差了。”"},{"clue":"c_kit1","breaks":"t_tea","crack":true,"a":"她看着杯盖凹槽里的白色结晶，嘴唇发抖：“我洗了两遍，以为洗干净了。我只想让他睡过去。”"},{"clue":"c_study2","breaks":"t_tea","crack":true,"a":"她看着日程本“17:00 茶”：“他记得很清楚。……是，我泡了。说他不喝，是怕你们问杯子。”"},{"clue":"c_aud3","breaks":"t_lockmemo","a":"她把“行长办公室周二拟稿”读了两遍，轻声说：“是我写的。”整了整袖口，“殷副行长信规定，不会追问。”"},{"clue":"c_kit2","breaks":"t_tea","crack":true,"a":"她看见药盒上母亲的名字，脸白了：“那是我妈的药。”闭上眼，“我以为扔进垃圾桶就没人看。”"},{"clue":"c_hall1","breaks":"t_deliv","a":"她看着“gr_0126”苦笑：“是我的账号。他从不管这种小事，我替他定了，他没说不行。”"},{"clue":"c_study1","breaks":"t_memo","a":"她盯着那两页纸，慢慢蹲下去，把脸埋进手里：“我看过，看了一整夜。他连我知道都要算计。”"},{"clue":"c_aud2","a":"“我问过桑审计。”她低声说，“只想弄明白，当事人不在了，责任是不是就没人追。别想得太重。”"},{"clue":"c_cam1","a":"她看着画面里扶墙的柯行长，眼睫颤了颤：“他走得很慢。”停了停，“我那时不在场，没看到。”"}],"fallback":"我只是个秘书，这个我不太清楚。"}],"solution":{"culprit":"guan","method":{"q":"凶手是怎么做到的？","options":["见行长昏沉靠在箱间却不声张，任双钥落下封死库门","在专用茶里下药，再改押运时间使清库仓促","趁行长独自喝茶无人看管时投药，等他自己下库","当面逼行长服药，趁封库混乱把人送进保管箱间"],"correct":1},"motive":{"q":"为什么杀人？","options":["多年被行长压着不给晋升，想顺势接手他的位置","私拿渠道返点被行长攥着，怕周一审计败露","被迫预签假确认书，又知行长要自己独自担责","家人买了行长力荐的理财亏光，要讨个说法"],"correct":2},"keyClues":["c_cam1","c_vault1","c_hall1","c_kit1","c_kit2","c_study1"],"truth":["凶手是行长秘书管若兰。柯正庭不是被失手关死的，他先被药放倒，再被时间锁和双钥封进了库。","殷鹤年看见了他却没拉一把，不是凶手：按钮计数为0，17:46他已扶墙走路。邬子骞与茶独处，但茶端进去时就已发苦。","16:58管若兰端茶进行长室，杯里掺了她母亲的镇静药，药盒署名霍桂英。药效发作，正是17:46柯扶墙进库。杯子洗了两遍，盖沿仍留结晶。","她又用账号gr_0126把押运改晚一小时，让清库仓促；周二拟的时间锁方案，让库成了无人进出的保险。17:50离开，18:41高铁，无懈可击。","动机：柯让她预签三份假确认书，缺口240万，还写好处理意见让她独担。她15:40问过审计，知道口头指示救不了自己。"]}},{"id":"casino","title":"第九局","tagline":"包间里赌客死在一手没发完的牌前，筹码箱少了一半，谁都像拿走它的人。","difficulty":4,"cover":"cv_casino","tone":"red","brief":"珊瑚角岛上，海湾酒店五楼有间不挂招牌的会员牌室“栖鸦会”。\n凌晨三点二十分，保镖在3号厅“雪松厅”发现地产商钟万山伏在百家乐桌上，左太阳穴塌陷，已经死了。牌只发到一半，筹码箱里一百枚十万码只剩五十枚。\n老板厉蓝把你请来：涨潮拦住了警长，六点才到，而钟万山六点就要飞走。她转着戒指说：“这里的客人都欠别人点什么。我只想在警察来之前，知道是哪一种。”\n你四点四十到达，监控、牌靴数据、出纳流水都没人动过。","victim":{"name":"钟万山","desc":"六十二岁，地产商，牌室最大的豪客。伏在雪松厅百家乐桌上，左太阳穴被钝器一击，西装内袋被人翻过。","look":{"skin":"tan","hair":"slick","hairColor":"grey","glasses":"none","beard":"none","outfit":"suit","acc":"pocketwatch","mood":"smirk"}},"publicFacts":["钟万山21:40进雪松厅玩私人百家乐，22:10买入100枚10万码筹码(序号4101–4200)，由荷官单青禾发牌。","03:19保镖巴图发现他死亡：左太阳穴一击。医生只敢说死于01:30至03:00之间，包间空调开到17度。","筹码箱只剩50枚，缺500万。现场没找到凶器。","雪松厅有两个入口：有监控的走廊正门，和荷官身后只能刷员工卡的侧门。","他的西装内袋被翻过，原本夹着数份会员借据。","祁安澜欠他1200万，他说过“天亮就收账”；裴七昨夜被他抓到出千；巴图当晚被解雇。","涨潮封了堤道，警长最早06:00到。岛上没有人离开酒店。"],"relations":{"shan":"雪松厅荷官，替他发了一晚牌","lan":"牌室老板，他是最大的豪客","batu":"跟了他七年的保镖，当晚被解雇","qi":"欠他1200万的女继承人","pei":"昨夜被他抓到出千的老赌客","rocha":"岛上博彩监管官，称只打过招呼","adi":"大厅吧台的酒保，当晚值班","qiao":"监管官罗查的随行翻译"},"links":[{"a":"rocha","b":"qiao","text":"监管官和他的随行翻译"},{"a":"qi","b":"pei","text":"裴七教过祁安澜两手牌技"},{"a":"lan","b":"shan","text":"牌室老板和她手下的荷官"}],"deathReport":{"time":"约 01:30–03:00","cause":"左太阳穴遭钝器一击","scene":"03:19保镖巴图推门，发现他伏在百家乐桌上，牌只发到一半，已无气息。","loc":"room","notes":["左太阳穴塌陷，一击致命，现场没找到凶器","西装内袋被翻过，借据不见了","包间空调开到17度，尸温难以判断死亡时间"]},"timeline":[{"t":"22:10","text":"钟万山在出纳处买入100枚10万码筹码，封条完整。"},{"t":"01:35","text":"监控拍到荷官单青禾按轮休离开雪松厅，钟万山仍坐在桌边。"},{"t":"02:00","text":"单青禾轮休结束，回大厅3号牌桌发牌，直到天亮。"},{"t":"02:18","text":"祁安澜刷会员卡进入雪松厅，02:21匆匆离开。"},{"t":"03:19","text":"巴图返回，发现钟万山死亡，报告老板。"},{"t":"04:40","text":"侦探(你)到达牌室。"},{"t":"06:00","text":"警长预计到达；钟万山原定同时乘机离岛。"}],"budget":{"search":12,"ask":26},"locations":[{"id":"room","name":"雪松厅","scene":"study","desc":"五楼最里面的私人包间，墨绿丝绒墙，半月形百家乐桌，冷得像冰柜。","clues":[{"id":"c_room1","title":"桌面与牌靴","text":"桌面整洁，两格各扣两张牌。牌靴歪在桌角，缺一角，缝里有褐红色，表面很亮。侧门虚掩，内侧有刷卡感应器。"},{"id":"c_room2","title":"牌靴读数","text":"01:31结算；01:49:12抽第4张；01:49:51脱座；01:52:03归位；此后无记录。此前每局整局抽牌。"},{"id":"c_room3","title":"铝制筹码箱","text":"铝箱只剩4101–4150共50枚，序号连续。箱盖标签：22:10封，100枚。锁无撬痕，钥匙插在锁上。"},{"id":"c_room4","title":"钟万山的小本子","text":"小本逐页记人：“罗查——签，500”“祁——1200，天亮收”“裴——退300，留一手”“单有福，海燕号，收船”。"}]},{"id":"cctv","name":"安保监控室","scene":"lab","desc":"酒店后场的小房间，一面墙的屏幕，门禁主机嗡嗡响。","clues":[{"id":"c_cctv1","title":"走廊正门回放","text":"罗查、乔晓棠(手插口袋)00:28进，00:52出；巴图01:20离岗；祁安澜02:18进。01:35–02:18无人。"},{"id":"c_cctv2","title":"服务梯门禁日志","text":"通道无摄像头。门禁：卡0731 01:46:20进五楼、01:56:48出；卡0728 01:44–01:57在酒窖门。"},{"id":"c_cctv5","title":"办公室门口回放","text":"01:37厉蓝端酒杯进办公室，02:09出来去洗手间，两分钟后回去；03:21冲出。其间无人进出这扇门。"},{"id":"c_cctv3","title":"大厅与酒廊回放","text":"大厅：01:03乔晓棠去出纳窗口；裴七01:20–02:30坐5号桌。酒廊：祁安澜00:50–02:10没离座。"},{"id":"c_cctv4","title":"停车场回放","text":"01:25巴图坐进黑色越野车，没熄火；无人下车或靠近。03:08他下车走向电梯。"}]},{"id":"cage","name":"出纳处","scene":"hall","desc":"厚玻璃隔开的小窗口，后面是保险柜，登记簿摊在窗边。","clues":[{"id":"c_cage1","title":"筹码兑付记录","text":"01:05兑付：10万码50枚，序号4151–4200，共500万，转入R.ROCHA咨询公司，经办人乔晓棠。"},{"id":"c_cage2","title":"买入单与封条","text":"买入单序号4101–4200，封条与铝箱一致。背面铅笔：“4101–4150无兑付”“4151–4200见01:05”。"},{"id":"c_cage3","title":"祁安澜的借据账","text":"借据账：祁安澜累计欠1200万，以家族公司股权抵押。红章：到期，钟万山可次日收账。旁注：她下午来求过缓。"}]},{"id":"hall","name":"大厅与吧台","scene":"dining","desc":"主赌厅，绿呢桌，灯光很低。吧台紧挨通往后场的小门。","clues":[{"id":"c_hall1","title":"当晚排班表","text":"排班表：单青禾轮休01:35–02:00，粉笔下露出旧数字01:35–01:55；朱的一栏也改过。角上有老板签“批”。"},{"id":"c_hall2","title":"吧台签单","text":"吧台挂账两张姜茶：01:41、01:58，都是单青禾签。酒保背面写：“01:42站了一会儿”“02:00前后”(划掉)。"},{"id":"c_hall3","title":"吧凳下的袖匣","text":"高脚凳下粘着一只弹簧袖匣，匣口夹着折小的纸牌，牌背是栖鸦会暗纹，牌面一角有针孔。"}]},{"id":"staff","name":"员工休息室","scene":"backstage","desc":"后场走廊尽头的窄房间，一排储物柜，空气里有姜茶味。","clues":[{"id":"c_staff1","title":"员工卡对照表","text":"员工卡对照表：0728阿迪，0729出纳，0730乔小姐，0731单青禾，0732巴图。“卡不外借，丢了立即上报。”"},{"id":"c_staff2","title":"单青禾的储物柜","text":"柜子没上锁，柜门内贴着旧合影：渔民站在蓝白小船旁，船头写着“海燕号”，背面只有一个年份。"},{"id":"c_staff3","title":"围裙与擦布","text":"围裙口袋里三块擦牌布，一块角上有褐色干渍，沾着灰白头发，有姜和酒精的味道。另两块洗过。"}]},{"id":"office","name":"老板办公室","scene":"library","desc":"厉蓝的办公室，红木桌，满墙账簿，保险柜半开着。","clues":[{"id":"c_off1","title":"单青禾的员工档案","text":"单青禾档案：三年前入职，原籍石屿渔村，父亲单有福，红笔批“已故，2022”。评语：手极稳，话极少，不要加薪。"},{"id":"c_off2","title":"会员借据档案","text":"借据档案：渔民单有福经钟万山介绍，借300万，抵押渔船“海燕号”，逾期收船。钟万山为介绍人，抽佣15%。"},{"id":"c_off3","title":"钟留下的便条","text":"保险柜里钟万山的便条：“牌靴里的东西我看见了。提成翻倍，别逼我找监管。”厉蓝批注：“先拖着，他六点就走。”"},{"id":"c_off4","title":"办公室座机记录","text":"座机通话单：01:41拨岛外号码，02:07挂断，共二十六分钟；03:20巴图内线打入，十一秒。"}]}],"suspects":[{"id":"lan","name":"厉蓝","role":"牌室老板","age":46,"look":{"skin":"light","hair":"long","hairColor":"auburn","glasses":"none","beard":"none","outfit":"qipao","acc":"earrings","mood":"smile"},"bio":"栖鸦会老板，五楼的实际主人。钟万山是她最大的客人，也最难得罪。案发时称在办公室。","demeanor":"圆滑温柔，爱叫人“亲爱的”，被问急了就转戒指。","topics":[{"id":"t_role","q":"钟先生","a":"亲爱的，他占这里三成流水，也是最难缠的一位。我留他到天亮，因为他六点要走。我犯不着让他死在这儿。"},{"id":"t_where","q":"凌晨在哪","a":"办公室对账，中间打过一通长途，一个人。保险柜我翻过，找一张便条……亲爱的，这个你们迟早知道，我先说。"},{"id":"t_rake","q":"他威胁你","lie":true,"a":"威胁？他对谁都笑眯眯的。他是客，我是老板，哪来的威胁。亲爱的，别把牌室想得太阴暗。","truth":"他拿牌靴的事压我。贵宾厅用过做了记号的牌，是不让输家一夜输光。他要我提成翻倍，不然找监管。"},{"id":"t_shan","q":"单青禾","a":"最稳的荷官，三年没出错牌，夜班从不迟到。我问她要不要加薪，她说“不用”。这种人最省心。"},{"id":"t_call","q":"那通长途","needs":["clue:c_off4"],"a":"打给岛外牌厂售后，问牌靴封条怎么对号。转了两次人，二十多分钟。我握着话筒，可没法分身。"},{"id":"t_break","q":"轮休你批","needs":["clue:c_hall1"],"a":"是我批的。她说手酸，想多歇五分钟。从不请假的人难得开口，我就点了头。朱那边也是我批的。"},{"id":"t_chips","q":"少的筹码","needs":["clue:c_room3"],"a":"我也想知道。每枚都有序号，拿去兑的人逃不过出纳。可要抢，为什么只拿一半，不整箱提走？"},{"id":"t_hist","q":"钟的旧客","needs":["clue:c_off2"],"a":"他介绍来的人我都记得：渔民、小贩、跑船的，借了就输，输了就签。生意是生意，人命是另一本账。"}],"confronts":[{"clue":"c_off3","breaks":"t_rake","a":"她盯着折过四折的便条，戒指不转了，笑了一声：“有这回事。可我杀他图什么？他六点就走。”"},{"clue":"c_off4","a":"“岛外牌厂，问牌靴封条怎么对号。”她松口气，戒指又转起来，“我半夜打，怕天亮钟先生先开口。”"},{"clue":"c_hall1","a":"“那栏我改的。”她很坦然，“如果知道她要做什么，我只会拦她。”垂下眼，“我以为她只是累了。”"},{"clue":"c_off2","a":"她看了很久，嘴唇抿成一线：“那个渔民签字时手在抖。没想到，还有人替这笔账记了三年。”"},{"clue":"c_cctv5","a":"她看着自己端酒进门的画面笑了：“要动手的人，不会给自己留这么多镜头。”戒指转了半圈，“批假我认。”"}],"fallback":"亲爱的，这个你得问别人，我真的记不清。"},{"id":"batu","name":"巴图","role":"保镖","age":38,"look":{"skin":"tan","hair":"short","hairColor":"black","glasses":"none","beard":"stubble","outfit":"suit","acc":"headset","mood":"stern"},"bio":"钟万山的保镖，跟了七年，魁梧寡言。守雪松厅门外，03:19进去发现尸体，称没离过岗。","demeanor":"口音重，句子短，爱说“成”“没事”，说到老板时低头。","topics":[{"id":"t_role","q":"跟了多久","a":"七年。他救过我一回，我替他挡过两回。嘴上骂人，给我妈的钱从来没断过。成，我欠他的。"},{"id":"t_post","q":"整晚在哪","lie":true,"a":"门口，一步没动。他进门到我进去，我都在走廊站着。没人进，没人出，我看着的，错不了，成。","truth":"01:20他骂我放祁小姐进去哭了十分钟，让我滚。我没脸待着，下车库坐车里，03:08才回楼上。"},{"id":"t_fire","q":"为何赶你","lie":true,"a":"没赶。他心情不好，叫我去歇会儿，我就去了。我不会背着老板干别的……成，没事，你往下问。","truth":"赶了，头一回。我放祁小姐进去，被他听见全程，骂我吃里扒外，七年白养了。我红着眼出的门。"},{"id":"t_qi","q":"放过祁安澜","needs":["ask:batu.t_post"],"a":"放过。九点多她求我，就五分钟，说她爸走后没人替她说话。我心软了，不是收钱，她像我妹。"},{"id":"t_found","q":"怎么发现","needs":["clue:c_cctv4"],"a":"03:08我上来想认个错。到门口，里头静得不对。推门，他趴在桌上，脖子凉的，硬的。我吼了一嗓子。"},{"id":"t_door","q":"侧门","needs":["clue:c_room1"],"a":"那是荷官进出的门，要刷员工卡。侧门从来不归我管，我管客人。成，你说我疏忽，我认。"},{"id":"t_card","q":"你的卡","needs":["clue:c_staff1"],"a":"0732是我的，能开侧门，可那头我七年没碰过。卡一直在外套里，我坐在车里，停车场灯你们翻得到。"},{"id":"t_money","q":"筹码的事","a":"听过。钟先生有时把筹码一把一把递给人，说是“辛苦费”。我不问，不看，不碰。谁拿，谁兑。"}],"confronts":[{"clue":"c_cctv4","breaks":"t_post","a":"他盯着屏幕里自己的车缩了一下：“成，我撒谎了。我在车里坐了快两个钟头，没脸上去。”"},{"clue":"c_cctv1","breaks":"t_fire","a":"“01:20我离岗。”他看着时间戳，闷声说，“是他把我骂出来的。七年了，第一次。”他抹了把脸。"},{"clue":"c_room1","a":"“侧门……”他皱眉，“荷官的门，我不管。你们是说，有人从那边进去？成，我没看见，也不敢说有。”"}],"fallback":"没事，你问吧，但这个我真不知道。"},{"id":"qi","name":"祁安澜","role":"女继承人","age":29,"look":{"skin":"fair","hair":"ponytail","hairColor":"brown","glasses":"none","beard":"none","outfit":"dress","acc":"earrings","mood":"worried"},"bio":"食品集团继承人，欠钟万山1200万。02:18被拍到进过雪松厅，是最惹眼的嫌疑人。","demeanor":"语速很快，爱抢话，紧张时夹英文，“I swear”“listen”。","topics":[{"id":"t_debt","q":"欠多少","a":"一千两百万，I know。我爸走后股价被做空，我赌气上桌想翻本，越陷越深。他说天亮就收，抵家里股份。"},{"id":"t_room","q":"去过雪松厅","lie":true,"a":"没有。我整晚在酒廊，喝了两杯，哭了一场。Listen，我欠他钱，不是欠他命，没理由去。","truth":"去了两次。九点巴图放我进去求缓，被拒。02:18我再去，进门他已死在桌上，我吓得拿了自己的借据就跑。"},{"id":"t_slip","q":"拿了什么","lie":true,"needs":["ask:qi.t_room"],"a":"什么也没拿，我对天发誓，I swear。你们爱搜身就搜，我一张纸都没带出来，真的。","truth":"我拿了借据。他内袋那叠纸，最上面一份是我的，我抽了出来，其余没动。I swear，我没想杀他。"},{"id":"t_seen","q":"看见什么","needs":["ask:qi.t_room"],"a":"冷。牌扣着，摆得整整齐齐，牌靴亮得像刚擦过，荷官身后的门虚掩着。那种整齐，不像刚死过人。"},{"id":"t_money","q":"筹码箱","a":"箱盖开着，空了一半。我当时只想着，他们会说是我拿的。所以我才跑，没喊人。我是懦夫，我知道。"},{"id":"t_dealer","q":"单青禾","a":"她发过我很多牌，很安静。有次我输惨了，她替我码好筹码，轻声说“别追”。她是唯一没骗过我的人。"},{"id":"t_pei","q":"认识裴七","a":"瘸腿老头？他教过我两手，说赌桌上最危险的是自己的手。昨天被钟当众揭穿，他看钟的眼神像在算坏账。"}],"confronts":[{"clue":"c_cctv1","breaks":"t_room","a":"她看着自己进出的画面，脸白了：“OK，是我。Listen，我进去时他已经没气了。”"},{"clue":"c_cctv3","a":"“你们连酒廊都看了。”她愣住，“我坐那儿一个半钟头，什么都没想，就盯着窗外的浪。I swear。”"},{"clue":"c_room4","breaks":"t_slip","a":"她看着“祁——1200”，鼻尖红了：“对，是我拿的。I swear，我只拿了自己的那份。”"},{"clue":"c_room2","a":"她盯着01:49:12，倒吸一口凉气：“那时我还在酒廊……他在我进去前就死了？Oh my god。”"}],"fallback":"I do not know, really。我现在脑子是乱的。"},{"id":"pei","name":"裴七","role":"职业老千","age":55,"look":{"skin":"tan","hair":"slick","hairColor":"silver","glasses":"round","beard":"mustache","outfit":"vest","acc":"pocketwatch","mood":"sly"},"bio":"微跛的老赌客，混迹牌室三十年。昨夜被钟万山抓到出千，退了三百万。称自己早早离开。","demeanor":"粤式江湖腔，爱叫人“后生仔”，被揭穿也笑。","topics":[{"id":"t_role","q":"靠什么吃饭","a":"后生仔，讲句公道话，我是赌客。赌了三十年没被人砍过手，全靠一条：该走就走。后生仔，记住。"},{"id":"t_cheat","q":"昨天出千","lie":true,"a":"出千？冤枉啊。钟生那天心情不好，看谁都像贼。我这双手只摸牌，不摸别人的钱，你去问荷官。","truth":"出过。弹簧袖匣换牌，二十年没失手，偏偏碰上钟万山，一眼看出袖口角度。他叫我退三百万，说“留你一手”。"},{"id":"t_leave","q":"几点离开","lie":true,"a":"十二点前就走了，输得精光，在酒吧坐到天亮。没回去过，也没再见到钟生，我可没那个胆。","truth":"我00:10离开的，他让我在大厅“替他看着点人”。我01:20起一直坐5号桌。没回去，这点不假。"},{"id":"t_sleeve","q":"袖匣呢","needs":["clue:c_hall3"],"a":"丢了，走得急，随手塞到吧凳下，跟酒保说了两句让他收着。后生仔，老千的东西不是证物，是尴尬。"},{"id":"t_dealer","q":"单青禾","a":"好手，我见过一千个荷官，她最稳，手腕不抖，呼吸不乱。可惜了，这样的人我从没见她笑过。"},{"id":"t_old","q":"钟万山","a":"他一辈子赢，赢得人心寒。我听他问过荷官：“你是不是觉得我欠你的？”她笑说“钟先生说笑”。"},{"id":"t_alibi","q":"那段时间","needs":["clue:c_cctv3"],"a":"我在5号桌，摄像头拍得清清楚楚。我这条腿走一趟五楼要多久？后生仔，你们算算，不要冤枉我。"}],"confronts":[{"clue":"c_hall3","breaks":"t_cheat","a":"他一眼认出袖匣，苦笑：“叫人收起来也收不好。好，这是我的。可是钟生抓我，不是我抓钟生。”"},{"clue":"c_cctv3","breaks":"t_leave","a":"“看见了吧？5号桌，不是吧台。好，我认。”他笑，皱纹挤成一团，“可我屁股没挪过窝。”"},{"clue":"c_room4","a":"他翻到“裴——退300，留一手”：“就是叫我在厅里看人。我00:10被放出来，没再上过五楼。”"}],"fallback":"后生仔，这个我不知道，不要问我。"},{"id":"rocha","name":"罗查","role":"博彩监管官","age":52,"look":{"skin":"brown","hair":"sidepart","hairColor":"grey","glasses":"rect","beard":"mustache","outfit":"suit","acc":"badge","mood":"stern"},"bio":"岛上博彩监管署巡查官，以“例行检查”留在栖鸦会，靠翻译交谈。称与钟万山只打过招呼。","demeanor":"官腔，先说条款再说事，由乔晓棠转述，语速慢而冷。","topics":[{"id":"t_role","q":"来做什么","a":"依据本岛博彩条例第三款，监管署可不预先通知巡查持牌场所。今晚我只是履行职责，别无其他。"},{"id":"t_room","q":"见过钟万山","lie":true,"a":"只在大厅见过一面，点头致意，没有交谈。我对任何会员都保持距离，这是监管官的纪律。","truth":"00:28我进了雪松厅。他要我对牌靴检查“宽容些”，让翻译拿走一袋筹码，称“咨询费”。我收了。"},{"id":"t_chips","q":"筹码的事","lie":true,"a":"听说五百万不见了。作为监管官，我只关注资金流向。对那笔钱我一无所知，也与我无关。","truth":"那五百万是我的，他亲手给的，翻译替我兑了。我没杀他。他死了，这笔钱的来路反而谁都能查。"},{"id":"t_time","q":"案发时在哪","a":"贵宾酒廊，01:10到02:00，我与翻译喝咖啡，摄像头可证明。之后回房间，直到被通知。"},{"id":"t_rule","q":"牌靴检查","needs":["clue:c_off3"],"a":"每年两次抽查，去年合格，今年报告未交。有人要我写“合格”，我会考虑；写“不合格”，我也会考虑。"},{"id":"t_hate","q":"你会杀他吗","a":"监管官杀人，职业就终结了。我五十二岁，离退休只剩三年，不会做这种蠢事，也没有理由。"}],"confronts":[{"clue":"c_cctv1","breaks":"t_room","a":"翻译念出“00:28进，00:52出”，他的脸像冻住，才让乔晓棠转述：“我去过，是被邀请。”"},{"clue":"c_cage1","breaks":"t_chips","a":"他看着R.ROCHA咨询公司那行，缓缓摘下眼镜：“这是我的钱。条例没禁止收咨询费，只禁止不申报。”"},{"clue":"c_cctv3","a":"“01:03乔去出纳处，是我让的。”他靠回椅背，“我没离开过座位，酒廊的摄像头会证明。”"}],"fallback":"依据条例，此问题不在今晚的范围内。"},{"id":"adi","name":"阿迪","role":"酒保","age":27,"look":{"skin":"brown","hair":"curly","hairColor":"black","glasses":"none","beard":"none","outfit":"vest","acc":"bow","mood":"smile"},"bio":"岛上长大的年轻酒保，话多手快，吧台正对后场小门。称整夜守着吧台，见过单青禾点姜茶。","demeanor":"话痨，语速快，爱用“真的啦”“哎呀”，被问到痛处就擦杯子。","topics":[{"id":"t_role","q":"你做什么","a":"调酒、记账、给荷官们泡茶，哎呀，什么都做。夜班没几个人说话，我就跟杯子说话，真的啦。"},{"id":"t_tea","q":"她的姜茶","a":"她轮休必点一杯，不加糖。今天点了两杯，01:41一杯，01:58又一杯。第二杯她站着端了就走。"},{"id":"t_watch","q":"她在不在","lie":true,"a":"在啊，休息室的门正对吧台，她一直坐里面，我一抬头就看见。哎呀，我盯着门像盯着钱，真的啦。","truth":"没那么准。01:44我下酒窖，十几分钟才上来，吧台没人。怕老板说我擅离岗位，才说一直在看。"},{"id":"t_sleeve","q":"凳下的东西","lie":true,"a":"什么东西？我没见过啊，真的啦。昨晚客人那么多，掉点东西很正常，我哪能每样都留意。","truth":"是裴七的袖匣。他走前塞我两千，叫我帮他收着。我怕得很，粘在凳子下，想等散场丢进海里。"},{"id":"t_door","q":"谁走过小门","needs":["ask:adi.t_watch"],"a":"小门通后场，员工刷卡就开，没有响声。我只看见乔小姐一点钟前后走过，别的我没留意。"},{"id":"t_shan","q":"她这个人","a":"安静的人。我问过她为什么不笑，她说“笑了，别人就看出你在想什么”。我当时听不懂，现在还是不太懂。"},{"id":"t_ginger","q":"为何下酒窖","needs":["ask:adi.t_watch","clue:c_cctv2"],"a":"青禾姐说姜快见底，问我能不能去酒窖拿一箱新的，说不急，慢慢找。箱子压在最底下，翻了好一阵。"}],"confronts":[{"clue":"c_hall2","breaks":"t_watch","a":"他看着票背面自己写的字，手里的杯子停住：“哎呀，被看出来了。我下过酒窖，十几分钟。我是怕丢工作。”"},{"clue":"c_hall3","breaks":"t_sleeve","a":"他脸一下垮了：“真的啦……是裴先生给我的，我收了他两千，什么也没问。别告诉老板，我想收班就扔掉。”"},{"clue":"c_cctv2","a":"“0728是我的卡，酒窖那扇门。”他赶紧说，“五楼我上不去，那张卡没开通，真的啦。”"},{"clue":"c_staff1","a":"“0731是青禾姐。”他笑得勉强，“她的卡很干净，从来没丢过。……哎呀，我说这个干嘛。”"}],"fallback":"哎呀，这个我真不清楚，你问别人吧，真的啦。"},{"id":"qiao","name":"乔晓棠","role":"翻译","age":31,"look":{"skin":"light","hair":"bob","hairColor":"black","glasses":"rect","beard":"none","outfit":"suit","acc":"scarf","mood":"worried"},"bio":"会四种语言的翻译，当晚替罗查转述所有谈话。称整夜没离开过罗查身边，没碰过任何筹码。","demeanor":"逐字准确，措辞谨慎，被问急了说“我的职责是”，紧张时摸耳垂。","topics":[{"id":"t_role","q":"你做什么","a":"同声翻译，兼客务联络。我的职责是把别人的话原样搬到另一种语言，不加意见，不少一个字。守了八年。"},{"id":"t_cage","q":"去过出纳处","lie":true,"a":"没有。我整晚跟着罗先生，不是在酒廊就是在大厅。出纳处的事跟我无关，我不碰筹码，也不碰钱。","truth":"去过。01:05我替罗先生兑了五十枚筹码，签了名。我没想过拒绝。撒谎是怕被当成同伙。"},{"id":"t_room","q":"进过雪松厅","a":"00:28随罗先生进去过，00:52离开。他们的话我都记得。但“该记得的”和“该说出来的”是两回事。"},{"id":"t_rec","q":"有录音吗","lie":true,"needs":["ask:qiao.t_room"],"a":"没有，我从不用录音设备。我的记忆就是录音，八年没出过一次差错，请你不要怀疑这一点。","truth":"有。进门前我按了手机录音。我不想一辈子替人传话，传的还是见不得光的话。打算离岛时交给监管署上级。"},{"id":"t_minnan","q":"听到什么","needs":["ask:qiao.t_cage","clue:c_cage1"],"a":"荷官倒酒时用闽南话低声问钟先生：“您还记得海燕号吗？”他笑着回：“哪条船？每年收的船太多了。”"},{"id":"t_shan","q":"单青禾","needs":["ask:qiao.t_minnan"],"a":"她说那句话时，嗓子是平的，像背了三年的台词。我当时以为是同乡寒暄，现在……不愿往下想。"},{"id":"t_dev","q":"会闽南话吗","a":"会，我母亲是泉州人。岛上会闽南话的不多，荷官单小姐是其中一个，所以我对她印象深。"}],"confronts":[{"clue":"c_cage1","breaks":"t_cage","a":"她看着自己的签名，摸了摸耳垂：“……是我。罗先生说是咨询费，让我去兑。我什么也没问，两样都做错了。”"},{"clue":"c_cctv1","breaks":"t_rec","a":"她盯着画面里插在口袋的手，沉默半晌：“手机开着，有录音。给你可以，但别让罗先生知道是我给的。”"},{"clue":"c_staff2","a":"她指尖按在“海燕号”三个字上：“就是这个。她在包间里问的就是这个。我早该意识到，那不是寒暄。”"}],"fallback":"这不在我的职责范围里，我不便转述。"},{"id":"shan","name":"单青禾","role":"荷官","age":34,"look":{"skin":"light","hair":"bun","hairColor":"black","glasses":"none","beard":"none","outfit":"vest","acc":"bow","mood":"neutral"},"bio":"雪松厅荷官，手稳话少，上了三年夜班。为钟万山发牌，01:35轮休，02:00回桌。","demeanor":"话短，用行话，眼睛盯着你的手而不是脸。","topics":[{"id":"t_role","q":"你的工作","a":"发牌，收码，盯桌。贵宾厅的客人图个安静，图个准。钟先生点名要我发他的牌，一发大半夜。"},{"id":"t_last","q":"最后见他","a":"01:35我轮休。他说回来把这靴发完，抬了下手，我就出去了。后来的事，是听老板说的。"},{"id":"t_where","q":"轮休在哪","lie":true,"a":"吧台要了杯姜茶，回休息室坐着，哪儿也没去，02:00回桌。吧台的阿迪见过我，你问他。","truth":"我没一直待着。01:46刷0731上梯，从侧门回了雪松厅。01:56下楼，01:58再端一杯姜茶。"},{"id":"t_know","q":"认识钟先生","lie":true,"a":"没有。他是客，我是荷官，一年说得上三句话。他肯叫我名字，已是给面子。我来之前没见过他。","truth":"我认识。三年前我父亲单有福经他介绍借了三百万，丢了船，后来人也没了。他天天赢，没认出我。"},{"id":"t_shoe","q":"牌靴","lie":true,"a":"钟先生嫌我发得慢，有时自己伸手抽。最后几张可能是他抽的。我01:35就走了，不清楚。","truth":"没人自己抽牌，最后几张是我发的。他俯身想看我手里的牌，那是老毛病。我抡下去时没有犹豫。"},{"id":"t_lan","q":"老板待你","needs":["clue:c_hall1","clue:c_cctv5"],"a":"客气。我请假她就批，加了五分钟也没多问。别的事她一概不管，只要账平、人安静就好。"},{"id":"t_boat","q":"你家里","needs":["ask:qiao.t_minnan","clue:c_off2"],"a":"海燕号是我爸的船，开了三十年。收船那天他在码头坐了一整夜，第二年人就不在了，船也卖了。"},{"id":"t_card","q":"你的卡","needs":["clue:c_cctv2"],"a":"卡不外借，我的一直在围裙口袋里，没丢过。想说别人拿了它？那人得先知道我几点轮休。"},{"id":"t_cry","q":"后悔吗","needs":["ask:shan.t_boat","clue:c_staff2"],"a":"后悔？想了三年。真到那一下，我只想着把这手牌发完。发牌的人，是不能有表情的，你说是不是。"}],"confronts":[{"clue":"c_cctv2","breaks":"t_where","crack":true,"a":"她看着“0731”两行，沉默很久，把右手放平：“我以为没人会查这条通道。卡是我的，两次都是我。”"},{"clue":"c_room2","breaks":"t_shoe","a":"她的目光停在“01:49:12”那行，嘴角动了动：“靴会记账……做了这么多年，我倒忘了。”"},{"clue":"c_off2","breaks":"t_know","a":"她先看见借据角上的“单”字：“我爸认字不多，名字签得很大。”她把纸边对齐放好，“你们比我想的快。”"},{"clue":"c_staff2","a":"她指尖停在照片边：“柜子不上锁，里头没值钱的东西。这张，我每天看一眼。”然后把脸转向窗外。"},{"clue":"c_staff3","a":"“荷官天天擦牌靴，擦布上有点什么不奇怪。头发是我的，姜味是我擦手用的。”她看着那块布，没再说。"},{"clue":"c_hall2","a":"“姜茶是我的习惯。01:41一杯，01:58一杯，没错。”她顿了顿，“中间那一段，你们自己去算。”"}],"fallback":"这跟牌没关系的话，我不方便多说。"}],"solution":{"culprit":"shan","method":{"q":"凶手怎么做到的？","options":["欠债客人02:18进门争执，抢回借据时行凶，带走半箱筹码","荷官借轮休刷员工卡走侧门折返，趁他俯身用牌靴击杀","老板多批轮休留出空档，派手下走侧门行凶，自己在办公室作证","被解雇的守卫趁换岗从正门折返行凶，再躲回车里装作刚到"],"correct":1},"motive":{"q":"为什么杀人？","options":["死者拿牌靴的秘密要挟老板，老板买通身边人替自己动手","死者当晚给了好处又想收回，收钱的人为守住五百万下手","死者多年前的一笔借款逼得凶手亲人家破人亡，凶手改名潜伏","死者发现凶手在牌靴上做手脚，要告发追讨，凶手先下手"],"correct":2},"keyClues":["c_room2","c_cctv1","c_cctv2","c_cage1","c_staff1","c_off2"],"truth":["凶手是荷官单青禾。表面是赌债劫杀：祁安澜欠钟万山1200万，02:18进过包间，走廊01:35–02:18又无人进出，像是她下的手。","第一次反转是时间。牌靴日志显示钟万山死在01:49，而祁安澜00:50–02:10都在酒廊。五十枚筹码是01:05乔晓棠兑给罗查的“咨询费”，并非劫走。","时间一改，只剩荷官身后的侧门。门禁里卡0731于01:46:20上楼、01:56:48下楼，对照表是单青禾。她借轮休折返，趁钟万山俯身看牌，用牌靴砸死了他。","第二次反转是好心。厉蓝被勒索，批了轮休，但01:37起一直在办公室通话；多批的五分钟只遮住了01:58那杯姜茶。阿迪被她支去酒窖，才空出吧台。他们都不知情。","动机在三年前：她的父亲单有福经钟万山介绍借债，丢了渔船“海燕号”，跳海而死。她改名潜伏，只等他最后一夜。红鲱鱼的谎，各自只为掩盖小事。"]}},{"id":"liaoyang","title":"台风夜查房","tagline":"台风封山，院长死在反锁的屋里，唯一的目击者是个“看见鬼”的病人","difficulty":4,"cover":"coverHospital","tone":"green","brief":"一九八七年九月二十六日傍晚，你上青崖山来到松岚疗养院。院长顾清源曾来信：“药房账目似有蹊跷，望一见。”他说明早再谈。当夜台风封山，电话线断。零点五十五分，院长室反锁的门被劈开，他伏在桌前，右臂插着空注射器，已死。副院长说是吗啡过量。一个病人却拦住你：“我看见没有脸的人，提灯进了他的屋。”警察天亮才到，你只有这一夜。","victim":{"name":"顾清源","desc":"松岚疗养院院长，六十一岁，晚期胰腺癌，每晚自行注射吗啡止痛。零点五十五分被发现伏在书桌前，右臂插着空注射器，门自内锁死。","look":{"skin":"light","hair":"short","hairColor":"grey","glasses":"round","beard":"none","outfit":"labcoat","acc":"stethoscope","mood":"tired"}},"relations":{"yan":"跟了他十二年的副手，副院长","xue":"管病区的护士长，在院十七年","liang":"住了六年的老病人，退休教师","su":"住院四年的病人，他答应秋天放她出院","hong":"病人苏婉如的丈夫，来探视被困","wei":"院里的老护工，管开水和发电机","jian":"来院才六天的实习医生，帮他做化验","song":"管药房和管制药品柜十五年的药剂师"},"links":[{"a":"hong","b":"su","text":"夫妻，他来探视被困在院里"},{"a":"jian","b":"su","text":"昨晚九点给她打了安神针"},{"a":"wei","b":"xue","text":"台风夜一同值夜班"},{"a":"yan","b":"xue","text":"都知道院长病情的院内老同事"}],"deathReport":{"time":"约 22:30–00:50","cause":"吗啡过量，呼吸抑制","scene":"魏德贵零点四十叩门无应，与严仲谦劈开门，见院长伏在桌前，右臂插着空注射器，身体尚温。","loc":"study","notes":["瞳孔缩成针尖大小，口唇发绀","遗体尚温，尸僵刚开始出现","门自内锁，钥匙在桌面，窗闩着"]},"publicFacts":["松岚疗养院在青崖山腰，设三十四张床位；19:10山路塌方，19:40电话线被风刮断，警方明晨才到。","顾清源患晚期胰腺癌，只有严仲谦、薛玉芬、宋鹤龄知情，他每晚自行注射吗啡止痛。","院长室是弹簧门锁，一拉上就锁；钥匙放在桌面，窗内插销闩着。","22:00值夜护工魏德贵送水时院长还活着；22:30全院停电，只用马灯和手电。","严仲谦初验认为是吗啡过量，倾向意外或自戕；你的委托信提到“药房账目蹊跷”。","病人梁秋白称见“白衣无面人提灯进院长室”，但护理记录写他21:30已服镇静药，医护都说是旧病幻觉。"],"timeline":[{"t":"19:10","text":"山路塌方，疗养院被隔绝；19:40电话线被风刮断。"},{"t":"21:10","text":"严仲谦与院长在院长室谈话约半小时，魏德贵听见有人提高嗓门。"},{"t":"22:00","text":"魏德贵送开水，院长在世，吩咐零点半再送一壶。"},{"t":"22:30","text":"全院停电，改用马灯和手电。"},{"t":"22:45","text":"魏德贵巡廊一次（值班本记录）。"},{"t":"00:40","text":"魏德贵送水叩门无人应，去叫严仲谦。"},{"t":"00:55","text":"二人劈开院长室门，院长已死，右臂插着空注射器，桌上三支空安瓿。"}],"budget":{"search":12,"ask":26},"locations":[{"id":"study","name":"院长室","scene":"study","desc":"东头的院长办公室，书柜、铁皮保险柜和老式写字台，窗内插销闩着。雨幕压在玻璃上。","clues":[{"id":"c_s1","title":"右臂新针眼","text":"遗体伏在桌前。左臂布满陈旧针眼，右上臂只有一个新针眼，空注射器斜插其上。"},{"id":"c_s2","title":"空安瓿与抽屉","text":"桌角三支空安瓿，批号8706。右手抽屉里另有两支未开封的，批号8612。"},{"id":"c_s4","title":"台历与便条","text":"台历9月27日写着“晨八时 宋 带8612账册来”。压着半张便条：“严 收洪 每月八十元 核实”。"},{"id":"c_s3","title":"弹簧锁与烟蒂","text":"门一合就自动锁上，钥匙放在桌面。门外廊砖上落着四个“大前门”烟蒂。"}]},{"id":"pharm","name":"药房","scene":"clinic","desc":"西侧药房，玻璃药柜、天平，里间有铁皮麻醉柜，侧门通后院。","clues":[{"id":"c_p1","title":"麻醉柜清点","text":"柜钥匙在宋鹤龄腰间。8706批标牌写“存50支”，清点只有47支。"},{"id":"c_p2","title":"管制药品登记册","text":"每页边缘盖红色骑缝章。第38页纸色偏新，半枚红章与前后页对不上，页末写着“22:10 8706×3 顾清源亲领”。"},{"id":"c_p3","title":"厚底右布鞋","text":"门后一根手杖、一双布鞋，右鞋垫得很厚，前掌钉着菱形格纹胶皮。旁挂白大褂和口罩。"}]},{"id":"lab","name":"化验室","scene":"lab","desc":"后楼窄小的化验室，酒精灯、试管架和旧显微镜，窗外就是后院。","clues":[{"id":"c_l1","title":"化验申请与结果","text":"9月22日顾清源申请检验8612批吗啡。结果：含量约十分之一，余为氯化钠。检验人简若川。批示：“仅限你我知悉。”"},{"id":"c_l2","title":"化验记录本","text":"9月26日14:30：8706批含量合格。抄送联钉在后页，药房签收栏写“宋鹤龄 收 16:20”。"},{"id":"c_l3","title":"窗台马灯","text":"窗台一盏马灯，灯芯刚剪过。记录纸上有新铅笔字：“22:40 复检第二法”。"}]},{"id":"records","name":"病历档案室","scene":"library","desc":"一楼拐角的档案室，铁皮病历柜成排，值班桌上压着护理记录和值班本。","clues":[{"id":"c_r1","title":"夜班护理记录单","text":"9月26日夜班记录从21:00填到次日06:00，连凌晨的体温栏都已写满，字迹墨色一致。"},{"id":"c_r4","title":"夜间值班本","text":"魏德贵的字：“22:00 送水，院长在。22:45 巡廊，严副院长房里有人说话。23:00 在发电机棚歇。00:40 叩门无应。”"},{"id":"c_r3","title":"苏婉如病历夹","text":"苏婉如的病历夹被抽走，空槽里夹着院长的评估：“病情稳定，拟十月出院”，下压洪建国探视登记。"},{"id":"c_r2","title":"梁秋白病历","text":"医嘱“氯丙嗪100mg 睡前”，每日“已服”。病程记录：诉夜见白衣无面人持灯，视为幻觉。"}]},{"id":"ward","name":"梁秋白的病室","scene":"guestroom","desc":"男病区尽头的单人病室，窗正对走廊另一头。东西收拾得很整齐。","clues":[{"id":"c_w1","title":"梁的夜间笔记","text":"“22:00 老魏送水，其后廊下无人。22:20 白衣人蒙口罩，左手提灯，右脚拖着，自药房来，入院长室。22:52 出，门咔一声自合。22:54 另一人来敲门点烟，至23:15。23:40 后院有火光。”"},{"id":"c_w2","title":"缸底的药片","text":"床头搪瓷缸底压着三片半化的白色药片，床垫下还有一手帕包好的药。"},{"id":"c_w3","title":"怀表与窗","text":"窗台铜怀表，与大厅座钟只差一分钟。从床边看出去，正对院长室的门，无遮挡。"}]},{"id":"yard","name":"后院","scene":"garden","desc":"药房侧门外的后院，有焚化炉、发电机棚和被风吹倒的葡萄藤。","clues":[{"id":"c_y1","title":"焚化炉残页","text":"炉灰里一角没烧透的纸，带半枚骑缝章，页码“38”，残字“破损2支”“破损3支”，行末都有“薛玉芬 核”。"},{"id":"c_y2","title":"棚边酒瓶与脚印","text":"发电机棚草席旁一只空酒瓶。棚与药房侧门间的泥地有脚印：右脚浅，前掌菱形格纹，后连一道浅沟。"},{"id":"c_y3","title":"药房侧门","text":"侧门的门闩刚上过油，门槛内侧地砖上落着几点黑色纸灰，旁有半干的泥印。"}]}],"suspects":[{"id":"yan","name":"严仲谦","role":"副院长","age":55,"look":{"skin":"light","hair":"sidepart","hairColor":"grey","glasses":"round","beard":"none","outfit":"suit","acc":"pocketwatch","mood":"stern"},"bio":"副院长兼内科主任，跟院长十二年。初验认为是吗啡过量。自称晚饭后回房休息，一直没出来。","demeanor":"官腔，爱说“按规定”，被问急了就拿资历压人","topics":[{"id":"t_judge","q":"您怎么看死因？","a":"吗啡过量，呼吸抑制。院长癌痛手抖，意外也好，自戕也好，院里体面要紧。结论我已经下了。"},{"id":"t_cancer","q":"院长的病有谁知道？","a":"只有三个人：我、薛护士长、药房的宋药师。他自己要求保密，怕病人和家属慌。这事我没对外说过。"},{"id":"t_where","q":"21:40 以后你在哪？","lie":true,"a":"谈完话我回房看文件，然后睡了，直到老魏砸门。屋里就我一人，没人作证，不等于我撒谎。","truth":"我没睡。从十点到十一点一刻，我和薛玉芬在我房里。我们处了两年了，传出去她当不成护士长。这与院长的死无关。"},{"id":"t_quarrel","q":"你们晚饭后吵了什么？","lie":true,"a":"谁说吵了？例行汇报，预算、床位、采购。老顾脾气硬，嗓门大了点，在我们之间这不算事。","truth":"他拿便条质问我收了家属的钱，说路一通就写材料交县卫生局，要我退赃、辞职。我嚷了几句就走。他快死了，我杀他图什么。"},{"id":"t_money","q":"便条上的钱怎么回事？","needs":["clue:c_s4"],"a":"洪建国每月八十，托我把他老婆多留一阵，一共收了十一个月。是我的错，但病人照样治。"},{"id":"t_succ","q":"院长之后谁接班？","a":"县里要外派，我这辈子也就到副字头了。他活着我还有块牌子，他一死，天知道上头派个什么人来。"},{"id":"t_ghost","q":"梁秋白看到的白影呢？","a":"妄想。护理单上他21:30就吃了氯丙嗪一百毫克，睡得比我还死。别拿病人的话办案。"}],"confronts":[{"clue":"c_r4","breaks":"t_where","a":"老魏这本子……好，我不抵赖，那晚我不是一个人。其余的事，按规定，我只对你一个人说。"},{"clue":"c_s4","breaks":"t_quarrel","a":"这条子……好，我不绕了。八十块是我的把柄。可我若要杀他，何必挑满院是人的台风夜？"},{"clue":"c_r1","a":"这是护士长的事。不过一张写到早上六点的记录，连我都看出不对来了。明早我会处理，轮不到你教我管人。"},{"clue":"c_w1","a":"梁秋白的笔记？我不对病人的本子表态。22:52前后我在哪里，你已经知道了，那是另一回事。"},{"clue":"c_s2","a":"8706，8612……我只验了死因，没去看批号。哪一批能要命，那是药房的账，问宋药师。"},{"clue":"c_s1","a":"右臂？癌痛的人疼起来，哪还顾得上哪只手？光凭这一点，不足以推翻我下的结论，同志。"}],"fallback":"这与案情有什么关系？按规定，我只答与案情有关的问题。"},{"id":"xue","name":"薛玉芬","role":"护士长","age":49,"look":{"skin":"light","hair":"bun","hairColor":"black","glasses":"none","beard":"none","outfit":"uniform","acc":"badge","mood":"tired"},"bio":"护士长，守着三十四张床十七年，与魏德贵共同值夜。自称当晚一直在病区查房，不曾离开。","demeanor":"短句利落，开口先说“按章办事”，心虚时语速变快","topics":[{"id":"t_round","q":"昨夜 22:30 查房了吗？","lie":true,"a":"查了。我点着马灯一间间看过去，各床安睡，才写的“查房毕”。记录单就是凭据，你可以看。","truth":"我没查。单子是傍晚交班前填好的，台风夜人手少，我想省事。22:00后我和严副院长在他房里，到十一点一刻才回病区。"},{"id":"t_pill","q":"梁秋白的药你看他咽了？","lie":true,"needs":["clue:c_r1"],"a":"我亲手递的杯子，亲眼看他咽下。他吃了就睡，所以半夜看见什么，一定是病没压住，不关药的事。","truth":"我递了杯子就去忙别的，没盯着。“已服”是我提前写的。梁先生从不闹，我就信了纸，没再回头看。"},{"id":"t_sign","q":"药房的破损登记你签过？","lie":true,"needs":["clue:c_y1"],"a":"每月月底，我亲自去药房点破损的空安瓿，一支支对数，核对无误才签字。这点规矩比命重要。","truth":"宋药师说站着点数腿疼，让我先签，他事后补数。我签了四个月，有时一次几页。我被他当了遮羞布。"},{"id":"t_vic","q":"院长平时怎么打针？","needs":["clue:c_s1"],"a":"他右手握针筒，扎左臂，十年没变。他说右臂要留着写字，从来不碰右臂。这几个月左臂没处下针了。"},{"id":"t_song","q":"你怎么看宋药师？","a":"勤勉，守时，药房的账从没出过岔子。院长的药都是他亲手发，我一个护士，只有信他的份。"},{"id":"t_ghost","q":"你信梁说的白影吗？","a":"我不好说。梁先生一向条理清楚，只在夜里偶尔胡言。可记录是那样写的，现在看，不好当凭据。"},{"id":"t_truth","q":"22:00 以后你人在哪？","needs":["clue:c_r1"],"a":"在严副院长房里，十点到十一点一刻，没出去过。老魏巡廊从门口过，我听见了他的脚步。"}],"confronts":[{"clue":"c_r1","breaks":"t_round","a":"是我写的，写到早上六点。我认错。单子废了，你问严副院长，我们那一个多钟头在哪儿。"},{"clue":"c_w2","breaks":"t_pill","a":"药在缸底……那我写的“已服”全是白纸黑字的谎。要是我盯着看那一眼，他的话也不会被当疯话。"},{"clue":"c_y1","breaks":"t_sign","a":"这是我的名字，同一支笔。四个月的“核”，烧起来是这样。宋药师，你拿我的字干了什么？"},{"clue":"c_r4","a":"老魏巡到严副院长房门口，我听见了，他没敢敲。后来他躲进棚里喝酒，我心里知道，也没说破。"}],"fallback":"这个我说不清楚，按章办事，我只认记录。"},{"id":"liang","name":"梁秋白","role":"长期住院病人","age":59,"look":{"skin":"light","hair":"short","hairColor":"white","glasses":"round","beard":"none","outfit":"vest","acc":"pocketwatch","mood":"smile"},"bio":"退休历史教师，抑郁住院六年。自称昨夜见白衣人提灯进了院长室，护理记录却说他已服药睡下。","demeanor":"文雅克制，有教师的条理，被当病人时语气温和而带锋","topics":[{"id":"t_saw","q":"昨夜你看见了什么？","a":"22:20，白衣人蒙着口罩，左手提灯，右脚拖着，进了院长室。22:52出来，门咔一声自合。都在本子里。"},{"id":"t_pill","q":"药你吃了吗？","lie":true,"a":"吃了。护士看着我咽的，我从不违抗医嘱，夜里睡得很沉。你不要因此怀疑我，你可以现在让我张嘴给你看。","truth":"没吃。氯丙嗪让我昏沉，写不出东西。我含在舌下，等护士走了吐进缸里。我只想要自己的脑子。"},{"id":"t_clock","q":"你怎么知道时间？","a":"怀表。我每天21:00和大厅座钟对一次表，差一分钟，不会更多。我用它记所有的事。"},{"id":"t_past","q":"你以前也见过他吗？","a":"八月以来六回，夜里一两点，同样的白影从药房侧门出来，去后院一趟又回去。幻觉不会走同一条路。"},{"id":"t_face","q":"那人是男是女？","needs":["ask:liang.t_saw"],"a":"男，中等偏瘦，肩往右塌。脸被口罩和暗影遮住，我说不出是谁。他走路右脚比左脚晚落地半拍。"},{"id":"t_record","q":"护士长的记录呢？","needs":["clue:c_r1"],"a":"我见过薛护士长对着墙补记。人少活多，我不怪她。可我的“已服”若也是先写的，我的话你就该掂量。"},{"id":"t_dignity","q":"被当成疯子是什么感觉？","a":"一开始愤怒，后来疲倦。人们只看你的病历，不看你的眼睛。请你先看我的本子，再看病历。"}],"confronts":[{"clue":"c_w2","breaks":"t_pill","a":"被你翻出来了。不错，我没吃。你不必替我瞒着护士长。这几片药是我的证词，不是我的罪。"},{"clue":"c_w1","a":"这是我的笔记，一字不改。你读到“右脚拖着”了吗？我只写所见，不下判断。判断是你的事。"},{"clue":"c_r2","a":"“视为幻觉”是他们写的。幻觉能记下时间、方向和步法吗？人总爱用现成的词，把看不懂的事关起来。"},{"clue":"c_r1","a":"连早上六点的体温都写好了，我就知道我的“已服”也白搭了。你信我的怀表吧，它从不先写。"}],"fallback":"这个我没看见，也不想编。我只说写进本子里的事。"},{"id":"su","name":"苏婉如","role":"住院病人","age":38,"look":{"skin":"fair","hair":"bob","hairColor":"black","glasses":"none","beard":"none","outfit":"robe","mood":"sad"},"bio":"原纺织厂会计，住院四年，院长曾答应她秋天出院。昨晚打了安神针，自称一觉睡到天亮。","demeanor":"说话轻，爱停顿，爱用数字；记忆断片时先道歉","topics":[{"id":"t_bio","q":"您原来做什么的？","a":"纺织三厂财务科，十年账目没出过错。我现在每天数床、数窗、数人。数字不骗人。对不起，说多了。"},{"id":"t_where","q":"昨夜你在哪里？","lie":true,"a":"我睡了。九点简医生给我打了针，之后什么都不记得，一觉到天亮。对不起，我真的不记得别的。","truth":"我不是一直睡。十一点后醒了，摸黑去水房，路上见药房亮着灯。后来又去档案室想拿回自己的病历。怕被加药，不敢说。"},{"id":"t_gap","q":"你的记忆是怎么回事？","a":"打完针，脑子像被擦过的黑板。简医生后来道歉，说记不清是不是打了两遍。对不起，我不怪他。"},{"id":"t_keep","q":"你想出院吗？","a":"想。院长答应今年秋天。我丈夫说家里没人照顾，让我再等等，他说话不看我，我就知道了。"},{"id":"t_hong","q":"你丈夫昨天的样子？","a":"他下午就到了，睡客房，我睡病房。他带了橘子，剥了一个又一个，剥完又装回去，像把心思也装回去了。"},{"id":"t_water","q":"你夜里走动时看见了什么？","needs":["clue:c_r3"],"a":"药房亮着灯，宋药师戴着口罩伏案写字。我认得那姿势，他在抄账。他抬头看见我，叫我回去睡。"},{"id":"t_ledger","q":"你怎么知道是抄账？","needs":["ask:su.t_water"],"a":"他左手压旧账，右手用尺压新纸，照着写，写一行吹一口气等墨干。那是造账的法子。钟刚打过十一下。"}],"confronts":[{"clue":"c_r3","breaks":"t_where","a":"那是我的病历夹……我没偷，我只是想拿回来看看。他们写了什么，我连看的资格都没有吗？好，我说，昨晚我不是一直在睡。"},{"clue":"c_p2","a":"这页红章边缘对不上。我们厂里叫抽换页，会计一眼就看得出。原来那页是什么样，我说不准。"},{"clue":"c_w1","a":"梁先生写得这样细，时间、方向、脚步都有，一定没说谎。字写得越小的人，越怕被人看轻。"}],"fallback":"对不起，这个我真的不记得，说不清。"},{"id":"hong","name":"洪建国","role":"病人家属","age":41,"look":{"skin":"tan","hair":"short","hairColor":"black","glasses":"none","beard":"stubble","outfit":"jacket","mood":"sly"},"bio":"苏婉如的丈夫，机修厂钳工。探视被山路塌方困在院里，住客房。自称晚饭后就睡，没见过院长。","demeanor":"粗嗓门，爱套近乎，急了拍桌子，一口车间腔","topics":[{"id":"t_visit","q":"你为什么来探视？","a":"一个月一回，这回赶上台风。我带了橘子。我就想她安安稳稳待在这儿，别再折腾，别回去受罪。"},{"id":"t_where","q":"昨夜你在哪里？","lie":true,"a":"客房，晚饭后就躺下了。风大睡不踏实，听见老魏砸门才爬起来。我连院长都没见着，别往我身上扯。","truth":"我去了院长室门口，想求他别让我老婆出院。敲了好几次没人应，抽了四根烟，十一点一刻才走。怕你们当我是凶手，才瞒。"},{"id":"t_money","q":"你给过严副院长什么吗？","lie":true,"needs":["clue:c_s4"],"a":"没有，没有。我一个工人，一个月才挣几十块，哪来钱孝敬领导？别听人胡说八道，我跟严副院长话都说不上几句。","truth":"每月八十，十一个月了。我厂里有个女工，跟我两年了，老婆一出院就藏不住。我不是好人，可没动过院长一根指头。"},{"id":"t_door","q":"你在门口都听到什么？","needs":["clue:c_w1"],"a":"里头没动静，只有粗重的呼吸，呼噜呼噜的，我当他睡着了。门底下透着灯光，我敲了三回。"},{"id":"t_heard","q":"你来的路上遇见谁？","needs":["ask:hong.t_door"],"a":"拐进走廊，见院长室那头有个白衣影子，提灯背对我往药房走，一拐一拐，右脚拖地。离我三四十步。"},{"id":"t_ghost","q":"听说院里闹鬼？","a":"我不信那些。这里的人爱说“白衣的”，我看是被药给灌的。要我说，我信的是人，不是鬼。"}],"confronts":[{"clue":"c_s3","breaks":"t_where","a":"那四个烟蒂是我的，大前门，我就抽这个。行，你逮着了！我是去过，可我就站在门口敲门，屁都没干！"},{"clue":"c_s4","breaks":"t_money","a":"这便条……他们连这个都记上了！行，我认。八十块，每个月。我工资不够，剩下的是借的。别让我老婆知道！"},{"clue":"c_r3","a":"拟十月出院！这就是我最怕的事。我没杀人，但心里确实盼过他别这么痛快。我知道我不是东西。"},{"clue":"c_p3","a":"这鞋……药房那边的东西，我哪认得清。院里穿布鞋的多了，我连药房门都没进过，别拿它问我。"},{"clue":"c_w1","breaks":"t_where","a":"梁老师那本子，连我抽烟都记了？行，我不赖。我就是去求院长的，敲了门没人应，也不敢硬闯。"}],"fallback":"这个我不懂，别问我，我就是个钳工。"},{"id":"wei","name":"魏德贵","role":"值夜护工","age":56,"look":{"skin":"brown","hair":"cap","hairColor":"grey","glasses":"none","beard":"stubble","outfit":"jacket","mood":"tired"},"bio":"老护工，管开水和发电机，干了十四年。22:00给院长送水，00:40叩门无应，第一个发现不对。","demeanor":"老实巴交，拖长音，爱说“咱们院里”，一紧张就搓手","topics":[{"id":"t_water","q":"22:00 院长什么样？","a":"脸白，说话喘。他拉开抽屉看了看那两支小玻璃管，又推回去，吩咐我零点半再送一壶水。"},{"id":"t_where","q":"你整夜在哪里？","lie":true,"a":"我哪儿也没去，整夜来回巡廊，开水房、病区、前后院。咱们院里台风夜，谁敢睡？零点二十我还在走。","truth":"22:45巡完一趟，我躲进发电机棚喝了半瓶地瓜烧，醉睡到零点二十。院长知道我这毛病，总骂我，也护着我。怕被辞，没敢说。"},{"id":"t_find","q":"你怎么发现的？","a":"零点四十我送水叩门，没人应，去叫严副院长。我俩劈开的门，钥匙在桌上，窗也闩着。院长手还是温的。"},{"id":"t_song","q":"宋药师这个人？","a":"老实人，肯干，从不跟人红脸。就是腿，七六年摔的，阴雨天右脚拖着，走几步就要歇一歇。他夜里常守药房。"},{"id":"t_fire","q":"后院有什么动静？","needs":["clue:c_y2"],"a":"半睡半醒时，我看见焚化炉那边有火光，旁边有个人影，好像在往里添东西。我当是做梦。"},{"id":"t_ghost","q":"院里闹鬼的说法？","a":"咱们院里的老人都听过，夜里一两点药房那边有灯，有时也在走廊。可那不像鬼，鬼哪用提灯呢。"},{"id":"t_doc","q":"院长最近怎么了？","a":"他疼得厉害，半夜常叫我去煮针。有回他看着一支小玻璃管，念叨：“怎么越打越疼……”"}],"confronts":[{"clue":"c_y2","breaks":"t_where","a":"那瓶酒是我的。唉，我说实话，我是喝多了睡过去的，不是在巡廊。你可别告诉护士长，她知道了非撵我走不可。"},{"clue":"c_r4","breaks":"t_where","a":"这是我写的，一笔一画都是真的。“23:00 在发电机棚歇”……我赖不掉，我是醉睡的。"},{"clue":"c_s3","a":"这些烟蒂，我22:45巡廊时还没有。大前门是客房那位洪师傅抽的，我闻得出这个味儿。"},{"clue":"c_p3","a":"这是宋药师的鞋，我认得，右脚垫了两层。他这条腿一到阴雨天就一拖一拖，咱们院里人都知道。"}],"fallback":"这个我不懂，咱们院里的事我只知道大概。"},{"id":"jian","name":"简若川","role":"实习医生","age":24,"look":{"skin":"fair","hair":"messy","hairColor":"black","glasses":"rect","beard":"none","outfit":"labcoat","acc":"stethoscope","mood":"worried"},"bio":"实习医生，来院才六天，在内科和化验室帮忙。自称昨夜九点半后一直在宿舍睡觉，没有出门。","demeanor":"年轻，语速快，爱先道歉，紧张时背医学名词","topics":[{"id":"t_where","q":"昨夜你在哪里？","lie":true,"a":"宿舍，九点半后就没出去过，躺着听风声，一直到喊声。我真的没出门，护士长可以作证……呃，对不起。","truth":"我在化验室，做到二十三点二十。我不踏实，想用第二种方法再验一遍那批药。怕被人知道违令，才瞒。"},{"id":"t_test","q":"你替院长做过化验吗？","lie":true,"needs":["clue:c_l1"],"a":"没有。就是照流程做常规检验，血常规、尿常规、肝功，没有谁交代我什么特别的，我什么都说。","truth":"有。9月22日院长给我一支8612批吗啡，让我悄悄检含量，连严副院长都不能讲。结果只有十分之一，我吓坏了，院长让我闭嘴。"},{"id":"t_day","q":"昨天院长有什么异常？","needs":["clue:c_l2"],"a":"下午两点半他让我复核新到的8706，合格。他说，这批是真的。还说明早八点，有些人就得老实了。"},{"id":"t_dose","q":"苏婉如的针是怎么打的？","needs":["ask:su.t_gap"],"a":"九点我给她打了氯丙嗪25毫克。后来见单子已写“已注”，怕漏，又补一针。等于两针，我不敢说。"},{"id":"t_slip","q":"复核结果你告诉了谁？","needs":["clue:c_l2"],"a":"8612的结果只告诉了院长。8706合格单按规程抄送药房，宋药师四点多签收，还问院长为何亲自盯这批。"},{"id":"t_song","q":"宋药师对你如何？","a":"客气，常给我倒茶。有天他半开玩笑问，新来的医生是不是要查账。他问的时候，手一直在转钥匙。"},{"id":"t_ghost","q":"你信有白影吗？","a":"我信数据，不信鬼。可梁先生的记录时间、方位那么一致，我越看越觉得，那很难只是幻觉。"}],"confronts":[{"clue":"c_l1","breaks":"t_test","a":"这是……我的字。院长让我保密，我就一直保着。我一个实习生，真的不知道该跟谁说，您早点来就好了。"},{"clue":"c_l3","breaks":"t_where","a":"那盏灯和那行字是我留的。我没在宿舍，我在做第二法复检。怕被扯进来，所以撒了谎，我知道这样不对。"},{"clue":"c_r1","a":"我是照着单子上的顺序打的针。如果记录是预先写的，我是在治病，还是在照假单子行事？"},{"clue":"c_l2","a":"合格单抄送是规程，我照办。可他接单时问得那样细……8706我验过，合格。问题在别的批号上。"}],"fallback":"对不起，这个我真的不清楚，可以问问别人吗？"},{"id":"song","name":"宋鹤龄","role":"药剂师","age":52,"look":{"skin":"light","hair":"short","hairColor":"grey","glasses":"rect","beard":"none","outfit":"labcoat","acc":"badge","mood":"tired"},"bio":"药剂师，管药房和管制药品柜十五年，七六年摔伤右腿，阴雨天走路拖脚。自称昨夜在药房月末盘点。","demeanor":"客气周到，说话慢，爱用“您”，被逼急了先叹气","topics":[{"id":"t_where","q":"昨夜你在哪里？","lie":true,"a":"药房。月底盘点，从九点多一直做到零点四十，听见喊声才出来。我腿疼，哪儿也没去，您翻登记册就知道。","truth":"我去了院长室，二十二点二十到五十二，与他谈了近半个钟头。我不敢承认，是怕您听了就认定是我。"},{"id":"t_ledger","q":"管制药品登记册可靠吗？","lie":true,"a":"每笔当场记当场签。昨晚22:10院长亲自来领了三支8706，他签的字，翻第38页就是。","truth":"那页是我后来补的。原页有不能让人看的记录，我烧了，另抄一页，添上“院长自领”，好让三支空安瓿有个来路。"},{"id":"t_key","q":"8706的柜钥匙谁有？","needs":["clue:c_p1"],"a":"两把锁，一把我带着，另一把也在我手里，备用的封在院长保险柜里，封条完好。除了我，谁也开不了。"},{"id":"t_stock","q":"药品账物相符吗？","lie":true,"a":"相符，一支不差。有破损，每月二三支，都有护士长核对签字。药房的账，是我一生的脸面。","truth":"不相符。我从八三年起把8612批吗啡冲成盐水，真药卖了钱，给儿子治肾病。破损是我编的，护士长的签字是骗的。"},{"id":"t_ghost","q":"你怎么看梁的白影？","a":"梁先生是体面人，我很同情。病程记录写得明白，是药物和病情。院里的白大褂，哪件不是白的？"},{"id":"t_visit2","q":"你去院长室做什么？","needs":["clue:c_w1"],"lie":true,"a":"梁先生的本子您看过了，我去过。只想解释，他最近疑心我。没带药，也没碰他的针。我走时他在备自己的8612。","truth":"我没劝他。他只叫我明早八点带8612账册，我又知道新批验过是真药，就知道他在盯药。我带着8706进去，说他手抖，我替他推。"},{"id":"t_conf","q":"那针是你打的？","needs":["ask:song.t_visit2","clue:c_s1","clue:c_s2"],"a":"是我。我从自己柜里取三支真药，推进他右臂，看着他睡下。拉门，咔一声锁上。回药房重抄了第38页，烧了原页。"}],"confronts":[{"clue":"c_w1","breaks":"t_where","crack":true,"a":"……唉。梁先生的本子，您读得仔细。是我，我去过。右脚拖着走，您大概也看出来了。我最怕的，就是有人把“疯话”当真。"},{"clue":"c_p2","breaks":"t_ledger","crack":true,"a":"这半枚章……您连这个都看出来了。字我抄得再像，章也盖不回去。……好，您问吧，您要什么，我给什么。"},{"clue":"c_y1","breaks":"t_ledger","a":"这一角没烧透。我烧得太急，雨又大，炉子不旺。第38页原样是什么，您现在大概猜得出。"},{"clue":"c_l1","breaks":"t_stock","a":"一比十……他竟然真的验了。他那个人，从不空口说话。账是假的，药也是假的，我认了。您想问什么，尽管问。"},{"clue":"c_s1","breaks":"t_visit2","crack":true,"a":"右臂……他从不扎右臂，这我是知道的。当时只想着快，竟忘了。您说得对，没人会扎错手臂。"},{"clue":"c_s2","breaks":"t_visit2","a":"三支空的是8706，抽屉里原封的是8612。他一支也没碰自己的药，真药是我带去的。"},{"clue":"c_y2","breaks":"t_where","a":"后院的泥，雨也冲不干净。右脚拖出的沟，我自己最清楚。我说“哪儿也没去”，不老实了。"},{"clue":"c_p3","a":"这是我的鞋，院里谁不知道？我腿不好，天天拖着走。可您拿一双鞋就定我的罪，未免太轻率了。"},{"clue":"c_l2","a":"合格单是我签收的，新批入库，哪回不是这样。院长亲自复核，对药房是好事，我欢喜还来不及。"},{"clue":"c_y3","a":"烧点废纸，药房里常有的事，包药的草纸、作废的处方，总得有个去处。您别见怪，我这人一向爱干净。"}],"fallback":"这个与药房无关，您恐怕问错人了。"}],"solution":{"culprit":"song","method":{"q":"凶手怎么做到的？","correct":1,"options":["A 院长癌痛难忍，自己多打了好几支吗啡，属于意外或自戕","B 借口替院长注射，自带的吗啡推进右臂，门自合锁死","C 有人在抽屉的安瓿里掺了药，院长自己注射后发作","D 凶手撬锁进屋，事后用另一把钥匙从外面反锁"]},"motive":{"q":"为什么杀人？","correct":3,"options":["A 想在院长死后接管疗养院，独占其中的利益","B 记恨多年前一次误诊的旧怨，借台风夜报复","C 院长发觉他私收家属的钱，要他退赃并辞职","D 院长查出他用盐水顶替吗啡，天亮要报官"]},"keyClues":["c_s1","c_s2","c_p2","c_l1","c_w1","c_r1"],"truth":["凶手是药剂师宋鹤龄。他多年把8612批吗啡冲成盐水，倒卖真药。院长发觉止痛针不管用，让简若川化验，只剩十分之一，并约宋明早八点带账册。宋借台风夜动手。","22:20宋蒙口罩、提马灯、右脚拖着，从药房走到院长室。他说“你手抖，我替你打”，把自带的8706三支推进院长从不扎的右臂。22:52出门，弹簧锁自合成了“密室”。","他回药房重抄登记册第38页，补上“22:10院长亲领8706×3”，23:35把原页烧在焚化炉，泥地留下拖沟脚印。梁、魏、苏各见一角。","梁的笔记写明22:00至22:20走廊无人，院长不可能22:10去药房。护理记录是薛玉芬提前填的，梁一直把药吐在缸底，证词可信。","其余人的谎各有隐情：严收钱并与薛私会，洪怕妻出院，魏醉睡，简违令化验。台历写着“宋 带8612账册”，院长要查的从来不是那八十块。"]}},{"id":"observatory","title":"天文台","tagline":"暴雨封山的夜里，台长死在从内插死的观测圆顶下，镜头瞄准了永远不该对的地平线。","difficulty":4,"cover":"cv_observatory","tone":"purple","brief":"栖云岭天文台建在一千八百米的山顶。你受资助人钟鸣鹤之托上山核查设备采购款，却撞上了这样的夜晚。\n台长岑望川22点多独自进了圆顶，从里面插上门栓。零点二十暴雨压境，一点四十山路塌方。凌晨两点十四分，电工阚大海撬开门，台长坐在折叠椅里，左额塌陷。望远镜低垂着，镜筒对着山腰的贵宾小楼。门是内插的，圆顶没有第二个入口。\n警察天亮后才能上山。台里八个人都被困着，你要先查清：门是谁锁的，镜头为何转向那里。","victim":{"name":"岑望川","desc":"栖云岭天文台台长，63岁，在山上工作三十一年。被发现时坐在望远镜北侧的折叠椅里，左额塌陷，身上是干的。","look":{"skin":"light","hair":"short","hairColor":"white","glasses":"round","beard":"none","outfit":"parka","acc":"scarf","mood":"tired"}},"publicFacts":["岑望川亲自上圆顶观测时，一定从里面插上门栓。他的保温杯二十年来都由夜间观测员夏守诚灌好。","圆顶只有螺旋梯一个入口，门禁刷卡，内侧另有钢栓。22:19“岑”刷卡进入，02:14 阚大海撬开门栓，台长已死。","当晚上弦月，约23:00落山。猎户座22:00以后才从东南升起，午夜也只有二三十度高。","望远镜停在高度约3度、方位约258度，贴着地平线，指向贵宾小楼。平时最低观测高度是15度。","控制软件的时间栏用恒星时，不是钟表时。恒星时每天比钟表时快约4分钟，9月下旬两者相同。","暴雨00:20压境，01:40山路塌方。山上八个人，谁也没有离开。"],"relations":{"xia":"夜班观测员，每晚给台长灌保温杯","fei":"副台长，管运行和人事，台长的下属","ruan":"台长指导的博士生，答辩要他签字","kan":"山上的电工，管圆顶电机和配电","sheng":"山上的厨师，管全台的伙食","xue":"来做三个月数据分析的访问学者","zhong":"新四米望远镜的最大资助人","jian":"结发三十四年的妻子"},"links":[{"a":"xia","b":"jian","text":"跟她丈夫二十四年，像半个儿子"},{"a":"fei","b":"zhong","text":"副台长和资助人，常谈续资助"},{"a":"sheng","b":"xia","text":"盛烧水备茶叶，夏灌台长的杯"},{"a":"kan","b":"ruan","text":"02:14 一起撬开圆顶的门"}],"deathReport":{"time":"约 22:30–02:00","cause":"左额遭钝器重击，颅骨塌陷","scene":"02:14 电工阚大海撬开门栓，发现台长坐在圆顶折叠椅里，已无生命体征。","loc":"dome","notes":["左额一处重击伤，一击致命","尸体坐姿端正，没有挣扎或防卫的痕迹","外套是干的，圆顶地上有水光"]},"timeline":[{"t":"17:40","text":"电工阚大海修高度轴限位开关，检修单贴在控制室白板上。"},{"t":"19:30","text":"晚饭。饭后各自散去，台长带着保温杯去圆顶。"},{"t":"22:19","text":"门禁记录：“岑”刷卡进入圆顶。"},{"t":"23:00","text":"上弦月落山，天空全黑。"},{"t":"00:20","text":"暴雨和雷电压境。"},{"t":"01:40","text":"山路塌方，电话时断时续。"},{"t":"02:14","text":"阚大海撬开圆顶内栓，发现台长遇害。"}],"budget":{"search":14,"ask":28},"locations":[{"id":"dome","name":"一米圆顶","scene":"lab","desc":"直径十米的白色圆顶，老式一米望远镜立在中央。天窗敞着，地上一片水光。","clues":[{"id":"c_dome1","title":"遗体与折叠椅","text":"台长坐在望远镜北侧的折叠椅里，左额塌陷。配重杆末端沾着血和白发，悬在椅子上方。外套是干的。"},{"id":"c_dome2","title":"保温杯","text":"保温杯里剩小半杯凉茶，有淡淡的苦味。杯底沉着一层没化开的白色细粉。"},{"id":"c_dome3","title":"门栓与门禁","text":"门内侧的钢栓被撬棍撬弯。刷卡记录：19:52 阮，21:18 阮，22:19 岑，之后空白，直到 02:14 手写“破门”。"},{"id":"c_dome4","title":"手写观测日志","text":"台长日志的最后几行：“22:25 开缝。月将落。”“22:35 M31 试拍。”“22:40 手有点抖，困。”之后空白。"}]},{"id":"ctrl","name":"控制室","scene":"cabin","desc":"圆顶下一层，三台显示器围成半圈，白板上贴满纸条。隔着玻璃是资料室。","clues":[{"id":"c_ctrl1","title":"序列文件","text":"cen 账号未退出。tonight.seq 存于“LST 00:32:10”：@LST 02:52:00，SLEW ALT 3.0 AZ 258.0，SOFTLIM OFF。"},{"id":"c_ctrl2","title":"恒星时对照卡","text":"一张手写的过塑卡，没有署名：“9月22日恒星时与钟表时相同，此后每天多约4分钟。10月中旬：钟表时＋1小时40分＝恒星时。”"},{"id":"c_ctrl3","title":"刷卡与雨感记录","text":"走廊刷卡：00:31 费，01:05 费。雨感报警 00:21 触发，02:16 才被按掉。白板规矩：下雨，当班观测员第一个上圆顶关缝。"},{"id":"c_ctrl4","title":"资料室拷贝记录","text":"资料室主机的 U 盘拷贝日志：21:24 开始，23:01 结束，38GB，账号“xue”。工位正对着控制室的玻璃。"},{"id":"c_ctrl5","title":"抽屉里的药瓶","text":"观测员工位抽屉里有一瓶舒眠宁，夏守诚名下，10月9日开具，共20片，每晚半片。瓶里还剩12片。"}]},{"id":"power","name":"机房配电间","scene":"engine","desc":"圆顶底层的机房，闷着柴油和润滑油味。墙上是配电箱，墙角一排工具柜。","clues":[{"id":"c_pow1","title":"电机事件记录","text":"最后一次手柄(HP)操作在 22:41:02。01:12:07 圆顶起转，来源 SEQ（序列自动运行）；01:12:44 俯仰轴过载。"},{"id":"c_pow2","title":"检修单与跳线","text":"检修单：“17:40 高度轴下限位接触不良，临时跳线短接，次日更换。阚。”台长签“知”。限位盒外的跳线还在。"},{"id":"c_pow3","title":"屋顶门磁记录","text":"屋顶门磁日志：21:49 关门后，到 23:34 才再次开启。风速自记纸上 22:40–23:10 走笔平稳，没有备注。"}]},{"id":"canteen","name":"食堂厨房","scene":"kitchen","desc":"山上唯一热气腾腾的地方，大灶台、汤锅和一张折叠圆桌，窗上全是雨水。","clues":[{"id":"c_can1","title":"牌局记分纸","text":"圆桌下压着记分纸：夏、盛、阚、阮四人，第一局 00:30，最后一局 01:58。01:00 旁注“夏如厕”。"},{"id":"c_can2","title":"灌杯的案台","text":"案台上落着几粒白色细粉，垃圾桶里有个揉皱的空纸包，闻着有点苦。"},{"id":"c_can3","title":"夜宵订单","text":"墙上的夜宵单：“22:00 台长保温杯茶，夏灌。”盛的批注：“台长的杯，老规矩，谁也不碰。”"}]},{"id":"office","name":"台长办公室","scene":"study","desc":"摆满书和旧底片盒，墙上挂着“岑星”的放大照片。台灯还亮着，抽屉被拉开过。","clues":[{"id":"c_off1","title":"解约通知稿","text":"台长10月16日签字的通知稿：四米望远镜投产后取消夜间观测岗，夏守诚合同12月31日终止，补偿六个月工资。"},{"id":"c_off2","title":"岑星底片","text":"底片盒写“2010.8.22 首见”。值班条上“夏守诚拍摄”被划去，改成“岑”。展板样稿写着“岑望川发现”。"},{"id":"c_off3","title":"诊断单","text":"三个月前的诊断单：“右手静止性震颤，考虑帕金森综合征早期。”页脚钢笔字：“告诉文漪。”"},{"id":"c_off4","title":"理事会议程","text":"周一理事会议程第三项“班子调整动议”，提议人栏空着，旁边红笔批了个“费”。背面写着“600万”“撤”。"},{"id":"c_off5","title":"医疗补助批条","text":"2016年批条复印件：夏母医疗费由岑望川个人专项款按季拨付，不受夏在编与否影响。最近一笔是9月30日。"}]},{"id":"chalet","name":"贵宾小楼","scene":"guestroom","desc":"半山腰的独栋小楼，资助人的住处。落地窗正对圆顶，壁炉余温还在。","clues":[{"id":"c_che1","title":"智能门锁日志","text":"小楼门锁日志：21:55 钟；22:21 费进；00:26 费出。茶几上有两只茶杯。"},{"id":"c_che2","title":"窗边的视线","text":"客厅落地窗正对山顶圆顶，夜里能看见轮廓。圆顶天窗的缝，朝着这扇窗的方向敞着。"},{"id":"c_che3","title":"钟的备忘","text":"钟的备忘本：“费同意：台长换人后资助继续，冠名权归公司。台长不松口，就撤资。”页角：“21:40 台长电话，拒绝。”"}]}],"suspects":[{"id":"fei","name":"费思齐","role":"副台长","age":54,"look":{"skin":"light","hair":"sidepart","hairColor":"grey","glasses":"rect","beard":"none","outfit":"suit","acc":"tie","mood":"stern"},"bio":"分管运行和人事的副台长，在台里十九年，等台长的位置等了十年。当晚称早早回宿舍休息。","demeanor":"官腔，爱说“原则上”，被逼问就把语速放慢。","topics":[{"id":"t_role","q":"你在台里负责什么？","a":"副台长，管运行和人事。岑台长抓科学，我抓程序。这座山上的事，十年里一半是我签的字。"},{"id":"t_night","q":"23:00以后你在哪？","lie":true,"a":"宿舍，早早睡了。晚饭后我就回了房间，原则上我不参加夜间活动。直到阚师傅砸门，才知道出事。","truth":"我在贵宾小楼和钟总谈话，22:21到00:26。00:31我回楼刷卡进了控制室走廊，去删一封不该留的邮件。"},{"id":"t_plot","q":"班子调整动议是你提的？","lie":true,"a":"什么动议？我没听说过这回事。理事会的议程是办公室在排，我这个副台长原则上不过问。","truth":"是我起草的：请理事会换掉岑台长，由我接手，钟总续资助。我不是杀人的人，但我盼他退下来。"},{"id":"t_ctrl","q":"为何两次进走廊？","needs":["clue:c_ctrl3"],"a":"路过。00:31看见雨感灯亮着，台长在圆顶，那是他的事。01:05我又去看了一眼，没人就走了。"},{"id":"t_seq","q":"那份序列和你有关吗？","needs":["clue:c_ctrl1","ask:fei.t_ctrl"],"a":"没有。我没碰过那里的序列，也没有 cen 的密码。进走廊的时间和“00:32”碰得上，是巧合。"},{"id":"t_dir","q":"你想当台长吗？","a":"想。我从没对谁瞒过。岑台长干了三十一年，也该歇歇了，这话我敢当面讲，可我没动过他一根头发。"},{"id":"t_chalet","q":"你和钟总谈了什么？","needs":["clue:c_che1"],"a":"资助款的续期，四米望远镜的冠名。仅此而已。这也是为台里好，没有钱，一切都是空话。"}],"confronts":[{"clue":"c_che1","breaks":"t_night","a":"他咳了两声：“好吧，我去过小楼。22:21进的门，00:26出的，这个我没有隐瞒的必要了。”"},{"clue":"c_off4","breaks":"t_plot","a":"他脸一下沉下来：“那个‘费’字是我写的，没什么好抵赖。可你要明白，这是工作，不是谋杀。”"},{"clue":"c_ctrl2","a":"他把卡片读了两遍。“钟表时加一小时四十……那就不是00:32了。22:52，我在钟总客厅里，茶还是他倒的。”"},{"clue":"c_ctrl1","a":"他看着“LST 00:32:10”，脸色白了：“00:32……我是00:31刷的卡。我知道你们会怎么想。”"},{"clue":"c_che3","a":"他读着钟的备忘，良久才说：“撤资这一条，我是今晚才知道的。我只想换个台长，没想把山搞垮。”"}],"fallback":"原则上，这不是我分管的范围。"},{"id":"ruan","name":"阮禾","role":"博士生","age":26,"look":{"skin":"light","hair":"messy","hairColor":"black","glasses":"round","beard":"none","outfit":"hoodie","mood":"worried"},"bio":"台里的博三学生，因观测时间和答辩的事，与台长闹得不愉快。当晚称一直在宿舍改论文。","demeanor":"语速快，爱说“就是说”“真的”，一紧张就抠手指。","topics":[{"id":"t_role","q":"你是做什么的？","a":"博三，做近邻星系测光。一米镜头排期很紧，我一个月才轮得上三个晚上。我很需要这批数据。"},{"id":"t_dome","q":"晚上你上过圆顶吗？","lie":true,"a":"没有，真的没有。我一晚上都在宿舍改论文，台长不批我的观测时间，我哪敢往圆顶去啊。","truth":"我去了。19:52刷卡上去，21:18下来。趁台长吃饭，我拍了三组 M33 补论文的图。怕他知道。"},{"id":"t_after","q":"后半夜你在干什么？","lie":true,"a":"回宿舍睡了啊，睡得可死了，连雷都没听见。后来是阚师傅来敲我的门，我才迷迷糊糊爬起来的。","truth":"我在食堂打牌。夏师傅睡不着，00:30叫上盛师傅、阚师傅，我凑了一桌。山上禁赌，我没敢说。"},{"id":"t_thesis","q":"你和台长有什么过节？","a":"他不肯在答辩前签字，说我的图太糙，要重新观测。有人说我恨他，我气过，但没那个胆。"},{"id":"t_orion","q":"你看到了什么天象？","needs":["ask:ruan.t_dome"],"a":"我下楼那会儿是21点多，东南边还没有猎户座。22点前后在院子里抽烟，才看见它爬出山脊。"},{"id":"t_park","q":"你走时镜子在什么位置？","needs":["ask:ruan.t_dome"],"a":"我照规矩收了：镜筒摇回六十度上下，刹车锁好，手柄挂回去。21:18出来，里头什么都没动。"}],"confronts":[{"clue":"c_dome3","breaks":"t_dome","a":"他盯着那条记录，嘴唇颤了颤：“……我上去过。就拍了三组，半个小时。台长没发现，对吧？”"},{"clue":"c_can1","breaks":"t_after","a":"他苦笑：“被翻出来了。00:30到01:58我们四个都在。夏师傅一点去了趟厕所，我赢了他十块。”"},{"clue":"c_dome4","a":"他读着台长最后的字迹，眼眶发红：“‘手有点抖，困。’我21:18刚走，他是在那之后才上去的。”"},{"clue":"c_pow1","a":"他盯着记录发呆：“22:41之后没有手柄，01:12才有 SEQ……那中间台长是不是……”他没说下去。"}],"fallback":"就是说……这个我真的不太清楚。"},{"id":"xia","name":"夏守诚","role":"夜间观测员","age":49,"look":{"skin":"tan","hair":"cap","hairColor":"grey","glasses":"none","beard":"stubble","outfit":"parka","acc":"scarf","mood":"tired"},"bio":"上山二十四年的夜班师傅，从不缺勤。当晚亲手灌了台长的保温杯，后半夜在食堂陪人打牌。","demeanor":"话少、语速平，爱用行话，被问到痛处就看天花板。","topics":[{"id":"t_role","q":"你在台里做什么？","a":"夜间观测员，上山二十四年了。观测我跑，日志我记，镜子我擦。台长的杯子，也是我灌。"},{"id":"t_round","q":"22:40到23:10你在哪？","lie":true,"a":"屋顶气象平台。每晚那个钟点都要手测一次风速、换自记纸。空口无凭，你们可以去看自记纸。","truth":"我没上屋顶。那半个钟头我在楼下控制室里坐着。别的……你们先去问问别人，那晚谁看见我了。"},{"id":"t_flask","q":"保温杯里是什么？","lie":true,"a":"茶叶和冰糖，别的没有。二十年了，台长只喝我灌的茶。晚饭后我把杯子灌满，交给他，就是这样。","truth":"是药。我自己的舒眠宁，四片，在案台上碾碎兑进茶里。他从不看杯里有什么，喝了会困。"},{"id":"t_limit","q":"限位的事你知道吗？","lie":true,"a":"限位怎么了？没人跟我说过。白板上的检修单我没留意，电工的事电工自己管，我只管看天。","truth":"我知道。17:40单子一贴我就看见了，下限位被短接。我知道低到三度，配重杆会扫过椅子。"},{"id":"t_alibi","q":"01:12你在哪？","a":"食堂牌桌上，盛师傅、阚师傅、小阮都在。00:30开局，打到快两点。一点钟我去了趟厕所，三四分钟。"},{"id":"t_auto","q":"谁能写那份序列？","needs":["clue:c_ctrl1","ask:xia.t_round"],"a":"台里人人会写。cen 的会话挂了一晚上没退，谁坐上去都能存。我又不是头一个会的。"},{"id":"t_credit","q":"“岑星”怎么回事？","needs":["clue:c_off2","ask:xia.t_job"],"a":"2010年8月22日，那颗星的第一张底片是我拍的。台长说我年轻，先别署名，发现归台长。"},{"id":"t_job","q":"合同的事你知道吗？","lie":true,"needs":["clue:c_off1","ask:xia.t_role"],"a":"知道。四米投产，夜班取消。我四十九了，只会看天，我妈还在医院躺着，每个月都是钱。","truth":"钱不是事，我妈的钱一直是台长自己掏的。我求的是展板上添我的名字。他说，那是历史，不好改。"}],"confronts":[{"clue":"c_ctrl1","breaks":"t_round","crack":true,"a":"他盯着“LST 00:32”看了很久。“恒星时，减一小时四十，是22:52。那会儿我在这屋里坐着。文件是台长账号存的，我没说是我存的。”"},{"clue":"c_pow3","breaks":"t_round","a":"“屋顶……是我记岔了。”他按着膝盖，指节发白，“那半个钟头我在楼下。别的先别问。”"},{"clue":"c_can2","breaks":"t_flask","a":"他低头看那几粒白粉。“灌杯的案台，谁都在上头放过东西。”声音很轻，“纸包？厨房里还少么。”"},{"clue":"c_ctrl5","breaks":"t_flask","a":"“医生开的，睡不着，吃它有什么稀奇。”他把药瓶推远半寸，“台里睡不好的，又不止我。”"},{"clue":"c_off5","breaks":"t_job","a":"他把批条看了两遍。“这钱是台长的私房钱。我说怕没钱，是顺口的，你们容易信。他签条子时，是真拿我当自家人。”"},{"clue":"c_off2","a":"他盯着那行被划去的字。“当年我写的。后来每回路过展板，我都绕着走。二十年，我就想看一次底下有我的名字。”"},{"clue":"c_pow2","breaks":"t_limit","a":"“白板上有复印件，天天打那儿过，要说没看见也不实在。阚师傅忘了拆，我不好说什么。”"}],"fallback":"这个……你问点别的，我记不清了。"},{"id":"kan","name":"阚大海","role":"电工","age":52,"look":{"skin":"tan","hair":"short","hairColor":"grey","glasses":"none","beard":"stubble","outfit":"uniform","mood":"stern"},"bio":"山上干了三十二年的电工兼机修，嗓门大、脾气直。2011年弟弟在圆顶检修时丧生。当晚亲手撬开了圆顶的门。","demeanor":"嗓门大，爱说“我跟你讲”“他妈的”，被戳到就拍桌子。","topics":[{"id":"t_role","q":"你负责什么？","a":"电工兼机修，圆顶电机、配电、柴油发电机，都归我管。三十二年了。有话你直说，别绕。"},{"id":"t_limit","q":"高度轴限位正常吗？","lie":true,"a":"正常得很！我修的东西不出岔子。限位开关下午我拆开看过，一点毛病没有，我拍着胸脯保证，错不了。","truth":"没拆干净。接触不良，我先用红线短接，说好第二天换。后来一忙就忘了。这事压得我睡不着。"},{"id":"t_after","q":"后半夜你在干什么？","lie":true,"a":"睡觉，睡得早。晚饭后我就回宿舍了，啥动静也没听见，是被人叫起来撬门，才知道出了事的。","truth":"我在食堂跟老盛他们打牌。山上禁赌，怕台长扣年终，没敢说。00:30到快两点，我一直在桌上。"},{"id":"t_brother","q":"你弟弟是怎么没的？","a":"2011年，圆顶齿轮箱检修没断电，他被卷进去了。台长签的字，说可以省一道手续。赔偿我拿了，没原谅。"},{"id":"t_door","q":"那扇门是你撬开的？","needs":["clue:c_dome3"],"a":"我撬的。02:14我敲半天没人应，叫上小阮，撬棍一别钢栓底座就崩了。台长已经凉了。"},{"id":"t_motor","q":"01:12的电机记录？","needs":["clue:c_pow1","ask:kan.t_limit"],"a":"这条我看了一晚上。SEQ 是序列自动跑的，不是手柄。可要不是我的跳线，限位拦得住。这事我认。"}],"confronts":[{"clue":"c_pow2","breaks":"t_limit","a":"他一把抓过检修单，吼道：“对，是我写的！”吼完肩膀塌下去，“我他妈就该当天拆了它。”"},{"clue":"c_can1","breaks":"t_after","a":"他嘿了一声，转向窗外：“行，我打牌了。一点钟老夏上厕所，我还骂他尿多。你们别跟台长讲。”"},{"clue":"c_pow1","a":"他盯着屏幕上的 SEQ：“序列……那个钟点台长早睡死了，哪来的手柄。有人在搞鬼，不是机器。”"},{"clue":"c_dome1","a":"他掀开白布看了一眼，立刻别过头：“配重杆……是我那根跳线放下来的。我弟那年也是这样。”"}],"fallback":"嗨，这个我不懂，你问别人。"},{"id":"sheng","name":"盛阿福","role":"后勤厨师","age":57,"look":{"skin":"light","hair":"bald","hairColor":"grey","glasses":"none","beard":"none","outfit":"apron","mood":"smile"},"bio":"东北人，来山上做饭十二年，全台的胃都归他管。称自己晚上收拾完厨房，就早早回屋睡下了。","demeanor":"爱说“哎呀妈呀”“整”，嘴碎心软，说着说着就唠起来。","topics":[{"id":"t_role","q":"你在台里做什么？","a":"哎呀妈呀，管全台十几口人的嘴呗！我东北人，来山上十二年，做饭、采买、烧锅炉，啥都整。"},{"id":"t_after","q":"后半夜你在干什么？","lie":true,"a":"我？早睡了！晚上收拾完灶台就回屋，鞋一脱就打呼噜。您问这个，是怀疑我呀，哎呀妈呀？","truth":"得，说实话。00:30我们四个在食堂支了一桌：夏师傅、阚师傅、小阮和我。山上禁赌，我怕被罚才撒谎。"},{"id":"t_flask","q":"台长的保温杯谁灌？","a":"夏师傅灌，二十年的老规矩，台长不爱喝别人沏的茶。我只烧水备茶叶，杯子连盖都不碰。"},{"id":"t_seen","q":"22:00前后谁来过食堂？","needs":["clue:c_can3"],"a":"22:00来灌杯的是夏师傅。我在帘子后收拾灶，瞧见他手里拿着张纸，没细看。台长夫人也来倒过热水。"},{"id":"t_rain","q":"00:20的雨你注意到了吗？","needs":["ask:sheng.t_after"],"a":"00:20我煮姜汤，我说老夏，下雨了你不上去看看缝？他说，让台长自己关。他平时比谁都跑得快。"},{"id":"t_game","q":"谁提出来打牌的？","needs":["ask:sheng.t_after"],"a":"老夏。他说晚上睡不着，想找人说话，山里闷。他平时不爱凑这热闹，这回头一遭主动叫人。"}],"confronts":[{"clue":"c_can1","breaks":"t_after","a":"他拍大腿：“得，我认！牌局是我张罗的。可夏师傅一直在桌上，一点钟去厕所，我数着秒，三分多钟。”"},{"clue":"c_can3","a":"“‘台长的杯，老规矩，谁也不碰’，我写的。夏师傅二十年没出过差错，你们别疑心他。”"},{"clue":"c_can2","a":"他看了一眼案台：“这是夏师傅刚用过的地儿。白粉？不是盐也不是糖，我家灶上没这种东西。”"}],"fallback":"哎呀，这我可真整不明白。"},{"id":"xue","name":"薛霁","role":"访问学者","age":36,"look":{"skin":"light","hair":"bob","hairColor":"black","glasses":"rect","beard":"none","outfit":"turtleneck","acc":"earrings","mood":"neutral"},"bio":"海外研究所派来的访问学者，在台里做三个月数据分析。当晚称在露台拍星轨，之后回房。","demeanor":"冷静、书面，爱夹英文词，被问到违规处会停顿。","topics":[{"id":"t_role","q":"你为什么在这里？","a":"访问学者，来台里做三个月巡天数据分析。我只是客人，不涉及台里的人事和资金，别牵扯我。"},{"id":"t_orion","q":"21:30你在哪？","lie":true,"a":"露台，拍星轨。大概21:30，猎户座腰带从东南升起，三颗星一字排开。后来回房了。","truth":"我没在露台，是编的。我在资料室用 U 盘拷巡天数据，21:24到23:01。没经批准，不该拷。"},{"id":"t_sky","q":"那晚的天象怎样？","a":"前半夜晴好，23:00月落。猎户座22:00以后才冒出东南山脊。00:20云压上来，雷电，很快下雨。"},{"id":"t_copy","q":"你拷了什么数据？","needs":["clue:c_ctrl4","ask:xue.t_orion"],"a":"台里近十年的巡天原始帧，38G。我只有读权限，借了个临时账号。违规，所以我不想谈。"},{"id":"t_heard","q":"你在资料室看到了什么？","needs":["ask:xue.t_copy"],"a":"22:50左右我抬头活动脖子，看见控制室里有人背对我坐在主机前，戴灰毛线帽，敲了十分钟键盘。"},{"id":"t_cap","q":"灰毛线帽是谁的？","needs":["ask:xue.t_heard","clue:c_ctrl1"],"a":"没看到脸。毛线帽山上人手一顶，我抽屉里也有。夏师傅算一个，说头疼怕风。我不敢凭这个指人。"}],"confronts":[{"clue":"c_ctrl4","breaks":"t_orion","a":"她看着拷贝日志，抿紧嘴唇：“你们很快。我在资料室，猎户座那段是编的，我必须有个不在场的说法。”"},{"clue":"c_dome4","a":"“‘月将落’，22:25。那时月亮还有十度高，23:00才落。”她抬头，“他的字比我想的更抖。”"},{"clue":"c_ctrl1","a":"“LST 00:32，恒星时。做天文的第一反应是往回减。减出来的钟点，和我看见背影的时候差不多。”"}],"fallback":"这个，technically 我不清楚。"},{"id":"zhong","name":"钟鸣鹤","role":"项目资助人","age":60,"look":{"skin":"light","hair":"slick","hairColor":"silver","glasses":"none","beard":"none","outfit":"jacket","acc":"pocketwatch","mood":"smirk"},"bio":"制造业企业家，新四米望远镜的最大资助人，一年六百万。傍晚请你上山，当晚住在半山腰的贵宾小楼。","demeanor":"商人口吻，爱说“格局”“投入产出”“这样吧”，不动声色。","topics":[{"id":"t_role","q":"你为什么资助这座山？","a":"投入产出，格局二字。栖云岭这块招牌值钱，四米镜头冠名，对我是品牌，对台里是命脉。"},{"id":"t_alone","q":"昨晚你一直在小楼？","lie":true,"a":"一个人，看了会儿书就睡了。这山上没人陪我聊天，倒也清静。你问这个，是怀疑到我头上来了？","truth":"费思齐来过，22:21到00:26，谈换届和续资助。台长不松口，我说得很重，威胁撤资。我撒谎是怕你们当动机。"},{"id":"t_money","q":"你真的会撤资吗？","a":"年度六百万，撤了台里撑不过两年。那话是谈判筹码。人死了冠名权也黄了，我没处使这钱。"},{"id":"t_window","q":"镜头为何对着你的小楼？","a":"我也想问！我没拉窗帘，一点十分上下，看见那白圆球突然转过来，天窗缝正对我的窗。我看了表，刚过一点十分。"},{"id":"t_call","q":"21:40你给台长打过电话？","needs":["clue:c_che3","ask:zhong.t_alone"],"a":"打了。我最后问了一次：冠名给不给。他说，钱可以不要，名字不卖。我火大，说那就别怪我撤。"},{"id":"t_fei","q":"你和费思齐谈了什么？","needs":["ask:zhong.t_alone"],"a":"换届。我支持他上，条件是冠名权归我的公司。他答应得痛快。出钱的人和副台长聊聊，不犯法吧？"},{"id":"t_seen","q":"你还看到什么异常？","needs":["ask:zhong.t_window","clue:c_che2"],"a":"雨来之前圆顶的缝一直敞着，里头有灯，我隔窗见半个人影坐着不动。早知道，我该打个电话上去。"}],"confronts":[{"clue":"c_che1","breaks":"t_alone","a":"他摘下表放在桌上：“好，是我不老实。费思齐22:21到的，00:26走。谈什么，你们去猜。”"},{"clue":"c_che3","a":"他看着自己的备忘，语气平淡：“撤资是气话。但我写下来了，对吧。你想把它当动机，我无话可说。”"},{"clue":"c_ctrl1","a":"他盯着那份序列看了会儿：“定时的？这么说，人不用在场。”苦笑一下，“我这个外行，也就看懂这一层。”"}],"fallback":"这样吧，这个问题，我们换个角度谈。"},{"id":"jian","name":"简文漪","role":"台长遗孀","age":58,"look":{"skin":"light","hair":"bun","hairColor":"white","glasses":"round","beard":"none","outfit":"robe","acc":"flower","mood":"sad"},"bio":"岑望川的妻子，退休的天文工作者，住在山上的家属宿舍。称自己晚饭后一直在宿舍看书。","demeanor":"温和、书卷气，常引星图、诗句，被问到丈夫会停顿。","topics":[{"id":"t_role","q":"你和台长的关系？","a":"三十四年的夫妻。我也学天文，早年在山上看过两年天，后来调去资料室，退休仍住山上。他倔，但肯认错。"},{"id":"t_night","q":"昨晚你最后见他是什么时候？","lie":true,"a":"晚饭后就没见了。他上圆顶，向来不喜欢人打扰，我吃完饭回宿舍看书，十点多就睡下了。","truth":"我见了他两次。21:40在办公室，我劝他去复查手，吵了一场。22:05我去食堂取热水，看见一件事，不敢说。"},{"id":"t_ill","q":"他的手是怎么回事？","needs":["clue:c_off3","ask:jian.t_night"],"a":"三个月前查出的早期帕金森。他不让我告诉别人，怕被推下台。他想在四米投产前，再上一次老镜头。"},{"id":"t_water","q":"你在食堂看到了什么？","needs":["ask:jian.t_ill","ask:sheng.t_seen"],"a":"22:05我看见小夏往台长杯里倒一包白粉，用筷子搅。他笑说是台长的维生素，嫌苦，化在茶里。我就信了。"},{"id":"t_xia","q":"你怎么看小夏？","a":"小夏跟了他二十四年，像半个儿子。台长待他严也护他，夏母的医药费是他跑三趟院办批的。可这几天小夏眼神很空。"},{"id":"t_door","q":"他为什么总要上门栓？","a":"怕人打扰，也怕人看见他发抖的手。早年有人推门进来漏了光，毁了一夜底片。那是他的壳。"}],"confronts":[{"clue":"c_off3","breaks":"t_night","a":"她看着诊断单，指尖抚过“告诉文漪”四个字，眼泪落下：“他到底还是想告诉我的……好，我说实话。”"},{"clue":"c_dome2","a":"她盯着保温杯，嘴唇发抖：“这只杯子，他用了二十年。”她闭了闭眼，“杯底是白的？……我知道了。”"},{"clue":"c_off2","a":"她翻到那行被划去的字：“‘夏守诚拍摄’……我早该知道。我劝过他，他说，历史不好改。”"}],"fallback":"这个……请原谅，我一时想不起来。"}],"solution":{"culprit":"xia","method":{"q":"凶手是怎么做到的？","options":["茶里下药，再预存定时序列，让望远镜甩向地平线砸中熟睡的人","用备用门卡潜入砸人，再撬坏门栓，伪装成内锁的现场密室","坐在控制室，用死者账号实时遥控望远镜砸向独处圆顶的人","死者自己操作手柄，被短接限位放行的配重杆意外击中身亡"],"correct":0},"motive":{"q":"为什么杀人？","options":["死者要终止凶手的合同，凶手要靠这份收入给病重亲人付医药费","多年前凶手的亲人死于圆顶检修，凶手一直恨死者当年的签字","死者拒绝让出冠名权，凶手想赶在撤资之前保住这笔资助款","死者把凶手首个发现署成自己的，又要取消他的岗位和机会"],"correct":3},"keyClues":["c_dome1","c_off1","c_ctrl1","c_ctrl2","c_pow1","c_off2"],"truth":["凶手是夜间观测员夏守诚。他没进过圆顶，那道内插的门栓，是台长自己插的。","22:05，夏把自己的安眠药碾碎，兑进他灌的保温杯。台长22:19进圆顶，22:41最后一次动手柄，写下“困”就睡着了，之后再无手柄操作。","22:52，夏借台长没退出的账号存下定时序列：01:12把望远镜甩向高度3度，软限位关闭。保存戳是恒星时“00:32”，减一小时四十分才是22:52。","限位早被阚大海跳线短接。01:12配重杆扫过折叠椅，击中熟睡的台长。夏当时在牌桌上，屋顶门磁却戳穿了他“在屋顶测风”的谎。","动机：夏装作怕丢饭碗，可母亲的医药费由台长私人承担。真正的原因是署名：2010年“岑星”首张底片是夏拍的，台长改署己名，展板至今只写“岑望川发现”。"]}},{"id":"paimai","title":"压轴之夜","tagline":"暴雨封楼，拍卖师死在上锁的鉴定室，台下的名画却分毫未损","difficulty":4,"cover":"coverAuction","tone":"purple","brief":"暴雨夜，云轩拍卖行二十八层，失传百年的《霁雪寒林图》将在22:30开拍，估价八千八百万。开拍前，首席拍卖师谷鸣远被发现死在上锁的鉴定室里，名画就在三步之外，毫发无损。山路被暴雨冲断，警方两小时后才能赶到。拍卖行股东请你，先在这段时间里把事情弄清楚。你手里只有六处能搜的地方，和八个各怀心事的人。凶手就在他们中间。","victim":{"name":"谷鸣远","age":62,"desc":"云轩首席拍卖师兼鉴定师，业内公认最难糊弄的“眼睛”。死在上锁的鉴定室内，后脑遭钝器重击。","look":{"skin":"light","hair":"sidepart","hairColor":"grey","glasses":"round","beard":"none","outfit":"suit","acc":"bow","mood":"stern"}},"publicFacts":["谷鸣远死在鉴定室。门自动落锁，发现时锁着，保安用主卡打开。","《霁雪寒林图》完好地摆在展台上，没有被盗，没有破损。","东走廊3号摄像头因雷击离线；贵宾厅摄像头正常。","山路冲断，电梯停运，二十八层的人都没离开过。","画由柯美玲送拍，恒安保险承保，保险调查员严松负责监封。"],"relations":{"yan":"承保这幅画的保险调查员，负责监封","han":"云轩特聘修复师，替死者修过这幅画","ke":"送拍人，墨痕画廊老板，和死者合作多年","he":"压轴竞买人，酒会上与死者有过照面","qian":"拍卖行大股东，和死者合伙三十年","su":"贴身助理，跟了他两年","peng":"拍卖行保安队长，管门禁和监控","luo":"他的学生，也曾是恋人"},"links":[{"a":"ke","b":"yan","text":"送拍人与监封保险调查员"},{"a":"yan","b":"he","text":"整晚在贵宾厅洽谈区聊天"},{"a":"han","b":"ke","text":"修复师与长期雇主"}],"deathReport":{"time":"约 21:30–22:15","cause":"后脑遭钝器重击","scene":"保安彭大海用主卡打开自动落锁的鉴定室，发现他倒在书桌与灯台之间。","loc":"loc_lab","notes":["后脑一处钝器伤，一击致命","门内侧无撬痕，门关上即自动落锁","沾血的青铜镇纸滚落在地毯上"]},"timeline":[{"t":"19:30","text":"预展酒会开始"},{"t":"20:28","text":"门禁：谷鸣远刷卡进入鉴定室，此后无刷卡记录"},{"t":"21:10","text":"系统：东走廊3号摄像头雷击离线"},{"t":"21:42","text":"手机记录：谷鸣远与柯美玲通话三分钟，是最后一通电话"},{"t":"22:05","text":"柯美玲自称敲鉴定室门无人应，随后去找保安"},{"t":"22:38","text":"门禁：保安主卡开鉴定室门；原定22:30的开拍中止"}],"budget":{"search":12,"ask":26},"locations":[{"id":"loc_lab","name":"鉴定室","scene":"study","desc":"顶楼东侧的鉴定室，门关上即自动落锁。谷鸣远倒在书桌与灯台之间。","clues":[{"id":"c_st1","title":"鉴定笔记","text":"末页：“灯下有荧光‘巳’，韩那批摹本？10/2交柯。封条S-4417。绢偏新。封箱那天谁在？真迹在哪？”后两行被划掉。"},{"id":"c_st2","title":"死者手机","text":"短信：20:55发韩述“来一趟”；21:20发严松“S-4417。十点前，来一趟。”21:42与柯美玲通话3分钟。"},{"id":"c_st3","title":"青铜镇纸","text":"沾血的镇纸滚在地毯上，没有清晰指纹，只有棉纤维压痕。门内侧无撬痕。"},{"id":"c_st4","title":"紫外灯下的画","text":"灯下，画的右下角浮出淡青色“巳”字荧光。画心绢的丝线整齐，没有旧损。旁边有白棉手套。"},{"id":"c_st5","title":"笔记压痕","text":"被划掉的两行在下一页留有压痕：“21:42 柯——当天不在场。封箱只剩监封人。”"}]},{"id":"loc_mon","name":"监控室","scene":"library","desc":"一面墙的屏幕和嗡嗡作响的主机，保安彭大海在这里值守。","clues":[{"id":"c_mon1","title":"贵宾厅截图","text":"时间戳22:15:06：严松与贺承握手，身后倒计时屏显示“距压轴开拍 00:34:54”。"},{"id":"c_mon2","title":"门禁记录","text":"鉴定室仅两条：20:28谷鸣远刷卡，22:38主卡开门。3号摄像头21:10离线。附截屏：“自动校时：关闭”。"},{"id":"c_mon3","title":"安防整改单","text":"恒安保险整改单第3项：“门禁及监控主机时钟与标准时间不符，建议校准。”审核人严松，10月9日。"},{"id":"c_mon4","title":"巡逻本","text":"21:35至22:00空白，夹着彩票和棋牌室会员卡。另记：“21:32钱总上天台抽烟，22:11下来。”"}]},{"id":"loc_vip","name":"贵宾厅","scene":"hall","desc":"深红地毯的贵宾厅，洽谈区沙发围着一面倒计时屏。","clues":[{"id":"c_vip1","title":"夜场流程单","text":"21:15–21:55洽谈区（严松/贺承）；21:55终场铃；22:30开拍。批注：“铃响一次；谷老师说十点前出来。”"},{"id":"c_vip2","title":"揉皱的合同","text":"沙发缝里的质押借款合同复印件：借款2600万，10月20日到期，柯美玲签名。末页压着半枚“……险 承保……”蓝章。"},{"id":"c_vip3","title":"竞价牌登记册","text":"贺承号牌旁有铅笔小字“10/11预览，谷老师特批”，访客栏被涂改，仍辨得出“贺”字。"}]},{"id":"loc_bk","name":"后台寄存间","scene":"backstage","desc":"拍卖厅后台的寄存间，金属架上码着箱包与周转箱。","clues":[{"id":"c_bk1","title":"勘验箱夹层","text":"17号架严松的勘验箱，夹层卷着樟木轴绢本，题签“霁雪寒林图”，背面有旧补绢，轴头刻“程”字。"},{"id":"c_bk2","title":"装箱签收单","text":"10月5日：14:05柯美玲、严松双签验画；14:10柯离场，14:50返回；14:25封箱，监封人只有“严松”。"},{"id":"c_bk3","title":"洛芷的提包","text":"湿漉漉的帆布包，内有笔式紫外手电和便笺：“绢不对，手感太新——你再看一遍。芷 20:35”。"},{"id":"c_bk4","title":"编目照片","text":"苏小棠平板里10月8日的照片：封条S-4417完好，另有开箱后的全幅画照，备注“别告诉谷老师”。"}]},{"id":"loc_res","name":"修复间","scene":"lab","desc":"拍卖行里的修复间，灯台、镊子、浆糊盆，韩述把这里当半个家。","clues":[{"id":"c_lb1","title":"摹本交接单","text":"10月2日，韩述交付柯美玲《霁雪寒林图》展示用摹本，“仅限展陈”，右下角有“巳”字暗记，柯签收。"},{"id":"c_lb2","title":"修复日志","text":"真迹7至9月在此修复，9月21日交还柯美玲；背面多处旧补绢，轴头刻“程”字。日志下压着催缴单。"},{"id":"c_lb3","title":"律师函","text":"墨痕画廊来函，催韩述退还预付的摹本费40万。页边批注：“柯不付尾款，我凭什么退”。"}]},{"id":"loc_bar","name":"酒廊","scene":"dining","desc":"预展酒会的酒廊，香槟塔空了一半，雨声压过了音乐。","clues":[{"id":"c_dn1","title":"遗落的备忘","text":"手机备忘录：“收购云轩全部股权，报价2.4亿，贺总方；谷若反对，不成，先拿他那10%。”署名钱立诚。"},{"id":"c_dn4","title":"掉落的信封","text":"收件人严松。内是澳门赌场逾期通知，欠港币一千九百万，限10月25日清偿。背面铅笔字：“4200 拍后”。"},{"id":"c_dn2","title":"酒廊账单","text":"洛芷20:45点威士忌，21:30结账。侍者备注：“一直在哭，中途没离开过吧台”。"},{"id":"c_dn3","title":"侍者便签","text":"“21:15韩先生从东走廊快步回来，脸色发白；21:20柯女士在走廊尽头打电话，声音发抖。”"}]}],"suspects":[{"id":"yan","name":"严松","role":"保险调查员","age":41,"look":{"skin":"light","hair":"sidepart","hairColor":"black","glasses":"rect","beard":"none","outfit":"suit","acc":"tie","mood":"smile"},"bio":"恒安保险理赔调查员，负责这幅画的承保、监封和安防审核。当晚多半在贵宾厅陪买家聊天。","demeanor":"斯文周到，爱说“按程序”，被问到要害语速更慢","topics":[{"id":"t_where","q":"案发时你在哪？","lie":true,"a":"我说过，九点一刻起我一直在洽谈区陪贺总，监控能证明。到十点一刻才起身，中间半步没离开。","truth":"铃一响，九点五十五，我就借口去洗手间走了。监控快二十分钟，我故意让你们信那个时间。我去见了谷先生。"},{"id":"t_contact","q":"你联系过他吗？","lie":true,"a":"没有。酒会上点过头，没单独说过话，也没收到他的任何消息。拍卖夜我习惯把手机静音。","truth":"短信我看到了，九点二十。我没回，铃响后去见了他。撒谎，因为那条短信一被看到，我就完了。"},{"id":"t_crate","q":"10月5日装箱？","lie":true,"a":"我按程序监封，柯女士全程在场，搬运工也在，封条当着大家的面贴的。签收单上都有记录。","truth":"柯美玲十四点十分就走了，封箱前那十五分钟库房只有我。我把角落圆筒里的摹本装进木箱，真迹卷进我的勘验箱。"},{"id":"t_clock","q":"知道时钟偏差吗？","lie":true,"needs":["clue:c_mon3"],"a":"整改单是例行公事，随手写一条建议。监控差几分钟太常见了，具体差多少，我真不清楚。","truth":"我清楚。十月九号审核时对过表，快整整二十分钟。那天我就想到，这能变成我的不在场证明。"},{"id":"t_case","q":"勘验箱里有什么？","lie":true,"needs":["clue:c_bk1"],"a":"就是些普通东西。只有仪器：放大镜、色卡、湿度计、手套和记录本。保险调查员的箱子里，还能有什么？","truth":"夹层里是真迹。港商出四千二百万，拍卖一结束我就带箱子走。摹本拍出去，谁还会查？谷鸣远偏偏查了。"},{"id":"t_ke","q":"你怎么看柯美玲？","lie":true,"needs":["clue:c_vip2"],"a":"柯女士这几年周转紧，圈子里都知道。她要是缺钱，把画质押再挂个摹本，也不是想不到。随口一说。","truth":"合同复印件是我塞进沙发缝的，魏老板的律师给过我一套。摹本一露，她的质押和谎话自己就连成一条线。"},{"id":"t_debt","q":"你最近手头宽裕吗？","lie":true,"needs":["clue:c_dn4"],"a":"说实话，我们这行薪水稳当，谈不上宽裕，也不算紧。我不好赌，公司背景调查里都有记录。","truth":"我欠了澳门一千九百万港币，催债的人已找到公司楼下。港商的四千二百万能还清。我本不想杀人，是谷鸣远逼的。"}],"confronts":[{"clue":"c_mon1","breaks":"t_where","crack":true,"a":"……三十五分钟。压轴二十二点半开拍，往回数，这一帧是九点五十五，不是十点十五。主机的钟不对，我比谁都清楚。"},{"clue":"c_vip1","breaks":"t_where","a":"终场铃九点五十五，流程单上有。我说陪到十点一刻，是照监控说的。铃响以后，我离开过洽谈区。"},{"clue":"c_st2","breaks":"t_contact","a":"九点二十，“十点前，来一趟”。我看到了。说没收到，是不想做他最后一条短信的收件人。"},{"clue":"c_bk2","breaks":"t_crate","a":"十四点十分离场，十四点五十回来，监封人一栏只有我一个名字。我说她全程在场……不是记错。"},{"clue":"c_bk1","breaks":"t_case","crack":true,"a":"……那是我的箱子，夹层里是什么，我无法再否认。轴头有“程”字款，是的，那才是真迹。"},{"clue":"c_mon3","breaks":"t_clock","a":"……那是我亲笔签的字。我说不清楚偏差，是装的。其实快了整整二十分钟，一分不差，你们算得对。"},{"clue":"c_dn4","breaks":"t_debt","a":"……信是我掉的。既然你们捡到了，我也不必再装了。欠款是真的，期限也是真的，一个字不假。"},{"clue":"c_vip2","breaks":"t_ke","a":"……这枚章是我们承保部的归档章。行，合同是我放的，我不会再说是柯女士自己弄丢的。"},{"clue":"c_st5","a":"他划掉的那两行……这么说，九点四十二分之后，他就不怀疑柯女士了。他想的是谁，我不替他说。"}],"fallback":"这和我无关，请按程序来。我愿意配合，但请别断章取义。"},{"id":"han","name":"韩述","role":"书画修复师","age":38,"look":{"skin":"light","hair":"messy","hairColor":"black","glasses":"round","beard":"stubble","outfit":"hoodie","mood":"worried"},"bio":"云轩特聘修复师，这幅真迹曾在他手里修复了三个月。当晚在修复间和酒廊之间来回跑动。","demeanor":"内向絮叨，爱用手艺人的比喻，紧张就搓手指","topics":[{"id":"t_job","q":"你和这幅画的关系？","a":"七月到九月，这幅画整整三个月在我案子上。揭裱、补绢、全色，我比它的主人更熟它的绢纹。"},{"id":"t_where","q":"案发前后你在哪？","lie":true,"a":"我一直在修复间收拾工具，后来去酒廊喝了两杯。鉴定室我没去过，谷老师忙，我哪敢烦他。","truth":"我去过。他发短信叫我，我九点到九点十二分在里面，被问得像审犯人。我走时他还活着，在调紫外灯。"},{"id":"t_copy","q":"你做过摹本吗？","lie":true,"a":"哎，摹本？没有没有，我是修复师，不是造假的。这行最忌讳摹本，我怎么可能去碰那种东西。","truth":"做过。十月二日交给柯美玲一幅展示用摹本，合同写明仅限展陈。我怕被当成调包的人，才说没有。"},{"id":"t_money","q":"你缺钱吗？","needs":["clue:c_lb2"],"a":"工作室欠三个月薪水，银行在催，柯美玲的尾款拖了又拖。缺是缺，可我不会用这种脏手段。"},{"id":"t_msg","q":"他找你说了什么？","needs":["clue:c_st2"],"a":"他问摹本交给了谁，我说只交了柯美玲。又问装箱那天谁在，我答不上。他说心里有数了，让我回去。"},{"id":"t_mark","q":"“巳”字暗记？","needs":["clue:c_st4"],"a":"我的习惯，每幅摹本右下角加“巳”，紫外灯下才显形，防有人拿摹本冒充真迹。没想到谷老师靠它查出了问题。"}],"confronts":[{"clue":"c_st2","breaks":"t_where","a":"……这条短信是我的名字。好吧，我去过。一想到说出来我就成了最后见他的人，我就怕。"},{"clue":"c_dn3","breaks":"t_where","a":"啊，侍者看见我九点十五分快步回来？对，我刚从鉴定室出来，吓得脸白得像宣纸一样，自己都知道。"},{"clue":"c_lb1","breaks":"t_copy","a":"……交接单上有柯美玲的签名。我否认，是想撇清自己，现在没办法了，摹本是我做的，我认。"},{"clue":"c_bk1","a":"这几处补绢是我七月亲手补的，轴头的“程”字款也在。这才是真迹。它怎么会在保险公司的箱子里？"}],"fallback":"我只会修画，别的真不懂，您问点我能答的行吗？"},{"id":"ke","name":"柯美玲","role":"墨痕画廊主","age":52,"look":{"skin":"light","hair":"bun","hairColor":"black","glasses":"none","beard":"none","outfit":"qipao","acc":"necklace","mood":"stern"},"bio":"墨痕画廊老板，这幅画的送拍人，成交后她拿大头。当晚多在酒廊应酬，十点后敲过鉴定室的门。","demeanor":"干练强势，爱抬高声调，被戳到痛处会压低声音","topics":[{"id":"t_replica","q":"这幅画有摹本吗？","lie":true,"a":"荒唐！摹本？我们做画廊的，最忌讳真迹旁边放仿品，哪来的摹本。你们别听风就是雨，乱猜。","truth":"有。韩述十月二日交给我一幅展示用摹本。我没告诉拍卖行，怕保险公司觉得保管不严，不肯承保。"},{"id":"t_present","q":"10月5日装箱你在吗？","lie":true,"a":"这还用问？当然在，从头到尾都盯着。封条是当着我的面贴的，严先生和搬运工都能作证。","truth":"我十四点十分出去了，四十分钟，有个人必须见。库房里只剩严松监封。我越想越怕，才硬说全程在场。"},{"id":"t_call","q":"你们最后说了什么？","lie":true,"a":"没什么，那通电话只聊夜场流程，叮嘱我别紧张，开拍时坐第一排替藏家举牌。统共才三分钟。","truth":"他问我装箱那天在不在场。我说我出去了一会儿。他沉默很久，说：“知道了。等拍卖完我再找你。”"},{"id":"t_knock","q":"你去敲过鉴定室？","a":"十点零五分左右敲了三下，没人应。我等了几分钟才去找保安。动主卡要先报备，磨了十来分钟才开门。"},{"id":"t_loan","q":"你很缺钱吗？","needs":["clue:c_vip2"],"a":"是。魏老板的质押款十月二十号到期，拍卖成交我才还得上。保险公司那边我瞒着。今晚我连贵宾厅都没进过。"},{"id":"t_yan","q":"封箱那天还有谁？","needs":["clue:c_bk2"],"a":"监封的是严先生，就他一个。我走前画是两人一起核对的，回来封条已贴好。库房没锁，我信得过他。"}],"confronts":[{"clue":"c_lb1","breaks":"t_replica","a":"这是我的签名……好吧，摹本有的。它一直躺在库房圆筒里，我没碰过，别把我往坏处想。"},{"clue":"c_bk2","breaks":"t_present","a":"……签收单写着我离场，我还能说什么。我撒谎，是怕保险失效，质押方就会立刻抽贷，我赔不起。"},{"clue":"c_st2","breaks":"t_call","a":"……他手机里记着我，三分钟。好，我说实话，他问的是封箱，不是流程。我当时慌了，所以才……"},{"clue":"c_vip2","a":"合同内容是我的，可我没复印过，更没带到这儿。这个章是保险公司的？我连贵宾厅都没去过。"},{"clue":"c_dn3","a":"是，我在东走廊求魏老板宽限日子。声音抖，是急的，换了你被逼到那份上，也会哭出来。"}],"fallback":"这和我没关系，我只关心画能不能顺利拍卖。"},{"id":"he","name":"贺承","role":"压轴竞买人","age":49,"look":{"skin":"tan","hair":"slick","hairColor":"black","glasses":"none","beard":"mustache","outfit":"jacket","acc":"pocketwatch","mood":"smirk"},"bio":"地产起家的富商，今晚最可能拿下压轴拍品的买家。酒会大半时间都在贵宾厅和严松聊天。","demeanor":"豪爽带江湖气，爱叫人“老弟”，急了会拍桌子","topics":[{"id":"t_job","q":"你为什么想拍这幅画？","a":"哈哈，老弟，我就缺一幅压得住场的雪景。这幅画来历干净，名头又响，该花的钱我不省。"},{"id":"t_know","q":"你认识谷鸣远吗？","lie":true,"a":"谷老师？今晚酒会才第一次见，隔着人群点了个头而已。我一个做地产的，哪有什么交情。","truth":"十月十一号我私下来预览过，他特批的。我想探别的买家上限，他翻脸骂我。我怕号牌被吊销，才装不熟。"},{"id":"t_talk","q":"你和严松聊了什么？","a":"艺术品投资，保险条款、估值逻辑，一套一套的。九点一刻起在洽谈区坐下，聊了将近四十分钟。"},{"id":"t_bell","q":"终场铃响时他怎样？","needs":["clue:c_mon1"],"a":"铃一响他就起身，说去趟洗手间，让我先进场。我抬头看了倒计时，三十五分钟，记得清楚。之后没再见到他。"},{"id":"t_qian","q":"你和钱立诚有往来吗？","lie":true,"a":"哈，钱总？酒会上碰过一杯，没有往来。他是云轩股东，不过如此，你别把我和他扯一块儿。","truth":"我在谈收购云轩，价码二点四亿，钱立诚是中间人。谷鸣远不松口就黄了。我怕你们把收购和命案扯一起。"},{"id":"t_bid","q":"你打算出到多少？","a":"我直说，一亿二的底线，再多我就走人。这事谁问我都这么说，拍卖场上讲的就是干脆利落。"}],"confronts":[{"clue":"c_vip3","breaks":"t_know","a":"哎呀，连“贺”字都涂改出来了？行，我认。那次预览是我求他特批的，你们别往歪处想。"},{"clue":"c_dn1","breaks":"t_qian","a":"“贺总方”，那是钱立诚的手机。是，我们在谈收购。谷鸣远是最大的拦路虎，我得瞒着。"},{"clue":"c_mon1","a":"没错，这就是我说的，铃响他起身，那块倒计时三十五分钟。我先进的场，他没跟上来，我可没看见他。"}],"fallback":"老弟，这个我真不清楚，你换个问法。"},{"id":"qian","name":"钱立诚","role":"拍卖行大股东","age":58,"look":{"skin":"light","hair":"bald","hairColor":"grey","glasses":"round","beard":"none","outfit":"vest","acc":"bow","mood":"sly"},"bio":"云轩持股最多的股东，主管财务后勤。与谷鸣远合伙三十年，近来为股权去向屡次发生争执。","demeanor":"官腔十足，爱说“按公司章程”，被追问就绕圈子","topics":[{"id":"t_job","q":"你在公司负责什么？","a":"我主管财务与后勤。按公司章程，估值与成交归鉴定部和拍卖师，我不干涉。老谷是首席。"},{"id":"t_where","q":"案发前后你在哪？","lie":true,"a":"这还用问，我一直在拍卖厅调试大屏和音响，九点半到十点一刻都在，工作人员都能作证。","truth":"我九点半多上了天台，说是抽烟，实则一直跟对方律师通电话，十点十一分才下来。那通电话在谈出卖公司。"},{"id":"t_stock","q":"他的股份会怎样？","a":"老谷持有百分之十，无继承人，按章程由公司回购或转给其他股东。谁受益我明白，所以先说清楚：我没杀他。"},{"id":"t_deal","q":"你在谈收购吗？","needs":["clue:c_dn1"],"lie":true,"a":"哈，收购？没有的事，股权上的事我从来不碰。一条没头没尾的备忘录，说明不了什么问题。","truth":"我谈了。贺承出价二点四亿，条件是拿到老谷的百分之十，老谷不同意。可我没杀他，他死了交易反而悬了。"},{"id":"t_roof","q":"你在天台和谁通话？","needs":["ask:qian.t_where"],"a":"对方的律师，姓顾。九点三十四分打出，十点零九分挂断，一共三十五分钟，通话记录尽管去查。"},{"id":"t_clock","q":"你知道监控时钟吗？","a":"那是安保部的事。我只在年终会上听老彭提过一句，主机老了该换了，具体偏差我没留意。"}],"confronts":[{"clue":"c_mon4","breaks":"t_where","a":"彭大海居然把我上天台的时间都记下来了？……行，我认，那段时间我确实不在拍卖厅里。真是榆木脑袋。"},{"clue":"c_dn1","breaks":"t_deal","a":"……这是我的手机，备忘录是我写的。收购我一直在推，老谷不点头，我一个人做不了主。"},{"clue":"c_vip2","a":"哦，柯美玲的质押合同？我头一次见。公司没有备案，这事你们该去问她本人，别来问我。我真的毫不知情。"}],"fallback":"这个问题，按公司章程，我无可奉告。"},{"id":"su","name":"苏小棠","role":"拍卖助理","age":25,"look":{"skin":"fair","hair":"ponytail","hairColor":"brown","glasses":"none","beard":"none","outfit":"dress","acc":"headset","mood":"worried"},"bio":"谷鸣远的贴身助理，管流程、编目和竞买人登记，跟了他两年。当晚戴着耳麦在场内跑来跑去。","demeanor":"语速飞快，爱说“哎呀”“真的啦”，紧张就咬嘴唇","topics":[{"id":"t_job","q":"你平时做什么？","a":"我是谷老师的助理，流程单、编目、号牌登记，全是我的活。他脾气硬，但平时很照顾我。"},{"id":"t_tea","q":"你最后见他是何时？","a":"二十点十分，我给他送了壶茶。他在门口接过去，说“今晚谁也别打扰我”，还叮嘱我十点前准时敲铃。"},{"id":"t_open","q":"编目时你开过箱吗？","lie":true,"a":"没开过呀，真的啦。箱子原封到的，封条S-4417完好，我只核对封条，开箱是谷老师的权限。","truth":"我开过。十月八日偷偷拧开侧板拍了照，想赶在谷老师前做图录，违规了。封条没动，我动的是侧板螺丝。"},{"id":"t_photo","q":"照片里的画有问题吗？","needs":["clue:c_bk4"],"a":"我看不出来……绢色、题款、印章都对。我不是鉴定师，要是有问题，只有谷老师看得出。"},{"id":"t_see","q":"终场铃后你看见谁？","needs":["ask:he.t_bell"],"a":"我在厅门口收号牌。大概十点零八分，严先生从东边走廊那头过来，说洗手间排队，找了个靠后的座位。"},{"id":"t_list","q":"号牌名单给过谁？","a":"真的，没有啊……只有贺总的助理私下问过我一嘴，我没给。你们别外传哦，我会被开除的。"}],"confronts":[{"clue":"c_bk4","breaks":"t_open","a":"啊，这是我的平板……好吧，我违规了。我只是想早点做图录，真的没想到会出这种大事。"},{"clue":"c_vip1","a":"嗯，这是我打的流程单，批注也是我写的，是谷老师亲口说的，他说十点前就出来，我记得清楚。"},{"clue":"c_st1","a":"啊，这是谷老师的笔迹。“真迹在哪？”……他是不是早就发现了，画被人换了？天哪，他当时一定很难受。"}],"fallback":"哎呀，这个我真不知道，你别吓我……"},{"id":"peng","name":"彭大海","role":"保安队长","age":46,"look":{"skin":"tan","hair":"short","hairColor":"black","glasses":"none","beard":"stubble","outfit":"uniform","acc":"badge","mood":"stern"},"bio":"云轩保安队长，退伍军人，管门禁、监控和夜巡。当晚用主卡打开鉴定室，发现了谷鸣远。","demeanor":"军人腔，爱说“报告”，被问到痛处声音变大","topics":[{"id":"t_clock","q":"监控时间准确吗？","lie":true,"a":"报告，准！主机每天自动校时，误差不超过几秒，我天天盯着。所有时间戳，你们放心当真。","truth":"报告，不准。去年自动校时老让摄像头掉线，我就关了，主机越走越快，现在快了二十分钟。我怕扣奖金，没敢报。"},{"id":"t_post","q":"你整晚在监控室吗？","lie":true,"a":"没错！报告，整晚没离开过监控室，眼睛都没眨一下。要是有人进出，我不可能不知道的。","truth":"报告，九点三十五到十点我溜去消防楼梯间打牌，监控室没人。我知道失职，可我真没碰过鉴定室。"},{"id":"t_open","q":"你怎么开的门？","a":"柯女士十点零八分来找我，说敲门没人应。主卡要先报备，十点十八分开门，谷先生已倒地，我立刻报警。"},{"id":"t_door","q":"谁能进鉴定室？","a":"门自动落锁，能开的有两张卡：谷先生的，和我的主卡。里面的人要放人进来，按钮一按门就开。按钮不留记录。"},{"id":"t_cam","q":"东走廊摄像头？","needs":["clue:c_mon2"],"a":"雷击，3号那一路跳闸，要去配电间手动合闸。我想巡完这轮再去，一拖就出了事。这事我认。"},{"id":"t_offset","q":"时钟偏了多少？","needs":["clue:c_mon3"],"a":"二十分钟，我拿手机对过。严先生来过，说整改月底前做完就行，夜场前千万别动系统。我就顺坡下驴，拖着了。"}],"confronts":[{"clue":"c_mon2","breaks":"t_clock","a":"……报告，设置页是我截的，“自动校时：关闭”，是我关的。我愿意受处分，不再瞒了。"},{"clue":"c_mon4","breaks":"t_post","a":"报告，空白那一栏，就是我溜走的时间。我认罚，只求你们别把我赌博的事告诉老板，我还要养家。"},{"clue":"c_mon1","a":"报告，这帧时间戳十点十五分，可我觉得，这块倒计时屏看着不对劲。我不是技术员，说不准。"}],"fallback":"报告，这个我不清楚，请换个问题。"},{"id":"luo","name":"洛芷","role":"博物馆研究员","age":33,"look":{"skin":"light","hair":"long","hairColor":"black","glasses":"round","beard":"none","outfit":"turtleneck","acc":"scarf","mood":"sad"},"bio":"谷鸣远的学生，也曾是他的恋人，现在省博做书画研究。受他邀请来看夜场，多半时间在酒廊独坐。","demeanor":"冷静克制带自嘲，被刺痛时会笑一下","topics":[{"id":"t_relation","q":"你们是什么关系？","a":"师生，也曾经不止是师生。都过去了，各过各的日子，这些年很少联系，你们真的不用多想。"},{"id":"t_visit","q":"你单独见过他吗？","lie":true,"a":"没有，没有。我一直待在酒廊，没去过鉴定室，也没有单独见过他。请你们别把我扯进来。","truth":"我去过。二十点二十分到四十分，我和他吵了一架，提醒他那幅画绢手感太新。我撂下一句“你会后悔的”就走了。"},{"id":"t_paper","q":"为什么说手感太新？","needs":["clue:c_bk3"],"a":"我摸过上百幅清初绢本，那幅画的画心绢太新太挺括。可我没勇气说它是假的，怕错，也怕对。"},{"id":"t_after","q":"九点半后你在哪？","a":"我嘛，二十一点半离开酒廊后，我在楼梯间坐着，雨声很大，我哭了一阵。这些没人能证明。"},{"id":"t_old","q":"你们的旧事？","needs":["ask:luo.t_visit"],"a":"九年前他答应推荐我去故宫，后来因一场鉴定风波撤回了。我恨过他很多年，后来才明白是为了保护我。"},{"id":"t_victim","q":"你觉得他遇到了什么？","a":"他太认真了，认真的人容易得罪人。请柬上只写“来看一幅画”，他多半在为这幅画发愁。"}],"confronts":[{"clue":"c_bk3","breaks":"t_visit","a":"那是我的包，便笺是我写的，时间也是真的。好，二十点三十五分我还在鉴定室，我去过。"},{"clue":"c_dn2","a":"二十点四十五到二十一点三十分我都在吧台，侍者能证明。我不是不想说，是怕被问更多。"},{"clue":"c_st4","a":"“巳”字……他是不是已经确认，那是摹本了？我的直觉没错，可我宁愿是自己看错了，真的。"}],"fallback":"我只想知道真相，别的与我无关。"}],"solution":{"culprit":"yan","method":{"q":"凶手怎么做到的？","options":["电话后敲门对质，争执中抓起镇纸行凶","买通保安用主卡开门，行凶后门自动落锁","茶中下药待其昏睡后再动手，并伪造死亡时间","借时钟快二十分钟造不在场，被放行后行凶"],"correct":3},"motive":{"q":"为什么杀人？","options":["为填质押借款窟窿换画，被识破后灭口","为还赌债私卖真迹，被死者识破后灭口","收购案中拿了好处，死者拒让股份而遇害","共同隐瞒旧日鉴定失误，为保名声灭口"],"correct":1},"keyClues":["c_mon1","c_vip1","c_st1","c_st2","c_bk1","c_bk2"],"truth":["凶手是保险调查员严松。他欠下赌债，10月5日监督装箱，柯美玲14:10离场，库房只剩他一人。他把摹本封进木箱，真迹卷进自己的勘验箱夹层，港商出价四千二百万。","谷鸣远终检，在紫外灯下照出摹本上韩述留的“巳”字暗记。他21:20短信召严松，21:42问柯美玲封箱时在不在，得知她不在，划掉了对她的怀疑。","第一个假结论是柯美玲：缺钱、撒谎、有摹本和质押合同，又是最后通话人。但14:05双签证明离场前画是真的，封箱时她不在场。","第二个假结论是严松的不在场证明：监控显示他陪贺承到22:15。其实监控快了二十分钟，倒计时换算是21:55，即终场铃响时。整改单上有他亲笔写的时钟不符。","21:58，严松戴手套，被谷鸣远按钮放行，趁其转身用镇纸行凶。他还把合同复印件塞进沙发缝，上面的承保章反而指向他。"]}},{"id":"zujie","title":"留声","tagline":"满座宾客都听见他在门里念稿，可那扇门是从外面锁上的。","difficulty":4,"cover":"coverGramophone","tone":"sepia","brief":"一九三七年八月底，上海法租界，闸北炮声不断。泰和洋行买办顾鸿章在公馆办欢送酒会，致词前却死在反锁的书房里。公馆里挤着英国大班、日本记者、来历不明的女学生。巡捕房的老朋友怕牵出外交纠纷，半夜把你请来。二十来位宾客被扣在原地，钢琴早已没人弹了。你到时，客人们异口同声：九点四十一分，顾老爷还在书房里排练致词，还活着。","victim":{"name":"顾鸿章","desc":"泰和洋行买办，五十八岁。仰卧在二楼书房书桌后，后脑被重物击伤。门从外面反锁，窗闩却是抬起的。","look":{"skin":"light","hair":"slick","hairColor":"grey","glasses":"rect","beard":"mustache","outfit":"suit","acc":"pocketwatch","mood":"stern"}},"publicFacts":["顾鸿章是泰和洋行买办，周二将去香港，今晚酒会是欢送，也为二十二点的致词。","二十二点十分，管家周福用钥匙开反锁的书房门，发现顾死在书桌后，凶器像是桌上的铜镇纸。","书房钥匙共三把：顾自己一把（在口袋里）、管家一把、账房钱仲平一把。","大班哈考特与钱仲平称，二十一点四十一分在门外听见顾排练致词，众人据此认为那时他还活着。","公馆里有英国大班、日本记者、女学生，据说阁楼还有人发电报。十点后大门落锁，宾客不得离开。"],"relations":{"qian":"顾家做了二十二年的账房先生","hark":"顾的上司，泰和洋行英国大班","shen":"顾的正室太太，酒会女主人","bai":"顾的姨太太，原是百乐门歌女","ming":"顾家过继的养子，住三楼阁楼","shi":"凭白露名帖进门的日本记者","zhou":"在顾家管了三十年的老管家","lin":"白露请来弹琴的女学生"},"links":[{"a":"bai","b":"shi","text":"白露引他进的酒会"},{"a":"bai","b":"lin","text":"白露介绍她来弹琴"},{"a":"shen","b":"ming","text":"太太娘家侄孙，过继给顾家"},{"a":"hark","b":"qian","text":"一同在书房门外听过声音"}],"deathReport":{"time":"约 20:30–22:00","cause":"后脑遭钝器重击","scene":"二十二点十分，管家周福用钥匙打开反锁的书房门，见顾仰卧在书桌后，窗闩抬起。","loc":"study","notes":["后脑塌陷，伤口一处","桌角铜镇纸沾有血迹","法式窗虚掩，窗外露台湿漉漉"]},"timeline":[{"t":"19:30","text":"晚宴开席，二十几位宾客入座。"},{"t":"20:40","text":"宾客移至大客厅，林素秋弹钢琴，白露放留声机。"},{"t":"21:41","text":"大班与账房称在书房门外听见顾排练致词。"},{"t":"22:00","text":"原定致词时间，顾没有出现。"},{"t":"22:10","text":"管家开门发现顾死亡，窗闩抬起，门反锁。"},{"t":"22:15","text":"公馆报案，巡捕房通知了你。"}],"budget":{"search":12,"ask":26},"locations":[{"id":"study","name":"顾鸿章的书房","scene":"study","desc":"二楼走廊尽头的大书房，厚地毯、红木书桌。尸体已盖上白布，门被管家用钥匙开过。","clues":[{"id":"c_study1","title":"书房的手摇唱机","text":"唱机发条已松尽，唱针停在刻录盘最里圈，盘面写“致词 一”。制动杆上缠着一截烧焦的红棉线，旁有半寸线香头。"},{"id":"c_study2","title":"死者的状态","text":"顾鸿章仰卧，后脑塌陷，血已发暗干结。医生二十三点才到，记录：下颌颈项僵硬，指尖冰凉。桌角铜镇纸沾血。"},{"id":"c_study3","title":"刻录盘试听","text":"放“致词 一”：顾的声音念告别词，清了嗓子，说“我先静一静，稍后再出来”，底噪沙沙。“致词 二”盘面无磨痕。"},{"id":"c_study4","title":"门锁与钥匙","text":"弹子锁，只能从外面用钥匙反锁。顾的钥匙在他口袋里。锁共三把：顾、管家、账房钱仲平各一把。"},{"id":"c_study5","title":"半开的法式窗","text":"窗闩被抬起，窗扇虚掩。但窗框上的薄灰完好，没有蹭痕；窗外这晚下过雨，露台边缘湿漉漉的。"}]},{"id":"acct","name":"账房","scene":"library","desc":"一楼后侧的小账房，满柜线装账簿，一股檀香味。钱仲平平日在此办公，门没锁。","clues":[{"id":"c_acct1","title":"线轴与线香","text":"桌上有装订账册的红棉线轴，线头剪口还新。香筒里插着粗细相同的线香，其中一支只剩半截。"},{"id":"c_acct2","title":"两套账簿","text":"保证金账页页盖“钱”字朱印，四十二万以“寄港·K.M.”转出。顾的私账里，K.M.即香港“金茂行”，户主是顾的化名。"},{"id":"c_acct3","title":"钱的存折","text":"折上是钱仲平四千八百元全部积蓄，存在顾家“鸿泰钱庄”，八月二十六日起盖“暂缓提取”。折下压便条：“儿媳产期在十月”。"},{"id":"c_acct4","title":"最底层的抽屉","text":"抽屉没有上锁，轨道很顺。吸墨纸上压出一个钥匙大小的凹印，里面是空的，沾着一点檀香灰。"}]},{"id":"hall","name":"大客厅","scene":"hall","desc":"摆着钢琴和留声机的大客厅，酒会残局未收，窗外隐约传来闸北的炮声。","clues":[{"id":"c_hall1","title":"舞会节目单","text":"背面铅笔写着：“林小姐：21:38起停琴七分钟（老爷要排练致词）。21:45恢复。”红笔圈着“22:00致词”，无署名。"},{"id":"c_hall2","title":"电话便条","text":"“21:10吴律师来电，请太太回电，说遗嘱和房契的事。我敲了太太卧房的门，太太在里头应了一声。”落款是佣人。"},{"id":"c_hall3","title":"来宾签名簿","text":"最后一栏潦草写着“石川谦”，介绍人是“白露夫人”，没有请柬编号，旁边有人用铅笔打了问号。"},{"id":"c_hall4","title":"沙发上的手袋","text":"手袋里有本窄小册子，页页是四位数字和圈叉，夹着白鸽票和马票存根，还有一张去香港的两人船票收据。"}]},{"id":"garden","name":"花园与露台","scene":"garden","desc":"洋房后的草坪和露台，夜里下过雨，泥地潮软。墙角立着一只焚烧落叶的铁桶。","clues":[{"id":"c_gar1","title":"焚烧桶里的残纸","text":"灰底压着半张毛边纸，右下角有朱红“钱”字方印，纸边一排针孔。残字：“……自承……所亏……无异议”。"},{"id":"c_gar2","title":"窗下的花坛","text":"露台下的花坛泥土松软，没有脚印通向窗台。远处树荫下草被踩平，落着五六个“敷岛”牌烟头。"},{"id":"c_gar3","title":"掉落的胶卷盒","text":"树荫下的草丛里有只空胶卷盒，盖上用指甲划了个“I”字。附近的草被压得很平，正对书房窗口。"}]},{"id":"attic","name":"三楼阁楼","scene":"guestroom","desc":"顾明远住的阁楼客房，斜顶小窗，一张行军床，满屋焊锡和旧木头的味道。","clues":[{"id":"c_att1","title":"藏在箱里的电台","text":"床下箱里有台短波发报机。日志记“21:04起·21:29止”，批注“21:08新底本到（素）”，每行签“明”字。"},{"id":"c_att2","title":"《圣经》密码页","text":"床头英文《圣经》里夹着手抄数字，对应章节行数，是一套以经文为底的密码。扉页写着“林素秋，圣玛丽女校”。"},{"id":"c_att3","title":"顾写给明远的字条","text":"顾的手书：“那东西明晚之前搬走，不然我自己送去公董局。你想害我们全家吗？ 鸿”。日期八月二十三日。"}]},{"id":"kitchen","name":"厨房与后楼梯","scene":"kitchen","desc":"一楼后侧的厨房，连着通二楼的后楼梯和通花园的后门，碗碟堆了半个灶台。","clues":[{"id":"c_kit1","title":"灶间的湿毛巾","text":"毛巾架上挂着潮湿的粗布毛巾，有一抹淡褐红痕和檀香味。厨娘说九点一刻过些，一位穿长衫的先生在这冲过手。"},{"id":"c_kit2","title":"领用单","text":"领用簿记：“20:30书房 冰一桶 酒杯二只 周福取”；“20:55书房 咖啡两份——钱先生说不必，退”。红棉线钉成。"},{"id":"c_kit3","title":"后门的泥印","text":"后门内侧有新鲜的布鞋泥印。木盒盖上写“周”，骰盅下压着“福记牌档”筹码票，红戳：入21:02，出21:14。"}]}],"suspects":[{"id":"shen","name":"沈婉仪","role":"顾太太","age":51,"look":{"skin":"light","hair":"bun","hairColor":"grey","glasses":"none","beard":"none","outfit":"qipao","acc":"necklace","mood":"stern"},"bio":"顾鸿章的正室，酒会的女主人。说自己一直在客厅招呼女眷，直到管家喊人才知道老爷出了事。","demeanor":"端着架子，冷而克制，开口先“我们顾家”，被戳痛处就笑。","topics":[{"id":"t_role","q":"你们是怎样的夫妻？","a":"顾家二十六年。他是买办，我是顾太太，该有的体面一样不缺。外头怎么说，我一概不管。你还想问什么？"},{"id":"t_where","q":"案发时你在哪？","lie":true,"a":"客厅，陪几位银行太太说话，一步没挪。我是女主人，怎么能随便离席？你尽管去问她们。","truth":"我二十点五十分上了楼，在他卧房翻抽屉，待到九点二十分。我想找船票，想知道他是不是要把我留下。"},{"id":"t_noise","q":"楼上听到什么？","needs":["ask:shen.t_where"],"a":"落地钟敲过九点没几分钟，我站在楼梯口，听见书房一声闷响，像重物倒了，接着是玻璃碎地声。我没理会。"},{"id":"t_marriage","q":"感情和睦吗？","lie":true,"a":"夫妻之间有什么不和睦？二十六年没红过脸，要说不顺心，也是这世道不顺心，与我们无关。","truth":"和睦？我翻到两张周二去香港的头等票，一张他，一张白露。没有我的。他要把我留给炮火。"},{"id":"t_will","q":"吴律师为何来电？","needs":["clue:c_hall2"],"a":"遗嘱的事。八月二十号老爷改过一次。九点二十我在楼上分机回话，律师说大头给了“不认得的户头”。"},{"id":"t_ming","q":"对养子怎么看？","a":"明远是我娘家侄孙，聪明，就是心太野，跟些来历不明的同学来往。老爷为他发过几次火。"}],"confronts":[{"clue":"c_hall2","breaks":"t_where","a":"她盯着“敲了太太卧房的门”，嘴角抽了抽。“佣人嘴快。”她终于说，“我那时在楼上。”"},{"clue":"c_hall4","breaks":"t_marriage","a":"她指甲掐进掌心。“船票收据，两个名字……那就不必装了。我气得发抖，也想过杀人，可没动手。”"},{"clue":"c_study2","a":"她看着白布下的人形，良久。“僵了？那么九点过的那声闷响，就是……”话没说完，手撑住了椅背。"}],"fallback":"这些我不懂，你去问账房与管家。"},{"id":"qian","name":"钱仲平","role":"账房先生","age":55,"look":{"skin":"light","hair":"short","hairColor":"grey","glasses":"round","beard":"none","outfit":"robe","acc":"pocketwatch","mood":"tired"},"bio":"顾家账房二十二年，经手全部账目。说九点半后在大厅招呼客人，还陪大班去过书房门口。","demeanor":"恭谨、絮叨，爱说“不敢”，被问急了就擦眼镜。","topics":[{"id":"t_role","q":"你管什么？","a":"洋行保证金、家里开销、钱庄往来，都是小的经手。二十二年了，账上的章只有我这一枚。"},{"id":"t_last","q":"最后见他？","lie":true,"a":"二十点五十几分，我送账册进书房，老爷看了两眼说声“知道了”，我就退出来了，再没进去过。","truth":"我没退出来。他拿字据逼我画押，说四十二万亏空全是我经手。我抄起镇纸……九点过一刻才出来。"},{"id":"t_where","q":"21点你在哪？","lie":true,"a":"在账房一个人对着账册，灯亮着，门也开着。九点半光景才去大厅添茶，厨房的人都能作证。","truth":"我不在账房。我从后楼梯下来，在灶间冲手，又去了花园。周福撞见我，我说是烫着了手。"},{"id":"t_alive","q":"21:41听见什么？","lie":true,"needs":["ask:qian.t_where"],"a":"我陪大班去书房门口，老爷在里头排练致词，还清了嗓子。那时他活着，凶手只能是翻窗的外人。","truth":"那不是老爷。九点十分我放上“致词一”，红线拴住制动杆，搭在点着的线香上。香烧线断，盘就转了。"},{"id":"t_stop","q":"为何要林小姐停琴？","needs":["clue:c_hall1"],"a":"是我传的话，说老爷要排练致词，请清静七分钟。我也请大班去听听，洋人在旁，老爷脸上有光。"},{"id":"t_window","q":"书房的窗怎么回事？","needs":["clue:c_study5"],"a":"窗闩抬着，窗虚掩着。依小的愚见，是外头来的人翻窗行凶，再翻出去。闸北那么乱，谁说得清。"},{"id":"t_key","q":"你那把钥匙呢？","lie":true,"needs":["clue:c_study4"],"a":"一直锁在账房抽屉里，没动过。抽屉的小钥匙我随身带着，外头人碰不到，您可以去看看。","truth":"钥匙在我手里。九点一刻我用它从外面反锁了书房，回账房才放进抽屉。抽屉本来就没上锁，那话是哄您的。"},{"id":"t_ledger","q":"“寄港K.M.”是什么？","needs":["clue:c_acct2"],"a":"户头是老爷吩咐开的，小的只管登记盖章。去向账上只写“寄港”，外头怎么传，小的不敢猜。"},{"id":"t_money","q":"你的钱呢？","needs":["clue:c_acct3"],"a":"一辈子的积蓄四千八百元，存在老爷的钱庄，八月底停付，取不出来。儿媳十月生产……这与命案何干？"}],"confronts":[{"clue":"c_study1","breaks":"t_alive","crack":true,"a":"他的手伸向眼镜又缩回。“唱机停了，针在最里头。”半晌才说：“是我放的盘。至于是不是老爷的声音……”"},{"clue":"c_study2","breaks":"t_alive","a":"“僵了……可九点四十一分我亲耳……”他忽然闭嘴，低声说：“人死了多久，是尸体说了算，不是耳朵。”"},{"clue":"c_study3","a":"他听着“稍后再出来同诸位道别”，肩头塌下去。“连清嗓子的位置都没差。老爷刻它时还笑着让我听。”"},{"clue":"c_acct1","breaks":"t_alive","crack":true,"a":"“这是账房的装订线，香也是我的。”他手发抖，“可全公馆的账册都用这种线，说是我，也说得通别人。”"},{"clue":"c_hall1","a":"“是我吩咐林小姐的。可一个账房请大班听老爷念稿，也犯法么？”话说完，嗓子已经哑了。"},{"clue":"c_gar1","breaks":"t_last","a":"他盯着朱印许久。“那是我的章，老爷逼我画的押。我烧了它。可烧一张纸，不是杀人。”这话像辩解，又像认罪。"},{"clue":"c_kit1","breaks":"t_where","a":"“是我擦的手。”他苦笑，“我说是烫着了，厨娘居然还记得。”他低头看着自己的手心，像要找什么没洗掉的东西。"},{"clue":"c_acct4","breaks":"t_key","a":"他看着空凹印，嘴唇动了动。“钥匙我拿了，又放回去了。放回去的时候，手是稳的，我自己都吓一跳。”"},{"clue":"c_acct2","a":"“您翻到他的私账了。”他声音发干，“K.M.是金茂行，四十二万是他转的，账却做在我名下。不签字据，就送我去巡捕房。”"},{"clue":"c_acct3","a":"他眼圈红了。“那是我一辈子。他要走，要我顶缸，还把我的棺材本留在不会再开门的钱庄。”"}],"fallback":"小的不敢乱说，这件东西小的没见过。"},{"id":"bai","name":"白露","role":"顾家姨太太","age":31,"look":{"skin":"fair","hair":"curly","hairColor":"black","glasses":"none","beard":"none","outfit":"qipao","acc":"earrings","mood":"worried"},"bio":"百乐门出身的歌女，顾的姨太太。今晚在客厅给林素秋翻谱、放唱片，还引了一位记者进门。","demeanor":"软糯爱撒娇，自称“阿拉”，紧张就绞手帕、岔开话题。","topics":[{"id":"t_book","q":"手袋里的小册子？","lie":true,"a":"那是家里的菜账呀，买米买菜的，数字密密麻麻，我自己都认不全。侬要看就拿去看好了。","truth":"是白鸽票和马票的号码。我偷偷买，输了好些钱，不敢叫老爷知道。别人当它是密码本，阿拉哪有那么玄。"},{"id":"t_invite","q":"石川怎么进来的？","lie":true,"a":"他是阿拉的表哥呀，在日本做事情，想来见见世面，阿拉就替他写了个名帖，老爷也晓得的。","truth":"他不是表哥，是个记者，来打听顾家与东洋人的往来。我缺钱，收了点好处替他签名。不晓得他会蹲在花园。"},{"id":"t_quarrel","q":"你和老爷吵过架？","a":"二十点二十分，在走廊。我问周二去香港带不带我，他吞吞吐吐。我丢了手帕，躲房里哭了十几分钟才下楼。"},{"id":"t_record","q":"老爷下午做了什么？","needs":["clue:c_study1"],"a":"四点半，老爷拿新买的刻录机在书房玩，刻了“致词一”“致词二”，念完自己先笑。钱先生就站在桌边递账册。"},{"id":"t_ticket","q":"去香港的船票？","needs":["clue:c_hall4"],"a":"周二头等舱，一张老爷，一张阿拉。他说太太留在上海看房子。这话对太太讲没讲，阿拉不晓得。"},{"id":"t_hall","q":"21点后你在做什么？","a":"在客厅换唱片。林小姐九点过后说去透口气，我替她放舞曲，放到她回来，大概九点二十几分。"},{"id":"t_ming","q":"你觉得明远如何？","a":"那孩子心眼好，就是爱躲阁楼。上礼拜我听见楼上“嘀嘀嗒嗒”，像发电报。老爷也听见了，把他叫去训话。"}],"confronts":[{"clue":"c_hall4","breaks":"t_book","a":"她脸一下白了。“侬翻了阿拉的包。”她抢过又松开，“好吧，我赌，输光了不敢说。总比杀人好听吧？”"},{"clue":"c_hall3","breaks":"t_invite","a":"她看着那行“石川谦”，抿着嘴不吭声，半晌才小声说：“是我签的。我真不晓得会出这种事。”"},{"clue":"c_study3","a":"她听见老爷的声音，浑身一抖。“就是这张。下午他笑说，等我走了，你们想我就放这张。”"}],"fallback":"阿拉不晓得呀，侬不要一直盯着阿拉看。"},{"id":"ming","name":"顾明远","role":"顾家养子","age":24,"look":{"skin":"light","hair":"messy","hairColor":"black","glasses":"round","beard":"none","outfit":"shirt","mood":"worried"},"bio":"太太娘家的侄孙，过继给顾家，圣约翰大学学生。说自己整晚都待在三楼房里看书睡觉，直到被喊声惊醒。","demeanor":"年轻气盛，防备心重，爱反问，被逼急了冷笑。","topics":[{"id":"t_role","q":"你和顾家什么关系？","a":"过继来的，吃顾家的饭，念顾家的书。老爷待我有恩，也管得严。我想去的地方，他不肯放我去。"},{"id":"t_night","q":"案发时你在哪？","lie":true,"a":"三楼自己房里睡觉。白天在外头跑了一天，累得很，一觉睡到管家敲门。我又不是杀人的人。","truth":"我没睡。九点零四到九点二十九，我在阁楼发报。我们同学有个小团体，把战事消息发往内地，那刻不能走开。"},{"id":"t_gu","q":"你和顾有矛盾吗？","lie":true,"a":"没有。老爷待我很好，偶尔训几句，那是做父亲的本分，我从来不放在心上，更不会记恨。","truth":"有。上周他发现电台，说再不拆就送我去公董局。我们吵过，我摔了门。但他养了我十年，我不会杀他。"},{"id":"t_lin","q":"你认识林素秋吗？","lie":true,"a":"林小姐？今晚才第一次见。她是白姨太请来弹琴的，我们一句话都没说过，谈不上认识，更没来往。","truth":"她是我同学，也是联络员。她借弹琴进门，是来送新的密码底本。九点零八分上阁楼，十几分钟就走了。"},{"id":"t_radio","q":"电台是怎么回事？","needs":["clue:c_att1"],"a":"一位教授拆旧收音机拼的。我替他们发闸北的情况。日志写着九点零四到二十九，这二十五分钟我一步没离开。"},{"id":"t_smell","q":"之后你下过楼吗？","needs":["ask:ming.t_night"],"a":"发完报我下二楼，约九点三十二分。路过书房，里头没声音，门缝飘出浓檀香。老爷最讨厌香味，我当时还奇怪。"},{"id":"t_key","q":"你有书房钥匙吗？","a":"三把钥匙：老爷、管家、钱先生各一把，我没有。书房是顾家重地，我这个养子进去只能敲门。"},{"id":"t_will","q":"想过遗嘱吗？","a":"我不指望他留什么给我。顾家的财产，太太、白姨太、洋行，谁拿都轮不到我，我也不想要。"}],"confronts":[{"clue":"c_att1","breaks":"t_night","a":"他沉默好一会儿，合上日志。“你们还是翻到了。我认。可这二十五分钟，我寸步没离开。”"},{"clue":"c_att3","breaks":"t_gu","a":"“他写得很重。”明远冷笑，“可你以为我会动手？我宁可把机器沉进苏州河，也不想拿命去换。”"},{"clue":"c_att2","breaks":"t_lin","a":"他脸色变了。“她的名字写在扉页上……好，她是我的联络员。请别把她牵扯进来，她才十九岁。”"}],"fallback":"这个我不清楚，我只管自己的书。"},{"id":"hark","name":"哈考特","role":"英籍洋行大班","age":52,"look":{"skin":"fair","hair":"sidepart","hairColor":"red","glasses":"none","beard":"mustache","outfit":"suit","acc":"tie","mood":"stern"},"bio":"泰和洋行英国大班，顾的上司，明早本要查账。说自己一直在客厅，九点四十分去过书房门口。","demeanor":"英式冷淡，中文夹英语，先反问“你凭什么这样问”。","topics":[{"id":"t_role","q":"你与顾什么关系？","a":"他是我的买办，二十年。他给洋行办事，我给他地位，互不亏欠。今晚来送行，也有几件账目小事。"},{"id":"t_private","q":"散席后见过他？","lie":true,"a":"Well，不曾。晚宴之后我一直在客厅，同银行的几位先生谈话，没有单独见过顾。你们别总想着密谈。","truth":"见过。二十点三十五分，他请我喝威士忌，谈到保证金亏空。他说“账都是钱仲平经手，你去问他”。"},{"id":"t_spy","q":"为何盯着他的账？","lie":true,"needs":["ask:hark.t_private"],"a":"洋行大班查买办的账，天经地义。你若想听出别的意思，那是你的想象。我没有什么谍报任务。","truth":"领事馆托我查他是否把钢材卖给日方。我查到钱流向香港，不是通敌。此事不能公开，我才隐瞒。"},{"id":"t_41","q":"21:41听见什么？","a":"九点三十九分，钱先生请我去书房门口。里面念“诸位，今晚承蒙赏光”，清了嗓子，说“稍后再出来道别”。"},{"id":"t_odd","q":"那声音有异样吗？","needs":["ask:hark.t_41"],"a":"Hmm，现在想来有点怪。语气平，没有停顿，没有重复，连呼吸都很匀。人排练总会改词、骂自己。"},{"id":"t_qian","q":"钱是怎么引你去的？","needs":["ask:hark.t_41","clue:c_hall1"],"a":"他在客厅找到我，很恭敬，说老爷在排练，请大班指教。还特意看表，说“差一两分钟，等等就好”。"},{"id":"t_window","q":"窗外有人吗？","a":"我在客厅窗前抽烟，往花园看过一眼，似乎树荫下有个影子。眼睛不好，也许是花匠。没见谁翻窗。"}],"confronts":[{"clue":"c_kit2","breaks":"t_private","a":"他把领用单看了两遍，哼了一声。“冰桶，两只杯子。是我。”他松了松领带，“好吧，我说实话。”"},{"clue":"c_acct2","breaks":"t_spy","a":"他看着“金茂行”，神情松动。“原来不是汉奸，只是个贼。”他苦笑，“比我们想的好一些，也坏一些。”"},{"clue":"c_hall1","a":"“停琴七分钟。”他皱眉，“我进客厅时琴还在响，走到楼梯口它就停了。我以为是顾要求的。谁写的？”"}],"fallback":"这与我无关。要指控什么，请先拿证据。"},{"id":"shi","name":"石川谦","role":"日籍记者","age":35,"look":{"skin":"light","hair":"sidepart","hairColor":"black","glasses":"rect","beard":"none","outfit":"suit","acc":"tie","mood":"sly"},"bio":"《大陆晨报》驻沪日本记者，凭白露的名帖进了酒会。自称整晚一直在大客厅里与宾客攀谈。","demeanor":"客气过分，常鞠躬，说话绕弯，被追问先道歉再回避。","topics":[{"id":"t_role","q":"为何来参加酒会？","a":"失礼了。我是记者，想报道买办离沪赴港的新闻，也想听听商界怎么看战局。顾先生是体面人物。"},{"id":"t_where","q":"案发时你在哪？","lie":true,"a":"一直在大客厅，与几位先生谈话，也听林小姐弹琴。失礼，酒喝得不少，记不清具体和谁说话。","truth":"我在花园。九点后借口透气，在树荫下蹲了很久，想拍书房窗口。我是日本人，出现在命案现场，谁都会怀疑。"},{"id":"t_cam","q":"你带相机了吗？","lie":true,"a":"没有。记者赴酒会，带笔和耳朵就够了，带相机太失礼。我一向守规矩，请不要误会，更不要怀疑我。","truth":"带了一台小相机，藏在大衣里。偷拍时胶卷盒掉在草丛里。我什么都没拍到，窗帘一直拉着。"},{"id":"t_voice","q":"花园里听到什么？","needs":["ask:shi.t_where"],"a":"九点四十分左右，窗里传出“诸位，今晚承蒙赏光”。声音带沙沙杂音，像唱片底噪。当时离得远，没多想。"},{"id":"t_shadow","q":"看到谁了？","needs":["ask:shi.t_where"],"a":"九点二十分前后，焚烧桶边有个瘦人影，穿灰布长衫，背对我烧东西，烧完用鞋尖拨平灰，匆匆走了。没见脸。"},{"id":"t_window","q":"有人翻窗吗？","a":"九点到九点四十，我一直盯着那扇窗，没人爬上露台，也没人从窗里出来。窗帘一直拉着。"},{"id":"t_bai","q":"怎么认识白露？","a":"朋友引荐。白夫人需要点帮忙，我需要一张名帖，各取所需。我没为难她，也没写不利于她的东西。"}],"confronts":[{"clue":"c_gar3","breaks":"t_cam","a":"他看着胶卷盒，苦笑鞠躬。“失礼了，是我的，“I”是我划的。我只想拿点证据，没想到命案先发生了。”"},{"clue":"c_gar2","breaks":"t_where","a":"他望着“敷岛”烟头叹气。“这牌子租界里肯抽的人不多，我是一个。好吧，我在花园，只是旁观者。”"},{"clue":"c_gar1","a":"他认出了铁桶，眼睛一亮。“就是这里。九点二十分，穿灰长衫的人烧的就是这样的纸，一张张撕着烧。”"}],"fallback":"请原谅，这件事我实在不清楚。"},{"id":"zhou","name":"周福","role":"顾家管家","age":62,"look":{"skin":"tan","hair":"short","hairColor":"white","glasses":"none","beard":"stubble","outfit":"vest","mood":"tired"},"bio":"顾家管家三十年，手里一串钥匙。十点过后用钥匙打开书房门，是公馆里第一个看到尸体的人。","demeanor":"老派絮叨，句句带“老爷”“东家”，一慌就绕回规矩。","topics":[{"id":"t_ice","q":"20:30送了什么？","lie":true,"a":"冰一桶，杯子一只，威士忌一瓶，书房里只有老爷一人。他嘱咐别吵，我放下就出来了，没多待。","truth":"杯子是两只。大班哈考特也在里头，递给我十块钱，叫我别说他来过。我收了钱，就把嘴缝上了。"},{"id":"t_pantry","q":"21点到21:30在哪？","lie":true,"a":"就在茶水间，添酒、收杯子、擦盘子，一步没走开。厨房的人都看见的，东家的规矩我不敢忘。","truth":"我溜去后弄堂福记牌档赌牌九，九点零二出去，九点十四回来，输了八块。怕东家知道，更怕太太知道。"},{"id":"t_back","q":"后楼梯遇到谁？","needs":["clue:c_kit3","ask:zhou.t_pantry"],"a":"九点十六分我从后门回来，刚上后楼梯，撞见钱先生一身灰布长衫从楼上急急下来，搓着手，说烫着了。"},{"id":"t_alibi","q":"牌档有人认得你吗？","needs":["clue:c_kit3"],"a":"福记的伙计认得，我是常客，进门登筹码，出来盖红戳，他们账上有底。丢人，可只能这么说。"},{"id":"t_order","q":"钱先生有吩咐吗？","needs":["ask:zhou.t_back"],"a":"九点半前后，钱先生说“老爷在排练致词，别惊动，十点以后再说”。我就守到十点，才拿钥匙去开门。"},{"id":"t_door","q":"开门时什么情形？","a":"十点过十分，门锁着，锁孔里没钥匙。我开门进去，老爷躺在书桌后，头上全是血。窗虚掩着，窗闩抬着。"},{"id":"t_key","q":"钥匙借出去过吗？","a":"那串钥匙从不离身，睡觉都挂腰上。出事时我这把还在身上。钱先生那把，是东家亲手给的。"},{"id":"t_lin","q":"林小姐离开过吗？","a":"九点后我见她从楼梯下来，神色匆匆，手里拿着本书。白姨太替她放了唱片。我只当年轻人坐不住。"}],"confronts":[{"clue":"c_kit2","breaks":"t_ice","a":"管家的手有点抖。“一桶冰，两只杯子，是我自己写的。”他叹气，“大班给了十块钱，是我糊涂。”"},{"clue":"c_kit3","breaks":"t_pantry","a":"他看着骰盅，脸红到耳根。“被翻出来了。我只出去一刻钟，可就那一刻钟，我撞见了不该撞见的。”"},{"clue":"c_kit1","a":"“毛巾……”他想了想，“我撞见钱先生时，他身上就有这股檀香味。他向来用檀香，我没往心里去。”"}],"fallback":"老头子不懂这些，您问别人吧。"},{"id":"lin","name":"林素秋","role":"女学生·钢琴伴奏","age":19,"look":{"skin":"fair","hair":"bob","hairColor":"black","glasses":"none","beard":"none","outfit":"dress","acc":"bow","mood":"worried"},"bio":"圣玛丽女校学生，经白露介绍来弹琴。说自己整晚坐在琴凳上，只有被请停琴那一次离开。","demeanor":"说话清脆急促，带学生腔，紧张咬嘴唇，爱说“其实”。","topics":[{"id":"t_role","q":"怎么来弹琴的？","a":"白姨太说酒会缺人弹琴，给二十块。其实我家在闸北，炮响后逃到法租界，我需要这笔钱。"},{"id":"t_piano","q":"21点到21:30在哪？","lie":true,"a":"一直坐在琴凳上，没离开过。白姨太只是替我翻谱子，琴一直是我弹的，不信你问在座的客人。","truth":"九点零五分起我离开二十分钟，白姨太替我放唱片。我上阁楼，把新的密码底本交给顾明远，九点二十五回来。"},{"id":"t_ming","q":"认识顾明远吗？","lie":true,"a":"不认识。今晚才第一次听说有这么个人。顾家少爷怎么会和我这样的女学生打交道呢？我们差得远了。","truth":"他是我同学，也是团体负责人。我们靠发报把战事消息送到内地。请不要把他交出去，他是好人。"},{"id":"t_stop","q":"钱先生要你做什么？","needs":["clue:c_hall1"],"a":"九点半前后，钱先生说老爷要排练致词，请我九点三十八分起停琴七分钟，之前换慢板。他还站在琴旁看着表。"},{"id":"t_clock","q":"停琴时看到什么？","needs":["ask:lin.t_stop"],"a":"我一停手，客厅就静了。钱先生马上走到大班身边，两人往楼梯去。回来时大班脸色古怪，他却很平静。"},{"id":"t_bible","q":"《圣经》是你的吗？","needs":["clue:c_att2"],"a":"是我的，我送给明远的。用章节行数做底本，每周换一套新密码，免得被敌人破译，不是为了做礼拜。"},{"id":"t_bai","q":"白姨太人怎样？","a":"她是个可怜人，嘴上爱撒娇，心里很空。替我放唱片一点怨言也没有，还说年轻人有自己的事。"}],"confronts":[{"clue":"c_att1","breaks":"t_piano","a":"她咬着嘴唇，眼圈红了。“日志上有我的名字……是，我九点零八分在阁楼，二十分钟就回来了。别抓明远。”"},{"clue":"c_att2","breaks":"t_ming","a":"她愣愣看着扉页，忽然笑了一下。“我写的字，终究骗不过人。”她低下头，“我认了。”"},{"clue":"c_hall1","a":"“这是钱先生当面跟我说的，纸上没写他。”她盯着铅笔字，“他一直站在琴边看表，比我还紧张。”"}],"fallback":"我不太懂这个，请您问别人吧。"}],"solution":{"culprit":"qian","method":{"q":"凶手怎样制造“九点四十一分他还活着”？","options":["死者早已遇害，门内是预刻唱盘，线香烧线定时","死者当时尚活，凶手在众人听完后从窗口潜入行凶","凶手立在门外，压低嗓子模仿死者口吻念稿","死者仍在屋内，凶手趁人离开后用钥匙开门行凶"],"correct":0},"motive":{"q":"凶手为什么杀人？","options":["死者暗中向日方转卖军需钢材，凶手为阻止他通敌","死者要携情人赴港并改了遗嘱，凶手因遗产落空","死者发现私设电台扬言送官，凶手为保同伴灭口","死者做假账逼凶手画押顶罪，凶手失控下了手"],"correct":3},"keyClues":["c_study1","c_study2","c_acct1","c_acct2","c_hall1","c_gar1"],"truth":["凶手是账房钱仲平。他用留声机和一张刻录盘，把死人的声音放进了所有人的耳朵。","谍战是迷雾：电台属明远与林素秋的救亡团体，石川在花园偷拍，哈考特暗查为领事馆，白露的“密码本”是马票，太太翻抽屉找船票。都与命案无关。","真动机在账里：顾侵吞保证金四十二万转入香港“金茂行”，把亏空做成钱经手、盖钱章的账。二十点五十五分逼钱画押，钱积蓄困在钱庄，一怒用镇纸打死他，约二十一点零五分。","诡计：钱把顾下午刻的“致词一”放上唱机，红线拴制动杆，搭在点燃的线香上，烧断线盘即转。他九点十五分反锁门，抬起窗闩，又烧字据，再请林素秋停琴，带大班来听。","破绽：唱机停在盘尾，焦线与账房同款；尸体早已僵硬；节目单有停琴嘱咐；焚烧桶有带钱印的残纸；抽屉没锁，窗台无痕、花园无脚印。凶手是被逼到墙角的老账房。"]}},{"id":"clanhall","title":"宗祠夜宴","tagline":"冬至祭祖夜，族长倒在供桌旁，满堂人都说酒有毒；可祠门，三十年前就关过一回。","difficulty":5,"cover":"cv_clanhall","tone":"sepia","brief":"水头村邝氏宗祠，冬至祭祖夜。族长邝世昌七十四岁，二十点五十八分在供桌边按住胸口倒下，再没起来。\n长女慧芳说，父亲倒下前低声讲了一句：“酒是苦的。”族人都认定酒里有毒。山洪冲断了桥，警察最快二十三点三十分到。慧芳请来了你。\n你二十一点五十分进门，八个人围着遗体，各怀心事。老规矩，冬至夜祠门不到子时不开。没人能走。","victim":{"name":"邝世昌","desc":"七十四岁，邝氏族长，患冠心病。穿祭服倒在供桌右侧，右手攥着白瓷药盒，嘴唇发绀，21:25确认死亡。","look":{"skin":"light","hair":"short","hairColor":"white","glasses":"round","beard":"none","outfit":"robe","acc":"pocketwatch","mood":"stern"}},"publicFacts":["族长患冠心病，随身带一只白瓷药盒，装舌下含服的急救药。","祭酒由族老邝秉德司酒；酒壶封泥封好，18:10由守祠人麦焕送上供桌。","据慧芳说，族长初献后说过“酒是苦的”。慧珍当场要求封存酒壶和银杯。","新谱重排位次，不少人不满；祖田征收协议（三千八百万）要求明早九点前签字。","三十年前族长发妻病逝，此后族长定下规矩：冬至夜祭礼未毕，祠门不开。","山洪断桥，23:30前没人能来；祠里八个人都在。"],"relations":{"yao":"长子，镇上做建材生意","hui":"次女，中学老师，天天给他送药","bing":"族里辈分最高的族老，今晚司酒","ke":"受聘来修新谱的族谱先生","fang":"长女，远嫁深圳，退休护士长","ruan":"二女婿，入赘二十年，今晚主厨","mai":"守了四十一年祠堂的老看门人","yuan":"长孙，在上海读药学博士"},"links":[{"a":"hui","b":"ruan","text":"夫妻，入赘二十年"},{"a":"hui","b":"fang","text":"亲姐妹，一个在家一个远嫁"},{"a":"yao","b":"yuan","text":"亲生父子，儿子在上海读书"},{"a":"yao","b":"bing","text":"新谱要把族老一支并入耀宗房"}],"deathReport":{"time":"约 20:30–21:30","cause":"冠心病急性发作，心脏骤停","scene":"祭礼初献后，族长在供桌旁按住胸口倒地；长女慧芳取药喂了两次，无效，21:25确认死亡。","loc":"altar","notes":["嘴唇发绀，无外伤","右手紧攥白瓷药盒","舌下有白色残渣"]},"timeline":[{"t":"18:10","text":"麦伯把酒壶送上供桌；族长入更衣间斋戒沐手。"},{"t":"20:40","text":"初献：族长举杯沾唇，酒由族老斟。"},{"t":"20:58","text":"族长倒在供桌旁；慧芳取药喂了两次，无效。"},{"t":"21:25","text":"确认死亡；120告知山路中断。"},{"t":"21:50","text":"你到达追远堂。"}],"budget":{"search":12,"ask":26},"locations":[{"id":"altar","name":"正殿与供桌","scene":"mourning","desc":"追远堂正殿，香烟未散。供桌上牌位成排，遗体盖着红布，神龛后有一扇小木门。","clues":[{"id":"c_altar1","title":"遗体与药盒","text":"右手攥着白瓷药盒，盖内胶布是他的笔迹：“硝酸甘油”。盒里剩十一片白片，压着“润”字。舌下有白渣，味凉。"},{"id":"c_altar2","title":"神龛后的暗格","text":"暗格里有樟木谱匣，旁塞一只棕色玻璃瓶，标签“硝酸甘油片 邝世昌”，五天前开的，近满。瓶身蒙灰，瓶塞有新刮痕。"},{"id":"c_altar3","title":"银杯与酒壶","text":"银杯里还剩大半杯酒，杯底沉着细白粉末，尝过的人说苦。壶底有同样沉淀，壶盖内壁有一圈手指抹痕。"}]},{"id":"robing","name":"东厢更衣间","scene":"guestroom","desc":"正殿东侧的小房间，屏风后是铜盆热水，门口挂着厚布帘。","clues":[{"id":"c_robing1","title":"斋戒须知与托盘","text":"门框须知：“族长沐手斋戒自18:10起，药物置于托盘，18:40著祭服时取回。”红漆托盘上有方形压痕，散着几粒白碎屑。"},{"id":"c_robing2","title":"门边自签单","text":"自签单：18:10 世昌沐手；18:20 慧珍送祭服；18:25 知远，出18:28；18:40 慧珍系腰带；18:43 世昌出。"},{"id":"c_robing3","title":"外套内袋与字纸篓","text":"家常外套内袋缝着一只空布袋，大小正好放下药盒。字纸篓里有半张玻璃纸，印着“清润薄荷含片”。"}]},{"id":"gate","name":"门房与偏厅","scene":"hall","desc":"祠门内侧的门房，墙上挂着钥匙板和登记簿；隔壁偏厅衣架上挂满了族人的外衣。","clues":[{"id":"c_gate1","title":"钥匙簿","text":"钥匙簿：“18:00 偏厅钥匙 借 耀宗”；“19:42 神龛暗格 借 慧珍（放谱匣），20:05 还”。钥匙平时挂麦焕腰间。"},{"id":"c_gate2","title":"来客签到簿","text":"签到簿：知远17:00到；慧芳17:20到，去向“谱局”；吴科长18:00入、19:00出，访耀宗于偏厅。"},{"id":"c_gate3","title":"偏厅衣架上的外衣","text":"族老的棉袍口袋里有一板艾司唑仑1mg，十片装缺了四粒，还有半盒压字的清润薄荷含片。"}]},{"id":"kitchen","name":"祠后厨房","scene":"kitchen","desc":"祠堂后院的大灶间，锅还冒着热气。灶边挂着出品单，墙角码着几只红泥酒坛。","clues":[{"id":"c_kitchen1","title":"厨房出品单","text":"出品单：18:32 麦伯取姜糖；18:50 志刚出，19:10 回；19:20 大少爷借擂钵“捣胃药”，19:30 还，没洗。"},{"id":"c_kitchen2","title":"酒坛与封泥","text":"酒坛封条完好，签着“秉德”。17:40志刚滤酒灌壶，18:00族老封壶，18:10麦伯端走。滤勺和空坛底的酒清亮无沉淀。"},{"id":"c_kitchen3","title":"没洗的擂钵","text":"石擂钵没洗，钵底沾着细白粉末，钵边有红滤嘴烟蒂；垃圾桶里有撕开的艾司唑仑铝箔板。"}]},{"id":"archive","name":"谱局","scene":"library","desc":"西厢改作的修谱局，桌上摊满校样、拓片和线装旧谱。","clues":[{"id":"c_archive1","title":"出诊簿复印件","text":"出诊簿复印件，三十年前冬至夜：“出诊邝宅，哮喘重症；祠门不启，传话‘祭礼未毕’；候至00:30退回。00:50闻已殁。”"},{"id":"c_archive2","title":"旧谱与墓碑拓片","text":"旧谱写“蔡氏，冬至前三日病殁”；夹着的墓碑拓片却刻“冬至夜殁”。两处相差三天。"},{"id":"c_archive3","title":"新谱校样","text":"校样蔡氏已改“冬至夜殁”，族长红笔批“改回。祭祖夜不书殁”。另批“秉德一支并入耀宗房”“赘婿只书赘阮氏”。"}]},{"id":"study","name":"族长书房","scene":"study","desc":"祠堂东院族长的书房，老红木书桌，台历上圈着今天冬至。","clues":[{"id":"c_study1","title":"处方笺与药袋","text":"处方笺：硝酸甘油片，五天前开，“家属代取：阮志刚”。桌上常放药瓶处只剩一圈浅印。台历冬至格写：“药盒随身”。"},{"id":"c_study2","title":"征收协议与公尝章程","text":"《祖田征收协议》补偿三千八百万，乙方签字栏空白，限明日九时。族长毛笔批：“祖田不卖，立公尝，外嫁者不预。”"},{"id":"c_study3","title":"蓝布面日记","text":"日记，三天前：“柯某多事，把旧账翻了出来。珍儿夜里在东厢门口站了很久，我没开口。祠门的规矩是我定的，没有错。”"}]}],"suspects":[{"id":"yao","name":"邝耀宗","role":"长子","age":52,"look":{"skin":"tan","hair":"slick","hairColor":"black","glasses":"none","beard":"none","outfit":"jacket","acc":"badge","mood":"stern"},"bio":"族长长子，镇上建材商，一心要卖祖田。称下午一直在偏厅接待征收办，开祭后站东边第三排。","demeanor":"急躁，爱说“讲实际”，被问到钱就拔高声音。","topics":[{"id":"t_land","q":"祖田征收","a":"三千八百万，明天九点前不签就作废。讲实际点：田荒着，年轻人都走了，卖了人人有份。老头子偏不肯。"},{"id":"t_where","q":"开祭前在哪","lie":true,"a":"我一直在偏厅陪吴科长，他十九点走了我就去殿里站班。哪都没去，更没碰过供桌的东西。","truth":"十九点二十我借擂钵碾了四片药，十九点三十五分倒进酒壶和银杯。只想让他昏沉点签字，没想他死。"},{"id":"t_father","q":"和父亲","a":"他把我当账房，几十年没听过我一句。开祭前我最后劝他一回，他头都没抬。我恨过他，可他是我爸。"},{"id":"t_drug","q":"药哪来的","needs":["ask:yao.t_where"],"a":"族老的艾司唑仑，外衣挂在偏厅，我顺了四片。吃一片够睡一觉，爸只沾了唇，不可能出事。"},{"id":"t_late","q":"倒下时","needs":["ask:yao.t_where"],"a":"我站东边第三排。听见慧芳说“酒是苦的”，我脑子一白：药放多了。可再看爸的脸，是心口疼，不是犯困。"},{"id":"t_ruan","q":"阮志刚","a":"十八点五十几从厨房后门出去，二十来分钟才回，板着脸。入赘的人，今年修谱没他位置，换谁都不痛快。"}],"confronts":[{"clue":"c_kitchen3","breaks":"t_where","a":"他脸红到耳根：“擂钵也翻出来了……行！”一屁股坐下，“铝箔是我丢的，烟头也是我的。”"},{"clue":"c_kitchen1","breaks":"t_where","a":"他盯着“借擂钵”那一行，咬牙：“阿英多嘴。我说捣胃药，是怕她多想。”他抹了把脸，没再争辩。"},{"clue":"c_altar3","a":"“杯底的白粉。”他喉结滚了一下，“就是它。可杯里还剩大半杯，爸只喝了一口，你们自己看。”"},{"clue":"c_altar1","a":"“药盒？”他凑近看，“我没碰过爸的药盒。……这‘润’字是什么？”他皱着眉，自己也糊涂了。"}],"fallback":"这个跟我没关系，讲实际一点，别绕。"},{"id":"hui","name":"邝慧珍","role":"次女 · 祠堂理事","age":47,"look":{"skin":"light","hair":"bun","hairColor":"black","glasses":"round","beard":"none","outfit":"coat","acc":"scarf","mood":"tired"},"bio":"族长次女，中学老师，祠堂理事，管公账和钥匙，天天给父亲送药。倒下时站在殿侧，第一个喊“酒有问题”。","demeanor":"老师口吻，温和有条理，急了会攥手帕。","topics":[{"id":"t_robe","q":"送祭服之后","lie":true,"a":"十八点二十我送祭服进去，放下就出来，回厨房催夜宵了。我连屏风都没绕过去，没碰过他的东西。","truth":"我没马上出来。他在屏风后洗手，我在托盘前站了十来分钟，十八点四十又进去给他系腰带。"},{"id":"t_key","q":"暗格钥匙","lie":true,"a":"十九点四十几借过一回，放柯先生的谱匣，二十点五分就还了。我只放了谱匣，别的没放。","truth":"还放了一只药瓶，是我爸的原药。药盒里倒出来的真药都在里面，我把它塞进了暗格深处。"},{"id":"t_pill","q":"你爸的药盒","needs":["clue:c_altar1"],"lie":true,"a":"盒里一向就是他的救心药，我每周帮他理一次。我只是看着、递着，从没动过里面的东西。","truth":"药是我换的。十八点二十，我把真药全倒出来，换成口袋里的润喉片，大小一样，一片不少。"},{"id":"t_mother","q":"你母亲","lie":true,"a":"我妈是冬至前三天病走的。那年发大水，路断了，村医过不来。我才十七，大人不让我多问。","truth":"她走在冬至夜。村医在祠门外站了一个半钟头，我爸隔门说祭礼未毕，不开。我趴在门缝里，看着妈没了声。"},{"id":"t_know","q":"谁告诉你的","needs":["ask:hui.t_mother"],"a":"柯先生，本月六号，把出诊簿复印件放在我桌上。我看了一夜。我去问爸，他只说：“规矩我定的，没有错。”"},{"id":"t_end","q":"还想说什么","needs":["ask:hui.t_key","ask:hui.t_pill","ask:hui.t_mother"],"a":"他倒下时指着胸口，药就在手边，吃不到嘴里。三十年前我妈指着柜里的吸入药，也是这样。你们带我走吧。"}],"confronts":[{"clue":"c_robing2","breaks":"t_robe","a":"她把单子拿近看，手帕绞成一团。“十八点四十是我写的。”停了停，“我进去过两回，第一回，不止放了件衣服。”"},{"clue":"c_gate1","breaks":"t_key","a":"她看着钥匙簿上自己的名字。“是我借的，不赖。我说我只放了谱匣——”她抬起眼，“这句不全。”"},{"clue":"c_altar2","breaks":"t_key","crack":true,"a":"她盯着棕色小瓶的标签，半晌没出声。“我以为藏得够深。这是我爸的药，瓶是我放进去的。”"},{"clue":"c_altar1","breaks":"t_pill","a":"她看着盒里压字的白片，肩膀塌下来。“这味道我熟，我办公室抽屉里常年有一盒。盒子里的药，是我换的。”"},{"clue":"c_robing1","breaks":"t_pill","a":"“托盘上的碎屑？”她声音发干，指尖停在手帕上，“换的时候掉了一片，我没来得及捡。”"},{"clue":"c_archive1","breaks":"t_mother","a":"她一行行读到“祠门不启”，手背青筋鼓起。“这是我妈最后一晚。我说水冲了路——不是水，是我爸关的那扇门。”"},{"clue":"c_study3","a":"“他还记了我站在门口。”她轻轻笑了一下，“想问他一句，妈那晚，您为什么不开门。他没抬头。”"}],"fallback":"这个……我们换个话题，好吗？我得先定定神。"},{"id":"bing","name":"邝秉德","role":"族老 · 司酒","age":79,"look":{"skin":"light","hair":"bald","hairColor":"white","glasses":"none","beard":"goatee","outfit":"robe","mood":"stern"},"bio":"邝氏辈分最高的族老，今晚的司酒，亲手封壶、斟酒。新谱把他一支并入耀宗房，他一直不服。","demeanor":"文白夹杂，爱咳嗽，称人“后生仔”。","topics":[{"id":"t_wine","q":"碰过酒壶吗","lie":true,"a":"封壶之后，老朽一指未碰。神明未尝，人先尝，是司酒大忌。后生仔，你莫要拿这个冤枉老人。","truth":"碰过。十九点四十我进殿，怕酒冷，揭盖用指头蘸了点试温。不敢认，认了就坏了祖宗规矩。"},{"id":"t_pills","q":"吃安眠药吗","lie":true,"a":"老朽从不吃洋药，睡不着就点沉香。那些片片丸丸吃了伤魂，不吃也罢，是你们后生仔才信这个。","truth":"吃，艾司唑仑，吃了五年。下午数过，原本十粒只剩六粒，我没声张，怕人说我拿去害族长。"},{"id":"t_spu","q":"修谱","a":"一笔把我这一支并去耀宗房，三个儿子的份子钱没了。我当面讲过不服。可毒酒的事不是我。"},{"id":"t_rule","q":"关祠门","a":"世昌定的规矩，三十年了：冬至夜祭礼未毕，门不开，外人不得入。族里人都晓得，没人敢破。"},{"id":"t_old","q":"三十年前","needs":["ask:bing.t_rule","clue:c_archive1"],"a":"蔡氏发病，村医在门外候了个多钟头，世昌不肯开门。人没了，对外说冬至前病殁，是我提的。"},{"id":"t_hui","q":"慧珍","needs":["ask:bing.t_old"],"a":"那晚她十七岁，趴在门缝哭了一夜，再没提过。这孩子心思深。近一年天天给她爸拿药……老朽不敢往下想。"}],"confronts":[{"clue":"c_altar3","breaks":"t_wine","a":"他盯着壶盖内壁的指痕，咳了很久：“……是老朽的手。”按着胸口，“这罪我担。可酒里的药，不是我下的！”"},{"clue":"c_gate3","breaks":"t_pills","a":"他看着缺了四粒的药，嘴唇哆嗦：“被你们翻出来了……我是吃，可那四粒不是我拿的。”"},{"clue":"c_archive3","a":"“并入耀宗房。”他苦笑，“这一笔，老朽记了三个月。可我要真想杀人，何必等到今晚。”"},{"clue":"c_archive2","a":"他不看拓片，低头：“旧谱上那个日子，是老朽提的笔。”声音小下去，“碑上刻的才是真的。”"}],"fallback":"后生仔，老朽记不清了，问点别的吧。"},{"id":"ke","name":"柯望舒","role":"族谱先生","age":68,"look":{"skin":"light","hair":"sidepart","hairColor":"grey","glasses":"rect","beard":"none","outfit":"vest","acc":"pocketwatch","mood":"worried"},"bio":"县志办退休编辑，受聘来修新谱，已在祠里住了三个月，口头禅是“只认史料，不认人情”。","demeanor":"书卷气，爱说“据校”“按例”，被追问会推眼镜。","topics":[{"id":"t_job","q":"修谱","a":"世系、生卒、婚嫁，一个字都不能错。我修了四十年志书，最怕有人要我“顺一顺”，核了七遍。"},{"id":"t_where","q":"十八到十九点","lie":true,"a":"我一个人在谱局核校样，半步没离开过。这差事一个字错了就是百年的错，连晚饭都是后来吃的。","truth":"慧芳十七点二十分一到就来谱局，我们一起看了一个钟头出诊簿复印件。我瞒着，是怕差事不保。"},{"id":"t_private","q":"私下往来","lie":true,"a":"没有。谱是公器，各房的意见我只在族议上听，私下一个字不递，更不替哪一房说话，这是本分。","truth":"有。本月六号我把出诊簿复印件悄悄放在慧珍桌上，今天又给了慧芳。我有私心，这事不能烂在我手里。"},{"id":"t_date","q":"蔡氏殁期","needs":["ask:ke.t_private"],"a":"旧谱写冬至前三日，墓碑却是冬至夜。我查出诊簿才知，村医那晚到了祠门口没进去。我改了，族长批“改回”。"},{"id":"t_vic","q":"族长态度","a":"起初答应，后来越改越窄：外嫁女删、秉德支并走、蔡氏殁日改回。我说谱是信史，他说谱是规矩。"},{"id":"t_lozenge","q":"你的嗓子","a":"读校样嗓子冒烟，一直含清润薄荷含片，口袋里就有，你拿去看。修志的、教书的都爱这个。"}],"confronts":[{"clue":"c_gate2","breaks":"t_where","a":"他推推眼镜，翻开签到簿又合上：“慧芳去向写的是‘谱局’……是我们。读书人说谎，破绽百出。”"},{"clue":"c_archive1","breaks":"t_private","a":"他看着复印件，叹口气：“好吧，这份我先后给了两个人。我不是要谁杀人，只是不想它烂在抽屉里。”"},{"clue":"c_archive3","a":"“族长的红笔。”他的指腹在“改回”两个字上停了很久，“祭祖夜不书殁——他一辈子都在改日期。”"}],"fallback":"这个……史料上没有记载，恕我无法回答。"},{"id":"fang","name":"邝慧芳","role":"长女 · 外嫁","age":54,"look":{"skin":"light","hair":"bob","hairColor":"auburn","glasses":"none","beard":"none","outfit":"turtleneck","acc":"earrings","mood":"sad"},"bio":"族长长女，远嫁深圳，退休护士长。新谱把外嫁女删出派下，她是第一个被删的。是她请你来的。","demeanor":"语速快，带粤语“咁”“唔该”，哭着也讲条理。","topics":[{"id":"t_arrive","q":"几点到的","lie":true,"a":"十七点二十到，进门就去厢房歇脚，到开祭没见过什么人。坐了一天车腰都断了，唔该别问这么细。","truth":"我一到就去谱局，跟柯先生看了一个钟头出诊簿复印件，十九点才出来。怕人当我是寻仇的。"},{"id":"t_quarrel","q":"和父亲争执","needs":["ask:fang.t_arrive"],"a":"二十点零五分，屏风后面。我问他当年村医在门外，为什么不开门？他说祭礼大过天，就这一句。我问了三遍。"},{"id":"t_pill","q":"喂药","needs":["ask:fang.t_bitter"],"a":"我喂的，一分钟两片。他皱着眉说：“怎么不麻舌。”我以为他是慌了。做了三十年护士，竟没想到。"},{"id":"t_bitter","q":"酒苦","a":"初献后他侧过头小声说：“酒是苦的。”我站他右手边。当时只觉得他脸色发灰，没多想。"},{"id":"t_mother","q":"母亲","needs":["ask:fang.t_arrive"],"a":"她走那年我二十四岁，在广州。爸说她冬至前病的，我信了三十年。看了出诊簿才知，她是被耽误在祠门外。"},{"id":"t_hui","q":"慧珍","needs":["ask:fang.t_mother"],"a":"珍珍比我早知道。上个月她电话里只讲：“姐，冬至你回来。”她是不是想让我做个见证？我不敢乱讲。"}],"confronts":[{"clue":"c_gate2","breaks":"t_arrive","a":"她看着“谱局”两个字，叹气：“咁都被你们看到了。是，我一到就找柯先生。怕大家当我是寻仇的。”"},{"clue":"c_altar1","a":"她盯着压“润”字的白片，脸慢慢变白：“我喂的时候没看，直接倒的。做了三十年护士，竟然没看。”"},{"clue":"c_robing2","a":"她一行行看过去，没有马上说话。“那会儿我在谱局，这上头没有我。”又低声补一句，“……名字倒认得几个。”"}],"fallback":"唔该，这个我真的不清楚。"},{"id":"ruan","name":"阮志刚","role":"赘婿 · 厨师","age":48,"look":{"skin":"tan","hair":"cap","hairColor":"black","glasses":"none","beard":"stubble","outfit":"apron","mood":"tired"},"bio":"慧珍的丈夫，二十年前入赘邝家，开小酒楼，今晚主厨。新谱只书“赘阮氏”，不入派下。","demeanor":"粗直，话少，爱说“我一个煮饭的”，被戳到会闷头擦手。","topics":[{"id":"t_kitchen","q":"一直在灶上","lie":true,"a":"从十七点半到开祭，我没离开过灶台一步。十几口锅，我走了菜就糊了。你可以问任何人。","truth":"十八点五十到十九点十分我出去了。柯先生说赘婿不入谱，只书“赘阮氏”。我受不了，去后巷蹲着抽了三根烟。"},{"id":"t_meds","q":"取药","a":"五天前我去县医院取的药，处方是老爷子自己开的。取回交给他，他说自己分装，不用我管。"},{"id":"t_wine","q":"灌酒","a":"十七点四十开坛，滤一遍灌壶，酒清得能照人。十八点族老来封壶口，十八点十分麦伯端走。我没碰过别的。"},{"id":"t_yao","q":"大少爷","needs":["clue:c_kitchen3"],"a":"十九点二十他进来借擂钵，说捣胃药，我在收尾没多问。用完放回灶边，没洗。他脸色不对，我现在才想起来。"},{"id":"t_book","q":"入谱","a":"岳父说赘婿是半个儿，现在这半个儿被写成“赘阮氏”，孩子的姓都排在母亲后面。我不怨慧珍，她比我还难受。"},{"id":"t_wife","q":"慧珍当晚","needs":["ask:ruan.t_kitchen","clue:c_robing2"],"a":"十八点四十几，她回厨房喝热水，手一直抖。她说祭服腰带系得太紧。那么大的人，系个腰带怎么会抖。"}],"confronts":[{"clue":"c_kitchen1","breaks":"t_kitchen","a":"他闷头擦着手：“阿英记得真细。……是，我出去了。不是躲懒，是怕忍不住在灶台前砸锅。”"},{"clue":"c_altar2","a":"他盯着棕色小瓶的标签：“这就是我取回来的那一瓶。……它怎么会在神龛后面？”他一脸不解。"},{"clue":"c_archive3","a":"他看到“赘阮氏”三个字，把抹布攥成一团：“好看，真好看。我在这家煮了二十年饭，就换来这三个字。”"}],"fallback":"这个我不懂，我一个煮饭的。"},{"id":"mai","name":"麦焕","role":"守祠人","age":71,"look":{"skin":"brown","hair":"short","hairColor":"white","glasses":"none","beard":"stubble","outfit":"jacket","mood":"tired"},"bio":"守祠四十一年的老人，腰间一串钥匙。当晚看门、送酒壶，自称一步没离过更衣间的门帘。","demeanor":"慢吞吞，爱讲古，口头语“咯”，被问不想答的事就叹气。","topics":[{"id":"t_post","q":"一直守着吗","lie":true,"a":"帘子外头我一步没离，谁进谁出，我记得清清楚楚咯。族长沐手时，除了送祭服的没人敢靠近。","truth":"十八点半我去厨房取姜糖，十八点五十五才回，还喝了一口酒。帘子外空了二十几分钟。怕东家怪罪，没敢讲。"},{"id":"t_key","q":"暗格钥匙","lie":true,"a":"那把铜钥匙一直挂在我腰上，从来没离过身咯。四十几年了，除了我，没有第二个人碰过它。","truth":"借过。十九点四十二分，理事说要放柯先生的谱匣，我不敢拒。二十点零五分她还了。我没往心里去。"},{"id":"t_who","q":"谁进谁出","needs":["ask:mai.t_post"],"a":"十八点十分老爷进去沐手；二十分理事送祭服；二十五分知远探头，几分钟就出来；半点我走时，理事还没出来。"},{"id":"t_old","q":"三十年前","a":"我守的门。村医提药箱在门口等，我去通报，老爷说祭礼未毕。后来太太没了，我这几十年夜里都睡不踏实。"},{"id":"t_rule","q":"祠门规矩","a":"老爷定的：冬至夜祭礼未毕，门不开。三十年没破过一回。今晚桥断了，更没人能出去咯。"},{"id":"t_drink","q":"酒气","a":"厨房里喝了一口，只一口。我这把年纪，一年就冬至这天敢喝一口。你们莫要拿这个说我。"}],"confronts":[{"clue":"c_kitchen1","breaks":"t_post","a":"他叹口气看着天花板：“阿英写得清楚咯。十八点三十二我去签的姜糖。……是我离岗了，唔使瞒你。”"},{"clue":"c_gate1","breaks":"t_key","a":"他盯着钥匙簿自己的字迹，半晌：“咁……我写的。理事借的，十九点四十二。我说一直在我腰上，是我老糊涂。”"},{"clue":"c_altar2","a":"他看着棕色小瓶，嘴唇动了动：“理事借钥匙，就放了一个谱匣……怎么多出个瓶子？”他自己先愣住了。"}],"fallback":"咁……我老了，记不清咯。"},{"id":"yuan","name":"邝知远","role":"孙辈 · 药学博士生","age":26,"look":{"skin":"fair","hair":"messy","hairColor":"black","glasses":"rect","beard":"none","outfit":"hoodie","mood":"smirk"},"bio":"耀宗的独子，上海药学博士生，称十九点二十才赶到。下午为学费与爷爷争吵，吵完躲在后院。","demeanor":"年轻，爱说“说实话”“离谱”，心虚时刷手机。","topics":[{"id":"t_arrive","q":"几点到的","lie":true,"a":"十九点二十才到，高速堵了俩小时。说实话我连爷爷的面都没怎么见上，更别提更衣间那边了。","truth":"十七点就到了。下午我找爷爷要二十万学费，被怼回来，躲在后院生闷气。说晚到，是怕你们觉得我有动机。"},{"id":"t_money","q":"和爷爷吵","a":"下午在殿里吵的：我想借二十万读书，他说你爸有钱找你爸。说实话我挺想说句难听的，但转身走了。"},{"id":"t_pharm","q":"学药","a":"药学博士在读。爷爷倒下时我想冲上去，被人群挡住。后来看他攥着的药盒，我心里咯噔了一下，没敢乱说。"},{"id":"t_room","q":"更衣间","needs":["ask:yuan.t_arrive"],"a":"十八点二十五，我想再求爷爷一次，探头进去，屏风后水声哗哗。里面还有个人，我三分钟就出来了。"},{"id":"t_aunt","q":"里面是谁","needs":["ask:yuan.t_room","clue:c_robing2"],"a":"慧珍姑姑。她背对门站在放爷爷东西的托盘前，手里捏着个小盒子。她回头说：“别碰爷爷的东西，出去。”"},{"id":"t_box","q":"那个小盒子","needs":["ask:yuan.t_aunt","clue:c_altar1"],"a":"巴掌大，铁皮的，圆的。她办公桌上也有一个差不多的。说实话我不确定是不是同一种，你别当真。"}],"confronts":[{"clue":"c_gate2","breaks":"t_arrive","a":"他挠挠头，笑得尴尬：“签到簿有这个……行吧，十七点就到了。不是怕被抓，是怕被怀疑。”"},{"clue":"c_robing2","a":"“自签单上有我，十八点二十五到二十八。”他点头，“这个我认，是我签的，我就进去了三分钟。”"},{"clue":"c_altar1","a":"他凑近看了很久，喉咙动了动：“……我们实验室的片剂，一般不压这种字。”又摇头，“算了，我不乱讲。”"}],"fallback":"说实话，这个我真不太清楚。"}],"solution":{"culprit":"hui","method":{"q":"凶手是怎么做到的？","options":["司酒人在祭酒里下了镇静药，老人沾唇后药性发作，心脏病猝死","有人为逼签字把安眠药混进酒壶，剂量过大，老人心脏骤停","趁沐手药盒离身，把急救药换成外形相同的含片，真药另藏","发病后喂药的人塞进了异物，老人被呛住窒息而亡"],"correct":2},"motive":{"q":"为什么杀人？","options":["被删出族谱，田产又被拒绝，多年委屈一并爆发","经手公账有亏空，被查出后抢先下手封口","三十年前亲人因拒开祠门而死，事后还被改了日期","遗嘱把祖屋公尝都留给别人，尽孝多年却什么也分不到"],"correct":2},"keyClues":["c_altar1","c_altar2","c_robing1","c_robing2","c_gate1","c_archive1"],"truth":["凶手是次女邝慧珍。族长不是死于酒里的毒，而是死于药不对：慧芳喂他的两片，是压“润”字的薄荷含片。","表面看是族老下毒：酒里有镇静药，他揭过盖，药袋缺四粒。其实下药的是耀宗，为逼父亲签字；族长只沾唇，不致命。","真死因在药盒。盒里是压“润”字的薄荷片，盖内胶布却写“硝酸甘油”；慧芳又听他说“怎么不麻舌”。药被换了。","换药在斋戒窗口：药盒放在更衣间托盘，只有慧珍两度入内。真药藏进暗格，钥匙簿记着她19:42借钥匙。","动机：三十年前冬至夜，慧珍的母亲哮喘发作，族长以“祭礼未毕”拒开祠门，母亲没熬过去，殁期还被改。她要他尝尝药在手边却吃不到的滋味。"]}},{"id":"deepstation","title":"深潜站","tagline":"海底四十一米，通讯断了十一天，科学家死在气密舱。记录都指向一个人，却干净得过分。","difficulty":5,"cover":"cv_deepstation","tone":"cold","brief":"“渊一号”是坐在四十一米海底的饱和居住站，十一天前通讯中断。按规程，失联满十天，水面会放下检查钟。\n你就是被检查钟送下来的独立调查员。清晨七点五十，首席科学家屠鹤年已倒在气密舱里，没有外伤。控制器记录写着：凌晨有人用站长的主钥匙向舱里灌了氦气。站长否认。\n检查钟只能停留九个小时。你有这九小时，和八个都有话没说的人。","victim":{"name":"屠鹤年","desc":"六十三岁的首席科学家，研究热液生物三十年。倒在气密舱采样台边，唇和指甲发紫，无外伤，疑为缺氧窒息。","look":{"skin":"light","hair":"sidepart","hairColor":"white","glasses":"round","beard":"goatee","outfit":"labcoat","mood":"neutral"}},"publicFacts":["渊一号水深41米，舱内约5.1个大气压，呼吸氦氧混合气。氧只占约8%，但氧分压约0.41 bar，属正常。","十一天前通讯光缆中断。通讯工程师判断是渔船拖网挂断。","屠鹤年每晚在气密舱采样，采样时内侧电动锁止，外人进不去。","气密舱可“惰化冲洗”，注入氦气置换空气，须站长主钥匙授权，且氧低警报自动屏蔽。","站长称自己整晚在舱里睡觉。主钥匙放在控制室钥匙盒，站长和三名值班人员知道密码。"],"relations":{"yue":"站里的站长，和死者共事三十年","jiang":"站里的首席潜水员，负责出水作业","zhuo":"合作多年的地质学家，常和他吵架","shao":"管通讯和授时的工程师，一年前调来","lan":"站医，管全站人的健康","he":"站里的厨师，每晚给他送热茶","shen":"他带的博士后，负责整理样本数据","gu":"赞助方派来的代表，监督项目和评估书"},"links":[{"a":"yue","b":"gu","text":"为安全评估书打交道的站长与赞助方"},{"a":"lan","b":"zhuo","text":"站医和病人，昨夜刚给他治耳朵"},{"a":"yue","b":"jiang","text":"站长管着潜水员，上下级"}],"deathReport":{"time":"约 23:00–03:00","cause":"缺氧窒息，疑吸入无氧气体","scene":"06:40，站长岳峥与医生蓝秋荷解锁气密舱，发现屠鹤年侧倒在采样台边。","loc":"lock","notes":["唇和指甲发紫，无外伤","手里攥着采样管，保温壶里的茶已凉","舱内加热，尸体降温很慢，难定精确时间"]},"timeline":[{"t":"00:02","text":"气密舱控制器：转入采样模式，内侧锁止，卡号屠鹤年。"},{"t":"02:18","text":"控制器：惰化冲洗启动22分钟，来源控制室终端，授权站长主钥匙。"},{"t":"02:40","text":"控制器：冲洗停止，回补通风。"},{"t":"06:40","text":"站长与医生解锁气密舱，发现屠鹤年已死。"},{"t":"07:50","text":"检查钟抵达，你进入居住区。"}],"budget":{"search":14,"ask":28},"locations":[{"id":"lock","name":"气密舱","scene":"engine","desc":"居住区尽头的圆形过渡舱，有采样台、样品冷柜和一台自带电池的采样仪。舱内空气已恢复正常。","clues":[{"id":"c_lock1","title":"采样仪纸带","text":"采样仪自带电池，独立走时。纸带：00:40 氧分压0.41；01:00 0.00；01:20 0.09；02:00起0.41。"},{"id":"c_lock2","title":"控制器事件记录","text":"02:01 湿区舱口开；02:18 冲洗启动，授权主钥匙·站长；02:40 停止；02:56 湿区舱口开。"},{"id":"c_lock3","title":"采样台与遗体","text":"屠鹤年侧倒在采样台边，手里攥着采样管。保温壶里的茶已凉。最后一张标签写着“00:40 14号”。"},{"id":"c_lock4","title":"冷柜里的米酒","text":"冷柜最下层抽屉裹着三瓶米酒，一瓶剩半。旧毛巾角上用圆珠笔写着“贺”字。"}]},{"id":"ctrl","name":"控制室","scene":"cabin","desc":"挤满屏幕的小舱，墙边是玻璃门钥匙盒。事发后站长封了这里。","clues":[{"id":"c_ctrl1","title":"钥匙盒与登记","text":"钥匙盒有四位密码锁，内挂主钥匙。登记本最后一行：“22:05 岳 取；22:40 岳 还”。"},{"id":"c_ctrl2","title":"控制器审计记录","text":"审计页：“手动校时 21:47:12 调整为 23:17:12，账户ADM，终端T1（通讯机房）”。上一行：“外部对时丢失”。"},{"id":"c_ctrl3","title":"惰化冲洗面板","text":"冲洗面板有钥匙开关和定时旋钮，停在“22”。座椅调得很低，脚踏板推到最前。"}]},{"id":"comm","name":"通讯机房","scene":"study","desc":"机架成排，墙上贴满线路标签。邵远的工作台上有一台打开的终端T1。","clues":[{"id":"c_comm1","title":"光缆断点记录","text":"反射仪纸条：“断点距机架 7.2 m”，十一天前。墙上邵远的报告写：“光缆约2.1公里处断裂，疑拖网所致”。"},{"id":"c_comm2","title":"授时服务器与账户表","text":"授时服务器外部参考熄灭，镜像上传全部超时。账户表：“ADM 邵远；OP 岳峥、蓝秋荷、江野”。"},{"id":"c_comm3","title":"旧录音与照片","text":"手抄通话：“请求上浮——再留五分钟，屠老师说的。”夹着邵远与短发女子的合影，背面写“岚”。"}]},{"id":"lab","name":"样本实验室","scene":"lab","desc":"摆满冷藏柜和显微镜的实验室，只有屠鹤年的位置还摊着东西。","clues":[{"id":"c_lab1","title":"屠鹤年的笔记","text":"笔记：“回岸后说明宁岚事件：我不知情，日志是岳峥改的。”页边小字：“那段录音，应当已经没有了吧？”"},{"id":"c_lab2","title":"样本出库表","text":"三行“已出库”无人签收，对应热液晶体，旁有价格数字。卓岩便条：“篮子放外架第三格，老规矩。”"},{"id":"c_lab3","title":"沈小棠的邮件草稿","text":"未发出的邮件草稿，指屠鹤年署名的两组数据不实。保存时间00:52、01:30，与餐厅挂钟一致。"},{"id":"c_lab4","title":"屠鹤年的便签","text":"便签：“蓝医生的高压医学资质去年9月到期，回岸后必须向医务委员会报告。”"}]},{"id":"quarters","name":"居住舱区","scene":"guestroom","desc":"窄走廊两侧是各人的舱室和医务室，门牌都是手写的。","clues":[{"id":"c_qua1","title":"江野的潜水电脑表","text":"潜水电脑表：“昨夜入水00:31，出水01:26，最大深度46 m”。时间与餐厅挂钟一致，表带还湿着。"},{"id":"c_qua2","title":"站长的航海日志","text":"三年前6月14日那页被撕掉重抄：“宁岚自行超时下潜。”页缝夹着半张旧页，残一行：“延长滞底，屠要求。”"},{"id":"c_qua3","title":"谷慎舱里的酒杯","text":"谷慎舱桌上两只酒杯，各剩一点威士忌，旁边是岳峥签了首字母修改的《安全评估书补充说明》。"},{"id":"c_qua4","title":"蓝医生的柜子","text":"柜里有资质到期通知，日期去年9月。接诊登记：“卓岩，外耳炎，00:35开始，01:15结束”。"}]},{"id":"mess","name":"餐厅与厨房","scene":"kitchen","desc":"站里唯一能聚在一起的地方：长桌、咖啡机，墙上挂着一只圆挂钟。","clues":[{"id":"c_mess1","title":"挂钟与对表本","text":"挂钟旁贴着“居住区标准钟，每晚22:00站长对表”。对表本末行：“昨22:00 岳”。挂钟走时很准。"},{"id":"c_mess2","title":"牌局记分纸","text":"记分纸写“21:00开局，22:00散”，参赛者岳、谷、卓、蓝四人，旁有四只咖啡杯。"},{"id":"c_mess3","title":"空了的料酒瓶","text":"料酒瓶几乎见底，标签写着“补”，无补货记录。垃圾桶里有个绣着半个“贺”字的毛巾角线头。"}]}],"suspects":[{"id":"yue","name":"岳峥","role":"站长","age":55,"look":{"skin":"tan","hair":"short","hairColor":"grey","glasses":"none","beard":"stubble","outfit":"uniform","acc":"badge","mood":"stern"},"bio":"渊一号站长，退役潜艇军官，身高一米八五，掌管主钥匙。他说自己昨夜整晚都在舱内睡觉。","demeanor":"短句，军人腔，爱说“按规程”。","topics":[{"id":"t_role","q":"你在站里管什么？","a":"气、电、人、规程，都归我。主钥匙在我手里，要紧的操作我签字。出了人命，我第一个担。"},{"id":"t_sleep","q":"昨晚你在哪？","lie":true,"a":"22:40还完钥匙就回舱睡了，一觉到五点五十。舱里就我一个人，没人能证明，这我认。","truth":"我没睡。01:20到02:50我在谷慎舱里，改评估书的措辞。不光彩，所以瞒了。但我没碰过冲洗。"},{"id":"t_key","q":"主钥匙谁能拿到？","a":"钥匙盒四位密码，我、邵远、江野、蓝医生知道。我22:05取、22:40还，例行夜检，登记本上有。"},{"id":"t_victim","q":"你和屠鹤年的关系？","a":"三十年的老同事，也是对头。昨天晚饭前还拍了桌子。可我要灭他的口，用挂在盒里的钥匙？那是自己套绞索。"},{"id":"t_ning","q":"宁岚的事","lie":true,"a":"宁岚超时下潜，两次警告都不上浮，后来是减压病，没救回来。日志这么写，委员会也这么结案。别翻了。","truth":"日志是我改的。屠鹤年下令“再留五分钟”，事后求我，说否则资格作废。我撕页重抄，改成“自行超时”。"},{"id":"t_gu","q":"你和谷慎谈了什么？","needs":["clue:c_qua3"],"a":"他是赞助方的人，想把评估书里的“管理缺陷”改成“已整改”。我松了口。散的时候，挂钟差十分钟三点。"},{"id":"t_clock","q":"控制器的钟准不准？","needs":["clue:c_ctrl2"],"a":"我对的是餐厅挂钟，每晚22:00。控制器的钟归邵远管，管理员账户我碰不了。谁动的我不知道，不是我。"}],"confronts":[{"clue":"c_qua3","breaks":"t_sleep","a":"他盯着酒杯，沉默很久：“好，01:20到02:50我都在他这儿。这事见光会被撤职，所以撒了谎。”"},{"clue":"c_qua2","breaks":"t_ning","a":"他摩挲着那页新纸：“重抄的。屠要我改，我就改了。这三年我每晚都后悔。但这跟他的死是两回事。”"},{"clue":"c_lock2","a":"他盯着“授权主钥匙·站长”：“钥匙是我的，机器写的我没法说它错。要定我的罪，先问我那个钟点在哪。”"},{"clue":"c_ctrl2","a":"“21:47？那是牌局，我手里拿着一把烂牌。管理员账户不归我管，我碰都碰不了，这行字跟我没关系。”"},{"clue":"c_ctrl3","a":"他低头看脚踏板，再看自己的膝盖：“我一米八五，坐这个腿塞不进台子底下。座椅不是我调的。”"}],"fallback":"报告，这个我不清楚。你换个问题。"},{"id":"jiang","name":"江野","role":"潜水员","age":33,"look":{"skin":"brown","hair":"cap","hairColor":"black","glasses":"none","beard":"stubble","outfit":"jacket","mood":"neutral"},"bio":"首席潜水员，负责出水作业，三年前宁岚遇难时是她的潜伴。他说自己昨夜一直在舱里睡觉。","demeanor":"惜字如金，爱说“嗯”“不知道”，提到宁岚会移开视线。","topics":[{"id":"t_role","q":"你负责什么？","a":"出水、检查外架、修设备。下去的人归我管，上来的人也归我数一遍。站里就这么点事，没别的。"},{"id":"t_dive","q":"昨夜你下水了吗？","lie":true,"a":"没有。夜里不下水，规程不许的。我昨晚一直在舱里睡觉，一觉睡到天亮，什么也没听见。","truth":"下了。00:31入水，01:26出水。卓岩托我取回外架第三格的样本篮，给两千块。违规，所以我不敢认。"},{"id":"t_panel","q":"下水前看到什么？","needs":["clue:c_qua1"],"a":"湿区舱口旁面板上有个小钟，显示02:00，可我腕上的表才00:31。我当它坏了，没往心里去。"},{"id":"t_box","q":"湿区那个接线盒","needs":["clue:c_qua1","clue:c_comm1"],"a":"光缆接线盒在湿区，盖上的密封条被割过，切口很齐。我当时以为是邵远在修线路，没多问。"},{"id":"t_ning","q":"宁岚的事","a":"我是她的潜伴。通话里太吵，我只听见她说氧耗得快，没听清谁让她留下。她不是会自己超时的人。"},{"id":"t_hatch","q":"湿区舱口的记录","needs":["clue:c_lock2","clue:c_qua1"],"a":"两点那几行？我01:26出水就回舱躺下了。后面舱口怎么又开又关，我不知道，也看不明白。"},{"id":"t_key","q":"你知道钥匙盒密码吗？","a":"知道。轮到我值班时可以开盒，但我从没动过主钥匙。那东西是站长的，我碰它干什么，没理由。"}],"confronts":[{"clue":"c_qua1","breaks":"t_dive","a":"他看着那行记录，沉默片刻：“好，我下过水。篮子的事你们要报就报。冲洗那会儿，我在海里。”"},{"clue":"c_lock2","a":"他盯着“湿区舱口开启”：“……不是我。我什么时候下的水，你们总该查得到，不用我自己说。”"},{"clue":"c_comm1","a":"“7.2米？”他重复了一遍，“那是在站里，不可能是拖网。”他压低声音，“有人在自家剪的缆。”"},{"clue":"c_qua2","a":"他看到“延长滞底，屠要求”几个字，指节一下攥白了：“原来是真话。我在钟里没听清的那一句。”"}],"fallback":"嗯，不知道。你问别人。"},{"id":"zhuo","name":"卓岩","role":"地质学家","age":47,"look":{"skin":"light","hair":"messy","hairColor":"brown","glasses":"round","beard":"full","outfit":"vest","mood":"smirk"},"bio":"地质学家，研究热液硫化物，与屠鹤年合作多年却常吵架。他称昨夜打完牌就去了医务室。","demeanor":"话多爱打比方，常拿岩石形容人，谈到钱就语速加快。","topics":[{"id":"t_role","q":"你研究什么？","a":"热液烟囱，就是海底冒黑烟的硫化物柱子。我敲石头，屠老敲虫子，各吃各的饭。石头比人老实。"},{"id":"t_sample","q":"样本有私下出库吗？","lie":true,"a":"怎么可能？每一块都登记在册，我靠这个吃饭。你拿放大镜找，也找不出一粒私自出库的沙子。","truth":"有。三块烟囱晶体，我卖给一个藏家。海底的东西，回岸后没人会想起。我穷怕了，才动了心。"},{"id":"t_ear","q":"昨夜你在哪？","a":"打完牌耳朵发炎，饱和潜水员的老毛病。00:35到01:15蓝医生给我上药，登记本上有。"},{"id":"t_basket","q":"外架那只篮子","needs":["clue:c_lab2"],"a":"外架第三格，我托江野去取的，他夜里去，我白天等着。规矩上不许，可谁会管一只篮子。"},{"id":"t_victim","q":"你和屠鹤年的关系？","a":"他是首席，我是跟班。论文我排第二，第三作者是石头。吵得多，但没到要杀人。他死了我反倒睡不着。"},{"id":"t_shao","q":"邵远这个人怎样？","a":"安静得像块玄武岩，从不上牌桌。他脖子上挂着一枚戒指，我问过，他说“她用过”，我就没再问。"}],"confronts":[{"clue":"c_lab2","breaks":"t_sample","a":"他嘴角抽了抽：“你们动作倒快。好，晶体是我卖的，不抵赖了。但这跟屠老的死没关系，我发誓。”"},{"clue":"c_qua4","a":"“就是这个登记。00:35到01:15，蓝医生拿着棉签，我耳朵里全是药水味。我可不会分身。”"},{"clue":"c_mess2","a":"“牌我打了，输了二十块。”他笑了一声，“岳站长手气差。22:00散，邵远没来，说是去查线路。”"},{"clue":"c_lock3","a":"他看着凉透的茶壶，声音哑了：“屠老最爱喝这壶茶。我跟他吵了一辈子，这回没话好吵了。”"}],"fallback":"这个嘛，石头里没写。你问点别的。"},{"id":"shao","name":"邵远","role":"通讯工程师","age":38,"look":{"skin":"fair","hair":"sidepart","hairColor":"black","glasses":"rect","beard":"none","outfit":"shirt","acc":"headset","mood":"tired"},"bio":"一年前调来的通讯工程师，个子不高，管通讯、授时和门禁。称事发时在机房陪着沈小棠。","demeanor":"语速平稳，爱用技术词，谈私事会停顿。","topics":[{"id":"t_role","q":"你具体管什么？","a":"通讯、授时、门禁和控制器的软件。站里所有“几点几分谁做了什么”，最后都落在我的机架上。"},{"id":"t_cable","q":"通讯怎么断的？","lie":true,"a":"十一天前链路中断，我用反射仪测过，断点在2.1公里外，多半是拖网挂的。报告贴在墙上了。","truth":"是我剪的。断点在湿区接线盒，离机架七米。我要让水面收不到控制器镜像，设备也没有外部对时。"},{"id":"t_clock","q":"控制器的钟准吗？","lie":true,"a":"断缆后各设备自走，我每天校一遍，误差最多几秒。控制器的钟是准的，你放心用它的记录。","truth":"不准。21:47我用管理员账户把它拨快了一小时半。日志上的案发时间就落进了我有人陪的时段。"},{"id":"t_night","q":"00:30到01:50在哪？","lie":true,"a":"23:30就回舱睡了，01:50沈小棠敲门，我才起来陪她去机房。之前一个人睡，没有证人，我不撒谎。","truth":"我没睡。00:35前后我在控制室，取了站长的主钥匙，00:48启动冲洗，01:10还回钥匙。"},{"id":"t_key","q":"钥匙盒密码你知道吗？","a":"知道，岳站长、江野、蓝医生和我。22:05到22:40站长取过钥匙，登记本上有，之后我没碰过。"},{"id":"t_seen","q":"有人说00:35见过你","needs":["ask:he.t_corridor"],"lie":true,"a":"谁说的？贺师傅？我那会儿去查加热器报警，随手开盒取手电。照这么算，站里每个人我都见过。","truth":"他看见的就是我，我正拿着主钥匙，门没关严。他问我，我说“加热器报警”，他没多问。"},{"id":"t_ning","q":"你认识宁岚吗？","lie":true,"a":"她是以前的潜水员，三年前出了事。我是后来才调来的，跟她不熟，只是听人说起过一些。","truth":"她是我的妻子，登记用的是她自己的姓。我调来渊一号，就是想弄明白她到底是怎么死的。"},{"id":"t_audio","q":"三年前的录音","needs":["clue:c_comm3","clue:c_ctrl2"],"a":"一个月前我恢复了被删的录音：她请求上浮，屠说“再留五分钟”。日志却写她自行超时。我要他们都付出代价。"}],"confronts":[{"clue":"c_comm1","breaks":"t_cable","a":"他的手停在桌沿：“我忘了拆这一张。”他深吸一口气，“断点离机架七米，是我剪的。”"},{"clue":"c_ctrl2","breaks":"t_clock","crack":true,"a":"他看着“21:47:12调整为23:17:12”，很久没说话：“管理员账户只有我。这行字是我写的。”"},{"clue":"c_lock1","breaks":"t_night","a":"他盯着01:00的0.00，喉结滚了一下：“采样仪是电池供电的，我没算进去。是我，00:48开始。”"},{"clue":"c_comm2","a":"他看着账户表：“ADM 邵远。你想说只有我能动那个钟？是，那归我管。”指尖敲了两下桌面。"},{"clue":"c_lock2","a":"“02:18，授权站长主钥匙。”他念得像在读报表，“机器写的，我只负责让它一直转下去，别的不管。”"},{"clue":"c_comm3","breaks":"t_ning","a":"他看着照片里的短发女子，声音轻得像自言自语：“岚。”他抬起头，“她是我妻子。我来这里，是为了她。”"},{"clue":"c_ctrl3","breaks":"t_seen","a":"他看着压到最低的座椅，苦笑：“站长一米八五，坐不到这个高度。我一米六五。好吧，那时我在控制台前。”"}],"fallback":"这个不在我的权限里，你问点别的。"},{"id":"lan","name":"蓝秋荷","role":"站医","age":44,"look":{"skin":"light","hair":"bun","hairColor":"black","glasses":"none","beard":"none","outfit":"labcoat","acc":"stethoscope","mood":"stern"},"bio":"渊一号站医，负责健康与高压医学。昨夜给卓岩治外耳炎，早上和站长一起打开了气密舱。","demeanor":"干脆，爱说“按规程”“从医学上讲”。","topics":[{"id":"t_role","q":"你负责什么？","a":"全员体检、高压医学、减压方案。饱和环境里的人病了不能随便往上送，所以我既是医生，也是半个工程师。"},{"id":"t_body","q":"死因是什么？","a":"缺氧窒息。唇和指甲发紫，没有外伤，没有挣扎，符合吸入无氧气体后几秒内失去意识。氦气不会报警。"},{"id":"t_time","q":"死亡时间能判断吗？","a":"判断不了。舱里加热，尸体降温很慢，给不出精确时间。02:18只是控制器的记录，不是我的结论。"},{"id":"t_cert","q":"你的资质有效吗？","lie":true,"a":"当然有效，高压医学资质每年复审，我从没落下。证书我可以拿给你看，只是现在不太方便。","truth":"去年9月就过期了。复审要上岸，我拖着没去，觉得站里没人会查。我没出过错，但确实不该瞒。"},{"id":"t_ear","q":"昨夜你在哪？","a":"00:35开始给卓岩清洗外耳炎，01:15结束，接诊登记里有。之后我回舱睡觉，一个人，没人证明。"},{"id":"t_tu","q":"屠鹤年和你有过节吗？","needs":["clue:c_lab4"],"a":"他两次问过我证书的事，说回岸后要报。我睡不好，可他是对的。我要真想让他闭嘴，何必等到现在。"}],"confronts":[{"clue":"c_qua4","breaks":"t_cert","a":"她看着到期通知，肩膀松了一下：“是的，去年9月到期，我一直没敢说。你要报就报，我不辩解。”"},{"clue":"c_lock3","a":"她轻声说：“他走得很安静吧？氦气没有味道，人什么也感觉不到。我只希望他没受过罪。”"},{"clue":"c_lock1","a":"她把纸带来回看了两遍，没有说话，只用指甲在01:00那一行划了一道印子，然后把纸带推回给你。"},{"clue":"c_lab4","a":"她读完便签，嘴角抿成一条线：“他两次问我，我都说在办。他要报，我没怪他。你要说我为此动手，随你想。”"}],"fallback":"从医学上讲，这个我给不出结论。"},{"id":"he","name":"贺守业","role":"厨师","age":56,"look":{"skin":"tan","hair":"bald","hairColor":"grey","glasses":"none","beard":"none","outfit":"apron","mood":"smile"},"bio":"干了八年的老厨师，北方口音，每天凌晨四点发面。给屠鹤年送过茶，称22:30就睡了。","demeanor":"爱说“嗨”“得嘞”，边说边擦手，被问到喝酒就岔开。","topics":[{"id":"t_role","q":"你在站里做什么？","a":"嗨，管九张嘴呗。氦氧空气里舌头发木，菜不做重口，谁也咽不下去。八年了，闭着眼我都摸得到每口锅。"},{"id":"t_tea","q":"送茶的事","a":"他夜里采样，我每晚22:20灌一壶热茶放他台子边。昨晚他还说了声“谢了老贺”，这是最后一次了。"},{"id":"t_night","q":"22:30以后你在哪？","lie":true,"a":"得嘞，22:30我就上床了，一觉睡到凌晨四点起来发面，睡得跟死猪一样，哪也没去过，您可别冤枉人。","truth":"我没睡。00:20我溜去气密舱，想取藏在冷柜里的米酒，舱门锁着，我只好趴在舷窗上看。怕站长知道。"},{"id":"t_porthole","q":"舷窗里看到了什么？","needs":["clue:c_lock4"],"a":"屠老师坐在采样台前低头写标签，好端端的，那会儿我手表是00:25。我敲了下玻璃，他没抬头，我就走了。"},{"id":"t_corridor","q":"回去的路上呢？","needs":["ask:he.t_porthole"],"a":"回舱要经过控制室。00:35左右门虚掩着，邵远在台子前，钥匙盒开着。他说“加热器报警”，我就走了。"},{"id":"t_congee","q":"你知道邵远的事吗？","needs":["ask:he.t_corridor"],"a":"每年6月14号，邵远来厨房要碗白粥，摆两副筷子，一口不吃，说“她爱喝”。那天是宁岚的忌日。"}],"confronts":[{"clue":"c_lock4","breaks":"t_night","a":"他在围裙上擦了又擦手：“得嘞，毛巾上有我的字，赖不掉。我00:20去了舱外，看到他还好好的才走。”"},{"clue":"c_mess3","a":"“料酒？”他嘿嘿一笑，笑意很快淡了，“我自己抿的。要是被站长知道，我这八年饭碗就没了。”"},{"clue":"c_lock3","a":"他看着那壶凉透的茶，眼眶发红：“我22:20灌的，他喝了小半杯。人这一辈子，说没就没了。”"}],"fallback":"嗨，这个我真不知道，您问别人吧。"},{"id":"shen","name":"沈小棠","role":"助理研究员","age":24,"look":{"skin":"fair","hair":"ponytail","hairColor":"black","glasses":"round","beard":"none","outfit":"hoodie","mood":"worried"},"bio":"屠鹤年带的博士后，第一次住进饱和站。称昨夜一直在舱里睡觉，被问到凌晨时显得紧张。","demeanor":"又快又碎，爱说“其实”“那个”，紧张就咬笔帽。","topics":[{"id":"t_role","q":"你在站里做什么？","a":"我是屠老师的博士后，做样本整理和数据。其实……站里的数据基本都是我一遍遍对过的，每组我都记得。"},{"id":"t_night","q":"昨晚你在哪？","lie":true,"a":"我一直在舱里睡觉，其实我睡得很早，一觉睡到天亮，那个，什么动静都没听见，真的什么都没有。","truth":"我没睡。00:00到01:45我在实验室写给期刊的邮件，举报导师的两组数据。怕被人知道，才撒谎。"},{"id":"t_comm","q":"你后来去了哪？","needs":["clue:c_lab3"],"a":"01:50我去敲机房的门，邵哥在，我们一直坐到03:30。他一直盯着屏幕，没离开过，我可以作证。"},{"id":"t_passing","q":"更早见过邵远吗？","needs":["ask:shen.t_comm"],"a":"其实……21:40左右我路过机房，门开着，他坐在终端前敲着什么。我没进去，大概在设置设备吧。"},{"id":"t_data","q":"那两组数据怎么回事？","needs":["clue:c_lab3"],"a":"屠老师让我“整理”，我把原始值抹平了。我后来知道不对，但不敢反抗。邮件我写了三遍，一次都没发出去。"},{"id":"t_shao","q":"邵远有什么异常？","needs":["ask:shen.t_comm"],"a":"那个，我进门时他的手很凉，像刚洗过冷水。他问我几点了，我说一点五十，他“哦”了一声就没再说话。"}],"confronts":[{"clue":"c_lab3","breaks":"t_night","a":"她盯着保存时间，咬紧笔帽：“00:52，01:30……都是我写的。对，我没睡。我不想被人知道。”"},{"clue":"c_lab1","a":"“‘我不知情’？”她读完笔记，声音发抖，“他怎么能这么写？那两组数据明明是他要我动的。”"},{"clue":"c_lock1","a":"她把纸带读了两遍：“01:00……其实我那时在实验室，没出过门，笔记本的保存时间可以证明。”"}],"fallback":"那个……我不太清楚，对不起。"},{"id":"gu","name":"谷慎","role":"赞助方代表","age":45,"look":{"skin":"light","hair":"slick","hairColor":"black","glasses":"none","beard":"none","outfit":"suit","acc":"tie","mood":"sly"},"bio":"海衡能源派驻的赞助方代表，负责监督项目与评估书。称自己吃了安眠药，昨夜睡得很沉。","demeanor":"圆滑，满口“原则上”，被逼问就笑着换话题。","topics":[{"id":"t_role","q":"你在这里代表谁？","a":"海衡能源，项目的出资方。原则上，我们对站里的安全负责，也对结果负责。这次的事我们很痛心。"},{"id":"t_sleep","q":"昨晚你在哪？","lie":true,"a":"我吃了半片安眠药，22:30就睡了，一觉到六点。要证明这点很难，但我没有理由撒谎。","truth":"我没睡。01:20站长来我舱里，我们谈到02:50，改安全评估书的措辞。怕被人做文章，才说我在睡觉。"},{"id":"t_chief","q":"你和站长谈了什么？","needs":["clue:c_qua3"],"a":"评估书里的“管理缺陷”，我们想改成“已整改”。他本来不肯，后来松了口。02:50他走时我看了表。"},{"id":"t_report","q":"屠鹤年的报告","a":"他要写三年前宁岚的事，还有站里的安全隐患，措辞尖锐。我们劝过，他不肯。报告一出，许可证可能不保。"},{"id":"t_pressure","q":"你要医生改结论？","a":"我只是建议，没定论前不必急着写“他杀”。这对站里的人、项目和家属都更稳妥。你们觉得不妥，我收回。"},{"id":"t_key","q":"你知道钥匙盒密码吗？","a":"不知道，我不是值班人员，没有这个权限。主钥匙我只在介绍会上见过一次，当时挂在站长腰上。"}],"confronts":[{"clue":"c_qua3","breaks":"t_sleep","a":"他笑容僵了一瞬：“被你们看到了。岳站长01:20到我这儿，02:50才走。我不想传出去，才撒了谎。”"},{"clue":"c_lab1","a":"“‘日志是岳峥改的’……”他念了一遍，揉了揉眉心，“屠老师想得倒周到，想把一切推给站长。”"},{"clue":"c_qua2","a":"他看到撕页，倒吸一口气：“三年前的日志被改过？这我可不知道。要是知道，评估书我不会签。”"}],"fallback":"原则上，这个我不便评论。"}],"solution":{"culprit":"shao","method":{"q":"凶手是怎么做到的？","options":["02:18借站长主钥匙冲洗，事后还回盒中","在热茶里下药，再改动采样仪与日志","拨快控制器的钟，00:48借钥匙冲洗","夜里潜水经湿区舱口入站，取钥匙冲洗"],"correct":2},"motive":{"q":"为什么杀人？","options":["出资方授意灭口，防止报告交出去","亲人死于延长的深潜，要两人偿命","死者握有造假证据，先下手保前程","多年自责，只想让下令的人付出代价"],"correct":1},"keyClues":["c_lock1","c_lock2","c_ctrl2","c_comm1","c_comm2","c_qua1"],"truth":["凶手是通讯工程师邵远。屠鹤年死于00:48，不是日志上的02:18。“站长主钥匙授权”是他布下的陷阱。","三年前，邵远的妻子宁岚深潜时请求上浮，屠鹤年却令她“再留五分钟”，她死了；岳峥又改了日志。邵远要屠死，要岳背罪。","他剪断光缆，断绝外部对时和镜像；21:47用ADM账户把控制器的钟拨快90分钟。那时岳、谷、卓、蓝正在牌桌上。","00:35他取走站长钥匙，被贺守业撞见；00:48冲洗，01:10还钥匙。01:50起沈小棠陪他，只盖住日志上的02:18。","破绽在钟：电池采样仪01:00氧归零，江野的表00:31入水，都比日志早90分钟。岳、江、蓝由此洗清，其余人的谎与命案无关。"]}},{"id":"mirror","title":"镜厅","tagline":"四壁皆镜，一地粉面，只留一串脚印，和一具没有凶器的尸体。","difficulty":5,"cover":"coverOldHouse","tone":"red","brief":"一九二七年十一月五日深夜，暴雪封山。霍恩男爵的庄园里，管家克勒在电话线断前请你赶来。他在门厅攥着手套，嗓音发哑：“主人死在镜厅里。老爷嘱咐仪式后多留他一会儿，我守到二十三点四十分才开门。我第一个进去，只探了脉，别的什么都没碰。他脸上红肿，像被烫过。”舞厅大门敞着，镜里一地雪白。八个被困的人，等着你开口。","victim":{"name":"奥古斯特·冯·霍恩","desc":"霍恩男爵，六十一岁，会馆主人。仰卧在舞厅正中，面部红肿，没有外伤，没有凶器。","look":{"skin":"light","hair":"slick","hairColor":"silver","glasses":"none","beard":"goatee","outfit":"suit","acc":"pocketwatch","mood":"stern"}},"publicFacts":["每年假面夜二十三点，男爵与两名替身（克勒、马洛）戴金面具入镜厅，替身退出，男爵独留，二十三点一刻摇铃摘面具。","舞厅地上新撒滑石粉，门没有锁，仪式期间由管家守在门外。","二十三点四十分管家开门，男爵已死。粉面上没有别人的脚印，男爵戴入的金面具不见了。","暴雪封桥，电话线二十三点五十八分中断。","在场相关者八人：管家、面具师、画家、上校、女伯爵、医生、记者、债权人。","男爵负债，庄园已抵押，与几位客人不睦。"],"relations":{"kohler":"伺候霍恩四十年的老管家","liese":"会馆的面具师，替他管金面具","lucien":"驻馆三年的画家，替他修镜描金","konrad":"二十年的老战友，每年必来赴宴","elena":"未婚妻，春天就要结婚","braun":"山下小镇的医生，老朋友","margot":"女伯爵带来的专栏记者","levi":"放贷给他的债主，抵押着庄园"},"links":[{"a":"kohler","b":"lucien","text":"同为今晚的金面替身"},{"a":"liese","b":"lucien","text":"面具的重镀与验收都要经两人之手"},{"a":"elena","b":"margot","text":"女伯爵带着记者来赴宴"},{"a":"kohler","b":"liese","text":"管家举荐她进的工坊"}],"deathReport":{"time":"约 23:00–23:30","cause":"疑似生物碱中毒，经皮肤吸收，无外伤","scene":"管家克勒二十三点四十分开门，见男爵仰卧舞厅正中，面部红肿，已无脉搏，金面具不见。","loc":"hall","notes":["面部红肿麻木，口鼻沾着金箔屑","瞳孔散大，全身无外伤","四周没有凶器，粉面上只有一串脚印"]},"timeline":[{"t":"22:50","text":"男爵、管家、画家在前厅戴上金面具。"},{"t":"23:00","text":"三个金面黑披风的人走进舞厅，23:01 两人退出。"},{"t":"23:02","text":"管家关上舞厅大门，守在门外。"},{"t":"23:15","text":"本应是男爵摇铃摘面具的时间，无动静。"},{"t":"23:40","text":"管家开门，发现男爵死亡，面具不见。"},{"t":"23:58","text":"电话线中断。"}],"budget":{"search":12,"ask":22},"locations":[{"id":"hall","name":"镜厅（舞厅）","scene":"hall","desc":"四壁嵌满镜板的大舞厅，吊灯只亮一半，成百个自己在镜里重叠。地上新撒的滑石粉白得像雪。","clues":[{"id":"c_hall1","title":"厅心的尸体与粉面","text":"粉面上只有一串脚印，止于厅心的尸体旁。尸体脸上无面具，口鼻红肿，沾着金箔屑。四周没有凶器。"},{"id":"c_hall2","title":"脚手架下的工具箱","text":"帆布后藏着木箱：金箔本、貂毛笔、金胶、细铜铆钉和一支沾铜屑的小冲子。箱盖内侧写着 L.M.。"},{"id":"c_hall3","title":"北墙的镜板暗门","text":"北墙一块镜板后是旋转暗门，门前粉面完好。镜板背面铸着“V. & FILS 1896”，每块都一样。"}]},{"id":"atelier","name":"面具工坊","scene":"library","desc":"旧图书室改的工坊，架上摆满空白面具和假发，工作台上一盏绿罩灯，满是胶水味。","clues":[{"id":"c_lib1","title":"退回的“II号”面具","text":"工作台上的金面具，内眉钉着铭牌“II”，铆钉头比旁边的亮。左太阳穴有一道泛黄的修补痕。内衬干净。"},{"id":"c_lib2","title":"面具登记簿","text":"登记簿：11月5日收回三面，验号栏空白。I号左太阳穴有旧裂，已补。22:50凭铭牌发：I男爵，II马洛，III克勒。"},{"id":"c_lib3","title":"抽屉底的信与预约卡","text":"抽屉底有封泪湿的信：“他说过会娶我，却要抛下我……爸爸，我不敢告诉你。”夹着诊所预约卡，写“妊娠三月”。"}]},{"id":"study","name":"男爵书房","scene":"study","desc":"二楼尽头的书房，红木书桌、保险柜和一面落地镜。壁炉还有余温，空气里有纸灰味。","clues":[{"id":"c_study1","title":"旧卷宗与合影","text":"抽屉里有《瓦朗镜厂清算案 1908》，保证人霍恩。夹着合影，背面“Armand 与 Lucien”，男孩食指缠绷带。"},{"id":"c_study2","title":"流程单与雪橇单","text":"男爵手写流程单：“23:05 北镜门；23:40 M 开门，宣布失踪。”雪橇单“23:30 北角门”。旅行箱已空。"},{"id":"c_study3","title":"遗嘱与新草稿","text":"11月1日的遗嘱草稿划去伊莲娜的份额，改为补偿金。抵押附页：债权人利维，欠款四十万，庄园估价约三十万。"},{"id":"c_study4","title":"壁炉里的纸灰","text":"壁炉里有新烧的纸灰，残角印着军团徽记和“军需款”。炉边地毯上掉着一粒军服铜纽扣。"}]},{"id":"dining","name":"餐厅","scene":"dining","desc":"长桌上的夜宵没收，银烛台歪着，花窗下摆着几张小圆桌。窗外雪越下越大。","clues":[{"id":"c_din1","title":"花窗下的两只酒杯","text":"小圆桌上两只酒杯，一只沾深红口脂。杯下字条：“什么都别签。二十三点十分，北角门等您。”背面有“L”。"},{"id":"c_din2","title":"皮套里的相机","text":"餐边柜下的皮套里有台相机，底片可见流程单、空皮箱，标注22:36至22:41。皮套别着记者证：玛戈·法伊弗。"},{"id":"c_din3","title":"医生的药箱","text":"药箱里有只空药瓶，标签“霍恩男爵·强心”，洋地黄。处方存根写着“11月3日 布劳恩”。"},{"id":"c_din4","title":"画家的座位","text":"一个几乎没动的餐位，椅背搭着沾金粉的围裙。座次表旁注：“马洛22:20起席，说去整理披风。”"}]},{"id":"garden","name":"雪中花园","scene":"garden","desc":"积雪没过脚踝的花园，玻璃温室在雪里泛着微光，北墙有扇通向小路的角门。","clues":[{"id":"c_gar1","title":"毒草温室","text":"温室里两盆乌头被连根拔去。石臼里是棕糊混着金胶、金箔，旁有沾金粉的貂毛笔。门口有串防滑钉鞋印，边缘已圆钝。"},{"id":"c_gar2","title":"北角门的雪橇辙","text":"北角门外有雪橇辙，停了很久。门内雪地有皮靴来回踱步的印子，边缘锋利，地上散着粗雪茄烟蒂。"},{"id":"c_gar3","title":"药棚里的乌头酊","text":"药棚里“乌头酊（外用）”只剩小半瓶，标签盖着布劳恩医生的领用章，最近日期是十月初。"}]},{"id":"cellar","name":"酒窖","scene":"cellar","desc":"潮冷的石砌酒窖，橡木桶排成行，窖尾有道砖拱。煤油灯照不透角落。","clues":[{"id":"c_cel1","title":"酒桶后的金面","text":"空酒桶后，绣着 M.K. 的白手套裹着金面具：铭牌“I”，铆钉头新亮，边缘下铸号“2”，无修补痕。内衬透出苦味褐胶。"},{"id":"c_cel2","title":"深色证件夹","text":"同一桶后有只证件夹：护照名“安东·维克”，照片却是霍恩；一捆法郎，十来万；车票存根“23:30 北角门”。"},{"id":"c_cel3","title":"窖尾的暗道","text":"砖拱后的窄暗道通向舞厅北墙。厚灰上没有任何鞋印，出口石阶上的灰也完整。"}]}],"suspects":[{"id":"kohler","name":"马蒂亚斯·克勒","role":"会馆管家","age":58,"look":{"skin":"light","hair":"bald","hairColor":"grey","glasses":"none","beard":"mustache","outfit":"suit","acc":"pocketwatch","mood":"worried"},"bio":"霍恩家的四十年老管家，三名金面替身之一，仪式后守在厅门外。就是他在断线前请你赶来。","demeanor":"老仆口吻，爱说“先生”“照规矩”，急了攥手套。","topics":[{"id":"t_role","q":"在会馆多久？","a":"四十年了，先生。十八岁进宅子，伺候过老男爵，后来是现在的老爷。老爷有事先吩咐我。"},{"id":"t_touch","q":"进去碰过什么？","lie":true,"a":"只探了他的脉，冰凉，没救了。别的什么都没碰。面具我也没见着，大概他自己扔到哪儿去了。","truth":"我拿了。面具掉在他手边，内衬有苦味。我怕莉泽小姐被疑，连同证件夹塞进了酒窖空桶后。"},{"id":"t_delay","q":"为何迟迟不开门？","lie":true,"a":"老爷自己嘱咐的，说今年想在镜子前多留一会儿。我是仆人，不敢违命，谁来催也不能开。","truth":"老爷定的就是二十三点四十分。他欠了债，要借仪式失踪，我拖到时辰再宣布他“消失在镜里”。"},{"id":"t_niece","q":"莉泽是你什么人？","lie":true,"needs":["clue:c_lib3"],"a":"远房侄女，先生。我举荐她来工坊，因为她手巧。除此之外没有别的，她这些日子不舒服，您别吓着她。","truth":"她是我亲生女儿，随母姓。她怀了老爷的孩子，我见她哭着躲进工坊才知道。她连小鸟都不敢捏。"},{"id":"t_mask_seen","q":"那面具哪不对？","needs":["clue:c_cel1","ask:kohler.t_touch"],"a":"老爷那张左太阳穴有修补痕，我亲眼见莉泽补的，这张没有。铭牌写着I，边上露出个“2”。里头一股苦味。"},{"id":"t_pouch","q":"证件夹怎么回事？","needs":["clue:c_cel2","ask:kohler.t_touch"],"a":"假护照是老爷的主意。他怀里鼓着，我一时糊涂就拿了，想着这笔钱至少能留给小姐。先生，我不是贼。"},{"id":"t_who","q":"谁动过面具？","needs":["ask:kohler.t_mask_seen","clue:c_lib2"],"a":"工坊门平日不上锁。重镀是马洛先生包办的，四号取走，五号傍晚还回。小姐那天不舒服，只签了收条。"}],"confronts":[{"clue":"c_cel1","breaks":"t_touch","a":"手套放上桌，克勒的手抖了一下，慢慢坐下去。“是我藏的。我以为这样能护住她。我骗了您，先生。”"},{"clue":"c_study2","breaks":"t_delay","a":"他盯着流程单，嘴唇发颤。“那是老爷的字。我答应过他到死都不说，可如今他真的死了。”"},{"clue":"c_lib3","breaks":"t_niece","a":"“您翻了她的抽屉！”他先怒，又垮下来。“是，她是我女儿。我这辈子没敢当着人叫她一声。”"},{"clue":"c_lib1","a":"他看了很久。“这是老爷的原面具，铭牌却写着II。莉泽凭牌递出去的……原来她比我更不知情。”"}],"fallback":"先生，这东西老仆没见过，也不敢乱猜。"},{"id":"liese","name":"莉泽·哈恩","role":"面具师","age":31,"look":{"skin":"fair","hair":"bun","hairColor":"brown","glasses":"none","beard":"none","outfit":"apron","acc":"necklace","mood":"worried"},"bio":"会馆面具师，自称是管家的远房侄女。仪式前由她擦拭并分发三张金面具，整晚守着工坊。","demeanor":"声音轻，爱咬指节，句子很短，逼急会哭。","topics":[{"id":"t_role","q":"你做什么？","a":"做面具、修面具、管面具。I、II、III三张金面是霍恩老爷订的，每年仪式用。我不喜欢人多。"},{"id":"t_hand","q":"面具怎么发的？","a":"二十二点二十五分我擦了老爷那张，认的是左太阳穴的修补痕，放上托盘。二十二点五十分暗灯里凭铭牌摸着发。"},{"id":"t_receive","q":"重镀后验过吗？","lie":true,"a":"十一月五日傍晚收回时，我逐面验了号和铭牌，都对，才放上架。登记簿上有我的签名，不会错。","truth":"我没验。那天下午我去了诊所，回来恶心得站不住，只签了字。我怕你们说我失职，所以撒谎。"},{"id":"t_baron","q":"你和男爵？","lie":true,"a":"雇主和手艺人，如此而已。他有他的宾客，我有我的工坊，我们并不熟，请您别乱猜，我什么都不知道。","truth":"我怀了他的孩子，三个月。他答应过娶我，可我发现他在准备远走。我恨过他，但我没有杀他。"},{"id":"t_dad","q":"克勒是你什么人？","needs":["clue:c_lib3"],"a":"他是我父亲。我随母姓，他叫我侄女，是怕人闲话。今晚他守舞厅门，我守工坊，没说话。"},{"id":"t_painter","q":"马洛碰过面具吗？","needs":["ask:liese.t_receive","clue:c_hall2"],"a":"十一月四日下午他来取面具重镀，还讨了一小把铜铆钉，说铭牌松了要重铆。我给了，他的手艺没人比得过。"},{"id":"t_rivet","q":"铆钉什么样？","needs":["clue:c_cel1","ask:liese.t_swap"],"a":"四号交出去时，I和II的铆钉头都是旧的，发暗。五号收回……我只看了签收单，真的没记得。"},{"id":"t_swap","q":"这张“II号”？","needs":["clue:c_lib1","ask:liese.t_hand"],"a":"这张有修补痕，是老爷的原面具。可铭牌写着II？我擦的是它，发时摸的却是牌。那我递给老爷的……"}],"confronts":[{"clue":"c_lib2","breaks":"t_receive","a":"她盯着那栏空白，眼泪涌出来。“我签了字，没验……我怕你们说我害了老爷。可我没在面具上动过手脚。”"},{"clue":"c_lib3","breaks":"t_baron","a":"“那是我的信！”她声音一尖，又低下去。“是，是我的孩子。我恨过他，可我怎么会杀他？”"},{"clue":"c_hall2","a":"她盯着铆钉与冲子。“这是马洛先生的箱子。他是我见过最稳的手。铜屑是新的……您别问我，我不敢往下想。”"},{"clue":"c_cel1","a":"她接过手套，指尖发白。“这是爸爸的手套……面具里有毒？我每天擦它们。是我的错，我没验。”"},{"clue":"c_lib1","a":"她摸着那道修补痕，眼眶红了。“我认得每一道胶线。可铭牌写着II……这牌子，是谁钉的？”"}],"fallback":"我不知道这是什么……我不想看，也不想被人问。"},{"id":"lucien","name":"吕西安·马洛","role":"驻馆画家","age":34,"look":{"skin":"tan","hair":"messy","hairColor":"brown","glasses":"none","beard":"stubble","outfit":"vest","acc":"scarf","mood":"smile"},"bio":"法国画家，三年前受聘修镜描金，左手食指少一节。今晚是金面替身之一，爱笑也爱开玩笑。","demeanor":"温和幽默、爱用比喻，被追问时语速更慢。","topics":[{"id":"t_role","q":"你做什么？","a":"描金、修镜框、补壁画。镜厅四壁的金线是我一笔笔描的。我在这里三年，不太爱说话，爱看光。"},{"id":"t_alias","q":"你是哪里人？","lie":true,"a":"里昂人，孤儿，叔叔养大的。三年前看到招聘告示才来，之前没听过霍恩的名字。手指是小时候被炉子烫的。","truth":"我姓瓦朗。一九〇八年霍恩吞了我父亲的镜厂，父亲在炉前上了吊。镜厅四壁的镜子，就是我家最后一批货。"},{"id":"t_mask","q":"面具的事？","lie":true,"a":"我只负责重镀三张，十一月五日傍晚原样还给莉泽，没碰别的。仪式我戴的是II号，退回时她也在。","truth":"我对调了I和II的铭牌。毒涂在No.2的内衬，让莉泽凭牌把它发给霍恩。我戴的才是他的原面具。"},{"id":"t_where","q":"离席去哪了？","lie":true,"a":"一直陪伯爵夫人坐在餐厅，直到去前厅戴面具。我的围裙还搭在椅背上，不少人看见我坐着。","truth":"我借口整理披风，去温室洗石臼。石臼里还有半臼糊没洗干净。雪下得大，我一身是雪回来。"},{"id":"t_target","q":"毒冲谁来的？","lie":true,"needs":["clue:c_cel1"],"a":"前厅灯暗，三人摸着面具往脸上扣，谁拿错都可能。毒也许冲着我或克勒，男爵只是倒霉。","truth":"没有人拿错。是我换的牌，毒从一开始就冲着他。从我父亲死的那年起，我就该做这件事。"},{"id":"t_plate","q":"铭牌何以新铆？","needs":["clue:c_lib1","ask:lucien.t_mask"],"a":"重镀时铭牌松了，我顺手重铆，莉泽还借了铜铆钉给我。这是正常工序，换了谁来做都一样。"},{"id":"t_gild","q":"金胶和铜屑？","lie":true,"needs":["ask:lucien.t_plate","clue:c_hall2"],"a":"金胶是重镀用的，铜屑是冲子磨铆钉磨出来的。我吃这碗饭，箱子丢在脚手架后，谁路过都能看。","truth":"冲子是我拆铭牌用的：起旧钉，换位，再铆。箱子本该收走，那晚我急着去温室，来不及。"},{"id":"t_root","q":"温室乌头？","lie":true,"needs":["ask:lucien.t_gild","clue:c_gar1"],"a":"温室？我从没进去过。石臼大概是园丁的，貂毛笔也是别人落下的，我画画只用猪鬃笔，您可以去查。","truth":"我挖了两盆乌头根，磨成糊混进金胶，涂满No.2内衬，盖上金箔。我的指尖到现在还发麻。"}],"confronts":[{"clue":"c_lib1","breaks":"t_mask","crack":true,"a":"他看着那道修补痕，指尖在桌沿停了一下。“这是霍恩的原面具，对吗？”他笑了，“是，我戴的才是他的。”"},{"clue":"c_din4","breaks":"t_where","a":"“围裙还在椅背上……我忘了。”他笑得很淡，“说谎的人，总以为自己收拾得很干净。”"},{"clue":"c_cel1","breaks":"t_target","a":"他听着“铭牌I，铸号2”，沉默很久。“没有人拿错。”他说，“那张面具从一开始就是为他准备的。”"},{"clue":"c_study1","breaks":"t_alias","a":"“他居然留着这张照片。”他盯着缠绷带的男孩，低声说：“我父亲在炉前上的吊，我十五岁。”"},{"clue":"c_hall2","breaks":"t_gild","a":"他看着箱子，反而放松了。“冲子是我的，铆钉是我的，铜屑也是。我把两块铭牌换了位置。”"},{"clue":"c_gar1","breaks":"t_root","a":"“温室里的石臼。”他叹气，“我本想洗掉，可雪太大，怕被人看见。乌头开了二十年，没人认得它有毒。”"}],"fallback":"您问的东西我听不太懂，画家只会看颜色。"},{"id":"konrad","name":"康拉德·冯·阿尔滕","role":"退役上校","age":55,"look":{"skin":"tan","hair":"short","hairColor":"grey","glasses":"none","beard":"mustache","outfit":"uniform","acc":"badge","mood":"stern"},"bio":"霍恩的老战友，退役上校，今晚头一个到场赴宴。自称仪式时一直站在厅门口的宾客队伍里。","demeanor":"短句、命令式，爱说“废话少说”，被戳痛会拍桌。","topics":[{"id":"t_role","q":"和男爵什么交情？","a":"二十年战友。一九一六年他在壕沟里背过我，这笔人情我记着。每年假面夜我必到，喝酒。"},{"id":"t_where","q":"23点后在哪？","lie":true,"a":"站在厅门口的宾客队伍里，没离开半步，一直到克勒开门。废话少说，这么多人看着，您问谁都一样。","truth":"我二十三点零三分离开了。溜进书房，想烧掉男爵手里握着的旧信。纽扣大概是那时勾落的。我没杀他。"},{"id":"t_sabre","q":"你的佩剑呢？","a":"在腰上，您可以看。礼仪佩剑，没开过刃。要杀人，我不会用这种玩具。去看尸体的脸，别看我的腰。"},{"id":"t_painter","q":"怎么看画家？","a":"手艺没话说，人有点怪。他刚来那天站在镜厅里翻看镜板背面的铸字，脸白得像纸。后来再没提过。"},{"id":"t_debt","q":"你和他有账？","needs":["clue:c_study4"],"a":"有。他拿几封旧信吊了我十年，是我挪用军需款的证据。他一死，信落到律师手里，我更糟。杀他对我没好处。"},{"id":"t_study","q":"书房里见到什么？","needs":["clue:c_study2","ask:konrad.t_where"],"a":"桌上有流程单，空皮箱，雪橇单写着北角门。老狐狸要跑！我骂了一句就走，二十三点二十分回到厅门口。"}],"confronts":[{"clue":"c_study4","breaks":"t_where","a":"康拉德脸涨得发紫，拍了下桌子。“那粒纽扣……该死。是，我溜去烧信。可我只烧了自己的。”"},{"clue":"c_study2","a":"他盯着流程单，喉结滚动。“他竟然要走。二十年的战友，到头来只留我一个人对着债主。”"},{"clue":"c_hall1","a":"“脸肿了，还有金屑……”他背过身，“没有刀，没有血，连个脚印都没有。这不是军人的杀法。”"}],"fallback":"这东西我没见过，废话少说，问点要紧的。"},{"id":"elena","name":"伊莲娜·冯·罗森","role":"女伯爵","age":44,"look":{"skin":"fair","hair":"long","hairColor":"blonde","glasses":"none","beard":"none","outfit":"dress","acc":"earrings","mood":"sly"},"bio":"霍恩的未婚妻，按旧遗嘱是继承人。仪式时站在厅门口，二十三点半头一个催管家开门，神色从容。","demeanor":"贵族腔，慵懒带刺，爱说“亲爱的”。","topics":[{"id":"t_role","q":"和男爵的关系？","a":"亲爱的，我是他的未婚妻，春天就结婚。认识五年了，他会说笑话，会写诗。我不是为钱。"},{"id":"t_love","q":"感情如何？","lie":true,"a":"恩爱，如同镜子里的两个人。他从没让我受过委屈，我也从没想过离开他。想听别的，那是白费功夫。","truth":"我知道他的新遗嘱。他要甩开我，只给一笔补偿金，我自己也在准备离开。但我没有杀他。"},{"id":"t_aware","q":"知道他的债务吗？","lie":true,"a":"债务？他从不跟我谈钱，我只知道他慷慨。庄园抵押没抵押，我真不清楚。谁会在舞会前夜问这种事。","truth":"我知道。利维告诉我，男爵要借仪式一走了之，让我别签字。我们约好二十三点十分北角门见，我没能走开。"},{"id":"t_levi","q":"和利维谈什么？","needs":["clue:c_din1"],"a":"他说男爵欠他四十万，庄园只值三十万，我继承的是空壳。我们商量过要不要替男爵还账，仅此而已。"},{"id":"t_painter","q":"画家的行踪？","a":"马洛先生坐我邻座，二十二点二十分借口整理披风离席，二十二点五十分前后才回，肩头有雪。"},{"id":"t_will","q":"遗嘱怎么看？","needs":["clue:c_study3"],"a":"新草稿划了我的名字，一点也不意外。庄园资不抵债，我继承的是负资产。把我当最大受益人，岂不是个笑话？"}],"confronts":[{"clue":"c_din1","breaks":"t_aware","a":"她先笑，笑意渐淡。“那是利维的字条，口脂是我的。好吧，亲爱的，我知道。不说，是因为这太像杀人动机。”"},{"clue":"c_study3","breaks":"t_love","a":"她盯着被划去的名字看了很久。“他连这个也不告诉我。我们都等着对方先开口，等到他躺在地上。”"},{"clue":"c_hall1","a":"“脸上的金屑……”她眼底闪了一下，“二十三点半我就觉得不对。他爱干净，仪式不可能拖这么久。”"}],"fallback":"亲爱的，这东西我不认得，也不想认得。"},{"id":"braun","name":"西奥多·布劳恩","role":"医生","age":47,"look":{"skin":"light","hair":"sidepart","hairColor":"brown","glasses":"round","beard":"goatee","outfit":"suit","acc":"stethoscope","mood":"tired"},"bio":"山下小镇的医生，霍恩的老朋友。二十三点四十一分头一个验尸，称死亡在二三十分钟前。","demeanor":"冷静克制，爱用专业词，被追问私事会扶眼镜。","topics":[{"id":"t_exam","q":"死因怎么看？","a":"我二十三点四十一分入内：面部红肿麻木，瞳孔散大，死亡约二三十分钟前。像生物碱经皮肤吸收，没有外伤。"},{"id":"t_treat","q":"给他开过药吗？","lie":true,"a":"没有。我只是社交上的朋友，从没给他开过药，也没为他治过病。他身体硬朗得很，别往医药上猜。","truth":"我给他开过洋地黄，他有心脏病，一直瞒着人。我怕泄露病情才撒谎，药是他自己服完的，与命案无关。"},{"id":"t_tincture","q":"药棚的乌头酊？","lie":true,"needs":["clue:c_gar3"],"a":"我今年夏天以后就没碰过药棚，那瓶酊剂跟我无关。您不必拿这个吓我，我是医生，不是投毒的人。","truth":"我取过，给他痛风外敷，稀释后才能用。瓶里少的那些，十月初就用掉了。我没想到有人拿乌头做别的用途。"},{"id":"t_cause","q":"怀疑什么毒？","needs":["clue:c_hall1"],"a":"唇周红肿、金屑、全身麻木，像乌头碱。数分钟起效，经皮肤黏膜都能吸收。但得先有东西贴在脸上。"},{"id":"t_liese","q":"见过莉泽吗？","needs":["clue:c_lib3"],"a":"十一月五日十六点三十分她来过，孕三月，需要休息。保密义务本不该破，可她没有杀人的嫌疑，我可以作证。"},{"id":"t_hand","q":"谁手上异常？","needs":["ask:braun.t_exam","clue:c_gar1"],"a":"一提温室，我想起马洛。十一月五日中午他问我手指发麻是怎么回事，说画画冻着了。我给了锌软膏，没多问。"}],"confronts":[{"clue":"c_din3","breaks":"t_treat","a":"他扶了扶眼镜。“那是我的处方。”他苦笑，“霍恩要我保密，他最怕人知道他心脏不好。”"},{"clue":"c_gar3","breaks":"t_tincture","a":"“我的章。”他淡淡道，“痛风的老毛病，酊剂是外敷的。我撒谎，因为这瓶东西在命案里太像凶器。”"},{"clue":"c_cel1","a":"他戴上手套，用镊子拨开内衬嗅了嗅。“乌头碱，涂得很匀，外面盖了金箔。这是熟悉金箔与胶的人干的。”"}],"fallback":"这不是我的专业范围，抱歉。"},{"id":"margot","name":"玛戈·法伊弗","role":"记者","age":29,"look":{"skin":"light","hair":"bob","hairColor":"auburn","glasses":"none","beard":"none","outfit":"jacket","acc":"flower","mood":"smirk"},"bio":"自称是伯爵夫人带来的社交专栏记者，整晚在宾客中穿梭，爱说爱笑，手里总握着笔记本。","demeanor":"快嘴、俏皮、爱抢话头，爱说“您别想套我”。","topics":[{"id":"t_role","q":"来会馆做什么？","lie":true,"a":"社交专栏呀。伯爵夫人带我来写假面夜，谁戴什么面具、谁和谁跳舞。我就是个写八卦的，别想套我。","truth":"我是《科隆晨报》的调查记者，来查霍恩的假账和那四十万抵押。伯爵夫人是我的掩护，她不知情。"},{"id":"t_study","q":"22点半在哪？","lie":true,"a":"在餐厅，对着蛋糕和香槟写稿，侍者可以作证。我连书房在哪儿都不知道，您别想套我的话。","truth":"我撬了书房抽屉，22:36到22:41拍了流程单、空皮箱。我知道男爵打算失踪，没说，是想要独家。"},{"id":"t_case","q":"你拍到什么？","needs":["clue:c_din2"],"a":"流程单上23:40“宣布失踪”，空皮箱，雪橇单。我猜他要借仪式跑路，所以伯爵夫人催门时我一点也不急。"},{"id":"t_bell","q":"听到铃声吗？","a":"没有。铃是男爵亲手摇的，每年准时。今年没响，我就觉得不对。伯爵夫人二十三点半去敲门，克勒死活不开。"},{"id":"t_butler","q":"管家后来去哪了？","needs":["clue:c_cel1"],"a":"二十三点五十分，克勒说去取酒，脸灰得像纸，披风下鼓鼓的，像藏了东西，往酒窖楼梯去了。"},{"id":"t_gate","q":"外面有动静吗？","needs":["clue:c_gar2"],"a":"二十三点一刻前后，我在走廊窗口看见雪地里有个裹深色大衣的人，在北角门来回走，我没在意。"}],"confronts":[{"clue":"c_din2","breaks":"t_role","a":"她笑了一声，像被抓到偷糖。“好吧，被您翻了皮套，我是记者。可我不是凶手，我只想拿一份独家。”"},{"clue":"c_study2","breaks":"t_study","a":"“那抽屉是我撬的。”她干脆承认，“偷拍又不犯杀人罪，顶多算犯了点新闻道德，对吧？”"},{"clue":"c_cel2","a":"“证件夹……”她眼睛一亮又皱眉，“克勒藏的？好新闻，也是坏兆头。他到底在护着谁？”"}],"fallback":"这玩意儿我没拍过，您别想套我。"},{"id":"levi","name":"所罗门·利维","role":"债权人","age":52,"look":{"skin":"light","hair":"slick","hairColor":"black","glasses":"rect","beard":"mustache","outfit":"coat","acc":"pocketwatch","mood":"sly"},"bio":"山下银行老板，持有庄园抵押，欠款四十万。自称整晚留在大厅和餐厅，哪儿都没去，说话客气得体。","demeanor":"客气、算计，句句像在谈生意，被戳穿更礼貌。","topics":[{"id":"t_role","q":"你们的账怎么算？","a":"我借他四十万，抵押庄园。我不是他的敌人，只是他的债主。今晚来，就是想听听他怎么还。"},{"id":"t_where","q":"23点后在哪？","lie":true,"a":"一直在大厅和餐厅，伯爵夫人可以作证。我不是那种在雪夜里乱跑的人，我的皮靴也不配。","truth":"二十三点十分到四十五分，我在北角门外。雪橇夫说男爵订了二十三点半的车。我想堵他，什么人也没等到。"},{"id":"t_know","q":"知道他要逃吗？","lie":true,"a":"不知道。我只是来赴宴，顺便谈谈利息。债主要是知道他要逃，早就把庄园的钥匙收走了，对吧？","truth":"我知道。我买通了雪橇夫，他把预订的事全告诉了我。我又告诉了伯爵夫人，让她别签任何字。"},{"id":"t_note","q":"字条是你写的？","needs":["clue:c_din1"],"a":"是我写给她的：别答应他的条件，我在北角门等她商量对策。生意人的暗语，被你们读成了阴谋。"},{"id":"t_loan","q":"他死了你亏多少？","needs":["clue:c_study3"],"a":"庄园估价三十万，欠我四十万。他活着我还能追，死了庄园被分割，十万的洞就是我的。杀他是蠢事。"},{"id":"t_sleigh","q":"雪橇夫怎么说？","needs":["clue:c_gar2","ask:levi.t_where"],"a":"他说男爵订了车，不点灯，二十三点半停北角门。我守到四十五分，门里没人出来，就回来了。"}],"confronts":[{"clue":"c_gar2","breaks":"t_where","a":"利维笑得很客气：“雪茄烟蒂，我的牌子。好吧，我在北角门。我等的是一个骗子，不是一个死人。”"},{"clue":"c_study2","breaks":"t_know","a":"他读着雪橇单，笑意退去。“他真的订了。我撒谎，因为这太像预谋。我只想追回钱，不是要他的命。”"},{"clue":"c_din1","a":"他认出字条，微微一笑：“我的字，她的口脂。商人和贵妇的小秘密，请别当成杀人证据。”"}],"fallback":"这东西与我的账目无关，抱歉。"}],"solution":{"culprit":"lucien","method":{"q":"凶手怎样让霍恩“自己走进死亡”？","options":["管面具的人明知有毒，故意递给死者","三张面具内衬都涂毒，谁戴谁中毒","涂毒后从北墙暗道潜入，事后取走面具","毒涂一张面具，对调铭牌让死者戴上"],"correct":3},"motive":{"q":"凶手为什么杀人？","options":["死者握有挪用公款的旧信，长期勒索","死者当年吞并其家业，致其父自尽","死者让亲人怀孕又想抛弃她逃走","死者想卷款失踪，他要追回欠款"],"correct":1},"keyClues":["c_hall1","c_lib1","c_lib2","c_cel1","c_gar1","c_study1"],"truth":["凶手是画家吕西安·马洛，本名瓦朗。他没进过镜厅，毒是霍恩自己戴进去的。","一九〇八年，霍恩吞并瓦朗镜厂，厂主阿芒在炉前自尽。其子吕西安化名入馆，等了三年。","手法：重镀时他把乌头糊混进金胶，涂在No.2内衬，再对调No.1、No.2的铭牌。莉泽没验号，凭牌把毒面具发给了霍恩。","露馅：毒面具铭牌是I，铸号却是2；退回的“II号”反有男爵的修补痕。温室被挖的乌头、石臼和貂毛笔，也指向他。","其余人各有隐瞒：克勒藏面具是护女儿，莉泽怀着男爵的孩子，男爵本打算借仪式失踪。这些都与毒无关。"]}},{"id":"twins","title":"双生","tagline":"四十岁生日夜，海边别墅的码头浮起一具蓝裙女尸，零点一到，三亿信托归谁，全看她是谁。","difficulty":5,"cover":"coverTwins","tone":"purple","brief":"林家双胞胎姐妹四十岁生日，海滨别墅“听潮居”宾客云集。二十三点前后，有人在码头捞起一名蓝裙女子，已无呼吸。随后红裙女子冲来，哭喊：“死的是姐姐知夏，我是知秋！”可她丈夫和家庭医生都说，她是吓糊涂的知夏。\n律师梁叙请你来：零点起，祖父的信托归“长女知夏”。台风封山，警察一点半才到。你二十三点五十分抵达，只有这一夜，要弄清死者是谁、死在何时何处、谁让她死。","victim":{"name":"蓝裙女子（身份存疑）","desc":"四十岁左右的女子，身穿蓝色晚礼服，戴珍珠项链，在码头被发现浮于水中。她与红裙女子面容几乎一模一样。","look":{"skin":"fair","hair":"long","hairColor":"black","glasses":"none","beard":"none","outfit":"dress","acc":"necklace","mood":"sad"}},"publicFacts":["林知夏、林知秋是同卵双胞胎。家族惯例：生日当天互换装束，让宾客猜谁是谁。今年分穿红、蓝。","祖父遗嘱：零点起信托由长女知夏继承；若她此前去世，信托并入林氏基金会，执行人是继母柳月华。","22:58闺蜜苏念称在码头发现落水者。宋怀仁医生23:05赶到，判断溺水，死亡时间约22:50至23:10。","23:08红裙女子赶到，坚称自己是知秋；其丈夫谢承泽与宋医生都说她是惊吓过度的知夏。","二十年前同一晚，管家周妈的儿子周辉在这个码头溺亡，当时定为意外。","台风封山，警方凌晨一点半到。别墅里所有人都还在。"],"timeline":[{"t":"19:30","text":"晚宴开始，红、蓝两名姐妹同时亮相。"},{"t":"21:30","text":"宾客举杯祝酒，宋医生在场，约21:40离席。"},{"t":"22:58","text":"苏念在码头发现水中有人，高声呼救。"},{"t":"23:05","text":"宋医生赶到，判断死者已无生命体征。"},{"t":"23:08","text":"红裙女子赶到，称死者是知夏，自己是知秋。"},{"t":"23:50","text":"你到达别墅。"},{"t":"24:00","text":"信托生效，权利人是“长女知夏”。"}],"budget":{"search":12,"ask":24},"relations":{"qiu":"死者的双胞胎妹妹，今晚穿红裙","xie":"死者的丈夫，近来分房住","liang":"林家三十年的律师，管信托交割","song":"看着姐妹长大的家庭医生","zhou":"带大姐妹俩的管家","liu":"死者的继母，基金会执行人","su":"妹妹知秋的大学室友兼闺蜜","cheng":"晚宴上来历不明的陌生访客"},"links":[{"a":"su","b":"song","text":"苏念的母亲长年由宋医生照料"},{"a":"xie","b":"liu","text":"都向梁律师打听过信托条款"},{"a":"liang","b":"song","text":"同为林家三十年的老人"},{"a":"zhou","b":"qiu","text":"周妈从小带大的孩子"}],"deathReport":{"time":"约 21:00–23:10","cause":"疑似溺水，尚无正式尸检","scene":"22:58苏念在码头发现水中有人呼救，宋医生23:05赶到，判断已无生命体征。","loc":"garden","notes":["遗体浸泡海水，体温偏低，难以精确推断死亡时间","台风夜雨势不停，码头木板湿滑","警方凌晨一点半才到，现场暂无正式勘验"]},"locations":[{"id":"hall","name":"门厅与衣帽间","scene":"hall","desc":"别墅大门内的门厅，左边是衣帽间，右边墙上挂着钥匙板。宾客的外套还湿着。","clues":[{"id":"c_hall1","title":"酒窖钥匙登记","text":"借用登记簿“酒窖”栏末行：“20:45 宋”，归还栏空白。板上酒窖的挂钩是空的。"},{"id":"c_hall2","title":"宋医生的出诊包","text":"长椅上的出诊包里有几盒写着“林知秋”的助眠药。清点单：咪达唑仑上次6支，现存4支。"},{"id":"c_hall3","title":"访客登记簿","text":"程野19:50到，被访人写“林知夏”。苏念18:30到，被访人写“知秋”。"}]},{"id":"dining","name":"宴会厅","scene":"dining","desc":"长桌上残席未撤，吃了一半的蛋糕立在中央。角落架着一台直播摄像机，旁边是甜品台。","clues":[{"id":"c_dining1","title":"宴会厅录像回放","text":"红裙女子切蛋糕、写留言都用右手。21:25至22:05苏念在甜品台摆盘。21:40宋怀仁从侧门出厅。"},{"id":"c_dining2","title":"留言簿","text":"21:50的“知夏”签名向右倾。去年同一栏的“知夏”向左倾，笔画末端拖着灰影。"},{"id":"c_dining3","title":"备餐台账","text":"周妈的铅笔字：“22:00夜宵，苏小姐端出；22:15收厨房；22:25柳太太要热水袋，送上二楼。”"}]},{"id":"cellar","name":"酒窖","scene":"cellar","desc":"别墅地下的酒窖，石墙阴冷，酒架直抵拱顶。角落有扇通往花园的外侧小门，品酒桌的灯没关。","clues":[{"id":"c_cellar1","title":"品酒桌上的两只杯","text":"一只杯有红唇印，杯底残液发黏，甜中带苦。另一只倒扣，擦得很亮。"},{"id":"c_cellar2","title":"外侧小门","text":"插销拔开，门外台阶有两串被雨冲淡的鞋印。门内地面有两道平行擦痕，撒着灰白石灰粉。"},{"id":"c_cellar3","title":"酒架后的暗格","text":"暗格锁扣被撬，里面空了，底板有铁盒印痕。板缝卡着一截断口整齐的细玻璃管颈。"},{"id":"c_cellar4","title":"地上的白手帕","text":"绣着“月”字的白手帕盖在擦痕上，两面无灰，四周石灰粉被蹭乱。"}]},{"id":"garden","name":"花园与码头","scene":"garden","desc":"别墅后的海边花园，石板路通向木码头。路边有凉亭，远处悬崖上有观景台。","clues":[{"id":"c_garden1","title":"蓝裙遗体","text":"蓝裙遗体：鞋底沾石灰粉和酒渍，鞋跟有拖痕。左手小指侧有墨迹，右下腹有旧手术疤。"},{"id":"c_garden2","title":"遗体腕上的手表","text":"智能手表记录：心率21:16下降，21:17成直线。22:52显示“水锁模式已开启”。"},{"id":"c_garden3","title":"凉亭","text":"长椅和石桌积着一层薄灰，桌上没有杯子。烟灰缸干净，亭外石板缝里也没有烟头。"},{"id":"c_garden4","title":"观景台上的相机","text":"相机朝向码头。长曝光：22:52两个人影放下长条物，一人披浅色披肩，一人高个、深色外套。"}]},{"id":"guest","name":"客房","scene":"guestroom","desc":"二楼走廊尽头的客房，姐妹俩今晚在这里换装。梳妆台一片凌乱，床上扔着几条披肩。","clues":[{"id":"c_guest1","title":"镜框便签","text":"便签字迹向左倾，末尾拖灰：“19:25换好了。我八点五十去酒窖。晚了就替我撑到蛋糕，别问。”"},{"id":"c_guest2","title":"浅黄披肩","text":"浅黄披肩下摆湿透，沾着木屑、海藻和几处暗红渍。一角绣着“念”字。"},{"id":"c_guest3","title":"床头的老花镜","text":"金丝老花镜，镜腿刻“YH”。知夏的提包被翻乱，只剩一个印着“市急救中心”的空文件袋。"}]},{"id":"study","name":"父亲的书房","scene":"study","desc":"一楼尽头林国梁生前的书房，保险箱敞开，书桌抽屉被人拉开过。","clues":[{"id":"c_study1","title":"牛皮纸袋","text":"三份复印件：二十年前同夜的急救调度记录（23:05“有微弱呼吸”，23:12“医生在场，取消派车”）、宋怀仁签的死亡证明（23:40）、二百万收据。"},{"id":"c_study2","title":"股权转让书","text":"转让方签名“林知夏”，字迹向右倾。谢承泽的手机：22:03拨给放贷人，通话47分钟。"},{"id":"c_study3","title":"律师的备忘录","text":"梁叙的备忘本：“9月12日柳问信托条款，已告知；9月15日谢问条款，已告知。”"}]}],"suspects":[{"id":"qiu","name":"红裙女子","role":"双胞胎之一","age":40,"look":{"skin":"fair","hair":"long","hairColor":"black","glasses":"none","beard":"none","outfit":"dress","acc":"earrings","mood":"sad"},"bio":"同卵双胞胎之一，穿红裙，宾客一晚都叫她知夏。她赶到码头后，一口咬定自己是妹妹知秋。","demeanor":"声音发颤，说到一半常停住。","topics":[{"id":"t_who","q":"你到底是谁？","a":"我是知秋，红裙本来是姐姐的。我要真是知夏，零点一过信托全归我，何必硬说自己是知秋？"},{"id":"t_note","q":"晚上见过姐姐吗？","lie":true,"a":"十九点半换完装，我就没再见过她。我还当她去露台透气了，她这人一不自在就往外跑，不爱见人。","truth":"我撒谎了。她在镜框留了便签，说八点五十去酒窖，让我撑到蛋糕。我没敢说，怕被追问。"},{"id":"t_cellar","q":"你去过酒窖吗？","needs":["ask:qiu.t_note","clue:c_cellar2"],"a":"二十二点三十五分我下去过。正门锁着，灯从门缝漏出来。我敲了三下，没人应，就回宴会厅了。"},{"id":"t_scar","q":"姐姐有什么记号？","needs":["clue:c_garden1"],"a":"她二十五岁割过阑尾，右下腹有道疤，是宋叔叔开的刀。我没有。她还是左撇子，写字总蹭得一手灰。"},{"id":"t_sleep","q":"你在吃安眠药吗？","needs":["clue:c_hall2"],"a":"吃了好些年了，都是药片。宋医生从来没给我打过针，上次开药也是半个月前的事了。你们别误会。"},{"id":"t_doc","q":"宋医生为何说你是知夏？","needs":["ask:qiu.t_scar","ask:qiu.t_sleep"],"a":"那场手术是他做的，谁有疤他最清楚。可他一直说我认错了自己。我当时不敢往下想，现在更怕。"}],"confronts":[{"clue":"c_guest1","breaks":"t_note","a":"她读着那几行向左倾的字，嘴唇发抖：“是姐姐的字。她让我别问，我就真的什么都没问。”"},{"clue":"c_garden1","a":"她朝白布下看了一眼，脸色灰了：“这道疤，这块墨迹……是她。我没有认错，真的是她。”"},{"clue":"c_hall2","a":"“这些药是我的，都是药片，从没打过针。”她抬起头，“少了两支？那是拿来做什么的？”"},{"clue":"c_study1","a":"她翻到第二页就停住：“我爱过周辉，那晚没能救他。姐姐大概也是三天前才看到这些。”"}],"fallback":"我现在脑子一片空白，你问别的吧。"},{"id":"xie","name":"谢承泽","role":"知夏之夫","age":42,"look":{"skin":"light","hair":"sidepart","hairColor":"black","glasses":"rect","beard":"stubble","outfit":"suit","acc":"tie","mood":"stern"},"bio":"知夏的丈夫，经营一家酒店，长年住在林家，近来与妻子分房。祝酒后，他称自己回房休息。","demeanor":"强势，爱打断人，被戳中就拔高嗓门。","topics":[{"id":"t_wife","q":"她真是你太太？","lie":true,"a":"当然是我太太！十几年夫妻，我会认不出？她是吓糊涂了，死的是那个吃药吃得迷糊的知秋。","truth":"我认不出。我们分房两年，整晚我没细看过她。我咬定她是知夏，是不愿承认自己认不出。"},{"id":"t_where","q":"祝酒后你在哪？","lie":true,"a":"我喝多了，回房躺下，听见尖叫才下楼。屋里就我一个，没人作证，可我撒这个谎干什么？","truth":"我在书房接放贷人的电话，被催得走投无路。我没杀人，只是不敢让人知道我欠了一屁股债。"},{"id":"t_will","q":"你知道信托条款吗？","a":"知道，梁律师告诉过我，她是我妻子，我当然关心。你别盯着我，她活着，我的好处比她死了大得多。"},{"id":"t_forge","q":"那份转让书怎么回事？","needs":["clue:c_study2","ask:xie.t_where"],"a":"签名是我仿的，我写成了向右倾。后来才知道她是左撇子，字总往左歪。我这个丈夫，真是笑话。"},{"id":"t_doc","q":"宋医生怎么看她？","a":"宋医生是看着她们长大的长辈，他说她受了刺激，要吃镇静药，还让我劝她。我当然信他。"},{"id":"t_tall","q":"观景台照片里的高个子","needs":["clue:c_garden4","clue:c_study2"],"a":"你盯着我一米八五是吧？我22:03打出的电话，讲了47分钟，记录就在手机上，自己看。"}],"confronts":[{"clue":"c_dining1","breaks":"t_wife","a":"他盯着右手写字的红裙女子，脸抽了一下：“左撇子……我竟然不知道她写字用哪只手。”"},{"clue":"c_study2","breaks":"t_where","a":"他抓着桌沿：“好，我在书房。放贷人给我的最后期限是今晚零点。我没杀她，我巴不得她好好活着。”"},{"clue":"c_garden4","a":"他凑近看了很久：“披肩的是个女人。高个子天黑我看不清。反正不是我，我在打电话。”"}],"fallback":"这跟案子有什么关系？别浪费我时间。"},{"id":"liang","name":"梁叙","role":"家族律师","age":55,"look":{"skin":"light","hair":"slick","hairColor":"grey","glasses":"rect","beard":"none","outfit":"suit","acc":"pocketwatch","mood":"tired"},"bio":"林家三十年的家族律师，负责今晚的信托交割。祝酒后去了偏厅，案发后第一个提出要请侦探。","demeanor":"措辞谨慎，爱说“按规定”，被追问会推眼镜。","topics":[{"id":"t_will","q":"谁知道信托条款？","lie":true,"a":"没有人。这是职业操守，条款我一个字都没对外说过，连她丈夫都不清楚，只有我和知夏本人知道。","truth":"我说过。柳太太和谢先生先后来问，被缠得我松了口。我怕丢了林家这份饭碗，一直不敢认。"},{"id":"t_trust","q":"信托怎么分？","a":"知夏零点前去世，信托并入林氏基金会，柳太太当执行人。死的若是知秋，知夏就全权继承。"},{"id":"t_where","q":"祝酒后你在哪？","a":"我在偏厅沙发上，喝多了睡着了，听见尖叫才醒。没人能证明，你不必提醒我，我这岁数不该喝那么多。"},{"id":"t_xia","q":"知夏最近有何异常？","needs":["clue:c_study3"],"a":"三天前她进父亲的保险箱取了个纸袋，说要在生日夜前“了结一件旧账”，叫我别问。她出来时脸色很怪。"},{"id":"t_old","q":"二十年前周辉的事","needs":["ask:liang.t_xia","clue:c_study1"],"a":"那晚我不在。事后林国梁让我拟协议，给周妈二十万，换她不再追究。看了这纸袋，我睡不着了。"},{"id":"t_song","q":"宋医生和林家的关系","needs":["clue:c_study1"],"a":"他是林家三十年的家庭医生。二十年前，林国梁出了二百万让他开诊所，后来诊所成了他的招牌。"}],"confronts":[{"clue":"c_study3","breaks":"t_will","a":"他苦笑着摘下眼镜：“你们翻了我的本子。是，我说过，两次，对象就是你说的这两位。老了，怕得罪人。”"},{"clue":"c_study1","a":"他看着调度记录，慢慢念：“取消派车……我当年只拿到一张死亡证明，中间还有这一段。”"},{"clue":"c_guest3","a":"“这是柳太太的老花镜。”他认得很快，“她为什么在知夏的提包旁？这我不便替她解释。”"}],"fallback":"这涉及保密义务，我只能说到这里。"},{"id":"song","name":"宋怀仁","role":"私人医生","age":58,"look":{"skin":"light","hair":"sidepart","hairColor":"grey","glasses":"round","beard":"none","outfit":"coat","acc":"stethoscope","mood":"smile"},"bio":"林家三十年的私人医生，23:05第一个赶到码头。他称自己祝酒后在花园凉亭陪苏念聊天。","demeanor":"慈祥稳重，爱叫人“孩子”，被逼急语速变快。","topics":[{"id":"t_where","q":"祝酒后你在哪？","lie":true,"a":"21:40离席后，我在凉亭抽烟，苏念陪我聊她母亲的病，坐到22:40。她可以作证。","truth":"我没在凉亭。20:45我拿钥匙下酒窖见知夏，祝酒露个面又回去，待到22:40。是我让苏念这么说的。"},{"id":"t_death","q":"死亡时间怎么判断？","lie":true,"a":"我到码头时身体还是温的，瞳孔肢体都对得上。溺水，22:50到23:10，我有把握。","truth":"那是编的。她21:17就死在酒窖，我下药又捂死她。后来我和苏念趁风雨抬她到码头入水。"},{"id":"t_tell","q":"谁是知夏，谁是知秋？","lie":true,"a":"双胞胎我也分不清，只能认衣服。蓝裙是知秋，红裙是知夏，她是惊吓过度，认错了自己。","truth":"我分得清。知夏的阑尾是我开的刀。我故意说死者是知秋，因为她吃我开的镇静药，尸检才讲得通。"},{"id":"t_old","q":"二十年前周辉的事","lie":true,"a":"那晚人捞上来就没有呼吸了，我尽了全力，二十三点四十才宣布。你们现在翻这件旧事，伤的是活着的人。","truth":"他当时还有微弱呼吸。林国梁不许送医，我取消了派车，眼睁睁看着他停了，收下了二百万。"},{"id":"t_bag","q":"出诊包里少了药？","needs":["clue:c_hall2"],"lie":true,"a":"少两支？上周给知秋临时压惊用了，还没来得及补登记，是我疏忽，可这跟案子有什么关系。","truth":"没有给知秋用。一支兑进了知夏的酒，另一支留作备用。用完的空安瓿，被我扔进了海里。"},{"id":"t_hanky","q":"酒窖里的手帕？","needs":["clue:c_cellar4"],"lie":true,"a":"柳太太的吧，她手里总攥着手帕。落在酒窖，说明她下去过。我只是实话实说，没有指谁。","truth":"手帕是我从衣帽间长椅上拿的。事后我从外小门进去，把它压在擦痕上，想让人以为是柳月华下过酒窖。"},{"id":"t_sleep","q":"知秋有没有梦游？","a":"几年前她半夜走到过海边，我给她开了药。所以我头一个念头就是她。承泽那边债主逼得紧，也该问问。"}],"confronts":[{"clue":"c_hall1","breaks":"t_where","crack":true,"a":"他笑意僵了：“我拿钥匙是给寿星挑酒。”停了停，嗓子发干，“……可我没还，是吗。”"},{"clue":"c_dining1","breaks":"t_where","a":"他看着苏念摆盘的身影，干笑一声：“她大概记错了时间。”手背上的青筋一根根鼓起来。"},{"clue":"c_garden2","breaks":"t_death","crack":true,"a":"他沉默良久：“我没想过她戴着这个。”抬头时只剩疲惫，“水锁，22:52。你们都看到了。”"},{"clue":"c_cellar2","breaks":"t_death","a":"他嘴角一抽：“擦痕是搬酒留下的。”顿了顿，“可鞋跟的擦痕，也是搬酒搬的吗？”他自己先沉默了。"},{"clue":"c_cellar1","breaks":"t_bag","a":"他看着杯底的残液，没再辩解：“那杯子，是我擦的，我擦了自己那一只。她那杯，我没敢碰。”"},{"clue":"c_garden1","breaks":"t_tell","a":"他喉结滚了两下：“右下腹，四厘米，我自己缝的。”他抬眼看你，“你们是不会放过这个细节的。”"},{"clue":"c_study1","breaks":"t_old","a":"他手指发抖：“她从保险箱里拿的？”他嘴唇哆嗦，“二十年了，我以为它早就跟林国梁一起烧成灰了。”"},{"clue":"c_hall2","breaks":"t_bag","a":"他语速变快：“那两支给知秋用了，漏登一笔不算罪。”顿了顿，“她说没有？孩子睡糊涂了。”"},{"clue":"c_cellar4","breaks":"t_hanky","a":"他笑意慢慢收了：“压在擦痕上头……搬东西时在的话，早沾上石灰了。你们看得真细。”"},{"clue":"c_cellar3","a":"“老国梁的铁盒？”他摇头，“我只见他开过一回，像是旧药旧信。想翻旧账的，可不止一个。”"},{"clue":"c_garden4","a":"“天黑雨大，长曝光谁看得清？”他目光停了一下，“披肩的是女人，高个子……不会觉得是我吧？”"}],"fallback":"孩子，这个我一时想不起来，问点别的。"},{"id":"zhou","name":"周妈","role":"管家","age":62,"look":{"skin":"tan","hair":"bun","hairColor":"grey","glasses":"none","beard":"none","outfit":"apron","mood":"stern"},"bio":"林家管家，一手带大姐妹俩。二十年前她的儿子周辉在码头溺亡。她称当晚一直在厨房忙。","demeanor":"寡言，带方言腔，爱说“晓得”，提到儿子会停顿。","topics":[{"id":"t_peace","q":"周辉的事你放下了吗？","lie":true,"a":"二十年了，早放下了。林家供我吃住，我不恨任何人，人各有命，我只想安安稳稳过完这几年。","truth":"没放下。三天前我把保险箱号码告诉了知夏小姐。我恨，可我没害她，我疼她们像亲生的。"},{"id":"t_hand","q":"你分得出两姐妹吗？","a":"我带大的，闭眼都分得出。知夏左手，知秋右手。红裙那位一晚用右手，我就晓得是知秋。"},{"id":"t_night","q":"今晚你在做什么？","lie":true,"a":"一直在厨房备夜宵、洗碗，脚没沾过地。雨又大，窗外啥也看不清，我不作兴瞎打听，更不晓得外头有啥动静。","truth":"我出过后门。22点40几分拎垃圾，看见路上有人抬东西往码头走。我退回檐下，一声没敢吭。"},{"id":"t_safe","q":"保险箱的号码","needs":["ask:zhou.t_peace"],"a":"是老爷的生日，二十年没动过。三天前知夏小姐问起周辉，哭了，我才告诉她：该看的，都在里面。"},{"id":"t_doc","q":"你怎么看宋医生？","needs":["clue:c_study1","ask:zhou.t_safe"],"a":"原来120是被人取消的……他在我家吃了二十年年夜饭，我还给他煮过长寿面。我讲了，谁信？"},{"id":"t_window","q":"后门外看见什么？","needs":["ask:zhou.t_night","clue:c_cellar2","clue:c_garden4"],"a":"两个人影，抬着个长条东西往码头走。风大，我退回檐下没敢出声。你莫问我为啥先头不讲。"},{"id":"t_seen","q":"那两个人你看清了吗？","needs":["ask:zhou.t_window","clue:c_garden4"],"a":"一个裹浅黄披肩，是女人，肩在抖。一个高个子，从我跟前过，一股碘伏味。我怕被当成替儿子寻仇。"}],"confronts":[{"clue":"c_study1","breaks":"t_peace","a":"她攥紧了手：“这是我打的电话……我骗你们了，我一天也没放下。保险箱号码，是我告诉她的。”"},{"clue":"c_cellar3","a":"她看着空暗格：“老爷在这放过一只铁盒，装的是不能见光的东西。是知夏小姐拿的吧。”"},{"clue":"c_garden4","breaks":"t_night","a":"她嘴唇抖了好久：“披肩……我晓得这两个人。我骗你们了，我出过后门。我怕啊，说出来谁信？”"},{"clue":"c_garden2","a":"她看着那条归零的曲线，眼泪落下来：“二十年前那晚，我儿子也是这样……我真的没法说。”"}],"fallback":"这个我不晓得，你去问别人吧。"},{"id":"liu","name":"柳月华","role":"继母","age":58,"look":{"skin":"light","hair":"bob","hairColor":"grey","glasses":"none","beard":"none","outfit":"qipao","acc":"necklace","mood":"worried"},"bio":"林国梁的续弦，林氏基金会执行人。她称二十一点后头疼，一直在二楼自己的房间里休息。","demeanor":"客气克制，说话绕圈，被戳到会攥手帕。","topics":[{"id":"t_trust","q":"你了解信托吗？","lie":true,"a":"我一个妇道人家，对信托一窍不通。国梁在世时男人管事。什么零点、基金会，我都是今晚才听梁律师说的。","truth":"我知道。九月十二日梁律师亲口告诉了我。我怕知夏一接手就解散基金会，把我赶出林家。"},{"id":"t_where","q":"二十一点后你在哪？","lie":true,"a":"我头疼，二十一点以后一直在二楼房里躺着，直到听见尖叫。房里没别人，也没人能作证。我真的哪儿也没去。","truth":"我没躺着。21:30后溜进客房翻知夏的提包找新遗嘱，没找到，老花镜落在了床头。我只是怕。"},{"id":"t_hand","q":"你认得出谁是谁吗？","a":"我认不出，红蓝一换连我也糊涂了。宋医生说是知夏受惊，我就信了，毕竟他是医生，他不会骗人。"},{"id":"t_song","q":"你看到过宋医生吗？","needs":["ask:liu.t_where"],"a":"我房门没关严，听见21:40多有人皮鞋声很重，往地下室去。宋医生、承泽都有可能。"},{"id":"t_envelope","q":"知夏包里有什么？","needs":["clue:c_guest3","ask:liu.t_where"],"a":"就一个空文件袋，上头印着急救中心。我心里一沉：她要找的原来不是什么遗嘱。可我那会儿只顾着怕。"},{"id":"t_hanky","q":"酒窖里那方手帕？","needs":["clue:c_cellar4"],"a":"是我的。晚宴前在衣帽间长椅上擦手，随手放下就忘了。长椅边是宋医生的包。我没去过酒窖。"},{"id":"t_fund","q":"基金会是怎么回事？","needs":["clue:c_study3"],"a":"基金会管着家族信托的收益。知夏一继承就会解散它，我这个执行人也就没用了。我承认我怕。"}],"confronts":[{"clue":"c_study3","breaks":"t_trust","a":"她叹了口气：“梁叙啊。”手帕攥在掌心，“是，我问过。我不是图钱，我是怕被扫地出门。”"},{"clue":"c_guest3","breaks":"t_where","a":"她脸色发白：“难怪到处找不到。是我。我翻了知夏的提包，什么也没找到，只想知道她会不会赶我走。”"},{"clue":"c_hall1","a":"她慢慢说：“宋医生老爱往酒窖跑。我隔着门听见有人快步往那边去，可我不敢说一定是他。”"},{"clue":"c_cellar4","a":"她指尖一缩：“我的手帕，怎么会在酒窖？我没下去过。我要真下去过，也不会把它丢在那儿。”"}],"fallback":"这个我真不清楚，你别为难我。"},{"id":"su","name":"苏念","role":"知秋闺蜜","age":39,"look":{"skin":"light","hair":"ponytail","hairColor":"brown","glasses":"none","beard":"none","outfit":"dress","acc":"scarf","mood":"worried"},"bio":"知秋的大学室友，在画廊工作，二十多年的闺蜜。她第一个呼救，称自己当时在花园透气。","demeanor":"说话轻，爱说“其实”，一紧张就绞披肩。","topics":[{"id":"t_where","q":"祝酒后你在哪？","lie":true,"a":"21:40到22:40，我一直在花园凉亭陪宋医生，聊我妈的病。他帮了我家这么多。我可以发誓。","truth":"我没去凉亭。21:25我在甜品台，22:00后他叫我去酒窖。我欠他很多钱，替他说了谎。"},{"id":"t_pier","q":"你怎么发现尸体的？","lie":true,"a":"22:58我去花园透气，远远看见码头水里漂着个人。我吓坏了，喊着就跑回屋，没敢上码头。","truth":"我上过码头。我和宋医生把人从酒窖抬出来放进水里。他说口径一致，就替我还清我妈的医药费。"},{"id":"t_mother","q":"你母亲的病？","a":"我妈是尿毒症，每周透析两次。宋医生一直帮我垫钱，到现在我欠了他三十多万，我只能听他的。"},{"id":"t_dessert","q":"你在甜品台看到什么？","needs":["clue:c_dining1"],"a":"我一直在摆盘补酒，没离开过。21:40宋医生离席时，在我耳边说了一句“等下我找你”。"},{"id":"t_song","q":"你怎么看宋医生？","a":"他对我妈有恩，是长辈。其实今晚他有点怪，老盯着红裙那位，还问我她吃了药没有。我也不知是不是多心。"},{"id":"t_cry","q":"你还有什么没说？","needs":["ask:su.t_pier","clue:c_guest2"],"a":"他说那是意外，我不用怕，听他的就行。我每晚都做噩梦，知夏那个眼神我这辈子忘不了。"}],"confronts":[{"clue":"c_dining1","breaks":"t_where","a":"她脸一下没了血色：“那段时间我确实在甜品台。宋医生说，如果有人问，我就这么讲。”"},{"clue":"c_garden3","breaks":"t_where","a":"她看着凉亭的灰，声音越来越小：“我们说在这里。可是，没有。他叫我说什么，我就说了。”"},{"clue":"c_guest2","breaks":"t_pier","a":"她浑身一颤：“我淋了雨……”看见那些暗红污渍，嘴唇发抖，“……不。是我上过码头。”"},{"clue":"c_garden4","breaks":"t_pier","a":"她绞着衣角，看了很久很久：“披肩是我的。既然别人都看见了，我就再也说不下去了。”"}],"fallback":"我不太清楚，对不起。"},{"id":"cheng","name":"程野","role":"神秘访客","age":35,"look":{"skin":"tan","hair":"messy","hairColor":"black","glasses":"none","beard":"stubble","outfit":"jacket","mood":"sly"},"bio":"19:50到的陌生男子，自称朋友带来的客人。晚宴后少露面，案发时没人说得清他在哪。","demeanor":"懒散带笑，爱反问，被逼问会摸鼻子。","topics":[{"id":"t_who","q":"你为什么来这里？","lie":true,"a":"朋友带我来蹭饭的，和林家都不熟，知夏小姐更是素不相识。事情闹成这样，我想早点走。","truth":"三周前知夏雇我重查周辉旧案，今晚让我来当见证人。我怕被当成别有用心的人，就撒了谎。"},{"id":"t_where","q":"二十二点后你在哪？","lie":true,"a":"我一直在宴会厅，吃蛋糕、喝酒、闲聊。到处是人，我又这么不起眼，没人注意我也正常，嘿。","truth":"我在悬崖观景台。知夏让我22:00起守着，说她若迟迟不回，就把镜头对准码头。我拍到了，没敢说。"},{"id":"t_photo","q":"观景台那台相机？","needs":["clue:c_garden4","ask:cheng.t_where"],"a":"是我的。长曝光，雨又太大，只拍到人影、披肩和长条状的东西。台阶又滑，我没敢走近。"},{"id":"t_xia","q":"知夏雇你时说了什么？","needs":["ask:cheng.t_who"],"a":"她说二十年前那晚有人撒了谎，要一份“原件”，说零点前能拿到，叫我在场当个见证人。"},{"id":"t_doc","q":"她提到过要见谁吗？","needs":["ask:cheng.t_xia","clue:c_study1"],"a":"她说是“当年经手那件事的人”，只笑着说“你今晚就能看到”。她要原件，复印件不顶用。"},{"id":"t_hand","q":"你认得出谁是谁吗？","a":"我只见过知夏一面。红裙那位走路右肩略沉，知夏是左肩沉。毕竟灯光一晃，两张脸一模一样，我不敢肯定。"}],"confronts":[{"clue":"c_hall3","breaks":"t_who","a":"他摸摸鼻子，尴尬地笑：“被你们翻出来了。是她约的我。我不想卷进去，才撒了谎，对不住了。”"},{"clue":"c_garden4","breaks":"t_where","a":"他肩膀垮下来：“那是我的相机。我当时就在观景台，可我什么也没做，什么都没做。要是冲下去……”"},{"clue":"c_study1","a":"他看了一遍，吹了声口哨又收住：“这就是她说的东西。果然有人撒了谎，是人命的谎。”"}],"fallback":"这个我不好说，你找别人问问。"}],"solution":{"culprit":"song","method":{"q":"凶手是怎么做到的？","options":["在客房被撞破翻找遗嘱，推人下楼致死，再趁暴雨抛尸入海","利用死者长期服用的镇静药，让她在码头失足落水，定为意外","在书房掐死死者，让同伙推车把尸体送到海边抛入水中","在酒窖用药迷晕并捂死死者，趁暴雨抬到码头，伪装溺水"],"correct":3},"motive":{"q":"为什么杀人？","options":["死者接手后会解散基金会，凶手将失去稳定的收入和落脚处","死者握着二十年前见死不救的凭证，要在午夜前交给警方","死者发现凶手私吞了应付给受害家属的赔偿款，要追讨","死者撞破凶手一桩隐秘私情，以公开相威胁，逼他离开"],"correct":1},"keyClues":["c_hall1","c_cellar1","c_garden1","c_garden2","c_dining1","c_study1"],"truth":["凶手是私人医生宋怀仁，苏念是共犯。死者是姐姐林知夏，红裙女子确是知秋，说的是实话。","身份：姐妹换装，知夏穿蓝裙，20:50去酒窖逼宋交出旧案原件。宾客把红裙当知夏，可红裙右手写字，录像和留言簿都能证明。","时间：宋在酒里下药并捂死知夏，21:17心率归零。他让苏念谎称在凉亭，钥匙却没还。22:40两人抬尸到码头，22:52入水，死亡时间被推后。","嫁祸：他咬定死者是服镇静药的知秋，好解释药物成分，却忘了自己割过知夏的阑尾。柳月华的手帕是事后摆放，文件袋印急救中心，少的两支药在他包里。其余人的谎与命案无关。","动机：二十年前周辉还有呼吸，宋却取消急救、收下二百万。知夏拿到证据，要在零点报警，他便先灭口。"]}}];